insert into public.languages (id, code, name, native_name, writing_direction, tts_locale, is_available) values ('en', 'en', 'Anglais', 'English', 'ltr', 'en-GB', true) on conflict (id) do update set name = excluded.name, native_name = excluded.native_name, writing_direction = excluded.writing_direction, tts_locale = excluded.tts_locale, is_available = excluded.is_available;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g01.subject_pronouns', 'en', 'grammar', 'grammar', 'Les pronoms personnels sujets', 1, '{}'::text[], 1, '{"rule": {"summary": "Les pronoms sujets (I, you, he, she, it, we, they) remplacent la personne ou la chose dont on parle, au début de la phrase.", "explanation": "L''anglais a sept pronoms sujets : I (je), you (tu ou vous), he (il, pour un homme ou un garçon), she (elle, pour une femme ou une fille), it (il ou elle pour une chose ou un animal), we (nous), they (ils ou elles). I s''écrit toujours avec une majuscule, même au milieu d''une phrase. You sert à la fois pour « tu » et pour « vous », pour une ou plusieurs personnes. En anglais, les choses n''ont pas de genre : le livre ou la table, c''est toujours it. They remplace « ils » comme « elles ».", "pattern": "Pronom sujet + verbe : I am…, she is…, they are…", "examples": [{"text": "Hello! I am Emma.", "translation": "Bonjour ! Je suis Emma."}, {"text": "Thank you! — You are welcome.", "translation": "Merci ! — De rien."}, {"text": "The hotel? It is in Paris.", "translation": "L''hôtel ? Il est à Paris."}, {"text": "Lucy and Anna? They are in London.", "translation": "Lucy et Anna ? Elles sont à Londres."}], "commonErrors": [{"wrong": "Hello! i am Tom.", "right": "Hello! I am Tom.", "why": "I (je) s''écrit toujours avec une majuscule."}, {"wrong": "The hotel? He is in Paris.", "right": "The hotel? It is in Paris.", "why": "Une chose n''a pas de genre en anglais : on utilise it, même si le mot est masculin ou féminin en français."}, {"wrong": "Anna and Lucy? She is in London.", "right": "Anna and Lucy? They are in London.", "why": "Pour plusieurs personnes, même toutes féminines, on utilise they."}], "tip": "Un homme → he, une femme → she, une chose ou un animal → it, plusieurs → they."}, "functionWords": ["I", "you", "he", "she", "it", "we", "they"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g02.articles', 'en', 'grammar', 'grammar', 'Les articles : a, an, the', 1, '{}'::text[], 1, '{"rule": {"summary": "A et an veulent dire « un / une » ; the veut dire « le, la, l'', les ».", "explanation": "A ou an se met devant un nom singulier quand on parle d''une personne ou d''une chose parmi d''autres : a man (un homme). On choisit selon le son qui suit, pas selon la lettre : an devant un son de voyelle (an idea, an hour, car le h de hour ne se prononce pas), a devant un son de consonne (a man, a university, car on prononce « you-niversity »). The sert pour une personne ou une chose précise, au singulier comme au pluriel, et ne change jamais : the man, the woman, the children. Pour parler de quelque chose en général, on ne met pas d''article : Life is beautiful (la vie est belle). Devant un métier, l''anglais garde a ou an : She is a teacher (elle est professeure).", "pattern": "a + son de consonne · an + son de voyelle · the + nom précis", "examples": [{"text": "a man and a woman", "translation": "un homme et une femme"}, {"text": "an idea, an hour", "translation": "une idée, une heure"}, {"text": "the woman and the child", "translation": "la femme et l''enfant"}, {"text": "a university", "translation": "une université"}], "commonErrors": [{"wrong": "an university", "right": "a university", "why": "University commence par le son « you » : c''est un son de consonne, donc a."}, {"wrong": "a hour", "right": "an hour", "why": "Le h de hour ne se prononce pas : le mot commence par un son de voyelle, donc an."}, {"wrong": "The life is beautiful.", "right": "Life is beautiful.", "why": "Pour parler d''une chose en général, l''anglais ne met pas the."}], "tip": "Écoute le premier son du mot, pas sa première lettre : an hour, mais a university."}, "functionWords": ["a", "an", "the"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g03.be_affirmative', 'en', 'grammar', 'verbs', 'Le verbe to be : forme affirmative', 1, array['en.g01.subject_pronouns']::text[], 1, '{"rule": {"summary": "Le verbe to be (être) au présent : I am, you are, he / she / it is, we are, they are.", "explanation": "To be veut dire « être ». Au présent, il a trois formes : am avec I ; is avec he, she, it ou un nom singulier (Anna is…) ; are avec you, we, they ou un sujet pluriel (Tom and Anna are…). À l''oral et dans les messages, on contracte souvent : I''m, you''re, he''s, she''s, it''s, we''re, they''re. Devant un métier, on garde a ou an : He is a teacher. Attention : l''anglais utilise be là où le français dit parfois « avoir » : I am 20 (j''ai 20 ans), I am hungry (j''ai faim).", "pattern": "I am · he / she / it is · you / we / they are + adjectif ou nom", "examples": [{"text": "I am tired.", "translation": "Je suis fatigué."}, {"text": "She is a teacher.", "translation": "Elle est professeure."}, {"text": "We are ready.", "translation": "Nous sommes prêts."}, {"text": "Tom and Anna are happy.", "translation": "Tom et Anna sont heureux."}], "commonErrors": [{"wrong": "She are happy.", "right": "She is happy.", "why": "Avec he, she ou it, la forme de be est is."}, {"wrong": "He is teacher.", "right": "He is a teacher.", "why": "Devant un métier au singulier, l''anglais garde l''article a ou an."}, {"wrong": "I am agree.", "right": "I agree.", "why": "Agree est déjà un verbe (« être d''accord ») : on n''ajoute pas am. Am se met devant un adjectif ou un nom : I am happy."}], "tip": "I → am ; he, she, it → is ; tout le reste → are."}, "functionWords": ["be", "am", "is", "are"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g04.be_negative_questions', 'en', 'grammar', 'verbs', 'To be : négation et questions', 1, array['en.g03.be_affirmative']::text[], 1, '{"rule": {"summary": "Négation : on ajoute not après am, is, are. Question : on place am, is ou are avant le sujet.", "explanation": "Pour dire non, on met not juste après le verbe : I am not tired. On contracte souvent : I''m not, isn''t (is not), aren''t (are not) ; am not ne se contracte jamais en « amn''t ». Pour poser une question, on inverse le sujet et le verbe : You are ready → Are you ready? Il n''y a pas d''équivalent de « est-ce que » : l''inversion suffit. On répond souvent en version courte : Yes, I am. / No, I''m not. Dans une réponse courte positive, on ne contracte pas : Yes, I am (et non Yes, I''m).", "pattern": "Sujet + am / is / are + not · Am / Is / Are + sujet + … ?", "examples": [{"text": "I am not late.", "translation": "Je ne suis pas en retard."}, {"text": "She isn''t busy.", "translation": "Elle n''est pas occupée."}, {"text": "Are you hungry? — Yes, I am.", "translation": "Tu as faim ? — Oui."}, {"text": "Is Tom right? — No, he isn''t.", "translation": "Est-ce que Tom a raison ? — Non."}], "commonErrors": [{"wrong": "I not am busy.", "right": "I am not busy.", "why": "Not se place après am, is ou are."}, {"wrong": "You are ready?", "right": "Are you ready?", "why": "Dans une question, are passe avant le sujet."}, {"wrong": "I amn''t late.", "right": "I''m not late.", "why": "Am not ne se contracte pas en amn''t : on dit I''m not."}], "tip": "Négation : not juste après le verbe. Question : le verbe passe devant le sujet."}, "functionWords": ["not", "isn''t", "aren''t"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g05.have_has', 'en', 'grammar', 'verbs', 'Le verbe to have : have / has', 1, array['en.g01.subject_pronouns']::text[], 1, '{"rule": {"summary": "To have (avoir) : have avec I, you, we, they ; has avec he, she, it.", "explanation": "Have sert à dire ce qu''on possède : I have a car (j''ai une voiture). Avec he, she, it ou un nom singulier (Anna, the dog…), on utilise has : She has a dog. En anglais britannique, on dit aussi souvent have got / has got, avec le même sens : I''ve got a phone. Attention : pour l''âge, la faim, le froid ou « avoir raison », l''anglais utilise be et non have : I am 20 (j''ai 20 ans), I am hungry (j''ai faim), You are right (tu as raison).", "pattern": "I / you / we / they + have · he / she / it + has", "examples": [{"text": "I have a phone.", "translation": "J''ai un téléphone."}, {"text": "Anna has a dog.", "translation": "Anna a un chien."}, {"text": "We have a house in London.", "translation": "Nous avons une maison à Londres."}, {"text": "She is 20.", "translation": "Elle a 20 ans."}], "commonErrors": [{"wrong": "She have a car.", "right": "She has a car.", "why": "Avec he, she ou it, have devient has."}, {"wrong": "I have 20 years.", "right": "I am 20.", "why": "En anglais, l''âge se dit avec be : I am 20 (ou I am 20 years old)."}, {"wrong": "I have hungry.", "right": "I am hungry.", "why": "Hungry est un adjectif (« affamé ») : on l''utilise avec be, pas avec have."}], "tip": "He, she, it → has. Pour l''âge, la faim ou le froid → be, jamais have."}, "functionWords": ["have", "has"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g06.possessive_adjectives', 'en', 'grammar', 'grammar', 'Les adjectifs possessifs', 1, array['en.g01.subject_pronouns']::text[], 1, '{"rule": {"summary": "Les adjectifs possessifs (my, your, his, her, its, our, their) se placent devant le nom pour dire à qui il appartient.", "explanation": "My = mon, ma, mes ; your = ton, ta, tes, votre, vos ; his = son, sa, ses (à lui) ; her = son, sa, ses (à elle) ; its = son, sa, ses (à une chose ou un animal) ; our = notre, nos ; their = leur, leurs. Le possessif ne change jamais : même mot devant un nom masculin, féminin, singulier ou pluriel (my son, my daughter, my parents). Le piège : his ou her dépend du possesseur, pas du nom qui suit. La femme de Tom → his wife ; le mari d''Anna → her husband. Its s''écrit sans apostrophe : it''s veut dire it is.", "pattern": "my / your / his / her / its / our / their + nom", "examples": [{"text": "My son is a student.", "translation": "Mon fils est étudiant."}, {"text": "Tom and his wife are in Paris.", "translation": "Tom et sa femme sont à Paris."}, {"text": "Anna and her husband have a dog.", "translation": "Anna et son mari ont un chien."}, {"text": "Our parents are at home.", "translation": "Nos parents sont à la maison."}], "commonErrors": [{"wrong": "Anna and his husband", "right": "Anna and her husband", "why": "Le mari est celui d''Anna, une femme : on dit her, même si husband est masculin."}, {"wrong": "The hotel is in London. It''s name is The Rose.", "right": "The hotel is in London. Its name is The Rose.", "why": "Its (son, sa) s''écrit sans apostrophe ; it''s veut dire it is."}, {"wrong": "mys parents", "right": "my parents", "why": "Le possessif ne prend jamais de -s, même devant un nom pluriel."}], "tip": "Pour choisir entre his et her, demande-toi « à qui ? » : à un homme → his, à une femme → her."}, "functionWords": ["my", "your", "his", "her", "its", "our", "their"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g07.plural_nouns', 'en', 'grammar', 'grammar', 'Le pluriel des noms', 1, array['en.g02.articles']::text[], 1, '{"rule": {"summary": "Pour mettre un nom au pluriel, on ajoute en général -s ; quelques noms très courants sont irréguliers.", "explanation": "La plupart des noms prennent -s : a book → books, a key → keys. Après s, ss, sh, ch ou x, on ajoute -es : a bus → buses, a box → boxes. Après une consonne + y, le y devient -ies : a family → families (mais key → keys, car il y a une voyelle avant le y). Quelques noms très fréquents sont irréguliers : man → men, woman → women, child → children, person → people. People est déjà un pluriel : People are… Enfin, l''adjectif ne prend jamais de -s : happy children.", "pattern": "nom + -s / -es / -ies · irréguliers : men, women, children, people", "examples": [{"text": "two books and three bags", "translation": "deux livres et trois sacs"}, {"text": "The children are at school.", "translation": "Les enfants sont à l''école."}, {"text": "The women are ready.", "translation": "Les femmes sont prêtes."}, {"text": "In London, people are busy.", "translation": "À Londres, les gens sont occupés."}], "commonErrors": [{"wrong": "two childrens", "right": "two children", "why": "Children est déjà le pluriel de child : on n''ajoute pas de -s."}, {"wrong": "The people is happy.", "right": "The people are happy.", "why": "People est un pluriel (les gens) : le verbe est are."}, {"wrong": "a books", "right": "books", "why": "A et an ne s''utilisent qu''avec un nom singulier."}], "tip": "Retiens les quatre pluriels irréguliers du quotidien : men, women, children, people."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g08.verbs_base_form', 'en', 'grammar', 'verbs', 'Les verbes essentiels avec I, you, we, they', 1, array['en.g01.subject_pronouns']::text[], 2, '{"rule": {"summary": "Avec I, you, we et they, le verbe garde sa forme de base : I go, we take, they give.", "explanation": "Au présent simple, on parle de ce qu''on fait habituellement ou de ce qu''on fait en général. Avec I, you, we et they, on utilise le verbe tel qu''il est dans le dictionnaire (sa forme de base), sans rien lui ajouter : I go, you go, we go, they go. Le verbe ne change pas selon la personne. Il n''y a pas non plus de verbe être devant : on ne dit pas « I am go », mais simplement I go. Avec he, she et it, il y aura un petit changement, mais ce sera pour plus tard.", "pattern": "I / you / we / they + verbe de base", "examples": [{"text": "I go home.", "translation": "Je rentre à la maison."}, {"text": "We take the car.", "translation": "Nous prenons la voiture."}, {"text": "They give a book to Tom.", "translation": "Ils donnent un livre à Tom."}, {"text": "You make a bag for your sister.", "translation": "Tu fabriques un sac pour ta sœur."}], "commonErrors": [{"wrong": "I am go home.", "right": "I go home.", "why": "Am est le verbe être : on ne le met pas devant un autre verbe. On dit simplement I go."}, {"wrong": "I go to home.", "right": "I go home.", "why": "Devant home, on n''ajoute pas to : go home (rentrer à la maison)."}, {"wrong": "They gives a book to Tom.", "right": "They give a book to Tom.", "why": "Avec they (comme avec I, you et we), le verbe ne prend pas de -s."}], "tip": "Avec I, you, we, they : le verbe ne change jamais. Sujet + verbe tel quel."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g09.do_vs_make', 'en', 'grammar', 'verbs', 'Do ou make ?', 2, array['en.g08.verbs_base_form']::text[], 2, '{"rule": {"summary": "Do s''emploie pour une tâche ou une activité ; make pour créer, fabriquer ou produire quelque chose.", "explanation": "En français, on dit « faire » dans les deux cas, mais l''anglais choisit. On utilise do pour les tâches, les activités et le travail à accomplir : do homework. On utilise make quand on crée, on prépare ou on produit quelque chose : make dinner, make coffee. Make sert aussi dans des expressions à apprendre par cœur : make a mistake (faire une erreur), make a decision (prendre une décision). Il n''y a pas de règle parfaite : le mieux est d''apprendre les groupes de mots ensemble.", "pattern": "do + tâche / activité ; make + chose créée / expression", "examples": [{"text": "I do my homework.", "translation": "Je fais mes devoirs."}, {"text": "We make dinner.", "translation": "Nous préparons le dîner."}, {"text": "I make a mistake.", "translation": "Je fais une erreur."}, {"text": "You make a decision.", "translation": "Tu prends une décision."}], "commonErrors": [{"wrong": "I make my homework.", "right": "I do my homework.", "why": "Les devoirs sont une tâche à accomplir, pas quelque chose qu''on crée : on dit do homework."}, {"wrong": "I do a mistake.", "right": "I make a mistake.", "why": "« Faire une erreur » est une expression avec make : make a mistake."}, {"wrong": "We do dinner.", "right": "We make dinner.", "why": "On prépare le dîner : on crée un repas. On dit make dinner."}], "tip": "Do = une tâche à faire ; make = quelque chose qu''on crée. Apprends les groupes : do homework, make a mistake."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g10.want_need_to', 'en', 'grammar', 'verbs', 'Want / need + to + verbe', 2, array['en.g08.verbs_base_form']::text[], 2, '{"rule": {"summary": "Après want et need, on met to + verbe de base : I want to go, we need to eat.", "explanation": "Want veut dire « vouloir » et need « avoir besoin de ». Quand ils sont suivis d''un autre verbe, on ajoute to, puis le verbe reste à sa forme de base : I want to go. Devant un nom, on n''ajoute pas to : I want a coffee. Pour dire « je veux que tu fasses quelque chose », l''anglais ne dit pas « I want that you… » : il place la personne juste après want, puis to + verbe : I want you to come.", "pattern": "Sujet + want / need + to + verbe de base ; Sujet + want / need + nom", "examples": [{"text": "I want to go home.", "translation": "Je veux rentrer à la maison."}, {"text": "We need to take the car.", "translation": "Nous avons besoin de prendre la voiture."}, {"text": "They want a coffee.", "translation": "Ils veulent un café."}, {"text": "I want you to give me the key.", "translation": "Je veux que tu me donnes la clé."}], "commonErrors": [{"wrong": "I want go home.", "right": "I want to go home.", "why": "Entre want et un autre verbe, il faut to."}, {"wrong": "I want that you take the car.", "right": "I want you to take the car.", "why": "En anglais, on ne dit pas « want that » : on met la personne après want, puis to + verbe."}, {"wrong": "I want to a coffee.", "right": "I want a coffee.", "why": "To s''utilise seulement devant un verbe. Devant un nom, on dit want + nom."}], "tip": "Want / need + to + verbe. Devant un nom, pas de to."}, "functionWords": ["to"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g11.can', 'en', 'grammar', 'verbs', 'Can / can''t : capacité et permission', 1, array['en.g08.verbs_base_form']::text[], 2, '{"rule": {"summary": "Can + verbe de base dit ce qu''on sait ou peut faire ; can''t dit qu''on ne peut pas.", "explanation": "Can est un verbe à part : il se place avant le verbe de base, sans to, et il ne change jamais, même avec he ou she (she can swim, jamais « she cans »). Il veut dire « savoir » (I can swim : je sais nager) ou « pouvoir ». Pour dire qu''on ne peut pas, on utilise can''t (ou cannot) : I can''t drive. Pour poser une question ou faire une demande, on met can avant le sujet : Can you help me?", "pattern": "Sujet + can / can''t + verbe de base ; Can + sujet + verbe de base ?", "examples": [{"text": "I can swim.", "translation": "Je sais nager."}, {"text": "She can''t drive.", "translation": "Elle ne sait pas conduire."}, {"text": "Can you speak English?", "translation": "Est-ce que tu parles anglais ?"}, {"text": "Tom can speak French.", "translation": "Tom sait parler français."}], "commonErrors": [{"wrong": "I can to swim.", "right": "I can swim.", "why": "Après can, on met directement le verbe de base : pas de to."}, {"wrong": "She cans drive.", "right": "She can drive.", "why": "Can ne prend jamais de -s, quelle que soit la personne."}, {"wrong": "I can speak not French.", "right": "I can''t speak French.", "why": "La négation se place sur can : can''t (ou cannot), puis le verbe."}], "tip": "Can est un verbe à part : jamais de to après, jamais de -s."}, "functionWords": ["can", "can''t", "cannot"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g12.must', 'en', 'grammar', 'verbs', 'Must / mustn''t : obligation et interdiction', 2, array['en.g11.can']::text[], 2, '{"rule": {"summary": "Must + verbe de base exprime une obligation forte ; mustn''t exprime une interdiction.", "explanation": "Must veut dire « il faut » ou « je dois ». Comme can, il est suivi directement du verbe de base, sans to, et il ne prend jamais de -s. Mustn''t veut dire « il ne faut pas » : c''est une interdiction. Attention : mustn''t ne veut pas dire « ce n''est pas nécessaire » : il dit « c''est interdit ».", "pattern": "Sujet + must / mustn''t + verbe de base", "examples": [{"text": "You must stop.", "translation": "Tu dois t''arrêter."}, {"text": "We must wait.", "translation": "Nous devons attendre."}, {"text": "You must be careful.", "translation": "Tu dois faire attention."}, {"text": "You mustn''t open the door.", "translation": "Tu ne dois pas ouvrir la porte."}], "commonErrors": [{"wrong": "I must to go.", "right": "I must go.", "why": "Après must, on met directement le verbe de base : pas de to."}, {"wrong": "She musts wait.", "right": "She must wait.", "why": "Must ne prend jamais de -s."}, {"wrong": "You must opening the door.", "right": "You must open the door.", "why": "Après must, le verbe reste à sa forme de base, sans -ing."}], "tip": "Must = il faut ; mustn''t = il ne faut pas. Toujours suivi du verbe de base, sans to."}, "functionWords": ["must", "mustn''t"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g13.imperative', 'en', 'grammar', 'verbs', 'L''impératif : Go! / Don''t go!', 1, array['en.g08.verbs_base_form']::text[], 2, '{"rule": {"summary": "Pour donner un ordre ou un conseil, on emploie le verbe de base sans sujet ; pour interdire, on ajoute Don''t devant.", "explanation": "L''impératif anglais est très simple : c''est le verbe de base, tout seul. Come! Look! Listen! Il n''y a pas de sujet et pas de to. La même forme sert pour « tu » et pour « vous ». Pour dire « ne… pas », on met Don''t devant le verbe : Don''t stop! Pour proposer quelque chose à plusieurs (« allons-y »), on utilise Let''s + verbe de base : Let''s go! Ajouter please rend la phrase plus polie.", "pattern": "Verbe de base ! / Don''t + verbe de base ! / Let''s + verbe de base !", "examples": [{"text": "Look at the dog!", "translation": "Regarde le chien !"}, {"text": "Please sit down.", "translation": "Asseyez-vous, s''il vous plaît."}, {"text": "Don''t be late!", "translation": "Ne sois pas en retard !"}, {"text": "Let''s go home.", "translation": "Rentrons à la maison."}], "commonErrors": [{"wrong": "Not stop!", "right": "Don''t stop!", "why": "Pour interdire, on met Don''t devant le verbe, pas not."}, {"wrong": "Don''t to wait.", "right": "Don''t wait.", "why": "Après Don''t, on met directement le verbe de base : pas de to."}, {"wrong": "Let''s to go home.", "right": "Let''s go home.", "why": "Après Let''s, on met directement le verbe de base : pas de to."}], "tip": "Un ordre = le verbe seul. Une interdiction = Don''t + verbe. Une proposition = Let''s + verbe."}, "functionWords": ["let''s"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g14.present_simple_third_person', 'en', 'grammar', 'verbs', 'Présent simple : la 3e personne (-s)', 2, array['en.g08.verbs_base_form','en.g01.subject_pronouns']::text[], 3, '{"rule": {"summary": "Au présent simple, on ajoute -s au verbe avec he, she, it et avec un sujet singulier (Tom, my mother).", "explanation": "Avec I, you, we et they, le verbe garde sa forme de base : I work, they work. Avec he, she, it, ou avec un prénom ou un nom au singulier, on ajoute -s : he works, Tom works, my mother works. Le présent simple sert à parler de ce qu''on fait d''habitude et de ce qui est vrai en général. Certains verbes prennent -es (watch → watches, finish → finishes, fix → fixes, go → goes, do → does), ceux en consonne + y changent en -ies (study → studies), et have devient has.", "pattern": "He / She / It + verbe + -s (-es / -ies) ; have → has", "examples": [{"text": "Tom works in London.", "translation": "Tom travaille à Londres."}, {"text": "My sister speaks French.", "translation": "Ma sœur parle français."}, {"text": "She watches a film every night.", "translation": "Elle regarde un film chaque soir."}, {"text": "He has a dog and a cat.", "translation": "Il a un chien et un chat."}], "commonErrors": [{"wrong": "He work in London.", "right": "He works in London.", "why": "Avec he, she, it, le verbe prend -s. En français, « il travaille » ne montre pas de différence à l''oral, mais en anglais le -s est obligatoire."}, {"wrong": "She have a dog.", "right": "She has a dog.", "why": "Have est irrégulier : à la 3e personne du singulier, il devient has (pas « haves »)."}, {"wrong": "He studys English.", "right": "He studies English.", "why": "Quand un verbe se termine par une consonne + y, on change le y en i et on ajoute -es : study → studies."}], "tip": "I, you, we, they : rien à ajouter. He, she, it : pense -s !"}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g15.present_simple_negative', 'en', 'grammar', 'verbs', 'Présent simple : don''t / doesn''t', 2, array['en.g14.present_simple_third_person']::text[], 3, '{"rule": {"summary": "Pour dire qu''on ne fait pas quelque chose au présent simple, on utilise don''t ou doesn''t + le verbe de base.", "explanation": "On emploie don''t (do not) avec I, you, we, they et doesn''t (does not) avec he, she, it. Après don''t ou doesn''t, le verbe reste toujours à sa forme de base, sans -s : le -s est déjà dans does. Cette négation fonctionne avec tous les verbes, sauf be, qui fait sa négation tout seul (I''m not, she isn''t).", "pattern": "Sujet + don''t / doesn''t + verbe de base", "examples": [{"text": "I don''t eat meat.", "translation": "Je ne mange pas de viande."}, {"text": "She doesn''t drink coffee.", "translation": "Elle ne boit pas de café."}, {"text": "My parents don''t live in London.", "translation": "Mes parents n''habitent pas à Londres."}, {"text": "He doesn''t work today.", "translation": "Il ne travaille pas aujourd''hui."}], "commonErrors": [{"wrong": "She don''t like fish.", "right": "She doesn''t like fish.", "why": "Avec he, she, it, on utilise doesn''t, pas don''t."}, {"wrong": "He doesn''t eats meat.", "right": "He doesn''t eat meat.", "why": "Après doesn''t, le verbe reste à sa forme de base : le -s est déjà dans does."}, {"wrong": "I no drink milk.", "right": "I don''t drink milk.", "why": "L''anglais n''a pas de « ne… pas » collé au verbe : il faut don''t ou doesn''t devant le verbe de base."}], "tip": "Doesn''t porte déjà le -s : le verbe qui suit reste tout simple."}, "functionWords": ["does", "don''t", "doesn''t"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g16.present_simple_questions', 'en', 'grammar', 'verbs', 'Présent simple : questions avec do / does', 2, array['en.g15.present_simple_negative']::text[], 3, '{"rule": {"summary": "Au présent simple, on pose une question en commençant par Do ou Does + sujet + verbe de base.", "explanation": "On utilise Do avec I, you, we, they et Does avec he, she, it. Le verbe qui suit reste à sa forme de base, sans -s : le -s est déjà dans Does. Pour répondre brièvement, on reprend do ou does : Yes, I do. / No, she doesn''t. On ne répète pas le verbe principal. Pour les questions avec be (Are you tired ?), on ne met pas do.", "pattern": "Do / Does + sujet + verbe de base ?   Yes, + sujet + do / does.   No, + sujet + don''t / doesn''t.", "examples": [{"text": "Do you speak French?", "translation": "Est-ce que tu parles français ?"}, {"text": "Does she work in London?", "translation": "Est-ce qu''elle travaille à Londres ?"}, {"text": "Yes, I do.", "translation": "Oui. (Oui, je parle français.)"}, {"text": "No, he doesn''t.", "translation": "Non. (Non, il ne travaille pas ici.)"}], "commonErrors": [{"wrong": "Does she works here?", "right": "Does she work here?", "why": "Après Does, le verbe reste à sa forme de base : le -s est déjà dans Does."}, {"wrong": "Do she like coffee?", "right": "Does she like coffee?", "why": "Avec he, she, it, la question commence par Does, pas Do."}, {"wrong": "Yes, she likes.", "right": "Yes, she does.", "why": "Pour une réponse courte, on reprend l''auxiliaire do / does, pas le verbe principal."}], "tip": "Question ou négation : Does / doesn''t prend le -s, le verbe n''en a plus besoin."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g17.frequency_adverbs', 'en', 'grammar', 'grammar', 'Les adverbes de fréquence', 2, array['en.g14.present_simple_third_person']::text[], 3, '{"rule": {"summary": "Les adverbes de fréquence (always, usually, often, sometimes, rarely, never) se placent avant le verbe, mais après to be.", "explanation": "Ils disent à quelle fréquence on fait quelque chose, de 100 % (always) à 0 % (never) : always, usually, often, sometimes, rarely, never. Avec un verbe ordinaire, l''adverbe se place avant le verbe : I always drink water. Avec to be, il se place après : She is never late. Never est déjà négatif : on n''ajoute pas don''t ou doesn''t. Sometimes peut aussi commencer la phrase : Sometimes I work at home.", "pattern": "Sujet + adverbe + verbe     /     Sujet + be + adverbe", "examples": [{"text": "I always drink water in the morning.", "translation": "Je bois toujours de l''eau le matin."}, {"text": "She is often tired in the evening.", "translation": "Elle est souvent fatiguée le soir."}, {"text": "We rarely eat meat.", "translation": "Nous mangeons rarement de la viande."}, {"text": "Tom never watches TV.", "translation": "Tom ne regarde jamais la télé."}], "commonErrors": [{"wrong": "I eat always breakfast.", "right": "I always eat breakfast.", "why": "L''adverbe de fréquence se place avant le verbe, pas après, contrairement au français « je mange toujours »."}, {"wrong": "He always is late.", "right": "He is always late.", "why": "Avec to be, l''adverbe se place après be."}, {"wrong": "She doesn''t never cook.", "right": "She never cooks.", "why": "Never a déjà un sens négatif : on n''ajoute pas doesn''t. Le -s reste sur le verbe."}], "tip": "Avant le verbe, après be : always, usually, often, rarely, never."}, "functionWords": ["always", "usually", "often", "sometimes", "rarely", "never"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g18.present_continuous', 'en', 'grammar', 'verbs', 'Le présent continu (be + -ing)', 2, array['en.g03.be_affirmative']::text[], 3, '{"rule": {"summary": "Le présent continu (be + verbe en -ing) décrit ce qui se passe en ce moment même.", "explanation": "On utilise am / is / are + le verbe en -ing : I am working, she is cooking, they are playing. Pour la négation, on ajoute not après be : I''m not working, he isn''t sleeping, we aren''t talking. Pour la question, on met be avant le sujet : Is she working ? Are you listening ? Réponse courte : Yes, she is. / No, I''m not. Côté orthographe : on enlève le -e final (make → making), on double la consonne finale d''un verbe court (run → running, sit → sitting) et ie devient y (lie → lying).", "pattern": "Sujet + am / is / are (+ not) + verbe-ing     /     Am / Is / Are + sujet + verbe-ing ?", "examples": [{"text": "It is raining now.", "translation": "Il pleut en ce moment."}, {"text": "They are not talking.", "translation": "Ils ne parlent pas."}, {"text": "Is he running?", "translation": "Est-ce qu''il court ?"}, {"text": "I''m making coffee.", "translation": "Je prépare du café."}], "commonErrors": [{"wrong": "She working now.", "right": "She is working now.", "why": "Le verbe en -ing ne s''utilise jamais seul : il faut am, is ou are devant."}, {"wrong": "He is runing.", "right": "He is running.", "why": "Run est un verbe court qui finit par une seule consonne : on la double avant -ing (running, sitting)."}, {"wrong": "I am makeing dinner.", "right": "I am making dinner.", "why": "On enlève le -e final avant d''ajouter -ing : make → making."}], "tip": "En ce moment = be + -ing. Pas de be, pas de présent continu."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g19.simple_vs_continuous', 'en', 'grammar', 'verbs', 'Présent simple ou présent continu ?', 3, array['en.g16.present_simple_questions','en.g18.present_continuous']::text[], 3, '{"rule": {"summary": "Le présent simple parle des habitudes et des faits ; le présent continu parle de ce qui se passe en ce moment.", "explanation": "Utilise le présent simple pour ce qu''on fait régulièrement ou toujours (I work every day, she often cooks). Utilise le présent continu pour ce qui se passe maintenant ou en ce moment (I''m working now, she is cooking at the moment). Les mots comme every day, always, usually vont avec le présent simple ; now, at the moment, today avec le présent continu. Les verbes d''état comme like, love, know, want, need ne s''emploient presque jamais au continu : on dit I like music, jamais I''m liking music. Avec today ou tonight, le présent continu parle de ce qu''on fait aujourd''hui ou de ce qu''on a prévu pour ce soir.", "pattern": "Habitude : Sujet + verbe (+ -s)     /     En ce moment : Sujet + be + verbe-ing", "examples": [{"text": "He works in an office every day.", "translation": "Il travaille dans un bureau tous les jours."}, {"text": "He is working at home today.", "translation": "Il travaille à la maison aujourd''hui."}, {"text": "I know her name.", "translation": "Je connais son nom."}, {"text": "They are talking at the moment.", "translation": "Ils parlent en ce moment."}], "commonErrors": [{"wrong": "I am working every day.", "right": "I work every day.", "why": "Every day indique une habitude : on utilise le présent simple, pas le présent continu."}, {"wrong": "I''m liking this music.", "right": "I like this music.", "why": "Like est un verbe d''état (un goût, un sentiment) : on ne l''emploie presque jamais au présent continu."}, {"wrong": "Tom cooks now.", "right": "Tom is cooking now.", "why": "Now indique ce qui se passe en ce moment : il faut le présent continu."}], "tip": "Tous les jours = présent simple. En ce moment = présent continu. J''aime, je sais, je veux = toujours simple."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g20.was_were', 'en', 'grammar', 'verbs', 'Le passé de to be : was / were', 2, array['en.g04.be_negative_questions']::text[], 4, '{"rule": {"summary": "Au passé, to be devient was (avec I, he, she, it) ou were (avec you, we, they).", "explanation": "Was et were sont le passé de am, is et are : ils servent à dire où on était, comment on était ou ce qu''on était (I was tired = j''étais fatigué). On utilise was avec I, he, she, it, et were avec you, we, they, y compris quand you désigne une seule personne. Pour la négation, on ajoute not : wasn''t, weren''t. Pour poser une question, on place was ou were avant le sujet (Were you at home?), et on répond brièvement : Yes, I was. / No, I wasn''t. Pour la naissance, l''anglais utilise aussi ce passé : I was born in Paris (je suis né à Paris).", "pattern": "I / he / she / it + was ; you / we / they + were — négation : wasn''t / weren''t — question : Was / Were + sujet… ?", "examples": [{"text": "I was at home yesterday.", "translation": "J''étais à la maison hier."}, {"text": "We weren''t tired last night.", "translation": "Nous n''étions pas fatigués hier soir."}, {"text": "Were you at school two days ago? — No, I wasn''t.", "translation": "Tu étais à l''école il y a deux jours ? — Non."}, {"text": "My sister was born in London.", "translation": "Ma sœur est née à Londres."}], "commonErrors": [{"wrong": "You was late yesterday.", "right": "You were late yesterday.", "why": "Avec you, c''est toujours were, même quand on parle à une seule personne."}, {"wrong": "I am born in Paris.", "right": "I was born in Paris.", "why": "« Être né » se dit to be born, et la naissance est passée : I was born."}, {"wrong": "I was in London before two days.", "right": "I was in London two days ago.", "why": "« Il y a » + durée se traduit par la durée suivie de ago : two days ago."}], "tip": "Was pour I, he, she, it ; were pour you, we, they. Et « il y a deux jours » = two days ago, avec ago après la durée."}, "functionWords": ["was", "were", "wasn''t", "weren''t"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g21.past_simple_regular', 'en', 'grammar', 'verbs', 'Passé simple : verbes réguliers (-ed)', 2, array['en.g14.present_simple_third_person']::text[], 4, '{"rule": {"summary": "Pour une action terminée dans le passé, un verbe régulier prend -ed, à toutes les personnes : I walked, she walked.", "explanation": "On utilise le passé simple (past simple) pour une action terminée à un moment passé : yesterday, last week, two days ago. Pour un verbe régulier, on ajoute -ed à la forme de base, et c''est la même forme à toutes les personnes (pas de -s avec he ou she). Orthographe : verbe terminé par -e → on ajoute seulement -d (live → lived) ; consonne + y → -ied (study → studied) ; verbe court terminé par consonne-voyelle-consonne → on double la dernière consonne (stop → stopped), et travel devient travelled en anglais britannique (traveled en américain). Prononciation : -ed se dit /t/ après un son « sourd » comme p, k, s, f, ch ou sh (walked), /d/ après les autres sons (played, cleaned), et /ɪd/, avec une syllabe en plus, seulement après t ou d (visited, decided). En français, ce passé se traduit en général par le passé composé : I walked = j''ai marché.", "pattern": "Sujet + verbe + -ed (même forme à toutes les personnes)", "examples": [{"text": "I walked to the office yesterday.", "translation": "Je suis allé au bureau à pied hier."}, {"text": "She visited her parents last week.", "translation": "Elle a rendu visite à ses parents la semaine dernière."}, {"text": "We stayed at home two days ago.", "translation": "Nous sommes restés à la maison il y a deux jours."}, {"text": "They travelled to London by train.", "translation": "Ils sont allés à Londres en train."}], "commonErrors": [{"wrong": "Yesterday I walk to school.", "right": "Yesterday I walked to school.", "why": "Avec yesterday, l''action est terminée : le verbe prend -ed."}, {"wrong": "I was walked to school.", "right": "I walked to school.", "why": "Pas de was devant un verbe d''action : walked suffit à exprimer le passé."}, {"wrong": "She studyed English.", "right": "She studied English.", "why": "Après une consonne, le y devient i avant -ed : studied."}], "tip": "Yesterday, last…, ago → verbe en -ed, sans was et sans -s."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g22.irregular_verbs', 'en', 'grammar', 'verbs', 'Passé simple : verbes irréguliers fréquents', 3, array['en.g21.past_simple_regular']::text[], 4, '{"rule": {"summary": "Beaucoup de verbes très courants ont un passé irrégulier, à apprendre par cœur : go → went, see → saw, buy → bought.", "explanation": "Les verbes irréguliers ne prennent pas -ed au passé : ils ont une forme à eux (go → went, have → had, do → did, make → made, take → took, give → gave, get → got, come → came). Comme pour les verbes réguliers, cette forme est la même à toutes les personnes : I went, she went. Ne confonds pas ce passé avec le participe passé (gone, seen, taken), qui sert à d''autres temps que tu verras plus tard. Quelques verbes ne changent pas : put → put ; read garde la même orthographe mais se prononce /red/ au passé. Le meilleur moyen de les retenir est de les apprendre dans une mini-phrase (I went home).", "pattern": "Sujet + passé irrégulier (go → went, see → saw, say → said, buy → bought…)", "examples": [{"text": "I went to work yesterday.", "translation": "Je suis allé au travail hier."}, {"text": "She saw Tom at the gym last week.", "translation": "Elle a vu Tom à la salle de sport la semaine dernière."}, {"text": "We had lunch with Anna two days ago.", "translation": "Nous avons déjeuné avec Anna il y a deux jours."}, {"text": "He put his keys in his bag.", "translation": "Il a mis ses clés dans son sac."}], "commonErrors": [{"wrong": "I goed to school.", "right": "I went to school.", "why": "Go est irrégulier : son passé est went, sans -ed."}, {"wrong": "She gone home.", "right": "She went home.", "why": "Gone est le participe passé ; pour raconter au passé simple, on utilise went."}, {"wrong": "I was go to the park.", "right": "I went to the park.", "why": "On n''ajoute pas was : went exprime déjà le passé."}], "tip": "Apprends chaque verbe irrégulier dans une mini-phrase au passé : go → I went home."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g23.past_simple_negative_questions', 'en', 'grammar', 'verbs', 'Passé simple : did / didn''t', 3, array['en.g22.irregular_verbs','en.g16.present_simple_questions']::text[], 4, '{"rule": {"summary": "Au passé simple, la négation et les questions se font avec did / didn''t + verbe à la forme de base.", "explanation": "Au passé, did remplace do et does, à toutes les personnes. Négation : sujet + didn''t (did not) + verbe de base : I didn''t go. Question : Did + sujet + verbe de base : Did you go? Avec un mot interrogatif, celui-ci se place devant did : Where did you go? What did you do? Le passé est déjà porté par did, donc le verbe qui suit reste à la base (go, see, like), jamais went ni une forme en -ed. Réponses courtes : Yes, I did. / No, I didn''t.", "pattern": "Sujet + didn''t + verbe de base — (Where / What…) + did + sujet + verbe de base ?", "examples": [{"text": "I didn''t go to the beach yesterday.", "translation": "Je ne suis pas allé à la plage hier."}, {"text": "Did you like the hotel? — Yes, I did.", "translation": "Tu as aimé l''hôtel ? — Oui."}, {"text": "Where did you go on holiday?", "translation": "Où es-tu allé en vacances ?"}, {"text": "She didn''t buy a present.", "translation": "Elle n''a pas acheté de cadeau."}], "commonErrors": [{"wrong": "Did you went to the beach?", "right": "Did you go to the beach?", "why": "Après did, le verbe reste à la base : le passé est déjà dans did."}, {"wrong": "I didn''t saw the film.", "right": "I didn''t see the film.", "why": "Didn''t + verbe de base : see, pas saw."}, {"wrong": "Where you went?", "right": "Where did you go?", "why": "Une question au passé a besoin de did avant le sujet, puis du verbe à la base."}], "tip": "Did porte le passé : le verbe qui suit reste à la base (did + go, didn''t + see)."}, "functionWords": ["did", "didn''t"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g24.will_future', 'en', 'grammar', 'verbs', 'Le futur avec will', 2, array['en.g08.verbs_base_form']::text[], 5, '{"rule": {"summary": "Avec will + verbe de base, tu parles du futur : une prédiction, une décision prise à l''instant, une promesse ou une proposition.", "explanation": "Will se place après le sujet et il est suivi du verbe à la forme de base : pas de to, pas de -s, même avec he, she et it. À l''oral, on dit surtout ''ll (I''ll call you later). La négation est will not, souvent won''t. Pour poser une question, on met will avant le sujet : Will you come tomorrow ? On l''emploie pour une prédiction (It will rain tomorrow.), une décision prise sur le moment (The phone is ringing. I''ll answer it.), une promesse ou une proposition (I''ll help you.).", "pattern": "Sujet + will / won''t + verbe de base  |  Will + sujet + verbe de base ?", "examples": [{"text": "It will rain tomorrow.", "translation": "Il pleuvra demain."}, {"text": "I''ll call you later.", "translation": "Je t''appellerai plus tard."}, {"text": "She won''t be late.", "translation": "Elle ne sera pas en retard."}, {"text": "Will you help me?", "translation": "Tu veux bien m''aider ?"}], "commonErrors": [{"wrong": "I will to go.", "right": "I will go.", "why": "Après will, on met directement le verbe de base, sans to."}, {"wrong": "He wills call you.", "right": "He will call you.", "why": "Will ne prend jamais de -s : il ne change pas, même avec he, she et it."}, {"wrong": "I call you tomorrow.", "right": "I''ll call you tomorrow.", "why": "Pour une décision ou une promesse sur l''avenir, le présent simple ne convient pas : on utilise will."}], "tip": "Après will, le verbe de base arrive tout de suite : pas de to, pas de -s."}, "functionWords": ["will", "won''t"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g25.going_to', 'en', 'grammar', 'verbs', 'Le futur avec going to', 2, array['en.g18.present_continuous']::text[], 5, '{"rule": {"summary": "Avec be + going to + verbe de base, tu parles d''une intention, d''un projet déjà décidé, ou d''une prédiction fondée sur ce que tu vois.", "explanation": "On met be (am, is, are) à la bonne forme, puis going to, puis le verbe de base : I''m going to learn French. Seul be change selon le sujet ; going to et le verbe ne bougent jamais. Pour la négation, on ajoute not après be (She isn''t going to move) ; pour la question, on met be avant le sujet (Are you going to work tomorrow ?). On utilise cette forme pour un projet décidé avant de parler, ou quand on voit un signe : Look at the sky! It''s going to rain. Attention : going to + lieu veut dire « aller quelque part » (I''m going to London), going to + verbe veut dire « je vais faire ».", "pattern": "Sujet + am / is / are (not) + going to + verbe de base", "examples": [{"text": "I''m going to learn French.", "translation": "Je vais apprendre le français."}, {"text": "We''re going to move next week.", "translation": "Nous allons déménager la semaine prochaine."}, {"text": "She isn''t going to work tomorrow.", "translation": "Elle ne va pas travailler demain."}, {"text": "Look at the sky! It''s going to rain.", "translation": "Regarde le ciel ! Il va pleuvoir."}], "commonErrors": [{"wrong": "I going to call him.", "right": "I''m going to call him.", "why": "Il manque be : am, is ou are doit toujours précéder going to."}, {"wrong": "I''m going to went home.", "right": "I''m going to go home.", "why": "Après going to, le verbe reste à la forme de base, jamais au passé."}, {"wrong": "Do you going to work tomorrow?", "right": "Are you going to work tomorrow?", "why": "La question se fait avec be, pas avec do : Are you going to… ?"}], "tip": "Going to se construit avec be : I''m, you''re, he''s… going to + verbe de base."}, "functionWords": ["going to"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g26.will_vs_going_to', 'en', 'grammar', 'verbs', 'Will ou going to ?', 3, array['en.g24.will_future','en.g25.going_to']::text[], 5, '{"rule": {"summary": "Utilise going to pour un projet déjà décidé ou une prédiction avec un indice visible ; utilise will pour une décision sur le moment, une promesse, une proposition ou une opinion.", "explanation": "Demande-toi si la décision est prise avant que tu parles. Si oui, c''est going to (I''m going to visit my mother : c''est déjà prévu). Si tu décides à l''instant, c''est will (The phone is ringing. I''ll answer it.). Pour une prédiction, on prend going to quand on voit un signe maintenant (Look at the sky! It''s going to rain.) et will quand c''est une opinion (I think it will rain tomorrow.). Les promesses et les propositions se disent avec will. En français, « je vais + verbe » et le futur simple peuvent donner will ou going to : c''est le contexte qui décide.", "pattern": "Projet décidé / indice visible → be going to + verbe  |  Décision sur le moment / promesse / opinion → will + verbe", "examples": [{"text": "I''m going to visit my mother this weekend.", "translation": "Je vais rendre visite à ma mère ce week-end. (c''est prévu)"}, {"text": "Oh, that''s a good idea. I''ll come with you.", "translation": "Ah, c''est une bonne idée. Je viendrai avec toi. (décision sur le moment)"}, {"text": "Look at the time! We''re going to be late.", "translation": "Regarde l''heure ! Nous allons être en retard. (indice visible)"}, {"text": "I think Anna will like the present.", "translation": "Je pense que le cadeau plaira à Anna. (opinion)"}], "commonErrors": [{"wrong": "Oh, you''re tired? I''m going to make you a coffee.", "right": "Oh, you''re tired? I''ll make you a coffee.", "why": "Une proposition faite sur le moment se dit avec will, pas avec going to."}, {"wrong": "She will going to call you.", "right": "She''s going to call you.", "why": "On choisit will ou going to, jamais les deux ensemble : She will call you / She''s going to call you."}, {"wrong": "I have a plan. I will to move.", "right": "I have a plan. I''m going to move.", "why": "Le projet est déjà décidé : on utilise going to. Et après will, jamais de to."}], "tip": "Déjà décidé ou signe visible ? going to. Décidé à l''instant, promesse ou opinion ? will."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g27.present_continuous_future', 'en', 'grammar', 'verbs', 'Le présent continu pour les projets fixés', 3, array['en.g25.going_to']::text[], 5, '{"rule": {"summary": "Le présent continu + un moment du futur (tomorrow, tonight, next week) sert à parler d''un rendez-vous ou d''un projet déjà organisé.", "explanation": "Quand un projet est déjà arrangé (il y a une heure, une personne, une réservation), on peut utiliser le présent continu avec une indication de temps : I''m seeing the dentist tomorrow. Sans indication de temps, la phrase parle du moment présent. Avec ce sens, going to est aussi possible (I''m going to see the dentist tomorrow), mais le présent continu montre que tout est déjà fixé. Avec un verbe d''action, on n''utilise pas le présent simple pour un rendez-vous personnel (I meet the dentist tomorrow est incorrect). On n''utilise pas non plus ce présent continu pour une simple prédiction : It will rain tomorrow, et non It''s raining tomorrow.", "pattern": "Sujet + am / is / are + verbe en -ing + moment du futur", "examples": [{"text": "I''m seeing the doctor tomorrow morning.", "translation": "Je vois le médecin demain matin."}, {"text": "We''re meeting our colleagues tonight.", "translation": "Nous retrouvons nos collègues ce soir."}, {"text": "Tom is having dinner with Anna tomorrow evening.", "translation": "Tom dîne avec Anna demain soir."}, {"text": "What are you doing next weekend?", "translation": "Qu''est-ce que tu fais le week-end prochain ?"}], "commonErrors": [{"wrong": "I meet the dentist tomorrow.", "right": "I''m meeting the dentist tomorrow.", "why": "Pour un rendez-vous fixé, on utilise be + -ing, pas le présent simple."}, {"wrong": "It''s raining tomorrow.", "right": "It will rain tomorrow.", "why": "Le présent continu parle d''un projet organisé. Pour une prédiction, on utilise will ou going to."}, {"wrong": "She meeting her friend tonight.", "right": "She''s meeting her friend tonight.", "why": "Il manque be (am, is, are) devant le verbe en -ing."}], "tip": "Rendez-vous déjà fixé ? be + -ing + un moment du futur (tomorrow, tonight, next week)."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g28.there_is_are', 'en', 'grammar', 'grammar', 'There is / there are', 2, array['en.g07.plural_nouns','en.g04.be_negative_questions']::text[], 6, '{"rule": {"summary": "Pour dire qu''une chose existe ou se trouve quelque part (« il y a »), on dit there is devant un seul élément et there are devant plusieurs.", "explanation": "« Il y a » se dit there is devant un seul élément (There is a sofa) et there are devant plusieurs (There are two chairs). Le verbe est toujours be, jamais have, et il s''accorde avec ce qui suit there. Pour nier, on dit there isn''t ou there aren''t. Pour poser une question, on inverse : Is there a garden ? Are there two chairs ? On répond Yes, there is. / No, there isn''t. À l''oral, there is se contracte en there''s.", "pattern": "There is / There are + nom + lieu", "examples": [{"text": "There is a sofa in the living room.", "translation": "Il y a un canapé dans le salon."}, {"text": "There are two chairs in the kitchen.", "translation": "Il y a deux chaises dans la cuisine."}, {"text": "There isn''t a garden.", "translation": "Il n''y a pas de jardin."}, {"text": "Is there a lamp in the bedroom? Yes, there is.", "translation": "Y a-t-il une lampe dans la chambre ? Oui, il y en a une."}], "commonErrors": [{"wrong": "There have a garden.", "right": "There is a garden.", "why": "« Il y a » ne se traduit pas par have. Avec there, on utilise toujours is ou are."}, {"wrong": "There is two chairs.", "right": "There are two chairs.", "why": "Deux chaises, c''est pluriel : on utilise there are, pas there is."}, {"wrong": "It''s a table in the kitchen.", "right": "There is a table in the kitchen.", "why": "Pour dire « il y a », on commence par there is. It''s veut dire « c''est »."}], "tip": "« Il y a » = there is (un seul) ou there are (plusieurs) : jamais have."}, "functionWords": ["there"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g29.some_any', 'en', 'grammar', 'grammar', 'Some / any', 2, array['en.g28.there_is_are']::text[], 6, '{"rule": {"summary": "Some s''utilise dans les phrases affirmatives et dans les demandes polies ; any s''utilise dans les phrases négatives et dans les questions.", "explanation": "Some veut dire « du, de la, des, quelques » : une quantité qu''on ne précise pas. Dans une phrase affirmative, on dit some : There is some bread. Dans une négation ou une question simple, on dit any : There isn''t any bread (« pas de pain »), Do you have any water ? Mais dans une demande ou une offre polie, on garde some : Can I have some water, please ? Some et any s''emploient avec les pluriels et les noms qu''on ne compte pas (water, bread), sans article.", "pattern": "Affirmatif : some + nom  |  Négatif / question : any + nom  |  Demande polie : Can I have some + nom ?", "examples": [{"text": "We have some bread.", "translation": "Nous avons du pain."}, {"text": "There isn''t any milk in the fridge.", "translation": "Il n''y a pas de lait dans le frigo."}, {"text": "Do you have any water?", "translation": "Avez-vous de l''eau ?"}, {"text": "Can I have some coffee, please?", "translation": "Puis-je avoir du café, s''il vous plaît ?"}], "commonErrors": [{"wrong": "I have any water.", "right": "I have some water.", "why": "Any ne s''utilise pas dans une phrase affirmative : on dit some."}, {"wrong": "I don''t have some bread.", "right": "I don''t have any bread.", "why": "Dans une phrase négative, on utilise any, pas some."}, {"wrong": "Can I have any water, please?", "right": "Can I have some water, please?", "why": "Quand on demande poliment quelque chose, on garde some, même dans une question."}], "tip": "Some = oui (et demandes polies) ; any = non ou question."}, "functionWords": ["some", "any"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g30.how_much_many', 'en', 'grammar', 'grammar', 'How much / how many', 2, array['en.g29.some_any']::text[], 6, '{"rule": {"summary": "How many se place devant un nom qu''on peut compter (au pluriel) ; how much devant un nom qu''on ne compte pas, et pour demander un prix.", "explanation": "Pour demander « combien de », on se demande d''abord si on peut compter. Si oui, on dit how many + pluriel : How many tickets do you need ? Si non (money, bread, luggage), on dit how much + nom sans -s : How much money do you have ? Pour demander un prix, on dit How much is it ? (un objet) ou How much are they ? (plusieurs), et on répond It''s ten pounds. Luggage n''a jamais de pluriel : jamais « luggages ». Dans une phrase affirmative, on préfère a lot of (beaucoup de), qui va avec les deux : a lot of money, a lot of tickets.", "pattern": "How many + nom pluriel ?  |  How much + nom non comptable ?  |  How much is / are + sujet ?", "examples": [{"text": "How many tickets do you need?", "translation": "De combien de billets as-tu besoin ?"}, {"text": "How much money do you have?", "translation": "Combien d''argent as-tu ?"}, {"text": "How much is the bread? It''s two pounds.", "translation": "Combien coûte le pain ? Il coûte deux livres."}, {"text": "We have a lot of luggage.", "translation": "Nous avons beaucoup de bagages."}], "commonErrors": [{"wrong": "How many money do you have?", "right": "How much money do you have?", "why": "Money ne se compte pas (on ne dit pas « un money, deux moneys ») : on utilise how much."}, {"wrong": "How much tickets do you need?", "right": "How many tickets do you need?", "why": "Les billets se comptent : on utilise how many devant un pluriel."}, {"wrong": "I have two luggages.", "right": "I have two bags. / I have a lot of luggage.", "why": "Luggage ne se compte pas et n''a jamais de -s. Pour compter, on dit two bags."}], "tip": "On peut compter ? How many + pluriel. On ne peut pas ? How much."}, "functionWords": ["much", "many", "a lot of"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g31.time_and_dates', 'en', 'grammar', 'grammar', 'Dire l''heure et la date', 2, array['en.g04.be_negative_questions']::text[], 6, '{"rule": {"summary": "Pour dire l''heure, on utilise It''s + l''heure : It''s seven o''clock, half past six, quarter past seven, quarter to eight.", "explanation": "On demande What time is it ? et on répond It''s + l''heure. Heure pile : It''s seven o''clock (o''clock ne s''utilise que pour les heures pleines). Après l''heure, on dit past : ten past six, quarter past six (6 h 15), half past six (6 h 30, jamais « six and half »). Avant l''heure, on dit to : twenty to seven (6 h 40), quarter to seven (6 h 45). Pour dire à quelle heure, on utilise at (at seven o''clock), et in pour « dans combien de temps » (in twenty minutes) ; hour désigne une durée (an hour), pas l''heure : pas de « at 7 hours ». Les grands nombres : twenty (20), a hundred (100).", "pattern": "It''s + nombre + o''clock  |  It''s + minutes + past / to + heure  |  at + heure", "examples": [{"text": "It''s seven o''clock.", "translation": "Il est sept heures."}, {"text": "It''s half past six.", "translation": "Il est six heures et demie."}, {"text": "It''s quarter past eight.", "translation": "Il est huit heures et quart."}, {"text": "The meeting is at quarter to nine.", "translation": "La réunion est à neuf heures moins le quart."}], "commonErrors": [{"wrong": "It''s six and half.", "right": "It''s half past six.", "why": "« Et demie » se dit half past devant l''heure : half past six. On n''utilise pas and."}, {"wrong": "I get up at 7 hours.", "right": "I get up at seven o''clock.", "why": "Pour l''heure, on n''utilise pas hours (qui veut dire « durée »). On dit at seven o''clock, ou simplement at seven."}, {"wrong": "It''s seven hours.", "right": "It''s seven o''clock.", "why": "Pour dire l''heure qu''il est, on dit o''clock après un nombre : It''s seven o''clock."}], "tip": "Demie = half past + heure ; moins le quart = quarter to + heure suivante."}, "functionWords": ["o''clock", "quarter"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g32.word_order', 'en', 'grammar', 'sentence_building', 'L''ordre des mots dans la phrase', 2, array['en.g14.present_simple_third_person']::text[], 7, '{"rule": {"summary": "En anglais, l''ordre des mots est presque toujours le même : sujet + verbe + complément, avec l''adjectif avant le nom.", "explanation": "Une phrase anglaise suit l''ordre sujet + verbe + complément (I like English). On ne glisse jamais un adverbe entre le verbe et son complément : on le met à la fin (I like English very much). L''adjectif se place avant le nom (a big apartment) et il ne change jamais : pas de -s au pluriel (two big apartments), pas de féminin. Les adverbes de fréquence (always, never) se placent avant le verbe, mais après be. Les mots de temps comme today, tomorrow ou yesterday se mettent au début ou à la fin de la phrase.", "pattern": "Sujet + verbe + complément (+ lieu + temps) ; adjectif + nom", "examples": [{"text": "We have a big apartment.", "translation": "Nous avons un grand appartement."}, {"text": "I like English very much.", "translation": "J''aime beaucoup l''anglais."}, {"text": "Tom never drinks coffee.", "translation": "Tom ne boit jamais de café."}, {"text": "Tomorrow we visit a new school.", "translation": "Demain, nous visitons une nouvelle école."}], "commonErrors": [{"wrong": "I like very much English.", "right": "I like English very much.", "why": "En français, on dit « j''aime beaucoup l''anglais », mais en anglais l''adverbe ne s''intercale pas entre le verbe et son complément : il passe à la fin."}, {"wrong": "She has a house big.", "right": "She has a big house.", "why": "L''adjectif se place avant le nom, pas après."}, {"wrong": "They have two bigs apartments.", "right": "They have two big apartments.", "why": "L''adjectif est invariable : il ne prend ni -s ni féminin."}], "tip": "Verbe et complément restent collés : on met l''adjectif devant le nom, et l''adverbe tout à la fin."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g33.prepositions_place', 'en', 'grammar', 'sentence_building', 'Les prépositions de lieu', 2, array['en.g28.there_is_are']::text[], 7, '{"rule": {"summary": "In, on et at servent à dire où se trouve quelque chose ; under, next to, between, behind et in front of précisent sa position.", "explanation": "Avec in, on voit un espace fermé ou une zone : in the kitchen, in London, in the park. Avec on, on voit une surface ou un étage : on the table, on the floor, on the second floor. Avec at, on voit un point précis ou un lieu où l''on fait son activité : at the door, at home, at school. Pour la position exacte, on utilise under (sous), next to (à côté de), between … and … (entre), behind (derrière) et in front of (devant). Attention : « devant » se dit in front of, avec of.", "pattern": "Sujet + be + préposition + the + lieu", "examples": [{"text": "The keys are on the table.", "translation": "Les clés sont sur la table."}, {"text": "My brother lives in London.", "translation": "Mon frère habite à Londres."}, {"text": "Anna is at the door.", "translation": "Anna est à la porte."}, {"text": "The dog is between Anna and Tom.", "translation": "Le chien est entre Anna et Tom."}], "commonErrors": [{"wrong": "The book is in the table.", "right": "The book is on the table.", "why": "Le livre est posé sur une surface : on utilise on, pas in."}, {"wrong": "I am in home.", "right": "I am at home.", "why": "« À la maison » est une expression fixe : at home."}, {"wrong": "The car is in front the house.", "right": "The car is in front of the house.", "why": "« Devant » se dit in front of : il ne faut pas oublier of."}], "tip": "In = dedans, on = dessus, at = à un endroit précis."}, "functionWords": ["in", "on", "at", "under", "next to", "between", "behind", "in front of"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g34.prepositions_time', 'en', 'grammar', 'sentence_building', 'Les prépositions de temps : in, on, at', 2, array['en.g31.time_and_dates']::text[], 7, '{"rule": {"summary": "On dit at avec l''heure, on avec les jours et les dates, in avec les mois, les saisons, les années et les moments de la journée.", "explanation": "At sert pour l''heure exacte : at 8 o''clock, at noon, et pour at night et at the weekend. On sert pour un jour ou une date : on Monday, on Sunday morning, on 5 January. In sert pour les périodes plus longues : in January, in summer, in 2030, in the morning, in the evening. Les jours et les mois prennent toujours une majuscule en anglais (Monday, January), mais pas les saisons (summer, winter). Avec today, tomorrow, yesterday, next week et last year, on n''utilise aucune préposition. Before, after et during veulent dire « avant », « après » et « pendant ».", "pattern": "at + heure ; on + jour / date ; in + mois / saison / année / moment de la journée", "examples": [{"text": "The meeting is at 3 o''clock.", "translation": "La réunion est à 15 heures."}, {"text": "I stay at home on Sunday.", "translation": "Je reste à la maison le dimanche."}, {"text": "It snows in January.", "translation": "Il neige en janvier."}, {"text": "I always read after dinner.", "translation": "Je lis toujours après le dîner."}], "commonErrors": [{"wrong": "I work in Monday.", "right": "I work on Monday.", "why": "Pour un jour de la semaine, on utilise on."}, {"wrong": "I get up at the morning.", "right": "I get up in the morning.", "why": "Le matin se dit in the morning ; at ne s''emploie que pour l''heure exacte ou at night."}, {"wrong": "We go to the beach on summer.", "right": "We go to the beach in summer.", "why": "Une saison, un mois ou une année demande in, pas on."}], "tip": "Du plus précis au plus large : at 8 o''clock, on Monday, in January."}, "functionWords": ["before", "after", "during"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g35.question_words', 'en', 'grammar', 'sentence_building', 'Les mots interrogatifs', 2, array['en.g16.present_simple_questions','en.g23.past_simple_negative_questions']::text[], 7, '{"rule": {"summary": "Pour poser une question précise, on place le mot interrogatif au début, puis l''auxiliaire, puis le sujet.", "explanation": "Les mots interrogatifs sont what (quoi, quel), where (où), when (quand), who (qui), why (pourquoi), how (comment) et which (lequel, quel parmi un choix). L''ordre est toujours : mot interrogatif + auxiliaire (do, does, did, is, are, can…) + sujet + verbe. On dit Where do you live? et non Where you live?. Pour l''âge, on dit How old are you? (pas « quel âge as-tu »), et pour l''heure What time is it?. Quand who est le sujet de la question, il n''y a pas d''auxiliaire : Who lives here? On répond à why avec because.", "pattern": "Mot interrogatif + auxiliaire + sujet + verbe ?", "examples": [{"text": "Where do you live?", "translation": "Où habites-tu ?"}, {"text": "What time does the meeting start?", "translation": "À quelle heure commence la réunion ?"}, {"text": "How old is your daughter?", "translation": "Quel âge a ta fille ?"}, {"text": "Why are you late?", "translation": "Pourquoi es-tu en retard ?"}], "commonErrors": [{"wrong": "Where you live?", "right": "Where do you live?", "why": "Il faut l''auxiliaire do entre le mot interrogatif et le sujet."}, {"wrong": "What age have you?", "right": "How old are you?", "why": "En anglais, on demande l''âge avec how old + be, pas avec have."}, {"wrong": "Why do you are late?", "right": "Why are you late?", "why": "Avec le verbe be, on inverse be et le sujet, sans do."}], "tip": "Mot interrogatif, auxiliaire, sujet : dans cet ordre, toujours."}, "functionWords": ["what", "where", "when", "who", "why", "how", "which"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g36.connectors', 'en', 'grammar', 'sentence_building', 'Les connecteurs : and, but, because, so…', 2, array['en.g14.present_simple_third_person']::text[], 7, '{"rule": {"summary": "And, but, or, because, so et then relient deux idées : ajout, contraste, choix, cause, conséquence, suite.", "explanation": "And ajoute une idée (et), but marque une opposition (mais) et or propose un choix (ou). Because donne la cause (parce que) et répond à why ; so donne la conséquence (donc, alors). Then veut dire « puis, ensuite » : il montre l''ordre des actions. Après because, il faut une phrase complète avec un sujet et un verbe : because it rains. Ne confonds pas because et so : la cause se place après because, la conséquence après so.", "pattern": "Phrase 1 + and / but / or / so + phrase 2 ; phrase + because + sujet + verbe", "examples": [{"text": "It is hot, so I drink water.", "translation": "Il fait chaud, donc je bois de l''eau."}, {"text": "I like summer, but I don''t like the sun.", "translation": "J''aime l''été, mais je n''aime pas le soleil."}, {"text": "We stay at home because it snows.", "translation": "Nous restons à la maison parce qu''il neige."}, {"text": "First I eat breakfast, then I go to work.", "translation": "D''abord je prends mon petit-déjeuner, puis je vais travailler."}], "commonErrors": [{"wrong": "It is hot, because I drink water.", "right": "It is hot, so I drink water.", "why": "Ici, boire de l''eau est la conséquence de la chaleur : on utilise so. Because introduit la cause."}, {"wrong": "I stay at home because the rain.", "right": "I stay at home because it rains.", "why": "Après because, il faut un sujet et un verbe, pas seulement un nom."}, {"wrong": "I eat dinner, than I watch TV.", "right": "I eat dinner, then I watch TV.", "why": "« Puis » s''écrit then. Than sert aux comparaisons (taller than)."}], "tip": "Because donne la raison, so donne le résultat."}, "functionWords": ["and", "but", "or", "because", "so", "then"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g37.comparatives_superlatives', 'en', 'grammar', 'grammar', 'Comparatifs et superlatifs', 3, array['en.g04.be_negative_questions']::text[], 7, '{"rule": {"summary": "Pour comparer, on ajoute -er (ou more) à l''adjectif, puis than ; pour le plus haut degré, on utilise the + -est (ou the most).", "explanation": "Avec un adjectif court, on ajoute -er pour comparer et the + -est pour le superlatif : fast, faster, the fastest. Si l''adjectif finit par une consonne après une seule voyelle, on double la consonne (big, bigger, the biggest). Si l''adjectif finit par -y, le y devient i (easy, easier, the easiest). Avec un adjectif long, on met more ou the most devant : more beautiful, the most beautiful. Good et bad sont irréguliers : better, the best, worse, the worst. Après un comparatif, on utilise than (plus … que).", "pattern": "adjectif court + -er + than ; the + adjectif court + -est ; more / the most + adjectif long", "examples": [{"text": "My brother is taller than my father.", "translation": "Mon frère est plus grand que mon père."}, {"text": "My new book is easier than my old book.", "translation": "Mon nouveau livre est plus facile que mon vieux livre."}, {"text": "London is the biggest city in the country.", "translation": "Londres est la plus grande ville du pays."}, {"text": "The hotel is more expensive than the apartment.", "translation": "L''hôtel est plus cher que l''appartement."}], "commonErrors": [{"wrong": "My car is more big than your car.", "right": "My car is bigger than your car.", "why": "Big est un adjectif court : on ajoute -er (avec un g doublé), pas more."}, {"wrong": "He is the most good student.", "right": "He is the best student.", "why": "Good est irrégulier : better, the best."}, {"wrong": "Anna is taller that Tom.", "right": "Anna is taller than Tom.", "why": "« Que » dans une comparaison se dit than, pas that."}], "tip": "Court : -er / -est. Long : more / most. Après le comparatif : than."}, "functionWords": ["than", "more", "most"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g38.should_could', 'en', 'grammar', 'verbs', 'Should / could : conseils et demandes polies', 3, array['en.g11.can']::text[], 7, '{"rule": {"summary": "Should donne un conseil, could exprime une possibilité ou une demande polie ; would like sert à demander ou à proposer poliment.", "explanation": "Should veut dire « devrait » : You should rest. Could veut dire « pourrait » : We could go to the park, ou sert à demander poliment : Could you help me, please? Comme can, ces deux verbes sont suivis du verbe de base, sans to et sans -s : She should rest, He could come. Pour la forme négative, on dit shouldn''t, et pour la question, on inverse : Should I call the doctor? Pour demander poliment, on dit aussi I''d like… (je voudrais) et Would you like… ? (voulez-vous… ?), plus polis que I want et Do you want…?", "pattern": "Sujet + should / could + verbe de base ; Could you + verbe ? ; I''d like / Would you like ...", "examples": [{"text": "You should rest.", "translation": "Tu devrais te reposer."}, {"text": "We could eat at home tonight.", "translation": "On pourrait manger à la maison ce soir."}, {"text": "Could you open the window, please?", "translation": "Pourriez-vous ouvrir la fenêtre, s''il vous plaît ?"}, {"text": "Would you like a coffee?", "translation": "Voulez-vous un café ?"}], "commonErrors": [{"wrong": "I should to go.", "right": "I should go.", "why": "Après should (comme après can), on met le verbe de base, sans to."}, {"wrong": "Could you to help me?", "right": "Could you help me?", "why": "Même règle : could est suivi du verbe de base, sans to."}, {"wrong": "She shoulds rest.", "right": "She should rest.", "why": "Should ne prend jamais de -s, même avec she, he ou it."}], "tip": "Should et could sont suivis du verbe tout nu : jamais de to, jamais de -s."}, "functionWords": ["should", "could", "would"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g39.present_perfect_intro', 'en', 'grammar', 'verbs', 'Le present perfect : introduction', 4, array['en.g22.irregular_verbs']::text[], 8, '{"rule": {"summary": "Le present perfect (have / has + participe passé) sert à parler d''une expérience ou d''un résultat, sans dire quand cela s''est passé.", "explanation": "Le present perfect se forme avec have / has + participe passé : les verbes réguliers finissent en -ed (visited, tried), les irréguliers sont à apprendre (seen, eaten, done, been, gone ; met ou lost sont identiques au past simple). On l''utilise pour une expérience de vie ou un résultat, sans préciser le moment : I have seen this film. Pour demander une expérience, on dit Have you ever…? ; la réponse négative se fait avec never : I have never been abroad. Dès que tu donnes un moment précis (yesterday, last year, two days ago), tu dois utiliser le past simple : I saw this film yesterday. Been to veut dire « être allé quelque part et en être revenu » ; gone to veut dire « être parti et ne pas être encore revenu ». Tu rencontreras aussi just (je viens de), already (déjà), yet (déjà ? / pas encore), et plus tard for / since pour une durée (I have lived here for two years).", "pattern": "Sujet + have / has + participe passé  |  Have / Has + sujet + (ever) + participe passé ?  |  Sujet + have / has + never + participe passé", "examples": [{"text": "I have seen this film.", "translation": "J''ai déjà vu ce film."}, {"text": "Have you ever been to London?", "translation": "Es-tu déjà allé à Londres ?"}, {"text": "She has never eaten fish.", "translation": "Elle n''a jamais mangé de poisson."}, {"text": "I saw Tom yesterday.", "translation": "J''ai vu Tom hier. (moment précis : past simple)"}], "commonErrors": [{"wrong": "I have seen him yesterday.", "right": "I saw him yesterday.", "why": "Avec un moment précis (yesterday, last year, ago), on utilise le past simple, jamais le present perfect."}, {"wrong": "I have went to Paris.", "right": "I have been to Paris.", "why": "Went est le past simple. Après have, il faut le participe passé : gone ou, pour une visite terminée, been."}, {"wrong": "I am here since two years.", "right": "I have been here for two years.", "why": "Pour une situation qui dure depuis un moment, on utilise le present perfect avec for + durée (since + point de départ). On y reviendra plus tard."}], "tip": "Si tu dis quand, c''est le past simple ; si tu ne le dis pas (ever, never), c''est have / has + participe passé."}, "functionWords": ["been"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g40.short_answers', 'en', 'grammar', 'sentence_building', 'Réponses courtes et reprises (Yes, I do / Me too)', 3, array['en.g16.present_simple_questions','en.g23.past_simple_negative_questions']::text[], 8, '{"rule": {"summary": "Pour répondre brièvement, on reprend l''auxiliaire de la question (Yes, I do), et pour réagir on dit Me too (moi aussi) ou Me neither (moi non plus).", "explanation": "Quand une question commence par un auxiliaire (do, does, did, is, are, can, have…), la réponse courte reprend ce même auxiliaire : Do you like tea? Yes, I do. / No, I don''t. On ne répète pas le verbe principal. Pour dire « moi aussi » après une phrase affirmative, on dit Me too (ou I do too) ; pour dire « moi non plus » après une phrase négative, on dit Me neither (ou I don''t either). Too veut dire « aussi », either veut dire « non plus » : ils se placent à la fin de la phrase. Enfin, quelques formules de politesse sont à connaître par cœur : Nice to meet you, How are you?, Excuse me, Of course, No problem.", "pattern": "Do / Does / Did / Is / Are / Have…? → Yes, + pronom + auxiliaire. / No, + pronom + auxiliaire + n''t.  |  Affirmatif : Me too  |  Négatif : Me neither", "examples": [{"text": "Do you like coffee? — Yes, I do.", "translation": "Tu aimes le café ? — Oui."}, {"text": "Is she a teacher? — No, she isn''t.", "translation": "Est-elle professeure ? — Non."}, {"text": "Have you ever been abroad? — No, I haven''t.", "translation": "Es-tu déjà allé à l''étranger ? — Non."}, {"text": "I love this film. — Me too.", "translation": "J''adore ce film. — Moi aussi."}], "commonErrors": [{"wrong": "Do you like tea? — Yes, I like.", "right": "Do you like tea? — Yes, I do.", "why": "En réponse courte, on ne répète pas le verbe : on reprend l''auxiliaire de la question (do)."}, {"wrong": "I don''t like cold water. — Me too.", "right": "I don''t like cold water. — Me neither.", "why": "Me too répond à une phrase affirmative. Après une phrase négative, « moi non plus » se dit Me neither."}, {"wrong": "I don''t know. — I don''t neither.", "right": "I don''t know. — I don''t either.", "why": "En anglais, on ne met pas deux négations : on dit I don''t either (ou simplement Me neither)."}], "tip": "Même auxiliaire dans la réponse que dans la question ; « aussi » = too / me too, « non plus » = either / me neither."}, "functionWords": ["too", "either"]}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('en.g41.tense_contrast', 'en', 'grammar', 'verbs', 'Choisir le bon temps', 4, array['en.g19.simple_vs_continuous','en.g23.past_simple_negative_questions','en.g26.will_vs_going_to','en.g39.present_perfect_intro']::text[], 8, '{"rule": {"summary": "Pour choisir le bon temps, repère le marqueur de temps et ce que tu veux dire : habitude, action en cours, passé daté, expérience ou futur.", "explanation": "Regarde d''abord le petit mot de temps. Every day, always, usually : habitude, donc présent simple (I work). Now, at the moment : action en cours, donc présent continu (I''m working). Yesterday, last year, two days ago : moment précis dans le passé, donc past simple (I worked). Ever, never, already, just, yet, ou aucune date : expérience ou résultat, donc present perfect (I have worked). Tomorrow, next week, soon : futur, avec will (décision, promesse) ou going to (projet).", "pattern": "every day → présent simple  |  now → be + -ing  |  yesterday / ago → past simple  |  ever / never / already → have + participe passé  |  tomorrow / next → will / going to", "examples": [{"text": "I usually walk to work, but today I''m driving.", "translation": "D''habitude je vais au travail à pied, mais aujourd''hui je conduis."}, {"text": "I saw this film last year.", "translation": "J''ai vu ce film l''année dernière."}, {"text": "Have you ever tried sushi?", "translation": "As-tu déjà goûté des sushis ?"}, {"text": "We''re going to travel next week.", "translation": "Nous allons voyager la semaine prochaine."}], "commonErrors": [{"wrong": "I have visited the museum last year.", "right": "I visited the museum last year.", "why": "Last year donne un moment précis : on utilise le past simple."}, {"wrong": "I am working here every day.", "right": "I work here every day.", "why": "Every day indique une habitude : on utilise le présent simple, pas le présent continu."}, {"wrong": "I have never see this film.", "right": "I have never seen this film.", "why": "Après have / has, il faut le participe passé (seen), pas la forme de base."}], "tip": "Un marqueur, un temps : every day = simple, now = -ing, yesterday = past simple, ever / never = have + participe, tomorrow = will / going to."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
