insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('en.l60', 'en', 8, 'Comprendre et s''exprimer', 'Compréhension de textes courts et production de phrases autonomes.', 4, 60, 'en.g41.tense_contrast', array['en.v.describe','en.v.explain','en.v.believe','en.v.agree','en.v.opinion']::text[], array['en.g41.tense_contrast']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l01.e01', 'en', 'en.l01', 'en.g01.subject_pronouns', array['en.g01.subject_pronouns']::text[], 'mcq', 'lesson', 'Comment dit-on « elle » en anglais, pour parler d''une femme ?', array['she']::text[], 'She veut dire « elle » quand on parle d''une femme ou d''une fille. He, c''est « il » pour un homme.', 1, '{"id": "en.l01.e01", "unitIds": ["en.g01.subject_pronouns"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon pronom.", "prompt": "Comment dit-on « elle » en anglais, pour parler d''une femme ?", "promptLanguage": "fr", "options": ["she", "he", "it", "we"], "answer": "she", "acceptedAnswers": ["she"], "hint": "C''est le pronom de he, avec une lettre en plus devant.", "explanation": "She veut dire « elle » quand on parle d''une femme ou d''une fille. He, c''est « il » pour un homme.", "tip": "Retiens la paire : he = il (un homme), she = elle (une femme).", "extraExample": {"text": "Anna? She is in London.", "translation": "Anna ? Elle est à Londres."}, "errorPatterns": [{"equals": "he", "category": "vocabulary", "feedback": "He veut dire « il », pour un homme. Pour une femme, on dit she."}, {"equals": "it", "category": "word_confusion", "feedback": "It s''utilise pour une chose ou un animal. Pour une femme, on dit she."}, {"equals": "we", "category": "vocabulary", "feedback": "We veut dire « nous ». Pour « elle », on dit she."}], "pool": "lesson", "lessonId": "en.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l01.e02', 'en', 'en.l01', 'en.g01.subject_pronouns', array['en.g01.subject_pronouns']::text[], 'mcq', 'lesson', 'Quel pronom anglais utilises-tu pour parler d''une chose, comme un livre ou une table ?', array['it']::text[], 'En anglais, les choses n''ont pas de genre : un livre ou une table, c''est toujours it. He et she sont réservés aux personnes.', 1, '{"id": "en.l01.e02", "unitIds": ["en.g01.subject_pronouns"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon pronom.", "prompt": "Quel pronom anglais utilises-tu pour parler d''une chose, comme un livre ou une table ?", "promptLanguage": "fr", "options": ["it", "he", "she", "they"], "answer": "it", "acceptedAnswers": ["it"], "hint": "En anglais, une chose n''est ni masculine ni féminine.", "explanation": "En anglais, les choses n''ont pas de genre : un livre ou une table, c''est toujours it. He et she sont réservés aux personnes.", "tip": "Une chose ou un animal → it, même si le mot est masculin ou féminin en français.", "extraExample": {"text": "The hotel? It is in Paris.", "translation": "L''hôtel ? Il est à Paris."}, "errorPatterns": [{"equals": "he", "category": "grammar", "feedback": "He veut dire « il » pour un homme. Pour une chose, même masculine en français (le livre), on dit it."}, {"equals": "she", "category": "grammar", "feedback": "She veut dire « elle » pour une femme. Pour une chose, même féminine en français (la table), on dit it."}, {"equals": "they", "category": "grammar", "feedback": "They s''utilise pour plusieurs personnes ou choses. Pour une seule chose, on dit it."}], "pool": "lesson", "lessonId": "en.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l01.e03', 'en', 'en.l01', 'en.g01.subject_pronouns', array['en.g01.subject_pronouns']::text[], 'match', 'lesson', 'Les pronoms sujets : I, you, he, we, they', '{}'::text[], 'You sert à la fois pour « tu » et pour « vous ». They remplace « ils » comme « elles » : au pluriel, l''anglais ne distingue pas le masculin du féminin.', 1, '{"id": "en.l01.e03", "unitIds": ["en.g01.subject_pronouns"], "type": "match", "difficulty": 1, "instruction": "Associe chaque pronom anglais à sa traduction.", "prompt": "Les pronoms sujets : I, you, he, we, they", "promptLanguage": "fr", "pairs": [{"left": "I", "right": "je"}, {"left": "you", "right": "tu / vous"}, {"left": "he", "right": "il (un homme)"}, {"left": "we", "right": "nous"}, {"left": "they", "right": "ils / elles"}], "answer": "I = je ; you = tu / vous ; he = il (un homme) ; we = nous ; they = ils / elles", "acceptedAnswers": [], "explanation": "You sert à la fois pour « tu » et pour « vous ». They remplace « ils » comme « elles » : au pluriel, l''anglais ne distingue pas le masculin du féminin.", "tip": "Un seul mot pour tu et vous (you), un seul mot pour ils et elles (they).", "extraExample": {"text": "Lucy and Emma? They are in Paris.", "translation": "Lucy et Emma ? Elles sont à Paris."}, "pool": "lesson", "lessonId": "en.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l01.e04', 'en', 'en.l01', 'en.g01.subject_pronouns', array['en.g01.subject_pronouns','en.v.thank_you']::text[], 'fill_blank', 'lesson', 'Tom: ___ are welcome!', array['You']::text[], 'Pour répondre à « Thank you » (merci), on dit You are welcome (de rien). Tom parle à Anna, donc il utilise you (tu).', 2, '{"id": "en.l01.e04", "unitIds": ["en.g01.subject_pronouns", "en.v.thank_you"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon pronom. « ___ are welcome » est une formule toute faite qui veut dire « de rien » : tu étudieras are à la leçon 3.", "context": "Anna: Thank you, Tom!", "prompt": "Tom: ___ are welcome!", "promptLanguage": "en", "options": ["You", "I", "He", "She"], "answer": "You", "acceptedAnswers": ["You"], "hint": "Tom répond à Anna : il lui parle directement.", "explanation": "Pour répondre à « Thank you » (merci), on dit You are welcome (de rien). Tom parle à Anna, donc il utilise you (tu).", "tip": "Thank you → You are welcome : on répond toujours avec you.", "extraExample": {"text": "Thank you, Ben! — You are welcome, Emma.", "translation": "Merci, Ben ! — De rien, Emma."}, "errorPatterns": [{"equals": "i", "category": "grammar", "feedback": "I veut dire « je ». La formule pour dire « de rien » est You are welcome."}, {"equals": "he", "category": "grammar", "feedback": "He veut dire « il ». Tom parle directement à Anna : on dit You are welcome."}, {"equals": "she", "category": "grammar", "feedback": "She veut dire « elle ». Tom ne parle pas d''Anna, il lui parle : You are welcome."}], "pool": "lesson", "lessonId": "en.l01", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l01.e05', 'en', 'en.l01', 'en.g01.subject_pronouns', array['en.g01.subject_pronouns']::text[], 'fill_blank', 'lesson', 'Anna and I? ___ are in London.', array['We']::text[], 'Anna and I veut dire « Anna et moi » : c''est un groupe dont tu fais partie. En anglais, on le remplace par we (nous).', 2, '{"id": "en.l01.e05", "unitIds": ["en.g01.subject_pronouns"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon pronom. « are in London » veut dire « sont à Londres » : retiens-le comme une formule toute faite pour l''instant.", "prompt": "Anna and I? ___ are in London.", "promptLanguage": "en", "options": ["We", "They", "I", "She"], "answer": "We", "acceptedAnswers": ["We"], "hint": "Anna and I = Anna et moi. Combien de personnes, et en fais-tu partie ?", "explanation": "Anna and I veut dire « Anna et moi » : c''est un groupe dont tu fais partie. En anglais, on le remplace par we (nous).", "tip": "Si tu fais partie du groupe → we ; si tu n''en fais pas partie → they.", "extraExample": {"text": "Tom and I? We are in Paris.", "translation": "Tom et moi ? Nous sommes à Paris."}, "errorPatterns": [{"equals": "they", "category": "grammar", "feedback": "They veut dire « ils / elles », sans toi. Ici, tu fais partie du groupe (Anna and I) : on dit we."}, {"equals": "i", "category": "grammar", "feedback": "I veut dire « je » : une seule personne. Anna et toi, cela fait deux personnes : we."}, {"equals": "she", "category": "grammar", "feedback": "She ne remplace qu''Anna. Anna et toi ensemble, c''est we (nous)."}], "pool": "lesson", "lessonId": "en.l01", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l01.e06', 'en', 'en.l01', 'en.g01.subject_pronouns', array['en.g01.subject_pronouns','en.v.sorry']::text[], 'reorder', 'lesson', 'Je suis désolé.', array['I am sorry.']::text[], 'En anglais, la phrase commence par le sujet (I = je), puis le verbe (am = suis), puis sorry (désolé). I garde toujours sa majuscule.', 2, '{"id": "en.l01.e06", "unitIds": ["en.g01.subject_pronouns", "en.v.sorry"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire la phrase. I am = je suis (formule toute faite pour l''instant).", "prompt": "Je suis désolé.", "promptLanguage": "fr", "tokens": ["sorry", "am", "I"], "answer": "I am sorry.", "acceptedAnswers": ["I am sorry."], "hint": "La phrase commence par le pronom « je ».", "explanation": "En anglais, la phrase commence par le sujet (I = je), puis le verbe (am = suis), puis sorry (désolé). I garde toujours sa majuscule.", "tip": "Ordre de base : sujet + verbe + le reste.", "extraExample": {"text": "I am sorry, Ben.", "translation": "Je suis désolée, Ben."}, "pool": "lesson", "lessonId": "en.l01", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l01.e07', 'en', 'en.l01', 'en.g01.subject_pronouns', array['en.g01.subject_pronouns','en.v.hello']::text[], 'translation', 'lesson', 'Bonjour, je suis Emma.', array['Hello, I am Emma.','Hi, I am Emma.','Good morning, I am Emma.','Good afternoon, I am Emma.']::text[], 'Bonjour se dit hello (ou hi, plus familier). Pour se présenter, on dit I am + prénom : I = je, am = suis.', 2, '{"id": "en.l01.e07", "unitIds": ["en.g01.subject_pronouns", "en.v.hello"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais. Indice : « je suis » = I am.", "prompt": "Bonjour, je suis Emma.", "promptLanguage": "fr", "answer": "Hello, I am Emma.", "acceptedAnswers": ["Hello, I am Emma.", "Hi, I am Emma.", "Good morning, I am Emma.", "Good afternoon, I am Emma."], "hint": "Commence par le mot pour « bonjour », puis I am.", "explanation": "Bonjour se dit hello (ou hi, plus familier). Pour se présenter, on dit I am + prénom : I = je, am = suis.", "tip": "Pour te présenter : Hello, I am + ton prénom (à l''oral : I''m).", "extraExample": {"text": "Hello, I am Sam.", "translation": "Bonjour, je suis Sam."}, "errorPatterns": [{"equals": "hello i emma", "category": "grammar", "feedback": "Il manque am : en anglais, « je suis » se dit I am. Hello, I am Emma."}, {"contains": "me am", "category": "grammar", "feedback": "Me ne peut pas être sujet : pour « je », on dit I. Hello, I am Emma."}, {"contains": "i is", "category": "conjugation", "feedback": "Avec I, on dit toujours am : I am Emma."}], "pool": "lesson", "lessonId": "en.l01", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l01.e08', 'en', 'en.l01', 'en.v.thank_you', array['en.v.thank_you','en.v.goodbye']::text[], 'translation', 'lesson', 'Merci et au revoir, Tom !', array['Thank you and goodbye, Tom!','Thanks and goodbye, Tom!','Thank you and bye, Tom!','Thanks and bye, Tom!']::text[], 'Merci se dit thank you (ou thanks, plus familier) et au revoir se dit goodbye (ou bye, plus familier). « Et » se dit and.', 2, '{"id": "en.l01.e08", "unitIds": ["en.v.thank_you", "en.v.goodbye"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Merci et au revoir, Tom !", "promptLanguage": "fr", "answer": "Thank you and goodbye, Tom!", "acceptedAnswers": ["Thank you and goodbye, Tom!", "Thanks and goodbye, Tom!", "Thank you and bye, Tom!", "Thanks and bye, Tom!"], "hint": "Merci = deux mots en anglais ; « et » = and.", "explanation": "Merci se dit thank you (ou thanks, plus familier) et au revoir se dit goodbye (ou bye, plus familier). « Et » se dit and.", "tip": "Thank you s''écrit en deux mots ; goodbye s''écrit en un seul mot.", "extraExample": {"text": "Thank you, Anna! Goodbye!", "translation": "Merci, Anna ! Au revoir !"}, "errorPatterns": [{"contains": "thank and", "category": "vocabulary", "feedback": "Merci se dit thank you (ou thanks) : n''oublie pas you après thank."}, {"contains": "thanks you", "category": "spelling", "feedback": "On dit thank you ou thanks, mais jamais thanks you."}, {"contains": "hello", "category": "word_confusion", "feedback": "Hello veut dire « bonjour ». Pour « au revoir », on dit goodbye."}], "pool": "lesson", "lessonId": "en.l01", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l01.e09', 'en', 'en.l01', 'en.g01.subject_pronouns', array['en.g01.subject_pronouns']::text[], 'free_answer', 'lesson', 'Comment dit-on « elles » en anglais ? (par exemple pour parler d''Anna et Lucy)', array['they']::text[], 'Elles se dit they, exactement comme « ils ». Au pluriel, l''anglais n''a qu''un seul pronom, pour les hommes comme pour les femmes.', 3, '{"id": "en.l01.e09", "unitIds": ["en.g01.subject_pronouns"], "type": "free_answer", "difficulty": 3, "instruction": "Écris le mot anglais, sans aide.", "prompt": "Comment dit-on « elles » en anglais ? (par exemple pour parler d''Anna et Lucy)", "promptLanguage": "fr", "answer": "they", "acceptedAnswers": ["they"], "hint": "C''est le même mot que pour « ils ».", "explanation": "Elles se dit they, exactement comme « ils ». Au pluriel, l''anglais n''a qu''un seul pronom, pour les hommes comme pour les femmes.", "tip": "Ils ou elles → they, toujours.", "extraExample": {"text": "Emma and Lucy? They are in Paris.", "translation": "Emma et Lucy ? Elles sont à Paris."}, "errorPatterns": [{"equals": "she", "category": "grammar", "feedback": "She veut dire « elle », pour une seule femme. Pour plusieurs personnes, on dit they."}, {"equals": "shes", "category": "grammar", "feedback": "On n''ajoute pas de -s à un pronom. Pour « elles », on dit they."}, {"equals": "we", "category": "vocabulary", "feedback": "We veut dire « nous ». Pour « elles », on dit they."}], "pool": "lesson", "lessonId": "en.l01", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l01.e10', 'en', 'en.l01', 'en.v.please', array['en.v.please']::text[], 'free_answer', 'lesson', 'Comment dit-on « s''il vous plaît » en anglais ?', array['please']::text[], '« S''il te plaît » et « s''il vous plaît » se disent tous les deux please, en un seul mot. On le place souvent à la fin de la demande.', 3, '{"id": "en.l01.e10", "unitIds": ["en.v.please"], "type": "free_answer", "difficulty": 3, "instruction": "Écris le mot anglais, sans aide.", "prompt": "Comment dit-on « s''il vous plaît » en anglais ?", "promptLanguage": "fr", "answer": "please", "acceptedAnswers": ["please"], "hint": "Un seul mot, qui commence par p.", "explanation": "« S''il te plaît » et « s''il vous plaît » se disent tous les deux please, en un seul mot. On le place souvent à la fin de la demande.", "tip": "Tu ou vous, c''est toujours please.", "extraExample": {"text": "Anna, please!", "translation": "Anna, s''il te plaît !"}, "errorPatterns": [{"equals": "thank you", "category": "word_confusion", "feedback": "Thank you veut dire « merci ». Pour « s''il vous plaît », on dit please."}, {"equals": "sorry", "category": "word_confusion", "feedback": "Sorry veut dire « désolé ». Pour « s''il vous plaît », on dit please."}, {"equals": "you are welcome", "category": "word_confusion", "feedback": "You are welcome veut dire « de rien » (réponse à un merci). Pour « s''il vous plaît », on dit please."}], "pool": "lesson", "lessonId": "en.l01", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l02.e01', 'en', 'en.l02', 'en.g02.articles', array['en.g02.articles','en.v.man']::text[], 'mcq', 'lesson', 'Comment dit-on « un homme » en anglais ?', array['a man']::text[], '« Un » se dit a devant un mot qui commence par un son de consonne. Man commence par le son « m », donc a man.', 1, '{"id": "en.l02.e01", "unitIds": ["en.g02.articles", "en.v.man"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « un homme » en anglais ?", "promptLanguage": "fr", "options": ["a man", "an man", "the man", "man"], "answer": "a man", "acceptedAnswers": ["a man"], "hint": "Man commence par le son « m » : une consonne.", "explanation": "« Un » se dit a devant un mot qui commence par un son de consonne. Man commence par le son « m », donc a man.", "tip": "Un / une → a (ou an devant un son de voyelle) ; le / la → the.", "extraExample": {"text": "a woman and a child", "translation": "une femme et un enfant"}, "errorPatterns": [{"equals": "an man", "category": "grammar", "feedback": "An s''utilise seulement devant un son de voyelle (an idea). Man commence par une consonne : a man."}, {"equals": "the man", "category": "grammar", "feedback": "The veut dire « le, la ». Pour « un homme », on dit a man."}, {"equals": "man", "category": "grammar", "feedback": "Il manque l''article : « un homme » se dit a man."}], "pool": "lesson", "lessonId": "en.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l02.e02', 'en', 'en.l02', 'en.g02.articles', array['en.g02.articles']::text[], 'mcq', 'lesson', 'Comment dit-on « une université » en anglais ?', array['a university']::text[], 'On choisit a ou an selon le premier son, pas selon la lettre. University se prononce « you-niversity » : il commence par un son de consonne, donc a university.', 2, '{"id": "en.l02.e02", "unitIds": ["en.g02.articles"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « une université » en anglais ?", "promptLanguage": "fr", "options": ["a university", "an university", "the university"], "answer": "a university", "acceptedAnswers": ["a university"], "hint": "Prononce le mot à voix haute : university commence par le son « you ».", "explanation": "On choisit a ou an selon le premier son, pas selon la lettre. University se prononce « you-niversity » : il commence par un son de consonne, donc a university.", "tip": "Écoute le premier son : « you » est un son de consonne, donc a.", "extraExample": {"text": "a uniform", "translation": "un uniforme"}, "errorPatterns": [{"equals": "an university", "category": "grammar", "feedback": "U s''écrit comme une voyelle, mais ici on entend « you » : c''est un son de consonne. On dit a university."}, {"equals": "the university", "category": "grammar", "feedback": "The veut dire « l'', le, la ». Pour « une université », on dit a university."}], "pool": "lesson", "lessonId": "en.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l02.e03', 'en', 'en.l02', 'en.g02.articles', array['en.g02.articles','en.v.woman','en.v.child','en.v.friend','en.v.name']::text[], 'match', 'lesson', 'Les articles avec les nouveaux mots : a woman, a child, a friend, the name, an hour', '{}'::text[], 'A et an veulent dire « un, une » ; the veut dire « le, la ». Friend s''utilise pour un ami comme pour une amie. On dit an hour car le h de hour ne se prononce pas.', 1, '{"id": "en.l02.e03", "unitIds": ["en.g02.articles", "en.v.woman", "en.v.child", "en.v.friend", "en.v.name"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les articles avec les nouveaux mots : a woman, a child, a friend, the name, an hour", "promptLanguage": "fr", "pairs": [{"left": "a woman", "right": "une femme"}, {"left": "a child", "right": "un enfant"}, {"left": "a friend", "right": "un ami / une amie"}, {"left": "the name", "right": "le nom"}, {"left": "an hour", "right": "une heure"}], "answer": "a woman = une femme ; a child = un enfant ; a friend = un ami / une amie ; the name = le nom ; an hour = une heure", "acceptedAnswers": [], "explanation": "A et an veulent dire « un, une » ; the veut dire « le, la ». Friend s''utilise pour un ami comme pour une amie. On dit an hour car le h de hour ne se prononce pas.", "tip": "L''article anglais ne change pas selon le genre : a friend = un ami ou une amie.", "extraExample": {"text": "a man and the child", "translation": "un homme et l''enfant"}, "pool": "lesson", "lessonId": "en.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l02.e04', 'en', 'en.l02', 'en.g02.articles', array['en.g02.articles']::text[], 'fill_blank', 'lesson', '___ hour (une heure)', array['an']::text[], 'Le h de hour est muet : on entend « aour », un son de voyelle. Devant un son de voyelle, « une » se dit an : an hour.', 2, '{"id": "en.l02.e04", "unitIds": ["en.g02.articles"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec l''article qui correspond à la traduction entre parenthèses.", "prompt": "___ hour (une heure)", "promptLanguage": "en", "options": ["a", "an", "the"], "answer": "an", "acceptedAnswers": ["an"], "hint": "Le h de hour ne se prononce pas.", "explanation": "Le h de hour est muet : on entend « aour », un son de voyelle. Devant un son de voyelle, « une » se dit an : an hour.", "tip": "Devant un h muet (hour), on dit an ; devant un h prononcé (hotel), on dit a.", "extraExample": {"text": "an idea", "translation": "une idée"}, "errorPatterns": [{"equals": "a", "category": "grammar", "feedback": "Hour s''écrit avec un h, mais il ne se prononce pas : le mot commence par un son de voyelle. On dit an hour."}, {"equals": "the", "category": "grammar", "feedback": "The veut dire « l'', le, la ». Pour « une heure », on dit an hour."}], "pool": "lesson", "lessonId": "en.l02", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l02.e05', 'en', 'en.l02', 'en.g02.articles', array['en.g02.articles','en.v.name']::text[], 'fill_blank', 'lesson', '___ name (le nom)', array['the']::text[], 'Le, la, l'' et les se disent tous the en anglais. The ne change jamais, quel que soit le genre ou le nombre : the name, the woman, the children.', 2, '{"id": "en.l02.e05", "unitIds": ["en.g02.articles", "en.v.name"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec l''article qui correspond à la traduction entre parenthèses.", "prompt": "___ name (le nom)", "promptLanguage": "en", "options": ["a", "an", "the"], "answer": "the", "acceptedAnswers": ["the"], "hint": "Ici, on traduit « le », pas « un ».", "explanation": "Le, la, l'' et les se disent tous the en anglais. The ne change jamais, quel que soit le genre ou le nombre : the name, the woman, the children.", "tip": "Un seul mot pour le, la, l'' et les : the.", "extraExample": {"text": "the man and the woman", "translation": "l''homme et la femme"}, "errorPatterns": [{"equals": "a", "category": "grammar", "feedback": "A veut dire « un, une ». Pour « le nom », on dit the name."}, {"equals": "an", "category": "grammar", "feedback": "An veut dire « un, une » devant un son de voyelle. Pour « le », on dit the."}], "pool": "lesson", "lessonId": "en.l02", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l02.e06', 'en', 'en.l02', 'en.g02.articles', array['en.g02.articles','en.v.child']::text[], 'reorder', 'lesson', 'un enfant et un animal', array['a child and an animal','an animal and a child']::text[], 'Child commence par un son de consonne : a child. Animal commence par un son de voyelle : an animal. And veut dire « et ».', 2, '{"id": "en.l02.e06", "unitIds": ["en.g02.articles", "en.v.child"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "un enfant et un animal", "promptLanguage": "fr", "tokens": ["animal", "a", "and", "child", "an"], "answer": "a child and an animal", "acceptedAnswers": ["a child and an animal", "an animal and a child"], "hint": "Place an devant le mot qui commence par une voyelle.", "explanation": "Child commence par un son de consonne : a child. Animal commence par un son de voyelle : an animal. And veut dire « et ».", "tip": "Regarde le mot qui suit l''article : son de voyelle → an, son de consonne → a.", "extraExample": {"text": "a man and an idea", "translation": "un homme et une idée"}, "pool": "lesson", "lessonId": "en.l02", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l02.e07', 'en', 'en.l02', 'en.g02.articles', array['en.g02.articles','en.v.man','en.v.woman']::text[], 'translation', 'lesson', 'un homme et une femme', array['a man and a woman','a man and woman','one man and one woman']::text[], 'Un et une se disent tous les deux a devant un son de consonne : a man, a woman. L''article anglais ne change pas selon le genre.', 2, '{"id": "en.l02.e07", "unitIds": ["en.g02.articles", "en.v.man", "en.v.woman"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais. « et » = and.", "prompt": "un homme et une femme", "promptLanguage": "fr", "answer": "a man and a woman", "acceptedAnswers": ["a man and a woman", "a man and woman", "one man and one woman"], "hint": "Man et woman commencent tous les deux par un son de consonne.", "explanation": "Un et une se disent tous les deux a devant un son de consonne : a man, a woman. L''article anglais ne change pas selon le genre.", "tip": "Pas de masculin ni de féminin pour a : a man, a woman.", "extraExample": {"text": "a friend and a child", "translation": "une amie et un enfant"}, "errorPatterns": [{"contains": "an man", "category": "grammar", "feedback": "Man commence par un son de consonne : on dit a man, pas an man."}, {"contains": "an woman", "category": "grammar", "feedback": "Woman commence par le son « w », une consonne : on dit a woman."}, {"equals": "the man and the woman", "category": "grammar", "feedback": "The veut dire « l'', le, la ». Pour « un homme et une femme », on dit a man and a woman."}], "pool": "lesson", "lessonId": "en.l02", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l02.e08', 'en', 'en.l02', 'en.g02.articles', array['en.g02.articles','en.v.woman','en.v.child']::text[], 'translation', 'lesson', 'la femme et l''enfant', array['the woman and the child','the woman and child','the woman and the kid']::text[], 'La, le et l'' se disent tous the : the woman, the child. On utilise the parce qu''on parle d''une femme et d''un enfant précis.', 3, '{"id": "en.l02.e08", "unitIds": ["en.g02.articles", "en.v.woman", "en.v.child"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais. « et » = and.", "prompt": "la femme et l''enfant", "promptLanguage": "fr", "answer": "the woman and the child", "acceptedAnswers": ["the woman and the child", "the woman and child", "the woman and the kid"], "hint": "La et l'' se traduisent par le même mot.", "explanation": "La, le et l'' se disent tous the : the woman, the child. On utilise the parce qu''on parle d''une femme et d''un enfant précis.", "tip": "L'' devant une voyelle en français ? En anglais, c''est toujours the.", "extraExample": {"text": "the man and the friend", "translation": "l''homme et l''ami"}, "errorPatterns": [{"equals": "a woman and a child", "category": "grammar", "feedback": "A veut dire « un, une ». Pour « la femme et l''enfant », on dit the woman and the child."}, {"contains": "the women", "category": "spelling", "feedback": "Women est le pluriel (les femmes). Pour « la femme », on écrit the woman, avec un a."}, {"contains": "l child", "category": "grammar", "feedback": "L''anglais n''a pas d''article l''. Pour « l''enfant », on dit the child."}], "pool": "lesson", "lessonId": "en.l02", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l02.e09', 'en', 'en.l02', 'en.g02.articles', array['en.g02.articles']::text[], 'free_answer', 'lesson', 'Comment dit-on « une idée » en anglais ?', array['an idea']::text[], 'Idea commence par un son de voyelle (« aï »). Devant un son de voyelle, « un, une » se dit an : an idea.', 3, '{"id": "en.l02.e09", "unitIds": ["en.g02.articles"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais, avec a ou an.", "prompt": "Comment dit-on « une idée » en anglais ?", "promptLanguage": "fr", "answer": "an idea", "acceptedAnswers": ["an idea"], "hint": "Idée se dit idea : il commence par une voyelle.", "explanation": "Idea commence par un son de voyelle (« aï »). Devant un son de voyelle, « un, une » se dit an : an idea.", "tip": "An évite de buter entre deux voyelles : an idea se dit plus facilement que « a idea ».", "extraExample": {"text": "an animal", "translation": "un animal"}, "errorPatterns": [{"equals": "a idea", "category": "grammar", "feedback": "Idea commence par un son de voyelle : on dit an idea, pas a idea."}, {"equals": "one idea", "category": "instruction", "feedback": "One veut dire « un seul » (le chiffre 1). La consigne demande l''article : an idea."}, {"contains": "idee", "category": "vocabulary", "feedback": "En anglais, « idée » s''écrit idea : an idea."}], "pool": "lesson", "lessonId": "en.l02", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l02.e10', 'en', 'en.l02', 'en.g02.articles', array['en.g02.articles','en.v.friend']::text[], 'free_answer', 'lesson', 'Comment dit-on « une amie » en anglais ?', array['a friend','a female friend']::text[], 'Friend veut dire « ami » ou « amie » : il ne change pas selon le genre. Il commence par un son de consonne, donc a friend.', 3, '{"id": "en.l02.e10", "unitIds": ["en.g02.articles", "en.v.friend"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais, avec l''article qui convient (a, an ou the).", "prompt": "Comment dit-on « une amie » en anglais ?", "promptLanguage": "fr", "answer": "a friend", "acceptedAnswers": ["a friend", "a female friend"], "hint": "Le mot anglais est le même pour un ami et une amie.", "explanation": "Friend veut dire « ami » ou « amie » : il ne change pas selon le genre. Il commence par un son de consonne, donc a friend.", "tip": "Un ami ou une amie : c''est toujours a friend.", "extraExample": {"text": "Anna and a friend", "translation": "Anna et une amie"}, "errorPatterns": [{"equals": "an friend", "category": "grammar", "feedback": "Friend commence par un son de consonne : on dit a friend."}, {"equals": "a girlfriend", "category": "word_confusion", "feedback": "Girlfriend veut dire « petite amie » (en couple). Pour « une amie », on dit simplement a friend."}, {"equals": "one friend", "category": "instruction", "feedback": "One veut dire « un seul ». La consigne demande l''article : a friend."}], "pool": "lesson", "lessonId": "en.l02", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l03.e01', 'en', 'en.l03', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.tired','en.g01.subject_pronouns']::text[], 'mcq', 'lesson', 'Comment dit-on « Je suis fatigué » en anglais ?', array['I am tired']::text[], '« Je suis » se dit I am. En anglais, on ne peut pas supprimer le verbe : on écrit toujours I am tired, jamais I tired.', 1, '{"id": "en.l03.e01", "unitIds": ["en.g03.be_affirmative", "en.v.tired", "en.g01.subject_pronouns"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Je suis fatigué » en anglais ?", "promptLanguage": "fr", "options": ["I am tired", "I is tired", "I are tired", "I tired"], "answer": "I am tired", "acceptedAnswers": ["I am tired"], "hint": "Avec I, le verbe être se dit am.", "explanation": "« Je suis » se dit I am. En anglais, on ne peut pas supprimer le verbe : on écrit toujours I am tired, jamais I tired.", "tip": "I va toujours avec am : I am.", "extraExample": {"text": "I am ready.", "translation": "Je suis prêt."}, "errorPatterns": [{"equals": "i is tired", "category": "conjugation", "feedback": "Is va avec he, she et it. Avec I, on dit am : I am tired."}, {"equals": "i are tired", "category": "conjugation", "feedback": "Are va avec you, we et they. Avec I, on dit am : I am tired."}, {"equals": "i tired", "category": "grammar", "feedback": "Il manque le verbe être. En anglais, la phrase a toujours un verbe : I am tired."}], "pool": "lesson", "lessonId": "en.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l03.e02', 'en', 'en.l03', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.happy','en.g01.subject_pronouns']::text[], 'mcq', 'lesson', 'Tom and Anna ___ happy.', array['are']::text[], 'Tom and Anna, c''est « ils » : they. Avec they, le verbe être se dit are : Tom and Anna are happy.', 2, '{"id": "en.l03.e02", "unitIds": ["en.g03.be_affirmative", "en.v.happy", "en.g01.subject_pronouns"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme du verbe être.", "prompt": "Tom and Anna ___ happy.", "promptLanguage": "en", "options": ["are", "is", "am"], "answer": "are", "acceptedAnswers": ["are"], "hint": "Tom and Anna, c''est deux personnes : tu peux les remplacer par un seul pronom.", "explanation": "Tom and Anna, c''est « ils » : they. Avec they, le verbe être se dit are : Tom and Anna are happy.", "tip": "Deux personnes ou plus (Tom and Anna) = they = are.", "extraExample": {"text": "The man and the woman are ready.", "translation": "L''homme et la femme sont prêts."}, "errorPatterns": [{"equals": "is", "category": "conjugation", "feedback": "Is s''emploie pour une seule personne (he, she). Tom and Anna font deux personnes : they are."}, {"equals": "am", "category": "conjugation", "feedback": "Am s''emploie seulement avec I. Pour Tom and Anna (they), on dit are."}], "pool": "lesson", "lessonId": "en.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l03.e03', 'en', 'en.l03', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.happy','en.v.tired','en.v.ready','en.v.student','en.v.teacher']::text[], 'match', 'lesson', 'To be et les nouveaux mots : happy, tired, ready, student, teacher', '{}'::text[], 'Chaque pronom a sa forme de to be : I am, you are, he / she is, we are. Avec un métier ou un statut (student, teacher), l''anglais ajoute a : he is a student.', 1, '{"id": "en.l03.e03", "unitIds": ["en.g03.be_affirmative", "en.v.happy", "en.v.tired", "en.v.ready", "en.v.student", "en.v.teacher"], "type": "match", "difficulty": 1, "instruction": "Associe chaque phrase anglaise à sa traduction.", "prompt": "To be et les nouveaux mots : happy, tired, ready, student, teacher", "promptLanguage": "fr", "pairs": [{"left": "I am happy", "right": "je suis content"}, {"left": "you are tired", "right": "tu es fatigué"}, {"left": "he is a student", "right": "il est étudiant"}, {"left": "she is a teacher", "right": "elle est professeur"}, {"left": "we are ready", "right": "nous sommes prêts"}], "answer": "I am happy = je suis content ; you are tired = tu es fatigué ; he is a student = il est étudiant ; she is a teacher = elle est professeur ; we are ready = nous sommes prêts", "acceptedAnswers": [], "explanation": "Chaque pronom a sa forme de to be : I am, you are, he / she is, we are. Avec un métier ou un statut (student, teacher), l''anglais ajoute a : he is a student.", "tip": "En français on dit « il est étudiant » ; en anglais, he is a student.", "extraExample": {"text": "She is happy.", "translation": "Elle est heureuse."}, "pool": "lesson", "lessonId": "en.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l03.e04', 'en', 'en.l03', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.ready','en.g01.subject_pronouns']::text[], 'fill_blank', 'lesson', 'You ___ ready.', array['are']::text[], 'Avec you, le verbe être se dit are : you are ready. You veut dire « tu » comme « vous », et la forme est toujours are.', 1, '{"id": "en.l03.e04", "unitIds": ["en.g03.be_affirmative", "en.v.ready", "en.g01.subject_pronouns"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète avec la bonne forme du verbe être.", "prompt": "You ___ ready.", "promptLanguage": "en", "options": ["are", "is", "am"], "answer": "are", "acceptedAnswers": ["are"], "hint": "Le pronom est you.", "explanation": "Avec you, le verbe être se dit are : you are ready. You veut dire « tu » comme « vous », et la forme est toujours are.", "tip": "You = are, que ce soit « tu » ou « vous ».", "extraExample": {"text": "You are a friend and a teacher.", "translation": "Tu es un ami et un professeur."}, "errorPatterns": [{"equals": "is", "category": "conjugation", "feedback": "Is va avec he, she ou it. Avec you, on dit are : you are ready."}, {"equals": "am", "category": "conjugation", "feedback": "Am va uniquement avec I. Avec you, on dit are : you are ready."}], "pool": "lesson", "lessonId": "en.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l03.e05', 'en', 'en.l03', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.teacher','en.g01.subject_pronouns']::text[], 'fill_blank', 'lesson', 'She ___ a teacher.', array['is']::text[], 'Avec he, she et it, le verbe être se dit is : she is a teacher.', 1, '{"id": "en.l03.e05", "unitIds": ["en.g03.be_affirmative", "en.v.teacher", "en.g01.subject_pronouns"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète avec la bonne forme du verbe être.", "prompt": "She ___ a teacher.", "promptLanguage": "en", "options": ["is", "are", "am"], "answer": "is", "acceptedAnswers": ["is"], "hint": "Le pronom est she : une seule personne.", "explanation": "Avec he, she et it, le verbe être se dit is : she is a teacher.", "tip": "He, she, it : on pense à is.", "extraExample": {"text": "He is a teacher.", "translation": "Il est professeur."}, "errorPatterns": [{"equals": "are", "category": "conjugation", "feedback": "Are va avec you, we et they. Avec she, on dit is : she is a teacher."}, {"equals": "am", "category": "conjugation", "feedback": "Am va uniquement avec I. Avec she, on dit is : she is a teacher."}], "pool": "lesson", "lessonId": "en.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l03.e06', 'en', 'en.l03', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.teacher','en.v.woman']::text[], 'reorder', 'lesson', 'La femme est professeur.', array['The woman is a teacher']::text[], 'On met d''abord le sujet (The woman), puis le verbe is, puis a teacher. Avec un métier, l''anglais garde l''article a.', 2, '{"id": "en.l03.e06", "unitIds": ["en.g03.be_affirmative", "en.v.teacher", "en.v.woman"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former une phrase.", "prompt": "La femme est professeur.", "promptLanguage": "fr", "tokens": ["teacher", "The", "a", "is", "woman"], "answer": "The woman is a teacher", "acceptedAnswers": ["The woman is a teacher"], "hint": "L''ordre est : sujet, verbe être, puis a + métier.", "explanation": "On met d''abord le sujet (The woman), puis le verbe is, puis a teacher. Avec un métier, l''anglais garde l''article a.", "tip": "Sujet + verbe être + a + métier.", "extraExample": {"text": "The man is a student.", "translation": "L''homme est étudiant."}, "pool": "lesson", "lessonId": "en.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l03.e07', 'en', 'en.l03', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.student','en.g02.articles']::text[], 'translation', 'lesson', 'Je suis étudiant.', array['I am a student','I am a pupil']::text[], '« Je suis » se dit I am. Contrairement au français, l''anglais ajoute a devant un métier ou un statut : I am a student.', 2, '{"id": "en.l03.e07", "unitIds": ["en.g03.be_affirmative", "en.v.student", "en.g02.articles"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Je suis étudiant.", "promptLanguage": "fr", "answer": "I am a student", "acceptedAnswers": ["I am a student", "I am a pupil"], "hint": "N''oublie pas l''article a devant le mot student.", "explanation": "« Je suis » se dit I am. Contrairement au français, l''anglais ajoute a devant un métier ou un statut : I am a student.", "tip": "Français : « je suis étudiant ». Anglais : I am a student, avec a.", "extraExample": {"text": "I am a teacher.", "translation": "Je suis professeur."}, "errorPatterns": [{"contains": "am student", "category": "grammar", "feedback": "Il manque l''article. Devant un métier ou un statut, l''anglais met a : I am a student."}, {"contains": "i is", "category": "conjugation", "feedback": "Avec I, le verbe être se dit am : I am a student."}, {"contains": "i are", "category": "conjugation", "feedback": "Avec I, le verbe être se dit am : I am a student."}], "pool": "lesson", "lessonId": "en.l03", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l03.e08', 'en', 'en.l03', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.teacher','en.v.student','en.g01.subject_pronouns']::text[], 'translation', 'lesson', 'Elle est professeur et il est étudiant.', array['She is a teacher and he is a student','She is a teacher and he is a pupil']::text[], 'Elle = she et il = he : les deux prennent is. On répète le verbe pour chaque personne et on garde a devant teacher et student.', 3, '{"id": "en.l03.e08", "unitIds": ["en.g03.be_affirmative", "en.v.teacher", "en.v.student", "en.g01.subject_pronouns"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais. « et » = and.", "prompt": "Elle est professeur et il est étudiant.", "promptLanguage": "fr", "answer": "She is a teacher and he is a student", "acceptedAnswers": ["She is a teacher and he is a student", "She is a teacher and he is a pupil"], "hint": "Il y a deux verbes être : un avec she, un avec he.", "explanation": "Elle = she et il = he : les deux prennent is. On répète le verbe pour chaque personne et on garde a devant teacher et student.", "tip": "Une personne (he, she) : is. Et on n''oublie pas a devant le métier.", "extraExample": {"text": "He is a teacher and she is a friend.", "translation": "Il est professeur et elle est une amie."}, "errorPatterns": [{"contains": "is teacher", "category": "grammar", "feedback": "Il manque l''article. Devant un métier, l''anglais met a : she is a teacher."}, {"contains": "is student", "category": "grammar", "feedback": "Il manque l''article. Devant un statut, l''anglais met a : he is a student."}, {"contains": "she are", "category": "conjugation", "feedback": "Are va avec you, we et they. Avec she, on dit is."}], "pool": "lesson", "lessonId": "en.l03", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l03.e09', 'en', 'en.l03', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.happy','en.g01.subject_pronouns']::text[], 'free_answer', 'lesson', 'Comment dit-on « Ils sont heureux » en anglais ?', array['They are happy']::text[], 'Ils (ou elles) se dit they. Avec they, le verbe être se dit are : they are happy.', 2, '{"id": "en.l03.e09", "unitIds": ["en.g03.be_affirmative", "en.v.happy", "en.g01.subject_pronouns"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Ils sont heureux » en anglais ?", "promptLanguage": "fr", "answer": "They are happy", "acceptedAnswers": ["They are happy"], "hint": "Ils se dit they : le verbe être est are.", "explanation": "Ils (ou elles) se dit they. Avec they, le verbe être se dit are : they are happy.", "tip": "Plusieurs personnes : they are.", "extraExample": {"text": "We are happy.", "translation": "Nous sommes heureux."}, "errorPatterns": [{"equals": "they is happy", "category": "conjugation", "feedback": "Is s''emploie pour une seule personne. Avec they, on dit are : they are happy."}, {"equals": "they happy", "category": "grammar", "feedback": "Il manque le verbe être. En anglais, on dit they are happy."}, {"contains": "there are", "category": "word_confusion", "feedback": "There et they ne sont pas le même mot. « Ils » se dit they."}], "pool": "lesson", "lessonId": "en.l03", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l03.e10', 'en', 'en.l03', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.teacher','en.g02.articles']::text[], 'free_answer', 'lesson', 'Comment dit-on « Tu es professeur » en anglais ?', array['You are a teacher']::text[], '« Tu » se dit you et le verbe est are : you are. Devant un métier, l''anglais ajoute a : you are a teacher.', 3, '{"id": "en.l03.e10", "unitIds": ["en.g03.be_affirmative", "en.v.teacher", "en.g02.articles"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais. Tu parles à une seule personne.", "prompt": "Comment dit-on « Tu es professeur » en anglais ?", "promptLanguage": "fr", "answer": "You are a teacher", "acceptedAnswers": ["You are a teacher"], "hint": "Ne confonds pas le verbe avec am. Et n''oublie pas a.", "explanation": "« Tu » se dit you et le verbe est are : you are. Devant un métier, l''anglais ajoute a : you are a teacher.", "tip": "You are + a + métier.", "extraExample": {"text": "You are a student.", "translation": "Tu es étudiant."}, "errorPatterns": [{"contains": "are teacher", "category": "grammar", "feedback": "Il manque l''article. Devant un métier, l''anglais met a : you are a teacher."}, {"contains": "you is", "category": "conjugation", "feedback": "Avec you, le verbe être se dit are, pas is."}, {"contains": "you am", "category": "conjugation", "feedback": "Am va uniquement avec I. Avec you, on dit are."}], "pool": "lesson", "lessonId": "en.l03", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l04.e01', 'en', 'en.l04', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.brother','en.v.friend']::text[], 'mcq', 'lesson', 'Tom ___ a brother and a friend.', array['is']::text[], 'Tom, c''est « il » : he. Avec he, she et it, le verbe être se dit is : Tom is a brother and a friend.', 1, '{"id": "en.l04.e01", "unitIds": ["en.g03.be_affirmative", "en.v.brother", "en.v.friend"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme du verbe être.", "prompt": "Tom ___ a brother and a friend.", "promptLanguage": "en", "options": ["is", "are", "am"], "answer": "is", "acceptedAnswers": ["is"], "hint": "Tom, c''est une seule personne : tu peux le remplacer par he.", "explanation": "Tom, c''est « il » : he. Avec he, she et it, le verbe être se dit is : Tom is a brother and a friend.", "tip": "Un prénom = une personne = is.", "extraExample": {"text": "Anna is a sister and a student.", "translation": "Anna est sœur et étudiante."}, "errorPatterns": [{"equals": "are", "category": "conjugation", "feedback": "Are va avec you, we et they. Tom est une seule personne (he) : on dit is."}, {"equals": "am", "category": "conjugation", "feedback": "Am va uniquement avec I. Pour Tom (he), on dit is."}], "pool": "lesson", "lessonId": "en.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l04.e02', 'en', 'en.l04', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.family','en.g01.subject_pronouns']::text[], 'mcq', 'lesson', 'Comment dit-on « Nous sommes une famille » en anglais ?', array['We are a family']::text[], '« Nous » se dit we et le verbe être est are : we are. Devant family, on garde a : we are a family.', 2, '{"id": "en.l04.e02", "unitIds": ["en.g03.be_affirmative", "en.v.family", "en.g01.subject_pronouns"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Nous sommes une famille » en anglais ?", "promptLanguage": "fr", "options": ["We are a family", "We is a family", "We am a family", "We a family"], "answer": "We are a family", "acceptedAnswers": ["We are a family"], "hint": "Avec we, le verbe être se dit are.", "explanation": "« Nous » se dit we et le verbe être est are : we are. Devant family, on garde a : we are a family.", "tip": "We, you, they : toujours are.", "extraExample": {"text": "They are a family.", "translation": "Ils sont une famille."}, "errorPatterns": [{"equals": "we is a family", "category": "conjugation", "feedback": "Is va avec he, she et it. Avec we, on dit are : we are a family."}, {"equals": "we am a family", "category": "conjugation", "feedback": "Am va uniquement avec I. Avec we, on dit are : we are a family."}, {"equals": "we a family", "category": "grammar", "feedback": "Il manque le verbe être. En anglais, on dit we are a family."}], "pool": "lesson", "lessonId": "en.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l04.e03', 'en', 'en.l04', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.mother','en.v.father','en.v.brother','en.v.sister','en.v.family']::text[], 'match', 'lesson', 'Les mots de la famille : mother, father, brother, sister, family', '{}'::text[], 'Mother, father, brother, sister et family sont des noms : ils s''utilisent avec a ou the, comme man ou woman. Attention à la prononciation de mother, father et brother : le th se prononce « d » doux.', 1, '{"id": "en.l04.e03", "unitIds": ["en.g03.be_affirmative", "en.v.mother", "en.v.father", "en.v.brother", "en.v.sister", "en.v.family"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les mots de la famille : mother, father, brother, sister, family", "promptLanguage": "fr", "pairs": [{"left": "a mother", "right": "une mère"}, {"left": "a father", "right": "un père"}, {"left": "a brother", "right": "un frère"}, {"left": "a sister", "right": "une sœur"}, {"left": "a family", "right": "une famille"}], "answer": "a mother = une mère ; a father = un père ; a brother = un frère ; a sister = une sœur ; a family = une famille", "acceptedAnswers": [], "explanation": "Mother, father, brother, sister et family sont des noms : ils s''utilisent avec a ou the, comme man ou woman. Attention à la prononciation de mother, father et brother : le th se prononce « d » doux.", "tip": "Un mot de famille se met avec a ou the : a mother, the father.", "extraExample": {"text": "He is a father.", "translation": "Il est père."}, "pool": "lesson", "lessonId": "en.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l04.e04', 'en', 'en.l04', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.father','en.g02.articles']::text[], 'fill_blank', 'lesson', 'Sam is a ___. (Sam est père.)', array['father']::text[], 'Père se dit father. Mother veut dire « mère » et sister « sœur » : ces mots ne vont pas avec Sam, qui est un homme.', 1, '{"id": "en.l04.e04", "unitIds": ["en.g03.be_affirmative", "en.v.father", "en.g02.articles"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète avec le bon mot de la famille.", "prompt": "Sam is a ___. (Sam est père.)", "promptLanguage": "en", "options": ["father", "mother", "sister"], "answer": "father", "acceptedAnswers": ["father"], "hint": "Père se dit father, avec th.", "explanation": "Père se dit father. Mother veut dire « mère » et sister « sœur » : ces mots ne vont pas avec Sam, qui est un homme.", "tip": "F comme father (père), M comme mother (mère).", "extraExample": {"text": "Ben is a father and a teacher.", "translation": "Ben est père et professeur."}, "errorPatterns": [{"equals": "mother", "category": "vocabulary", "feedback": "Mother veut dire « mère ». Pour « père », on dit father."}, {"equals": "sister", "category": "vocabulary", "feedback": "Sister veut dire « sœur ». Pour « père », on dit father."}], "pool": "lesson", "lessonId": "en.l04", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l04.e05', 'en', 'en.l04', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.mother','en.v.father','en.v.happy']::text[], 'fill_blank', 'lesson', 'The mother and the father ___ happy.', array['are']::text[], 'La mère et le père, c''est « ils » : they. Avec they, le verbe être se dit are : the mother and the father are happy.', 2, '{"id": "en.l04.e05", "unitIds": ["en.g03.be_affirmative", "en.v.mother", "en.v.father", "en.v.happy"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme du verbe être.", "prompt": "The mother and the father ___ happy.", "promptLanguage": "en", "options": ["are", "is", "am"], "answer": "are", "acceptedAnswers": ["are"], "hint": "The mother and the father, c''est deux personnes : they.", "explanation": "La mère et le père, c''est « ils » : they. Avec they, le verbe être se dit are : the mother and the father are happy.", "tip": "Deux sujets reliés par and = they = are.", "extraExample": {"text": "The teacher and the student are ready.", "translation": "Le professeur et l''étudiant sont prêts."}, "errorPatterns": [{"equals": "is", "category": "conjugation", "feedback": "Is s''emploie pour une seule personne. Ici il y a deux personnes (la mère et le père) : on dit are."}, {"equals": "am", "category": "conjugation", "feedback": "Am va uniquement avec I. Pour deux personnes (they), on dit are."}], "pool": "lesson", "lessonId": "en.l04", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l04.e06', 'en', 'en.l04', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.sister','en.v.friend']::text[], 'reorder', 'lesson', 'Anna est une sœur et une amie.', array['Anna is a sister and a friend','Anna is a friend and a sister']::text[], 'On met le sujet (Anna), puis is, puis les deux noms reliés par and. Chaque nom garde son article a.', 2, '{"id": "en.l04.e06", "unitIds": ["en.g03.be_affirmative", "en.v.sister", "en.v.friend"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former une phrase.", "prompt": "Anna est une sœur et une amie.", "promptLanguage": "fr", "tokens": ["friend", "a", "Anna", "sister", "and", "is", "a"], "answer": "Anna is a sister and a friend", "acceptedAnswers": ["Anna is a sister and a friend", "Anna is a friend and a sister"], "hint": "Commence par le sujet, puis le verbe être.", "explanation": "On met le sujet (Anna), puis is, puis les deux noms reliés par and. Chaque nom garde son article a.", "tip": "Sujet + is + a + nom + and + a + nom.", "extraExample": {"text": "Tom is a brother and a friend.", "translation": "Tom est un frère et un ami."}, "pool": "lesson", "lessonId": "en.l04", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l04.e07', 'en', 'en.l04', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.mother','en.v.teacher','en.g02.articles']::text[], 'translation', 'lesson', 'Elle est mère et professeur.', array['She is a mother and a teacher','She is a mother and teacher','She is a mum and a teacher','She is a mom and a teacher']::text[], 'Elle = she, donc le verbe est is. En français on dit « mère et professeur » sans article ; en anglais, on met a devant chaque nom : a mother and a teacher.', 2, '{"id": "en.l04.e07", "unitIds": ["en.g03.be_affirmative", "en.v.mother", "en.v.teacher", "en.g02.articles"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais. « et » = and.", "prompt": "Elle est mère et professeur.", "promptLanguage": "fr", "answer": "She is a mother and a teacher", "acceptedAnswers": ["She is a mother and a teacher", "She is a mother and teacher", "She is a mum and a teacher", "She is a mom and a teacher"], "hint": "Elle se dit she. N''oublie pas a devant chaque nom.", "explanation": "Elle = she, donc le verbe est is. En français on dit « mère et professeur » sans article ; en anglais, on met a devant chaque nom : a mother and a teacher.", "tip": "Un métier ou un rôle (mother, teacher) : a devant le nom.", "extraExample": {"text": "He is a father and a student.", "translation": "Il est père et étudiant."}, "errorPatterns": [{"contains": "is mother", "category": "grammar", "feedback": "Il manque l''article. Devant un rôle comme mother, l''anglais met a : she is a mother."}, {"contains": "she are", "category": "conjugation", "feedback": "Are va avec you, we et they. Avec she, on dit is."}, {"contains": "she am", "category": "conjugation", "feedback": "Am va uniquement avec I. Avec she, on dit is."}], "pool": "lesson", "lessonId": "en.l04", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l04.e08', 'en', 'en.l04', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.father','en.v.mother','en.v.tired','en.v.happy']::text[], 'translation', 'lesson', 'Le père est fatigué et la mère est heureuse.', array['The father is tired and the mother is happy']::text[], 'Le père et la mère sont chacun une seule personne (he, she) : le verbe est is les deux fois. Le et la se disent tous les deux the.', 3, '{"id": "en.l04.e08", "unitIds": ["en.g03.be_affirmative", "en.v.father", "en.v.mother", "en.v.tired", "en.v.happy"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais. « et » = and.", "prompt": "Le père est fatigué et la mère est heureuse.", "promptLanguage": "fr", "answer": "The father is tired and the mother is happy", "acceptedAnswers": ["The father is tired and the mother is happy"], "hint": "Le et la se traduisent par le même mot. Il y a deux verbes être.", "explanation": "Le père et la mère sont chacun une seule personne (he, she) : le verbe est is les deux fois. Le et la se disent tous les deux the.", "tip": "Le, la, l'', les : toujours the. Une personne : is.", "extraExample": {"text": "The teacher is ready and the student is tired.", "translation": "Le professeur est prêt et l''étudiant est fatigué."}, "errorPatterns": [{"contains": "father are", "category": "conjugation", "feedback": "Le père est une seule personne : on dit is, pas are."}, {"contains": "mother are", "category": "conjugation", "feedback": "La mère est une seule personne : on dit is, pas are."}], "pool": "lesson", "lessonId": "en.l04", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l04.e09', 'en', 'en.l04', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.family','en.v.happy']::text[], 'free_answer', 'lesson', 'Comment dit-on « Nous sommes une famille heureuse » en anglais ?', array['We are a happy family']::text[], '« Nous sommes » se dit we are. L''adjectif happy se place avant le nom : a happy family, et non « a family happy ».', 3, '{"id": "en.l04.e09", "unitIds": ["en.g03.be_affirmative", "en.v.family", "en.v.happy"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Nous sommes une famille heureuse » en anglais ?", "promptLanguage": "fr", "answer": "We are a happy family", "acceptedAnswers": ["We are a happy family"], "hint": "En anglais, l''adjectif se place avant le nom.", "explanation": "« Nous sommes » se dit we are. L''adjectif happy se place avant le nom : a happy family, et non « a family happy ».", "tip": "En anglais, l''adjectif vient devant le nom : a happy family.", "extraExample": {"text": "She is a happy mother.", "translation": "C''est une mère heureuse."}, "errorPatterns": [{"contains": "family happy", "category": "word_order", "feedback": "En anglais, l''adjectif se place avant le nom : a happy family."}, {"contains": "we is", "category": "conjugation", "feedback": "Avec we, le verbe être se dit are : we are a happy family."}, {"equals": "we are happy family", "category": "grammar", "feedback": "Il manque l''article : we are a happy family."}], "pool": "lesson", "lessonId": "en.l04", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l04.e10', 'en', 'en.l04', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.sister','en.v.friend','en.g01.subject_pronouns']::text[], 'free_answer', 'lesson', 'Comment dit-on « Je suis une sœur et une amie » en anglais ?', array['I am a sister and a friend','I am a friend and a sister','I am a sister and friend']::text[], '« Je suis » se dit I am. Sister et friend sont deux noms : chacun prend a. L''article ne change pas selon le genre.', 2, '{"id": "en.l04.e10", "unitIds": ["en.g03.be_affirmative", "en.v.sister", "en.v.friend", "en.g01.subject_pronouns"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Je suis une sœur et une amie » en anglais ?", "promptLanguage": "fr", "answer": "I am a sister and a friend", "acceptedAnswers": ["I am a sister and a friend", "I am a friend and a sister", "I am a sister and friend"], "hint": "Je suis = I am. Ajoute a devant chaque nom.", "explanation": "« Je suis » se dit I am. Sister et friend sont deux noms : chacun prend a. L''article ne change pas selon le genre.", "tip": "I am + a + nom.", "extraExample": {"text": "I am a mother and a teacher.", "translation": "Je suis mère et professeur."}, "errorPatterns": [{"contains": "i is", "category": "conjugation", "feedback": "Is va avec he, she et it. Avec I, on dit am."}, {"contains": "i are", "category": "conjugation", "feedback": "Are va avec you, we et they. Avec I, on dit am."}, {"contains": "am sister", "category": "grammar", "feedback": "Il manque l''article. Devant un nom de famille, l''anglais met a : I am a sister."}], "pool": "lesson", "lessonId": "en.l04", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l05.e01', 'en', 'en.l05', 'en.g04.be_negative_questions', array['en.g04.be_negative_questions','en.v.busy','en.g03.be_affirmative']::text[], 'mcq', 'lesson', 'Comment dit-on « Je ne suis pas occupé » en anglais ?', array['I am not busy']::text[], 'Pour nier avec to be, on ajoute not après le verbe : I am not busy. Not se place toujours après am, is ou are.', 1, '{"id": "en.l05.e01", "unitIds": ["en.g04.be_negative_questions", "en.v.busy", "en.g03.be_affirmative"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Je ne suis pas occupé » en anglais ?", "promptLanguage": "fr", "options": ["I am not busy", "I not am busy", "I am no busy", "I not busy"], "answer": "I am not busy", "acceptedAnswers": ["I am not busy"], "hint": "Le mot not se place juste après le verbe être.", "explanation": "Pour nier avec to be, on ajoute not après le verbe : I am not busy. Not se place toujours après am, is ou are.", "tip": "Verbe être + not : am not, is not, are not.", "extraExample": {"text": "He is not tired.", "translation": "Il n''est pas fatigué."}, "errorPatterns": [{"equals": "i not am busy", "category": "word_order", "feedback": "Not se place après le verbe être, pas avant : I am not busy."}, {"equals": "i am no busy", "category": "grammar", "feedback": "No n''est pas le mot de la négation avec le verbe être. On utilise not : I am not busy."}, {"equals": "i not busy", "category": "grammar", "feedback": "Il manque le verbe être. En anglais : I am not busy."}], "pool": "lesson", "lessonId": "en.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l05.e02', 'en', 'en.l05', 'en.g04.be_negative_questions', array['en.g04.be_negative_questions','en.v.hungry','en.g03.be_affirmative']::text[], 'mcq', 'lesson', 'Comment dit-on « Tu as faim ? » en anglais ?', array['Are you hungry?']::text[], 'En anglais, on utilise le verbe être pour la faim : you are hungry (« tu es affamé »). Pour poser la question, on met are avant you : Are you hungry?', 2, '{"id": "en.l05.e02", "unitIds": ["en.g04.be_negative_questions", "en.v.hungry", "en.g03.be_affirmative"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Tu as faim ? » en anglais ?", "promptLanguage": "fr", "options": ["Are you hungry?", "Is you hungry?", "Am you hungry?", "Are hungry you?"], "answer": "Are you hungry?", "acceptedAnswers": ["Are you hungry?"], "hint": "En anglais, on ne « a » pas faim : on est hungry.", "explanation": "En anglais, on utilise le verbe être pour la faim : you are hungry (« tu es affamé »). Pour poser la question, on met are avant you : Are you hungry?", "tip": "Question avec to be : verbe être + sujet + le reste.", "extraExample": {"text": "Is she cold?", "translation": "A-t-elle froid ?"}, "errorPatterns": [{"equals": "is you hungry", "category": "conjugation", "feedback": "Is va avec he, she et it. Avec you, on dit are : Are you hungry?"}, {"equals": "am you hungry", "category": "conjugation", "feedback": "Am va uniquement avec I. Avec you, on dit are : Are you hungry?"}, {"equals": "are hungry you", "category": "word_order", "feedback": "L''ordre est verbe être, puis sujet, puis hungry : Are you hungry?"}], "pool": "lesson", "lessonId": "en.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l05.e03', 'en', 'en.l05', 'en.g04.be_negative_questions', array['en.g04.be_negative_questions','en.v.late','en.v.busy','en.v.hungry','en.v.cold','en.v.right']::text[], 'match', 'lesson', 'Les nouveaux mots avec to be : late, busy, hungry, cold, right', '{}'::text[], 'Attention : en français on « a » faim, froid ou raison, mais en anglais on utilise le verbe être : he is hungry, I am cold, she is right.', 1, '{"id": "en.l05.e03", "unitIds": ["en.g04.be_negative_questions", "en.v.late", "en.v.busy", "en.v.hungry", "en.v.cold", "en.v.right"], "type": "match", "difficulty": 1, "instruction": "Associe chaque phrase anglaise à sa traduction.", "prompt": "Les nouveaux mots avec to be : late, busy, hungry, cold, right", "promptLanguage": "fr", "pairs": [{"left": "I am late", "right": "je suis en retard"}, {"left": "you are busy", "right": "tu es occupé"}, {"left": "he is hungry", "right": "il a faim"}, {"left": "it is cold", "right": "il fait froid"}, {"left": "she is right", "right": "elle a raison"}], "answer": "I am late = je suis en retard ; you are busy = tu es occupé ; he is hungry = il a faim ; it is cold = il fait froid ; she is right = elle a raison", "acceptedAnswers": [], "explanation": "Attention : en français on « a » faim, froid ou raison, mais en anglais on utilise le verbe être : he is hungry, I am cold, she is right.", "tip": "Faim, froid, raison : en anglais, ce sont des états avec be, pas avec avoir.", "extraExample": {"text": "We are cold.", "translation": "Nous avons froid."}, "pool": "lesson", "lessonId": "en.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l05.e04', 'en', 'en.l05', 'en.g04.be_negative_questions', array['en.g04.be_negative_questions','en.v.late']::text[], 'fill_blank', 'lesson', 'She ___ late. (Elle n''est pas en retard.)', array['isn''t','is not']::text[], 'Avec she, le verbe être se dit is. Pour nier, on ajoute not : is not, qui s''abrège en isn''t. Donc she isn''t late.', 1, '{"id": "en.l05.e04", "unitIds": ["en.g04.be_negative_questions", "en.v.late"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète avec la forme négative qui convient.", "prompt": "She ___ late. (Elle n''est pas en retard.)", "promptLanguage": "en", "options": ["isn''t", "aren''t", "am not"], "answer": "isn''t", "acceptedAnswers": ["isn''t", "is not"], "hint": "She se rapproche de is.", "explanation": "Avec she, le verbe être se dit is. Pour nier, on ajoute not : is not, qui s''abrège en isn''t. Donc she isn''t late.", "tip": "Isn''t = is not : he, she, it.", "extraExample": {"text": "He isn''t ready.", "translation": "Il n''est pas prêt."}, "errorPatterns": [{"equals": "aren''t", "category": "conjugation", "feedback": "Aren''t va avec you, we et they. Avec she, on dit isn''t."}, {"equals": "am not", "category": "conjugation", "feedback": "Am not va uniquement avec I. Avec she, on dit isn''t : she isn''t late."}], "pool": "lesson", "lessonId": "en.l05", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l05.e05', 'en', 'en.l05', 'en.g04.be_negative_questions', array['en.g04.be_negative_questions','en.v.cold']::text[], 'fill_blank', 'lesson', 'We ___ cold. (Nous n''avons pas froid.)', array['aren''t','are not']::text[], 'Avec we, le verbe être se dit are. On ajoute not : are not, qui s''abrège en aren''t. En anglais, on est cold : we aren''t cold.', 2, '{"id": "en.l05.e05", "unitIds": ["en.g04.be_negative_questions", "en.v.cold"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la forme négative qui convient.", "prompt": "We ___ cold. (Nous n''avons pas froid.)", "promptLanguage": "en", "options": ["aren''t", "isn''t", "not"], "answer": "aren''t", "acceptedAnswers": ["aren''t", "are not"], "hint": "Avec we, le verbe être se dit are.", "explanation": "Avec we, le verbe être se dit are. On ajoute not : are not, qui s''abrège en aren''t. En anglais, on est cold : we aren''t cold.", "tip": "Aren''t = are not : you, we, they.", "extraExample": {"text": "They aren''t hungry.", "translation": "Ils n''ont pas faim."}, "errorPatterns": [{"equals": "isn''t", "category": "conjugation", "feedback": "Isn''t va avec he, she et it. Avec we, on dit aren''t."}, {"equals": "not", "category": "grammar", "feedback": "Not seul ne suffit pas : il faut le verbe être. On dit are not ou aren''t : we aren''t cold."}], "pool": "lesson", "lessonId": "en.l05", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l05.e06', 'en', 'en.l05', 'en.g04.be_negative_questions', array['en.g04.be_negative_questions','en.v.late','en.v.teacher']::text[], 'reorder', 'lesson', 'Le professeur est-il en retard ?', array['Is the teacher late']::text[], 'Pour poser une question avec to be, on place le verbe avant le sujet : Is the teacher late? Dans une phrase affirmative, l''ordre est inversé : The teacher is late.', 2, '{"id": "en.l05.e06", "unitIds": ["en.g04.be_negative_questions", "en.v.late", "en.v.teacher"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former une question.", "prompt": "Le professeur est-il en retard ?", "promptLanguage": "fr", "tokens": ["late", "teacher", "the", "Is"], "answer": "Is the teacher late", "acceptedAnswers": ["Is the teacher late"], "hint": "Une question commence par le verbe être.", "explanation": "Pour poser une question avec to be, on place le verbe avant le sujet : Is the teacher late? Dans une phrase affirmative, l''ordre est inversé : The teacher is late.", "tip": "Question : verbe être d''abord (Is, Are, Am), puis le sujet.", "extraExample": {"text": "Are you ready?", "translation": "Es-tu prêt ?"}, "pool": "lesson", "lessonId": "en.l05", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l05.e07', 'en', 'en.l05', 'en.g04.be_negative_questions', array['en.g04.be_negative_questions','en.v.right','en.g03.be_affirmative']::text[], 'translation', 'lesson', 'Tu as raison.', array['You are right','You are correct']::text[], 'Pour dire qu''on a raison, l''anglais utilise le verbe être : you are right. On ne traduit pas « avoir » par have ici.', 2, '{"id": "en.l05.e07", "unitIds": ["en.g04.be_negative_questions", "en.v.right", "en.g03.be_affirmative"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais. Tu parles à une seule personne.", "prompt": "Tu as raison.", "promptLanguage": "fr", "answer": "You are right", "acceptedAnswers": ["You are right", "You are correct"], "hint": "En anglais, on est right : on utilise le verbe être.", "explanation": "Pour dire qu''on a raison, l''anglais utilise le verbe être : you are right. On ne traduit pas « avoir » par have ici.", "tip": "Avoir raison = to be right.", "extraExample": {"text": "I am right.", "translation": "J''ai raison."}, "errorPatterns": [{"contains": "you have", "category": "verb_tense", "feedback": "Pour avoir raison, on utilise le verbe être et non « avoir » : you are right."}, {"contains": "you is", "category": "conjugation", "feedback": "Avec you, le verbe être se dit are : you are right."}], "pool": "lesson", "lessonId": "en.l05", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l05.e08', 'en', 'en.l05', 'en.g04.be_negative_questions', array['en.g04.be_negative_questions','en.v.tired','en.v.hungry','en.g03.be_affirmative']::text[], 'translation', 'lesson', 'Il n''est pas fatigué et il a faim.', array['He is not tired and he is hungry','He is not tired and is hungry']::text[], 'Il n''est pas fatigué = he is not tired (ou he isn''t tired). Il a faim = he is hungry : en anglais, on est hungry. Pas de have ici.', 3, '{"id": "en.l05.e08", "unitIds": ["en.g04.be_negative_questions", "en.v.tired", "en.v.hungry", "en.g03.be_affirmative"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais. « et » = and.", "prompt": "Il n''est pas fatigué et il a faim.", "promptLanguage": "fr", "answer": "He is not tired and he is hungry", "acceptedAnswers": ["He is not tired and he is hungry", "He is not tired and is hungry"], "hint": "Il a faim se dit avec le verbe être.", "explanation": "Il n''est pas fatigué = he is not tired (ou he isn''t tired). Il a faim = he is hungry : en anglais, on est hungry. Pas de have ici.", "tip": "Faim = hungry avec be : he is hungry.", "extraExample": {"text": "She is not cold and she is happy.", "translation": "Elle n''a pas froid et elle est contente."}, "errorPatterns": [{"contains": "he has", "category": "verb_tense", "feedback": "Pour la faim, l''anglais utilise le verbe être : he is hungry."}, {"contains": "he have", "category": "verb_tense", "feedback": "Pour la faim, l''anglais utilise le verbe être : he is hungry."}, {"contains": "he not is", "category": "word_order", "feedback": "Not se place après le verbe être : he is not tired."}], "pool": "lesson", "lessonId": "en.l05", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l05.e09', 'en', 'en.l05', 'en.g04.be_negative_questions', array['en.g04.be_negative_questions','en.v.late','en.g03.be_affirmative']::text[], 'free_answer', 'lesson', 'Comment dit-on « Est-ce que tu es en retard ? » en anglais ?', array['Are you late']::text[], 'Pour poser la question, on place le verbe être avant le sujet : Are you late? En français, « est-ce que » sert à poser la question ; en anglais, on inverse.', 2, '{"id": "en.l05.e09", "unitIds": ["en.g04.be_negative_questions", "en.v.late", "en.g03.be_affirmative"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la question en anglais.", "prompt": "Comment dit-on « Est-ce que tu es en retard ? » en anglais ?", "promptLanguage": "fr", "answer": "Are you late", "acceptedAnswers": ["Are you late"], "hint": "Place le verbe être avant le sujet.", "explanation": "Pour poser la question, on place le verbe être avant le sujet : Are you late? En français, « est-ce que » sert à poser la question ; en anglais, on inverse.", "tip": "Pas de « est-ce que » en anglais : on inverse le verbe et le sujet.", "extraExample": {"text": "Is he busy?", "translation": "Est-ce qu''il est occupé ?"}, "errorPatterns": [{"equals": "you are late", "category": "word_order", "feedback": "C''est l''ordre d''une phrase affirmative. Pour une question, mets are d''abord : Are you late?"}, {"equals": "is you late", "category": "conjugation", "feedback": "Is va avec he, she et it. Avec you, on dit are : Are you late?"}, {"equals": "are you be late", "category": "grammar", "feedback": "N''ajoute pas be : are est déjà le verbe. On dit Are you late?"}], "pool": "lesson", "lessonId": "en.l05", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l05.e10', 'en', 'en.l05', 'en.g04.be_negative_questions', array['en.g04.be_negative_questions','en.v.cold','en.g03.be_affirmative']::text[], 'free_answer', 'lesson', 'Comment dit-on « Non, je n''ai pas froid » en anglais ?', array['No, I am not cold','I am not cold','No I am not cold']::text[], 'Avoir froid se dit be cold en anglais : I am cold. Pour nier, on ajoute not après am : I am not cold. En anglais standard, « amn''t » n''existe pas : on dit I am not ou I''m not.', 3, '{"id": "en.l05.e10", "unitIds": ["en.g04.be_negative_questions", "en.v.cold", "en.g03.be_affirmative"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Non, je n''ai pas froid » en anglais ?", "promptLanguage": "fr", "answer": "No, I am not cold", "acceptedAnswers": ["No, I am not cold", "I am not cold", "No I am not cold"], "hint": "Froid se dit avec le verbe être : I am...", "explanation": "Avoir froid se dit be cold en anglais : I am cold. Pour nier, on ajoute not après am : I am not cold. En anglais standard, « amn''t » n''existe pas : on dit I am not ou I''m not.", "tip": "Avec I : I am not ou I''m not, jamais « I isn''t ».", "extraExample": {"text": "No, I''m not hungry.", "translation": "Non, je n''ai pas faim."}, "errorPatterns": [{"contains": "i have", "category": "verb_tense", "feedback": "Pour le froid, l''anglais utilise le verbe être : I am cold, et non « avoir »."}, {"contains": "i am no cold", "category": "grammar", "feedback": "Pour nier avec le verbe être, on utilise not : I am not cold."}, {"contains": "i not am", "category": "word_order", "feedback": "Not se place après le verbe être : I am not cold."}], "pool": "lesson", "lessonId": "en.l05", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l06.e01', 'en', 'en.l06', 'en.g05.have_has', array['en.g05.have_has','en.v.car','en.g01.subject_pronouns']::text[], 'mcq', 'lesson', 'Comment dit-on « J''ai une voiture » en anglais ?', array['I have a car']::text[], 'Avoir (posséder) se dit have. Avec I, you, we et they, on utilise have : I have a car.', 1, '{"id": "en.l06.e01", "unitIds": ["en.g05.have_has", "en.v.car", "en.g01.subject_pronouns"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « J''ai une voiture » en anglais ?", "promptLanguage": "fr", "options": ["I have a car", "I has a car", "I am have a car", "I a car"], "answer": "I have a car", "acceptedAnswers": ["I have a car"], "hint": "Pour posséder quelque chose, on utilise le verbe have.", "explanation": "Avoir (posséder) se dit have. Avec I, you, we et they, on utilise have : I have a car.", "tip": "I, you, we, they : have.", "extraExample": {"text": "You have a phone.", "translation": "Tu as un téléphone."}, "errorPatterns": [{"equals": "i has a car", "category": "conjugation", "feedback": "Has s''utilise seulement avec he, she et it. Avec I, on dit have : I have a car."}, {"equals": "i am have a car", "category": "grammar", "feedback": "Am et have sont deux verbes différents : on n''en met qu''un. Pour posséder, c''est have : I have a car."}, {"equals": "i a car", "category": "grammar", "feedback": "Il manque le verbe. Pour posséder, on dit I have a car."}], "pool": "lesson", "lessonId": "en.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l06.e02', 'en', 'en.l06', 'en.g05.have_has', array['en.g05.have_has','en.v.dog','en.g01.subject_pronouns']::text[], 'mcq', 'lesson', 'She ___ a dog.', array['has']::text[], 'Avec he, she et it, have devient has : she has a dog. Is veut dire « est » et ne sert pas à dire qu''on possède quelque chose.', 2, '{"id": "en.l06.e02", "unitIds": ["en.g05.have_has", "en.v.dog", "en.g01.subject_pronouns"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme.", "prompt": "She ___ a dog.", "promptLanguage": "en", "options": ["has", "have", "is"], "answer": "has", "acceptedAnswers": ["has"], "hint": "She fait partie de he, she, it.", "explanation": "Avec he, she et it, have devient has : she has a dog. Is veut dire « est » et ne sert pas à dire qu''on possède quelque chose.", "tip": "He, she, it : has.", "extraExample": {"text": "He has a car.", "translation": "Il a une voiture."}, "errorPatterns": [{"equals": "have", "category": "conjugation", "feedback": "Avec he, she et it, have devient has : she has a dog."}, {"equals": "is", "category": "grammar", "feedback": "Is veut dire « est ». Pour posséder un chien, on utilise has : she has a dog."}], "pool": "lesson", "lessonId": "en.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l06.e03', 'en', 'en.l06', 'en.g05.have_has', array['en.g05.have_has','en.v.car','en.v.house','en.v.home','en.v.dog','en.v.phone']::text[], 'match', 'lesson', 'Les nouveaux mots : car, house, home, dog, phone', '{}'::text[], 'House est le bâtiment, la maison qu''on voit dans la rue. Home est l''endroit où on habite, « chez soi » : on dit at home, sans the.', 1, '{"id": "en.l06.e03", "unitIds": ["en.g05.have_has", "en.v.car", "en.v.house", "en.v.home", "en.v.dog", "en.v.phone"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les nouveaux mots : car, house, home, dog, phone", "promptLanguage": "fr", "pairs": [{"left": "a car", "right": "une voiture"}, {"left": "a house", "right": "une maison (le bâtiment)"}, {"left": "at home", "right": "à la maison"}, {"left": "a dog", "right": "un chien"}, {"left": "a phone", "right": "un téléphone"}], "answer": "a car = une voiture ; a house = une maison (le bâtiment) ; at home = à la maison ; a dog = un chien ; a phone = un téléphone", "acceptedAnswers": [], "explanation": "House est le bâtiment, la maison qu''on voit dans la rue. Home est l''endroit où on habite, « chez soi » : on dit at home, sans the.", "tip": "House = le bâtiment ; home = chez soi. On dit at home, jamais « at the home ».", "extraExample": {"text": "The house is cold.", "translation": "La maison est froide."}, "pool": "lesson", "lessonId": "en.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l06.e04', 'en', 'en.l06', 'en.g05.have_has', array['en.g05.have_has','en.v.phone']::text[], 'fill_blank', 'lesson', 'I ___ a phone.', array['have']::text[], 'Avec I, le verbe avoir se dit have : I have a phone. Has est réservé à he, she et it.', 1, '{"id": "en.l06.e04", "unitIds": ["en.g05.have_has", "en.v.phone"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète avec have, has ou am.", "prompt": "I ___ a phone.", "promptLanguage": "en", "options": ["have", "has", "am"], "answer": "have", "acceptedAnswers": ["have"], "hint": "Le pronom est I.", "explanation": "Avec I, le verbe avoir se dit have : I have a phone. Has est réservé à he, she et it.", "tip": "I have, you have, we have, they have.", "extraExample": {"text": "We have a car.", "translation": "Nous avons une voiture."}, "errorPatterns": [{"equals": "has", "category": "conjugation", "feedback": "Has s''utilise seulement avec he, she et it. Avec I, on dit have."}, {"equals": "am", "category": "grammar", "feedback": "Am veut dire « suis ». Pour posséder un téléphone, on dit I have a phone."}], "pool": "lesson", "lessonId": "en.l06", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l06.e05', 'en', 'en.l06', 'en.g05.have_has', array['en.g05.have_has','en.v.car','en.v.house']::text[], 'fill_blank', 'lesson', 'Tom ___ a car and a house.', array['has']::text[], 'Tom, c''est « il » : he. Avec he, le verbe avoir se dit has : Tom has a car and a house.', 2, '{"id": "en.l06.e05", "unitIds": ["en.g05.have_has", "en.v.car", "en.v.house"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec have, has ou is.", "prompt": "Tom ___ a car and a house.", "promptLanguage": "en", "options": ["has", "have", "is"], "answer": "has", "acceptedAnswers": ["has"], "hint": "Tom peut être remplacé par he.", "explanation": "Tom, c''est « il » : he. Avec he, le verbe avoir se dit has : Tom has a car and a house.", "tip": "Un prénom seul (Tom, Anna) : has.", "extraExample": {"text": "Anna has a dog and a phone.", "translation": "Anna a un chien et un téléphone."}, "errorPatterns": [{"equals": "have", "category": "conjugation", "feedback": "Tom est une seule personne (he) : have devient has. On dit Tom has a car."}, {"equals": "is", "category": "grammar", "feedback": "Is veut dire « est ». Pour posséder une voiture et une maison, on utilise has."}], "pool": "lesson", "lessonId": "en.l06", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l06.e06', 'en', 'en.l06', 'en.g05.have_has', array['en.g05.have_has','en.v.car','en.v.house','en.v.man']::text[], 'reorder', 'lesson', 'L''homme a une voiture et une maison.', array['The man has a car and a house','The man has a house and a car']::text[], 'L''ordre est sujet + has + a + nom. The man est une seule personne (he) : on dit has. Les deux noms sont reliés par and et prennent chacun a.', 2, '{"id": "en.l06.e06", "unitIds": ["en.g05.have_has", "en.v.car", "en.v.house", "en.v.man"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former une phrase.", "prompt": "L''homme a une voiture et une maison.", "promptLanguage": "fr", "tokens": ["house", "The", "man", "a", "has", "and", "a", "car"], "answer": "The man has a car and a house", "acceptedAnswers": ["The man has a car and a house", "The man has a house and a car"], "hint": "Sujet, puis has, puis les deux noms reliés par and.", "explanation": "L''ordre est sujet + has + a + nom. The man est une seule personne (he) : on dit has. Les deux noms sont reliés par and et prennent chacun a.", "tip": "Sujet + has + a + nom + and + a + nom.", "extraExample": {"text": "The woman has a dog and a phone.", "translation": "La femme a un chien et un téléphone."}, "pool": "lesson", "lessonId": "en.l06", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l06.e07', 'en', 'en.l06', 'en.g05.have_has', array['en.g05.have_has','en.v.house']::text[], 'translation', 'lesson', 'Nous avons une maison.', array['We have a house','We have a home']::text[], 'Nous = we. Avec we, le verbe avoir se dit have : we have a house. Le mot house désigne le bâtiment.', 2, '{"id": "en.l06.e07", "unitIds": ["en.g05.have_has", "en.v.house"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Nous avons une maison.", "promptLanguage": "fr", "answer": "We have a house", "acceptedAnswers": ["We have a house", "We have a home"], "hint": "Nous se dit we. Quel verbe pour posséder ?", "explanation": "Nous = we. Avec we, le verbe avoir se dit have : we have a house. Le mot house désigne le bâtiment.", "tip": "We have : jamais « we has ».", "extraExample": {"text": "They have a house and a dog.", "translation": "Ils ont une maison et un chien."}, "errorPatterns": [{"contains": "we has", "category": "conjugation", "feedback": "Has s''utilise seulement avec he, she et it. Avec we, on dit have : we have a house."}, {"contains": "we are", "category": "grammar", "feedback": "Are veut dire « sommes ». Pour posséder, on utilise have : we have a house."}, {"equals": "we have house", "category": "grammar", "feedback": "Il manque l''article : we have a house."}], "pool": "lesson", "lessonId": "en.l06", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l06.e08', 'en', 'en.l06', 'en.g05.have_has', array['en.g05.have_has','en.g03.be_affirmative','en.v.home','en.v.dog']::text[], 'translation', 'lesson', 'Il est à la maison et il a un chien.', array['He is at home and he has a dog','He is at home and has a dog','He is home and he has a dog','He is home and has a dog']::text[], 'Il est à la maison = he is at home (verbe être). Il a un chien = he has a dog (verbe avoir, forme has avec he). À la maison se dit at home, sans article.', 3, '{"id": "en.l06.e08", "unitIds": ["en.g05.have_has", "en.g03.be_affirmative", "en.v.home", "en.v.dog"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais. « et » = and.", "prompt": "Il est à la maison et il a un chien.", "promptLanguage": "fr", "answer": "He is at home and he has a dog", "acceptedAnswers": ["He is at home and he has a dog", "He is at home and has a dog", "He is home and he has a dog", "He is home and has a dog"], "hint": "Deux verbes différents : être pour le lieu, avoir pour le chien.", "explanation": "Il est à la maison = he is at home (verbe être). Il a un chien = he has a dog (verbe avoir, forme has avec he). À la maison se dit at home, sans article.", "tip": "Être pour où on est, avoir pour ce qu''on possède.", "extraExample": {"text": "She is at home and she has a phone.", "translation": "Elle est à la maison et elle a un téléphone."}, "errorPatterns": [{"contains": "he have", "category": "conjugation", "feedback": "Avec he, have devient has : he has a dog."}, {"contains": "at the home", "category": "grammar", "feedback": "À la maison se dit at home, sans the."}, {"contains": "in home", "category": "preposition", "feedback": "À la maison se dit at home, pas in home."}], "pool": "lesson", "lessonId": "en.l06", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l06.e09', 'en', 'en.l06', 'en.g05.have_has', array['en.g05.have_has','en.v.phone','en.g01.subject_pronouns']::text[], 'free_answer', 'lesson', 'Comment dit-on « Elle a un téléphone » en anglais ?', array['She has a phone']::text[], 'Elle = she. Avec she, have devient has : she has a phone.', 2, '{"id": "en.l06.e09", "unitIds": ["en.g05.have_has", "en.v.phone", "en.g01.subject_pronouns"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Elle a un téléphone » en anglais ?", "promptLanguage": "fr", "answer": "She has a phone", "acceptedAnswers": ["She has a phone"], "hint": "Elle se dit she : quelle forme de have ?", "explanation": "Elle = she. Avec she, have devient has : she has a phone.", "tip": "She has, he has, it has.", "extraExample": {"text": "He has a phone.", "translation": "Il a un téléphone."}, "errorPatterns": [{"equals": "she have a phone", "category": "conjugation", "feedback": "Avec she, have devient has : she has a phone."}, {"equals": "she haves a phone", "category": "spelling", "feedback": "Le verbe have est irrégulier : he, she et it font has, pas « haves »."}, {"equals": "she has phone", "category": "grammar", "feedback": "Il manque l''article : she has a phone."}], "pool": "lesson", "lessonId": "en.l06", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l06.e10', 'en', 'en.l06', 'en.g05.have_has', array['en.g05.have_has','en.g04.be_negative_questions','en.v.hungry']::text[], 'free_answer', 'lesson', 'Comment dit-on « Elle a faim » en anglais ?', array['She is hungry']::text[], 'Pour la faim, l''anglais utilise le verbe être : she is hungry. Le verbe have sert à dire qu''on possède quelque chose (a car, a dog), pas à dire ce qu''on ressent.', 3, '{"id": "en.l06.e10", "unitIds": ["en.g05.have_has", "en.g04.be_negative_questions", "en.v.hungry"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Elle a faim » en anglais ?", "promptLanguage": "fr", "answer": "She is hungry", "acceptedAnswers": ["She is hungry"], "hint": "Attention : faim se dit avec le verbe être, pas avec have.", "explanation": "Pour la faim, l''anglais utilise le verbe être : she is hungry. Le verbe have sert à dire qu''on possède quelque chose (a car, a dog), pas à dire ce qu''on ressent.", "tip": "Faim, froid, raison : be (is, am, are). Voiture, chien, téléphone : have.", "extraExample": {"text": "I am cold.", "translation": "J''ai froid."}, "errorPatterns": [{"contains": "she has", "category": "verb_tense", "feedback": "On ne dit pas « she has hungry ». Pour la faim, l''anglais utilise le verbe être : she is hungry."}, {"contains": "she have", "category": "verb_tense", "feedback": "Pour la faim, l''anglais utilise le verbe être : she is hungry."}, {"contains": "she are", "category": "conjugation", "feedback": "Are va avec you, we et they. Avec she, on dit is : she is hungry."}], "pool": "lesson", "lessonId": "en.l06", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l07.e01', 'en', 'en.l07', 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.v.son']::text[], 'mcq', 'lesson', 'Comment dit-on « mon fils » en anglais ?', array['my son']::text[], '« Mon, ma, mes » se disent tous my en anglais. Me et I ne sont pas des possessifs : on dit my son.', 1, '{"id": "en.l07.e01", "unitIds": ["en.g06.possessive_adjectives", "en.v.son"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « mon fils » en anglais ?", "promptLanguage": "fr", "options": ["my son", "me son", "I son"], "answer": "my son", "acceptedAnswers": ["my son"], "hint": "Mon, ma et mes se disent avec le même mot qui commence par m.", "explanation": "« Mon, ma, mes » se disent tous my en anglais. Me et I ne sont pas des possessifs : on dit my son.", "tip": "Mon, ma, mes = my. Un seul mot, quel que soit le nom.", "extraExample": {"text": "my friend", "translation": "mon ami"}, "errorPatterns": [{"equals": "me son", "category": "grammar", "feedback": "Me n''est pas un possessif. Pour « mon », on dit my : my son."}, {"equals": "i son", "category": "grammar", "feedback": "I est un sujet (« je »), pas un possessif. Pour « mon », on dit my : my son."}], "pool": "lesson", "lessonId": "en.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l07.e02', 'en', 'en.l07', 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.v.husband']::text[], 'mcq', 'lesson', 'Anna has a husband. ___ husband is a teacher.', array['Her']::text[], 'En anglais, le possessif dépend de celui qui possède, pas de ce qui est possédé. Anna est une femme, donc her husband. Si c''était Tom, on dirait his wife.', 2, '{"id": "en.l07.e02", "unitIds": ["en.g06.possessive_adjectives", "en.v.husband"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon possessif.", "prompt": "Anna has a husband. ___ husband is a teacher.", "promptLanguage": "en", "options": ["Her", "His", "Its"], "answer": "Her", "acceptedAnswers": ["Her"], "hint": "Regarde qui possède le mari : Anna. Est-ce un homme ou une femme ?", "explanation": "En anglais, le possessif dépend de celui qui possède, pas de ce qui est possédé. Anna est une femme, donc her husband. Si c''était Tom, on dirait his wife.", "tip": "Possesseur féminin : her. Possesseur masculin : his.", "extraExample": {"text": "Tom has a wife. His wife is a student.", "translation": "Tom a une femme. Sa femme est étudiante."}, "errorPatterns": [{"equals": "his", "category": "grammar", "feedback": "His est pour un possesseur masculin. Ici, le possesseur est Anna, une femme : her husband."}, {"equals": "its", "category": "grammar", "feedback": "Its s''utilise pour un animal ou une chose, pas pour une personne. Pour Anna, on dit her."}], "pool": "lesson", "lessonId": "en.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l07.e03', 'en', 'en.l07', 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.v.name','en.v.daughter','en.v.husband','en.v.wife','en.v.parents']::text[], 'match', 'lesson', 'Les possessifs et les nouveaux mots : daughter, husband, wife, parents', '{}'::text[], 'My, your, our correspondent à mon, ton, notre. Pour « son, sa, ses », on choisit his (possesseur masculin) ou her (possesseur féminin). Attention : parents désigne seulement le père et la mère, pas toute la famille.', 1, '{"id": "en.l07.e03", "unitIds": ["en.g06.possessive_adjectives", "en.v.name", "en.v.daughter", "en.v.husband", "en.v.wife", "en.v.parents"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les possessifs et les nouveaux mots : daughter, husband, wife, parents", "promptLanguage": "fr", "pairs": [{"left": "my name", "right": "mon nom"}, {"left": "your daughter", "right": "ta fille"}, {"left": "his wife", "right": "sa femme (à lui)"}, {"left": "her husband", "right": "son mari (à elle)"}, {"left": "our parents", "right": "nos parents"}], "answer": "my name = mon nom ; your daughter = ta fille ; his wife = sa femme (à lui) ; her husband = son mari (à elle) ; our parents = nos parents", "acceptedAnswers": [], "explanation": "My, your, our correspondent à mon, ton, notre. Pour « son, sa, ses », on choisit his (possesseur masculin) ou her (possesseur féminin). Attention : parents désigne seulement le père et la mère, pas toute la famille.", "tip": "Son, sa, ses : his si c''est un homme qui possède, her si c''est une femme.", "extraExample": {"text": "their son", "translation": "leur fils"}, "pool": "lesson", "lessonId": "en.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l07.e04', 'en', 'en.l07', 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.v.daughter','en.v.student']::text[], 'fill_blank', 'lesson', '___ daughter is a student. (Ma fille est étudiante.)', array['My']::text[], 'Ma fille = my daughter. My veut dire « mon, ma, mes » : il ne change jamais.', 1, '{"id": "en.l07.e04", "unitIds": ["en.g06.possessive_adjectives", "en.v.daughter", "en.v.student"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète avec le possessif qui correspond à la traduction.", "prompt": "___ daughter is a student. (Ma fille est étudiante.)", "promptLanguage": "en", "options": ["My", "Your", "His"], "answer": "My", "acceptedAnswers": ["My"], "hint": "Ma se dit comme mon : un seul mot.", "explanation": "Ma fille = my daughter. My veut dire « mon, ma, mes » : il ne change jamais.", "tip": "My ne change pas : my son, my daughter.", "extraExample": {"text": "My son is a teacher.", "translation": "Mon fils est professeur."}, "errorPatterns": [{"equals": "your", "category": "grammar", "feedback": "Your veut dire « ton, ta, tes » ou « votre ». Pour « ma fille », on dit my daughter."}, {"equals": "his", "category": "grammar", "feedback": "His veut dire « son, sa, ses » (à lui). Pour « ma fille », on dit my daughter."}], "pool": "lesson", "lessonId": "en.l07", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l07.e05', 'en', 'en.l07', 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.v.dog','en.v.home']::text[], 'fill_blank', 'lesson', 'Anna and Tom have a dog. ___ dog is at home. (Leur chien est à la maison.)', array['Their']::text[], 'Anna et Tom, c''est « ils » : they. Le possessif correspondant est their (« leur, leurs ») : their dog.', 2, '{"id": "en.l07.e05", "unitIds": ["en.g06.possessive_adjectives", "en.v.dog", "en.v.home"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le possessif qui correspond à la traduction.", "prompt": "Anna and Tom have a dog. ___ dog is at home. (Leur chien est à la maison.)", "promptLanguage": "en", "options": ["Their", "Her", "His"], "answer": "Their", "acceptedAnswers": ["Their"], "hint": "Deux personnes possèdent le chien.", "explanation": "Anna et Tom, c''est « ils » : they. Le possessif correspondant est their (« leur, leurs ») : their dog.", "tip": "Their = leur, leurs. Attention à ne pas l''écrire there.", "extraExample": {"text": "Their car is at home.", "translation": "Leur voiture est à la maison."}, "errorPatterns": [{"equals": "her", "category": "grammar", "feedback": "Her ne désigne qu''une femme. Anna et Tom sont deux : their dog."}, {"equals": "his", "category": "grammar", "feedback": "His ne désigne qu''un homme. Anna et Tom sont deux : their dog."}, {"equals": "there", "category": "word_confusion", "feedback": "There est un autre mot (« là »). Pour « leur », on écrit their."}], "pool": "lesson", "lessonId": "en.l07", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l07.e06', 'en', 'en.l07', 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.v.parents','en.v.home']::text[], 'reorder', 'lesson', 'Nos parents sont à la maison.', array['Our parents are at home']::text[], 'Le possessif se place avant le nom : our parents. Parents désigne plusieurs personnes (they), donc le verbe est are. À la maison se dit at home.', 2, '{"id": "en.l07.e06", "unitIds": ["en.g06.possessive_adjectives", "en.v.parents", "en.v.home"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former une phrase.", "prompt": "Nos parents sont à la maison.", "promptLanguage": "fr", "tokens": ["home", "Our", "at", "are", "parents"], "answer": "Our parents are at home", "acceptedAnswers": ["Our parents are at home"], "hint": "Le possessif est devant le nom. Parents, c''est plusieurs personnes.", "explanation": "Le possessif se place avant le nom : our parents. Parents désigne plusieurs personnes (they), donc le verbe est are. À la maison se dit at home.", "tip": "Possessif + nom : our parents. Parents = plusieurs personnes : are.", "extraExample": {"text": "Your parents are ready.", "translation": "Tes parents sont prêts."}, "pool": "lesson", "lessonId": "en.l07", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l07.e07', 'en', 'en.l07', 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.v.wife','en.g03.be_affirmative']::text[], 'translation', 'lesson', 'Ma femme est fatiguée.', array['My wife is tired']::text[], 'Ma = my : un seul mot pour mon, ma, mes. Un possessif remplace l''article : on dit my wife, pas « the my wife ». Wife est une seule personne : is.', 2, '{"id": "en.l07.e07", "unitIds": ["en.g06.possessive_adjectives", "en.v.wife", "en.g03.be_affirmative"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Ma femme est fatiguée.", "promptLanguage": "fr", "answer": "My wife is tired", "acceptedAnswers": ["My wife is tired"], "hint": "Pas d''article devant my.", "explanation": "Ma = my : un seul mot pour mon, ma, mes. Un possessif remplace l''article : on dit my wife, pas « the my wife ». Wife est une seule personne : is.", "tip": "Possessif ou article, jamais les deux : my wife, the wife.", "extraExample": {"text": "My husband is happy.", "translation": "Mon mari est heureux."}, "errorPatterns": [{"contains": "the my", "category": "grammar", "feedback": "On n''utilise pas the avec un possessif : my wife."}, {"contains": "me wife", "category": "grammar", "feedback": "Me n''est pas un possessif. Pour « ma », on dit my : my wife."}, {"contains": "wife are", "category": "conjugation", "feedback": "Wife est une seule personne : is, pas are."}], "pool": "lesson", "lessonId": "en.l07", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l07.e08', 'en', 'en.l07', 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.g05.have_has','en.v.daughter']::text[], 'translation', 'lesson', 'Tom a une fille. Sa fille est heureuse.', array['Tom has a daughter. His daughter is happy','Tom has a daughter and his daughter is happy']::text[], 'Tom est un homme, donc « sa fille » = his daughter. Le possessif dépend du possesseur (Tom), pas de fille. Tom, c''est he : have devient has.', 3, '{"id": "en.l07.e08", "unitIds": ["en.g06.possessive_adjectives", "en.g05.have_has", "en.v.daughter"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais. Tom est un homme.", "prompt": "Tom a une fille. Sa fille est heureuse.", "promptLanguage": "fr", "answer": "Tom has a daughter. His daughter is happy", "acceptedAnswers": ["Tom has a daughter. His daughter is happy", "Tom has a daughter and his daughter is happy"], "hint": "Qui possède la fille ? Un homme.", "explanation": "Tom est un homme, donc « sa fille » = his daughter. Le possessif dépend du possesseur (Tom), pas de fille. Tom, c''est he : have devient has.", "tip": "Possesseur masculin : his, même devant un nom féminin.", "extraExample": {"text": "Anna has a son. Her son is tired.", "translation": "Anna a un fils. Son fils est fatigué."}, "errorPatterns": [{"contains": "her daughter", "category": "grammar", "feedback": "Her est pour une femme qui possède. Tom est un homme : his daughter."}, {"contains": "tom have", "category": "conjugation", "feedback": "Avec Tom (he), have devient has : Tom has a daughter."}, {"contains": "its daughter", "category": "grammar", "feedback": "Its est pour un animal ou une chose. Pour Tom, on dit his."}], "pool": "lesson", "lessonId": "en.l07", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l07.e09', 'en', 'en.l07', 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.v.parents']::text[], 'free_answer', 'lesson', 'Comment dit-on « leurs parents » en anglais ?', array['their parents']::text[], 'Leur et leurs se disent their : their parents. Parents est le mot pour « père et mère ».', 2, '{"id": "en.l07.e09", "unitIds": ["en.g06.possessive_adjectives", "en.v.parents"], "type": "free_answer", "difficulty": 2, "instruction": "Écris l''expression en anglais.", "prompt": "Comment dit-on « leurs parents » en anglais ?", "promptLanguage": "fr", "answer": "their parents", "acceptedAnswers": ["their parents"], "hint": "Leur se dit comme they, avec un r à la fin.", "explanation": "Leur et leurs se disent their : their parents. Parents est le mot pour « père et mère ».", "tip": "Their (leur) ne se confond pas avec there (là).", "extraExample": {"text": "their house", "translation": "leur maison"}, "errorPatterns": [{"equals": "there parents", "category": "word_confusion", "feedback": "There veut dire « là ». Pour « leurs », on écrit their."}, {"equals": "they parents", "category": "grammar", "feedback": "They est un sujet (« ils »). Pour « leurs », on dit their."}, {"equals": "theirs parents", "category": "grammar", "feedback": "Their ne prend pas de s. On dit their parents."}], "pool": "lesson", "lessonId": "en.l07", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l07.e10', 'en', 'en.l07', 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.v.husband','en.g03.be_affirmative']::text[], 'free_answer', 'lesson', 'Comment dit-on « Anna et son mari sont à la maison » en anglais ?', array['Anna and her husband are at home','Anna and her husband are home']::text[], 'Anna est une femme, donc « son mari » = her husband. Anna and her husband, c''est deux personnes : le verbe est are. À la maison se dit at home.', 3, '{"id": "en.l07.e10", "unitIds": ["en.g06.possessive_adjectives", "en.v.husband", "en.g03.be_affirmative"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Anna et son mari sont à la maison » en anglais ?", "promptLanguage": "fr", "answer": "Anna and her husband are at home", "acceptedAnswers": ["Anna and her husband are at home", "Anna and her husband are home"], "hint": "Anna est une femme : quel possessif pour « son » ?", "explanation": "Anna est une femme, donc « son mari » = her husband. Anna and her husband, c''est deux personnes : le verbe est are. À la maison se dit at home.", "tip": "Femme + son mari : her husband. Deux personnes : are.", "extraExample": {"text": "Tom and his wife are tired.", "translation": "Tom et sa femme sont fatigués."}, "errorPatterns": [{"contains": "his husband", "category": "grammar", "feedback": "His est pour un possesseur masculin. Anna est une femme : her husband."}, {"contains": "husband is", "category": "conjugation", "feedback": "Anna et son mari font deux personnes : on dit are, pas is."}, {"contains": "at the home", "category": "grammar", "feedback": "À la maison se dit at home, sans the."}], "pool": "lesson", "lessonId": "en.l07", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l08.e01', 'en', 'en.l08', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.book']::text[], 'mcq', 'lesson', 'Comment dit-on « des livres » en anglais ?', array['books']::text[], 'Pour faire le pluriel d''un nom, on ajoute en général -s : book devient books. Devant un pluriel, on n''utilise pas a : « des livres » se dit simplement books.', 1, '{"id": "en.l08.e01", "unitIds": ["en.g07.plural_nouns", "en.v.book"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « des livres » en anglais ?", "promptLanguage": "fr", "options": ["books", "book", "a books", "bookes"], "answer": "books", "acceptedAnswers": ["books"], "hint": "Il s''agit de plusieurs livres.", "explanation": "Pour faire le pluriel d''un nom, on ajoute en général -s : book devient books. Devant un pluriel, on n''utilise pas a : « des livres » se dit simplement books.", "tip": "Plusieurs = -s à la fin du nom, et pas de a.", "extraExample": {"text": "I have books.", "translation": "J''ai des livres."}, "errorPatterns": [{"equals": "book", "category": "grammar", "feedback": "Book est au singulier (un livre). Pour plusieurs livres, on ajoute -s : books."}, {"equals": "a books", "category": "grammar", "feedback": "A veut dire « un » : on ne le met pas devant un pluriel. On dit books."}, {"equals": "bookes", "category": "spelling", "feedback": "On ajoute -es seulement après s, x, ch ou sh. Après k, on ajoute juste -s : books."}], "pool": "lesson", "lessonId": "en.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l08.e02', 'en', 'en.l08', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.child','en.g02.articles']::text[], 'mcq', 'lesson', 'Comment dit-on « les enfants » en anglais ?', array['the children']::text[], 'Child a un pluriel irrégulier : children. On ne dit pas « childs ». Children est déjà un pluriel : on n''y ajoute pas de s.', 2, '{"id": "en.l08.e02", "unitIds": ["en.g07.plural_nouns", "en.v.child", "en.g02.articles"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « les enfants » en anglais ?", "promptLanguage": "fr", "options": ["the children", "the childs", "the childrens", "the child"], "answer": "the children", "acceptedAnswers": ["the children"], "hint": "Child a un pluriel irrégulier : il ne prend pas simplement -s.", "explanation": "Child a un pluriel irrégulier : children. On ne dit pas « childs ». Children est déjà un pluriel : on n''y ajoute pas de s.", "tip": "À retenir par cœur : one child, children.", "extraExample": {"text": "The children are happy.", "translation": "Les enfants sont heureux."}, "errorPatterns": [{"equals": "the childs", "category": "spelling", "feedback": "Child est un pluriel irrégulier : on ne dit pas « childs », mais children."}, {"equals": "the childrens", "category": "spelling", "feedback": "Children est déjà au pluriel : pas de s à la fin."}, {"equals": "the child", "category": "grammar", "feedback": "Child est au singulier (l''enfant). Pour « les enfants », on dit the children."}], "pool": "lesson", "lessonId": "en.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l08.e03', 'en', 'en.l08', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.key','en.v.bag','en.v.school','en.v.people']::text[], 'match', 'lesson', 'Les pluriels : keys, bags, schools, children, people', '{}'::text[], 'Keys, bags et schools suivent la règle : on ajoute -s. Children est un pluriel irrégulier. People est le pluriel de person : c''est déjà un pluriel, donc on dit people are.', 1, '{"id": "en.l08.e03", "unitIds": ["en.g07.plural_nouns", "en.v.key", "en.v.bag", "en.v.school", "en.v.people"], "type": "match", "difficulty": 1, "instruction": "Associe chaque pluriel anglais à sa traduction.", "prompt": "Les pluriels : keys, bags, schools, children, people", "promptLanguage": "fr", "pairs": [{"left": "keys", "right": "des clés"}, {"left": "bags", "right": "des sacs"}, {"left": "schools", "right": "des écoles"}, {"left": "children", "right": "des enfants"}, {"left": "people", "right": "des gens, des personnes"}], "answer": "keys = des clés ; bags = des sacs ; schools = des écoles ; children = des enfants ; people = des gens, des personnes", "acceptedAnswers": [], "explanation": "Keys, bags et schools suivent la règle : on ajoute -s. Children est un pluriel irrégulier. People est le pluriel de person : c''est déjà un pluriel, donc on dit people are.", "tip": "People est un pluriel : on dit people are, jamais « people is ».", "extraExample": {"text": "The people are ready.", "translation": "Les gens sont prêts."}, "pool": "lesson", "lessonId": "en.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l08.e04', 'en', 'en.l08', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.bag','en.v.home']::text[], 'fill_blank', 'lesson', 'The ___ are at home. (Les sacs sont à la maison.)', array['bags']::text[], 'Il y a plusieurs sacs : on ajoute -s à bag, ce qui donne bags. Le verbe are est aussi un signe de pluriel.', 1, '{"id": "en.l08.e04", "unitIds": ["en.g07.plural_nouns", "en.v.bag", "en.v.home"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète avec le bon mot.", "prompt": "The ___ are at home. (Les sacs sont à la maison.)", "promptLanguage": "en", "options": ["bags", "bag", "bages"], "answer": "bags", "acceptedAnswers": ["bags"], "hint": "Il y a plusieurs sacs, et le verbe est are.", "explanation": "Il y a plusieurs sacs : on ajoute -s à bag, ce qui donne bags. Le verbe are est aussi un signe de pluriel.", "tip": "Are indique un pluriel : le nom prend aussi un -s.", "extraExample": {"text": "The keys are at home.", "translation": "Les clés sont à la maison."}, "errorPatterns": [{"equals": "bag", "category": "grammar", "feedback": "Bag est au singulier. Pour plusieurs sacs, on ajoute -s : the bags are."}, {"equals": "bages", "category": "spelling", "feedback": "Le pluriel de bag est bags : on ajoute seulement -s."}], "pool": "lesson", "lessonId": "en.l08", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l08.e05', 'en', 'en.l08', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.woman','en.v.happy']::text[], 'fill_blank', 'lesson', 'The ___ are happy. (Les femmes sont heureuses.)', array['women']::text[], 'Woman a un pluriel irrégulier : women. On ne dit pas « womans ». Le verbe are annonce aussi un pluriel.', 2, '{"id": "en.l08.e05", "unitIds": ["en.g07.plural_nouns", "en.v.woman", "en.v.happy"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le pluriel qui convient.", "prompt": "The ___ are happy. (Les femmes sont heureuses.)", "promptLanguage": "en", "options": ["women", "woman", "womans"], "answer": "women", "acceptedAnswers": ["women"], "hint": "Le pluriel de woman est irrégulier.", "explanation": "Woman a un pluriel irrégulier : women. On ne dit pas « womans ». Le verbe are annonce aussi un pluriel.", "tip": "Man devient men, woman devient women.", "extraExample": {"text": "The wives are tired.", "translation": "Les épouses sont fatiguées."}, "errorPatterns": [{"equals": "woman", "category": "grammar", "feedback": "Woman est au singulier. Pour « les femmes », on dit women."}, {"equals": "womans", "category": "spelling", "feedback": "Woman est un pluriel irrégulier : on ne dit pas « womans », mais women."}], "pool": "lesson", "lessonId": "en.l08", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l08.e06', 'en', 'en.l08', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.book','en.v.school']::text[], 'reorder', 'lesson', 'Les livres sont à l''école.', array['The books are at school']::text[], 'Le sujet est au pluriel (books), donc le verbe est are. À l''école se dit at school, comme at home : sans article.', 2, '{"id": "en.l08.e06", "unitIds": ["en.g07.plural_nouns", "en.v.book", "en.v.school"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former une phrase.", "prompt": "Les livres sont à l''école.", "promptLanguage": "fr", "tokens": ["school", "The", "at", "are", "books"], "answer": "The books are at school", "acceptedAnswers": ["The books are at school"], "hint": "L''ordre est sujet, are, puis at school.", "explanation": "Le sujet est au pluriel (books), donc le verbe est are. À l''école se dit at school, comme at home : sans article.", "tip": "Sujet pluriel = are. À l''école = at school.", "extraExample": {"text": "The children are at school.", "translation": "Les enfants sont à l''école."}, "pool": "lesson", "lessonId": "en.l08", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l08.e07', 'en', 'en.l08', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.key','en.v.bag','en.g05.have_has']::text[], 'translation', 'lesson', 'Tom a des clés et un sac.', array['Tom has keys and a bag','Tom has some keys and a bag']::text[], 'Des clés se dit keys : on ajoute -s à key (après une voyelle + y, on ne change pas le y) et on n''ajoute pas a. Un sac se dit a bag, au singulier. Tom, c''est he : has.', 2, '{"id": "en.l08.e07", "unitIds": ["en.g07.plural_nouns", "en.v.key", "en.v.bag", "en.g05.have_has"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais. « et » = and.", "prompt": "Tom a des clés et un sac.", "promptLanguage": "fr", "answer": "Tom has keys and a bag", "acceptedAnswers": ["Tom has keys and a bag", "Tom has some keys and a bag"], "hint": "Des clés est au pluriel. Un sac est au singulier.", "explanation": "Des clés se dit keys : on ajoute -s à key (après une voyelle + y, on ne change pas le y) et on n''ajoute pas a. Un sac se dit a bag, au singulier. Tom, c''est he : has.", "tip": "Pluriel : nom + s, sans a. Singulier : a + nom.", "extraExample": {"text": "Anna has books and a phone.", "translation": "Anna a des livres et un téléphone."}, "errorPatterns": [{"contains": "a keys", "category": "grammar", "feedback": "A ne se met pas devant un pluriel. Des clés se dit simplement keys."}, {"contains": "keies", "category": "spelling", "feedback": "Key fait keys : après une voyelle + y, on ajoute seulement -s."}, {"contains": "tom have", "category": "conjugation", "feedback": "Avec Tom (he), have devient has : Tom has keys."}], "pool": "lesson", "lessonId": "en.l08", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l08.e08', 'en', 'en.l08', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.school','en.v.woman','en.v.child']::text[], 'translation', 'lesson', 'Les femmes et les enfants sont à l''école.', array['The women and the children are at school','The women and children are at school','The women and the children are at the school','The women and children are at the school','The women and the kids are at school','The women and kids are at school']::text[], 'Les femmes se dit the women et les enfants se dit the children : ce sont deux pluriels irréguliers. Le sujet est au pluriel : le verbe est are. À l''école se dit at school.', 3, '{"id": "en.l08.e08", "unitIds": ["en.g07.plural_nouns", "en.v.school", "en.v.woman", "en.v.child"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais. « et » = and.", "prompt": "Les femmes et les enfants sont à l''école.", "promptLanguage": "fr", "answer": "The women and the children are at school", "acceptedAnswers": ["The women and the children are at school", "The women and children are at school", "The women and the children are at the school", "The women and children are at the school", "The women and the kids are at school", "The women and kids are at school"], "hint": "Deux pluriels irréguliers : woman et child.", "explanation": "Les femmes se dit the women et les enfants se dit the children : ce sont deux pluriels irréguliers. Le sujet est au pluriel : le verbe est are. À l''école se dit at school.", "tip": "Woman → women, child → children : à connaître par cœur.", "extraExample": {"text": "The men and the women are at home.", "translation": "Les hommes et les femmes sont à la maison."}, "errorPatterns": [{"contains": "womans", "category": "spelling", "feedback": "Le pluriel de woman est women, pas « womans »."}, {"contains": "childs", "category": "spelling", "feedback": "Le pluriel de child est children, pas « childs »."}, {"contains": "childrens", "category": "spelling", "feedback": "Children est déjà un pluriel : pas de s à la fin."}], "pool": "lesson", "lessonId": "en.l08", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l08.e09', 'en', 'en.l08', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.man']::text[], 'free_answer', 'lesson', 'Comment dit-on « des hommes » en anglais ?', array['men','some men']::text[], 'Man a un pluriel irrégulier : men. On change le a en e, sans ajouter de s.', 2, '{"id": "en.l08.e09", "unitIds": ["en.g07.plural_nouns", "en.v.man"], "type": "free_answer", "difficulty": 2, "instruction": "Écris le pluriel en anglais.", "prompt": "Comment dit-on « des hommes » en anglais ?", "promptLanguage": "fr", "answer": "men", "acceptedAnswers": ["men", "some men"], "hint": "C''est un pluriel irrégulier : la voyelle change.", "explanation": "Man a un pluriel irrégulier : men. On change le a en e, sans ajouter de s.", "tip": "One man, two men : le a devient e.", "extraExample": {"text": "The men are ready.", "translation": "Les hommes sont prêts."}, "errorPatterns": [{"equals": "mans", "category": "spelling", "feedback": "Man est un pluriel irrégulier : on ne dit pas « mans », mais men."}, {"equals": "mens", "category": "spelling", "feedback": "Men est déjà un pluriel : pas de s à la fin."}, {"equals": "man", "category": "grammar", "feedback": "Man est au singulier. Pour « des hommes », on dit men."}], "pool": "lesson", "lessonId": "en.l08", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l08.e10', 'en', 'en.l08', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.people','en.v.tired','en.g03.be_affirmative']::text[], 'free_answer', 'lesson', 'Comment dit-on « Les gens sont fatigués » en anglais ?', array['The people are tired','People are tired']::text[], '« Les gens » se dit people, un pluriel (c''est le pluriel de person). Le verbe est donc are : the people are tired.', 3, '{"id": "en.l08.e10", "unitIds": ["en.g07.plural_nouns", "en.v.people", "en.v.tired", "en.g03.be_affirmative"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Les gens sont fatigués » en anglais ?", "promptLanguage": "fr", "answer": "The people are tired", "acceptedAnswers": ["The people are tired", "People are tired"], "hint": "People est déjà un pluriel : quel verbe ?", "explanation": "« Les gens » se dit people, un pluriel (c''est le pluriel de person). Le verbe est donc are : the people are tired.", "tip": "People are : toujours are, jamais « people is ».", "extraExample": {"text": "People are happy.", "translation": "Les gens sont heureux."}, "errorPatterns": [{"contains": "people is", "category": "conjugation", "feedback": "People est un pluriel : on dit people are, pas people is."}, {"contains": "peoples", "category": "spelling", "feedback": "People est déjà un pluriel : pas de s (peoples veut dire « les peuples »)."}, {"contains": "persons", "category": "word_confusion", "feedback": "Pour « les gens », on utilise people, pas persons."}], "pool": "lesson", "lessonId": "en.l08", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l09.e01', 'en', 'en.l09', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.three','en.v.book']::text[], 'mcq', 'lesson', 'Comment dit-on « trois livres » en anglais ?', array['three books']::text[], 'Après un nombre plus grand que one, le nom est au pluriel : three books. On ajoute -s à book, et on n''utilise pas a.', 1, '{"id": "en.l09.e01", "unitIds": ["en.g07.plural_nouns", "en.v.three", "en.v.book"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « trois livres » en anglais ?", "promptLanguage": "fr", "options": ["three books", "three book", "three bookes"], "answer": "three books", "acceptedAnswers": ["three books"], "hint": "Après trois, le nom est au pluriel.", "explanation": "Après un nombre plus grand que one, le nom est au pluriel : three books. On ajoute -s à book, et on n''utilise pas a.", "tip": "Plus d''un = nom au pluriel : three books, two keys.", "extraExample": {"text": "two bags", "translation": "deux sacs"}, "errorPatterns": [{"equals": "three book", "category": "grammar", "feedback": "Après three, le nom prend un -s : three books."}, {"equals": "three bookes", "category": "spelling", "feedback": "On ajoute -es seulement après s, x, ch ou sh. Après k, on ajoute juste -s : books."}], "pool": "lesson", "lessonId": "en.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l09.e02', 'en', 'en.l09', 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.ten','en.g05.have_has']::text[], 'mcq', 'lesson', 'Comment dit-on « J''ai dix ans » en anglais ?', array['I am ten']::text[], 'Pour donner son âge, l''anglais utilise le verbe être : I am ten (littéralement « je suis dix »). On peut aussi dire I am ten years old, mais years old n''est pas obligatoire.', 2, '{"id": "en.l09.e02", "unitIds": ["en.g03.be_affirmative", "en.v.ten", "en.g05.have_has"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « J''ai dix ans » en anglais ?", "promptLanguage": "fr", "options": ["I am ten", "I have ten", "I has ten", "I ten"], "answer": "I am ten", "acceptedAnswers": ["I am ten"], "hint": "En anglais, on dit son âge avec le verbe être.", "explanation": "Pour donner son âge, l''anglais utilise le verbe être : I am ten (littéralement « je suis dix »). On peut aussi dire I am ten years old, mais years old n''est pas obligatoire.", "tip": "L''âge se dit avec be : I am ten, jamais « I have ten ».", "extraExample": {"text": "He is five.", "translation": "Il a cinq ans."}, "errorPatterns": [{"equals": "i have ten", "category": "verb_tense", "feedback": "Pour l''âge, l''anglais utilise le verbe être et non « avoir » : I am ten."}, {"equals": "i has ten", "category": "verb_tense", "feedback": "Pour l''âge, on utilise le verbe être : I am ten. Et has ne va qu''avec he, she, it."}, {"equals": "i ten", "category": "grammar", "feedback": "Il manque le verbe être : I am ten."}], "pool": "lesson", "lessonId": "en.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l09.e03', 'en', 'en.l09', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.one','en.v.two','en.v.three','en.v.four','en.v.five']::text[], 'match', 'lesson', 'Les nombres de 1 à 5 avec des noms : one, two, three, four, five', '{}'::text[], 'Avec one, le nom reste au singulier : one dog. À partir de two, le nom est au pluriel : two keys, four children (pluriel irrégulier).', 1, '{"id": "en.l09.e03", "unitIds": ["en.g07.plural_nouns", "en.v.one", "en.v.two", "en.v.three", "en.v.four", "en.v.five"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les nombres de 1 à 5 avec des noms : one, two, three, four, five", "promptLanguage": "fr", "pairs": [{"left": "one dog", "right": "un chien"}, {"left": "two keys", "right": "deux clés"}, {"left": "three bags", "right": "trois sacs"}, {"left": "four children", "right": "quatre enfants"}, {"left": "five books", "right": "cinq livres"}], "answer": "one dog = un chien ; two keys = deux clés ; three bags = trois sacs ; four children = quatre enfants ; five books = cinq livres", "acceptedAnswers": [], "explanation": "Avec one, le nom reste au singulier : one dog. À partir de two, le nom est au pluriel : two keys, four children (pluriel irrégulier).", "tip": "One + singulier ; two et plus + pluriel.", "extraExample": {"text": "one friend and two friends", "translation": "un ami et deux amis"}, "pool": "lesson", "lessonId": "en.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l09.e04', 'en', 'en.l09', 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.v.son','en.v.six']::text[], 'fill_blank', 'lesson', 'Anna has a son. ___ son is six. (Son fils a six ans.)', array['Her']::text[], 'Le possessif dépend de celui qui possède. Anna est une femme, donc her son. His serait pour un homme, its pour un animal ou une chose.', 2, '{"id": "en.l09.e04", "unitIds": ["en.g06.possessive_adjectives", "en.v.son", "en.v.six"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le possessif qui convient.", "prompt": "Anna has a son. ___ son is six. (Son fils a six ans.)", "promptLanguage": "en", "options": ["Her", "His", "Its"], "answer": "Her", "acceptedAnswers": ["Her"], "hint": "Qui possède le fils ? Anna : une femme.", "explanation": "Le possessif dépend de celui qui possède. Anna est une femme, donc her son. His serait pour un homme, its pour un animal ou une chose.", "tip": "Possesseur féminin : her. Possesseur masculin : his.", "extraExample": {"text": "Tom has a daughter. His daughter is seven.", "translation": "Tom a une fille. Sa fille a sept ans."}, "errorPatterns": [{"equals": "his", "category": "grammar", "feedback": "His est pour un possesseur masculin. Anna est une femme : her son."}, {"equals": "its", "category": "grammar", "feedback": "Its est pour un animal ou une chose. Pour Anna, on dit her."}], "pool": "lesson", "lessonId": "en.l09", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l09.e05', 'en', 'en.l09', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.eight','en.v.key','en.g05.have_has']::text[], 'fill_blank', 'lesson', 'I have eight ___. (J''ai huit clés.)', array['keys']::text[], 'Après eight, le nom est au pluriel : on ajoute -s à key, ce qui donne keys. Après une voyelle + y, le y ne change pas.', 2, '{"id": "en.l09.e05", "unitIds": ["en.g07.plural_nouns", "en.v.eight", "en.v.key", "en.g05.have_has"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "I have eight ___. (J''ai huit clés.)", "promptLanguage": "en", "options": ["keys", "key", "keies"], "answer": "keys", "acceptedAnswers": ["keys"], "hint": "Il y a huit clés : le nom est au pluriel.", "explanation": "Après eight, le nom est au pluriel : on ajoute -s à key, ce qui donne keys. Après une voyelle + y, le y ne change pas.", "tip": "Key fait keys : on ajoute simplement -s.", "extraExample": {"text": "We have eight books.", "translation": "Nous avons huit livres."}, "errorPatterns": [{"equals": "key", "category": "grammar", "feedback": "Après eight, le nom est au pluriel : on ajoute -s, keys."}, {"equals": "keies", "category": "spelling", "feedback": "Key fait keys : après une voyelle + y, on ajoute seulement -s."}], "pool": "lesson", "lessonId": "en.l09", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l09.e06', 'en', 'en.l09', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.six','en.v.people','en.v.home']::text[], 'reorder', 'lesson', 'Six personnes sont à la maison.', array['Six people are at home']::text[], 'Six people : people est déjà un pluriel, donc pas de s, et le verbe est are. À la maison se dit at home.', 2, '{"id": "en.l09.e06", "unitIds": ["en.g07.plural_nouns", "en.v.six", "en.v.people", "en.v.home"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former une phrase.", "prompt": "Six personnes sont à la maison.", "promptLanguage": "fr", "tokens": ["home", "Six", "at", "are", "people"], "answer": "Six people are at home", "acceptedAnswers": ["Six people are at home"], "hint": "Le nombre vient en premier, puis people, puis are.", "explanation": "Six people : people est déjà un pluriel, donc pas de s, et le verbe est are. À la maison se dit at home.", "tip": "Nombre + people + are : six people are.", "extraExample": {"text": "Four people are at school.", "translation": "Quatre personnes sont à l''école."}, "pool": "lesson", "lessonId": "en.l09", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l09.e07', 'en', 'en.l09', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.ten','en.v.child','en.v.school']::text[], 'translation', 'lesson', 'Dix enfants sont à l''école.', array['Ten children are at school','Ten children are at the school','Ten kids are at school','Ten kids are at the school']::text[], 'Après ten, le nom est au pluriel. Child a un pluriel irrégulier : children. Le sujet est au pluriel : le verbe est are. À l''école se dit at school.', 2, '{"id": "en.l09.e07", "unitIds": ["en.g07.plural_nouns", "en.v.ten", "en.v.child", "en.v.school"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Dix enfants sont à l''école.", "promptLanguage": "fr", "answer": "Ten children are at school", "acceptedAnswers": ["Ten children are at school", "Ten children are at the school", "Ten kids are at school", "Ten kids are at the school"], "hint": "Le pluriel de child est irrégulier.", "explanation": "Après ten, le nom est au pluriel. Child a un pluriel irrégulier : children. Le sujet est au pluriel : le verbe est are. À l''école se dit at school.", "tip": "Child → children : jamais « childs ».", "extraExample": {"text": "Nine children are at home.", "translation": "Neuf enfants sont à la maison."}, "errorPatterns": [{"contains": "ten childs", "category": "spelling", "feedback": "Le pluriel de child est children, pas « childs »."}, {"contains": "ten childrens", "category": "spelling", "feedback": "Children est déjà un pluriel : pas de s à la fin."}, {"contains": "children is", "category": "conjugation", "feedback": "Children est un pluriel : le verbe est are, pas is."}], "pool": "lesson", "lessonId": "en.l09", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l09.e08', 'en', 'en.l09', 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.g03.be_affirmative','en.v.six','en.v.nine','en.v.daughter']::text[], 'translation', 'lesson', 'Mon fils a six ans et ma fille a neuf ans.', array['My son is six and my daughter is nine','My son is six years old and my daughter is nine years old','My son is six years old and my daughter is nine','My son is six and my daughter is nine years old']::text[], 'Mon et ma se disent my. L''âge s''exprime avec le verbe être : my son is six, my daughter is nine. On n''utilise pas have pour l''âge.', 3, '{"id": "en.l09.e08", "unitIds": ["en.g06.possessive_adjectives", "en.g03.be_affirmative", "en.v.six", "en.v.nine", "en.v.daughter"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais. « et » = and.", "prompt": "Mon fils a six ans et ma fille a neuf ans.", "promptLanguage": "fr", "answer": "My son is six and my daughter is nine", "acceptedAnswers": ["My son is six and my daughter is nine", "My son is six years old and my daughter is nine years old", "My son is six years old and my daughter is nine", "My son is six and my daughter is nine years old"], "hint": "L''âge se dit avec le verbe être.", "explanation": "Mon et ma se disent my. L''âge s''exprime avec le verbe être : my son is six, my daughter is nine. On n''utilise pas have pour l''âge.", "tip": "Âge = be : my son is six. Jamais « has six ».", "extraExample": {"text": "My friend is ten.", "translation": "Mon ami a dix ans."}, "errorPatterns": [{"contains": "son has", "category": "verb_tense", "feedback": "Pour l''âge, l''anglais utilise le verbe être : my son is six."}, {"contains": "daughter has", "category": "verb_tense", "feedback": "Pour l''âge, l''anglais utilise le verbe être : my daughter is nine."}, {"contains": "the my", "category": "grammar", "feedback": "On n''utilise pas the avec un possessif : my son, my daughter."}], "pool": "lesson", "lessonId": "en.l09", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l09.e09', 'en', 'en.l09', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.seven','en.v.bag']::text[], 'free_answer', 'lesson', 'Comment dit-on « sept sacs » en anglais ?', array['seven bags']::text[], 'Sept se dit seven. Après le nombre, le nom est au pluriel : seven bags.', 2, '{"id": "en.l09.e09", "unitIds": ["en.g07.plural_nouns", "en.v.seven", "en.v.bag"], "type": "free_answer", "difficulty": 2, "instruction": "Écris l''expression en anglais.", "prompt": "Comment dit-on « sept sacs » en anglais ?", "promptLanguage": "fr", "answer": "seven bags", "acceptedAnswers": ["seven bags"], "hint": "Sept se dit avec un v. N''oublie pas le pluriel.", "explanation": "Sept se dit seven. Après le nombre, le nom est au pluriel : seven bags.", "tip": "Seven (sept) s''écrit avec un v.", "extraExample": {"text": "seven keys", "translation": "sept clés"}, "errorPatterns": [{"equals": "seven bag", "category": "grammar", "feedback": "Après seven, le nom est au pluriel : seven bags."}, {"contains": "sept", "category": "vocabulary", "feedback": "En anglais, « sept » se dit seven."}, {"contains": "seven a", "category": "grammar", "feedback": "On n''utilise pas a devant un pluriel : seven bags."}], "pool": "lesson", "lessonId": "en.l09", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l09.e10', 'en', 'en.l09', 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.g05.have_has','en.v.two','en.v.dog','en.v.house']::text[], 'free_answer', 'lesson', 'Comment dit-on « Nous avons deux chiens et une maison » en anglais ?', array['We have two dogs and a house','We have two dogs and a home']::text[], 'Nous avons = we have. Deux chiens est au pluriel : two dogs. Une maison est au singulier : a house, avec a.', 3, '{"id": "en.l09.e10", "unitIds": ["en.g07.plural_nouns", "en.g05.have_has", "en.v.two", "en.v.dog", "en.v.house"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Nous avons deux chiens et une maison » en anglais ?", "promptLanguage": "fr", "answer": "We have two dogs and a house", "acceptedAnswers": ["We have two dogs and a house", "We have two dogs and a home"], "hint": "Pour posséder, on utilise have. Deux chiens est au pluriel, une maison au singulier.", "explanation": "Nous avons = we have. Deux chiens est au pluriel : two dogs. Une maison est au singulier : a house, avec a.", "tip": "Plusieurs = nom + s ; un seul = a + nom.", "extraExample": {"text": "They have three cars and a dog.", "translation": "Ils ont trois voitures et un chien."}, "errorPatterns": [{"contains": "two dog and", "category": "grammar", "feedback": "Après two, le nom est au pluriel : two dogs."}, {"contains": "we has", "category": "conjugation", "feedback": "Has s''utilise seulement avec he, she et it. Avec we, on dit have."}, {"contains": "we are", "category": "verb_tense", "feedback": "Pour posséder, on utilise have et non être : we have two dogs."}], "pool": "lesson", "lessonId": "en.l09", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l10.e01', 'en', 'en.l10', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.go']::text[], 'mcq', 'lesson', 'Comment dit-on « Je rentre à la maison » en anglais ?', array['I go home.']::text[], 'Avec I, on utilise le verbe à sa forme de base : I go. On n''ajoute ni -s, ni am. Et devant home, on ne met pas to : go home.', 1, '{"id": "en.l10.e01", "unitIds": ["en.g08.verbs_base_form", "en.v.go"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « Je rentre à la maison » en anglais ?", "promptLanguage": "fr", "options": ["I go home.", "I goes home.", "I am go home.", "I go to home."], "answer": "I go home.", "acceptedAnswers": ["I go home."], "hint": "Avec I, le verbe garde sa forme de base, et on n''ajoute rien devant home.", "explanation": "Avec I, on utilise le verbe à sa forme de base : I go. On n''ajoute ni -s, ni am. Et devant home, on ne met pas to : go home.", "tip": "I + verbe tel quel. Et go home, sans to.", "extraExample": {"text": "We go home.", "translation": "Nous rentrons à la maison."}, "errorPatterns": [{"equals": "I goes home.", "category": "conjugation", "feedback": "Avec I, le verbe ne prend pas de -s : on dit I go. Le -s viendra plus tard, avec d''autres sujets."}, {"equals": "I am go home.", "category": "grammar", "feedback": "Am est le verbe être : on ne le met pas devant un autre verbe. On dit simplement I go home."}, {"equals": "I go to home.", "category": "preposition", "feedback": "Devant home, on n''ajoute pas to. On dit go home."}], "pool": "lesson", "lessonId": "en.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l10.e02', 'en', 'en.l10', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.do']::text[], 'mcq', 'lesson', 'Dans « I do it », que veut dire do ?', array['faire']::text[], 'Do veut dire « faire » une action ou une tâche : I do it = je le fais. Go veut dire « aller », give « donner » et take « prendre ».', 1, '{"id": "en.l10.e02", "unitIds": ["en.g08.verbs_base_form", "en.v.do"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon sens.", "prompt": "Dans « I do it », que veut dire do ?", "promptLanguage": "fr", "options": ["faire", "aller", "donner", "prendre"], "answer": "faire", "acceptedAnswers": ["faire"], "hint": "I do it se traduit par « Je le fais ».", "explanation": "Do veut dire « faire » une action ou une tâche : I do it = je le fais. Go veut dire « aller », give « donner » et take « prendre ».", "tip": "Do = faire une action. Il ne change pas avec I, you, we, they.", "extraExample": {"text": "You do it for your family.", "translation": "Tu le fais pour ta famille."}, "errorPatterns": [{"equals": "aller", "category": "vocabulary", "feedback": "« Aller » se dit go. Do veut dire « faire »."}, {"equals": "donner", "category": "vocabulary", "feedback": "« Donner » se dit give. Do veut dire « faire »."}, {"equals": "prendre", "category": "vocabulary", "feedback": "« Prendre » se dit take. Do veut dire « faire »."}], "pool": "lesson", "lessonId": "en.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l10.e03', 'en', 'en.l10', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.go','en.v.do','en.v.make','en.v.take','en.v.give']::text[], 'match', 'lesson', 'Les verbes essentiels : go home, do it, make cars, take the key, give a book', '{}'::text[], 'Go = aller, do = faire (une action), make = fabriquer ou créer, take = prendre, give = donner. On dit go home sans to.', 1, '{"id": "en.l10.e03", "unitIds": ["en.g08.verbs_base_form", "en.v.go", "en.v.do", "en.v.make", "en.v.take", "en.v.give"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les verbes essentiels : go home, do it, make cars, take the key, give a book", "promptLanguage": "fr", "pairs": [{"left": "go home", "right": "rentrer à la maison"}, {"left": "do it", "right": "le faire"}, {"left": "make cars", "right": "fabriquer des voitures"}, {"left": "take the key", "right": "prendre la clé"}, {"left": "give a book", "right": "donner un livre"}], "answer": "go home = rentrer à la maison ; do it = le faire ; make cars = fabriquer des voitures ; take the key = prendre la clé ; give a book = donner un livre", "acceptedAnswers": [], "explanation": "Go = aller, do = faire (une action), make = fabriquer ou créer, take = prendre, give = donner. On dit go home sans to.", "tip": "Go = aller, take = prendre, give = donner : ce sont trois verbes à retenir avec leur objet.", "extraExample": {"text": "I take the bag and I give the key.", "translation": "Je prends le sac et je donne la clé."}, "pool": "lesson", "lessonId": "en.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l10.e04', 'en', 'en.l10', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.take','en.v.car']::text[], 'fill_blank', 'lesson', 'We ___ the car. (prendre)', array['take']::text[], '« Prendre » se dit take. Avec we, le verbe reste à sa forme de base : we take.', 2, '{"id": "en.l10.e04", "unitIds": ["en.g08.verbs_base_form", "en.v.take", "en.v.car"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase avec le bon verbe.", "prompt": "We ___ the car. (prendre)", "promptLanguage": "en", "options": ["take", "takes", "give", "make"], "answer": "take", "acceptedAnswers": ["take"], "hint": "Le verbe qui veut dire « prendre ».", "explanation": "« Prendre » se dit take. Avec we, le verbe reste à sa forme de base : we take.", "tip": "Avec we : take, sans -s.", "extraExample": {"text": "I take my bag.", "translation": "Je prends mon sac."}, "errorPatterns": [{"equals": "takes", "category": "conjugation", "feedback": "Avec we, le verbe ne prend pas de -s : we take."}, {"equals": "give", "category": "vocabulary", "feedback": "Give veut dire « donner ». Pour « prendre », on dit take."}, {"equals": "make", "category": "vocabulary", "feedback": "Make veut dire « fabriquer, créer ». Pour « prendre », on dit take."}], "pool": "lesson", "lessonId": "en.l10", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l10.e05', 'en', 'en.l10', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.give','en.v.book']::text[], 'fill_blank', 'lesson', 'They ___ a book to Tom. (donner)', array['give']::text[], '« Donner » se dit give. Avec they, le verbe reste à sa forme de base : they give.', 2, '{"id": "en.l10.e05", "unitIds": ["en.g08.verbs_base_form", "en.v.give", "en.v.book"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase avec le bon verbe.", "prompt": "They ___ a book to Tom. (donner)", "promptLanguage": "en", "options": ["give", "gives", "take", "go"], "answer": "give", "acceptedAnswers": ["give"], "hint": "Le verbe qui veut dire « donner ».", "explanation": "« Donner » se dit give. Avec they, le verbe reste à sa forme de base : they give.", "tip": "Avec they : give, sans -s.", "extraExample": {"text": "You give your phone to your mother.", "translation": "Tu donnes ton téléphone à ta mère."}, "errorPatterns": [{"equals": "gives", "category": "conjugation", "feedback": "Avec they, le verbe ne prend pas de -s : they give."}, {"equals": "take", "category": "vocabulary", "feedback": "Take veut dire « prendre ». Pour « donner », on dit give."}, {"equals": "go", "category": "vocabulary", "feedback": "Go veut dire « aller ». Pour « donner », on dit give."}], "pool": "lesson", "lessonId": "en.l10", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version