insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l10.e06', 'en', 'en.l10', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.do','en.v.family']::text[], 'reorder', 'lesson', 'Nous le faisons pour notre famille.', array['We do it for our family']::text[], 'L''ordre est : sujet + verbe + complément. We do it, puis for our family. Avec we, do ne change pas.', 2, '{"id": "en.l10.e06", "unitIds": ["en.g08.verbs_base_form", "en.v.do", "en.v.family"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Nous le faisons pour notre famille.", "promptLanguage": "fr", "tokens": ["family", "We", "it", "for", "do", "our"], "answer": "We do it for our family", "acceptedAnswers": ["We do it for our family"], "hint": "Sujet, verbe, puis ce qu''on fait, puis pour qui.", "explanation": "L''ordre est : sujet + verbe + complément. We do it, puis for our family. Avec we, do ne change pas.", "tip": "Sujet + verbe + complément : we do it.", "extraExample": {"text": "They do it for their mother.", "translation": "Ils le font pour leur mère."}, "pool": "lesson", "lessonId": "en.l10", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l10.e07', 'en', 'en.l10', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.take','en.v.car']::text[], 'translation', 'lesson', 'Vous prenez la voiture.', array['You take the car.','You are taking the car.']::text[], 'Vous se traduit you, et « prendre » se dit take. Avec you, le verbe reste à sa forme de base : you take.', 2, '{"id": "en.l10.e07", "unitIds": ["en.g08.verbs_base_form", "en.v.take", "en.v.car"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Vous prenez la voiture.", "promptLanguage": "fr", "answer": "You take the car.", "acceptedAnswers": ["You take the car.", "You are taking the car."], "hint": "Vous = you. Le verbe ne change pas.", "explanation": "Vous se traduit you, et « prendre » se dit take. Avec you, le verbe reste à sa forme de base : you take.", "tip": "Tu et vous se disent tous les deux you, avec le même verbe.", "extraExample": {"text": "You take the key.", "translation": "Tu prends la clé."}, "errorPatterns": [{"contains": "you takes", "category": "conjugation", "feedback": "Avec you, le verbe ne prend pas de -s : you take."}, {"contains": "you are take", "category": "grammar", "feedback": "Pas besoin du verbe être ici : on dit simplement you take."}, {"contains": "you give", "category": "vocabulary", "feedback": "Give veut dire « donner ». Pour « prendre », on dit take."}], "pool": "lesson", "lessonId": "en.l10", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l10.e08', 'en', 'en.l10', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.give','en.v.key']::text[], 'translation', 'lesson', 'Ils donnent la clé à Anna.', array['They give the key to Anna.','They give Anna the key.','They are giving the key to Anna.','They are giving Anna the key.']::text[], 'Ils se traduit they, et « donner » se dit give. Avec they, le verbe ne change pas : they give. On peut dire the key to Anna ou Anna the key.', 3, '{"id": "en.l10.e08", "unitIds": ["en.g08.verbs_base_form", "en.v.give", "en.v.key"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Ils donnent la clé à Anna.", "promptLanguage": "fr", "answer": "They give the key to Anna.", "acceptedAnswers": ["They give the key to Anna.", "They give Anna the key.", "They are giving the key to Anna.", "They are giving Anna the key."], "hint": "Ils = they. Donner = give.", "explanation": "Ils se traduit they, et « donner » se dit give. Avec they, le verbe ne change pas : they give. On peut dire the key to Anna ou Anna the key.", "tip": "They give : pas de -s, comme avec I, you, we.", "extraExample": {"text": "We give a book to Tom.", "translation": "Nous donnons un livre à Tom."}, "errorPatterns": [{"contains": "they gives", "category": "conjugation", "feedback": "Avec they, le verbe ne prend pas de -s : they give."}, {"contains": "they take", "category": "vocabulary", "feedback": "Take veut dire « prendre ». Pour « donner », on dit give."}, {"contains": "they are give", "category": "grammar", "feedback": "Pas besoin du verbe être ici : on dit simplement they give."}], "pool": "lesson", "lessonId": "en.l10", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l10.e09', 'en', 'en.l10', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.go','en.v.school']::text[], 'free_answer', 'lesson', 'Comment dit-on « Tu vas à l''école » en anglais ?', array['You go to school.','You go to the school.','You are going to school.','You are going to the school.']::text[], 'Tu se traduit you, et « aller » se dit go. Avec you, le verbe reste à sa forme de base : you go. À l''école se dit to school, sans article.', 3, '{"id": "en.l10.e09", "unitIds": ["en.g08.verbs_base_form", "en.v.go", "en.v.school"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Tu vas à l''école » en anglais ?", "promptLanguage": "fr", "answer": "You go to school.", "acceptedAnswers": ["You go to school.", "You go to the school.", "You are going to school.", "You are going to the school."], "hint": "Tu = you. Aller = go.", "explanation": "Tu se traduit you, et « aller » se dit go. Avec you, le verbe reste à sa forme de base : you go. À l''école se dit to school, sans article.", "tip": "I, you, we, they : go ne change jamais.", "extraExample": {"text": "They go to school.", "translation": "Ils vont à l''école."}, "errorPatterns": [{"contains": "you goes", "category": "conjugation", "feedback": "Avec you, le verbe ne prend pas de -s : you go."}, {"contains": "you are go", "category": "grammar", "feedback": "Pas besoin du verbe être ici : on dit simplement you go."}, {"contains": "you make", "category": "vocabulary", "feedback": "Make veut dire « fabriquer ». Pour « aller », on dit go."}], "pool": "lesson", "lessonId": "en.l10", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l10.e10', 'en', 'en.l10', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.make','en.v.bag']::text[], 'free_answer', 'lesson', 'Comment dit-on « Je fabrique un sac pour ma sœur » en anglais ?', array['I make a bag for my sister.','I make my sister a bag.','I am making a bag for my sister.','I am making my sister a bag.']::text[], '« Fabriquer » se dit make. Avec I, le verbe reste à sa forme de base : I make. Pour ma sœur se dit for my sister.', 3, '{"id": "en.l10.e10", "unitIds": ["en.g08.verbs_base_form", "en.v.make", "en.v.bag"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Je fabrique un sac pour ma sœur » en anglais ?", "promptLanguage": "fr", "answer": "I make a bag for my sister.", "acceptedAnswers": ["I make a bag for my sister.", "I make my sister a bag.", "I am making a bag for my sister.", "I am making my sister a bag."], "hint": "Fabriquer = make. Pour = for.", "explanation": "« Fabriquer » se dit make. Avec I, le verbe reste à sa forme de base : I make. Pour ma sœur se dit for my sister.", "tip": "Make = fabriquer, créer. Avec I : make, sans rien ajouter.", "extraExample": {"text": "We make a house for the dog.", "translation": "Nous fabriquons une niche pour le chien."}, "errorPatterns": [{"contains": "i makes", "category": "conjugation", "feedback": "Avec I, le verbe ne prend pas de -s : I make."}, {"contains": "i am make", "category": "grammar", "feedback": "Am est le verbe être : on ne le met pas devant un autre verbe. On dit I make."}, {"contains": "i do a bag", "category": "word_confusion", "feedback": "Pour fabriquer quelque chose, on dit make. Do s''utilise pour une tâche ou une activité."}], "pool": "lesson", "lessonId": "en.l10", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l11.e01', 'en', 'en.l11', 'en.g09.do_vs_make', array['en.g09.do_vs_make','en.v.homework','en.v.do']::text[], 'mcq', 'lesson', 'I ___ my homework.', array['do']::text[], 'Les devoirs sont une tâche à accomplir : on dit do homework. On n''ajoute pas de -s avec I.', 1, '{"id": "en.l11.e01", "unitIds": ["en.g09.do_vs_make", "en.v.homework", "en.v.do"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon verbe.", "prompt": "I ___ my homework.", "promptLanguage": "en", "options": ["do", "make", "does", "makes"], "answer": "do", "acceptedAnswers": ["do"], "hint": "Les devoirs sont une tâche à accomplir.", "explanation": "Les devoirs sont une tâche à accomplir : on dit do homework. On n''ajoute pas de -s avec I.", "tip": "Les devoirs, ça se fait : do homework, jamais make homework.", "extraExample": {"text": "We do our homework at school.", "translation": "Nous faisons nos devoirs à l''école."}, "errorPatterns": [{"equals": "make", "category": "word_confusion", "feedback": "Make sert à créer ou fabriquer quelque chose. Les devoirs sont une tâche : on dit do homework."}, {"equals": "does", "category": "conjugation", "feedback": "Avec I, le verbe garde sa forme de base : I do, sans -s."}, {"equals": "makes", "category": "word_confusion", "feedback": "Make ne convient pas ici, et le -s n''existe pas avec I. Les devoirs, ça se fait : I do my homework."}], "pool": "lesson", "lessonId": "en.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l11.e02', 'en', 'en.l11', 'en.g09.do_vs_make', array['en.g09.do_vs_make','en.v.decision','en.v.make']::text[], 'mcq', 'lesson', 'Comment dit-on « Tu prends une décision » en anglais ?', array['You make a decision.']::text[], '« Prendre une décision » se dit make a decision. C''est une expression à apprendre par cœur. Avec you, make ne prend pas de -s.', 1, '{"id": "en.l11.e02", "unitIds": ["en.g09.do_vs_make", "en.v.decision", "en.v.make"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « Tu prends une décision » en anglais ?", "promptLanguage": "fr", "options": ["You make a decision.", "You do a decision.", "You makes a decision."], "answer": "You make a decision.", "acceptedAnswers": ["You make a decision."], "hint": "Une décision, ça se « fabrique » : c''est une expression avec make.", "explanation": "« Prendre une décision » se dit make a decision. C''est une expression à apprendre par cœur. Avec you, make ne prend pas de -s.", "tip": "Make a decision, make a mistake : des expressions à retenir telles quelles.", "extraExample": {"text": "We make a decision.", "translation": "Nous prenons une décision."}, "errorPatterns": [{"equals": "you do a decision.", "category": "word_confusion", "feedback": "Do ne s''emploie pas avec decision. L''expression est make a decision."}, {"equals": "you makes a decision.", "category": "conjugation", "feedback": "Avec you, le verbe ne prend pas de -s : you make."}], "pool": "lesson", "lessonId": "en.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l11.e03', 'en', 'en.l11', 'en.g09.do_vs_make', array['en.g09.do_vs_make','en.v.homework','en.v.mistake','en.v.dinner','en.v.decision','en.v.coffee']::text[], 'match', 'lesson', 'Do ou make : do homework, make a mistake, make dinner, make a decision, make coffee', '{}'::text[], 'Do s''emploie pour les devoirs, une tâche. Make s''emploie pour créer ou préparer quelque chose (dinner, coffee) et dans les expressions make a mistake et make a decision.', 1, '{"id": "en.l11.e03", "unitIds": ["en.g09.do_vs_make", "en.v.homework", "en.v.mistake", "en.v.dinner", "en.v.decision", "en.v.coffee"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Do ou make : do homework, make a mistake, make dinner, make a decision, make coffee", "promptLanguage": "fr", "pairs": [{"left": "do homework", "right": "faire ses devoirs"}, {"left": "make a mistake", "right": "faire une erreur"}, {"left": "make dinner", "right": "préparer le dîner"}, {"left": "make a decision", "right": "prendre une décision"}, {"left": "make coffee", "right": "faire du café"}], "answer": "do homework = faire ses devoirs ; make a mistake = faire une erreur ; make dinner = préparer le dîner ; make a decision = prendre une décision ; make coffee = faire du café", "acceptedAnswers": [], "explanation": "Do s''emploie pour les devoirs, une tâche. Make s''emploie pour créer ou préparer quelque chose (dinner, coffee) et dans les expressions make a mistake et make a decision.", "tip": "Un seul do à retenir pour l''instant : do homework. Le reste de la liste est en make.", "extraExample": {"text": "I make coffee and I do my homework.", "translation": "Je fais du café et je fais mes devoirs."}, "pool": "lesson", "lessonId": "en.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l11.e04', 'en', 'en.l11', 'en.g09.do_vs_make', array['en.g09.do_vs_make','en.v.mistake','en.v.make']::text[], 'fill_blank', 'lesson', 'Sorry, I ___ a mistake.', array['make']::text[], '« Faire une erreur » se dit make a mistake : c''est une expression à apprendre par cœur. Avec I, make ne prend pas de -s.', 2, '{"id": "en.l11.e04", "unitIds": ["en.g09.do_vs_make", "en.v.mistake", "en.v.make"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon verbe.", "prompt": "Sorry, I ___ a mistake.", "promptLanguage": "en", "options": ["make", "do", "take", "give"], "answer": "make", "acceptedAnswers": ["make"], "hint": "« Faire une erreur » est une expression toute faite.", "explanation": "« Faire une erreur » se dit make a mistake : c''est une expression à apprendre par cœur. Avec I, make ne prend pas de -s.", "tip": "Une erreur, ça se « fabrique » : make a mistake.", "extraExample": {"text": "You make a mistake.", "translation": "Tu fais une erreur."}, "errorPatterns": [{"equals": "do", "category": "word_confusion", "feedback": "Le français dit « faire une erreur », mais l''anglais dit make a mistake. Do ne s''emploie pas avec mistake."}, {"equals": "makes", "category": "conjugation", "feedback": "Avec I, le verbe ne prend pas de -s : I make."}], "pool": "lesson", "lessonId": "en.l11", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l11.e05', 'en', 'en.l11', 'en.g09.do_vs_make', array['en.g09.do_vs_make','en.v.dinner','en.v.family']::text[], 'fill_blank', 'lesson', 'My mother and father ___ dinner for the family.', array['make']::text[], 'On prépare le dîner : on crée un repas, donc make dinner. Ma mère et mon père, c''est « ils » : le verbe ne prend pas de -s.', 2, '{"id": "en.l11.e05", "unitIds": ["en.g09.do_vs_make", "en.v.dinner", "en.v.family"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon verbe.", "prompt": "My mother and father ___ dinner for the family.", "promptLanguage": "en", "options": ["make", "do", "go", "makes"], "answer": "make", "acceptedAnswers": ["make"], "hint": "Préparer un repas, c''est créer quelque chose.", "explanation": "On prépare le dîner : on crée un repas, donc make dinner. Ma mère et mon père, c''est « ils » : le verbe ne prend pas de -s.", "tip": "Un repas ou une boisson qu''on prépare : make dinner, make coffee.", "extraExample": {"text": "We make dinner at home.", "translation": "Nous préparons le dîner à la maison."}, "errorPatterns": [{"equals": "do", "category": "word_confusion", "feedback": "On prépare le dîner : on dit make dinner, pas do dinner."}, {"equals": "makes", "category": "conjugation", "feedback": "Ma mère et mon père, c''est comme they : le verbe ne prend pas de -s."}], "pool": "lesson", "lessonId": "en.l11", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l11.e06', 'en', 'en.l11', 'en.g09.do_vs_make', array['en.g09.do_vs_make','en.v.decision']::text[], 'reorder', 'lesson', 'Tom et Anna prennent une décision.', array['Tom and Anna make a decision','Anna and Tom make a decision']::text[], 'Tom and Anna, c''est « ils » : make reste à sa forme de base. L''expression complète est make a decision.', 2, '{"id": "en.l11.e06", "unitIds": ["en.g09.do_vs_make", "en.v.decision"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Tom et Anna prennent une décision.", "promptLanguage": "fr", "tokens": ["decision", "Tom", "make", "and", "Anna", "a"], "answer": "Tom and Anna make a decision", "acceptedAnswers": ["Tom and Anna make a decision", "Anna and Tom make a decision"], "hint": "Sujet (Tom et Anna), puis make, puis a decision.", "explanation": "Tom and Anna, c''est « ils » : make reste à sa forme de base. L''expression complète est make a decision.", "tip": "Deux personnes, c''est « ils » : pas de -s sur le verbe.", "extraExample": {"text": "My brother and sister make a mistake.", "translation": "Mon frère et ma sœur font une erreur."}, "pool": "lesson", "lessonId": "en.l11", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l11.e07', 'en', 'en.l11', 'en.g09.do_vs_make', array['en.g09.do_vs_make','en.v.homework','en.v.do']::text[], 'translation', 'lesson', 'Je fais mes devoirs.', array['I do my homework.','I am doing my homework.']::text[], 'Les devoirs sont une tâche à accomplir : on dit do homework. Mes devoirs se traduit par my homework : homework ne prend pas de -s.', 2, '{"id": "en.l11.e07", "unitIds": ["en.g09.do_vs_make", "en.v.homework", "en.v.do"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Je fais mes devoirs.", "promptLanguage": "fr", "answer": "I do my homework.", "acceptedAnswers": ["I do my homework.", "I am doing my homework."], "hint": "Les devoirs sont une tâche à accomplir.", "explanation": "Les devoirs sont une tâche à accomplir : on dit do homework. Mes devoirs se traduit par my homework : homework ne prend pas de -s.", "tip": "Do my homework : on « fait » une tâche avec do.", "extraExample": {"text": "They do their homework.", "translation": "Ils font leurs devoirs."}, "errorPatterns": [{"contains": "make my homework", "category": "word_confusion", "feedback": "Make sert à créer quelque chose. Les devoirs sont une tâche : on dit do my homework."}, {"contains": "homeworks", "category": "spelling", "feedback": "Homework ne prend pas de -s : on dit my homework, même pour plusieurs devoirs."}, {"contains": "i does", "category": "conjugation", "feedback": "Avec I, le verbe ne prend pas de -s : I do."}], "pool": "lesson", "lessonId": "en.l11", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l11.e08', 'en', 'en.l11', 'en.g09.do_vs_make', array['en.g09.do_vs_make','en.v.dinner','en.v.friend']::text[], 'translation', 'lesson', 'Nous préparons le dîner pour nos amis.', array['We make dinner for our friends.','We make the dinner for our friends.','We make a dinner for our friends.','We are making dinner for our friends.','We are making the dinner for our friends.','We prepare dinner for our friends.','We prepare the dinner for our friends.','We are preparing dinner for our friends.','We cook dinner for our friends.','We cook the dinner for our friends.','We are cooking dinner for our friends.']::text[], 'On prépare le dîner : on dit make dinner. Nos amis se traduit our friends, avec un -s au pluriel du nom, mais pas sur le verbe.', 3, '{"id": "en.l11.e08", "unitIds": ["en.g09.do_vs_make", "en.v.dinner", "en.v.friend"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Nous préparons le dîner pour nos amis.", "promptLanguage": "fr", "answer": "We make dinner for our friends.", "acceptedAnswers": ["We make dinner for our friends.", "We make the dinner for our friends.", "We make a dinner for our friends.", "We are making dinner for our friends.", "We are making the dinner for our friends.", "We prepare dinner for our friends.", "We prepare the dinner for our friends.", "We are preparing dinner for our friends.", "We cook dinner for our friends.", "We cook the dinner for our friends.", "We are cooking dinner for our friends."], "hint": "Préparer un repas se dit avec make.", "explanation": "On prépare le dîner : on dit make dinner. Nos amis se traduit our friends, avec un -s au pluriel du nom, mais pas sur le verbe.", "tip": "Make dinner pour préparer le repas du soir.", "extraExample": {"text": "You make coffee for your friends.", "translation": "Tu fais du café pour tes amis."}, "errorPatterns": [{"contains": "do dinner", "category": "word_confusion", "feedback": "On prépare le dîner : on dit make dinner, pas do dinner."}, {"contains": "we makes", "category": "conjugation", "feedback": "Avec we, le verbe ne prend pas de -s : we make."}, {"contains": "we take dinner", "category": "vocabulary", "feedback": "Take veut dire « prendre ». Pour préparer le dîner, on dit make dinner."}], "pool": "lesson", "lessonId": "en.l11", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l11.e09', 'en', 'en.l11', 'en.g09.do_vs_make', array['en.g09.do_vs_make','en.v.mistake','en.v.make']::text[], 'free_answer', 'lesson', 'Comment dit-on « Je fais une erreur » en anglais ?', array['I make a mistake.','I am making a mistake.']::text[], '« Faire une erreur » se dit make a mistake. C''est une expression à apprendre par cœur : on n''utilise pas do ici.', 3, '{"id": "en.l11.e09", "unitIds": ["en.g09.do_vs_make", "en.v.mistake", "en.v.make"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Je fais une erreur » en anglais ?", "promptLanguage": "fr", "answer": "I make a mistake.", "acceptedAnswers": ["I make a mistake.", "I am making a mistake."], "hint": "Une expression avec make.", "explanation": "« Faire une erreur » se dit make a mistake. C''est une expression à apprendre par cœur : on n''utilise pas do ici.", "tip": "Erreur = mistake, et le verbe est make.", "extraExample": {"text": "They make a mistake.", "translation": "Ils font une erreur."}, "errorPatterns": [{"contains": "do a mistake", "category": "word_confusion", "feedback": "Le français dit « faire une erreur », mais l''anglais dit make a mistake."}, {"contains": "i makes", "category": "conjugation", "feedback": "Avec I, le verbe ne prend pas de -s : I make."}, {"equals": "i make mistake", "category": "grammar", "feedback": "Il manque l''article : « une erreur » se dit a mistake."}], "pool": "lesson", "lessonId": "en.l11", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l11.e10', 'en', 'en.l11', 'en.g09.do_vs_make', array['en.g09.do_vs_make','en.v.coffee','en.v.wife']::text[], 'free_answer', 'lesson', 'Comment dit-on « Je fais du café pour ma femme » en anglais ?', array['I make coffee for my wife.','I make some coffee for my wife.','I make a coffee for my wife.','I make my wife coffee.','I make my wife a coffee.','I am making coffee for my wife.','I am making some coffee for my wife.','I am making a coffee for my wife.']::text[], 'Préparer du café, c''est créer une boisson : on dit make coffee. Pour ma femme se dit for my wife.', 3, '{"id": "en.l11.e10", "unitIds": ["en.g09.do_vs_make", "en.v.coffee", "en.v.wife"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Je fais du café pour ma femme » en anglais ?", "promptLanguage": "fr", "answer": "I make coffee for my wife.", "acceptedAnswers": ["I make coffee for my wife.", "I make some coffee for my wife.", "I make a coffee for my wife.", "I make my wife coffee.", "I make my wife a coffee.", "I am making coffee for my wife.", "I am making some coffee for my wife.", "I am making a coffee for my wife."], "hint": "On prépare une boisson : quel verbe utilises-tu ?", "explanation": "Préparer du café, c''est créer une boisson : on dit make coffee. Pour ma femme se dit for my wife.", "tip": "Café, dîner : on les prépare, donc make coffee, make dinner.", "extraExample": {"text": "We make coffee for our parents.", "translation": "Nous faisons du café pour nos parents."}, "errorPatterns": [{"contains": "do coffee", "category": "word_confusion", "feedback": "On prépare le café : on dit make coffee, pas do coffee."}, {"contains": "i makes", "category": "conjugation", "feedback": "Avec I, le verbe ne prend pas de -s : I make."}, {"contains": "cafe", "category": "vocabulary", "feedback": "En anglais, « café » (la boisson) se dit coffee."}], "pool": "lesson", "lessonId": "en.l11", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l12.e01', 'en', 'en.l12', 'en.g10.want_need_to', array['en.g10.want_need_to','en.v.want','en.v.go']::text[], 'mcq', 'lesson', 'I want ___ go home.', array['to']::text[], 'Quand want est suivi d''un verbe, on met to entre les deux : want to + verbe. On dit donc I want to go home.', 1, '{"id": "en.l12.e01", "unitIds": ["en.g10.want_need_to", "en.v.want", "en.v.go"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le mot qui manque.", "prompt": "I want ___ go home.", "promptLanguage": "en", "options": ["to", "that", "for", "of"], "answer": "to", "acceptedAnswers": ["to"], "hint": "Il faut un petit mot entre want et le verbe go.", "explanation": "Quand want est suivi d''un verbe, on met to entre les deux : want to + verbe. On dit donc I want to go home.", "tip": "Want + verbe ? Ajoute to : want to go.", "extraExample": {"text": "We want to take the car.", "translation": "Nous voulons prendre la voiture."}, "errorPatterns": [{"equals": "that", "category": "grammar", "feedback": "En anglais, on ne dit pas « want that » avant un verbe. On dit want to + verbe : I want to go."}, {"equals": "for", "category": "preposition", "feedback": "For ne s''emploie pas entre want et un verbe. Il faut to : I want to go."}, {"equals": "of", "category": "preposition", "feedback": "Of ne s''emploie pas entre want et un verbe. Il faut to : I want to go."}], "pool": "lesson", "lessonId": "en.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l12.e02', 'en', 'en.l12', 'en.g10.want_need_to', array['en.g10.want_need_to','en.v.need','en.v.take']::text[], 'mcq', 'lesson', 'Comment dit-on « Nous avons besoin de prendre la voiture » ?', array['We need to take the car.']::text[], 'Après need, on met to, puis le verbe à sa forme de base : need to take. Avec we, need ne prend pas de -s.', 1, '{"id": "en.l12.e02", "unitIds": ["en.g10.want_need_to", "en.v.need", "en.v.take"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « Nous avons besoin de prendre la voiture » ?", "promptLanguage": "fr", "options": ["We need to take the car.", "We need take the car.", "We needs to take the car.", "We need to taking the car."], "answer": "We need to take the car.", "acceptedAnswers": ["We need to take the car."], "hint": "Need + to + verbe de base, sans -s ni -ing.", "explanation": "Après need, on met to, puis le verbe à sa forme de base : need to take. Avec we, need ne prend pas de -s.", "tip": "Need + to + verbe de base : rien d''autre à ajouter.", "extraExample": {"text": "You need to go home.", "translation": "Tu as besoin de rentrer à la maison."}, "errorPatterns": [{"equals": "we need take the car.", "category": "grammar", "feedback": "Il manque to entre need et le verbe : need to take."}, {"equals": "we needs to take the car.", "category": "conjugation", "feedback": "Avec we, need ne prend pas de -s : we need."}, {"equals": "we need to taking the car.", "category": "grammar", "feedback": "Après to, le verbe reste à sa forme de base, sans -ing : to take."}], "pool": "lesson", "lessonId": "en.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l12.e03', 'en', 'en.l12', 'en.g10.want_need_to', array['en.g10.want_need_to','en.v.get','en.v.know','en.v.think','en.v.want','en.v.need']::text[], 'match', 'lesson', 'Les nouveaux verbes : I want, I need, I know, I think, I get', '{}'::text[], 'Want = vouloir, need = avoir besoin de, know = savoir ou connaître, think = penser ou croire, get = recevoir ou obtenir. Avec I, ces verbes ne changent pas.', 1, '{"id": "en.l12.e03", "unitIds": ["en.g10.want_need_to", "en.v.get", "en.v.know", "en.v.think", "en.v.want", "en.v.need"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les nouveaux verbes : I want, I need, I know, I think, I get", "promptLanguage": "fr", "pairs": [{"left": "I want", "right": "je veux"}, {"left": "I need", "right": "j''ai besoin de"}, {"left": "I know", "right": "je sais / je connais"}, {"left": "I think", "right": "je pense / je crois"}, {"left": "I get", "right": "je reçois / j''obtiens"}], "answer": "I want = je veux ; I need = j''ai besoin de ; I know = je sais / je connais ; I think = je pense / je crois ; I get = je reçois / j''obtiens", "acceptedAnswers": [], "explanation": "Want = vouloir, need = avoir besoin de, know = savoir ou connaître, think = penser ou croire, get = recevoir ou obtenir. Avec I, ces verbes ne changent pas.", "tip": "Know sert pour savoir et pour connaître : I know the answer, I know Tom.", "extraExample": {"text": "I know Tom and I think he is tired.", "translation": "Je connais Tom et je pense qu''il est fatigué."}, "pool": "lesson", "lessonId": "en.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l12.e04', 'en', 'en.l12', 'en.g10.want_need_to', array['en.g10.want_need_to','en.v.need','en.v.homework']::text[], 'fill_blank', 'lesson', 'You ___ to do your homework. (avoir besoin de)', array['need']::text[], '« Avoir besoin de » se dit need. Il est suivi de to + verbe de base : need to do. Avec you, need ne prend pas de -s.', 2, '{"id": "en.l12.e04", "unitIds": ["en.g10.want_need_to", "en.v.need", "en.v.homework"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon verbe.", "prompt": "You ___ to do your homework. (avoir besoin de)", "promptLanguage": "en", "options": ["need", "know", "think", "needs"], "answer": "need", "acceptedAnswers": ["need"], "hint": "Le verbe qui veut dire « avoir besoin de ».", "explanation": "« Avoir besoin de » se dit need. Il est suivi de to + verbe de base : need to do. Avec you, need ne prend pas de -s.", "tip": "Need to + verbe : j''ai besoin de faire quelque chose.", "extraExample": {"text": "We need to make dinner.", "translation": "Nous avons besoin de préparer le dîner."}, "errorPatterns": [{"equals": "needs", "category": "conjugation", "feedback": "Avec you, le verbe ne prend pas de -s : you need."}, {"equals": "know", "category": "vocabulary", "feedback": "Know veut dire « savoir, connaître ». Pour « avoir besoin de », on dit need."}, {"equals": "think", "category": "vocabulary", "feedback": "Think veut dire « penser ». Pour « avoir besoin de », on dit need."}], "pool": "lesson", "lessonId": "en.l12", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l12.e05', 'en', 'en.l12', 'en.g10.want_need_to', array['en.g10.want_need_to','en.v.get','en.v.phone']::text[], 'fill_blank', 'lesson', 'I ___ a phone from my parents. (recevoir)', array['get','receive']::text[], 'Get veut dire « recevoir » ou « obtenir » : I get a phone = je reçois un téléphone. Avec I, le verbe ne change pas.', 2, '{"id": "en.l12.e05", "unitIds": ["en.g10.want_need_to", "en.v.get", "en.v.phone"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon verbe.", "prompt": "I ___ a phone from my parents. (recevoir)", "promptLanguage": "en", "options": ["get", "know", "think", "want"], "answer": "get", "acceptedAnswers": ["get", "receive"], "hint": "Le verbe qui veut dire « recevoir, obtenir ».", "explanation": "Get veut dire « recevoir » ou « obtenir » : I get a phone = je reçois un téléphone. Avec I, le verbe ne change pas.", "tip": "Get = recevoir, obtenir. C''est l''un des verbes les plus utilisés en anglais.", "extraExample": {"text": "We get a key from the teacher.", "translation": "Nous recevons une clé du professeur."}, "errorPatterns": [{"equals": "know", "category": "vocabulary", "feedback": "Know veut dire « savoir, connaître ». Pour « recevoir », on dit get."}, {"equals": "think", "category": "vocabulary", "feedback": "Think veut dire « penser ». Pour « recevoir », on dit get."}, {"equals": "want", "category": "vocabulary", "feedback": "Want veut dire « vouloir ». Pour « recevoir », on dit get."}], "pool": "lesson", "lessonId": "en.l12", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l12.e06', 'en', 'en.l12', 'en.g10.want_need_to', array['en.g10.want_need_to','en.v.need','en.v.homework']::text[], 'reorder', 'lesson', 'Ils ont besoin de faire leurs devoirs.', array['They need to do their homework']::text[], 'L''ordre est : sujet + need + to + verbe de base + complément. On obtient They need to do their homework.', 2, '{"id": "en.l12.e06", "unitIds": ["en.g10.want_need_to", "en.v.need", "en.v.homework"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Ils ont besoin de faire leurs devoirs.", "promptLanguage": "fr", "tokens": ["need", "They", "do", "to", "their", "homework"], "answer": "They need to do their homework", "acceptedAnswers": ["They need to do their homework"], "hint": "Sujet, need, to, puis le verbe do.", "explanation": "L''ordre est : sujet + need + to + verbe de base + complément. On obtient They need to do their homework.", "tip": "Need to + verbe : to reste collé au verbe.", "extraExample": {"text": "I need to do my homework.", "translation": "J''ai besoin de faire mes devoirs."}, "pool": "lesson", "lessonId": "en.l12", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l12.e07', 'en', 'en.l12', 'en.g10.want_need_to', array['en.g10.want_need_to','en.v.think']::text[], 'translation', 'lesson', 'Je pense que tu as raison.', array['I think you are right.','I think that you are right.','I think you are correct.','I think that you are correct.']::text[], 'Penser se dit think, et il est suivi directement de la phrase : I think you are right. « Avoir raison » se traduit par être right : you are right.', 2, '{"id": "en.l12.e07", "unitIds": ["en.g10.want_need_to", "en.v.think"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Je pense que tu as raison.", "promptLanguage": "fr", "answer": "I think you are right.", "acceptedAnswers": ["I think you are right.", "I think that you are right.", "I think you are correct.", "I think that you are correct."], "hint": "« Avoir raison » se dit be right en anglais.", "explanation": "Penser se dit think, et il est suivi directement de la phrase : I think you are right. « Avoir raison » se traduit par être right : you are right.", "tip": "Avoir raison = be right. Avec I, think ne change pas.", "extraExample": {"text": "We think they are tired.", "translation": "Nous pensons qu''ils sont fatigués."}, "errorPatterns": [{"contains": "have right", "category": "grammar", "feedback": "« Avoir raison » ne se dit pas avec have en anglais. On dit you are right (être right)."}, {"contains": "i thinks", "category": "conjugation", "feedback": "Avec I, le verbe ne prend pas de -s : I think."}, {"contains": "you right", "category": "grammar", "feedback": "Il manque le verbe être : you are right."}], "pool": "lesson", "lessonId": "en.l12", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l12.e08', 'en', 'en.l12', 'en.g10.want_need_to', array['en.g10.want_need_to','en.v.want','en.v.go','en.v.home']::text[], 'translation', 'lesson', 'Nous voulons rentrer à la maison.', array['We want to go home.','We want to get home.','We want to go back home.']::text[], 'Vouloir se dit want, suivi de to + verbe de base : want to go. Rentrer à la maison se dit go home, sans to devant home.', 3, '{"id": "en.l12.e08", "unitIds": ["en.g10.want_need_to", "en.v.want", "en.v.go", "en.v.home"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Nous voulons rentrer à la maison.", "promptLanguage": "fr", "answer": "We want to go home.", "acceptedAnswers": ["We want to go home.", "We want to get home.", "We want to go back home."], "hint": "Vouloir + verbe : n''oublie pas to.", "explanation": "Vouloir se dit want, suivi de to + verbe de base : want to go. Rentrer à la maison se dit go home, sans to devant home.", "tip": "Want to go home : un seul to, entre want et go.", "extraExample": {"text": "They want to go to school.", "translation": "Ils veulent aller à l''école."}, "errorPatterns": [{"contains": "want go", "category": "grammar", "feedback": "Il manque to entre want et le verbe : want to go."}, {"contains": "go to home", "category": "preposition", "feedback": "Devant home, on n''ajoute pas to : go home."}, {"contains": "want that", "category": "grammar", "feedback": "On ne dit pas « want that » avant un verbe. On dit want to + verbe."}], "pool": "lesson", "lessonId": "en.l12", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l12.e09', 'en', 'en.l12', 'en.g10.want_need_to', array['en.g10.want_need_to','en.v.want','en.v.make','en.v.coffee']::text[], 'free_answer', 'lesson', 'Comment dit-on « Je veux faire du café » en anglais ?', array['I want to make coffee.','I want to make some coffee.','I want to make a coffee.']::text[], 'Vouloir se dit want, suivi de to + verbe de base. Préparer du café se dit make coffee, donc I want to make coffee.', 3, '{"id": "en.l12.e09", "unitIds": ["en.g10.want_need_to", "en.v.want", "en.v.make", "en.v.coffee"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Je veux faire du café » en anglais ?", "promptLanguage": "fr", "answer": "I want to make coffee.", "acceptedAnswers": ["I want to make coffee.", "I want to make some coffee.", "I want to make a coffee."], "hint": "Vouloir + faire : want to + le verbe pour préparer.", "explanation": "Vouloir se dit want, suivi de to + verbe de base. Préparer du café se dit make coffee, donc I want to make coffee.", "tip": "Want to + verbe de base. Et le café, on le prépare : make coffee.", "extraExample": {"text": "We want to make dinner.", "translation": "Nous voulons préparer le dîner."}, "errorPatterns": [{"contains": "want make", "category": "grammar", "feedback": "Il manque to entre want et make : I want to make."}, {"contains": "want to do coffee", "category": "word_confusion", "feedback": "On prépare le café : on dit make coffee, pas do coffee."}, {"contains": "i wants", "category": "conjugation", "feedback": "Avec I, le verbe ne prend pas de -s : I want."}], "pool": "lesson", "lessonId": "en.l12", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l12.e10', 'en', 'en.l12', 'en.g10.want_need_to', array['en.g10.want_need_to','en.v.know','en.v.brother']::text[], 'free_answer', 'lesson', 'Comment dit-on « Tu connais mon frère » en anglais ?', array['You know my brother.']::text[], 'Know veut dire « savoir » et aussi « connaître » : you know my brother. Avec you, le verbe ne change pas, et il n''y a pas de to devant un nom.', 3, '{"id": "en.l12.e10", "unitIds": ["en.g10.want_need_to", "en.v.know", "en.v.brother"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Tu connais mon frère » en anglais ?", "promptLanguage": "fr", "answer": "You know my brother.", "acceptedAnswers": ["You know my brother."], "hint": "Connaître une personne se dit know, comme savoir.", "explanation": "Know veut dire « savoir » et aussi « connaître » : you know my brother. Avec you, le verbe ne change pas, et il n''y a pas de to devant un nom.", "tip": "Connaître quelqu''un, c''est know : I know Tom.", "extraExample": {"text": "We know your sister.", "translation": "Nous connaissons ta sœur."}, "errorPatterns": [{"contains": "you knows", "category": "conjugation", "feedback": "Avec you, le verbe ne prend pas de -s : you know."}, {"contains": "know to", "category": "grammar", "feedback": "To s''utilise devant un verbe, pas devant un nom. Ici, on dit you know my brother."}, {"contains": "you are know", "category": "grammar", "feedback": "Pas besoin du verbe être ici : on dit simplement you know."}], "pool": "lesson", "lessonId": "en.l12", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l13.e01', 'en', 'en.l13', 'en.g11.can', array['en.g11.can','en.v.swim']::text[], 'mcq', 'lesson', 'She ___ swim.', array['can']::text[], 'Can est un verbe à part : il ne change jamais, même avec she, et il est suivi directement du verbe de base. On dit donc she can swim.', 1, '{"id": "en.l13.e01", "unitIds": ["en.g11.can", "en.v.swim"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "She ___ swim.", "promptLanguage": "en", "options": ["can", "cans", "can to", "is can"], "answer": "can", "acceptedAnswers": ["can"], "hint": "Can ne change jamais et se place juste avant le verbe.", "explanation": "Can est un verbe à part : il ne change jamais, même avec she, et il est suivi directement du verbe de base. On dit donc she can swim.", "tip": "Can ne prend jamais de -s et n''est jamais suivi de to.", "extraExample": {"text": "My brother can swim.", "translation": "Mon frère sait nager."}, "errorPatterns": [{"equals": "cans", "category": "conjugation", "feedback": "Can ne prend jamais de -s, même avec she : she can swim."}, {"equals": "can to", "category": "grammar", "feedback": "Après can, on n''ajoute pas to : she can swim."}, {"equals": "is can", "category": "grammar", "feedback": "Can est déjà le verbe : on n''ajoute pas is. On dit she can swim."}], "pool": "lesson", "lessonId": "en.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l13.e02', 'en', 'en.l13', 'en.g11.can', array['en.g11.can','en.v.drive']::text[], 'mcq', 'lesson', 'Comment dit-on « Je sais conduire » en anglais ?', array['I can drive.']::text[], 'Pour dire qu''on sait faire quelque chose, on utilise can + verbe de base : I can drive. Know ne s''emploie pas ainsi devant un verbe.', 1, '{"id": "en.l13.e02", "unitIds": ["en.g11.can", "en.v.drive"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « Je sais conduire » en anglais ?", "promptLanguage": "fr", "options": ["I can drive.", "I can to drive.", "I know drive.", "I am drive."], "answer": "I can drive.", "acceptedAnswers": ["I can drive."], "hint": "En anglais, « savoir faire quelque chose » se dit avec can.", "explanation": "Pour dire qu''on sait faire quelque chose, on utilise can + verbe de base : I can drive. Know ne s''emploie pas ainsi devant un verbe.", "tip": "Savoir + verbe = can + verbe. Pas de to après can.", "extraExample": {"text": "You can drive.", "translation": "Tu sais conduire."}, "errorPatterns": [{"equals": "i can to drive.", "category": "grammar", "feedback": "Après can, on n''ajoute pas to : I can drive."}, {"equals": "i know drive.", "category": "vocabulary", "feedback": "En français, on dit « je sais conduire », mais en anglais on ne traduit pas ce « savoir » par know : on utilise can. I can drive."}, {"equals": "i am drive.", "category": "grammar", "feedback": "Am est le verbe être : on ne le met pas devant un autre verbe. On dit I can drive."}], "pool": "lesson", "lessonId": "en.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l13.e03', 'en', 'en.l13', 'en.g11.can', array['en.g11.can','en.v.swim','en.v.drive','en.v.speak','en.v.english','en.v.french']::text[], 'match', 'lesson', 'Ce que je sais faire : swim, drive, speak English, speak French', '{}'::text[], 'Can + verbe de base dit ce qu''on sait faire. Can''t dit qu''on ne sait pas. Les noms de langues, English et French, prennent une majuscule en anglais.', 1, '{"id": "en.l13.e03", "unitIds": ["en.g11.can", "en.v.swim", "en.v.drive", "en.v.speak", "en.v.english", "en.v.french"], "type": "match", "difficulty": 1, "instruction": "Associe chaque phrase anglaise à sa traduction.", "prompt": "Ce que je sais faire : swim, drive, speak English, speak French", "promptLanguage": "fr", "pairs": [{"left": "I can swim.", "right": "Je sais nager."}, {"left": "She can drive.", "right": "Elle sait conduire."}, {"left": "We can speak English.", "right": "Nous savons parler anglais."}, {"left": "They can speak French.", "right": "Ils savent parler français."}, {"left": "I can''t swim.", "right": "Je ne sais pas nager."}], "answer": "I can swim. = Je sais nager. ; She can drive. = Elle sait conduire. ; We can speak English. = Nous savons parler anglais. ; They can speak French. = Ils savent parler français. ; I can''t swim. = Je ne sais pas nager.", "acceptedAnswers": [], "explanation": "Can + verbe de base dit ce qu''on sait faire. Can''t dit qu''on ne sait pas. Les noms de langues, English et French, prennent une majuscule en anglais.", "tip": "English et French s''écrivent toujours avec une majuscule.", "extraExample": {"text": "Anna can swim and drive.", "translation": "Anna sait nager et conduire."}, "pool": "lesson", "lessonId": "en.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l13.e04', 'en', 'en.l13', 'en.g11.can', array['en.g11.can','en.v.speak','en.v.french']::text[], 'fill_blank', 'lesson', 'Tom ___ speak French. (il sait)', array['can']::text[], 'Pour dire qu''on sait faire quelque chose, on utilise can + verbe de base. Can ne prend pas de -s, même avec Tom : Tom can speak French.', 2, '{"id": "en.l13.e04", "unitIds": ["en.g11.can", "en.v.speak", "en.v.french"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme.", "prompt": "Tom ___ speak French. (il sait)", "promptLanguage": "en", "options": ["can", "cans", "can''t", "can to"], "answer": "can", "acceptedAnswers": ["can"], "hint": "La phrase est affirmative : Tom sait parler français.", "explanation": "Pour dire qu''on sait faire quelque chose, on utilise can + verbe de base. Can ne prend pas de -s, même avec Tom : Tom can speak French.", "tip": "Même avec un prénom, can reste can.", "extraExample": {"text": "My sister can speak English.", "translation": "Ma sœur sait parler anglais."}, "errorPatterns": [{"equals": "cans", "category": "conjugation", "feedback": "Can ne prend jamais de -s : Tom can speak."}, {"equals": "can''t", "category": "grammar", "feedback": "Can''t veut dire « ne pas pouvoir, ne pas savoir ». La phrase est affirmative : on dit can."}, {"equals": "can to", "category": "grammar", "feedback": "Après can, on n''ajoute pas to : Tom can speak."}], "pool": "lesson", "lessonId": "en.l13", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l13.e05', 'en', 'en.l13', 'en.g11.can', array['en.g11.can','en.v.swim']::text[], 'fill_blank', 'lesson', 'We ___ swim. (nous ne savons pas)', array['can''t','cannot','can not']::text[], 'Pour dire qu''on ne peut pas ou qu''on ne sait pas faire quelque chose, on utilise can''t (ou cannot) + verbe de base : we can''t swim.', 2, '{"id": "en.l13.e05", "unitIds": ["en.g11.can", "en.v.swim"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme.", "prompt": "We ___ swim. (nous ne savons pas)", "promptLanguage": "en", "options": ["can''t", "can", "cans", "to"], "answer": "can''t", "acceptedAnswers": ["can''t", "cannot", "can not"], "hint": "La phrase est négative.", "explanation": "Pour dire qu''on ne peut pas ou qu''on ne sait pas faire quelque chose, on utilise can''t (ou cannot) + verbe de base : we can''t swim.", "tip": "Can''t = can + not : la négation est collée à can.", "extraExample": {"text": "They can''t drive.", "translation": "Ils ne savent pas conduire."}, "errorPatterns": [{"equals": "can", "category": "grammar", "feedback": "Can est affirmatif. La phrase dit « nous ne savons pas » : on utilise can''t."}, {"equals": "cans", "category": "conjugation", "feedback": "Can ne prend jamais de -s. Ici, on veut la négation : can''t."}], "pool": "lesson", "lessonId": "en.l13", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l13.e06', 'en', 'en.l13', 'en.g11.can', array['en.g11.can','en.v.speak','en.v.english','en.v.french']::text[], 'reorder', 'lesson', 'Anna sait parler anglais et français.', array['Anna can speak English and French','Anna can speak French and English']::text[], 'L''ordre est : sujet + can + verbe de base + complément. Anna can speak, puis English and French.', 2, '{"id": "en.l13.e06", "unitIds": ["en.g11.can", "en.v.speak", "en.v.english", "en.v.french"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Anna sait parler anglais et français.", "promptLanguage": "fr", "tokens": ["English", "Anna", "speak", "and", "can", "French"], "answer": "Anna can speak English and French", "acceptedAnswers": ["Anna can speak English and French", "Anna can speak French and English"], "hint": "Sujet, can, verbe de base, puis les deux langues.", "explanation": "L''ordre est : sujet + can + verbe de base + complément. Anna can speak, puis English and French.", "tip": "Sujet + can + verbe : can se place toujours juste avant le verbe.", "extraExample": {"text": "Tom can speak French and English.", "translation": "Tom sait parler français et anglais."}, "pool": "lesson", "lessonId": "en.l13", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l13.e07', 'en', 'en.l13', 'en.g11.can', array['en.g11.can','en.v.drive','en.v.mother']::text[], 'translation', 'lesson', 'Ma mère sait conduire.', array['My mother can drive.','My mum can drive.','My mom can drive.','My mother can drive a car.','My mum can drive a car.','My mom can drive a car.']::text[], 'Pour dire qu''on sait faire quelque chose, on utilise can + verbe de base. Can ne change pas avec my mother : my mother can drive.', 2, '{"id": "en.l13.e07", "unitIds": ["en.g11.can", "en.v.drive", "en.v.mother"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Ma mère sait conduire.", "promptLanguage": "fr", "answer": "My mother can drive.", "acceptedAnswers": ["My mother can drive.", "My mum can drive.", "My mom can drive.", "My mother can drive a car.", "My mum can drive a car.", "My mom can drive a car."], "hint": "Savoir faire quelque chose = can. Can ne change pas avec my mother.", "explanation": "Pour dire qu''on sait faire quelque chose, on utilise can + verbe de base. Can ne change pas avec my mother : my mother can drive.", "tip": "She, he, my mother : can reste can, et le verbe suivant aussi.", "extraExample": {"text": "My father can drive.", "translation": "Mon père sait conduire."}, "errorPatterns": [{"contains": "mother cans", "category": "conjugation", "feedback": "Can ne prend jamais de -s : my mother can drive."}, {"contains": "can to drive", "category": "grammar", "feedback": "Après can, on n''ajoute pas to : can drive."}, {"contains": "can drives", "category": "conjugation", "feedback": "Après can, le verbe reste à sa forme de base : can drive, sans -s."}], "pool": "lesson", "lessonId": "en.l13", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l13.e08', 'en', 'en.l13', 'en.g11.can', array['en.g11.can','en.v.swim']::text[], 'translation', 'lesson', 'Ils ne savent pas nager.', array['They can''t swim.']::text[], 'Pour dire qu''on ne sait pas faire quelque chose, on utilise can''t + verbe de base : they can''t swim. On n''ajoute ni to ni -s.', 3, '{"id": "en.l13.e08", "unitIds": ["en.g11.can", "en.v.swim"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Ils ne savent pas nager.", "promptLanguage": "fr", "answer": "They can''t swim.", "acceptedAnswers": ["They can''t swim."], "hint": "La négation de can est can''t.", "explanation": "Pour dire qu''on ne sait pas faire quelque chose, on utilise can''t + verbe de base : they can''t swim. On n''ajoute ni to ni -s.", "tip": "Can''t + verbe de base : they can''t swim.", "extraExample": {"text": "We can''t drive.", "translation": "Nous ne savons pas conduire."}, "errorPatterns": [{"contains": "can swim not", "category": "word_order", "feedback": "La négation se place sur can : can''t (ou cannot), puis le verbe. On dit they can''t swim."}, {"contains": "can''t to", "category": "grammar", "feedback": "Après can''t, on n''ajoute pas to : they can''t swim."}, {"contains": "they are can", "category": "grammar", "feedback": "Can est déjà le verbe : on n''ajoute pas are. On dit they can''t swim."}], "pool": "lesson", "lessonId": "en.l13", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l13.e09', 'en', 'en.l13', 'en.g11.can', array['en.g11.can','en.v.speak','en.v.english']::text[], 'free_answer', 'lesson', 'Comment dit-on « Tu sais parler anglais ? » en anglais ?', array['Can you speak English?','Do you speak English?']::text[], 'Pour poser une question avec can, on place can avant le sujet : Can you speak English? Il n''y a pas de to ni de -s.', 3, '{"id": "en.l13.e09", "unitIds": ["en.g11.can", "en.v.speak", "en.v.english"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Tu sais parler anglais ? » en anglais ?", "promptLanguage": "fr", "answer": "Can you speak English?", "acceptedAnswers": ["Can you speak English?", "Do you speak English?"], "hint": "Pour une question avec can, on met can avant le sujet.", "explanation": "Pour poser une question avec can, on place can avant le sujet : Can you speak English? Il n''y a pas de to ni de -s.", "tip": "Question avec can : Can + sujet + verbe.", "extraExample": {"text": "Can you swim?", "translation": "Est-ce que tu sais nager ?"}, "errorPatterns": [{"contains": "you can speak", "category": "word_order", "feedback": "Pour une question, on met can avant le sujet : Can you speak English?"}, {"contains": "can you to", "category": "grammar", "feedback": "Après can you, on n''ajoute pas to : Can you speak English?"}, {"contains": "do you can", "category": "grammar", "feedback": "Avec can, on ne met pas do : on place simplement can avant le sujet. Can you speak English?"}], "pool": "lesson", "lessonId": "en.l13", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l13.e10', 'en', 'en.l13', 'en.g11.can', array['en.g11.can','en.v.drive']::text[], 'free_answer', 'lesson', 'Comment dit-on « Elle ne sait pas conduire » en anglais ?', array['She can''t drive.']::text[], 'Pour dire qu''on ne sait pas faire quelque chose, on utilise can''t + verbe de base. Can''t ne change pas avec she : she can''t drive.', 3, '{"id": "en.l13.e10", "unitIds": ["en.g11.can", "en.v.drive"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Elle ne sait pas conduire » en anglais ?", "promptLanguage": "fr", "answer": "She can''t drive.", "acceptedAnswers": ["She can''t drive."], "hint": "Can ne prend pas de -s, et sa négation est can''t.", "explanation": "Pour dire qu''on ne sait pas faire quelque chose, on utilise can''t + verbe de base. Can''t ne change pas avec she : she can''t drive.", "tip": "She can''t drive : pas de -s sur can, pas de -s sur le verbe.", "extraExample": {"text": "He can''t swim.", "translation": "Il ne sait pas nager."}, "errorPatterns": [{"contains": "cans", "category": "conjugation", "feedback": "Can ne prend jamais de -s, même avec she : she can''t drive."}, {"contains": "can''t drives", "category": "conjugation", "feedback": "Après can''t, le verbe reste à sa forme de base : can''t drive, sans -s."}, {"contains": "can''t to", "category": "grammar", "feedback": "Après can''t, on n''ajoute pas to : she can''t drive."}], "pool": "lesson", "lessonId": "en.l13", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l14.e01', 'en', 'en.l14', 'en.g11.can', array['en.g11.can','en.v.help']::text[], 'mcq', 'lesson', 'Comment dit-on « Peux-tu m''aider ? » en anglais ?', array['Can you help me?']::text[], 'Pour demander un service, on utilise Can you + verbe de base ? On n''ajoute pas to. Après help, on dit me (« moi ») et non I.', 1, '{"id": "en.l14.e01", "unitIds": ["en.g11.can", "en.v.help"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « Peux-tu m''aider ? » en anglais ?", "promptLanguage": "fr", "options": ["Can you help me?", "Can you to help me?", "Can you help I?", "Can help you me?"], "answer": "Can you help me?", "acceptedAnswers": ["Can you help me?"], "hint": "Pour une demande, on met can avant you, puis le verbe de base.", "explanation": "Pour demander un service, on utilise Can you + verbe de base ? On n''ajoute pas to. Après help, on dit me (« moi ») et non I.", "tip": "Demander un service : Can you + verbe de base ?", "extraExample": {"text": "Can you give me the key?", "translation": "Peux-tu me donner la clé ?"}, "errorPatterns": [{"equals": "can you to help me?", "category": "grammar", "feedback": "Après can you, on n''ajoute pas to : Can you help me?"}, {"equals": "can you help i?", "category": "grammar", "feedback": "Après le verbe, « moi » se dit me, pas I : Can you help me?"}, {"equals": "can help you me?", "category": "word_order", "feedback": "Dans une question, can est suivi du sujet : Can you help me?"}], "pool": "lesson", "lessonId": "en.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l14.e02', 'en', 'en.l14', 'en.g11.can', array['en.g11.can','en.v.give','en.v.key']::text[], 'mcq', 'lesson', 'Tom: Can you give me the key? — Anna: Yes, ___.', array['I can']::text[], 'Tom demande « Can you… ? » : il parle à Anna. Anna répond donc avec I : Yes, I can. Can ne change pas et ne prend pas de -s.', 1, '{"id": "en.l14.e02", "unitIds": ["en.g11.can", "en.v.give", "en.v.key"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Tom: Can you give me the key? — Anna: Yes, ___.", "promptLanguage": "en", "options": ["I can", "you can", "I cans", "can you"], "answer": "I can", "acceptedAnswers": ["I can"], "hint": "Anna répond pour elle-même : qui peut donner la clé ?", "explanation": "Tom demande « Can you… ? » : il parle à Anna. Anna répond donc avec I : Yes, I can. Can ne change pas et ne prend pas de -s.", "tip": "On répond à Can you… ? avec Yes, I can. ou No, I can''t.", "extraExample": {"text": "Can you help me? — Yes, I can.", "translation": "Peux-tu m''aider ? — Oui, je peux."}, "errorPatterns": [{"equals": "you can", "category": "grammar", "feedback": "Tom demande à Anna : « Peux-tu ? ». Anna répond pour elle-même, avec I : Yes, I can."}, {"equals": "i cans", "category": "conjugation", "feedback": "Can ne prend jamais de -s : Yes, I can."}, {"equals": "can you", "category": "grammar", "feedback": "Can you est la question. La réponse est Yes, I can."}], "pool": "lesson", "lessonId": "en.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l14.e03', 'en', 'en.l14', 'en.g11.can', array['en.g11.can','en.v.help','en.v.read','en.v.write','en.v.door','en.v.window']::text[], 'match', 'lesson', 'Demandes et mots utiles : help me, read, write your name, the door, the window', '{}'::text[], 'Can you + verbe de base ? sert à demander un service. Help = aider, read = lire, write = écrire, door = porte, window = fenêtre.', 1, '{"id": "en.l14.e03", "unitIds": ["en.g11.can", "en.v.help", "en.v.read", "en.v.write", "en.v.door", "en.v.window"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Demandes et mots utiles : help me, read, write your name, the door, the window", "promptLanguage": "fr", "pairs": [{"left": "Can you help me?", "right": "Peux-tu m''aider ?"}, {"left": "Can you read it?", "right": "Peux-tu le lire ?"}, {"left": "Can you write your name?", "right": "Peux-tu écrire ton nom ?"}, {"left": "the door", "right": "la porte"}, {"left": "the window", "right": "la fenêtre"}], "answer": "Can you help me? = Peux-tu m''aider ? ; Can you read it? = Peux-tu le lire ? ; Can you write your name? = Peux-tu écrire ton nom ? ; the door = la porte ; the window = la fenêtre", "acceptedAnswers": [], "explanation": "Can you + verbe de base ? sert à demander un service. Help = aider, read = lire, write = écrire, door = porte, window = fenêtre.", "tip": "Door (porte) et window (fenêtre) ne changent pas selon le genre : the door, the window.", "extraExample": {"text": "Can you read the name on the door?", "translation": "Peux-tu lire le nom sur la porte ?"}, "pool": "lesson", "lessonId": "en.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l14.e04', 'en', 'en.l14', 'en.g11.can', array['en.g11.can','en.v.help','en.v.window']::text[], 'fill_blank', 'lesson', 'Can you ___ me with the window?', array['help']::text[], 'Après Can you, le verbe reste à sa forme de base : help. On n''ajoute ni -s, ni to, ni -ing.', 2, '{"id": "en.l14.e04", "unitIds": ["en.g11.can", "en.v.help", "en.v.window"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la demande.", "prompt": "Can you ___ me with the window?", "promptLanguage": "en", "options": ["help", "helps", "to help", "helping"], "answer": "help", "acceptedAnswers": ["help"], "hint": "Après can you, on met le verbe de base.", "explanation": "Après Can you, le verbe reste à sa forme de base : help. On n''ajoute ni -s, ni to, ni -ing.", "tip": "Can you + verbe de base ? Rien d''autre à ajouter.", "extraExample": {"text": "Can you help me with the door?", "translation": "Peux-tu m''aider avec la porte ?"}, "errorPatterns": [{"equals": "helps", "category": "conjugation", "feedback": "Après can, le verbe ne prend jamais de -s : Can you help me?"}, {"equals": "to help", "category": "grammar", "feedback": "Après can, on n''ajoute pas to : Can you help me?"}, {"equals": "helping", "category": "grammar", "feedback": "Après can, le verbe reste à sa forme de base, sans -ing : help."}], "pool": "lesson", "lessonId": "en.l14", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l14.e05', 'en', 'en.l14', 'en.g11.can', array['en.g11.can','en.v.read','en.v.book']::text[], 'fill_blank', 'lesson', 'Can you ___ the book? (lire)', array['read']::text[], '« Lire » se dit read. Après Can you, le verbe reste à sa forme de base : Can you read the book?', 2, '{"id": "en.l14.e05", "unitIds": ["en.g11.can", "en.v.read", "en.v.book"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon verbe.", "prompt": "Can you ___ the book? (lire)", "promptLanguage": "en", "options": ["read", "write", "help", "reads"], "answer": "read", "acceptedAnswers": ["read"], "hint": "Le verbe qui veut dire « lire ».", "explanation": "« Lire » se dit read. Après Can you, le verbe reste à sa forme de base : Can you read the book?", "tip": "Read = lire, write = écrire : ne les mélange pas.", "extraExample": {"text": "I can read French.", "translation": "Je sais lire le français."}, "errorPatterns": [{"equals": "write", "category": "vocabulary", "feedback": "Write veut dire « écrire ». Pour « lire », on dit read."}, {"equals": "help", "category": "vocabulary", "feedback": "Help veut dire « aider ». Pour « lire », on dit read."}, {"equals": "reads", "category": "conjugation", "feedback": "Après can, le verbe ne prend jamais de -s : Can you read?"}], "pool": "lesson", "lessonId": "en.l14", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l14.e06', 'en', 'en.l14', 'en.g11.can', array['en.g11.can','en.v.read','en.v.door']::text[], 'reorder', 'lesson', 'Peux-tu lire le nom sur la porte ?', array['Can you read the name on the door']::text[], 'Dans une demande, can se place avant le sujet : Can you. Puis le verbe de base read, puis le complément the name on the door.', 2, '{"id": "en.l14.e06", "unitIds": ["en.g11.can", "en.v.read", "en.v.door"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Peux-tu lire le nom sur la porte ?", "promptLanguage": "fr", "tokens": ["door", "Can", "read", "you", "the", "name", "on", "the"], "answer": "Can you read the name on the door", "acceptedAnswers": ["Can you read the name on the door"], "hint": "Une question avec can commence par Can.", "explanation": "Dans une demande, can se place avant le sujet : Can you. Puis le verbe de base read, puis le complément the name on the door.", "tip": "Can + sujet + verbe + complément.", "extraExample": {"text": "Can you write the name on the window?", "translation": "Peux-tu écrire le nom sur la fenêtre ?"}, "pool": "lesson", "lessonId": "en.l14", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l14.e07', 'en', 'en.l14', 'en.g11.can', array['en.g11.can','en.v.write','en.v.name']::text[], 'translation', 'lesson', 'Peux-tu écrire ton nom ?', array['Can you write your name?','Could you write your name?','Can you write your name, please?','Could you write your name, please?','Can you please write your name?','Could you please write your name?','Please can you write your name?','Please could you write your name?']::text[], 'Pour demander à quelqu''un de faire quelque chose, on utilise Can you + verbe de base ? : Can you write your name? Ton nom se dit your name.', 2, '{"id": "en.l14.e07", "unitIds": ["en.g11.can", "en.v.write", "en.v.name"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Peux-tu écrire ton nom ?", "promptLanguage": "fr", "answer": "Can you write your name?", "acceptedAnswers": ["Can you write your name?", "Could you write your name?", "Can you write your name, please?", "Could you write your name, please?", "Can you please write your name?", "Could you please write your name?", "Please can you write your name?", "Please could you write your name?"], "hint": "Peux-tu = Can you.", "explanation": "Pour demander à quelqu''un de faire quelque chose, on utilise Can you + verbe de base ? : Can you write your name? Ton nom se dit your name.", "tip": "Peux-tu… ? se dit Can you… ? Le verbe suit directement.", "extraExample": {"text": "Can you read your name?", "translation": "Peux-tu lire ton nom ?"}, "errorPatterns": [{"contains": "can you to", "category": "grammar", "feedback": "Après can you, on n''ajoute pas to : Can you write your name?"}, {"contains": "you can write", "category": "word_order", "feedback": "Pour poser une question, on met can avant le sujet : Can you write your name?"}, {"contains": "can you writes", "category": "conjugation", "feedback": "Après can, le verbe ne prend jamais de -s : Can you write?"}], "pool": "lesson", "lessonId": "en.l14", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l14.e08', 'en', 'en.l14', 'en.g11.can', array['en.g11.can','en.v.take','en.v.bag']::text[], 'translation', 'lesson', 'Puis-je prendre ton sac ?', array['Can I take your bag?','May I take your bag?','Could I take your bag?','Can I take your bag, please?','Could I take your bag, please?','May I take your bag, please?']::text[], 'Pour demander la permission, on utilise Can I + verbe de base ? Can se place avant I, et le verbe reste à sa forme de base : Can I take your bag?', 3, '{"id": "en.l14.e08", "unitIds": ["en.g11.can", "en.v.take", "en.v.bag"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Puis-je prendre ton sac ?", "promptLanguage": "fr", "answer": "Can I take your bag?", "acceptedAnswers": ["Can I take your bag?", "May I take your bag?", "Could I take your bag?", "Can I take your bag, please?", "Could I take your bag, please?", "May I take your bag, please?"], "hint": "Pour demander la permission avec I : Can I… ?", "explanation": "Pour demander la permission, on utilise Can I + verbe de base ? Can se place avant I, et le verbe reste à sa forme de base : Can I take your bag?", "tip": "Can I… ? sert à demander la permission : Puis-je… ?", "extraExample": {"text": "Can I go home?", "translation": "Puis-je rentrer à la maison ?"}, "errorPatterns": [{"contains": "can i to", "category": "grammar", "feedback": "Après can I, on n''ajoute pas to : Can I take your bag?"}, {"contains": "i can take", "category": "word_order", "feedback": "Pour poser une question, on met can avant le sujet : Can I take your bag?"}, {"contains": "can i takes", "category": "conjugation", "feedback": "Après can, le verbe ne prend jamais de -s : Can I take?"}], "pool": "lesson", "lessonId": "en.l14", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l14.e09', 'en', 'en.l14', 'en.g11.can', array['en.g11.can','en.v.go','en.v.home']::text[], 'free_answer', 'lesson', 'Anna donne la permission à Tom. Comment dit-on « Oui, tu peux rentrer à la maison » en anglais ?', array['Yes, you can go home.','You can go home.','Yes you can go home.','Yes, you may go home.','You may go home.']::text[], 'Pour donner la permission, on utilise you can + verbe de base. Rentrer à la maison se dit go home, sans to devant home.', 3, '{"id": "en.l14.e09", "unitIds": ["en.g11.can", "en.v.go", "en.v.home"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Anna donne la permission à Tom. Comment dit-on « Oui, tu peux rentrer à la maison » en anglais ?", "promptLanguage": "fr", "answer": "Yes, you can go home.", "acceptedAnswers": ["Yes, you can go home.", "You can go home.", "Yes you can go home.", "Yes, you may go home.", "You may go home."], "hint": "Pour donner la permission, on dit you can + verbe.", "explanation": "Pour donner la permission, on utilise you can + verbe de base. Rentrer à la maison se dit go home, sans to devant home.", "tip": "You can + verbe = tu peux, tu as le droit de.", "extraExample": {"text": "Yes, you can take my phone.", "translation": "Oui, tu peux prendre mon téléphone."}, "errorPatterns": [{"contains": "can to go", "category": "grammar", "feedback": "Après can, on n''ajoute pas to : you can go home."}, {"contains": "go to home", "category": "preposition", "feedback": "Devant home, on n''ajoute pas to : go home."}, {"contains": "you cans", "category": "conjugation", "feedback": "Can ne prend jamais de -s : you can go."}], "pool": "lesson", "lessonId": "en.l14", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l14.e10', 'en', 'en.l14', 'en.g11.can', array['en.g11.can','en.v.read','en.v.name']::text[], 'free_answer', 'lesson', 'Comment dit-on « Je ne peux pas lire ton nom » en anglais ?', array['I can''t read your name.']::text[], 'Pour dire qu''on ne peut pas faire quelque chose, on utilise can''t + verbe de base : I can''t read. Ton nom se dit your name.', 3, '{"id": "en.l14.e10", "unitIds": ["en.g11.can", "en.v.read", "en.v.name"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Je ne peux pas lire ton nom » en anglais ?", "promptLanguage": "fr", "answer": "I can''t read your name.", "acceptedAnswers": ["I can''t read your name."], "hint": "Can''t + verbe de base.", "explanation": "Pour dire qu''on ne peut pas faire quelque chose, on utilise can''t + verbe de base : I can''t read. Ton nom se dit your name.", "tip": "Can''t + verbe de base, sans to et sans -s.", "extraExample": {"text": "We can''t read the name on the window.", "translation": "Nous ne pouvons pas lire le nom sur la fenêtre."}, "errorPatterns": [{"contains": "can''t to", "category": "grammar", "feedback": "Après can''t, on n''ajoute pas to : I can''t read."}, {"contains": "can read not", "category": "word_order", "feedback": "La négation se place sur can : I can''t read."}, {"contains": "can''t reads", "category": "conjugation", "feedback": "Après can''t, le verbe reste à sa forme de base : I can''t read."}], "pool": "lesson", "lessonId": "en.l14", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l15.e01', 'en', 'en.l15', 'en.g12.must', array['en.g12.must','en.v.careful']::text[], 'mcq', 'lesson', 'You ___ be careful.', array['must']::text[], 'Must veut dire « il faut, tu dois ». Il est suivi directement du verbe de base : you must be careful. Il ne prend ni -s, ni to.', 1, '{"id": "en.l15.e01", "unitIds": ["en.g12.must", "en.v.careful"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "You ___ be careful.", "promptLanguage": "en", "options": ["must", "musts", "must to", "mustn''t"], "answer": "must", "acceptedAnswers": ["must"], "hint": "Must ne change jamais et se place juste avant le verbe.", "explanation": "Must veut dire « il faut, tu dois ». Il est suivi directement du verbe de base : you must be careful. Il ne prend ni -s, ni to.", "tip": "Must + verbe de base : pas de to, pas de -s.", "extraExample": {"text": "We must be careful.", "translation": "Nous devons faire attention."}, "errorPatterns": [{"equals": "musts", "category": "conjugation", "feedback": "Must ne prend jamais de -s : you must be careful."}, {"equals": "must to", "category": "grammar", "feedback": "Après must, on n''ajoute pas to : you must be careful."}, {"equals": "mustn''t", "category": "grammar", "feedback": "Mustn''t veut dire « il ne faut pas ». Ici, on veut dire « tu dois être prudent » : must."}], "pool": "lesson", "lessonId": "en.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l15.e02', 'en', 'en.l15', 'en.g12.must', array['en.g12.must','en.v.open','en.v.door']::text[], 'mcq', 'lesson', 'You mustn''t open the door.', array['Tu ne dois pas ouvrir la porte.']::text[], 'Mustn''t veut dire « il ne faut pas » : c''est une interdiction. You mustn''t open the door = tu ne dois pas ouvrir la porte, c''est interdit.', 1, '{"id": "en.l15.e02", "unitIds": ["en.g12.must", "en.v.open", "en.v.door"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "You mustn''t open the door.", "promptLanguage": "en", "options": ["Tu ne dois pas ouvrir la porte.", "Tu peux ouvrir la porte.", "Tu dois ouvrir la porte.", "Tu n''as pas besoin d''ouvrir la porte."], "answer": "Tu ne dois pas ouvrir la porte.", "acceptedAnswers": ["Tu ne dois pas ouvrir la porte."], "hint": "Mustn''t, c''est une interdiction.", "explanation": "Mustn''t veut dire « il ne faut pas » : c''est une interdiction. You mustn''t open the door = tu ne dois pas ouvrir la porte, c''est interdit.", "tip": "Mustn''t = c''est interdit, pas seulement « ce n''est pas utile ».", "extraExample": {"text": "You mustn''t close the window.", "translation": "Tu ne dois pas fermer la fenêtre."}, "errorPatterns": [{"equals": "tu peux ouvrir la porte.", "category": "grammar", "feedback": "« Tu peux » se dit you can. Mustn''t exprime le contraire : une interdiction."}, {"equals": "tu dois ouvrir la porte.", "category": "grammar", "feedback": "« Tu dois » se dit you must. Ici, mustn''t indique une interdiction : tu ne dois pas."}, {"equals": "tu n''as pas besoin d''ouvrir la porte.", "category": "grammar", "feedback": "Mustn''t est plus fort que « ce n''est pas nécessaire » : c''est interdit. Tu ne dois pas ouvrir la porte."}], "pool": "lesson", "lessonId": "en.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l15.e03', 'en', 'en.l15', 'en.g12.must', array['en.g12.must','en.v.stop','en.v.wait','en.v.open','en.v.close','en.v.careful']::text[], 'match', 'lesson', 'Les obligations : stop, wait, open, close, be careful', '{}'::text[], 'Must + verbe de base exprime une obligation. Stop = s''arrêter, wait = attendre, open = ouvrir, close = fermer, careful = prudent. « Faire attention » se dit be careful.', 1, '{"id": "en.l15.e03", "unitIds": ["en.g12.must", "en.v.stop", "en.v.wait", "en.v.open", "en.v.close", "en.v.careful"], "type": "match", "difficulty": 1, "instruction": "Associe chaque phrase anglaise à sa traduction.", "prompt": "Les obligations : stop, wait, open, close, be careful", "promptLanguage": "fr", "pairs": [{"left": "You must stop.", "right": "Tu dois t''arrêter."}, {"left": "We must wait.", "right": "Nous devons attendre."}, {"left": "You must open the window.", "right": "Tu dois ouvrir la fenêtre."}, {"left": "You must close the door.", "right": "Tu dois fermer la porte."}, {"left": "You must be careful.", "right": "Tu dois faire attention."}], "answer": "You must stop. = Tu dois t''arrêter. ; We must wait. = Nous devons attendre. ; You must open the window. = Tu dois ouvrir la fenêtre. ; You must close the door. = Tu dois fermer la porte. ; You must be careful. = Tu dois faire attention.", "acceptedAnswers": [], "explanation": "Must + verbe de base exprime une obligation. Stop = s''arrêter, wait = attendre, open = ouvrir, close = fermer, careful = prudent. « Faire attention » se dit be careful.", "tip": "Open (ouvrir) et close (fermer) sont des contraires : ne les mélange pas.", "extraExample": {"text": "We must stop and wait.", "translation": "Nous devons nous arrêter et attendre."}, "pool": "lesson", "lessonId": "en.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l15.e04', 'en', 'en.l15', 'en.g12.must', array['en.g12.must','en.v.open','en.v.window']::text[], 'fill_blank', 'lesson', 'It is cold. You ___ open the window. (il ne faut pas)', array['mustn''t','must not']::text[], 'Pour dire « il ne faut pas », on utilise mustn''t + verbe de base : you mustn''t open the window. On n''ajoute pas to.', 2, '{"id": "en.l15.e04", "unitIds": ["en.g12.must", "en.v.open", "en.v.window"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme.", "prompt": "It is cold. You ___ open the window. (il ne faut pas)", "promptLanguage": "en", "options": ["mustn''t", "must", "musts", "mustn''t to"], "answer": "mustn''t", "acceptedAnswers": ["mustn''t", "must not"], "hint": "La phrase exprime une interdiction.", "explanation": "Pour dire « il ne faut pas », on utilise mustn''t + verbe de base : you mustn''t open the window. On n''ajoute pas to.", "tip": "Mustn''t = must + not : la négation est collée à must.", "extraExample": {"text": "You mustn''t close the door.", "translation": "Tu ne dois pas fermer la porte."}, "errorPatterns": [{"equals": "must", "category": "grammar", "feedback": "Must dit « il faut ». La phrase dit « il ne faut pas » : on utilise mustn''t."}, {"equals": "musts", "category": "conjugation", "feedback": "Must ne prend jamais de -s. Ici, on veut la négation : mustn''t."}, {"equals": "mustn''t to", "category": "grammar", "feedback": "Après mustn''t, on n''ajoute pas to : you mustn''t open the window."}], "pool": "lesson", "lessonId": "en.l15", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l15.e05', 'en', 'en.l15', 'en.g12.must', array['en.g12.must','en.v.wait']::text[], 'fill_blank', 'lesson', 'We ___ wait for Anna. (nous devons)', array['must']::text[], 'Pour dire qu''il faut faire quelque chose, on utilise must + verbe de base : we must wait. Must ne prend ni -s, ni to.', 2, '{"id": "en.l15.e05", "unitIds": ["en.g12.must", "en.v.wait"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme.", "prompt": "We ___ wait for Anna. (nous devons)", "promptLanguage": "en", "options": ["must", "mustn''t", "musts", "must to"], "answer": "must", "acceptedAnswers": ["must"], "hint": "La phrase exprime une obligation.", "explanation": "Pour dire qu''il faut faire quelque chose, on utilise must + verbe de base : we must wait. Must ne prend ni -s, ni to.", "tip": "Obligation : must. Interdiction : mustn''t.", "extraExample": {"text": "I must wait for my father.", "translation": "Je dois attendre mon père."}, "errorPatterns": [{"equals": "mustn''t", "category": "grammar", "feedback": "Mustn''t dit « il ne faut pas ». Ici, c''est une obligation : we must wait."}, {"equals": "musts", "category": "conjugation", "feedback": "Must ne prend jamais de -s : we must wait."}, {"equals": "must to", "category": "grammar", "feedback": "Après must, on n''ajoute pas to : we must wait."}], "pool": "lesson", "lessonId": "en.l15", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l15.e06', 'en', 'en.l15', 'en.g12.must', array['en.g12.must','en.v.close','en.v.window','en.v.door']::text[], 'reorder', 'lesson', 'Anna doit fermer la fenêtre et la porte.', array['Anna must close the window and the door','Anna must close the door and the window']::text[], 'Must se place entre le sujet et le verbe de base : Anna must close. Même avec Anna, must ne prend pas de -s.', 2, '{"id": "en.l15.e06", "unitIds": ["en.g12.must", "en.v.close", "en.v.window", "en.v.door"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Anna doit fermer la fenêtre et la porte.", "promptLanguage": "fr", "tokens": ["window", "Anna", "the", "close", "and", "must", "door", "the"], "answer": "Anna must close the window and the door", "acceptedAnswers": ["Anna must close the window and the door", "Anna must close the door and the window"], "hint": "Sujet, must, verbe de base, puis les deux compléments.", "explanation": "Must se place entre le sujet et le verbe de base : Anna must close. Même avec Anna, must ne prend pas de -s.", "tip": "Sujet + must + verbe de base : même avec un prénom.", "extraExample": {"text": "Tom must open the window.", "translation": "Tom doit ouvrir la fenêtre."}, "pool": "lesson", "lessonId": "en.l15", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l15.e07', 'en', 'en.l15', 'en.g12.must', array['en.g12.must','en.v.stop']::text[], 'translation', 'lesson', 'Tu dois t''arrêter.', array['You must stop.','You have to stop.','You need to stop.','You must stop here.']::text[], 'Pour exprimer une obligation, on utilise must + verbe de base : you must stop. Pas de to entre must et stop.', 2, '{"id": "en.l15.e07", "unitIds": ["en.g12.must", "en.v.stop"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Tu dois t''arrêter.", "promptLanguage": "fr", "answer": "You must stop.", "acceptedAnswers": ["You must stop.", "You have to stop.", "You need to stop.", "You must stop here."], "hint": "Obligation = must + verbe de base.", "explanation": "Pour exprimer une obligation, on utilise must + verbe de base : you must stop. Pas de to entre must et stop.", "tip": "Tu dois = you must. Le verbe suit directement.", "extraExample": {"text": "We must stop.", "translation": "Nous devons nous arrêter."}, "errorPatterns": [{"contains": "must to", "category": "grammar", "feedback": "Après must, on n''ajoute pas to : you must stop."}, {"contains": "you musts", "category": "conjugation", "feedback": "Must ne prend jamais de -s : you must stop."}, {"contains": "must stopping", "category": "grammar", "feedback": "Après must, le verbe reste à sa forme de base, sans -ing : must stop."}], "pool": "lesson", "lessonId": "en.l15", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l15.e08', 'en', 'en.l15', 'en.g12.must', array['en.g12.must','en.v.open','en.v.door']::text[], 'translation', 'lesson', 'Tu ne dois pas ouvrir la porte.', array['You mustn''t open the door.','You can''t open the door.','You aren''t allowed to open the door.','You are not allowed to open the door.']::text[], 'Pour exprimer une interdiction, on utilise mustn''t + verbe de base : you mustn''t open the door. Pas de to après mustn''t.', 3, '{"id": "en.l15.e08", "unitIds": ["en.g12.must", "en.v.open", "en.v.door"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Tu ne dois pas ouvrir la porte.", "promptLanguage": "fr", "answer": "You mustn''t open the door.", "acceptedAnswers": ["You mustn''t open the door.", "You can''t open the door.", "You aren''t allowed to open the door.", "You are not allowed to open the door."], "hint": "Interdiction = mustn''t + verbe de base.", "explanation": "Pour exprimer une interdiction, on utilise mustn''t + verbe de base : you mustn''t open the door. Pas de to après mustn''t.", "tip": "Mustn''t + verbe de base = c''est interdit.", "extraExample": {"text": "We mustn''t open the window.", "translation": "Nous ne devons pas ouvrir la fenêtre."}, "errorPatterns": [{"contains": "mustn''t to", "category": "grammar", "feedback": "Après mustn''t, on n''ajoute pas to : you mustn''t open."}, {"contains": "must open not", "category": "word_order", "feedback": "La négation se place sur must : mustn''t (ou must not), puis le verbe."}, {"contains": "not must", "category": "word_order", "feedback": "On ne met pas not avant must. On dit mustn''t ou must not."}], "pool": "lesson", "lessonId": "en.l15", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l15.e09', 'en', 'en.l15', 'en.g12.must', array['en.g12.must','en.v.careful']::text[], 'free_answer', 'lesson', 'Comment dit-on « Nous devons être prudents » en anglais ?', array['We must be careful.','We have to be careful.','We need to be careful.']::text[], 'Pour exprimer une obligation, on utilise must + verbe de base. Ici, le verbe de base est be : we must be careful. Careful ne change pas.', 3, '{"id": "en.l15.e09", "unitIds": ["en.g12.must", "en.v.careful"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Nous devons être prudents » en anglais ?", "promptLanguage": "fr", "answer": "We must be careful.", "acceptedAnswers": ["We must be careful.", "We have to be careful.", "We need to be careful."], "hint": "Être prudent : le verbe être suit must.", "explanation": "Pour exprimer une obligation, on utilise must + verbe de base. Ici, le verbe de base est be : we must be careful. Careful ne change pas.", "tip": "Must be + adjectif : le verbe être garde sa forme de base be.", "extraExample": {"text": "You must be careful.", "translation": "Tu dois faire attention."}, "errorPatterns": [{"equals": "we must careful", "category": "grammar", "feedback": "Il manque be : après must, le verbe être se dit be. We must be careful."}, {"contains": "must are", "category": "grammar", "feedback": "Après must, le verbe être se dit be, pas are : we must be careful."}, {"contains": "carefull", "category": "spelling", "feedback": "Careful s''écrit avec un seul l à la fin."}], "pool": "lesson", "lessonId": "en.l15", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l15.e10', 'en', 'en.l15', 'en.g12.must', array['en.g12.must','en.v.drive']::text[], 'free_answer', 'lesson', 'Tom est fatigué. Comment dit-on « Il ne doit pas conduire » en anglais ?', array['He mustn''t drive.','Tom mustn''t drive.','He isn''t allowed to drive.','He is not allowed to drive.','Tom isn''t allowed to drive.','Tom is not allowed to drive.']::text[], 'Mustn''t exprime une interdiction et ne change jamais, même avec he. Le verbe qui suit reste à sa forme de base : he mustn''t drive.', 3, '{"id": "en.l15.e10", "unitIds": ["en.g12.must", "en.v.drive"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Tom est fatigué. Comment dit-on « Il ne doit pas conduire » en anglais ?", "promptLanguage": "fr", "answer": "He mustn''t drive.", "acceptedAnswers": ["He mustn''t drive.", "Tom mustn''t drive.", "He isn''t allowed to drive.", "He is not allowed to drive.", "Tom isn''t allowed to drive.", "Tom is not allowed to drive."], "hint": "Même avec he, mustn''t ne change pas.", "explanation": "Mustn''t exprime une interdiction et ne change jamais, même avec he. Le verbe qui suit reste à sa forme de base : he mustn''t drive.", "tip": "Must et mustn''t : jamais de -s, même avec he ou she.", "extraExample": {"text": "She mustn''t swim.", "translation": "Elle ne doit pas nager."}, "errorPatterns": [{"contains": "mustn''t drives", "category": "conjugation", "feedback": "Après mustn''t, le verbe reste à sa forme de base : he mustn''t drive."}, {"contains": "mustn''t to", "category": "grammar", "feedback": "Après mustn''t, on n''ajoute pas to : he mustn''t drive."}, {"contains": "he musts", "category": "conjugation", "feedback": "Must ne prend jamais de -s, même avec he : he mustn''t drive."}], "pool": "lesson", "lessonId": "en.l15", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l16.e01', 'en', 'en.l16', 'en.g13.imperative', array['en.g13.imperative','en.v.stand_up']::text[], 'mcq', 'lesson', 'Comment dit-on « Lève-toi ! » en anglais ?', array['Stand up!']::text[], 'Pour donner un ordre, on utilise le verbe de base, sans sujet : Stand up! On n''ajoute ni -s, ni to, ni le verbe être.', 1, '{"id": "en.l16.e01", "unitIds": ["en.g13.imperative", "en.v.stand_up"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Lève-toi ! » en anglais ?", "promptLanguage": "fr", "options": ["Stand up!", "Stands up!", "To stand up!", "You are stand up!"], "answer": "Stand up!", "acceptedAnswers": ["Stand up!"], "hint": "Un ordre = le verbe de base, tout seul.", "explanation": "Pour donner un ordre, on utilise le verbe de base, sans sujet : Stand up! On n''ajoute ni -s, ni to, ni le verbe être.", "tip": "Un ordre en anglais = le verbe tout seul.", "extraExample": {"text": "Sit down!", "translation": "Assieds-toi !"}, "errorPatterns": [{"equals": "stands up!", "category": "conjugation", "feedback": "Pour un ordre, le verbe reste à sa forme de base, sans -s : Stand up!"}, {"equals": "to stand up!", "category": "grammar", "feedback": "Dans un ordre, on n''ajoute pas to : on dit simplement Stand up!"}, {"equals": "you are stand up!", "category": "grammar", "feedback": "Un ordre n''a pas de sujet ni de verbe être : on dit simplement Stand up!"}], "pool": "lesson", "lessonId": "en.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l16.e02', 'en', 'en.l16', 'en.g13.imperative', array['en.g13.imperative']::text[], 'mcq', 'lesson', '___ be late!', array['Don''t']::text[], 'Pour dire à quelqu''un de ne pas faire quelque chose, on met Don''t devant le verbe de base : Don''t be late! Be est la forme de base du verbe être.', 1, '{"id": "en.l16.e02", "unitIds": ["en.g13.imperative"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le mot qui manque pour dire « Ne sois pas en retard ! »", "prompt": "___ be late!", "promptLanguage": "en", "options": ["Don''t", "Not", "No", "Isn''t"], "answer": "Don''t", "acceptedAnswers": ["Don''t"], "hint": "Pour interdire, on met un petit mot devant le verbe de base.", "explanation": "Pour dire à quelqu''un de ne pas faire quelque chose, on met Don''t devant le verbe de base : Don''t be late! Be est la forme de base du verbe être.", "tip": "Ordre négatif : Don''t + verbe de base.", "extraExample": {"text": "Don''t stop!", "translation": "Ne t''arrête pas !"}, "errorPatterns": [{"equals": "not", "category": "grammar", "feedback": "On ne met pas not seul devant le verbe dans un ordre. On dit Don''t + verbe : Don''t be late!"}, {"equals": "no", "category": "grammar", "feedback": "No veut dire « non » ou « aucun ». Pour interdire, on dit Don''t + verbe."}, {"equals": "isn''t", "category": "grammar", "feedback": "Isn''t ne convient pas devant be. Pour un ordre négatif, on dit toujours Don''t + verbe."}], "pool": "lesson", "lessonId": "en.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l16.e03', 'en', 'en.l16', 'en.g13.imperative', array['en.g13.imperative','en.v.come','en.v.look','en.v.listen','en.v.sit_down','en.v.stand_up']::text[], 'match', 'lesson', 'Les consignes : come, look, listen, sit down, stand up', '{}'::text[], 'L''impératif est le verbe de base tout seul. Sit down et stand up sont deux verbes à particule : ils se disent toujours avec down et up. Look est suivi de at devant ce qu''on regarde.', 1, '{"id": "en.l16.e03", "unitIds": ["en.g13.imperative", "en.v.come", "en.v.look", "en.v.listen", "en.v.sit_down", "en.v.stand_up"], "type": "match", "difficulty": 1, "instruction": "Associe chaque ordre anglais à sa traduction.", "prompt": "Les consignes : come, look, listen, sit down, stand up", "promptLanguage": "fr", "pairs": [{"left": "Come with me!", "right": "Viens avec moi !"}, {"left": "Look at the book!", "right": "Regarde le livre !"}, {"left": "Listen, please.", "right": "Écoute, s''il te plaît."}, {"left": "Sit down!", "right": "Assieds-toi !"}, {"left": "Stand up!", "right": "Lève-toi !"}], "answer": "Come with me! = Viens avec moi ! ; Look at the book! = Regarde le livre ! ; Listen, please. = Écoute, s''il te plaît. ; Sit down! = Assieds-toi ! ; Stand up! = Lève-toi !", "acceptedAnswers": [], "explanation": "L''impératif est le verbe de base tout seul. Sit down et stand up sont deux verbes à particule : ils se disent toujours avec down et up. Look est suivi de at devant ce qu''on regarde.", "tip": "Look at = regarder quelque chose. Sit down, stand up : les deux mots vont ensemble.", "extraExample": {"text": "Come and look at the window!", "translation": "Viens regarder la fenêtre !"}, "pool": "lesson", "lessonId": "en.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l16.e04', 'en', 'en.l16', 'en.g13.imperative', array['en.g13.imperative','en.v.open','en.v.door']::text[], 'fill_blank', 'lesson', 'Don''t ___ the door! (ouvrir)', array['open']::text[], 'Après Don''t, on met le verbe de base : Don''t open the door! On n''ajoute ni -s, ni to, ni -ing.', 2, '{"id": "en.l16.e04", "unitIds": ["en.g13.imperative", "en.v.open", "en.v.door"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme.", "prompt": "Don''t ___ the door! (ouvrir)", "promptLanguage": "en", "options": ["open", "opens", "to open", "opening"], "answer": "open", "acceptedAnswers": ["open"], "hint": "Après Don''t, le verbe est à sa forme de base.", "explanation": "Après Don''t, on met le verbe de base : Don''t open the door! On n''ajoute ni -s, ni to, ni -ing.", "tip": "Don''t + verbe de base : rien d''autre à ajouter.", "extraExample": {"text": "Don''t close the window!", "translation": "Ne ferme pas la fenêtre !"}, "errorPatterns": [{"equals": "opens", "category": "conjugation", "feedback": "Après Don''t, le verbe ne prend pas de -s : Don''t open."}, {"equals": "to open", "category": "grammar", "feedback": "Après Don''t, on n''ajoute pas to : Don''t open the door!"}, {"equals": "opening", "category": "grammar", "feedback": "Après Don''t, le verbe reste à sa forme de base, sans -ing : Don''t open."}], "pool": "lesson", "lessonId": "en.l16", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l16.e05', 'en', 'en.l16', 'en.g13.imperative', array['en.g13.imperative','en.v.go','en.v.home']::text[], 'fill_blank', 'lesson', '___ go home! (allons)', array['Let''s','Let us']::text[], 'Pour proposer de faire quelque chose ensemble, on dit Let''s + verbe de base : Let''s go home! Let''s est la contraction de let us.', 2, '{"id": "en.l16.e05", "unitIds": ["en.g13.imperative", "en.v.go", "en.v.home"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "___ go home! (allons)", "promptLanguage": "en", "options": ["Let''s", "Lets", "Let", "We"], "answer": "Let''s", "acceptedAnswers": ["Let''s", "Let us"], "hint": "Pour proposer quelque chose à plusieurs.", "explanation": "Pour proposer de faire quelque chose ensemble, on dit Let''s + verbe de base : Let''s go home! Let''s est la contraction de let us.", "tip": "Let''s + verbe de base = « allons-y, faisons… ».", "extraExample": {"text": "Let''s wait.", "translation": "Attendons."}, "errorPatterns": [{"equals": "lets", "category": "spelling", "feedback": "Il faut l''apostrophe : Let''s est la contraction de let us."}, {"equals": "let", "category": "grammar", "feedback": "Pour proposer quelque chose à plusieurs, on dit Let''s (let us), avec ''s."}, {"equals": "we", "category": "grammar", "feedback": "Pour dire « allons-y », on utilise Let''s + verbe, pas we."}], "pool": "lesson", "lessonId": "en.l16", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l16.e06', 'en', 'en.l16', 'en.g13.imperative', array['en.g13.imperative','en.v.listen','en.v.teacher']::text[], 'reorder', 'lesson', 'Écoute le professeur, s''il te plaît.', array['Please listen to the teacher','Listen to the teacher please']::text[], 'Un ordre commence par le verbe de base. Écouter quelqu''un se dit listen to. Please peut se placer au début ou à la fin.', 2, '{"id": "en.l16.e06", "unitIds": ["en.g13.imperative", "en.v.listen", "en.v.teacher"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Écoute le professeur, s''il te plaît.", "promptLanguage": "fr", "tokens": ["the", "Please", "teacher", "to", "listen"], "answer": "Please listen to the teacher", "acceptedAnswers": ["Please listen to the teacher", "Listen to the teacher please"], "hint": "Écouter quelqu''un se dit listen to.", "explanation": "Un ordre commence par le verbe de base. Écouter quelqu''un se dit listen to. Please peut se placer au début ou à la fin.", "tip": "Listen to + quelqu''un : en anglais, il faut to.", "extraExample": {"text": "Listen to your mother.", "translation": "Écoute ta mère."}, "pool": "lesson", "lessonId": "en.l16", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l16.e07', 'en', 'en.l16', 'en.g13.imperative', array['en.g13.imperative']::text[], 'translation', 'lesson', 'Ne sois pas en retard !', array['Don''t be late!','Do not be late!']::text[], 'Pour dire « ne… pas » dans un ordre, on utilise Don''t + verbe de base. Le verbe de base d''être est be : Don''t be late!', 2, '{"id": "en.l16.e07", "unitIds": ["en.g13.imperative"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Ne sois pas en retard !", "promptLanguage": "fr", "answer": "Don''t be late!", "acceptedAnswers": ["Don''t be late!", "Do not be late!"], "hint": "Ordre négatif : Don''t + verbe de base.", "explanation": "Pour dire « ne… pas » dans un ordre, on utilise Don''t + verbe de base. Le verbe de base d''être est be : Don''t be late!", "tip": "Don''t be + adjectif : le verbe être devient be.", "extraExample": {"text": "Don''t be tired!", "translation": "Ne sois pas fatigué !"}, "errorPatterns": [{"category": "grammar", "feedback": "Dans un ordre négatif, on met Don''t devant le verbe : Don''t be late!", "equals": "not be late"}, {"contains": "don''t late", "category": "grammar", "feedback": "Il manque le verbe be : Don''t be late!"}, {"contains": "don''t to be", "category": "grammar", "feedback": "Après Don''t, on n''ajoute pas to : Don''t be late!"}], "pool": "lesson", "lessonId": "en.l16", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l16.e08', 'en', 'en.l16', 'en.g13.imperative', array['en.g13.imperative','en.v.sit_down','en.v.listen']::text[], 'translation', 'lesson', 'Assieds-toi et écoute, s''il te plaît.', array['Sit down and listen, please.','Please sit down and listen.','Sit down and listen.','Please, sit down and listen.','You sit down and listen.']::text[], 'Chaque ordre est le verbe de base tout seul : sit down, puis listen. On les relie avec and, et please rend la phrase polie.', 3, '{"id": "en.l16.e08", "unitIds": ["en.g13.imperative", "en.v.sit_down", "en.v.listen"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Assieds-toi et écoute, s''il te plaît.", "promptLanguage": "fr", "answer": "Sit down and listen, please.", "acceptedAnswers": ["Sit down and listen, please.", "Please sit down and listen.", "Sit down and listen.", "Please, sit down and listen.", "You sit down and listen."], "hint": "Deux ordres reliés par and.", "explanation": "Chaque ordre est le verbe de base tout seul : sit down, puis listen. On les relie avec and, et please rend la phrase polie.", "tip": "Deux ordres de suite : sit down and listen, sans sujet.", "extraExample": {"text": "Stand up and come with me, please.", "translation": "Lève-toi et viens avec moi, s''il te plaît."}, "errorPatterns": [{"contains": "to sit", "category": "grammar", "feedback": "Dans un ordre, on n''ajoute pas to : Sit down and listen."}, {"contains": "sit and", "category": "vocabulary", "feedback": "S''asseoir se dit sit down, avec down : Sit down and listen."}], "pool": "lesson", "lessonId": "en.l16", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l16.e09', 'en', 'en.l16', 'en.g13.imperative', array['en.g13.imperative','en.v.come']::text[], 'free_answer', 'lesson', 'Comment dit-on « Viens avec moi ! » en anglais ?', array['Come with me!','Come with me, please!','Please come with me!','Please, come with me!','You come with me!']::text[], 'Pour donner un ordre, on utilise le verbe de base, sans sujet : Come! Avec moi se dit with me.', 3, '{"id": "en.l16.e09", "unitIds": ["en.g13.imperative", "en.v.come"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Viens avec moi ! » en anglais ?", "promptLanguage": "fr", "answer": "Come with me!", "acceptedAnswers": ["Come with me!", "Come with me, please!", "Please come with me!", "Please, come with me!", "You come with me!"], "hint": "Un ordre = le verbe de base. « Avec » se dit with.", "explanation": "Pour donner un ordre, on utilise le verbe de base, sans sujet : Come! Avec moi se dit with me.", "tip": "Pas de you devant un ordre : Come with me!", "extraExample": {"text": "Come home!", "translation": "Rentre à la maison !"}, "errorPatterns": [{"contains": "come with i", "category": "grammar", "feedback": "Après with, « moi » se dit me, pas I : Come with me!"}, {"contains": "comes", "category": "conjugation", "feedback": "Pour un ordre, le verbe reste à sa forme de base, sans -s : Come!"}], "pool": "lesson", "lessonId": "en.l16", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l16.e10', 'en', 'en.l16', 'en.g13.imperative', array['en.g13.imperative','en.v.look','en.v.phone']::text[], 'free_answer', 'lesson', 'Comment dit-on « Ne regardez pas le téléphone ! » en anglais ?', array['Don''t look at the phone!','Don''t look at your phone!']::text[], 'Pour interdire, on met Don''t devant le verbe de base : Don''t look. Regarder quelque chose se dit look at : look at the phone.', 3, '{"id": "en.l16.e10", "unitIds": ["en.g13.imperative", "en.v.look", "en.v.phone"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Ne regardez pas le téléphone ! » en anglais ?", "promptLanguage": "fr", "answer": "Don''t look at the phone!", "acceptedAnswers": ["Don''t look at the phone!", "Don''t look at your phone!"], "hint": "Ordre négatif + look at.", "explanation": "Pour interdire, on met Don''t devant le verbe de base : Don''t look. Regarder quelque chose se dit look at : look at the phone.", "tip": "Don''t look at… : regarder quelque chose = look at.", "extraExample": {"text": "Don''t look at the dog!", "translation": "Ne regarde pas le chien !"}, "errorPatterns": [{"contains": "don''t look the", "category": "preposition", "feedback": "Regarder quelque chose se dit look at : Don''t look at the phone!"}, {"contains": "not look", "category": "grammar", "feedback": "Dans un ordre négatif, on met Don''t devant le verbe : Don''t look at the phone!"}, {"contains": "don''t to look", "category": "grammar", "feedback": "Après Don''t, on n''ajoute pas to : Don''t look at the phone!"}], "pool": "lesson", "lessonId": "en.l16", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l17.e01', 'en', 'en.l17', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.live']::text[], 'mcq', 'lesson', 'We ___ in Paris.', array['live']::text[], 'Avec we, on utilise le verbe à sa forme de base : we live. On n''ajoute ni -s, ni are, ni -ing.', 1, '{"id": "en.l17.e01", "unitIds": ["en.g08.verbs_base_form", "en.v.live"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "We ___ in Paris.", "promptLanguage": "en", "options": ["live", "lives", "are live", "living"], "answer": "live", "acceptedAnswers": ["live"], "hint": "Avec we, le verbe garde sa forme de base.", "explanation": "Avec we, on utilise le verbe à sa forme de base : we live. On n''ajoute ni -s, ni are, ni -ing.", "tip": "I, you, we, they + verbe tel quel : we live, they live.", "extraExample": {"text": "They live in London.", "translation": "Ils habitent à Londres."}, "errorPatterns": [{"equals": "lives", "category": "conjugation", "feedback": "Avec we, le verbe ne prend pas de -s : we live."}, {"equals": "are live", "category": "grammar", "feedback": "Are est le verbe être : on ne le met pas devant un autre verbe. On dit we live."}, {"equals": "living", "category": "grammar", "feedback": "Pour dire où on habite en général, on utilise la forme de base : we live."}], "pool": "lesson", "lessonId": "en.l17", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l17.e02', 'en', 'en.l17', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.like','en.v.coffee']::text[], 'mcq', 'lesson', 'Comment dit-on « J''aime le café » (le café en général) en anglais ?', array['I like coffee.']::text[], 'Pour parler du café en général, on n''utilise pas d''article : I like coffee. I like the coffee parlerait d''un café précis.', 1, '{"id": "en.l17.e02", "unitIds": ["en.g08.verbs_base_form", "en.v.like", "en.v.coffee"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « J''aime le café » (le café en général) en anglais ?", "promptLanguage": "fr", "options": ["I like coffee.", "I like the coffee.", "I like to coffee.", "I am like coffee."], "answer": "I like coffee.", "acceptedAnswers": ["I like coffee."], "hint": "Pour parler d''une chose en général, on n''ajoute pas the.", "explanation": "Pour parler du café en général, on n''utilise pas d''article : I like coffee. I like the coffee parlerait d''un café précis.", "tip": "En général, pas d''article en anglais : I like coffee, I like dogs.", "extraExample": {"text": "We like dogs.", "translation": "Nous aimons les chiens."}, "errorPatterns": [{"equals": "i like the coffee.", "category": "grammar", "feedback": "The désigne un café précis. Pour parler du café en général, on dit I like coffee, sans article."}, {"equals": "i like to coffee.", "category": "grammar", "feedback": "To s''utilise devant un verbe, pas devant un nom : I like coffee."}, {"equals": "i am like coffee.", "category": "grammar", "feedback": "Am est le verbe être : on ne le met pas devant like. On dit I like coffee."}], "pool": "lesson", "lessonId": "en.l17", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l17.e03', 'en', 'en.l17', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.work','en.v.live','en.v.like','en.v.love','en.v.eat']::text[], 'match', 'lesson', 'Les verbes de tous les jours : work, live, like, love, eat', '{}'::text[], 'Avec I, we et they, le verbe reste à sa forme de base. Like veut dire « aimer bien » et love « aimer beaucoup, adorer » : love est plus fort que like.', 1, '{"id": "en.l17.e03", "unitIds": ["en.g08.verbs_base_form", "en.v.work", "en.v.live", "en.v.like", "en.v.love", "en.v.eat"], "type": "match", "difficulty": 1, "instruction": "Associe chaque phrase anglaise à sa traduction.", "prompt": "Les verbes de tous les jours : work, live, like, love, eat", "promptLanguage": "fr", "pairs": [{"left": "I work in London.", "right": "Je travaille à Londres."}, {"left": "We live in Paris.", "right": "Nous habitons à Paris."}, {"left": "I like coffee.", "right": "J''aime bien le café."}, {"left": "I love my family.", "right": "J''adore ma famille."}, {"left": "They eat at home.", "right": "Ils mangent à la maison."}], "answer": "I work in London. = Je travaille à Londres. ; We live in Paris. = Nous habitons à Paris. ; I like coffee. = J''aime bien le café. ; I love my family. = J''adore ma famille. ; They eat at home. = Ils mangent à la maison.", "acceptedAnswers": [], "explanation": "Avec I, we et they, le verbe reste à sa forme de base. Like veut dire « aimer bien » et love « aimer beaucoup, adorer » : love est plus fort que like.", "tip": "Like = aimer bien. Love = adorer. Love est plus fort.", "extraExample": {"text": "You like London and you love Paris.", "translation": "Tu aimes bien Londres et tu adores Paris."}, "pool": "lesson", "lessonId": "en.l17", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l17.e04', 'en', 'en.l17', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.work','en.v.school']::text[], 'fill_blank', 'lesson', 'I ___ in a school. (travailler)', array['work']::text[], '« Travailler » se dit work. Avec I, le verbe reste à sa forme de base : I work.', 2, '{"id": "en.l17.e04", "unitIds": ["en.g08.verbs_base_form", "en.v.work", "en.v.school"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon verbe.", "prompt": "I ___ in a school. (travailler)", "promptLanguage": "en", "options": ["work", "works", "live", "eat"], "answer": "work", "acceptedAnswers": ["work"], "hint": "Le verbe qui veut dire « travailler ».", "explanation": "« Travailler » se dit work. Avec I, le verbe reste à sa forme de base : I work.", "tip": "Work = travailler. Avec I : work, sans -s.", "extraExample": {"text": "They work with children.", "translation": "Ils travaillent avec des enfants."}, "errorPatterns": [{"equals": "works", "category": "conjugation", "feedback": "Avec I, le verbe ne prend pas de -s : I work."}, {"equals": "live", "category": "vocabulary", "feedback": "Live veut dire « habiter ». Pour « travailler », on dit work."}, {"equals": "eat", "category": "vocabulary", "feedback": "Eat veut dire « manger ». Pour « travailler », on dit work."}], "pool": "lesson", "lessonId": "en.l17", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l17.e05', 'en', 'en.l17', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.eat','en.v.dinner']::text[], 'fill_blank', 'lesson', 'We ___ dinner with our friends. (manger)', array['eat']::text[], '« Manger » se dit eat. Avec we, le verbe reste à sa forme de base : we eat. Eat dinner veut dire « dîner, manger le dîner ».', 2, '{"id": "en.l17.e05", "unitIds": ["en.g08.verbs_base_form", "en.v.eat", "en.v.dinner"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon verbe.", "prompt": "We ___ dinner with our friends. (manger)", "promptLanguage": "en", "options": ["eat", "eats", "make", "like"], "answer": "eat", "acceptedAnswers": ["eat"], "hint": "Le verbe qui veut dire « manger ».", "explanation": "« Manger » se dit eat. Avec we, le verbe reste à sa forme de base : we eat. Eat dinner veut dire « dîner, manger le dîner ».", "tip": "Eat = manger. Avec we : eat, sans -s.", "extraExample": {"text": "I eat at home.", "translation": "Je mange à la maison."}, "errorPatterns": [{"equals": "eats", "category": "conjugation", "feedback": "Avec we, le verbe ne prend pas de -s : we eat."}, {"equals": "make", "category": "vocabulary", "feedback": "Make veut dire « préparer, fabriquer ». Pour « manger », on dit eat."}, {"equals": "like", "category": "vocabulary", "feedback": "Like veut dire « aimer bien ». Pour « manger », on dit eat."}], "pool": "lesson", "lessonId": "en.l17", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l17.e06', 'en', 'en.l17', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.like','en.v.love']::text[], 'reorder', 'lesson', 'J''aime bien Londres et j''adore Paris.', array['I like London and I love Paris']::text[], 'On répète le sujet I devant chaque verbe : I like London and I love Paris. Like exprime « aimer bien » et love « adorer ».', 2, '{"id": "en.l17.e06", "unitIds": ["en.g08.verbs_base_form", "en.v.like", "en.v.love"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "J''aime bien Londres et j''adore Paris.", "promptLanguage": "fr", "tokens": ["London", "I", "like", "and", "love", "I", "Paris"], "answer": "I like London and I love Paris", "acceptedAnswers": ["I like London and I love Paris"], "hint": "Like pour « aimer bien », love pour « adorer ».", "explanation": "On répète le sujet I devant chaque verbe : I like London and I love Paris. Like exprime « aimer bien » et love « adorer ».", "tip": "Like = aimer bien, love = adorer (plus fort).", "extraExample": {"text": "We like coffee and we love dinner with friends.", "translation": "Nous aimons bien le café et nous adorons dîner avec des amis."}, "pool": "lesson", "lessonId": "en.l17", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l17.e07', 'en', 'en.l17', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.work','en.v.live']::text[], 'translation', 'lesson', 'Je travaille à Londres.', array['I work in London.','I am working in London.']::text[], '« Travailler » se dit work. Avec I, le verbe reste à sa forme de base. Devant le nom d''une ville, « à » se dit in : in London.', 2, '{"id": "en.l17.e07", "unitIds": ["en.g08.verbs_base_form", "en.v.work", "en.v.live"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Je travaille à Londres.", "promptLanguage": "fr", "answer": "I work in London.", "acceptedAnswers": ["I work in London.", "I am working in London."], "hint": "Travailler = work. « À » devant une ville se dit in.", "explanation": "« Travailler » se dit work. Avec I, le verbe reste à sa forme de base. Devant le nom d''une ville, « à » se dit in : in London.", "tip": "Devant une ville : in London, in Paris.", "extraExample": {"text": "You work in Paris.", "translation": "Tu travailles à Paris."}, "errorPatterns": [{"contains": "i works", "category": "conjugation", "feedback": "Avec I, le verbe ne prend pas de -s : I work."}, {"contains": "i am work", "category": "grammar", "feedback": "Am est le verbe être : on ne le met pas devant un autre verbe. On dit I work."}, {"contains": "work to london", "category": "preposition", "feedback": "Pour dire où on travaille, on utilise in : I work in London."}], "pool": "lesson", "lessonId": "en.l17", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l17.e08', 'en', 'en.l17', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.eat','en.v.hungry','en.g10.want_need_to']::text[], 'translation', 'lesson', 'J''ai faim et je veux manger.', array['I am hungry and I want to eat.','I am hungry and want to eat.']::text[], '« Avoir faim » se dit be hungry : I am hungry. Ensuite, want est suivi de to + verbe de base : I want to eat.', 3, '{"id": "en.l17.e08", "unitIds": ["en.g08.verbs_base_form", "en.v.eat", "en.v.hungry", "en.g10.want_need_to"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "J''ai faim et je veux manger.", "promptLanguage": "fr", "answer": "I am hungry and I want to eat.", "acceptedAnswers": ["I am hungry and I want to eat.", "I am hungry and want to eat."], "hint": "En anglais, on ne dit pas « avoir faim » avec have.", "explanation": "« Avoir faim » se dit be hungry : I am hungry. Ensuite, want est suivi de to + verbe de base : I want to eat.", "tip": "Avoir faim = be hungry. Jamais « have hungry ».", "extraExample": {"text": "We are tired and we want to go home.", "translation": "Nous sommes fatigués et nous voulons rentrer à la maison."}, "errorPatterns": [{"contains": "have hungry", "category": "grammar", "feedback": "En anglais, on utilise être, pas avoir : I am hungry."}, {"contains": "want eat", "category": "grammar", "feedback": "Il manque to entre want et eat : I want to eat."}, {"contains": "have hunger", "category": "grammar", "feedback": "Pour « avoir faim », on dit be hungry : I am hungry."}], "pool": "lesson", "lessonId": "en.l17", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l17.e09', 'en', 'en.l17', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.live','en.v.parents']::text[], 'free_answer', 'lesson', 'Comment dit-on « Ils habitent avec leurs parents » en anglais ?', array['They live with their parents.','They are living with their parents.']::text[], '« Habiter » se dit live. Avec they, le verbe reste à sa forme de base : they live. Leurs parents se dit their parents.', 3, '{"id": "en.l17.e09", "unitIds": ["en.g08.verbs_base_form", "en.v.live", "en.v.parents"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Ils habitent avec leurs parents » en anglais ?", "promptLanguage": "fr", "answer": "They live with their parents.", "acceptedAnswers": ["They live with their parents.", "They are living with their parents."], "hint": "Habiter = live. Avec = with. Leurs = their.", "explanation": "« Habiter » se dit live. Avec they, le verbe reste à sa forme de base : they live. Leurs parents se dit their parents.", "tip": "Avec they : live, sans -s. Et leurs = their.", "extraExample": {"text": "I live with my sister.", "translation": "J''habite avec ma sœur."}, "errorPatterns": [{"contains": "they lives", "category": "conjugation", "feedback": "Avec they, le verbe ne prend pas de -s : they live."}, {"contains": "they are live", "category": "grammar", "feedback": "Are est le verbe être : on ne le met pas devant un autre verbe. On dit they live."}, {"contains": "with they", "category": "grammar", "feedback": "« Leurs parents » se dit their parents (adjectif possessif), pas they."}], "pool": "lesson", "lessonId": "en.l17", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l17.e10', 'en', 'en.l17', 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.love','en.v.family']::text[], 'free_answer', 'lesson', 'Comment dit-on « J''adore ma famille » en anglais ?', array['I love my family.','I adore my family.']::text[], '« Adorer » se dit love. Avec I, le verbe reste à sa forme de base : I love. Ma famille se dit my family.', 3, '{"id": "en.l17.e10", "unitIds": ["en.g08.verbs_base_form", "en.v.love", "en.v.family"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « J''adore ma famille » en anglais ?", "promptLanguage": "fr", "answer": "I love my family.", "acceptedAnswers": ["I love my family.", "I adore my family."], "hint": "Adorer = love, plus fort que like.", "explanation": "« Adorer » se dit love. Avec I, le verbe reste à sa forme de base : I love. Ma famille se dit my family.", "tip": "Love = adorer, aimer beaucoup. Avec I : love, sans -s.", "extraExample": {"text": "We love our dog.", "translation": "Nous adorons notre chien."}, "errorPatterns": [{"contains": "i loves", "category": "conjugation", "feedback": "Avec I, le verbe ne prend pas de -s : I love."}, {"contains": "i like my", "category": "vocabulary", "feedback": "Like veut dire « aimer bien ». Pour « adorer », on dit love."}, {"contains": "the family", "category": "grammar", "feedback": "« Ma famille » se dit my family : on utilise l''adjectif possessif my, pas the."}], "pool": "lesson", "lessonId": "en.l17", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l18.e01', 'en', 'en.l18', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.sleep']::text[], 'mcq', 'lesson', 'My dog ___ in the house.', array['sleeps']::text[], 'My dog est un sujet au singulier : on peut le remplacer par it. Avec he, she, it (ou un nom singulier), le verbe prend -s : the dog sleeps.', 1, '{"id": "en.l18.e01", "unitIds": ["en.g14.present_simple_third_person", "en.v.sleep"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme du verbe.", "prompt": "My dog ___ in the house.", "promptLanguage": "en", "options": ["sleeps", "sleep", "sleepes"], "answer": "sleeps", "acceptedAnswers": ["sleeps"], "hint": "My dog = it : un seul animal.", "explanation": "My dog est un sujet au singulier : on peut le remplacer par it. Avec he, she, it (ou un nom singulier), le verbe prend -s : the dog sleeps.", "tip": "He, she, it, my dog : le verbe prend -s.", "extraExample": {"text": "My brother sleeps in the car.", "translation": "Mon frère dort dans la voiture."}, "errorPatterns": [{"equals": "sleep", "category": "conjugation", "feedback": "My dog est un sujet singulier (= it) : le verbe doit prendre -s. On dit my dog sleeps."}, {"equals": "sleepes", "category": "spelling", "feedback": "Sleep se termine par -p : on ajoute simplement -s. Le -es est réservé à d''autres verbes (watch, fix…)."}], "pool": "lesson", "lessonId": "en.l18", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l18.e02', 'en', 'en.l18', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.watch']::text[], 'mcq', 'lesson', 'My parents ___ TV after dinner.', array['watch']::text[], 'My parents veut dire « ils » (they) : plusieurs personnes. Avec they, le verbe garde sa forme de base, sans -s : they watch. Le -s de parents est le -s du pluriel du nom, pas celui du verbe.', 1, '{"id": "en.l18.e02", "unitIds": ["en.g14.present_simple_third_person", "en.v.watch"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme du verbe.", "prompt": "My parents ___ TV after dinner.", "promptLanguage": "en", "options": ["watch", "watches", "watchs"], "answer": "watch", "acceptedAnswers": ["watch"], "hint": "My parents = they : plusieurs personnes.", "explanation": "My parents veut dire « ils » (they) : plusieurs personnes. Avec they, le verbe garde sa forme de base, sans -s : they watch. Le -s de parents est le -s du pluriel du nom, pas celui du verbe.", "tip": "Le -s du verbe, c''est pour un seul sujet (he, she, it). Pour plusieurs personnes : pas de -s.", "extraExample": {"text": "My friends drink coffee.", "translation": "Mes amis boivent du café."}, "errorPatterns": [{"equals": "watches", "category": "conjugation", "feedback": "My parents = they : le sujet est pluriel, donc le verbe n''a pas de -s. Le -s du verbe, c''est seulement avec he, she, it."}, {"equals": "watchs", "category": "spelling", "feedback": "Ici le sujet est pluriel (they) : pas de -s, on écrit watch. (Avec he ou she, ce serait watches, pas watchs.)"}], "pool": "lesson", "lessonId": "en.l18", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l18.e03', 'en', 'en.l18', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.drink','en.v.play','en.v.sleep','en.v.cook','en.v.watch']::text[], 'match', 'lesson', 'Les nouveaux verbes avec leur sujet', '{}'::text[], 'Avec un sujet singulier (he, she, my dog, my mother), le verbe prend -s. Avec they, il reste à sa forme de base : they watch.', 1, '{"id": "en.l18.e03", "unitIds": ["en.g14.present_simple_third_person", "en.v.drink", "en.v.play", "en.v.sleep", "en.v.cook", "en.v.watch"], "type": "match", "difficulty": 1, "instruction": "Associe chaque phrase anglaise à sa traduction.", "prompt": "Les nouveaux verbes avec leur sujet", "promptLanguage": "fr", "pairs": [{"left": "he drinks", "right": "il boit"}, {"left": "she plays", "right": "elle joue"}, {"left": "my dog sleeps", "right": "mon chien dort"}, {"left": "my mother cooks", "right": "ma mère cuisine"}, {"left": "they watch", "right": "ils regardent"}], "answer": "he drinks = il boit ; she plays = elle joue ; my dog sleeps = mon chien dort ; my mother cooks = ma mère cuisine ; they watch = ils regardent", "acceptedAnswers": [], "explanation": "Avec un sujet singulier (he, she, my dog, my mother), le verbe prend -s. Avec they, il reste à sa forme de base : they watch.", "tip": "Un seul sujet : -s. Plusieurs sujets (they) : pas de -s.", "extraExample": {"text": "He plays and she cooks.", "translation": "Il joue et elle cuisine."}, "pool": "lesson", "lessonId": "en.l18", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l18.e04', 'en', 'en.l18', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.play']::text[], 'fill_blank', 'lesson', 'My son ___ with his friends after school.', array['plays']::text[], 'My son se remplace par he : un seul garçon. Au présent simple, le verbe prend -s avec he, she, it : plays. Après une voyelle + y, on ajoute simplement -s.', 2, '{"id": "en.l18.e04", "unitIds": ["en.g14.present_simple_third_person", "en.v.play"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme du verbe play.", "prompt": "My son ___ with his friends after school.", "promptLanguage": "en", "options": ["play", "plays", "playes"], "answer": "plays", "acceptedAnswers": ["plays"], "hint": "My son = he.", "explanation": "My son se remplace par he : un seul garçon. Au présent simple, le verbe prend -s avec he, she, it : plays. Après une voyelle + y, on ajoute simplement -s.", "tip": "He, she, it + verbe + s : he plays, she plays, it plays.", "extraExample": {"text": "She plays with her dog.", "translation": "Elle joue avec son chien."}, "errorPatterns": [{"equals": "play", "category": "conjugation", "feedback": "My son = he : un seul sujet, donc le verbe prend -s. On dit my son plays."}, {"equals": "playes", "category": "spelling", "feedback": "Après voyelle + y (play), on ajoute seulement -s : plays, pas playes."}], "pool": "lesson", "lessonId": "en.l18", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l18.e05', 'en', 'en.l18', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.cook']::text[], 'fill_blank', 'lesson', 'Anna and I ___ dinner for our friends.', array['cook']::text[], 'Anna and I veut dire « nous » (we). Avec we, le verbe garde sa forme de base : we cook. Le -s n''apparaît qu''avec he, she, it.', 2, '{"id": "en.l18.e05", "unitIds": ["en.g14.present_simple_third_person", "en.v.cook"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme du verbe cook.", "prompt": "Anna and I ___ dinner for our friends.", "promptLanguage": "en", "options": ["cook", "cooks", "to cook"], "answer": "cook", "acceptedAnswers": ["cook"], "hint": "Anna and I = we (nous).", "explanation": "Anna and I veut dire « nous » (we). Avec we, le verbe garde sa forme de base : we cook. Le -s n''apparaît qu''avec he, she, it.", "tip": "Anna and I = we : pas de -s.", "extraExample": {"text": "My brother and I play with the dog.", "translation": "Mon frère et moi, nous jouons avec le chien."}, "errorPatterns": [{"equals": "cooks", "category": "conjugation", "feedback": "Anna and I = we (nous), plusieurs personnes : pas de -s. On dit Anna and I cook."}, {"equals": "to cook", "category": "grammar", "feedback": "Après le sujet, on met directement le verbe conjugué, sans to : we cook."}], "pool": "lesson", "lessonId": "en.l18", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l18.e06', 'en', 'en.l18', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.drink']::text[], 'reorder', 'lesson', 'Mon père boit du café à la maison.', array['My father drinks coffee at home','At home my father drinks coffee']::text[], 'L''ordre habituel est sujet + verbe + complément. My father = he, donc le verbe prend -s : drinks. On termine par le lieu : at home.', 2, '{"id": "en.l18.e06", "unitIds": ["en.g14.present_simple_third_person", "en.v.drink"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Mon père boit du café à la maison.", "promptLanguage": "fr", "tokens": ["home", "drinks", "at", "My", "coffee", "father"], "answer": "My father drinks coffee at home", "acceptedAnswers": ["My father drinks coffee at home", "At home my father drinks coffee"], "hint": "Commence par le sujet : My father.", "explanation": "L''ordre habituel est sujet + verbe + complément. My father = he, donc le verbe prend -s : drinks. On termine par le lieu : at home.", "tip": "Sujet, verbe avec -s, puis le reste de la phrase.", "extraExample": {"text": "My mother cooks dinner at home.", "translation": "Ma mère prépare le dîner à la maison."}, "pool": "lesson", "lessonId": "en.l18", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l18.e07', 'en', 'en.l18', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.cook']::text[], 'translation', 'lesson', 'Ma sœur cuisine pour la famille.', array['My sister cooks for the family.','My sister cooks for her family.','My sister cooks for my family.','My sister cooks for our family.','My sister is cooking for the family.','My sister is cooking for her family.','My sister is cooking for my family.','My sister is cooking for our family.']::text[], 'My sister se remplace par she, donc le verbe cook prend -s : cooks. « Pour la famille » se dit for the family.', 2, '{"id": "en.l18.e07", "unitIds": ["en.g14.present_simple_third_person", "en.v.cook"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Ma sœur cuisine pour la famille.", "promptLanguage": "fr", "answer": "My sister cooks for the family.", "acceptedAnswers": ["My sister cooks for the family.", "My sister cooks for her family.", "My sister cooks for my family.", "My sister cooks for our family.", "My sister is cooking for the family.", "My sister is cooking for her family.", "My sister is cooking for my family.", "My sister is cooking for our family."], "hint": "Ma sœur = she : le verbe prend -s.", "explanation": "My sister se remplace par she, donc le verbe cook prend -s : cooks. « Pour la famille » se dit for the family.", "tip": "Ma sœur, mon père, Tom : un seul sujet, un -s sur le verbe.", "extraExample": {"text": "My father cooks for his friends.", "translation": "Mon père cuisine pour ses amis."}, "errorPatterns": [{"contains": "sister cook for", "category": "conjugation", "feedback": "My sister = she : le verbe doit prendre -s. On dit my sister cooks."}, {"contains": "sister make for", "category": "word_confusion", "feedback": "Pour « cuisiner », on utilise cook. En plus, avec my sister (= she), le verbe prend -s : cooks."}], "pool": "lesson", "lessonId": "en.l18", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l18.e08', 'en', 'en.l18', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.drink','en.v.sleep']::text[], 'translation', 'lesson', 'Mes parents boivent du café et mon fils dort.', array['My parents drink coffee and my son sleeps.','My parents drink coffee and my son is sleeping.','My parents are drinking coffee and my son sleeps.','My parents are drinking coffee and my son is sleeping.']::text[], 'My parents = they : pas de -s sur drink. My son = he : -s sur sleep. C''est le sujet qui décide, pas le nom : parents finit par -s mais le verbe n''en prend pas.', 3, '{"id": "en.l18.e08", "unitIds": ["en.g14.present_simple_third_person", "en.v.drink", "en.v.sleep"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Mes parents boivent du café et mon fils dort.", "promptLanguage": "fr", "answer": "My parents drink coffee and my son sleeps.", "acceptedAnswers": ["My parents drink coffee and my son sleeps.", "My parents drink coffee and my son is sleeping.", "My parents are drinking coffee and my son sleeps.", "My parents are drinking coffee and my son is sleeping."], "hint": "Un sujet pluriel (they) et un sujet singulier (he).", "explanation": "My parents = they : pas de -s sur drink. My son = he : -s sur sleep. C''est le sujet qui décide, pas le nom : parents finit par -s mais le verbe n''en prend pas.", "tip": "Compte les personnes : une seule → -s sur le verbe, plusieurs → rien.", "extraExample": {"text": "My friends play and my sister cooks.", "translation": "Mes amis jouent et ma sœur cuisine."}, "errorPatterns": [{"contains": "parents drinks coffee", "category": "conjugation", "feedback": "My parents = they (plusieurs personnes) : pas de -s sur le verbe. On dit my parents drink."}, {"equals": "my parents drink coffee and my son sleep", "category": "conjugation", "feedback": "My son = he : un seul garçon, donc sleep prend -s. On dit my son sleeps."}], "pool": "lesson", "lessonId": "en.l18", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l18.e09', 'en', 'en.l18', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.cook']::text[], 'free_answer', 'lesson', 'Comment dit-on « Mon mari cuisine » ?', array['My husband cooks.','My husband is cooking.']::text[], 'My husband se remplace par he, donc le verbe cook prend -s : my husband cooks. Cook n''a pas besoin de complément pour dire qu''on cuisine.', 3, '{"id": "en.l18.e09", "unitIds": ["en.g14.present_simple_third_person", "en.v.cook"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Mon mari cuisine » ?", "promptLanguage": "fr", "answer": "My husband cooks.", "acceptedAnswers": ["My husband cooks.", "My husband is cooking."], "hint": "Mon mari = he : le verbe prend un -s.", "explanation": "My husband se remplace par he, donc le verbe cook prend -s : my husband cooks. Cook n''a pas besoin de complément pour dire qu''on cuisine.", "tip": "Mon mari, ma femme, Tom : -s sur le verbe.", "extraExample": {"text": "My wife plays with the dog.", "translation": "Ma femme joue avec le chien."}, "errorPatterns": [{"equals": "my husband cook", "category": "conjugation", "feedback": "My husband = he : un seul sujet, donc le verbe prend -s. On dit my husband cooks."}, {"equals": "my husband cookes", "category": "spelling", "feedback": "Cook se termine par -k : on ajoute simplement -s (cooks)."}], "pool": "lesson", "lessonId": "en.l18", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l18.e10', 'en', 'en.l18', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.drink','en.v.play','en.v.watch','en.v.sleep','en.v.cook']::text[], 'free_answer', 'lesson', 'Que fait une personne que tu connais ? Écris une phrase.', array['My brother plays with his friends.','My mother cooks dinner for the family.','Anna drinks coffee at home.','My dog sleeps in the house.']::text[], 'Avec un sujet au singulier (he, she, my brother, Anna), le verbe au présent simple prend -s : plays, cooks, drinks, sleeps, watches.', 4, '{"id": "en.l18.e10", "unitIds": ["en.g14.present_simple_third_person", "en.v.drink", "en.v.play", "en.v.watch", "en.v.sleep", "en.v.cook"], "type": "free_answer", "difficulty": 4, "instruction": "Écris une phrase sur une personne de ta famille ou un ami, avec un de ces verbes : drink, play, watch, sleep ou cook. Pense au -s !", "prompt": "Que fait une personne que tu connais ? Écris une phrase.", "promptLanguage": "fr", "requirements": {"mustInclude": [["drinks", "plays", "watches", "sleeps", "cooks"]], "minWords": 3}, "answer": "My brother plays with his friends.", "acceptedAnswers": ["My brother plays with his friends.", "My mother cooks dinner for the family.", "Anna drinks coffee at home.", "My dog sleeps in the house."], "hint": "Choisis un sujet au singulier (he, she, my mother, Tom) et ajoute -s au verbe.", "explanation": "Avec un sujet au singulier (he, she, my brother, Anna), le verbe au présent simple prend -s : plays, cooks, drinks, sleeps, watches.", "tip": "Relis ton verbe : si ton sujet est « il » ou « elle », il lui faut un -s.", "extraExample": {"text": "Lucy watches TV with her mother.", "translation": "Lucy regarde la télé avec sa mère."}, "errorPatterns": [{"contains": "he play with", "category": "conjugation", "feedback": "Avec he, le verbe prend -s : he plays with…"}, {"contains": "she cook dinner", "category": "conjugation", "feedback": "Avec she, le verbe prend -s : she cooks dinner."}], "pool": "lesson", "lessonId": "en.l18", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l19.e01', 'en', 'en.l19', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.study']::text[], 'mcq', 'lesson', 'Lucy ___ French at school.', array['studies']::text[], 'Lucy = she, donc le verbe prend une terminaison. Study se termine par consonne + y : on change le y en i et on ajoute -es. On obtient studies.', 1, '{"id": "en.l19.e01", "unitIds": ["en.g14.present_simple_third_person", "en.v.study"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme du verbe.", "prompt": "Lucy ___ French at school.", "promptLanguage": "en", "options": ["studies", "study", "studys", "studyes"], "answer": "studies", "acceptedAnswers": ["studies"], "hint": "Study se termine par une consonne + y.", "explanation": "Lucy = she, donc le verbe prend une terminaison. Study se termine par consonne + y : on change le y en i et on ajoute -es. On obtient studies.", "tip": "Consonne + y : y → i, puis -es (study → studies).", "extraExample": {"text": "My brother studies English.", "translation": "Mon frère étudie l''anglais."}, "errorPatterns": [{"equals": "study", "category": "conjugation", "feedback": "Lucy = she : le verbe doit prendre une terminaison. Study devient studies."}, {"equals": "studys", "category": "spelling", "feedback": "Après une consonne + y, on change le y en i : studies, pas studys."}, {"equals": "studyes", "category": "spelling", "feedback": "Il faut changer le y en i avant -es : studies, pas studyes."}], "pool": "lesson", "lessonId": "en.l19", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l19.e02', 'en', 'en.l19', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person']::text[], 'mcq', 'lesson', 'Tom ___ to school by car.', array['goes']::text[], 'Tom = he : le verbe prend une terminaison. Les verbes comme go, do et watch prennent -es et non -s : he goes.', 2, '{"id": "en.l19.e02", "unitIds": ["en.g14.present_simple_third_person"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme du verbe.", "prompt": "Tom ___ to school by car.", "promptLanguage": "en", "options": ["goes", "go", "gos"], "answer": "goes", "acceptedAnswers": ["goes"], "hint": "Go est un verbe qui prend -es.", "explanation": "Tom = he : le verbe prend une terminaison. Les verbes comme go, do et watch prennent -es et non -s : he goes.", "tip": "Go → goes, do → does : on ajoute -es.", "extraExample": {"text": "My sister goes to London by car.", "translation": "Ma sœur va à Londres en voiture."}, "errorPatterns": [{"equals": "go", "category": "conjugation", "feedback": "Tom = he : le verbe doit prendre une terminaison. Go devient goes."}, {"equals": "gos", "category": "spelling", "feedback": "Go prend -es, pas seulement -s : goes."}], "pool": "lesson", "lessonId": "en.l19", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l19.e03', 'en', 'en.l19', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.fix','en.v.carry','en.v.teach','en.v.study','en.v.finish']::text[], 'match', 'lesson', 'Les nouveaux verbes à la 3e personne', '{}'::text[], 'Les verbes qui finissent par -x, -ch ou -sh prennent -es (fixes, teaches, finishes). Les verbes en consonne + y changent y en i et prennent -es (carries, studies).', 2, '{"id": "en.l19.e03", "unitIds": ["en.g14.present_simple_third_person", "en.v.fix", "en.v.carry", "en.v.teach", "en.v.study", "en.v.finish"], "type": "match", "difficulty": 2, "instruction": "Associe chaque phrase anglaise à sa traduction.", "prompt": "Les nouveaux verbes à la 3e personne", "promptLanguage": "fr", "pairs": [{"left": "he fixes", "right": "il répare"}, {"left": "she carries", "right": "elle porte"}, {"left": "he teaches", "right": "il enseigne"}, {"left": "she studies", "right": "elle étudie"}, {"left": "he finishes", "right": "il finit"}], "answer": "he fixes = il répare ; she carries = elle porte ; he teaches = il enseigne ; she studies = elle étudie ; he finishes = il finit", "acceptedAnswers": [], "explanation": "Les verbes qui finissent par -x, -ch ou -sh prennent -es (fixes, teaches, finishes). Les verbes en consonne + y changent y en i et prennent -es (carries, studies).", "tip": "-x, -ch, -sh → -es. Consonne + y → -ies.", "extraExample": {"text": "She watches TV and he fixes the car.", "translation": "Elle regarde la télé et il répare la voiture."}, "pool": "lesson", "lessonId": "en.l19", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l19.e04', 'en', 'en.l19', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.teach']::text[], 'fill_blank', 'lesson', 'My mother ___ English at a school in London.', array['teaches']::text[], 'My mother = she. Teach se termine par -ch : on ajoute -es, pas seulement -s. On obtient teaches, qui se prononce avec un son « iz » à la fin.', 2, '{"id": "en.l19.e04", "unitIds": ["en.g14.present_simple_third_person", "en.v.teach"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme du verbe teach.", "prompt": "My mother ___ English at a school in London.", "promptLanguage": "en", "options": ["teaches", "teachs", "teach"], "answer": "teaches", "acceptedAnswers": ["teaches"], "hint": "Teach se termine par -ch.", "explanation": "My mother = she. Teach se termine par -ch : on ajoute -es, pas seulement -s. On obtient teaches, qui se prononce avec un son « iz » à la fin.", "tip": "-ch → -es : teach → teaches, watch → watches.", "extraExample": {"text": "My sister watches TV after school.", "translation": "Ma sœur regarde la télé après l''école."}, "errorPatterns": [{"equals": "teachs", "category": "spelling", "feedback": "Après -ch, on ajoute -es : teaches. Teachs serait impossible à prononcer."}, {"equals": "teach", "category": "conjugation", "feedback": "My mother = she : le verbe doit prendre une terminaison. Teach devient teaches."}], "pool": "lesson", "lessonId": "en.l19", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l19.e05', 'en', 'en.l19', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.finish']::text[], 'fill_blank', 'lesson', 'Tom ___ his homework after dinner.', array['finishes']::text[], 'Tom = he. Finish se termine par -sh : on ajoute -es. On obtient finishes.', 2, '{"id": "en.l19.e05", "unitIds": ["en.g14.present_simple_third_person", "en.v.finish"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme du verbe finish.", "prompt": "Tom ___ his homework after dinner.", "promptLanguage": "en", "options": ["finishes", "finishs", "finish"], "answer": "finishes", "acceptedAnswers": ["finishes"], "hint": "Finish se termine par -sh.", "explanation": "Tom = he. Finish se termine par -sh : on ajoute -es. On obtient finishes.", "tip": "-sh → -es : finish → finishes, wash → washes.", "extraExample": {"text": "Anna finishes work at six.", "translation": "Anna finit le travail à six heures."}, "errorPatterns": [{"equals": "finishs", "category": "spelling", "feedback": "Après -sh, on ajoute -es : finishes."}, {"equals": "finish", "category": "conjugation", "feedback": "Tom = he : le verbe prend une terminaison. Finish devient finishes."}], "pool": "lesson", "lessonId": "en.l19", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l19.e06', 'en', 'en.l19', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.carry']::text[], 'reorder', 'lesson', 'Anna porte son sac à l''école.', array['Anna carries her bag to school']::text[], 'Anna = she, donc le verbe prend une terminaison. Carry se termine par consonne + y : carries. Her est l''adjectif possessif qui correspond à Anna.', 2, '{"id": "en.l19.e06", "unitIds": ["en.g14.present_simple_third_person", "en.v.carry"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Anna porte son sac à l''école.", "promptLanguage": "fr", "tokens": ["bag", "to", "school", "Anna", "her", "carries"], "answer": "Anna carries her bag to school", "acceptedAnswers": ["Anna carries her bag to school"], "hint": "Commence par le sujet : Anna.", "explanation": "Anna = she, donc le verbe prend une terminaison. Carry se termine par consonne + y : carries. Her est l''adjectif possessif qui correspond à Anna.", "tip": "Carry → carries, study → studies : y devient i.", "extraExample": {"text": "My father carries the bags to the car.", "translation": "Mon père porte les sacs jusqu''à la voiture."}, "pool": "lesson", "lessonId": "en.l19", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l19.e07', 'en', 'en.l19', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.fix']::text[], 'translation', 'lesson', 'Mon père répare la voiture.', array['My father fixes the car.','My dad fixes the car.','My father repairs the car.','My dad repairs the car.','My father is fixing the car.','My dad is fixing the car.','My father is repairing the car.','My dad is repairing the car.']::text[], 'My father = he. Fix se termine par -x : on ajoute -es, ce qui donne fixes. « La voiture » se dit the car.', 2, '{"id": "en.l19.e07", "unitIds": ["en.g14.present_simple_third_person", "en.v.fix"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Mon père répare la voiture.", "promptLanguage": "fr", "answer": "My father fixes the car.", "acceptedAnswers": ["My father fixes the car.", "My dad fixes the car.", "My father repairs the car.", "My dad repairs the car.", "My father is fixing the car.", "My dad is fixing the car.", "My father is repairing the car.", "My dad is repairing the car."], "hint": "Fix se termine par -x.", "explanation": "My father = he. Fix se termine par -x : on ajoute -es, ce qui donne fixes. « La voiture » se dit the car.", "tip": "-x → -es : fix → fixes, mix → mixes.", "extraExample": {"text": "My brother fixes his phone.", "translation": "Mon frère répare son téléphone."}, "errorPatterns": [{"contains": "fix the car", "category": "conjugation", "feedback": "Avec my father (= he), le verbe prend une terminaison : fixes."}, {"contains": "fixs", "category": "spelling", "feedback": "Après -x, on ajoute -es : fixes."}], "pool": "lesson", "lessonId": "en.l19", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l19.e08', 'en', 'en.l19', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.study']::text[], 'translation', 'lesson', 'Il fait ses devoirs et elle étudie l''anglais.', array['He does his homework and she studies English.','He is doing his homework and she studies English.','He does his homework and she is studying English.','He is doing his homework and she is studying English.']::text[], 'Avec he, do devient does : he does his homework. Study devient studies avec she (consonne + y). Pour « faire ses devoirs », on utilise do et non make.', 3, '{"id": "en.l19.e08", "unitIds": ["en.g14.present_simple_third_person", "en.v.study"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Il fait ses devoirs et elle étudie l''anglais.", "promptLanguage": "fr", "answer": "He does his homework and she studies English.", "acceptedAnswers": ["He does his homework and she studies English.", "He is doing his homework and she studies English.", "He does his homework and she is studying English.", "He is doing his homework and she is studying English."], "hint": "On fait ses devoirs se dit avec do. Do prend -es avec he.", "explanation": "Avec he, do devient does : he does his homework. Study devient studies avec she (consonne + y). Pour « faire ses devoirs », on utilise do et non make.", "tip": "Les devoirs, ça se « fait » avec do : do homework.", "extraExample": {"text": "He does his homework at home.", "translation": "Il fait ses devoirs à la maison."}, "errorPatterns": [{"contains": "he do his homework", "category": "conjugation", "feedback": "Avec he, do devient does : he does his homework."}, {"contains": "he makes his homework", "category": "word_confusion", "feedback": "Pour les devoirs, on utilise do et non make : he does his homework."}, {"contains": "she studys", "category": "spelling", "feedback": "Study devient studies : on change le y en i avant -es."}], "pool": "lesson", "lessonId": "en.l19", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l19.e09', 'en', 'en.l19', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person']::text[], 'free_answer', 'lesson', 'Comment dit-on « Elle a deux frères et une sœur » ?', array['She has two brothers and a sister.','She has got two brothers and a sister.']::text[], 'Avec he, she, it, have devient has : she has. C''est une forme irrégulière (pas « haves »). Brothers est au pluriel après two.', 3, '{"id": "en.l19.e09", "unitIds": ["en.g14.present_simple_third_person"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Elle a deux frères et une sœur » ?", "promptLanguage": "fr", "answer": "She has two brothers and a sister.", "acceptedAnswers": ["She has two brothers and a sister.", "She has got two brothers and a sister."], "hint": "Have change de forme avec she.", "explanation": "Avec he, she, it, have devient has : she has. C''est une forme irrégulière (pas « haves »). Brothers est au pluriel après two.", "tip": "Have → has avec he, she, it.", "extraExample": {"text": "My father has a car and a house.", "translation": "Mon père a une voiture et une maison."}, "errorPatterns": [{"contains": "she have two", "category": "conjugation", "feedback": "Avec she, have devient has : she has two brothers."}, {"contains": "she haves", "category": "spelling", "feedback": "La forme de have avec he, she, it est has, pas haves."}], "pool": "lesson", "lessonId": "en.l19", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l19.e10', 'en', 'en.l19', 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.v.study','en.v.finish','en.v.teach','en.v.carry','en.v.fix']::text[], 'free_answer', 'lesson', 'Que fait cette personne ? Écris une phrase.', array['My father fixes cars.','Anna studies English.','My mother teaches French at a school.','Tom finishes work at six.']::text[], 'Avec he, she ou un sujet au singulier, le verbe prend -es s''il finit par -x, -ch ou -sh (fixes, teaches, finishes), et -ies après une consonne + y (studies, carries).', 4, '{"id": "en.l19.e10", "unitIds": ["en.g14.present_simple_third_person", "en.v.study", "en.v.finish", "en.v.teach", "en.v.carry", "en.v.fix"], "type": "free_answer", "difficulty": 4, "instruction": "Écris une phrase sur une personne que tu connais, avec un de ces verbes : study, finish, teach, carry ou fix. Fais attention à la terminaison !", "prompt": "Que fait cette personne ? Écris une phrase.", "promptLanguage": "fr", "requirements": {"mustInclude": [["studies", "finishes", "teaches", "carries", "fixes"]], "minWords": 3}, "answer": "My father fixes cars.", "acceptedAnswers": ["My father fixes cars.", "Anna studies English.", "My mother teaches French at a school.", "Tom finishes work at six."], "hint": "Choisis un sujet au singulier, puis demande-toi : -s, -es ou -ies ?", "explanation": "Avec he, she ou un sujet au singulier, le verbe prend -es s''il finit par -x, -ch ou -sh (fixes, teaches, finishes), et -ies après une consonne + y (studies, carries).", "tip": "Avant d''écrire, regarde la fin du verbe : -x, -ch, -sh ou consonne + y ?", "extraExample": {"text": "Lucy carries her books to school.", "translation": "Lucy porte ses livres à l''école."}, "errorPatterns": [{"contains": "she studys", "category": "spelling", "feedback": "Study devient studies : on change le y en i avant -es."}, {"contains": "he teachs", "category": "spelling", "feedback": "Après -ch, on ajoute -es : teaches."}], "pool": "lesson", "lessonId": "en.l19", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l20.e01', 'en', 'en.l20', 'en.g15.present_simple_negative', array['en.g15.present_simple_negative','en.v.milk']::text[], 'mcq', 'lesson', 'My brother ___ drink milk.', array['doesn''t']::text[], 'My brother se remplace par he. Avec he, she, it, la négation du présent simple se fait avec doesn''t + le verbe de base : he doesn''t drink.', 1, '{"id": "en.l20.e01", "unitIds": ["en.g15.present_simple_negative", "en.v.milk"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "My brother ___ drink milk.", "promptLanguage": "en", "options": ["doesn''t", "don''t", "not"], "answer": "doesn''t", "acceptedAnswers": ["doesn''t"], "hint": "My brother = he.", "explanation": "My brother se remplace par he. Avec he, she, it, la négation du présent simple se fait avec doesn''t + le verbe de base : he doesn''t drink.", "tip": "I, you, we, they : don''t. He, she, it : doesn''t.", "extraExample": {"text": "I don''t drink milk.", "translation": "Je ne bois pas de lait."}, "errorPatterns": [{"equals": "don''t", "category": "conjugation", "feedback": "Don''t s''utilise avec I, you, we, they. Avec my brother (= he), on dit doesn''t."}, {"equals": "not", "category": "grammar", "feedback": "On ne peut pas mettre not seul devant un verbe d''action comme drink : il faut doesn''t ou don''t."}], "pool": "lesson", "lessonId": "en.l20", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l20.e02', 'en', 'en.l20', 'en.g15.present_simple_negative', array['en.g15.present_simple_negative','en.v.meat']::text[], 'mcq', 'lesson', 'Comment dit-on « Tom ne mange pas de viande » ?', array['Tom doesn''t eat meat.']::text[], 'Avec Tom (= he), on utilise doesn''t. Après doesn''t, le verbe reste à sa forme de base : eat, sans -s. Meat s''emploie sans article quand on parle de la viande en général.', 2, '{"id": "en.l20.e02", "unitIds": ["en.g15.present_simple_negative", "en.v.meat"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « Tom ne mange pas de viande » ?", "promptLanguage": "fr", "options": ["Tom doesn''t eat meat.", "Tom doesn''t eats meat.", "Tom don''t eat meat.", "Tom not eat meat."], "answer": "Tom doesn''t eat meat.", "acceptedAnswers": ["Tom doesn''t eat meat."], "hint": "Doesn''t + verbe de base.", "explanation": "Avec Tom (= he), on utilise doesn''t. Après doesn''t, le verbe reste à sa forme de base : eat, sans -s. Meat s''emploie sans article quand on parle de la viande en général.", "tip": "Doesn''t + verbe tout simple : he doesn''t eat.", "extraExample": {"text": "My sister doesn''t eat fish.", "translation": "Ma sœur ne mange pas de poisson."}, "errorPatterns": [{"equals": "Tom doesn''t eats meat.", "category": "conjugation", "feedback": "Après doesn''t, le verbe reste à sa forme de base : le -s est déjà dans does. On dit doesn''t eat."}, {"equals": "Tom don''t eat meat.", "category": "conjugation", "feedback": "Avec Tom (= he), on utilise doesn''t et non don''t."}, {"equals": "Tom not eat meat.", "category": "grammar", "feedback": "Il faut doesn''t devant le verbe : not seul ne suffit pas au présent simple."}], "pool": "lesson", "lessonId": "en.l20", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l20.e03', 'en', 'en.l20', 'en.g15.present_simple_negative', array['en.g15.present_simple_negative','en.v.food','en.v.meat','en.v.fish','en.v.milk','en.v.water']::text[], 'match', 'lesson', 'Les mots de la nourriture et des boissons', '{}'::text[], 'Ces cinq mots sont des noms. Quand on parle de nourriture ou de boisson en général, on les utilise sans article : I don''t eat meat (et non « the meat »).', 1, '{"id": "en.l20.e03", "unitIds": ["en.g15.present_simple_negative", "en.v.food", "en.v.meat", "en.v.fish", "en.v.milk", "en.v.water"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot anglais à sa traduction.", "prompt": "Les mots de la nourriture et des boissons", "promptLanguage": "fr", "pairs": [{"left": "food", "right": "la nourriture"}, {"left": "meat", "right": "la viande"}, {"left": "fish", "right": "le poisson"}, {"left": "milk", "right": "le lait"}, {"left": "water", "right": "l''eau"}], "answer": "food = la nourriture ; meat = la viande ; fish = le poisson ; milk = le lait ; water = l''eau", "acceptedAnswers": [], "explanation": "Ces cinq mots sont des noms. Quand on parle de nourriture ou de boisson en général, on les utilise sans article : I don''t eat meat (et non « the meat »).", "tip": "En anglais, pas d''article pour parler en général : I like fish.", "extraExample": {"text": "We don''t drink milk at school.", "translation": "Nous ne buvons pas de lait à l''école."}, "pool": "lesson", "lessonId": "en.l20", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l20.e04', 'en', 'en.l20', 'en.g15.present_simple_negative', array['en.g15.present_simple_negative']::text[], 'fill_blank', 'lesson', 'She doesn''t ___ to school.', array['go']::text[], 'Après doesn''t, le verbe reste à sa forme de base. On utilise donc go et non goes.', 2, '{"id": "en.l20.e04", "unitIds": ["en.g15.present_simple_negative"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le verbe go (aller) à la bonne forme.", "prompt": "She doesn''t ___ to school.", "promptLanguage": "en", "options": ["go", "goes", "to go"], "answer": "go", "acceptedAnswers": ["go"], "hint": "Où est déjà le -s dans cette phrase ?", "explanation": "Après doesn''t, le verbe reste à sa forme de base. On utilise donc go et non goes.", "tip": "Le -s est déjà présent dans does : on ne l''ajoute pas une seconde fois au verbe principal.", "extraExample": {"text": "He doesn''t work today.", "translation": "Il ne travaille pas aujourd''hui."}, "errorPatterns": [{"equals": "goes", "category": "conjugation", "feedback": "Après doesn''t, le verbe reste à sa forme de base : le -s est déjà dans does."}, {"equals": "to go", "category": "grammar", "feedback": "Après doesn''t, on met directement le verbe de base, sans to."}], "pool": "lesson", "lessonId": "en.l20", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l20.e05', 'en', 'en.l20', 'en.g15.present_simple_negative', array['en.g15.present_simple_negative','en.v.food']::text[], 'fill_blank', 'lesson', 'My parents ___ like the food in London.', array['don''t']::text[], 'My parents veut dire « ils » (they). Avec they, la négation se fait avec don''t. Le verbe like reste à sa forme de base.', 2, '{"id": "en.l20.e05", "unitIds": ["en.g15.present_simple_negative", "en.v.food"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec don''t ou doesn''t.", "prompt": "My parents ___ like the food in London.", "promptLanguage": "en", "options": ["don''t", "doesn''t", "aren''t"], "answer": "don''t", "acceptedAnswers": ["don''t"], "hint": "My parents = they : plusieurs personnes.", "explanation": "My parents veut dire « ils » (they). Avec they, la négation se fait avec don''t. Le verbe like reste à sa forme de base.", "tip": "Un sujet pluriel (my parents, my friends) → don''t.", "extraExample": {"text": "My friends don''t eat meat.", "translation": "Mes amis ne mangent pas de viande."}, "errorPatterns": [{"equals": "doesn''t", "category": "conjugation", "feedback": "My parents = they (pluriel) : on utilise don''t. Doesn''t est réservé à he, she, it."}, {"equals": "aren''t", "category": "grammar", "feedback": "Aren''t s''emploie avec be (they aren''t tired). Avec un verbe d''action comme like, on utilise don''t."}], "pool": "lesson", "lessonId": "en.l20", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l20.e06', 'en', 'en.l20', 'en.g15.present_simple_negative', array['en.g15.present_simple_negative','en.v.meat','en.v.fish']::text[], 'reorder', 'lesson', 'Mon fils ne mange ni viande ni poisson.', array['My son doesn''t eat meat or fish','My son doesn''t eat fish or meat']::text[], 'My son = he, donc on utilise doesn''t suivi du verbe de base eat. En anglais, après une négation, on relie les deux choses avec or (« ou ») : meat or fish.', 2, '{"id": "en.l20.e06", "unitIds": ["en.g15.present_simple_negative", "en.v.meat", "en.v.fish"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Mon fils ne mange ni viande ni poisson.", "promptLanguage": "fr", "tokens": ["son", "My", "eat", "or", "doesn''t", "meat", "fish"], "answer": "My son doesn''t eat meat or fish", "acceptedAnswers": ["My son doesn''t eat meat or fish", "My son doesn''t eat fish or meat"], "hint": "Le sujet, puis doesn''t, puis le verbe de base.", "explanation": "My son = he, donc on utilise doesn''t suivi du verbe de base eat. En anglais, après une négation, on relie les deux choses avec or (« ou ») : meat or fish.", "tip": "Sujet + doesn''t + verbe de base + complément.", "extraExample": {"text": "My daughter doesn''t drink milk or water.", "translation": "Ma fille ne boit ni lait ni eau."}, "pool": "lesson", "lessonId": "en.l20", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l20.e07', 'en', 'en.l20', 'en.g15.present_simple_negative', array['en.g15.present_simple_negative','en.v.meat']::text[], 'translation', 'lesson', 'Je ne mange pas de viande.', array['I don''t eat meat.','I don''t eat any meat.','I''m not eating meat.','I''m not eating any meat.']::text[], 'Avec I, la négation se fait avec don''t + verbe de base : I don''t eat. « De la viande » se dit simplement meat, sans article.', 2, '{"id": "en.l20.e07", "unitIds": ["en.g15.present_simple_negative", "en.v.meat"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Je ne mange pas de viande.", "promptLanguage": "fr", "answer": "I don''t eat meat.", "acceptedAnswers": ["I don''t eat meat.", "I don''t eat any meat.", "I''m not eating meat.", "I''m not eating any meat."], "hint": "Il n''y a pas de « ne… pas » collé au verbe en anglais.", "explanation": "Avec I, la négation se fait avec don''t + verbe de base : I don''t eat. « De la viande » se dit simplement meat, sans article.", "tip": "I don''t + verbe : c''est don''t qui porte la négation.", "extraExample": {"text": "We don''t eat fish.", "translation": "Nous ne mangeons pas de poisson."}, "errorPatterns": [{"contains": "i not eat", "category": "grammar", "feedback": "Au présent simple, on ne met pas not seul : il faut I don''t eat."}, {"contains": "i no eat", "category": "grammar", "feedback": "En anglais, on dit I don''t eat. No ne se place pas devant le verbe."}, {"contains": "eat the meat", "category": "grammar", "feedback": "Pour parler de la viande en général, on n''utilise pas the : I don''t eat meat."}], "pool": "lesson", "lessonId": "en.l20", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l20.e08', 'en', 'en.l20', 'en.g15.present_simple_negative', array['en.g15.present_simple_negative','en.v.milk','en.v.fish']::text[], 'translation', 'lesson', 'Elle ne boit pas de lait et il ne mange pas de poisson.', array['She doesn''t drink milk and he doesn''t eat fish.','She isn''t drinking milk and he isn''t eating fish.']::text[], 'Elle (she) et il (he) demandent doesn''t. Après doesn''t, les verbes drink et eat restent à la forme de base, sans -s.', 3, '{"id": "en.l20.e08", "unitIds": ["en.g15.present_simple_negative", "en.v.milk", "en.v.fish"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Elle ne boit pas de lait et il ne mange pas de poisson.", "promptLanguage": "fr", "answer": "She doesn''t drink milk and he doesn''t eat fish.", "acceptedAnswers": ["She doesn''t drink milk and he doesn''t eat fish.", "She isn''t drinking milk and he isn''t eating fish."], "hint": "Deux sujets au singulier : deux fois doesn''t.", "explanation": "Elle (she) et il (he) demandent doesn''t. Après doesn''t, les verbes drink et eat restent à la forme de base, sans -s.", "tip": "Une négation, un doesn''t : répète-le pour chaque verbe.", "extraExample": {"text": "She doesn''t eat meat and he doesn''t drink milk.", "translation": "Elle ne mange pas de viande et il ne boit pas de lait."}, "errorPatterns": [{"contains": "she don''t drink", "category": "conjugation", "feedback": "Avec she, on utilise doesn''t et non don''t."}, {"contains": "doesn''t drinks", "category": "conjugation", "feedback": "Après doesn''t, le verbe reste à sa forme de base : le -s est déjà dans does."}, {"contains": "doesn''t eats", "category": "conjugation", "feedback": "Après doesn''t, le verbe reste à sa forme de base : he doesn''t eat."}], "pool": "lesson", "lessonId": "en.l20", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l20.e09', 'en', 'en.l20', 'en.g15.present_simple_negative', array['en.g15.present_simple_negative','en.v.water']::text[], 'free_answer', 'lesson', 'Comment dit-on « Ma fille ne boit pas d''eau » ?', array['My daughter doesn''t drink water.','My daughter isn''t drinking water.']::text[], 'My daughter = she, donc la négation se fait avec doesn''t. Le verbe drink reste à sa forme de base. On dit water sans article.', 3, '{"id": "en.l20.e09", "unitIds": ["en.g15.present_simple_negative", "en.v.water"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Ma fille ne boit pas d''eau » ?", "promptLanguage": "fr", "answer": "My daughter doesn''t drink water.", "acceptedAnswers": ["My daughter doesn''t drink water.", "My daughter isn''t drinking water."], "hint": "Ma fille = she.", "explanation": "My daughter = she, donc la négation se fait avec doesn''t. Le verbe drink reste à sa forme de base. On dit water sans article.", "tip": "Ma fille, mon fils, Anna : doesn''t + verbe de base.", "extraExample": {"text": "My son doesn''t drink water.", "translation": "Mon fils ne boit pas d''eau."}, "errorPatterns": [{"equals": "my daughter don''t drink water", "category": "conjugation", "feedback": "My daughter = she : il faut doesn''t, pas don''t."}, {"equals": "my daughter doesn''t drinks water", "category": "conjugation", "feedback": "Après doesn''t, le verbe reste à sa forme de base : drink, sans -s."}], "pool": "lesson", "lessonId": "en.l20", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l20.e10', 'en', 'en.l20', 'en.g15.present_simple_negative', array['en.g15.present_simple_negative','en.v.food','en.v.meat','en.v.fish','en.v.milk','en.v.water']::text[], 'free_answer', 'lesson', 'Qu''est-ce que tu ne manges pas, ou qu''une personne de ta famille ne boit pas ?', array['I don''t eat meat.','I don''t drink milk.','My brother doesn''t eat fish.','My mother doesn''t drink water.']::text[], 'On utilise don''t avec I, you, we, they et doesn''t avec he, she, it. Après les deux, le verbe reste à sa forme de base : I don''t eat, she doesn''t eat.', 4, '{"id": "en.l20.e10", "unitIds": ["en.g15.present_simple_negative", "en.v.food", "en.v.meat", "en.v.fish", "en.v.milk", "en.v.water"], "type": "free_answer", "difficulty": 4, "instruction": "Écris une phrase négative sur ce que toi ou une personne que tu connais ne mange pas ou ne boit pas. Utilise don''t ou doesn''t.", "prompt": "Qu''est-ce que tu ne manges pas, ou qu''une personne de ta famille ne boit pas ?", "promptLanguage": "fr", "requirements": {"mustInclude": [["don''t", "doesn''t", "do not", "does not"]], "minWords": 4}, "answer": "I don''t eat meat.", "acceptedAnswers": ["I don''t eat meat.", "I don''t drink milk.", "My brother doesn''t eat fish.", "My mother doesn''t drink water."], "hint": "I, we, they → don''t ; he, she → doesn''t. Puis le verbe de base.", "explanation": "On utilise don''t avec I, you, we, they et doesn''t avec he, she, it. Après les deux, le verbe reste à sa forme de base : I don''t eat, she doesn''t eat.", "tip": "Avant de valider, vérifie : doesn''t + verbe sans -s.", "extraExample": {"text": "My son doesn''t like fish.", "translation": "Mon fils n''aime pas le poisson."}, "errorPatterns": [{"contains": "i doesn''t", "category": "conjugation", "feedback": "Avec I, on utilise don''t : I don''t…"}, {"contains": "she don''t", "category": "conjugation", "feedback": "Avec she, on utilise doesn''t : she doesn''t…"}], "pool": "lesson", "lessonId": "en.l20", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l21.e01', 'en', 'en.l21', 'en.g16.present_simple_questions', array['en.g16.present_simple_questions','en.v.breakfast']::text[], 'mcq', 'lesson', '___ your sister eat breakfast at home?', array['Does']::text[], 'Your sister se remplace par she. Au présent simple, une question avec he, she, it commence par Does. Le verbe eat reste ensuite à la forme de base.', 1, '{"id": "en.l21.e01", "unitIds": ["en.g16.present_simple_questions", "en.v.breakfast"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot pour poser la question.", "prompt": "___ your sister eat breakfast at home?", "promptLanguage": "en", "options": ["Does", "Do", "Is"], "answer": "Does", "acceptedAnswers": ["Does"], "hint": "Your sister = she.", "explanation": "Your sister se remplace par she. Au présent simple, une question avec he, she, it commence par Does. Le verbe eat reste ensuite à la forme de base.", "tip": "Do avec I, you, we, they. Does avec he, she, it.", "extraExample": {"text": "Does your brother eat breakfast?", "translation": "Est-ce que ton frère prend un petit-déjeuner ?"}, "errorPatterns": [{"equals": "Do", "category": "conjugation", "feedback": "Your sister = she : on commence la question par Does. Do est pour I, you, we, they."}, {"equals": "Is", "category": "grammar", "feedback": "Is s''emploie avec to be (Is she tired ?). Avec un verbe d''action comme eat, on pose la question avec Do ou Does."}], "pool": "lesson", "lessonId": "en.l21", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l21.e02', 'en', 'en.l21', 'en.g16.present_simple_questions', array['en.g16.present_simple_questions','en.v.night']::text[], 'mcq', 'lesson', 'Comment dit-on « Est-ce que ton frère travaille la nuit ? »', array['Does your brother work at night?']::text[], 'Ton frère = he, donc la question commence par Does. Après Does, le verbe reste à sa forme de base : work, sans -s. On dit at night pour « la nuit ».', 2, '{"id": "en.l21.e02", "unitIds": ["en.g16.present_simple_questions", "en.v.night"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la question correcte.", "prompt": "Comment dit-on « Est-ce que ton frère travaille la nuit ? »", "promptLanguage": "fr", "options": ["Does your brother work at night?", "Does your brother works at night?", "Do your brother work at night?", "Is your brother work at night?"], "answer": "Does your brother work at night?", "acceptedAnswers": ["Does your brother work at night?"], "hint": "Does + sujet + verbe de base.", "explanation": "Ton frère = he, donc la question commence par Does. Après Does, le verbe reste à sa forme de base : work, sans -s. On dit at night pour « la nuit ».", "tip": "Does + sujet + verbe de base : le -s est déjà dans Does.", "extraExample": {"text": "Does your mother work in the morning?", "translation": "Est-ce que ta mère travaille le matin ?"}, "errorPatterns": [{"equals": "Does your brother works at night?", "category": "conjugation", "feedback": "Après Does, le verbe reste à sa forme de base : le -s est déjà dans Does. On dit Does he work."}, {"equals": "Do your brother work at night?", "category": "conjugation", "feedback": "Your brother = he : on commence par Does, pas par Do."}, {"equals": "Is your brother work at night?", "category": "grammar", "feedback": "Is s''emploie avec to be. Avec le verbe work, on pose la question avec Does."}], "pool": "lesson", "lessonId": "en.l21", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l21.e03', 'en', 'en.l21', 'en.g16.present_simple_questions', array['en.g16.present_simple_questions','en.v.breakfast','en.v.lunch','en.v.morning','en.v.evening','en.v.night']::text[], 'match', 'lesson', 'Les repas et les moments de la journée', '{}'::text[], 'Breakfast et lunch s''emploient sans article quand on parle des repas en général. Pour les moments de la journée, on dit in the morning, in the evening mais at night.', 1, '{"id": "en.l21.e03", "unitIds": ["en.g16.present_simple_questions", "en.v.breakfast", "en.v.lunch", "en.v.morning", "en.v.evening", "en.v.night"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les repas et les moments de la journée", "promptLanguage": "fr", "pairs": [{"left": "breakfast", "right": "le petit-déjeuner"}, {"left": "lunch", "right": "le déjeuner"}, {"left": "in the morning", "right": "le matin"}, {"left": "in the evening", "right": "le soir"}, {"left": "at night", "right": "la nuit"}], "answer": "breakfast = le petit-déjeuner ; lunch = le déjeuner ; in the morning = le matin ; in the evening = le soir ; at night = la nuit", "acceptedAnswers": [], "explanation": "Breakfast et lunch s''emploient sans article quand on parle des repas en général. Pour les moments de la journée, on dit in the morning, in the evening mais at night.", "tip": "In the morning, in the evening, mais at night.", "extraExample": {"text": "Do you eat lunch at school?", "translation": "Est-ce que tu déjeunes à l''école ?"}, "pool": "lesson", "lessonId": "en.l21", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l21.e04', 'en', 'en.l21', 'en.g16.present_simple_questions', array['en.g16.present_simple_questions','en.v.evening']::text[], 'fill_blank', 'lesson', 'Does your mother ___ dinner in the evening?', array['cook']::text[], 'Après Does, le verbe reste à sa forme de base : cook. Le -s de la 3e personne est déjà dans Does, on ne le met pas deux fois.', 2, '{"id": "en.l21.e04", "unitIds": ["en.g16.present_simple_questions", "en.v.evening"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le verbe cook.", "prompt": "Does your mother ___ dinner in the evening?", "promptLanguage": "en", "options": ["cook", "cooks", "to cook"], "answer": "cook", "acceptedAnswers": ["cook"], "hint": "Où est déjà le -s dans cette question ?", "explanation": "Après Does, le verbe reste à sa forme de base : cook. Le -s de la 3e personne est déjà dans Does, on ne le met pas deux fois.", "tip": "Does porte le -s, le verbe reste tout simple.", "extraExample": {"text": "Does Tom play with his dog in the evening?", "translation": "Est-ce que Tom joue avec son chien le soir ?"}, "errorPatterns": [{"equals": "cooks", "category": "conjugation", "feedback": "Après Does, le verbe reste à sa forme de base : le -s est déjà dans Does. On dit Does she cook."}, {"equals": "to cook", "category": "grammar", "feedback": "Après Do ou Does, on met directement le verbe de base, sans to."}], "pool": "lesson", "lessonId": "en.l21", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l21.e05', 'en', 'en.l21', 'en.g16.present_simple_questions', array['en.g16.present_simple_questions','en.v.lunch']::text[], 'fill_blank', 'lesson', 'Do you eat lunch at school? No, I ___.', array['don''t']::text[], 'Pour répondre à une question avec Do, on reprend do ou don''t dans la réponse courte : No, I don''t. On ne répète pas le verbe eat.', 2, '{"id": "en.l21.e05", "unitIds": ["en.g16.present_simple_questions", "en.v.lunch"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la réponse courte.", "prompt": "Do you eat lunch at school? No, I ___.", "promptLanguage": "en", "options": ["don''t", "doesn''t", "am not"], "answer": "don''t", "acceptedAnswers": ["don''t"], "hint": "On reprend l''auxiliaire de la question.", "explanation": "Pour répondre à une question avec Do, on reprend do ou don''t dans la réponse courte : No, I don''t. On ne répète pas le verbe eat.", "tip": "Question avec Do → réponse avec do / don''t.", "extraExample": {"text": "Does Tom drink milk? No, he doesn''t.", "translation": "Est-ce que Tom boit du lait ? Non."}, "errorPatterns": [{"equals": "doesn''t", "category": "conjugation", "feedback": "Avec I, on reprend don''t. Doesn''t est pour he, she, it."}, {"equals": "am not", "category": "grammar", "feedback": "On répond avec le même auxiliaire que la question : question en Do → réponse en do / don''t, pas avec be."}], "pool": "lesson", "lessonId": "en.l21", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l21.e06', 'en', 'en.l21', 'en.g16.present_simple_questions', array['en.g16.present_simple_questions','en.v.morning']::text[], 'reorder', 'lesson', 'Est-ce qu''elle boit du café le matin ?', array['Does she drink coffee in the morning']::text[], 'L''ordre d''une question au présent simple est Does + sujet + verbe de base + le reste. Drink reste sans -s car Does porte déjà le -s.', 2, '{"id": "en.l21.e06", "unitIds": ["en.g16.present_simple_questions", "en.v.morning"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Est-ce qu''elle boit du café le matin ?", "promptLanguage": "fr", "tokens": ["coffee", "Does", "morning", "she", "in", "drink", "the"], "answer": "Does she drink coffee in the morning", "acceptedAnswers": ["Does she drink coffee in the morning"], "hint": "La question commence par Does.", "explanation": "L''ordre d''une question au présent simple est Does + sujet + verbe de base + le reste. Drink reste sans -s car Does porte déjà le -s.", "tip": "Does + sujet + verbe de base : toujours dans cet ordre.", "extraExample": {"text": "Does he eat breakfast in the morning?", "translation": "Est-ce qu''il prend un petit-déjeuner le matin ?"}, "pool": "lesson", "lessonId": "en.l21", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l21.e07', 'en', 'en.l21', 'en.g16.present_simple_questions', array['en.g16.present_simple_questions','en.v.breakfast']::text[], 'translation', 'lesson', 'Est-ce que tu manges le petit-déjeuner à la maison ?', array['Do you eat breakfast at home?','Do you have breakfast at home?','Do you eat your breakfast at home?','Do you have your breakfast at home?','Are you eating breakfast at home?','Are you having breakfast at home?']::text[], 'Avec you, la question commence par Do. Le verbe reste à sa forme de base. Breakfast s''emploie sans article : Do you eat breakfast ?', 2, '{"id": "en.l21.e07", "unitIds": ["en.g16.present_simple_questions", "en.v.breakfast"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Est-ce que tu manges le petit-déjeuner à la maison ?", "promptLanguage": "fr", "answer": "Do you eat breakfast at home?", "acceptedAnswers": ["Do you eat breakfast at home?", "Do you have breakfast at home?", "Do you eat your breakfast at home?", "Do you have your breakfast at home?", "Are you eating breakfast at home?", "Are you having breakfast at home?"], "hint": "Pas de « est-ce que » en anglais : on commence par Do.", "explanation": "Avec you, la question commence par Do. Le verbe reste à sa forme de base. Breakfast s''emploie sans article : Do you eat breakfast ?", "tip": "« Est-ce que tu… ? » se traduit par Do you… ?", "extraExample": {"text": "Do you eat lunch at home?", "translation": "Est-ce que tu déjeunes à la maison ?"}, "errorPatterns": [{"equals": "you eat breakfast at home", "category": "grammar", "feedback": "Pour poser une question au présent simple, il faut commencer par Do : Do you eat breakfast ?"}, {"contains": "are you eat breakfast", "category": "grammar", "feedback": "Are s''emploie avec to be ou avec un verbe en -ing. Avec eat, on commence par Do : Do you eat…"}, {"contains": "do you eats", "category": "conjugation", "feedback": "Après Do, le verbe reste à sa forme de base : Do you eat."}], "pool": "lesson", "lessonId": "en.l21", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l21.e08', 'en', 'en.l21', 'en.g16.present_simple_questions', array['en.g16.present_simple_questions','en.v.lunch']::text[], 'translation', 'lesson', 'Est-ce que ta sœur déjeune à l''école ?', array['Does your sister eat lunch at school?','Does your sister have lunch at school?','Does your sister eat her lunch at school?','Does your sister have her lunch at school?','Is your sister eating lunch at school?','Is your sister having lunch at school?']::text[], 'Ta sœur (your sister) = she, donc la question commence par Does. Le verbe eat reste à sa forme de base. On peut aussi dire have lunch.', 3, '{"id": "en.l21.e08", "unitIds": ["en.g16.present_simple_questions", "en.v.lunch"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Est-ce que ta sœur déjeune à l''école ?", "promptLanguage": "fr", "answer": "Does your sister eat lunch at school?", "acceptedAnswers": ["Does your sister eat lunch at school?", "Does your sister have lunch at school?", "Does your sister eat her lunch at school?", "Does your sister have her lunch at school?", "Is your sister eating lunch at school?", "Is your sister having lunch at school?"], "hint": "Ta sœur = she.", "explanation": "Ta sœur (your sister) = she, donc la question commence par Does. Le verbe eat reste à sa forme de base. On peut aussi dire have lunch.", "tip": "Ta sœur, ton frère, Anna : Does + verbe de base.", "extraExample": {"text": "Does your brother eat lunch at the office?", "translation": "Est-ce que ton frère déjeune au bureau ?"}, "errorPatterns": [{"contains": "do your sister", "category": "conjugation", "feedback": "Your sister = she : la question commence par Does, pas par Do."}, {"contains": "does your sister eats", "category": "conjugation", "feedback": "Après Does, le verbe reste à sa forme de base : le -s est déjà dans Does."}], "pool": "lesson", "lessonId": "en.l21", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l21.e09', 'en', 'en.l21', 'en.g16.present_simple_questions', array['en.g16.present_simple_questions']::text[], 'free_answer', 'lesson', 'Do you watch TV in the evening?', array['Yes, I do.']::text[], 'Pour une réponse courte, on reprend l''auxiliaire de la question : la question commence par Do, on répond Yes, I do. On ne répète pas le verbe watch.', 3, '{"id": "en.l21.e09", "unitIds": ["en.g16.present_simple_questions"], "type": "free_answer", "difficulty": 3, "instruction": "Réponds « oui » avec une réponse courte (Yes, …).", "prompt": "Do you watch TV in the evening?", "promptLanguage": "en", "answer": "Yes, I do.", "acceptedAnswers": ["Yes, I do."], "hint": "On reprend l''auxiliaire de la question.", "explanation": "Pour une réponse courte, on reprend l''auxiliaire de la question : la question commence par Do, on répond Yes, I do. On ne répète pas le verbe watch.", "tip": "Question en Do → Yes, I do. / No, I don''t.", "extraExample": {"text": "Does she cook? Yes, she does.", "translation": "Est-ce qu''elle cuisine ? Oui."}, "errorPatterns": [{"equals": "yes i am", "category": "grammar", "feedback": "La question commence par Do, donc on répond avec do : Yes, I do."}, {"equals": "yes i watch", "category": "instruction", "feedback": "La consigne demande une réponse courte : on reprend do au lieu du verbe. Yes, I do."}, {"equals": "yes i does", "category": "conjugation", "feedback": "Avec I, on utilise do : Yes, I do. Does est pour he, she, it."}], "pool": "lesson", "lessonId": "en.l21", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l21.e10', 'en', 'en.l21', 'en.g16.present_simple_questions', array['en.g16.present_simple_questions','en.v.breakfast','en.v.lunch','en.v.morning','en.v.evening','en.v.night']::text[], 'free_answer', 'lesson', 'Pose une question à un ami ou à un membre de ta famille.', array['Do you eat breakfast in the morning?','Does your mother cook dinner in the evening?','Do your parents eat lunch at home?','Does Tom work at night?']::text[], 'Une question au présent simple commence par Do ou Does, suivi du sujet et du verbe de base. Le verbe ne prend jamais de -s après Does.', 4, '{"id": "en.l21.e10", "unitIds": ["en.g16.present_simple_questions", "en.v.breakfast", "en.v.lunch", "en.v.morning", "en.v.evening", "en.v.night"], "type": "free_answer", "difficulty": 4, "instruction": "Écris une question avec Do ou Does pour interroger quelqu''un sur sa routine. Utilise breakfast, lunch, morning, evening ou night.", "prompt": "Pose une question à un ami ou à un membre de ta famille.", "promptLanguage": "fr", "requirements": {"mustInclude": [["do", "does"], ["breakfast", "lunch", "morning", "evening", "night"]], "minWords": 4}, "answer": "Do you eat breakfast in the morning?", "acceptedAnswers": ["Do you eat breakfast in the morning?", "Does your mother cook dinner in the evening?", "Do your parents eat lunch at home?", "Does Tom work at night?"], "hint": "Do avec you, we, they. Does avec he, she, it. Puis le verbe de base.", "explanation": "Une question au présent simple commence par Do ou Does, suivi du sujet et du verbe de base. Le verbe ne prend jamais de -s après Does.", "tip": "Relis : Does + sujet + verbe sans -s.", "extraExample": {"text": "Do your friends eat lunch at school?", "translation": "Est-ce que tes amis déjeunent à l''école ?"}, "errorPatterns": [{"contains": "does they", "category": "conjugation", "feedback": "Avec they, la question commence par Do : Do they…"}, {"contains": "do she", "category": "conjugation", "feedback": "Avec she, la question commence par Does : Does she…"}], "pool": "lesson", "lessonId": "en.l21", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l22.e01', 'en', 'en.l22', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.gym']::text[], 'mcq', 'lesson', 'Comment dit-on « Je vais toujours à la salle de sport le matin » ?', array['I always go to the gym in the morning.']::text[], 'Avec un verbe ordinaire, l''adverbe de fréquence se place avant le verbe : I always go. En français, toujours se met après le verbe (« je vais toujours »), mais pas en anglais.', 1, '{"id": "en.l22.e01", "unitIds": ["en.g17.frequency_adverbs", "en.v.gym"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « Je vais toujours à la salle de sport le matin » ?", "promptLanguage": "fr", "options": ["I always go to the gym in the morning.", "I go always to the gym in the morning.", "I go to always the gym in the morning."], "answer": "I always go to the gym in the morning.", "acceptedAnswers": ["I always go to the gym in the morning."], "hint": "Où se place always par rapport au verbe go ?", "explanation": "Avec un verbe ordinaire, l''adverbe de fréquence se place avant le verbe : I always go. En français, toujours se met après le verbe (« je vais toujours »), mais pas en anglais.", "tip": "Avant le verbe : I always go, she often eats.", "extraExample": {"text": "My sister always goes to the gym.", "translation": "Ma sœur va toujours à la salle de sport."}, "errorPatterns": [{"equals": "I go always to the gym in the morning.", "category": "word_order", "feedback": "L''adverbe de fréquence se place avant le verbe, pas après : I always go."}, {"equals": "I go to always the gym in the morning.", "category": "word_order", "feedback": "Always ne se place jamais au milieu d''un groupe comme to the gym. Mets-le avant le verbe : I always go."}], "pool": "lesson", "lessonId": "en.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l22.e02', 'en', 'en.l22', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.weekend']::text[], 'mcq', 'lesson', 'Quelle phrase est correcte ?', array['Tom is always happy at the weekend.']::text[], 'Avec le verbe be (am, is, are), l''adverbe de fréquence se place après be : Tom is always happy. Avec un autre verbe, il se place avant.', 1, '{"id": "en.l22.e02", "unitIds": ["en.g17.frequency_adverbs", "en.v.weekend"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la phrase correcte.", "prompt": "Quelle phrase est correcte ?", "promptLanguage": "fr", "options": ["Tom is always happy at the weekend.", "Tom always is happy at the weekend.", "Tom is happy always at the weekend."], "answer": "Tom is always happy at the weekend.", "acceptedAnswers": ["Tom is always happy at the weekend."], "hint": "Avec le verbe be, l''adverbe se place après be.", "explanation": "Avec le verbe be (am, is, are), l''adverbe de fréquence se place après be : Tom is always happy. Avec un autre verbe, il se place avant.", "tip": "Après be, avant les autres verbes.", "extraExample": {"text": "My parents are never late.", "translation": "Mes parents ne sont jamais en retard."}, "errorPatterns": [{"equals": "Tom always is happy at the weekend.", "category": "word_order", "feedback": "Avec be, l''adverbe se place après be : Tom is always happy."}, {"equals": "Tom is happy always at the weekend.", "category": "word_order", "feedback": "Always se place juste après is, avant happy : Tom is always happy."}], "pool": "lesson", "lessonId": "en.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l22.e03', 'en', 'en.l22', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs']::text[], 'match', 'lesson', 'Les adverbes de fréquence', '{}'::text[], 'Ces adverbes vont de 100 % (always) à 0 % (never) : always, usually, often, sometimes (parfois), rarely, never. Never a déjà un sens négatif.', 1, '{"id": "en.l22.e03", "unitIds": ["en.g17.frequency_adverbs"], "type": "match", "difficulty": 1, "instruction": "Associe chaque adverbe à sa traduction.", "prompt": "Les adverbes de fréquence", "promptLanguage": "fr", "pairs": [{"left": "always", "right": "toujours"}, {"left": "usually", "right": "d''habitude"}, {"left": "often", "right": "souvent"}, {"left": "rarely", "right": "rarement"}, {"left": "never", "right": "jamais"}], "answer": "always = toujours ; usually = d''habitude ; often = souvent ; rarely = rarement ; never = jamais", "acceptedAnswers": [], "explanation": "Ces adverbes vont de 100 % (always) à 0 % (never) : always, usually, often, sometimes (parfois), rarely, never. Never a déjà un sens négatif.", "tip": "Retiens l''échelle : always, usually, often, sometimes, rarely, never.", "extraExample": {"text": "I never drink coffee at night.", "translation": "Je ne bois jamais de café la nuit."}, "pool": "lesson", "lessonId": "en.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l22.e04', 'en', 'en.l22', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.music']::text[], 'fill_blank', 'lesson', 'My brother ___ listens to music. (parfois)', array['sometimes']::text[], 'Sometimes veut dire « parfois ». Il se place avant le verbe listens. Le verbe garde son -s car my brother = he.', 2, '{"id": "en.l22.e04", "unitIds": ["en.g17.frequency_adverbs", "en.v.music"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec l''adverbe qui correspond à la traduction entre parenthèses.", "prompt": "My brother ___ listens to music. (parfois)", "promptLanguage": "en", "options": ["sometimes", "always", "never"], "answer": "sometimes", "acceptedAnswers": ["sometimes"], "hint": "Parfois = ni toujours ni jamais.", "explanation": "Sometimes veut dire « parfois ». Il se place avant le verbe listens. Le verbe garde son -s car my brother = he.", "tip": "Sometimes = parfois (pas « sometime »).", "extraExample": {"text": "She sometimes plays music in the evening.", "translation": "Elle joue parfois de la musique le soir."}, "errorPatterns": [{"equals": "always", "category": "vocabulary", "feedback": "Always veut dire « toujours ». Pour « parfois », on dit sometimes."}, {"equals": "never", "category": "vocabulary", "feedback": "Never veut dire « jamais ». Pour « parfois », on dit sometimes."}], "pool": "lesson", "lessonId": "en.l22", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l22.e05', 'en', 'en.l22', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs']::text[], 'fill_blank', 'lesson', 'Anna ___ late for school. (jamais)', array['is never']::text[], 'Avec be, l''adverbe se place après le verbe : Anna is never late. Il faut aussi le verbe is : never seul ne suffit pas.', 2, '{"id": "en.l22.e05", "unitIds": ["en.g17.frequency_adverbs"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne expression (le verbe be et l''adverbe).", "prompt": "Anna ___ late for school. (jamais)", "promptLanguage": "en", "options": ["is never", "never is", "never"], "answer": "is never", "acceptedAnswers": ["is never"], "hint": "Avec be, l''adverbe se place après le verbe.", "explanation": "Avec be, l''adverbe se place après le verbe : Anna is never late. Il faut aussi le verbe is : never seul ne suffit pas.", "tip": "Be d''abord, l''adverbe ensuite : is never, are always.", "extraExample": {"text": "My father is often busy.", "translation": "Mon père est souvent occupé."}, "errorPatterns": [{"equals": "never is", "category": "word_order", "feedback": "Avec be, l''adverbe se place après be : is never."}, {"equals": "never", "category": "grammar", "feedback": "Il manque le verbe be : Anna is never late."}], "pool": "lesson", "lessonId": "en.l22", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l22.e06', 'en', 'en.l22', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.early','en.v.gym']::text[], 'reorder', 'lesson', 'Anna va d''habitude à la salle de sport tôt.', array['Anna usually goes to the gym early','Usually Anna goes to the gym early']::text[], 'L''adverbe usually se place avant le verbe : Anna usually goes. Early, qui veut dire « tôt », se place à la fin de la phrase.', 3, '{"id": "en.l22.e06", "unitIds": ["en.g17.frequency_adverbs", "en.v.early", "en.v.gym"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Anna va d''habitude à la salle de sport tôt.", "promptLanguage": "fr", "tokens": ["early", "Anna", "gym", "usually", "the", "goes", "to"], "answer": "Anna usually goes to the gym early", "acceptedAnswers": ["Anna usually goes to the gym early", "Usually Anna goes to the gym early"], "hint": "Usually se place avant le verbe goes.", "explanation": "L''adverbe usually se place avant le verbe : Anna usually goes. Early, qui veut dire « tôt », se place à la fin de la phrase.", "tip": "Adverbe de fréquence avant le verbe, early à la fin.", "extraExample": {"text": "My father usually goes to work early.", "translation": "Mon père va d''habitude au travail tôt."}, "pool": "lesson", "lessonId": "en.l22", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l22.e07', 'en', 'en.l22', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.day']::text[], 'translation', 'lesson', 'Mon père ne regarde jamais la télé pendant la journée.', array['My father never watches TV during the day.','My dad never watches TV during the day.','My father never watches TV in the day.','My father never watches television during the day.','My father never watches TV in the daytime.','My father never watches TV during the daytime.','My dad never watches television during the day.','My father doesn''t ever watch TV during the day.','During the day my father never watches TV.']::text[], 'Never veut dire « jamais » et se place avant le verbe : my father never watches. Never est déjà négatif : on ne dit pas doesn''t never. Le -s reste sur le verbe (he watches).', 3, '{"id": "en.l22.e07", "unitIds": ["en.g17.frequency_adverbs", "en.v.day"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Mon père ne regarde jamais la télé pendant la journée.", "promptLanguage": "fr", "answer": "My father never watches TV during the day.", "acceptedAnswers": ["My father never watches TV during the day.", "My dad never watches TV during the day.", "My father never watches TV in the day.", "My father never watches television during the day.", "My father never watches TV in the daytime.", "My father never watches TV during the daytime.", "My dad never watches television during the day.", "My father doesn''t ever watch TV during the day.", "During the day my father never watches TV."], "hint": "Never est déjà négatif : pas besoin de doesn''t.", "explanation": "Never veut dire « jamais » et se place avant le verbe : my father never watches. Never est déjà négatif : on ne dit pas doesn''t never. Le -s reste sur le verbe (he watches).", "tip": "Never remplace doesn''t : le verbe garde son -s.", "extraExample": {"text": "My sister never eats meat.", "translation": "Ma sœur ne mange jamais de viande."}, "errorPatterns": [{"contains": "doesn''t never", "category": "grammar", "feedback": "Never est déjà négatif : on ne l''utilise pas avec doesn''t. On dit my father never watches."}, {"contains": "watches never", "category": "word_order", "feedback": "L''adverbe se place avant le verbe : never watches."}, {"contains": "never watch tv", "category": "conjugation", "feedback": "My father = he : le verbe garde son -s après never. On dit never watches."}], "pool": "lesson", "lessonId": "en.l22", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l22.e08', 'en', 'en.l22', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.weekend','en.v.music']::text[], 'translation', 'lesson', 'Nous écoutons souvent de la musique le week-end.', array['We often listen to music at the weekend.','We often listen to music on the weekend.','We often listen to music at weekends.','We often listen to music on weekends.','At the weekend we often listen to music.','On the weekend we often listen to music.','At weekends we often listen to music.','On weekends we often listen to music.']::text[], 'Often se place avant le verbe : we often listen. Après listen, on met to : listen to music. Au week-end se dit at the weekend (anglais britannique) ou on the weekend (américain).', 3, '{"id": "en.l22.e08", "unitIds": ["en.g17.frequency_adverbs", "en.v.weekend", "en.v.music"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Nous écoutons souvent de la musique le week-end.", "promptLanguage": "fr", "answer": "We often listen to music at the weekend.", "acceptedAnswers": ["We often listen to music at the weekend.", "We often listen to music on the weekend.", "We often listen to music at weekends.", "We often listen to music on weekends.", "At the weekend we often listen to music.", "On the weekend we often listen to music.", "At weekends we often listen to music.", "On weekends we often listen to music."], "hint": "Often se place avant le verbe listen. Écouter se dit listen to.", "explanation": "Often se place avant le verbe : we often listen. Après listen, on met to : listen to music. Au week-end se dit at the weekend (anglais britannique) ou on the weekend (américain).", "tip": "Listen to + musique ; often avant le verbe.", "extraExample": {"text": "They often play music at the weekend.", "translation": "Ils jouent souvent de la musique le week-end."}, "errorPatterns": [{"contains": "listen often", "category": "word_order", "feedback": "L''adverbe se place avant le verbe : we often listen."}, {"contains": "listen music", "category": "preposition", "feedback": "Listen se construit avec to : listen to music."}], "pool": "lesson", "lessonId": "en.l22", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l22.e09', 'en', 'en.l22', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs']::text[], 'free_answer', 'lesson', 'Comment dit-on « Nous sommes souvent fatigués le soir » ?', array['We are often tired in the evening.','In the evening we are often tired.','We are often tired in the evenings.','In the evenings we are often tired.']::text[], 'Avec le verbe be (are), l''adverbe se place après : we are often tired. Le soir se dit in the evening.', 3, '{"id": "en.l22.e09", "unitIds": ["en.g17.frequency_adverbs"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Nous sommes souvent fatigués le soir » ?", "promptLanguage": "fr", "answer": "We are often tired in the evening.", "acceptedAnswers": ["We are often tired in the evening.", "In the evening we are often tired.", "We are often tired in the evenings.", "In the evenings we are often tired."], "hint": "Le verbe est be : l''adverbe vient après.", "explanation": "Avec le verbe be (are), l''adverbe se place après : we are often tired. Le soir se dit in the evening.", "tip": "After be : we are often, she is never.", "extraExample": {"text": "They are always tired in the morning.", "translation": "Ils sont toujours fatigués le matin."}, "errorPatterns": [{"contains": "we often are", "category": "word_order", "feedback": "Avec be, l''adverbe se place après be : we are often tired."}, {"contains": "tired often", "category": "word_order", "feedback": "Place l''adverbe juste après be, avant tired : we are often tired."}], "pool": "lesson", "lessonId": "en.l22", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l22.e10', 'en', 'en.l22', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.day','en.v.weekend','en.v.early','en.v.music','en.v.gym']::text[], 'free_answer', 'lesson', 'Que fais-tu souvent, parfois ou jamais ? Écris une phrase.', array['I usually go to the gym in the morning.','I never listen to music at night.','I am often tired in the evening.','My mother rarely goes to the gym.']::text[], 'L''adverbe de fréquence se place avant le verbe (I usually go) mais après be (I am often tired). Never et rarely sont déjà négatifs : pas de don''t avec eux.', 4, '{"id": "en.l22.e10", "unitIds": ["en.g17.frequency_adverbs", "en.v.day", "en.v.weekend", "en.v.early", "en.v.music", "en.v.gym"], "type": "free_answer", "difficulty": 4, "instruction": "Écris une phrase sur tes habitudes avec un adverbe de fréquence : always, usually, often, sometimes, rarely ou never.", "prompt": "Que fais-tu souvent, parfois ou jamais ? Écris une phrase.", "promptLanguage": "fr", "requirements": {"mustInclude": [["always", "usually", "often", "sometimes", "rarely", "never"]], "minWords": 4}, "answer": "I usually go to the gym in the morning.", "acceptedAnswers": ["I usually go to the gym in the morning.", "I never listen to music at night.", "I am often tired in the evening.", "My mother rarely goes to the gym."], "hint": "Avant le verbe, après be.", "explanation": "L''adverbe de fréquence se place avant le verbe (I usually go) mais après be (I am often tired). Never et rarely sont déjà négatifs : pas de don''t avec eux.", "tip": "Relis : avant le verbe, ou après be.", "extraExample": {"text": "I rarely drink milk in the evening.", "translation": "Je bois rarement du lait le soir."}, "errorPatterns": [{"contains": "always am", "category": "word_order", "feedback": "Avec be, l''adverbe se place après be : I am always…"}, {"contains": "don''t never", "category": "grammar", "feedback": "Never est déjà négatif : on dit I never… et non I don''t never…"}, {"contains": "doesn''t never", "category": "grammar", "feedback": "Never est déjà négatif : on dit she never… et non she doesn''t never…"}], "pool": "lesson", "lessonId": "en.l22", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l23.e01', 'en', 'en.l23', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.take_a_shower']::text[], 'mcq', 'lesson', 'Comment dit-on « Elle prend toujours une douche le matin » ?', array['She always takes a shower in the morning.']::text[], 'L''adverbe always se place avant le verbe : she always takes. Le verbe garde son -s à la 3e personne (she takes). Pour une douche, on dit take a shower.', 1, '{"id": "en.l23.e01", "unitIds": ["en.g17.frequency_adverbs", "en.v.take_a_shower"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « Elle prend toujours une douche le matin » ?", "promptLanguage": "fr", "options": ["She always takes a shower in the morning.", "She takes always a shower in the morning.", "She always take a shower in the morning."], "answer": "She always takes a shower in the morning.", "acceptedAnswers": ["She always takes a shower in the morning."], "hint": "Où se place always ? Et que devient take avec she ?", "explanation": "L''adverbe always se place avant le verbe : she always takes. Le verbe garde son -s à la 3e personne (she takes). Pour une douche, on dit take a shower.", "tip": "Adverbe avant le verbe, et n''oublie pas le -s de she.", "extraExample": {"text": "He always has a shower in the evening.", "translation": "Il prend toujours une douche le soir."}, "errorPatterns": [{"equals": "She takes always a shower in the morning.", "category": "word_order", "feedback": "L''adverbe se place avant le verbe : she always takes."}, {"equals": "She always take a shower in the morning.", "category": "conjugation", "feedback": "She demande un -s sur le verbe, même après always : she always takes."}], "pool": "lesson", "lessonId": "en.l23", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l23.e02', 'en', 'en.l23', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.have_breakfast']::text[], 'mcq', 'lesson', 'Anna never ___ breakfast at home.', array['has']::text[], 'Never se place avant le verbe, et le verbe garde sa forme de 3e personne. Avec she, have devient has : Anna never has breakfast.', 2, '{"id": "en.l23.e02", "unitIds": ["en.g17.frequency_adverbs", "en.v.have_breakfast"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme du verbe.", "prompt": "Anna never ___ breakfast at home.", "promptLanguage": "en", "options": ["has", "have", "haves"], "answer": "has", "acceptedAnswers": ["has"], "hint": "Anna = she. Have change de forme.", "explanation": "Never se place avant le verbe, et le verbe garde sa forme de 3e personne. Avec she, have devient has : Anna never has breakfast.", "tip": "Après never aussi : he / she / it → has.", "extraExample": {"text": "My brother often has breakfast at school.", "translation": "Mon frère prend souvent son petit-déjeuner à l''école."}, "errorPatterns": [{"equals": "have", "category": "conjugation", "feedback": "Anna = she : have devient has, même après never."}, {"equals": "haves", "category": "spelling", "feedback": "La forme de have à la 3e personne est has, pas haves."}], "pool": "lesson", "lessonId": "en.l23", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l23.e03', 'en', 'en.l23', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.wake_up','en.v.get_up','en.v.go_to_bed','en.v.take_a_shower','en.v.have_breakfast']::text[], 'match', 'lesson', 'Les expressions de la routine', '{}'::text[], 'En anglais, on n''utilise pas de verbe pronominal : on dit get up (et non « get up myself »). Wake up, c''est ouvrir les yeux ; get up, c''est sortir du lit.', 1, '{"id": "en.l23.e03", "unitIds": ["en.g17.frequency_adverbs", "en.v.wake_up", "en.v.get_up", "en.v.go_to_bed", "en.v.take_a_shower", "en.v.have_breakfast"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression à sa traduction.", "prompt": "Les expressions de la routine", "promptLanguage": "fr", "pairs": [{"left": "wake up", "right": "se réveiller"}, {"left": "get up", "right": "se lever"}, {"left": "go to bed", "right": "aller se coucher"}, {"left": "take a shower", "right": "prendre une douche"}, {"left": "have breakfast", "right": "prendre le petit-déjeuner"}], "answer": "wake up = se réveiller ; get up = se lever ; go to bed = aller se coucher ; take a shower = prendre une douche ; have breakfast = prendre le petit-déjeuner", "acceptedAnswers": [], "explanation": "En anglais, on n''utilise pas de verbe pronominal : on dit get up (et non « get up myself »). Wake up, c''est ouvrir les yeux ; get up, c''est sortir du lit.", "tip": "Wake up = se réveiller, get up = se lever : deux moments différents.", "extraExample": {"text": "I wake up at six and I get up at seven.", "translation": "Je me réveille à six heures et je me lève à sept heures."}, "pool": "lesson", "lessonId": "en.l23", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l23.e04', 'en', 'en.l23', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.wake_up','en.v.get_up']::text[], 'fill_blank', 'lesson', 'I usually ___ up at six, but I get up at seven.', array['wake']::text[], 'Le sens de la phrase est « je me réveille à six heures, mais je me lève à sept heures ». Se réveiller se dit wake up ; se lever se dit get up. Usually se place avant le verbe.', 2, '{"id": "en.l23.e04", "unitIds": ["en.g17.frequency_adverbs", "en.v.wake_up", "en.v.get_up"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon verbe.", "prompt": "I usually ___ up at six, but I get up at seven.", "promptLanguage": "en", "options": ["wake", "get", "go"], "answer": "wake", "acceptedAnswers": ["wake"], "hint": "On se réveille d''abord, on se lève ensuite.", "explanation": "Le sens de la phrase est « je me réveille à six heures, mais je me lève à sept heures ». Se réveiller se dit wake up ; se lever se dit get up. Usually se place avant le verbe.", "tip": "Wake up avant get up : on ouvre les yeux, puis on se lève.", "extraExample": {"text": "She wakes up at six but she gets up at seven.", "translation": "Elle se réveille à six heures mais elle se lève à sept heures."}, "errorPatterns": [{"equals": "get", "category": "word_confusion", "feedback": "Get up veut dire « se lever ». Ici, on se réveille à six heures et on se lève à sept : wake up."}, {"equals": "go", "category": "vocabulary", "feedback": "Go up ne veut pas dire « se réveiller ». Le verbe attendu est wake : wake up."}], "pool": "lesson", "lessonId": "en.l23", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l23.e05', 'en', 'en.l23', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.take_a_shower']::text[], 'fill_blank', 'lesson', 'Tom often ___ a shower before breakfast.', array['takes','has']::text[], 'Pour une douche, on ne « fait » pas : on prend. L''expression est take a shower, qui devient takes avec Tom (= he). Often se place avant le verbe.', 2, '{"id": "en.l23.e05", "unitIds": ["en.g17.frequency_adverbs", "en.v.take_a_shower"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon verbe.", "prompt": "Tom often ___ a shower before breakfast.", "promptLanguage": "en", "options": ["takes", "makes", "does"], "answer": "takes", "acceptedAnswers": ["takes", "has"], "hint": "Une douche, on la « prend » en anglais.", "explanation": "Pour une douche, on ne « fait » pas : on prend. L''expression est take a shower, qui devient takes avec Tom (= he). Often se place avant le verbe.", "tip": "Une douche ne se fait pas : take a shower.", "extraExample": {"text": "We take a shower at the gym.", "translation": "Nous prenons une douche à la salle de sport."}, "errorPatterns": [{"equals": "makes", "category": "word_confusion", "feedback": "En anglais, on ne « fait » pas une douche avec make : on dit take a shower."}, {"equals": "does", "category": "word_confusion", "feedback": "Do ne s''utilise pas pour une douche : on dit take a shower."}], "pool": "lesson", "lessonId": "en.l23", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l23.e06', 'en', 'en.l23', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.go_to_bed']::text[], 'reorder', 'lesson', 'Ma sœur ne se couche jamais tôt.', array['My sister never goes to bed early']::text[], 'Never se place avant le verbe : my sister never goes. Never est déjà négatif : pas de doesn''t. L''expression est go to bed, et early se met à la fin.', 3, '{"id": "en.l23.e06", "unitIds": ["en.g17.frequency_adverbs", "en.v.go_to_bed"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Ma sœur ne se couche jamais tôt.", "promptLanguage": "fr", "tokens": ["early", "My", "bed", "goes", "sister", "never", "to"], "answer": "My sister never goes to bed early", "acceptedAnswers": ["My sister never goes to bed early"], "hint": "Never se place avant le verbe goes.", "explanation": "Never se place avant le verbe : my sister never goes. Never est déjà négatif : pas de doesn''t. L''expression est go to bed, et early se met à la fin.", "tip": "Never remplace doesn''t : le verbe garde son -s.", "extraExample": {"text": "Tom rarely goes to bed late.", "translation": "Tom se couche rarement tard."}, "pool": "lesson", "lessonId": "en.l23", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l23.e07', 'en', 'en.l23', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.get_up']::text[], 'translation', 'lesson', 'Je me lève toujours à sept heures.', array['I always get up at seven.','I always get up at seven o''clock.']::text[], 'Always se place avant le verbe : I always get up. Il n''y a pas de verbe pronominal en anglais : on dit get up, sans « myself ».', 2, '{"id": "en.l23.e07", "unitIds": ["en.g17.frequency_adverbs", "en.v.get_up"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Je me lève toujours à sept heures.", "promptLanguage": "fr", "answer": "I always get up at seven.", "acceptedAnswers": ["I always get up at seven.", "I always get up at seven o''clock."], "hint": "Always se place avant le verbe. Se lever : get up.", "explanation": "Always se place avant le verbe : I always get up. Il n''y a pas de verbe pronominal en anglais : on dit get up, sans « myself ».", "tip": "Je me lève = I get up. Pas de « me » en anglais.", "extraExample": {"text": "She always gets up early.", "translation": "Elle se lève toujours tôt."}, "errorPatterns": [{"contains": "i get up always", "category": "word_order", "feedback": "L''adverbe se place avant le verbe : I always get up."}, {"contains": "always wake up", "category": "word_confusion", "feedback": "Wake up veut dire « se réveiller ». Pour « se lever », on dit get up."}], "pool": "lesson", "lessonId": "en.l23", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l23.e08', 'en', 'en.l23', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.take_a_shower','en.v.have_breakfast']::text[], 'translation', 'lesson', 'Ma mère prend toujours une douche avant le petit-déjeuner.', array['My mother always takes a shower before breakfast.','My mother always has a shower before breakfast.','My mother always showers before breakfast.','My mum always takes a shower before breakfast.','My mum always has a shower before breakfast.','My mum always showers before breakfast.','My mom always takes a shower before breakfast.','My mom always has a shower before breakfast.','My mom always showers before breakfast.']::text[], 'Always se place avant le verbe : my mother always takes. Le verbe prend -s avec my mother (= she). En anglais britannique, on peut aussi dire have a shower.', 3, '{"id": "en.l23.e08", "unitIds": ["en.g17.frequency_adverbs", "en.v.take_a_shower", "en.v.have_breakfast"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Ma mère prend toujours une douche avant le petit-déjeuner.", "promptLanguage": "fr", "answer": "My mother always takes a shower before breakfast.", "acceptedAnswers": ["My mother always takes a shower before breakfast.", "My mother always has a shower before breakfast.", "My mother always showers before breakfast.", "My mum always takes a shower before breakfast.", "My mum always has a shower before breakfast.", "My mum always showers before breakfast.", "My mom always takes a shower before breakfast.", "My mom always has a shower before breakfast.", "My mom always showers before breakfast."], "hint": "Always avant le verbe. Une douche : take (ou have) a shower.", "explanation": "Always se place avant le verbe : my mother always takes. Le verbe prend -s avec my mother (= she). En anglais britannique, on peut aussi dire have a shower.", "tip": "Always + verbe avec -s : she always takes.", "extraExample": {"text": "My brother always has a shower after the gym.", "translation": "Mon frère prend toujours une douche après la salle de sport."}, "errorPatterns": [{"contains": "takes always", "category": "word_order", "feedback": "L''adverbe se place avant le verbe : always takes."}, {"contains": "always take a", "category": "conjugation", "feedback": "My mother = she : le verbe garde son -s après always (takes)."}, {"contains": "makes a shower", "category": "word_confusion", "feedback": "On ne « fait » pas une douche avec make : on dit take a shower."}], "pool": "lesson", "lessonId": "en.l23", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l23.e09', 'en', 'en.l23', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.go_to_bed']::text[], 'free_answer', 'lesson', 'Comment dit-on « Il ne se couche jamais tard » ?', array['He never goes to bed late.']::text[], 'Never veut dire « jamais » : il suffit pour exprimer la négation, sans doesn''t. Il se place avant le verbe, qui garde son -s : he never goes to bed late.', 3, '{"id": "en.l23.e09", "unitIds": ["en.g17.frequency_adverbs", "en.v.go_to_bed"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Il ne se couche jamais tard » ?", "promptLanguage": "fr", "answer": "He never goes to bed late.", "acceptedAnswers": ["He never goes to bed late."], "hint": "Never est déjà négatif.", "explanation": "Never veut dire « jamais » : il suffit pour exprimer la négation, sans doesn''t. Il se place avant le verbe, qui garde son -s : he never goes to bed late.", "tip": "Never + verbe : jamais de doesn''t avec never.", "extraExample": {"text": "She never goes to bed early.", "translation": "Elle ne se couche jamais tôt."}, "errorPatterns": [{"contains": "doesn''t never", "category": "grammar", "feedback": "Never est déjà négatif : on dit he never goes, sans doesn''t."}, {"contains": "goes never", "category": "word_order", "feedback": "L''adverbe se place avant le verbe : he never goes."}, {"equals": "he never go to bed late", "category": "conjugation", "feedback": "He demande un -s sur le verbe : he never goes."}], "pool": "lesson", "lessonId": "en.l23", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l23.e10', 'en', 'en.l23', 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs','en.v.wake_up','en.v.get_up','en.v.go_to_bed','en.v.take_a_shower','en.v.have_breakfast']::text[], 'free_answer', 'lesson', 'Que fais-tu d''habitude le matin ou le soir ?', array['I usually take a shower before breakfast.','I always get up at seven.','I never go to bed early.','I sometimes have breakfast at school.']::text[], 'Pour parler de ta routine, utilise le présent simple et place l''adverbe de fréquence avant le verbe : I usually get up at seven. Avec he ou she, n''oublie pas le -s.', 4, '{"id": "en.l23.e10", "unitIds": ["en.g17.frequency_adverbs", "en.v.wake_up", "en.v.get_up", "en.v.go_to_bed", "en.v.take_a_shower", "en.v.have_breakfast"], "type": "free_answer", "difficulty": 4, "instruction": "Écris une phrase sur ta routine, avec un adverbe de fréquence et une de ces expressions : wake up, get up, go to bed, take a shower ou have breakfast.", "prompt": "Que fais-tu d''habitude le matin ou le soir ?", "promptLanguage": "fr", "requirements": {"mustInclude": [["always", "usually", "often", "sometimes", "rarely", "never"], ["up", "bed", "shower", "breakfast"]], "minWords": 4}, "answer": "I usually take a shower before breakfast.", "acceptedAnswers": ["I usually take a shower before breakfast.", "I always get up at seven.", "I never go to bed early.", "I sometimes have breakfast at school."], "hint": "Adverbe avant le verbe, après be.", "explanation": "Pour parler de ta routine, utilise le présent simple et place l''adverbe de fréquence avant le verbe : I usually get up at seven. Avec he ou she, n''oublie pas le -s.", "tip": "Routine = présent simple + adverbe avant le verbe.", "extraExample": {"text": "I always have breakfast at home.", "translation": "Je prends toujours mon petit-déjeuner à la maison."}, "errorPatterns": [{"contains": "get up always", "category": "word_order", "feedback": "L''adverbe se place avant le verbe : I always get up."}, {"contains": "don''t never", "category": "grammar", "feedback": "Never est déjà négatif : on dit I never…, sans don''t."}], "pool": "lesson", "lessonId": "en.l23", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l24.e01', 'en', 'en.l24', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.rain','en.v.now']::text[], 'mcq', 'lesson', 'It ___ in London now.', array['is raining']::text[], 'Now indique que l''action se passe en ce moment. On utilise le présent continu : am / is / are + verbe en -ing. It is raining veut dire « il pleut (en ce moment) ».', 1, '{"id": "en.l24.e01", "unitIds": ["en.g18.present_continuous", "en.v.rain", "en.v.now"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "It ___ in London now.", "promptLanguage": "en", "options": ["is raining", "rains", "raining"], "answer": "is raining", "acceptedAnswers": ["is raining"], "hint": "Now veut dire « maintenant ».", "explanation": "Now indique que l''action se passe en ce moment. On utilise le présent continu : am / is / are + verbe en -ing. It is raining veut dire « il pleut (en ce moment) ».", "tip": "En ce moment : be + verbe en -ing.", "extraExample": {"text": "My brother is sleeping now.", "translation": "Mon frère dort en ce moment."}, "errorPatterns": [{"equals": "rains", "category": "verb_tense", "feedback": "Rains parle d''un fait général ou d''une habitude. Avec now, on veut dire « en ce moment » : it is raining."}, {"equals": "raining", "category": "grammar", "feedback": "Le verbe en -ing ne s''utilise jamais seul : il faut is devant. On dit it is raining."}], "pool": "lesson", "lessonId": "en.l24", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l24.e02', 'en', 'en.l24', 'en.g18.present_continuous', array['en.g18.present_continuous']::text[], 'mcq', 'lesson', 'Lucy and Ben are ___ now.', array['swimming']::text[], 'Après are, le verbe prend -ing. Swim est un verbe court qui se termine par une voyelle + une consonne : on double la consonne finale avant -ing. On écrit swimming.', 2, '{"id": "en.l24.e02", "unitIds": ["en.g18.present_continuous"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne orthographe.", "prompt": "Lucy and Ben are ___ now.", "promptLanguage": "en", "options": ["swimming", "swiming", "swimeing"], "answer": "swimming", "acceptedAnswers": ["swimming"], "hint": "Swim est un verbe court : une voyelle suivie d''une seule consonne.", "explanation": "Après are, le verbe prend -ing. Swim est un verbe court qui se termine par une voyelle + une consonne : on double la consonne finale avant -ing. On écrit swimming.", "tip": "Verbe court (voyelle + consonne) : on double la consonne (swim → swimming, sit → sitting).", "extraExample": {"text": "The man is sitting in the car.", "translation": "L''homme est assis dans la voiture."}, "errorPatterns": [{"equals": "swiming", "category": "spelling", "feedback": "Swim est un verbe court : on double le m avant -ing. On écrit swimming."}, {"equals": "swimeing", "category": "spelling", "feedback": "Swim ne se termine pas par un -e. On double la consonne m : swimming."}], "pool": "lesson", "lessonId": "en.l24", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l24.e03', 'en', 'en.l24', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.now','en.v.rain','en.v.wear','en.v.talk','en.v.laugh']::text[], 'match', 'lesson', 'Ce qui se passe maintenant', '{}'::text[], 'Le présent continu se forme avec am / is / are + le verbe en -ing. Il décrit ce qui se passe maintenant. Wear s''utilise pour les vêtements.', 1, '{"id": "en.l24.e03", "unitIds": ["en.g18.present_continuous", "en.v.now", "en.v.rain", "en.v.wear", "en.v.talk", "en.v.laugh"], "type": "match", "difficulty": 1, "instruction": "Associe chaque phrase anglaise à sa traduction.", "prompt": "Ce qui se passe maintenant", "promptLanguage": "fr", "pairs": [{"left": "now", "right": "maintenant"}, {"left": "it is raining", "right": "il pleut"}, {"left": "she is wearing", "right": "elle porte"}, {"left": "they are talking", "right": "ils parlent"}, {"left": "he is laughing", "right": "il rit"}], "answer": "now = maintenant ; it is raining = il pleut ; she is wearing = elle porte ; they are talking = ils parlent ; he is laughing = il rit", "acceptedAnswers": [], "explanation": "Le présent continu se forme avec am / is / are + le verbe en -ing. Il décrit ce qui se passe maintenant. Wear s''utilise pour les vêtements.", "tip": "Maintenant = be + -ing : is raining, are talking.", "extraExample": {"text": "I am wearing a hat now.", "translation": "Je porte un chapeau maintenant."}, "pool": "lesson", "lessonId": "en.l24", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l24.e04', 'en', 'en.l24', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.talk']::text[], 'fill_blank', 'lesson', 'My friends are ___ on the phone.', array['talking','speaking']::text[], 'Le présent continu se forme avec be + verbe en -ing. Ici, are est déjà là : le verbe talk prend -ing et devient talking.', 2, '{"id": "en.l24.e04", "unitIds": ["en.g18.present_continuous", "en.v.talk"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme du verbe.", "prompt": "My friends are ___ on the phone.", "promptLanguage": "en", "options": ["talking", "talk", "talks"], "answer": "talking", "acceptedAnswers": ["talking", "speaking"], "hint": "Après are, le verbe prend -ing.", "explanation": "Le présent continu se forme avec be + verbe en -ing. Ici, are est déjà là : le verbe talk prend -ing et devient talking.", "tip": "Are / is / am + verbe-ing.", "extraExample": {"text": "Anna is talking to her mother.", "translation": "Anna parle à sa mère."}, "errorPatterns": [{"equals": "talk", "category": "grammar", "feedback": "Après are, le verbe prend -ing : are talking."}, {"equals": "talks", "category": "grammar", "feedback": "Après are, on n''ajoute pas -s mais -ing : are talking."}], "pool": "lesson", "lessonId": "en.l24", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l24.e05', 'en', 'en.l24', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.laugh']::text[], 'fill_blank', 'lesson', 'Look! The children ___ laughing.', array['are']::text[], 'The children est un sujet pluriel (they), donc on utilise are : the children are laughing. Le choix de am / is / are dépend du sujet.', 2, '{"id": "en.l24.e05", "unitIds": ["en.g18.present_continuous", "en.v.laugh"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec am, is ou are.", "prompt": "Look! The children ___ laughing.", "promptLanguage": "en", "options": ["are", "is", "am"], "answer": "are", "acceptedAnswers": ["are"], "hint": "The children = they.", "explanation": "The children est un sujet pluriel (they), donc on utilise are : the children are laughing. Le choix de am / is / are dépend du sujet.", "tip": "I am, he / she / it is, we / you / they are.", "extraExample": {"text": "My parents are laughing.", "translation": "Mes parents rient."}, "errorPatterns": [{"equals": "is", "category": "grammar", "feedback": "The children est pluriel (= they) : on utilise are, pas is."}, {"equals": "am", "category": "grammar", "feedback": "Am s''utilise seulement avec I. Avec the children, on dit are."}], "pool": "lesson", "lessonId": "en.l24", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l24.e06', 'en', 'en.l24', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.wear','en.v.now']::text[], 'reorder', 'lesson', 'Ma sœur porte un manteau maintenant.', array['My sister is wearing a coat now','Now my sister is wearing a coat']::text[], 'Le présent continu se construit avec sujet + is + verbe en -ing. Now se place souvent à la fin de la phrase (ou au début).', 3, '{"id": "en.l24.e06", "unitIds": ["en.g18.present_continuous", "en.v.wear", "en.v.now"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Ma sœur porte un manteau maintenant.", "promptLanguage": "fr", "tokens": ["wearing", "coat", "My", "now", "a", "is", "sister"], "answer": "My sister is wearing a coat now", "acceptedAnswers": ["My sister is wearing a coat now", "Now my sister is wearing a coat"], "hint": "Sujet + is + verbe en -ing.", "explanation": "Le présent continu se construit avec sujet + is + verbe en -ing. Now se place souvent à la fin de la phrase (ou au début).", "tip": "Sujet, be, verbe-ing, puis le reste.", "extraExample": {"text": "Tom is wearing a hat now.", "translation": "Tom porte un chapeau maintenant."}, "pool": "lesson", "lessonId": "en.l24", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l24.e07', 'en', 'en.l24', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.talk','en.v.now']::text[], 'translation', 'lesson', 'Ma sœur parle au téléphone maintenant.', array['My sister is talking on the phone now.','My sister is talking on the phone right now.','My sister is talking on the phone at the moment.','Now my sister is talking on the phone.','Right now my sister is talking on the phone.','At the moment my sister is talking on the phone.','My sister is speaking on the phone now.','My sister is speaking on the phone right now.','My sister is speaking on the phone at the moment.','Now my sister is speaking on the phone.','Right now my sister is speaking on the phone.','At the moment my sister is speaking on the phone.','My sister is on the phone now.','My sister is on the phone right now.','My sister is on the phone at the moment.']::text[], 'Maintenant indique une action en cours : on utilise le présent continu, is talking. On dit talk on the phone (et non in the phone).', 2, '{"id": "en.l24.e07", "unitIds": ["en.g18.present_continuous", "en.v.talk", "en.v.now"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Ma sœur parle au téléphone maintenant.", "promptLanguage": "fr", "answer": "My sister is talking on the phone now.", "acceptedAnswers": ["My sister is talking on the phone now.", "My sister is talking on the phone right now.", "My sister is talking on the phone at the moment.", "Now my sister is talking on the phone.", "Right now my sister is talking on the phone.", "At the moment my sister is talking on the phone.", "My sister is speaking on the phone now.", "My sister is speaking on the phone right now.", "My sister is speaking on the phone at the moment.", "Now my sister is speaking on the phone.", "Right now my sister is speaking on the phone.", "At the moment my sister is speaking on the phone.", "My sister is on the phone now.", "My sister is on the phone right now.", "My sister is on the phone at the moment."], "hint": "Maintenant → be + verbe en -ing.", "explanation": "Maintenant indique une action en cours : on utilise le présent continu, is talking. On dit talk on the phone (et non in the phone).", "tip": "Au téléphone = on the phone.", "extraExample": {"text": "My father is talking to his friend.", "translation": "Mon père parle à son ami."}, "errorPatterns": [{"contains": "sister talks", "category": "verb_tense", "feedback": "Avec maintenant, on utilise le présent continu : my sister is talking."}, {"contains": "sister talking", "category": "grammar", "feedback": "Il manque is : le verbe en -ing a besoin de be. My sister is talking."}, {"contains": "in the phone", "category": "preposition", "feedback": "Au téléphone se dit on the phone."}], "pool": "lesson", "lessonId": "en.l24", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l24.e08', 'en', 'en.l24', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.rain','en.v.laugh']::text[], 'translation', 'lesson', 'Il pleut et les enfants rient maintenant.', array['It is raining and the children are laughing now.','It is raining and the children are laughing.','It is raining and the kids are laughing now.','It is raining and the kids are laughing.','Now it is raining and the children are laughing.','Now it is raining and the kids are laughing.','It is raining now and the children are laughing.','It is raining now and the kids are laughing.']::text[], 'Les deux actions se passent maintenant : présent continu. Chaque sujet a son be : it is raining, the children are laughing.', 3, '{"id": "en.l24.e08", "unitIds": ["en.g18.present_continuous", "en.v.rain", "en.v.laugh"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Il pleut et les enfants rient maintenant.", "promptLanguage": "fr", "answer": "It is raining and the children are laughing now.", "acceptedAnswers": ["It is raining and the children are laughing now.", "It is raining and the children are laughing.", "It is raining and the kids are laughing now.", "It is raining and the kids are laughing.", "Now it is raining and the children are laughing.", "Now it is raining and the kids are laughing.", "It is raining now and the children are laughing.", "It is raining now and the kids are laughing."], "hint": "Deux sujets, deux fois be : it is… the children are…", "explanation": "Les deux actions se passent maintenant : présent continu. Chaque sujet a son be : it is raining, the children are laughing.", "tip": "Un sujet, un be : it is, the children are.", "extraExample": {"text": "My brother is sleeping and my sister is cooking.", "translation": "Mon frère dort et ma sœur cuisine."}, "errorPatterns": [{"contains": "children laughing", "category": "grammar", "feedback": "Il manque are : the children are laughing."}, {"contains": "it rains", "category": "verb_tense", "feedback": "Pour dire « il pleut maintenant », on utilise le présent continu : it is raining."}, {"contains": "children laugh", "category": "verb_tense", "feedback": "Avec maintenant, on utilise be + -ing : the children are laughing."}], "pool": "lesson", "lessonId": "en.l24", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l24.e09', 'en', 'en.l24', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.now']::text[], 'free_answer', 'lesson', 'Comment dit-on « Je fais du café maintenant » ?', array['I am making coffee now.','I am making some coffee now.','I am making coffee right now.','I am making some coffee right now.','I am making a coffee now.','I am making a coffee right now.','Now I am making coffee.','Right now I am making coffee.']::text[], 'Maintenant → présent continu : I am making coffee. Pour le café, on utilise make (pas do). Make perd son -e avant -ing : making.', 3, '{"id": "en.l24.e09", "unitIds": ["en.g18.present_continuous", "en.v.now"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Je fais du café maintenant » ?", "promptLanguage": "fr", "answer": "I am making coffee now.", "acceptedAnswers": ["I am making coffee now.", "I am making some coffee now.", "I am making coffee right now.", "I am making some coffee right now.", "I am making a coffee now.", "I am making a coffee right now.", "Now I am making coffee.", "Right now I am making coffee."], "hint": "Du café, on le « fait » avec make. Make perd son e devant -ing.", "explanation": "Maintenant → présent continu : I am making coffee. Pour le café, on utilise make (pas do). Make perd son -e avant -ing : making.", "tip": "Verbe en -e : on enlève le e avant -ing (make → making).", "extraExample": {"text": "She is taking a shower now.", "translation": "Elle prend une douche maintenant."}, "errorPatterns": [{"contains": "makeing", "category": "spelling", "feedback": "Make se termine par -e : on l''enlève avant -ing. On écrit making."}, {"contains": "doing coffee", "category": "word_confusion", "feedback": "On ne « fait » pas du café avec do : on dit make coffee."}, {"equals": "i make coffee now", "category": "verb_tense", "feedback": "Avec now, on utilise le présent continu : I am making coffee now."}], "pool": "lesson", "lessonId": "en.l24", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l24.e10', 'en', 'en.l24', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.rain','en.v.wear','en.v.talk','en.v.laugh','en.v.now']::text[], 'free_answer', 'lesson', 'Que se passe-t-il autour de toi en ce moment ?', array['It is raining now.','My brother is talking on the phone.','I am wearing a coat.','The children are laughing.']::text[], 'Pour dire ce qui se passe maintenant, on utilise le présent continu : am / is / are + verbe en -ing (is raining, are talking, am wearing, is laughing).', 4, '{"id": "en.l24.e10", "unitIds": ["en.g18.present_continuous", "en.v.rain", "en.v.wear", "en.v.talk", "en.v.laugh", "en.v.now"], "type": "free_answer", "difficulty": 4, "instruction": "Écris une phrase au présent continu avec un de ces verbes : rain, wear, talk ou laugh.", "prompt": "Que se passe-t-il autour de toi en ce moment ?", "promptLanguage": "fr", "requirements": {"mustInclude": [["raining", "wearing", "talking", "laughing"]], "minWords": 3}, "answer": "It is raining now.", "acceptedAnswers": ["It is raining now.", "My brother is talking on the phone.", "I am wearing a coat.", "The children are laughing."], "hint": "Sujet + am / is / are + verbe en -ing.", "explanation": "Pour dire ce qui se passe maintenant, on utilise le présent continu : am / is / are + verbe en -ing (is raining, are talking, am wearing, is laughing).", "tip": "N''oublie jamais be avant le verbe en -ing.", "extraExample": {"text": "Anna is laughing and Tom is talking.", "translation": "Anna rit et Tom parle."}, "errorPatterns": [{"contains": "it raining", "category": "grammar", "feedback": "Il manque is : it is raining."}, {"contains": "they talking", "category": "grammar", "feedback": "Il manque are : they are talking."}], "pool": "lesson", "lessonId": "en.l24", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l25.e01', 'en', 'en.l25', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.use','en.v.laptop']::text[], 'mcq', 'lesson', 'My brother ___ using his laptop now.', array['isn''t']::text[], 'Au présent continu, on fait la négation avec be + not : he isn''t (is not) using. On n''utilise pas doesn''t, qui sert au présent simple. My brother = he, donc is.', 1, '{"id": "en.l25.e01", "unitIds": ["en.g18.present_continuous", "en.v.use", "en.v.laptop"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "My brother ___ using his laptop now.", "promptLanguage": "en", "options": ["isn''t", "doesn''t", "aren''t"], "answer": "isn''t", "acceptedAnswers": ["isn''t"], "hint": "Le verbe est en -ing : on utilise be.", "explanation": "Au présent continu, on fait la négation avec be + not : he isn''t (is not) using. On n''utilise pas doesn''t, qui sert au présent simple. My brother = he, donc is.", "tip": "Présent continu : isn''t, aren''t, I''m not + -ing. Pas de don''t.", "extraExample": {"text": "My sister isn''t wearing a coat.", "translation": "Ma sœur ne porte pas de manteau."}, "errorPatterns": [{"equals": "doesn''t", "category": "verb_tense", "feedback": "Doesn''t est pour le présent simple (he doesn''t use). Quand le verbe est en -ing, on nie avec be : he isn''t using."}, {"equals": "aren''t", "category": "conjugation", "feedback": "Aren''t s''emploie avec you, we, they. Avec my brother (= he), on dit isn''t."}], "pool": "lesson", "lessonId": "en.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l25.e02', 'en', 'en.l25', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.sing']::text[], 'mcq', 'lesson', 'Comment dit-on « Est-ce qu''elle chante en ce moment ? »', array['Is she singing now?']::text[], 'Pour poser une question au présent continu, on place be avant le sujet : Is she singing ? Le verbe reste en -ing. On n''utilise pas do / does.', 2, '{"id": "en.l25.e02", "unitIds": ["en.g18.present_continuous", "en.v.sing"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la question correcte.", "prompt": "Comment dit-on « Est-ce qu''elle chante en ce moment ? »", "promptLanguage": "fr", "options": ["Is she singing now?", "Are she singing now?", "Does she singing now?", "Is she sing now?"], "answer": "Is she singing now?", "acceptedAnswers": ["Is she singing now?"], "hint": "On place be avant le sujet.", "explanation": "Pour poser une question au présent continu, on place be avant le sujet : Is she singing ? Le verbe reste en -ing. On n''utilise pas do / does.", "tip": "Question : be + sujet + verbe-ing (Is she…? Are you…?).", "extraExample": {"text": "Is he talking on the phone?", "translation": "Est-ce qu''il parle au téléphone ?"}, "errorPatterns": [{"equals": "Are she singing now?", "category": "conjugation", "feedback": "She va avec is : Is she singing ? Are est pour you, we, they."}, {"equals": "Does she singing now?", "category": "verb_tense", "feedback": "Does est pour le présent simple. Avec un verbe en -ing, on utilise be : Is she singing ?"}, {"equals": "Is she sing now?", "category": "grammar", "feedback": "Après is, le verbe prend -ing : Is she singing ?"}], "pool": "lesson", "lessonId": "en.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l25.e03', 'en', 'en.l25', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.call','en.v.use','en.v.sing','en.v.dance','en.v.laptop']::text[], 'match', 'lesson', 'Les nouveaux mots de la leçon', '{}'::text[], 'Use et dance se terminent par un -e : on l''enlève avant -ing (using, dancing). Call et sing prennent simplement -ing (calling, singing).', 1, '{"id": "en.l25.e03", "unitIds": ["en.g18.present_continuous", "en.v.call", "en.v.use", "en.v.sing", "en.v.dance", "en.v.laptop"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot anglais à sa traduction.", "prompt": "Les nouveaux mots de la leçon", "promptLanguage": "fr", "pairs": [{"left": "call", "right": "appeler"}, {"left": "use", "right": "utiliser"}, {"left": "sing", "right": "chanter"}, {"left": "dance", "right": "danser"}, {"left": "laptop", "right": "un ordinateur portable"}], "answer": "call = appeler ; use = utiliser ; sing = chanter ; dance = danser ; laptop = un ordinateur portable", "acceptedAnswers": [], "explanation": "Use et dance se terminent par un -e : on l''enlève avant -ing (using, dancing). Call et sing prennent simplement -ing (calling, singing).", "tip": "Verbe en -e : on enlève le e (use → using, dance → dancing).", "extraExample": {"text": "Are you using your laptop?", "translation": "Est-ce que tu utilises ton ordinateur portable ?"}, "pool": "lesson", "lessonId": "en.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l25.e04', 'en', 'en.l25', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.use']::text[], 'fill_blank', 'lesson', 'My sister is ___ her laptop now.', array['using']::text[], 'Après is, le verbe prend -ing. Use se termine par un -e : on l''enlève avant d''ajouter -ing. On écrit using.', 2, '{"id": "en.l25.e04", "unitIds": ["en.g18.present_continuous", "en.v.use"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme du verbe use.", "prompt": "My sister is ___ her laptop now.", "promptLanguage": "en", "options": ["using", "useing", "uses"], "answer": "using", "acceptedAnswers": ["using"], "hint": "Use se termine par -e.", "explanation": "Après is, le verbe prend -ing. Use se termine par un -e : on l''enlève avant d''ajouter -ing. On écrit using.", "tip": "On enlève le e final avant -ing : use → using, make → making.", "extraExample": {"text": "He is dancing in the house.", "translation": "Il danse dans la maison."}, "errorPatterns": [{"equals": "useing", "category": "spelling", "feedback": "Use se termine par -e : on l''enlève avant -ing. On écrit using."}, {"equals": "uses", "category": "grammar", "feedback": "Après is, le verbe prend -ing, pas -s : is using."}], "pool": "lesson", "lessonId": "en.l25", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l25.e05', 'en', 'en.l25', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.dance']::text[], 'fill_blank', 'lesson', 'Is Anna dancing? No, she ___.', array['isn''t']::text[], 'Pour répondre à une question avec Is, on reprend is : No, she isn''t. On ne répète pas le verbe dancing.', 2, '{"id": "en.l25.e05", "unitIds": ["en.g18.present_continuous", "en.v.dance"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la réponse courte.", "prompt": "Is Anna dancing? No, she ___.", "promptLanguage": "en", "options": ["isn''t", "doesn''t", "aren''t"], "answer": "isn''t", "acceptedAnswers": ["isn''t"], "hint": "On reprend le verbe be de la question.", "explanation": "Pour répondre à une question avec Is, on reprend is : No, she isn''t. On ne répète pas le verbe dancing.", "tip": "Question en Is / Are → réponse en is / isn''t, are / aren''t.", "extraExample": {"text": "Is Tom calling his mother? Yes, he is.", "translation": "Est-ce que Tom appelle sa mère ? Oui."}, "errorPatterns": [{"equals": "doesn''t", "category": "verb_tense", "feedback": "La question commence par Is : on répond avec is / isn''t, pas avec does."}, {"equals": "aren''t", "category": "conjugation", "feedback": "Aren''t est pour you, we, they. Avec she, on dit isn''t."}], "pool": "lesson", "lessonId": "en.l25", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l25.e06', 'en', 'en.l25', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.call']::text[], 'reorder', 'lesson', 'Est-ce que tu appelles ta mère maintenant ?', array['Are you calling your mother now']::text[], 'Pour une question au présent continu, on place be avant le sujet : Are you… ? Puis le verbe en -ing (calling), puis le reste de la phrase.', 2, '{"id": "en.l25.e06", "unitIds": ["en.g18.present_continuous", "en.v.call"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Est-ce que tu appelles ta mère maintenant ?", "promptLanguage": "fr", "tokens": ["calling", "Are", "you", "now", "mother", "your"], "answer": "Are you calling your mother now", "acceptedAnswers": ["Are you calling your mother now"], "hint": "La question commence par Are.", "explanation": "Pour une question au présent continu, on place be avant le sujet : Are you… ? Puis le verbe en -ing (calling), puis le reste de la phrase.", "tip": "You are devient Are you : on inverse be et le sujet.", "extraExample": {"text": "Is your brother using his laptop?", "translation": "Est-ce que ton frère utilise son ordinateur portable ?"}, "pool": "lesson", "lessonId": "en.l25", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l25.e07', 'en', 'en.l25', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.use','en.v.laptop']::text[], 'translation', 'lesson', 'Tom n''utilise pas son ordinateur portable en ce moment.', array['Tom isn''t using his laptop at the moment.','Tom isn''t using his laptop now.','Tom isn''t using his laptop right now.','At the moment Tom isn''t using his laptop.','Right now Tom isn''t using his laptop.','Now Tom isn''t using his laptop.']::text[], 'En ce moment : présent continu. La négation se fait avec be + not (is not = isn''t), puis le verbe en -ing : Tom isn''t using. Use perd son -e : using.', 2, '{"id": "en.l25.e07", "unitIds": ["en.g18.present_continuous", "en.v.use", "en.v.laptop"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Tom n''utilise pas son ordinateur portable en ce moment.", "promptLanguage": "fr", "answer": "Tom isn''t using his laptop at the moment.", "acceptedAnswers": ["Tom isn''t using his laptop at the moment.", "Tom isn''t using his laptop now.", "Tom isn''t using his laptop right now.", "At the moment Tom isn''t using his laptop.", "Right now Tom isn''t using his laptop.", "Now Tom isn''t using his laptop."], "hint": "Pour nier un verbe en -ing, on utilise be + not.", "explanation": "En ce moment : présent continu. La négation se fait avec be + not (is not = isn''t), puis le verbe en -ing : Tom isn''t using. Use perd son -e : using.", "tip": "Be + not + verbe-ing : isn''t using, aren''t talking.", "extraExample": {"text": "We aren''t talking now.", "translation": "Nous ne parlons pas maintenant."}, "errorPatterns": [{"contains": "tom doesn''t use", "category": "verb_tense", "feedback": "Pour une action en cours, la négation se fait avec isn''t + -ing : Tom isn''t using."}, {"contains": "tom not using", "category": "grammar", "feedback": "Il manque is : Tom is not (isn''t) using."}, {"contains": "isn''t use his", "category": "grammar", "feedback": "Après isn''t, le verbe prend -ing : isn''t using."}], "pool": "lesson", "lessonId": "en.l25", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l25.e08', 'en', 'en.l25', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.sing','en.v.dance']::text[], 'translation', 'lesson', 'Est-ce que ta sœur danse et chante maintenant ?', array['Is your sister dancing and singing now?','Is your sister singing and dancing now?','Is your sister dancing and singing right now?','Is your sister singing and dancing right now?','Is your sister dancing and singing at the moment?','Is your sister singing and dancing at the moment?','Is your sister dancing and singing?','Is your sister singing and dancing?']::text[], 'Pour une question au présent continu : Is + sujet + verbe en -ing. Dance se termine par -e, qu''on enlève : dancing. Sing prend simplement -ing : singing.', 3, '{"id": "en.l25.e08", "unitIds": ["en.g18.present_continuous", "en.v.sing", "en.v.dance"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Est-ce que ta sœur danse et chante maintenant ?", "promptLanguage": "fr", "answer": "Is your sister dancing and singing now?", "acceptedAnswers": ["Is your sister dancing and singing now?", "Is your sister singing and dancing now?", "Is your sister dancing and singing right now?", "Is your sister singing and dancing right now?", "Is your sister dancing and singing at the moment?", "Is your sister singing and dancing at the moment?", "Is your sister dancing and singing?", "Is your sister singing and dancing?"], "hint": "Is + sujet + verbe en -ing. Dance perd son -e.", "explanation": "Pour une question au présent continu : Is + sujet + verbe en -ing. Dance se termine par -e, qu''on enlève : dancing. Sing prend simplement -ing : singing.", "tip": "Question : Is your sister + verbe-ing ?", "extraExample": {"text": "Are your parents singing?", "translation": "Est-ce que tes parents chantent ?"}, "errorPatterns": [{"contains": "does your sister", "category": "verb_tense", "feedback": "Pour une action en cours, on pose la question avec be : Is your sister…"}, {"contains": "danceing", "category": "spelling", "feedback": "Dance se termine par -e : on l''enlève avant -ing. On écrit dancing."}, {"contains": "are your sister", "category": "conjugation", "feedback": "Your sister = she : on utilise Is, pas Are."}], "pool": "lesson", "lessonId": "en.l25", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l25.e09', 'en', 'en.l25', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.dance']::text[], 'free_answer', 'lesson', 'Are your friends dancing now?', array['Yes, they are.']::text[], 'La question commence par Are : on répond avec are. À la fin d''une réponse courte positive, on ne contracte pas : Yes, they are (et non Yes, they''re).', 3, '{"id": "en.l25.e09", "unitIds": ["en.g18.present_continuous", "en.v.dance"], "type": "free_answer", "difficulty": 3, "instruction": "Réponds « oui » avec une réponse courte (Yes, …).", "prompt": "Are your friends dancing now?", "promptLanguage": "en", "answer": "Yes, they are.", "acceptedAnswers": ["Yes, they are."], "hint": "On reprend le verbe be de la question.", "explanation": "La question commence par Are : on répond avec are. À la fin d''une réponse courte positive, on ne contracte pas : Yes, they are (et non Yes, they''re).", "tip": "Question en Are → Yes, they are. / No, they aren''t.", "extraExample": {"text": "Is Tom laughing? No, he isn''t.", "translation": "Est-ce que Tom rit ? Non."}, "errorPatterns": [{"equals": "yes they do", "category": "verb_tense", "feedback": "La question commence par Are : on répond avec are, pas avec do. Yes, they are."}, {"equals": "yes they dancing", "category": "grammar", "feedback": "Dans une réponse courte, on reprend seulement are : Yes, they are."}, {"equals": "yes they dance", "category": "instruction", "feedback": "La consigne demande une réponse courte : on reprend are. Yes, they are."}], "pool": "lesson", "lessonId": "en.l25", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l25.e10', 'en', 'en.l25', 'en.g18.present_continuous', array['en.g18.present_continuous','en.v.call','en.v.use','en.v.sing','en.v.dance','en.v.laptop']::text[], 'free_answer', 'lesson', 'Que demandes-tu à un ami qui est avec toi en ce moment ?', array['Are you using your laptop now?','Is Anna singing now?','Is your brother calling his friend?','Are they dancing?']::text[], 'Pour poser une question au présent continu, on place be (am, is, are) avant le sujet, puis le verbe en -ing : Are you using…? Is she singing…?', 4, '{"id": "en.l25.e10", "unitIds": ["en.g18.present_continuous", "en.v.call", "en.v.use", "en.v.sing", "en.v.dance", "en.v.laptop"], "type": "free_answer", "difficulty": 4, "instruction": "Pose une question au présent continu avec un de ces verbes : call, use, sing ou dance.", "prompt": "Que demandes-tu à un ami qui est avec toi en ce moment ?", "promptLanguage": "fr", "requirements": {"mustInclude": [["calling", "using", "singing", "dancing"], ["am", "is", "are"]], "minWords": 3}, "answer": "Are you using your laptop now?", "acceptedAnswers": ["Are you using your laptop now?", "Is Anna singing now?", "Is your brother calling his friend?", "Are they dancing?"], "hint": "Be + sujet + verbe en -ing ?", "explanation": "Pour poser une question au présent continu, on place be (am, is, are) avant le sujet, puis le verbe en -ing : Are you using…? Is she singing…?", "tip": "Question : on inverse be et le sujet, le verbe reste en -ing.", "extraExample": {"text": "Is it raining in Paris now?", "translation": "Est-ce qu''il pleut à Paris maintenant ?"}, "errorPatterns": [{"contains": "do you using", "category": "verb_tense", "feedback": "On ne mélange pas do et -ing : avec un verbe en -ing, la question commence par be. Are you using…?"}, {"contains": "is they", "category": "conjugation", "feedback": "Avec they, on utilise are : Are they…?"}], "pool": "lesson", "lessonId": "en.l25", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l26.e01', 'en', 'en.l26', 'en.g19.simple_vs_continuous', array['en.g19.simple_vs_continuous','en.v.colleague']::text[], 'mcq', 'lesson', 'My colleague ___ coffee every morning.', array['drinks']::text[], 'Every morning indique une habitude : on utilise le présent simple. My colleague = he, donc le verbe prend -s : drinks.', 1, '{"id": "en.l26.e01", "unitIds": ["en.g19.simple_vs_continuous", "en.v.colleague"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "My colleague ___ coffee every morning.", "promptLanguage": "en", "options": ["drinks", "is drinking", "drink"], "answer": "drinks", "acceptedAnswers": ["drinks"], "hint": "Every morning indique une habitude.", "explanation": "Every morning indique une habitude : on utilise le présent simple. My colleague = he, donc le verbe prend -s : drinks.", "tip": "Tous les jours, souvent, toujours : présent simple.", "extraExample": {"text": "My sister plays music every evening.", "translation": "Ma sœur joue de la musique tous les soirs."}, "errorPatterns": [{"equals": "is drinking", "category": "verb_tense", "feedback": "Every morning indique une habitude, pas une action en cours : on utilise le présent simple, drinks."}, {"equals": "drink", "category": "conjugation", "feedback": "My colleague = he : le verbe prend -s au présent simple. On dit drinks."}], "pool": "lesson", "lessonId": "en.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l26.e02', 'en', 'en.l26', 'en.g19.simple_vs_continuous', array['en.g19.simple_vs_continuous','en.v.at_the_moment','en.v.colleague']::text[], 'mcq', 'lesson', 'At the moment, my colleague ___ on the phone.', array['is talking']::text[], 'At the moment veut dire « en ce moment » : l''action est en cours. On utilise le présent continu, be + verbe en -ing : is talking.', 2, '{"id": "en.l26.e02", "unitIds": ["en.g19.simple_vs_continuous", "en.v.at_the_moment", "en.v.colleague"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme.", "prompt": "At the moment, my colleague ___ on the phone.", "promptLanguage": "en", "options": ["is talking", "talks", "talk"], "answer": "is talking", "acceptedAnswers": ["is talking"], "hint": "At the moment veut dire « en ce moment ».", "explanation": "At the moment veut dire « en ce moment » : l''action est en cours. On utilise le présent continu, be + verbe en -ing : is talking.", "tip": "At the moment, now : be + -ing.", "extraExample": {"text": "At the moment, my brother is sleeping.", "translation": "En ce moment, mon frère dort."}, "errorPatterns": [{"equals": "talks", "category": "verb_tense", "feedback": "Talks décrit une habitude. Avec at the moment, l''action est en cours : is talking."}, {"equals": "talk", "category": "verb_tense", "feedback": "Avec at the moment, on utilise le présent continu : my colleague is talking."}], "pool": "lesson", "lessonId": "en.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l26.e03', 'en', 'en.l26', 'en.g19.simple_vs_continuous', array['en.g19.simple_vs_continuous','en.v.today','en.v.tonight','en.v.at_the_moment','en.v.office','en.v.colleague']::text[], 'match', 'lesson', 'Les mots du temps et du travail', '{}'::text[], 'Today, tonight et at the moment vont souvent avec le présent continu : ils parlent de ce qui se passe maintenant ou d''un projet précis. Colleague s''emploie pour un collègue comme pour une collègue.', 1, '{"id": "en.l26.e03", "unitIds": ["en.g19.simple_vs_continuous", "en.v.today", "en.v.tonight", "en.v.at_the_moment", "en.v.office", "en.v.colleague"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot anglais à sa traduction.", "prompt": "Les mots du temps et du travail", "promptLanguage": "fr", "pairs": [{"left": "today", "right": "aujourd''hui"}, {"left": "tonight", "right": "ce soir"}, {"left": "at the moment", "right": "en ce moment"}, {"left": "office", "right": "le bureau"}, {"left": "colleague", "right": "un collègue / une collègue"}], "answer": "today = aujourd''hui ; tonight = ce soir ; at the moment = en ce moment ; office = le bureau ; colleague = un collègue / une collègue", "acceptedAnswers": [], "explanation": "Today, tonight et at the moment vont souvent avec le présent continu : ils parlent de ce qui se passe maintenant ou d''un projet précis. Colleague s''emploie pour un collègue comme pour une collègue.", "tip": "Today, tonight, at the moment : pense au présent continu.", "extraExample": {"text": "I''m working at the office today.", "translation": "Je travaille au bureau aujourd''hui."}, "pool": "lesson", "lessonId": "en.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l26.e04', 'en', 'en.l26', 'en.g19.simple_vs_continuous', array['en.g19.simple_vs_continuous','en.v.office']::text[], 'fill_blank', 'lesson', 'I ___ my office.', array['like']::text[], 'Like est un verbe d''état : il exprime un goût ou un sentiment, pas une action. Les verbes d''état (like, love, know, want, need) ne s''utilisent presque jamais au présent continu.', 2, '{"id": "en.l26.e04", "unitIds": ["en.g19.simple_vs_continuous", "en.v.office"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le verbe like, à la forme qui convient.", "prompt": "I ___ my office.", "promptLanguage": "en", "options": ["like", "am liking", "likes"], "answer": "like", "acceptedAnswers": ["like"], "hint": "Like exprime un goût, pas une action.", "explanation": "Like est un verbe d''état : il exprime un goût ou un sentiment, pas une action. Les verbes d''état (like, love, know, want, need) ne s''utilisent presque jamais au présent continu.", "tip": "J''aime, je sais, je veux : toujours au présent simple.", "extraExample": {"text": "I love my school.", "translation": "J''adore mon école."}, "errorPatterns": [{"equals": "am liking", "category": "verb_tense", "feedback": "Like est un verbe d''état : on ne dit pas I''m liking. On dit simplement I like."}, {"equals": "likes", "category": "conjugation", "feedback": "Avec I, le verbe ne prend pas de -s : I like."}], "pool": "lesson", "lessonId": "en.l26", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l26.e05', 'en', 'en.l26', 'en.g19.simple_vs_continuous', array['en.g19.simple_vs_continuous','en.v.at_the_moment','en.v.office']::text[], 'fill_blank', 'lesson', 'Anna usually works at the office, but at the moment she ___ at home.', array['is working']::text[], 'La phrase oppose une habitude (usually works) et ce qui se passe en ce moment. At the moment demande le présent continu : she is working at home.', 3, '{"id": "en.l26.e05", "unitIds": ["en.g19.simple_vs_continuous", "en.v.at_the_moment", "en.v.office"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la bonne forme du verbe work.", "prompt": "Anna usually works at the office, but at the moment she ___ at home.", "promptLanguage": "en", "options": ["is working", "works", "working"], "answer": "is working", "acceptedAnswers": ["is working"], "hint": "Usually = habitude. At the moment = maintenant.", "explanation": "La phrase oppose une habitude (usually works) et ce qui se passe en ce moment. At the moment demande le présent continu : she is working at home.", "tip": "Habitude = présent simple. Maintenant = présent continu.", "extraExample": {"text": "Anna usually cooks dinner, but tonight her brother is cooking.", "translation": "D''habitude, Anna prépare le dîner, mais ce soir son frère cuisine."}, "errorPatterns": [{"equals": "works", "category": "verb_tense", "feedback": "At the moment parle de maintenant : on utilise le présent continu, she is working."}, {"equals": "working", "category": "grammar", "feedback": "Il manque is : le verbe en -ing a besoin de be. She is working."}], "pool": "lesson", "lessonId": "en.l26", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l26.e06', 'en', 'en.l26', 'en.g19.simple_vs_continuous', array['en.g19.simple_vs_continuous','en.v.office','en.v.colleague']::text[], 'reorder', 'lesson', 'Mon collègue travaille au bureau tous les jours.', array['My colleague works at the office every day','Every day my colleague works at the office']::text[], 'Every day indique une habitude : présent simple. My colleague = he, donc works avec un -s. Every day se place à la fin de la phrase (ou au début).', 3, '{"id": "en.l26.e06", "unitIds": ["en.g19.simple_vs_continuous", "en.v.office", "en.v.colleague"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Mon collègue travaille au bureau tous les jours.", "promptLanguage": "fr", "tokens": ["office", "colleague", "every", "My", "works", "the", "at", "day"], "answer": "My colleague works at the office every day", "acceptedAnswers": ["My colleague works at the office every day", "Every day my colleague works at the office"], "hint": "Tous les jours = habitude : présent simple.", "explanation": "Every day indique une habitude : présent simple. My colleague = he, donc works avec un -s. Every day se place à la fin de la phrase (ou au début).", "tip": "Every day → présent simple, pas de -ing.", "extraExample": {"text": "My sister goes to the gym every day.", "translation": "Ma sœur va à la salle de sport tous les jours."}, "pool": "lesson", "lessonId": "en.l26", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l26.e07', 'en', 'en.l26', 'en.g19.simple_vs_continuous', array['en.g19.simple_vs_continuous','en.v.colleague']::text[], 'translation', 'lesson', 'Est-ce que tu connais mon collègue ?', array['Do you know my colleague?','Do you know my coworker?','Do you know my co-worker?']::text[], 'Know est un verbe d''état : il ne s''utilise presque jamais au présent continu. On pose donc la question au présent simple avec Do you… ?', 2, '{"id": "en.l26.e07", "unitIds": ["en.g19.simple_vs_continuous", "en.v.colleague"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Est-ce que tu connais mon collègue ?", "promptLanguage": "fr", "answer": "Do you know my colleague?", "acceptedAnswers": ["Do you know my colleague?", "Do you know my coworker?", "Do you know my co-worker?"], "hint": "Know est un verbe d''état.", "explanation": "Know est un verbe d''état : il ne s''utilise presque jamais au présent continu. On pose donc la question au présent simple avec Do you… ?", "tip": "Je sais, je connais, je veux : pas de -ing.", "extraExample": {"text": "I know her name.", "translation": "Je connais son nom."}, "errorPatterns": [{"contains": "are you knowing", "category": "verb_tense", "feedback": "Know est un verbe d''état : on ne l''utilise pas au présent continu. Do you know… ?"}, {"contains": "do you knows", "category": "conjugation", "feedback": "Après Do, le verbe reste à sa forme de base : Do you know."}], "pool": "lesson", "lessonId": "en.l26", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
