insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l26.e09', 'en', 'en.l26', 'en.g19.simple_vs_continuous', array['en.g19.simple_vs_continuous','en.v.tonight']::text[], 'free_answer', 'lesson', 'Comment dit-on « Qu''est-ce que tu fais ce soir ? »', array['What are you doing tonight?','Tonight, what are you doing?','What are you going to do tonight?']::text[], 'Pour demander ce que quelqu''un a prévu de faire ce soir, on utilise le présent continu : What are you doing tonight ? Tonight veut dire « ce soir ».', 3, '{"id": "en.l26.e09", "unitIds": ["en.g19.simple_vs_continuous", "en.v.tonight"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la question en anglais.", "prompt": "Comment dit-on « Qu''est-ce que tu fais ce soir ? »", "promptLanguage": "fr", "answer": "What are you doing tonight?", "acceptedAnswers": ["What are you doing tonight?", "Tonight, what are you doing?", "What are you going to do tonight?"], "hint": "Pour un projet de ce soir, on utilise be + -ing.", "explanation": "Pour demander ce que quelqu''un a prévu de faire ce soir, on utilise le présent continu : What are you doing tonight ? Tonight veut dire « ce soir ».", "tip": "Projet de ce soir : What are you doing tonight ?", "extraExample": {"text": "I''m cooking dinner for my friends tonight.", "translation": "Je prépare le dîner pour mes amis ce soir."}, "errorPatterns": [{"equals": "what do you do tonight", "category": "verb_tense", "feedback": "Pour un projet de ce soir, on utilise le présent continu : What are you doing tonight ?"}, {"contains": "what you doing", "category": "grammar", "feedback": "Il manque are : What are you doing tonight ?"}, {"contains": "you do tonight", "category": "grammar", "feedback": "Avec are, le verbe prend -ing : What are you doing tonight ?"}], "pool": "lesson", "lessonId": "en.l26", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l26.e10', 'en', 'en.l26', 'en.g19.simple_vs_continuous', array['en.g19.simple_vs_continuous','en.v.today','en.v.tonight','en.v.at_the_moment','en.v.office','en.v.colleague']::text[], 'free_answer', 'lesson', 'Que se passe-t-il pour toi ou pour un collègue aujourd''hui, ce soir ou en ce moment ?', array['I am working at the office at the moment.','Tonight I am cooking dinner for my friends.','Today I am using my laptop at home.','My colleague is talking on the phone at the moment.']::text[], 'Avec at the moment, today ou tonight, on utilise le présent continu : I am working, she is cooking. Pour une habitude, on utiliserait le présent simple avec every day ou usually.', 4, '{"id": "en.l26.e10", "unitIds": ["en.g19.simple_vs_continuous", "en.v.today", "en.v.tonight", "en.v.at_the_moment", "en.v.office", "en.v.colleague"], "type": "free_answer", "difficulty": 4, "instruction": "Écris une phrase sur ce que tu fais ou ce que quelqu''un fait. Utilise at the moment, today ou tonight.", "prompt": "Que se passe-t-il pour toi ou pour un collègue aujourd''hui, ce soir ou en ce moment ?", "promptLanguage": "fr", "requirements": {"mustInclude": [["moment", "today", "tonight"]], "minWords": 4}, "answer": "I am working at the office at the moment.", "acceptedAnswers": ["I am working at the office at the moment.", "Tonight I am cooking dinner for my friends.", "Today I am using my laptop at home.", "My colleague is talking on the phone at the moment."], "hint": "Today, tonight, at the moment : be + verbe en -ing.", "explanation": "Avec at the moment, today ou tonight, on utilise le présent continu : I am working, she is cooking. Pour une habitude, on utiliserait le présent simple avec every day ou usually.", "tip": "Les verbes comme like, know, want restent au présent simple, même avec now.", "extraExample": {"text": "At the moment, I am using my laptop at the office.", "translation": "En ce moment, j''utilise mon ordinateur portable au bureau."}, "errorPatterns": [{"contains": "am liking", "category": "verb_tense", "feedback": "Like est un verbe d''état : on ne dit pas I''m liking. On dit I like."}, {"contains": "am knowing", "category": "verb_tense", "feedback": "Know est un verbe d''état : on ne dit pas I''m knowing. On dit I know."}, {"contains": "am wanting", "category": "verb_tense", "feedback": "Want est un verbe d''état : on ne dit pas I''m wanting. On dit I want."}], "pool": "lesson", "lessonId": "en.l26", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l27.e01', 'en', 'en.l27', 'en.g20.was_were', array['en.g20.was_were','en.v.yesterday']::text[], 'mcq', 'lesson', 'Yesterday, I ___ tired.', array['was']::text[], 'Yesterday (hier) place la phrase dans le passé : on n''utilise plus am, mais was. Avec I, he, she et it, le passé de to be est was.', 1, '{"id": "en.l27.e01", "unitIds": ["en.g20.was_were", "en.v.yesterday"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Yesterday, I ___ tired.", "promptLanguage": "en", "options": ["was", "were", "am"], "answer": "was", "acceptedAnswers": ["was"], "hint": "Yesterday veut dire « hier » : la phrase parle du passé.", "explanation": "Yesterday (hier) place la phrase dans le passé : on n''utilise plus am, mais was. Avec I, he, she et it, le passé de to be est was.", "tip": "Hier = passé : am et is deviennent was, are devient were.", "extraExample": {"text": "She was busy yesterday.", "translation": "Elle était occupée hier."}, "errorPatterns": [{"equals": "were", "category": "conjugation", "feedback": "Were s''utilise avec you, we et they. Avec I, le passé de to be est was : I was."}, {"equals": "am", "category": "verb_tense", "feedback": "Am est le présent. Yesterday parle du passé : on dit I was."}], "pool": "lesson", "lessonId": "en.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l27.e02', 'en', 'en.l27', 'en.g20.was_were', array['en.g20.was_were','en.v.last','en.v.week']::text[], 'mcq', 'lesson', 'Anna and Tom ___ in London last week.', array['were']::text[], 'Anna and Tom correspond à they (eux). Avec they, we et you, le passé de to be est were. Last week (la semaine dernière) confirme que c''est le passé.', 1, '{"id": "en.l27.e02", "unitIds": ["en.g20.was_were", "en.v.last", "en.v.week"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Anna and Tom ___ in London last week.", "promptLanguage": "en", "options": ["were", "was", "are"], "answer": "were", "acceptedAnswers": ["were"], "hint": "Anna and Tom, c''est « eux » : they.", "explanation": "Anna and Tom correspond à they (eux). Avec they, we et you, le passé de to be est were. Last week (la semaine dernière) confirme que c''est le passé.", "tip": "Plusieurs personnes (we, you, they) → were.", "extraExample": {"text": "My parents were at the office last week.", "translation": "Mes parents étaient au bureau la semaine dernière."}, "errorPatterns": [{"equals": "was", "category": "conjugation", "feedback": "Was s''utilise avec I, he, she et it. Anna and Tom = they : on dit were."}, {"equals": "are", "category": "verb_tense", "feedback": "Are est le présent. Last week parle du passé : on dit were."}], "pool": "lesson", "lessonId": "en.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l27.e03', 'en', 'en.l27', 'en.g20.was_were', array['en.g20.was_were','en.v.yesterday','en.v.last','en.v.ago','en.v.week','en.v.born']::text[], 'match', 'lesson', 'Les repères de temps du passé', '{}'::text[], 'Ces repères placent l''action dans le passé. Last se place avant le nom (last week), alors que ago se place après la durée (two days ago). Pour la naissance, l''anglais dit I was born : on utilise was.', 1, '{"id": "en.l27.e03", "unitIds": ["en.g20.was_were", "en.v.yesterday", "en.v.last", "en.v.ago", "en.v.week", "en.v.born"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les repères de temps du passé", "promptLanguage": "fr", "pairs": [{"left": "yesterday", "right": "hier"}, {"left": "last week", "right": "la semaine dernière"}, {"left": "two days ago", "right": "il y a deux jours"}, {"left": "last night", "right": "hier soir"}, {"left": "I was born in Paris", "right": "je suis né à Paris"}], "answer": "yesterday = hier ; last week = la semaine dernière ; two days ago = il y a deux jours ; last night = hier soir ; I was born in Paris = je suis né à Paris", "acceptedAnswers": [], "explanation": "Ces repères placent l''action dans le passé. Last se place avant le nom (last week), alors que ago se place après la durée (two days ago). Pour la naissance, l''anglais dit I was born : on utilise was.", "tip": "Last avant le nom, ago après la durée.", "extraExample": {"text": "three weeks ago", "translation": "il y a trois semaines"}, "pool": "lesson", "lessonId": "en.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l27.e04', 'en', 'en.l27', 'en.g20.was_were', array['en.g20.was_were','en.v.ago']::text[], 'fill_blank', 'lesson', 'My brother was at the office two days ___.', array['ago']::text[], 'Pour dire « il y a » devant une durée, l''anglais place ago après la durée : two days ago. On ne dit pas « before two days ».', 2, '{"id": "en.l27.e04", "unitIds": ["en.g20.was_were", "en.v.ago"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "My brother was at the office two days ___.", "promptLanguage": "en", "options": ["ago", "before", "last"], "answer": "ago", "acceptedAnswers": ["ago"], "hint": "« Il y a deux jours » : le mot se place après la durée.", "explanation": "Pour dire « il y a » devant une durée, l''anglais place ago après la durée : two days ago. On ne dit pas « before two days ».", "tip": "« Il y a deux jours » = two days ago : la durée d''abord, ago ensuite.", "extraExample": {"text": "Anna was in Paris three days ago.", "translation": "Anna était à Paris il y a trois jours."}, "errorPatterns": [{"equals": "before", "category": "word_confusion", "feedback": "Before ne veut pas dire « il y a ». On écrit la durée puis ago : two days ago."}, {"equals": "last", "category": "word_confusion", "feedback": "Last se place devant un nom (last week). Après une durée, « il y a » se dit ago."}], "pool": "lesson", "lessonId": "en.l27", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l27.e05', 'en', 'en.l27', 'en.g20.was_were', array['en.g20.was_were']::text[], 'fill_blank', 'lesson', 'Anna ___ at school yesterday. She was at home.', array['wasn''t']::text[], 'Anna correspond à she, donc on utilise was. Pour dire « n''était pas », on ajoute not : was not, qu''on contracte en wasn''t.', 2, '{"id": "en.l27.e05", "unitIds": ["en.g20.was_were"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la forme négative.", "prompt": "Anna ___ at school yesterday. She was at home.", "promptLanguage": "en", "options": ["wasn''t", "weren''t", "isn''t"], "answer": "wasn''t", "acceptedAnswers": ["wasn''t"], "hint": "Elle était à la maison : elle n''était pas à l''école.", "explanation": "Anna correspond à she, donc on utilise was. Pour dire « n''était pas », on ajoute not : was not, qu''on contracte en wasn''t.", "tip": "was + not = wasn''t ; were + not = weren''t.", "extraExample": {"text": "Tom wasn''t hungry at lunch.", "translation": "Tom n''avait pas faim au déjeuner."}, "errorPatterns": [{"equals": "weren''t", "category": "conjugation", "feedback": "Weren''t s''utilise avec you, we et they. Anna = she : on dit wasn''t."}, {"equals": "isn''t", "category": "verb_tense", "feedback": "Isn''t est le présent. Yesterday parle du passé : wasn''t."}], "pool": "lesson", "lessonId": "en.l27", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l27.e06', 'en', 'en.l27', 'en.g20.was_were', array['en.g20.was_were','en.v.yesterday']::text[], 'reorder', 'lesson', 'Tu étais à la maison hier ?', array['Were you at home yesterday']::text[], 'Pour poser une question avec to be, on place was ou were avant le sujet : Were you…? Il n''y a pas besoin de do. Avec you, on utilise were.', 2, '{"id": "en.l27.e06", "unitIds": ["en.g20.was_were", "en.v.yesterday"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour poser la question.", "prompt": "Tu étais à la maison hier ?", "promptLanguage": "fr", "tokens": ["you", "yesterday", "Were", "home", "at"], "answer": "Were you at home yesterday", "acceptedAnswers": ["Were you at home yesterday"], "hint": "Une question commence par was ou were.", "explanation": "Pour poser une question avec to be, on place was ou were avant le sujet : Were you…? Il n''y a pas besoin de do. Avec you, on utilise were.", "tip": "Question : Was ou Were passe devant le sujet.", "extraExample": {"text": "Was she tired last night?", "translation": "Était-elle fatiguée hier soir ?"}, "pool": "lesson", "lessonId": "en.l27", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l27.e07', 'en', 'en.l27', 'en.g20.was_were', array['en.g20.was_were','en.v.yesterday']::text[], 'translation', 'lesson', 'Elle était fatiguée hier.', array['She was tired yesterday','Yesterday she was tired']::text[], 'Le passé de is est was. Avec she, on dit was : She was tired. Yesterday peut se placer à la fin ou au début de la phrase.', 2, '{"id": "en.l27.e07", "unitIds": ["en.g20.was_were", "en.v.yesterday"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Elle était fatiguée hier.", "promptLanguage": "fr", "answer": "She was tired yesterday", "acceptedAnswers": ["She was tired yesterday", "Yesterday she was tired"], "hint": "Elle = she. Quel est le passé de is ?", "explanation": "Le passé de is est was. Avec she, on dit was : She was tired. Yesterday peut se placer à la fin ou au début de la phrase.", "tip": "She, he, it, I → was.", "extraExample": {"text": "He was late yesterday.", "translation": "Il était en retard hier."}, "errorPatterns": [{"contains": "she were", "category": "conjugation", "feedback": "Were ne s''utilise qu''avec you, we et they. Avec she, on dit was."}, {"contains": "she is tired", "category": "verb_tense", "feedback": "Is est le présent. Pour « était », on utilise was."}, {"contains": "she has tired", "category": "grammar", "feedback": "Pour dire « elle était fatiguée », on utilise to be : she was tired, pas have."}], "pool": "lesson", "lessonId": "en.l27", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l27.e08', 'en', 'en.l27', 'en.g20.was_were', array['en.g20.was_were','en.v.last','en.v.week']::text[], 'translation', 'lesson', 'Nous n''étions pas à la maison la semaine dernière.', array['We weren''t at home last week','We weren''t home last week','Last week we weren''t at home','Last week we weren''t home']::text[], 'Avec we, le passé de to be est were. Pour la négation, on ajoute not : weren''t. Last week se place avant ou après le reste de la phrase.', 3, '{"id": "en.l27.e08", "unitIds": ["en.g20.was_were", "en.v.last", "en.v.week"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Nous n''étions pas à la maison la semaine dernière.", "promptLanguage": "fr", "answer": "We weren''t at home last week", "acceptedAnswers": ["We weren''t at home last week", "We weren''t home last week", "Last week we weren''t at home", "Last week we weren''t home"], "hint": "Nous = we. Le passé négatif de are est weren''t.", "explanation": "Avec we, le passé de to be est were. Pour la négation, on ajoute not : weren''t. Last week se place avant ou après le reste de la phrase.", "tip": "Nous / vous / ils + négation au passé : weren''t.", "extraExample": {"text": "They weren''t at school yesterday.", "translation": "Ils n''étaient pas à l''école hier."}, "errorPatterns": [{"contains": "we wasn''t", "category": "conjugation", "feedback": "Wasn''t s''utilise avec I, he, she et it. Avec we, on dit weren''t."}, {"contains": "we aren''t", "category": "verb_tense", "feedback": "Aren''t est le présent. La phrase parle de la semaine dernière : weren''t."}], "pool": "lesson", "lessonId": "en.l27", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l27.e09', 'en', 'en.l27', 'en.g20.was_were', array['en.g20.was_were','en.v.yesterday']::text[], 'free_answer', 'lesson', 'Comment dit-on « Où étais-tu hier ? » en anglais ?', array['Where were you yesterday']::text[], 'On place le mot interrogatif where en premier, puis were (le passé de are avec you), puis le sujet : Where were you yesterday ? Avec you, c''est toujours were.', 3, '{"id": "en.l27.e09", "unitIds": ["en.g20.was_were", "en.v.yesterday"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la question en anglais.", "prompt": "Comment dit-on « Où étais-tu hier ? » en anglais ?", "promptLanguage": "fr", "answer": "Where were you yesterday", "acceptedAnswers": ["Where were you yesterday"], "hint": "Le mot interrogatif vient en premier, puis were, puis you.", "explanation": "On place le mot interrogatif where en premier, puis were (le passé de are avec you), puis le sujet : Where were you yesterday ? Avec you, c''est toujours were.", "tip": "Question avec where : Where + was / were + sujet.", "extraExample": {"text": "Where was Tom last night?", "translation": "Où était Tom hier soir ?"}, "errorPatterns": [{"contains": "where was you", "category": "conjugation", "feedback": "Avec you, le passé est toujours were : Where were you ?"}, {"contains": "where are you", "category": "verb_tense", "feedback": "Are est le présent. Pour « hier », on utilise were."}, {"equals": "where you were yesterday", "category": "word_order", "feedback": "Dans une question, were se place avant le sujet : Where were you yesterday ?"}], "pool": "lesson", "lessonId": "en.l27", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l27.e10', 'en', 'en.l27', 'en.g20.was_were', array['en.g20.was_were','en.v.born']::text[], 'free_answer', 'lesson', 'Comment dit-on « Je suis né à Paris » en anglais ?', array['I was born in Paris']::text[], '« Être né » se dit to be born, et la naissance appartient au passé : I was born. On utilise la préposition in devant une ville : in Paris.', 3, '{"id": "en.l27.e10", "unitIds": ["en.g20.was_were", "en.v.born"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Je suis né à Paris » en anglais ?", "promptLanguage": "fr", "answer": "I was born in Paris", "acceptedAnswers": ["I was born in Paris"], "hint": "En anglais, la naissance se dit au passé avec to be.", "explanation": "« Être né » se dit to be born, et la naissance appartient au passé : I was born. On utilise la préposition in devant une ville : in Paris.", "tip": "Je suis né(e) = I was born : jamais I am born.", "extraExample": {"text": "My father was born in London.", "translation": "Mon père est né à Londres."}, "errorPatterns": [{"contains": "i am born", "category": "verb_tense", "feedback": "La naissance est passée : on dit I was born, pas I am born."}, {"equals": "i born in paris", "category": "grammar", "feedback": "Il manque was : I was born in Paris."}, {"contains": "born at", "category": "preposition", "feedback": "Devant une ville, on utilise in : born in Paris."}], "pool": "lesson", "lessonId": "en.l27", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l28.e01', 'en', 'en.l28', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.walk']::text[], 'mcq', 'lesson', 'My sister ___ to school yesterday.', array['walked']::text[], 'Yesterday (hier) indique une action terminée : on utilise le passé simple. Pour un verbe régulier, on ajoute -ed à la forme de base : walk → walked, avec toutes les personnes.', 1, '{"id": "en.l28.e01", "unitIds": ["en.g21.past_simple_regular", "en.v.walk"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "My sister ___ to school yesterday.", "promptLanguage": "en", "options": ["walked", "walk", "was walk"], "answer": "walked", "acceptedAnswers": ["walked"], "hint": "Yesterday : l''action est terminée.", "explanation": "Yesterday (hier) indique une action terminée : on utilise le passé simple. Pour un verbe régulier, on ajoute -ed à la forme de base : walk → walked, avec toutes les personnes.", "tip": "Yesterday, last… ou ago → verbe + -ed, sans was et sans -s.", "extraExample": {"text": "Tom walked to the gym yesterday morning.", "translation": "Tom est allé à pied à la salle de sport hier matin."}, "errorPatterns": [{"equals": "walk", "category": "verb_tense", "feedback": "Walk est la forme de base, utilisée au présent. Avec yesterday, il faut -ed : walked."}, {"equals": "was walk", "category": "grammar", "feedback": "On n''ajoute pas was devant un verbe d''action : walked exprime déjà le passé."}], "pool": "lesson", "lessonId": "en.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l28.e02', 'en', 'en.l28', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.visit']::text[], 'mcq', 'lesson', 'Anna ___ her parents last week.', array['visited']::text[], 'Last week (la semaine dernière) place l''action dans le passé. Le verbe régulier visit prend -ed : visited. Il n''y a pas de -s avec she, car le -s est réservé au présent.', 1, '{"id": "en.l28.e02", "unitIds": ["en.g21.past_simple_regular", "en.v.visit"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Anna ___ her parents last week.", "promptLanguage": "en", "options": ["visited", "visit", "visits"], "answer": "visited", "acceptedAnswers": ["visited"], "hint": "Last week : c''est le passé.", "explanation": "Last week (la semaine dernière) place l''action dans le passé. Le verbe régulier visit prend -ed : visited. Il n''y a pas de -s avec she, car le -s est réservé au présent.", "tip": "Au passé, plus de -s avec he / she / it : on ajoute seulement -ed.", "extraExample": {"text": "Lucy visited her brother last weekend.", "translation": "Lucy a rendu visite à son frère le week-end dernier."}, "errorPatterns": [{"equals": "visits", "category": "verb_tense", "feedback": "Visits est le présent (avec -s). La phrase parle de la semaine dernière : visited."}, {"equals": "visit", "category": "verb_tense", "feedback": "Visit est la forme de base du présent. Pour le passé, on ajoute -ed : visited."}], "pool": "lesson", "lessonId": "en.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l28.e03', 'en', 'en.l28', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.walk','en.v.visit','en.v.stay','en.v.start','en.v.travel']::text[], 'match', 'lesson', 'Cinq verbes réguliers au passé', '{}'::text[], 'Ces cinq verbes sont réguliers : on ajoute -ed. Le -ed ne se prononce pas toujours pareil : walked /wɔːkt/ (le d sonne comme un t), stayed /steɪd/ et visited /ˈvɪzɪtɪd/ (avec une syllabe en plus).', 1, '{"id": "en.l28.e03", "unitIds": ["en.g21.past_simple_regular", "en.v.walk", "en.v.visit", "en.v.stay", "en.v.start", "en.v.travel"], "type": "match", "difficulty": 1, "instruction": "Associe chaque verbe au passé à sa traduction.", "prompt": "Cinq verbes réguliers au passé", "promptLanguage": "fr", "pairs": [{"left": "walked", "right": "a marché"}, {"left": "visited", "right": "a visité / a rendu visite"}, {"left": "stayed", "right": "est resté / a séjourné"}, {"left": "started", "right": "a commencé"}, {"left": "travelled", "right": "a voyagé"}], "answer": "walked = a marché ; visited = a visité / a rendu visite ; stayed = est resté / a séjourné ; started = a commencé ; travelled = a voyagé", "acceptedAnswers": [], "explanation": "Ces cinq verbes sont réguliers : on ajoute -ed. Le -ed ne se prononce pas toujours pareil : walked /wɔːkt/ (le d sonne comme un t), stayed /steɪd/ et visited /ˈvɪzɪtɪd/ (avec une syllabe en plus).", "tip": "En anglais, le passé simple se traduit souvent par le passé composé français : walked = a marché.", "extraExample": {"text": "They stayed in Paris.", "translation": "Ils sont restés à Paris."}, "pool": "lesson", "lessonId": "en.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l28.e04', 'en', 'en.l28', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.stay']::text[], 'fill_blank', 'lesson', 'We ___ at my sister''s house for two days. (stay)', array['stayed']::text[], 'Stay est un verbe régulier : on ajoute -ed, ce qui donne stayed. Le y reste un y, car il est précédé d''une voyelle (a) : on ne le change en i qu''après une consonne (study → studied).', 2, '{"id": "en.l28.e04", "unitIds": ["en.g21.past_simple_regular", "en.v.stay"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le passé du verbe entre parenthèses.", "prompt": "We ___ at my sister''s house for two days. (stay)", "promptLanguage": "en", "options": ["stayed", "stay", "stays"], "answer": "stayed", "acceptedAnswers": ["stayed"], "hint": "Le verbe est régulier : ajoute -ed.", "explanation": "Stay est un verbe régulier : on ajoute -ed, ce qui donne stayed. Le y reste un y, car il est précédé d''une voyelle (a) : on ne le change en i qu''après une consonne (study → studied).", "tip": "Voyelle + y : on garde le y (stayed). Consonne + y : y devient i (studied).", "extraExample": {"text": "He stayed at home last night.", "translation": "Il est resté à la maison hier soir."}, "errorPatterns": [{"equals": "stay", "category": "verb_tense", "feedback": "Stay est la forme du présent. L''action est terminée : il faut -ed, stayed."}, {"equals": "staied", "category": "spelling", "feedback": "Après une voyelle, le y ne change pas : stay → stayed (et non staied)."}, {"equals": "stayd", "category": "spelling", "feedback": "Le passé régulier s''écrit avec -ed, pas seulement -d : stayed."}], "pool": "lesson", "lessonId": "en.l28", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l28.e05', 'en', 'en.l28', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.start']::text[], 'fill_blank', 'lesson', 'Tom ___ work early yesterday. (start)', array['started']::text[], 'Start est régulier : on ajoute -ed. Comme start se termine par un t, on entend une syllabe de plus : started se dit /ˈstɑːtɪd/. Avec yesterday, c''est le passé simple.', 2, '{"id": "en.l28.e05", "unitIds": ["en.g21.past_simple_regular", "en.v.start"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le passé du verbe entre parenthèses.", "prompt": "Tom ___ work early yesterday. (start)", "promptLanguage": "en", "options": ["started", "start", "starts"], "answer": "started", "acceptedAnswers": ["started"], "hint": "Yesterday : l''action est terminée.", "explanation": "Start est régulier : on ajoute -ed. Comme start se termine par un t, on entend une syllabe de plus : started se dit /ˈstɑːtɪd/. Avec yesterday, c''est le passé simple.", "tip": "Même forme à toutes les personnes : I started, he started, they started.", "extraExample": {"text": "The film started late.", "translation": "Le film a commencé tard."}, "errorPatterns": [{"equals": "start", "category": "verb_tense", "feedback": "Start est la forme du présent. Avec yesterday, on ajoute -ed : started."}, {"equals": "starts", "category": "verb_tense", "feedback": "Le -s est réservé au présent. Au passé, tous les sujets prennent -ed : started."}], "pool": "lesson", "lessonId": "en.l28", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l28.e06', 'en', 'en.l28', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.visit']::text[], 'reorder', 'lesson', 'Anna a rendu visite à sa sœur la semaine dernière.', array['Anna visited her sister last week','Last week Anna visited her sister']::text[], 'L''ordre de base est sujet + verbe + complément : Anna visited her sister. Le repère de temps last week se place à la fin, ou au début de la phrase.', 2, '{"id": "en.l28.e06", "unitIds": ["en.g21.past_simple_regular", "en.v.visit"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Anna a rendu visite à sa sœur la semaine dernière.", "promptLanguage": "fr", "tokens": ["her", "Anna", "week", "sister", "visited", "last"], "answer": "Anna visited her sister last week", "acceptedAnswers": ["Anna visited her sister last week", "Last week Anna visited her sister"], "hint": "Sujet + verbe au passé + complément. Last se place devant week.", "explanation": "L''ordre de base est sujet + verbe + complément : Anna visited her sister. Le repère de temps last week se place à la fin, ou au début de la phrase.", "tip": "Last se place devant le nom : last week, pas week last.", "extraExample": {"text": "My friend visited me last week.", "translation": "Mon ami m''a rendu visite la semaine dernière."}, "pool": "lesson", "lessonId": "en.l28", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l28.e07', 'en', 'en.l28', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.walk','en.v.yesterday']::text[], 'translation', 'lesson', 'Hier, j''ai marché jusqu''au bureau.', array['I walked to the office yesterday','Yesterday I walked to the office','I walked to my office yesterday','Yesterday I walked to my office','I walked to work yesterday','Yesterday I walked to work']::text[], '« J''ai marché » se traduit par I walked : walk + -ed. On n''utilise pas have comme en français. Yesterday peut se placer au début ou à la fin.', 2, '{"id": "en.l28.e07", "unitIds": ["en.g21.past_simple_regular", "en.v.walk", "en.v.yesterday"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Hier, j''ai marché jusqu''au bureau.", "promptLanguage": "fr", "answer": "I walked to the office yesterday", "acceptedAnswers": ["I walked to the office yesterday", "Yesterday I walked to the office", "I walked to my office yesterday", "Yesterday I walked to my office", "I walked to work yesterday", "Yesterday I walked to work"], "hint": "Le passé composé français se traduit par le passé simple anglais.", "explanation": "« J''ai marché » se traduit par I walked : walk + -ed. On n''utilise pas have comme en français. Yesterday peut se placer au début ou à la fin.", "tip": "Pas d''auxiliaire : « j''ai marché » = I walked.", "extraExample": {"text": "She walked home after work.", "translation": "Elle est rentrée à pied après le travail."}, "errorPatterns": [{"contains": "i walk to", "category": "verb_tense", "feedback": "Walk est le présent. Hier, l''action est terminée : I walked."}, {"contains": "i have walked", "category": "verb_tense", "feedback": "L''anglais n''utilise pas have ici. Pour une action finie dans le passé, on dit simplement I walked."}, {"contains": "was walked", "category": "grammar", "feedback": "Pas de was devant un verbe d''action : I walked."}], "pool": "lesson", "lessonId": "en.l28", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l28.e08', 'en', 'en.l28', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.travel','en.v.ago']::text[], 'translation', 'lesson', 'Mes parents ont voyagé à Londres il y a deux jours.', array['My parents travelled to London two days ago','My parents traveled to London two days ago','Two days ago my parents travelled to London','Two days ago my parents traveled to London']::text[], 'Travel est régulier : travel → travelled. En anglais britannique, on double le l ; en américain, on écrit traveled. « Il y a deux jours » se dit two days ago.', 3, '{"id": "en.l28.e08", "unitIds": ["en.g21.past_simple_regular", "en.v.travel", "en.v.ago"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Mes parents ont voyagé à Londres il y a deux jours.", "promptLanguage": "fr", "answer": "My parents travelled to London two days ago", "acceptedAnswers": ["My parents travelled to London two days ago", "My parents traveled to London two days ago", "Two days ago my parents travelled to London", "Two days ago my parents traveled to London"], "hint": "« Il y a deux jours » : la durée d''abord, puis ago.", "explanation": "Travel est régulier : travel → travelled. En anglais britannique, on double le l ; en américain, on écrit traveled. « Il y a deux jours » se dit two days ago.", "tip": "Travel double son l en anglais britannique : travelled (traveled en américain).", "extraExample": {"text": "We travelled to Paris three days ago.", "translation": "Nous avons voyagé jusqu''à Paris il y a trois jours."}, "errorPatterns": [{"contains": "parents travel to", "category": "verb_tense", "feedback": "Travel est le présent. L''action est passée : il faut -ed, travelled."}, {"contains": "before two days", "category": "word_confusion", "feedback": "« Il y a » se dit ago, placé après la durée : two days ago."}, {"contains": "two days before", "category": "word_confusion", "feedback": "Before ne veut pas dire « il y a ». On dit two days ago."}], "pool": "lesson", "lessonId": "en.l28", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l28.e09', 'en', 'en.l28', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.stay','en.v.yesterday']::text[], 'free_answer', 'lesson', 'Comment dit-on « Nous sommes restés à la maison hier » en anglais ?', array['We stayed at home yesterday','We stayed home yesterday','Yesterday we stayed at home','Yesterday we stayed home']::text[], '« Sommes restés » est un passé composé français : en anglais, on utilise le passé simple, stayed. Le verbe a la même forme avec we, I, he ou they.', 3, '{"id": "en.l28.e09", "unitIds": ["en.g21.past_simple_regular", "en.v.stay", "en.v.yesterday"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Nous sommes restés à la maison hier » en anglais ?", "promptLanguage": "fr", "answer": "We stayed at home yesterday", "acceptedAnswers": ["We stayed at home yesterday", "We stayed home yesterday", "Yesterday we stayed at home", "Yesterday we stayed home"], "hint": "Stay est un verbe régulier : stay + -ed.", "explanation": "« Sommes restés » est un passé composé français : en anglais, on utilise le passé simple, stayed. Le verbe a la même forme avec we, I, he ou they.", "tip": "« Nous sommes restés » = We stayed : pas de verbe être devant.", "extraExample": {"text": "I stayed in bed all morning.", "translation": "Je suis resté au lit toute la matinée."}, "errorPatterns": [{"contains": "we stay at", "category": "verb_tense", "feedback": "Stay est le présent. Hier, l''action est finie : stayed."}, {"contains": "we were stayed", "category": "grammar", "feedback": "Pas de were devant un verbe d''action : We stayed."}, {"contains": "we are stayed", "category": "grammar", "feedback": "Le passé simple se fait sans verbe être : We stayed."}], "pool": "lesson", "lessonId": "en.l28", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l28.e10', 'en', 'en.l28', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.start']::text[], 'free_answer', 'lesson', 'Comment dit-on « Hier, ma journée a commencé tôt » en anglais ?', array['My day started early yesterday','Yesterday my day started early','My day began early yesterday','Yesterday my day began early']::text[], 'Avec yesterday, on utilise le passé simple : start → started. Le sujet my day se comporte comme it : le verbe ne change pas, et il n''y a pas de -s.', 3, '{"id": "en.l28.e10", "unitIds": ["en.g21.past_simple_regular", "en.v.start"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Hier, ma journée a commencé tôt » en anglais ?", "promptLanguage": "fr", "answer": "My day started early yesterday", "acceptedAnswers": ["My day started early yesterday", "Yesterday my day started early", "My day began early yesterday", "Yesterday my day began early"], "hint": "Le verbe est start. Early veut dire « tôt ».", "explanation": "Avec yesterday, on utilise le passé simple : start → started. Le sujet my day se comporte comme it : le verbe ne change pas, et il n''y a pas de -s.", "tip": "Au passé, le verbe ne change jamais selon le sujet : my day started, we started.", "extraExample": {"text": "School started at eight.", "translation": "Les cours ont commencé à huit heures."}, "errorPatterns": [{"contains": "day start early", "category": "verb_tense", "feedback": "Start est le présent. Hier, l''action est finie : started."}, {"contains": "day was start", "category": "grammar", "feedback": "On n''ajoute pas was devant un verbe d''action : My day started."}], "pool": "lesson", "lessonId": "en.l28", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l29.e01', 'en', 'en.l29', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.arrive']::text[], 'mcq', 'lesson', 'Anna ___ home late yesterday.', array['arrived']::text[], 'Arrive se termine déjà par un e : on ajoute seulement -d, ce qui donne arrived (/əˈraɪvd/). Avec yesterday, l''action est terminée, donc on utilise le passé simple.', 1, '{"id": "en.l29.e01", "unitIds": ["en.g21.past_simple_regular", "en.v.arrive"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Anna ___ home late yesterday.", "promptLanguage": "en", "options": ["arrived", "arriveed", "arrive"], "answer": "arrived", "acceptedAnswers": ["arrived"], "hint": "Arrive se termine déjà par la lettre e.", "explanation": "Arrive se termine déjà par un e : on ajoute seulement -d, ce qui donne arrived (/əˈraɪvd/). Avec yesterday, l''action est terminée, donc on utilise le passé simple.", "tip": "Verbe qui finit par -e : on ajoute seulement -d (love → loved).", "extraExample": {"text": "Tom loved the music.", "translation": "Tom a adoré la musique."}, "errorPatterns": [{"equals": "arriveed", "category": "spelling", "feedback": "Arrive finit déjà par un e : on ajoute seulement -d, pas -ed. On écrit arrived."}, {"equals": "arrive", "category": "verb_tense", "feedback": "Arrive est la forme de base. Yesterday parle d''une action finie : arrived."}], "pool": "lesson", "lessonId": "en.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l29.e02', 'en', 'en.l29', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.decide']::text[], 'mcq', 'lesson', 'Comment se prononce la fin de decided ?', array['comme « id », avec une syllabe en plus']::text[], 'Quand le verbe se termine par le son t ou d (decide, start, wait…), on ajoute une syllabe : -ed se dit /ɪd/. On entend decided /dɪˈsaɪdɪd/, car deux d de suite seraient impossibles à prononcer.', 2, '{"id": "en.l29.e02", "unitIds": ["en.g21.past_simple_regular", "en.v.decide"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne prononciation.", "prompt": "Comment se prononce la fin de decided ?", "promptLanguage": "fr", "options": ["comme un t", "comme un d", "comme « id », avec une syllabe en plus"], "answer": "comme « id », avec une syllabe en plus", "acceptedAnswers": ["comme « id », avec une syllabe en plus"], "hint": "Decide se termine déjà par le son d.", "explanation": "Quand le verbe se termine par le son t ou d (decide, start, wait…), on ajoute une syllabe : -ed se dit /ɪd/. On entend decided /dɪˈsaɪdɪd/, car deux d de suite seraient impossibles à prononcer.", "tip": "Verbe en t ou d : syllabe en plus, /ɪd/. Sinon, une seule syllabe : /t/ ou /d/.", "extraExample": {"text": "We waited at the door.", "translation": "Nous avons attendu à la porte."}, "errorPatterns": [{"equals": "comme un t", "category": "spelling", "feedback": "Le son /t/ s''entend après p, k, s, f, ch ou sh (asked, walked). Après un d, on ajoute la syllabe /ɪd/."}, {"equals": "comme un d", "category": "spelling", "feedback": "Le son /d/ s''entend après la plupart des autres sons (cleaned). Après un d ou un t, on ajoute la syllabe /ɪd/."}], "pool": "lesson", "lessonId": "en.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l29.e03', 'en', 'en.l29', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.arrive','en.v.decide','en.v.ask','en.v.answer','en.v.clean']::text[], 'match', 'lesson', 'Cinq verbes réguliers au passé et leur prononciation', '{}'::text[], 'Ces verbes sont réguliers, mais le -ed se prononce de trois façons : /t/ dans asked /ɑːskt/, /d/ dans arrived /əˈraɪvd/, cleaned /kliːnd/ et answered /ˈɑːnsəd/, et /ɪd/ dans decided /dɪˈsaɪdɪd/. Le w de answer ne se prononce pas.', 1, '{"id": "en.l29.e03", "unitIds": ["en.g21.past_simple_regular", "en.v.arrive", "en.v.decide", "en.v.ask", "en.v.answer", "en.v.clean"], "type": "match", "difficulty": 1, "instruction": "Associe chaque verbe au passé à sa traduction.", "prompt": "Cinq verbes réguliers au passé et leur prononciation", "promptLanguage": "fr", "pairs": [{"left": "arrived", "right": "est arrivé"}, {"left": "decided", "right": "a décidé"}, {"left": "asked", "right": "a demandé"}, {"left": "answered", "right": "a répondu"}, {"left": "cleaned", "right": "a nettoyé"}], "answer": "arrived = est arrivé ; decided = a décidé ; asked = a demandé ; answered = a répondu ; cleaned = a nettoyé", "acceptedAnswers": [], "explanation": "Ces verbes sont réguliers, mais le -ed se prononce de trois façons : /t/ dans asked /ɑːskt/, /d/ dans arrived /əˈraɪvd/, cleaned /kliːnd/ et answered /ˈɑːnsəd/, et /ɪd/ dans decided /dɪˈsaɪdɪd/. Le w de answer ne se prononce pas.", "tip": "-ed : /t/ après p, k, s, f, ch, sh ; /ɪd/ après t ou d ; /d/ dans les autres cas.", "extraExample": {"text": "Sam asked me for a coffee.", "translation": "Sam m''a demandé un café."}, "pool": "lesson", "lessonId": "en.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l29.e04', 'en', 'en.l29', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.clean']::text[], 'fill_blank', 'lesson', 'Last weekend, Sam ___ the windows. (clean)', array['cleaned']::text[], 'Last weekend place l''action dans le passé : clean + -ed = cleaned, qui se prononce /kliːnd/ (le -ed sonne comme un d). On ne double pas le n, car clean contient deux voyelles (ea).', 2, '{"id": "en.l29.e04", "unitIds": ["en.g21.past_simple_regular", "en.v.clean"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le passé du verbe entre parenthèses.", "prompt": "Last weekend, Sam ___ the windows. (clean)", "promptLanguage": "en", "options": ["cleaned", "clean", "cleans"], "answer": "cleaned", "acceptedAnswers": ["cleaned"], "hint": "Last weekend : l''action est terminée.", "explanation": "Last weekend place l''action dans le passé : clean + -ed = cleaned, qui se prononce /kliːnd/ (le -ed sonne comme un d). On ne double pas le n, car clean contient deux voyelles (ea).", "tip": "On double la consonne seulement dans un verbe court à une seule voyelle : stop → stopped.", "extraExample": {"text": "Anna cleaned the house yesterday.", "translation": "Anna a nettoyé la maison hier."}, "errorPatterns": [{"equals": "clean", "category": "verb_tense", "feedback": "Clean est la forme du présent. Avec last weekend, on ajoute -ed : cleaned."}, {"equals": "cleans", "category": "verb_tense", "feedback": "Le -s est réservé au présent. Au passé, tous les sujets prennent -ed : cleaned."}, {"equals": "cleanned", "category": "spelling", "feedback": "Clean a deux voyelles (ea) : on ne double pas le n. On écrit cleaned."}], "pool": "lesson", "lessonId": "en.l29", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l29.e05', 'en', 'en.l29', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular']::text[], 'fill_blank', 'lesson', 'Anna ___ French last night. (study)', array['studied']::text[], 'Quand un verbe se termine par une consonne + y, le y devient i avant -ed : study → studied. Avec une voyelle + y (stay), on garde le y : stayed.', 2, '{"id": "en.l29.e05", "unitIds": ["en.g21.past_simple_regular"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le passé du verbe entre parenthèses.", "prompt": "Anna ___ French last night. (study)", "promptLanguage": "en", "options": ["studied", "studyed", "studdied"], "answer": "studied", "acceptedAnswers": ["studied"], "hint": "Study finit par une consonne + y.", "explanation": "Quand un verbe se termine par une consonne + y, le y devient i avant -ed : study → studied. Avec une voyelle + y (stay), on garde le y : stayed.", "tip": "Consonne + y → -ied : study → studied, carry → carried.", "extraExample": {"text": "He carried the bag to the car.", "translation": "Il a porté le sac jusqu''à la voiture."}, "errorPatterns": [{"equals": "studyed", "category": "spelling", "feedback": "Après une consonne (d), le y se change en i : study → studied."}, {"equals": "studdied", "category": "spelling", "feedback": "On ne double pas le d ici : le y devient simplement i. On écrit studied."}], "pool": "lesson", "lessonId": "en.l29", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l29.e06', 'en', 'en.l29', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.ask']::text[], 'reorder', 'lesson', 'Il a demandé de l''aide à son professeur hier.', array['He asked his teacher for help yesterday','Yesterday he asked his teacher for help']::text[], 'Asked est le passé régulier de ask : on l''entend /ɑːskt/ (le -ed sonne comme un t). L''ordre est sujet + verbe + personne + for + chose demandée : asked his teacher for help.', 2, '{"id": "en.l29.e06", "unitIds": ["en.g21.past_simple_regular", "en.v.ask"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Il a demandé de l''aide à son professeur hier.", "promptLanguage": "fr", "tokens": ["his", "help", "He", "teacher", "yesterday", "for", "asked"], "answer": "He asked his teacher for help yesterday", "acceptedAnswers": ["He asked his teacher for help yesterday", "Yesterday he asked his teacher for help"], "hint": "Ask quelqu''un for + ce qu''on demande.", "explanation": "Asked est le passé régulier de ask : on l''entend /ɑːskt/ (le -ed sonne comme un t). L''ordre est sujet + verbe + personne + for + chose demandée : asked his teacher for help.", "tip": "Demander de l''aide à quelqu''un = ask someone for help.", "extraExample": {"text": "She asked her mother for the key.", "translation": "Elle a demandé la clé à sa mère."}, "pool": "lesson", "lessonId": "en.l29", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l29.e07', 'en', 'en.l29', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.decide','en.v.stay']::text[], 'translation', 'lesson', 'Nous avons décidé de rester à la maison.', array['We decided to stay at home','We decided to stay home']::text[], '« Avons décidé » se dit decided : decide finit par un e, on ajoute seulement -d. Après decided, le verbe suivant est précédé de to : decided to stay, comme want to ou need to.', 2, '{"id": "en.l29.e07", "unitIds": ["en.g21.past_simple_regular", "en.v.decide", "en.v.stay"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Nous avons décidé de rester à la maison.", "promptLanguage": "fr", "answer": "We decided to stay at home", "acceptedAnswers": ["We decided to stay at home", "We decided to stay home"], "hint": "Decide finit déjà par un e. Après decided, on met to + verbe.", "explanation": "« Avons décidé » se dit decided : decide finit par un e, on ajoute seulement -d. Après decided, le verbe suivant est précédé de to : decided to stay, comme want to ou need to.", "tip": "decide + to + verbe : on garde toujours to.", "extraExample": {"text": "Anna decided to call her mother.", "translation": "Anna a décidé d''appeler sa mère."}, "errorPatterns": [{"contains": "we decide to", "category": "verb_tense", "feedback": "Decide est le présent. L''action est faite : on écrit decided."}, {"contains": "decided stay", "category": "grammar", "feedback": "Après decided, il faut to devant le verbe : decided to stay."}, {"contains": "we have decided", "category": "verb_tense", "feedback": "L''anglais n''utilise pas have ici. Pour « nous avons décidé », on dit simplement we decided."}], "pool": "lesson", "lessonId": "en.l29", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l29.e08', 'en', 'en.l29', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.arrive']::text[], 'translation', 'lesson', 'Mon frère est arrivé au bureau à huit heures.', array['My brother arrived at the office at eight','My brother arrived at the office at eight o''clock','My brother arrived at work at eight','My brother arrived at work at eight o''clock']::text[], '« Est arrivé » se traduit par arrived : arrive + -d. Après arrive, on dit at pour un lieu précis (at the office) et in pour une ville ou un pays (in London).', 3, '{"id": "en.l29.e08", "unitIds": ["en.g21.past_simple_regular", "en.v.arrive"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Mon frère est arrivé au bureau à huit heures.", "promptLanguage": "fr", "answer": "My brother arrived at the office at eight", "acceptedAnswers": ["My brother arrived at the office at eight", "My brother arrived at the office at eight o''clock", "My brother arrived at work at eight", "My brother arrived at work at eight o''clock"], "hint": "« Est arrivé » se dit arrived. Quelle préposition après arrive pour un lieu précis ?", "explanation": "« Est arrivé » se traduit par arrived : arrive + -d. Après arrive, on dit at pour un lieu précis (at the office) et in pour une ville ou un pays (in London).", "tip": "Arrive at + lieu précis ; arrive in + ville ou pays. Jamais arrive to.", "extraExample": {"text": "We arrived in Paris at night.", "translation": "Nous sommes arrivés à Paris la nuit."}, "errorPatterns": [{"contains": "arrived to", "category": "preposition", "feedback": "Après arrive, on n''utilise pas to : on dit arrived at the office."}, {"contains": "brother arrive at", "category": "verb_tense", "feedback": "Arrive est le présent. Pour « est arrivé », on ajoute -d : arrived."}, {"contains": "arrived in the office", "category": "preposition", "feedback": "Pour un lieu précis comme un bureau, on dit at : arrived at the office."}], "pool": "lesson", "lessonId": "en.l29", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l29.e09', 'en', 'en.l29', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.answer']::text[], 'free_answer', 'lesson', 'Comment dit-on « Elle a répondu au téléphone » en anglais ?', array['She answered the phone','She answered her phone','She answered the call']::text[], 'Answer est régulier : answered se prononce /ˈɑːnsəd/ (le w ne s''entend pas). On dit answer the phone, sans to : le verbe est directement suivi de ce à quoi on répond.', 3, '{"id": "en.l29.e09", "unitIds": ["en.g21.past_simple_regular", "en.v.answer"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Elle a répondu au téléphone » en anglais ?", "promptLanguage": "fr", "answer": "She answered the phone", "acceptedAnswers": ["She answered the phone", "She answered her phone", "She answered the call"], "hint": "Answer est un verbe régulier. Après answer, pas de préposition.", "explanation": "Answer est régulier : answered se prononce /ˈɑːnsəd/ (le w ne s''entend pas). On dit answer the phone, sans to : le verbe est directement suivi de ce à quoi on répond.", "tip": "Answer the phone : pas de to entre les deux.", "extraExample": {"text": "I answered the phone in the car.", "translation": "J''ai répondu au téléphone dans la voiture."}, "errorPatterns": [{"contains": "answer the phone", "category": "verb_tense", "feedback": "Answer est la forme du présent. L''action est terminée : answered."}, {"contains": "answered to", "category": "preposition", "feedback": "Ici, answer se construit sans to : answered the phone."}], "pool": "lesson", "lessonId": "en.l29", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l29.e10', 'en', 'en.l29', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.stop']::text[], 'free_answer', 'lesson', 'Comment dit-on « Tom a arrêté la musique » en anglais ?', array['Tom stopped the music']::text[], 'Stop est un verbe court qui finit par consonne-voyelle-consonne (s-t-o-p) : on double la dernière lettre avant -ed. Cela donne stopped, qui se prononce /stɒpt/ (le -ed sonne comme un t).', 3, '{"id": "en.l29.e10", "unitIds": ["en.g21.past_simple_regular", "en.v.stop"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais avec le verbe stop.", "prompt": "Comment dit-on « Tom a arrêté la musique » en anglais ?", "promptLanguage": "fr", "answer": "Tom stopped the music", "acceptedAnswers": ["Tom stopped the music"], "hint": "Stop est un verbe court : pense à doubler la dernière lettre.", "explanation": "Stop est un verbe court qui finit par consonne-voyelle-consonne (s-t-o-p) : on double la dernière lettre avant -ed. Cela donne stopped, qui se prononce /stɒpt/ (le -ed sonne comme un t).", "tip": "Verbe court en consonne-voyelle-consonne : on double la consonne (stop → stopped).", "extraExample": {"text": "The rain stopped at night.", "translation": "La pluie s''est arrêtée dans la nuit."}, "errorPatterns": [{"contains": "stoped", "category": "spelling", "feedback": "Stop est un verbe court : on double le p. On écrit stopped, avec deux p."}, {"contains": "tom stop the", "category": "verb_tense", "feedback": "Stop est la forme du présent. L''action est terminée : stopped."}], "pool": "lesson", "lessonId": "en.l29", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l30.e01', 'en', 'en.l30', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs']::text[], 'mcq', 'lesson', 'What is the past tense of go?', array['Went']::text[], 'Go est un verbe irrégulier : son passé ne se forme pas avec -ed, il a une forme à lui, went. Gone existe aussi, mais c''est le participe passé, utilisé dans d''autres temps que tu verras plus tard.', 1, '{"id": "en.l30.e01", "unitIds": ["en.g22.irregular_verbs"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le passé du verbe.", "prompt": "What is the past tense of go?", "promptLanguage": "en", "options": ["Goed", "Went", "Gone"], "answer": "Went", "acceptedAnswers": ["Went"], "hint": "Go est un verbe irrégulier : il ne prend pas -ed.", "explanation": "Go est un verbe irrégulier : son passé ne se forme pas avec -ed, il a une forme à lui, went. Gone existe aussi, mais c''est le participe passé, utilisé dans d''autres temps que tu verras plus tard.", "tip": "Go → went : apprends-le dans une mini-phrase, I went home.", "extraExample": {"text": "She went to bed at ten.", "translation": "Elle est allée se coucher à dix heures."}, "errorPatterns": [{"equals": "goed", "category": "conjugation", "feedback": "Goed n''existe pas : go est irrégulier, on ne lui ajoute pas -ed. Son passé est went."}, {"equals": "gone", "category": "conjugation", "feedback": "Gone est le participe passé de go, pas le passé simple. Pour raconter hier, on dit went."}], "pool": "lesson", "lessonId": "en.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l30.e02', 'en', 'en.l30', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.see']::text[], 'mcq', 'lesson', 'Last week, I ___ Tom at the gym.', array['saw']::text[], 'See est un verbe irrégulier : son passé est saw (/sɔː/). Seen est le participe passé, utilisé dans d''autres temps, et see est la forme de base du présent.', 1, '{"id": "en.l30.e02", "unitIds": ["en.g22.irregular_verbs", "en.v.see"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Last week, I ___ Tom at the gym.", "promptLanguage": "en", "options": ["saw", "seen", "see"], "answer": "saw", "acceptedAnswers": ["saw"], "hint": "Last week : le passé simple de see.", "explanation": "See est un verbe irrégulier : son passé est saw (/sɔː/). Seen est le participe passé, utilisé dans d''autres temps, et see est la forme de base du présent.", "tip": "See → saw : « I saw Tom » = j''ai vu Tom.", "extraExample": {"text": "We saw Anna at school yesterday.", "translation": "Nous avons vu Anna à l''école hier."}, "errorPatterns": [{"equals": "seen", "category": "conjugation", "feedback": "Seen est le participe passé de see. Pour raconter au passé simple, on dit saw."}, {"equals": "see", "category": "verb_tense", "feedback": "See est la forme de base, pour le présent. Avec last week, on utilise le passé : saw."}], "pool": "lesson", "lessonId": "en.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l30.e03', 'en', 'en.l30', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.see','en.v.say','en.v.tell','en.v.find','en.v.put']::text[], 'match', 'lesson', 'Cinq verbes irréguliers au passé', '{}'::text[], 'Ces verbes sont irréguliers : leur passé ne se termine pas par -ed, il faut l''apprendre par cœur. Put ne change pas (put → put). Said se prononce /sed/, comme « sèd ».', 1, '{"id": "en.l30.e03", "unitIds": ["en.g22.irregular_verbs", "en.v.see", "en.v.say", "en.v.tell", "en.v.find", "en.v.put"], "type": "match", "difficulty": 1, "instruction": "Associe chaque verbe au passé à sa traduction.", "prompt": "Cinq verbes irréguliers au passé", "promptLanguage": "fr", "pairs": [{"left": "saw", "right": "a vu"}, {"left": "said", "right": "a dit"}, {"left": "told", "right": "a raconté / a dit à quelqu''un"}, {"left": "found", "right": "a trouvé"}, {"left": "put", "right": "a mis"}], "answer": "saw = a vu ; said = a dit ; told = a raconté / a dit à quelqu''un ; found = a trouvé ; put = a mis", "acceptedAnswers": [], "explanation": "Ces verbes sont irréguliers : leur passé ne se termine pas par -ed, il faut l''apprendre par cœur. Put ne change pas (put → put). Said se prononce /sed/, comme « sèd ».", "tip": "Un verbe irrégulier, une forme à apprendre : retiens-la dans une mini-phrase.", "extraExample": {"text": "She put the key in the door.", "translation": "Elle a mis la clé dans la porte."}, "pool": "lesson", "lessonId": "en.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l30.e04', 'en', 'en.l30', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs']::text[], 'fill_blank', 'lesson', 'Yesterday, I ___ to school.', array['went']::text[], 'Yesterday place l''action dans le passé : on utilise le passé de go, qui est went. Went est la même forme pour tous les sujets : I went, she went, they went.', 2, '{"id": "en.l30.e04", "unitIds": ["en.g22.irregular_verbs"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le passé de go.", "prompt": "Yesterday, I ___ to school.", "promptLanguage": "en", "options": ["went", "go", "goed", "gone"], "answer": "went", "acceptedAnswers": ["went"], "hint": "Yesterday = hier : cherche le passé irrégulier de go.", "explanation": "Yesterday place l''action dans le passé : on utilise le passé de go, qui est went. Went est la même forme pour tous les sujets : I went, she went, they went.", "tip": "Yesterday + go ? Non : yesterday + went.", "extraExample": {"text": "Anna went to the gym two days ago.", "translation": "Anna est allée à la salle de sport il y a deux jours."}, "errorPatterns": [{"equals": "go", "category": "verb_tense", "feedback": "Go est le présent. Yesterday parle du passé : I went."}, {"equals": "goed", "category": "conjugation", "feedback": "Go est irrégulier : on n''ajoute pas -ed. Son passé est went."}, {"equals": "gone", "category": "conjugation", "feedback": "Gone est le participe passé. Pour le passé simple, on dit went."}], "pool": "lesson", "lessonId": "en.l30", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l30.e05', 'en', 'en.l30', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.put']::text[], 'fill_blank', 'lesson', 'Yesterday, she ___ her keys in her bag. (put)', array['put']::text[], 'Put est un verbe irrégulier un peu spécial : il a la même forme au présent et au passé (put → put). Ici, yesterday montre que l''action est passée. Il n''y a pas de -s avec she au passé.', 2, '{"id": "en.l30.e05", "unitIds": ["en.g22.irregular_verbs", "en.v.put"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le passé du verbe entre parenthèses.", "prompt": "Yesterday, she ___ her keys in her bag. (put)", "promptLanguage": "en", "options": ["put", "putted", "puts"], "answer": "put", "acceptedAnswers": ["put"], "hint": "Ce verbe irrégulier est très particulier : regarde bien les options.", "explanation": "Put est un verbe irrégulier un peu spécial : il a la même forme au présent et au passé (put → put). Ici, yesterday montre que l''action est passée. Il n''y a pas de -s avec she au passé.", "tip": "Put → put : la forme ne change pas, c''est yesterday qui indique le passé.", "extraExample": {"text": "Tom put his phone in his bag last night.", "translation": "Tom a mis son téléphone dans son sac hier soir."}, "errorPatterns": [{"equals": "putted", "category": "conjugation", "feedback": "Put est irrégulier : on n''ajoute pas -ed. Son passé est put, sans changement."}, {"equals": "puts", "category": "verb_tense", "feedback": "Le -s est réservé au présent. Au passé, même avec she, on dit put."}], "pool": "lesson", "lessonId": "en.l30", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l30.e06', 'en', 'en.l30', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.take']::text[], 'reorder', 'lesson', 'Tom a pris son sac et il est rentré à la maison.', array['Tom took his bag and went home']::text[], 'Took est le passé irrégulier de take, et went est celui de go. Quand deux actions se suivent, on garde chaque verbe au passé et on les relie par and. Home se place directement après went, sans to.', 2, '{"id": "en.l30.e06", "unitIds": ["en.g22.irregular_verbs", "en.v.take"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Tom a pris son sac et il est rentré à la maison.", "promptLanguage": "fr", "tokens": ["home", "Tom", "bag", "and", "his", "went", "took"], "answer": "Tom took his bag and went home", "acceptedAnswers": ["Tom took his bag and went home"], "hint": "Deux verbes irréguliers reliés par and : took, puis went.", "explanation": "Took est le passé irrégulier de take, et went est celui de go. Quand deux actions se suivent, on garde chaque verbe au passé et on les relie par and. Home se place directement après went, sans to.", "tip": "Go home : pas de to devant home (went home).", "extraExample": {"text": "Anna took her phone and came home.", "translation": "Anna a pris son téléphone et elle est rentrée."}, "pool": "lesson", "lessonId": "en.l30", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l30.e07', 'en', 'en.l30', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs']::text[], 'translation', 'lesson', 'Je suis allé au travail.', array['I went to work']::text[], '« Je suis allé » se traduit par I went : on utilise le passé simple de go, sans verbe être comme en français. Après went, on met to + le lieu : went to work.', 2, '{"id": "en.l30.e07", "unitIds": ["en.g22.irregular_verbs"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Je suis allé au travail.", "promptLanguage": "fr", "answer": "I went to work", "acceptedAnswers": ["I went to work"], "hint": "Le passé composé français devient le passé simple anglais : quel est le passé de go ?", "explanation": "« Je suis allé » se traduit par I went : on utilise le passé simple de go, sans verbe être comme en français. Après went, on met to + le lieu : went to work.", "tip": "Pas d''auxiliaire : « je suis allé » = I went.", "extraExample": {"text": "She went to work by car.", "translation": "Elle est allée au travail en voiture."}, "errorPatterns": [{"contains": "goed", "category": "conjugation", "feedback": "Go est irrégulier : son passé est went, sans -ed."}, {"contains": "gone", "category": "conjugation", "feedback": "Gone est le participe passé. Pour « je suis allé », on dit I went."}, {"contains": "was go", "category": "grammar", "feedback": "On n''ajoute pas was devant go : went exprime déjà le passé."}, {"equals": "i go to work", "category": "verb_tense", "feedback": "I go est le présent. Pour « je suis allé », on utilise le passé : I went."}], "pool": "lesson", "lessonId": "en.l30", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l30.e08', 'en', 'en.l30', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.find']::text[], 'translation', 'lesson', 'Mon père a trouvé mes clés hier.', array['My father found my keys yesterday','Yesterday my father found my keys','My dad found my keys yesterday','Yesterday my dad found my keys']::text[], 'Find est un verbe irrégulier : son passé est found (/faʊnd/), sans -ed. Cette forme est la même pour tous les sujets.', 3, '{"id": "en.l30.e08", "unitIds": ["en.g22.irregular_verbs", "en.v.find"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Mon père a trouvé mes clés hier.", "promptLanguage": "fr", "answer": "My father found my keys yesterday", "acceptedAnswers": ["My father found my keys yesterday", "Yesterday my father found my keys", "My dad found my keys yesterday", "Yesterday my dad found my keys"], "hint": "Find est irrégulier. Son passé se prononce /faʊnd/.", "explanation": "Find est un verbe irrégulier : son passé est found (/faʊnd/), sans -ed. Cette forme est la même pour tous les sujets.", "tip": "Find → found : trouvé. Attention, founded vient d''un autre verbe (fonder).", "extraExample": {"text": "Anna found her bag in the car.", "translation": "Anna a trouvé son sac dans la voiture."}, "errorPatterns": [{"contains": "finded", "category": "conjugation", "feedback": "Find est irrégulier : on n''ajoute pas -ed. Son passé est found."}, {"contains": "founded", "category": "word_confusion", "feedback": "Founded est le passé de found (fonder). Le passé de find (trouver) est simplement found."}, {"contains": "father find", "category": "verb_tense", "feedback": "Find est le présent. Hier, l''action est terminée : found."}], "pool": "lesson", "lessonId": "en.l30", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l30.e09', 'en', 'en.l30', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.tell','en.v.say']::text[], 'free_answer', 'lesson', 'Comment dit-on « Il m''a dit son nom » en anglais ?', array['He told me his name','He said his name to me']::text[], 'Tell veut dire « dire à quelqu''un » et se construit directement avec la personne : told me. Son passé est irrégulier (told, pas telled). Say se construit avec to : said his name to me, jamais said me.', 3, '{"id": "en.l30.e09", "unitIds": ["en.g22.irregular_verbs", "en.v.tell", "en.v.say"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Il m''a dit son nom » en anglais ?", "promptLanguage": "fr", "answer": "He told me his name", "acceptedAnswers": ["He told me his name", "He said his name to me"], "hint": "Pour « dire à quelqu''un », on utilise un verbe qui se construit directement avec la personne.", "explanation": "Tell veut dire « dire à quelqu''un » et se construit directement avec la personne : told me. Son passé est irrégulier (told, pas telled). Say se construit avec to : said his name to me, jamais said me.", "tip": "Tell + personne (told me) ; say + chose (said hello).", "extraExample": {"text": "Anna told Tom her name.", "translation": "Anna a dit son nom à Tom."}, "errorPatterns": [{"contains": "said me", "category": "word_confusion", "feedback": "Après said, on ne met pas directement la personne. Dis told me, ou said … to me."}, {"contains": "telled", "category": "conjugation", "feedback": "Tell est irrégulier : on n''ajoute pas -ed. Son passé est told."}, {"contains": "he tell me", "category": "verb_tense", "feedback": "Tell est le présent. Pour une action finie, on dit told."}], "pool": "lesson", "lessonId": "en.l30", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l30.e10', 'en', 'en.l30', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs']::text[], 'free_answer', 'lesson', 'Écris une phrase au passé avec go.', array['I went to school yesterday','Yesterday I went to the gym','We went home late last night','She went to work two days ago']::text[], 'Au passé, go devient went, pour toutes les personnes. Avec un repère de temps (yesterday, last week, two days ago), ta phrase est claire et naturelle.', 3, '{"id": "en.l30.e10", "unitIds": ["en.g22.irregular_verbs"], "type": "free_answer", "difficulty": 3, "instruction": "Écris une phrase en anglais.", "prompt": "Écris une phrase au passé avec go.", "promptLanguage": "fr", "requirements": {"mustInclude": [["went"]], "minWords": 3}, "hint": "Utilise le passé irrégulier de go et un repère de temps comme yesterday ou last week.", "answer": "I went to school yesterday", "acceptedAnswers": ["I went to school yesterday", "Yesterday I went to the gym", "We went home late last night", "She went to work two days ago"], "explanation": "Au passé, go devient went, pour toutes les personnes. Avec un repère de temps (yesterday, last week, two days ago), ta phrase est claire et naturelle.", "tip": "Went + un repère de temps : c''est un passé réussi.", "extraExample": {"text": "They went to London last week.", "translation": "Ils sont allés à Londres la semaine dernière."}, "errorPatterns": [{"contains": "goed", "category": "conjugation", "feedback": "Go est irrégulier : son passé est went, sans -ed."}, {"contains": "gone", "category": "conjugation", "feedback": "Gone est le participe passé. Pour le passé simple, on utilise went."}, {"contains": "was go", "category": "grammar", "feedback": "On n''ajoute pas was devant go : went exprime déjà le passé."}], "pool": "lesson", "lessonId": "en.l30", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l31.e01', 'en', 'en.l31', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.buy']::text[], 'mcq', 'lesson', 'Anna ___ a book for her brother yesterday.', array['bought']::text[], 'Buy est irrégulier : son passé est bought (/bɔːt/), et non buyed. Cette forme est la même pour tous les sujets : I bought, she bought.', 1, '{"id": "en.l31.e01", "unitIds": ["en.g22.irregular_verbs", "en.v.buy"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Anna ___ a book for her brother yesterday.", "promptLanguage": "en", "options": ["bought", "buyed", "buy"], "answer": "bought", "acceptedAnswers": ["bought"], "hint": "Buy est un verbe irrégulier : il ne prend pas -ed.", "explanation": "Buy est irrégulier : son passé est bought (/bɔːt/), et non buyed. Cette forme est la même pour tous les sujets : I bought, she bought.", "tip": "Buy → bought : on n''ajoute jamais -ed à un verbe irrégulier.", "extraExample": {"text": "My father bought a car two days ago.", "translation": "Mon père a acheté une voiture il y a deux jours."}, "errorPatterns": [{"equals": "buyed", "category": "conjugation", "feedback": "Buy est irrégulier : on n''ajoute pas -ed. Son passé est bought."}, {"equals": "buy", "category": "verb_tense", "feedback": "Buy est la forme de base, pour le présent. Avec yesterday, on dit bought."}], "pool": "lesson", "lessonId": "en.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l31.e02', 'en', 'en.l31', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.forget']::text[], 'mcq', 'lesson', 'Yesterday morning, Tom ___ his keys at home.', array['forgot']::text[], 'Forget est irrégulier : son passé est forgot (/fəˈɡɒt/). Forgotten est le participe passé, utilisé dans d''autres temps, et forgetted n''existe pas.', 2, '{"id": "en.l31.e02", "unitIds": ["en.g22.irregular_verbs", "en.v.forget"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme.", "prompt": "Yesterday morning, Tom ___ his keys at home.", "promptLanguage": "en", "options": ["forgot", "forgotten", "forgetted"], "answer": "forgot", "acceptedAnswers": ["forgot"], "hint": "Forget est irrégulier, comme get → got.", "explanation": "Forget est irrégulier : son passé est forgot (/fəˈɡɒt/). Forgotten est le participe passé, utilisé dans d''autres temps, et forgetted n''existe pas.", "tip": "Forget → forgot, comme get → got : le e devient o.", "extraExample": {"text": "I forgot my homework yesterday.", "translation": "J''ai oublié mes devoirs hier."}, "errorPatterns": [{"equals": "forgotten", "category": "conjugation", "feedback": "Forgotten est le participe passé. Pour raconter au passé simple, on dit forgot."}, {"equals": "forgetted", "category": "conjugation", "feedback": "Forget est irrégulier : on n''ajoute pas -ed. Son passé est forgot."}], "pool": "lesson", "lessonId": "en.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l31.e03', 'en', 'en.l31', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.buy','en.v.leave','en.v.meet','en.v.forget','en.v.begin']::text[], 'match', 'lesson', 'Cinq autres verbes irréguliers au passé', '{}'::text[], 'Ces verbes sont irréguliers : leur passé s''apprend par cœur. Ils se prononcent bought /bɔːt/, left /left/, met /met/, forgot /fəˈɡɒt/ et began /bɪˈɡæn/, avec la même forme pour tous les sujets.', 1, '{"id": "en.l31.e03", "unitIds": ["en.g22.irregular_verbs", "en.v.buy", "en.v.leave", "en.v.meet", "en.v.forget", "en.v.begin"], "type": "match", "difficulty": 1, "instruction": "Associe chaque verbe au passé à sa traduction.", "prompt": "Cinq autres verbes irréguliers au passé", "promptLanguage": "fr", "pairs": [{"left": "bought", "right": "a acheté"}, {"left": "left", "right": "est parti / a quitté"}, {"left": "met", "right": "a rencontré / a retrouvé"}, {"left": "forgot", "right": "a oublié"}, {"left": "began", "right": "a commencé"}], "answer": "bought = a acheté ; left = est parti / a quitté ; met = a rencontré / a retrouvé ; forgot = a oublié ; began = a commencé", "acceptedAnswers": [], "explanation": "Ces verbes sont irréguliers : leur passé s''apprend par cœur. Ils se prononcent bought /bɔːt/, left /left/, met /met/, forgot /fəˈɡɒt/ et began /bɪˈɡæn/, avec la même forme pour tous les sujets.", "tip": "Beaucoup de passés irréguliers se ressemblent : buy → bought, think → thought.", "extraExample": {"text": "Sam came home late and slept all morning.", "translation": "Sam est rentré tard et a dormi toute la matinée."}, "pool": "lesson", "lessonId": "en.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l31.e04', 'en', 'en.l31', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.meet']::text[], 'fill_blank', 'lesson', 'I ___ my teacher in London last week. (meet)', array['met']::text[], 'Meet est irrégulier : meet → met (/met/). Last week place l''action dans le passé. Met est la même forme pour tous les sujets.', 2, '{"id": "en.l31.e04", "unitIds": ["en.g22.irregular_verbs", "en.v.meet"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le passé du verbe entre parenthèses.", "prompt": "I ___ my teacher in London last week. (meet)", "promptLanguage": "en", "options": ["met", "meeted", "meet"], "answer": "met", "acceptedAnswers": ["met"], "hint": "Le passé de meet est plus court que meet.", "explanation": "Meet est irrégulier : meet → met (/met/). Last week place l''action dans le passé. Met est la même forme pour tous les sujets.", "tip": "Meet → met : il suffit d''enlever un e.", "extraExample": {"text": "We met Anna at the door.", "translation": "Nous avons retrouvé Anna à la porte."}, "errorPatterns": [{"equals": "meeted", "category": "conjugation", "feedback": "Meet est irrégulier : on n''ajoute pas -ed. Son passé est met."}, {"equals": "meet", "category": "verb_tense", "feedback": "Meet est le présent. Avec last week, on utilise le passé : met."}], "pool": "lesson", "lessonId": "en.l31", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l31.e05', 'en', 'en.l31', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.leave']::text[], 'fill_blank', 'lesson', 'My mother ___ the house at eight yesterday. (leave)', array['left']::text[], 'Leave est irrégulier : leave → left (/left/). Leave the house veut dire « quitter la maison ». Avec yesterday, l''action est terminée, donc on utilise le passé.', 2, '{"id": "en.l31.e05", "unitIds": ["en.g22.irregular_verbs", "en.v.leave"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le passé du verbe entre parenthèses.", "prompt": "My mother ___ the house at eight yesterday. (leave)", "promptLanguage": "en", "options": ["left", "leaved", "leave"], "answer": "left", "acceptedAnswers": ["left"], "hint": "Leave est irrégulier.", "explanation": "Leave est irrégulier : leave → left (/left/). Leave the house veut dire « quitter la maison ». Avec yesterday, l''action est terminée, donc on utilise le passé.", "tip": "Leave → left : « partir » et « quitter » au passé.", "extraExample": {"text": "He left home at six.", "translation": "Il est parti de la maison à six heures."}, "errorPatterns": [{"equals": "leaved", "category": "conjugation", "feedback": "Leave est irrégulier : on n''ajoute pas -ed. Son passé est left."}, {"equals": "leave", "category": "verb_tense", "feedback": "Leave est la forme du présent. Avec yesterday, on dit left."}], "pool": "lesson", "lessonId": "en.l31", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l31.e06', 'en', 'en.l31', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.eat','en.v.drink']::text[], 'reorder', 'lesson', 'Nous avons mangé du poisson et bu de l''eau.', array['We ate fish and drank water']::text[], 'Ate est le passé de eat, et drank est le passé de drink : deux verbes irréguliers. Quand le sujet est le même, on ne le répète pas après and : We ate fish and drank water.', 2, '{"id": "en.l31.e06", "unitIds": ["en.g22.irregular_verbs", "en.v.eat", "en.v.drink"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Nous avons mangé du poisson et bu de l''eau.", "promptLanguage": "fr", "tokens": ["fish", "We", "water", "ate", "and", "drank"], "answer": "We ate fish and drank water", "acceptedAnswers": ["We ate fish and drank water"], "hint": "Deux verbes irréguliers, un pour manger, un pour boire.", "explanation": "Ate est le passé de eat, et drank est le passé de drink : deux verbes irréguliers. Quand le sujet est le même, on ne le répète pas après and : We ate fish and drank water.", "tip": "Eat → ate ; drink → drank : on retient chacun avec sa mini-phrase.", "extraExample": {"text": "I ate lunch and drank water.", "translation": "J''ai déjeuné et bu de l''eau."}, "pool": "lesson", "lessonId": "en.l31", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l31.e07', 'en', 'en.l31', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.buy','en.v.yesterday']::text[], 'translation', 'lesson', 'J''ai acheté du lait hier.', array['I bought milk yesterday','I bought some milk yesterday','Yesterday I bought milk','Yesterday I bought some milk']::text[], '« J''ai acheté » se traduit par I bought, sans auxiliaire. Buy est irrégulier : son passé est bought. Milk ne se compte pas : on dit simplement milk ou some milk, sans a.', 2, '{"id": "en.l31.e07", "unitIds": ["en.g22.irregular_verbs", "en.v.buy", "en.v.yesterday"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "J''ai acheté du lait hier.", "promptLanguage": "fr", "answer": "I bought milk yesterday", "acceptedAnswers": ["I bought milk yesterday", "I bought some milk yesterday", "Yesterday I bought milk", "Yesterday I bought some milk"], "hint": "« J''ai acheté » : le passé composé devient le passé simple.", "explanation": "« J''ai acheté » se traduit par I bought, sans auxiliaire. Buy est irrégulier : son passé est bought. Milk ne se compte pas : on dit simplement milk ou some milk, sans a.", "tip": "Pas d''auxiliaire : « j''ai acheté » = I bought.", "extraExample": {"text": "She bought fish for dinner.", "translation": "Elle a acheté du poisson pour le dîner."}, "errorPatterns": [{"contains": "buyed", "category": "conjugation", "feedback": "Buy est irrégulier : on n''ajoute pas -ed. Son passé est bought."}, {"contains": "i buy", "category": "verb_tense", "feedback": "Buy est le présent. Hier, l''action est terminée : I bought."}, {"contains": "i have bought", "category": "verb_tense", "feedback": "L''anglais n''utilise pas have ici. Pour une action finie hier, on dit simplement I bought."}], "pool": "lesson", "lessonId": "en.l31", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l31.e08', 'en', 'en.l31', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.meet']::text[], 'translation', 'lesson', 'Elle a rencontré son mari au bureau.', array['She met her husband at the office','She met her husband at work']::text[], '« A rencontré » se traduit par met, le passé irrégulier de meet. Meet se construit directement avec la personne, sans préposition : met her husband. Her veut dire « son, sa » quand le possesseur est une femme.', 3, '{"id": "en.l31.e08", "unitIds": ["en.g22.irregular_verbs", "en.v.meet"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Elle a rencontré son mari au bureau.", "promptLanguage": "fr", "answer": "She met her husband at the office", "acceptedAnswers": ["She met her husband at the office", "She met her husband at work"], "hint": "Meet est irrégulier. Son passé est plus court que meet.", "explanation": "« A rencontré » se traduit par met, le passé irrégulier de meet. Meet se construit directement avec la personne, sans préposition : met her husband. Her veut dire « son, sa » quand le possesseur est une femme.", "tip": "Meet + personne : pas de préposition (met her husband).", "extraExample": {"text": "Tom met his wife at school.", "translation": "Tom a rencontré sa femme à l''école."}, "errorPatterns": [{"contains": "meeted", "category": "conjugation", "feedback": "Meet est irrégulier : on n''ajoute pas -ed. Son passé est met."}, {"contains": "she meet", "category": "verb_tense", "feedback": "Meet est le présent. Pour une action finie, on dit met."}, {"contains": "met to", "category": "preposition", "feedback": "Après meet, on ne met pas to : on dit met her husband."}], "pool": "lesson", "lessonId": "en.l31", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l31.e09', 'en', 'en.l31', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.begin']::text[], 'free_answer', 'lesson', 'Comment dit-on « Nous avons commencé à neuf heures » en anglais ?', array['We began at nine','We began at nine o''clock']::text[], 'Begin est irrégulier : begin → began (/bɪˈɡæn/). Begin veut dire comme start « commencer », mais began est irrégulier alors que started est régulier. Began est la même forme pour tous les sujets.', 3, '{"id": "en.l31.e09", "unitIds": ["en.g22.irregular_verbs", "en.v.begin"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais avec le verbe begin.", "prompt": "Comment dit-on « Nous avons commencé à neuf heures » en anglais ?", "promptLanguage": "fr", "answer": "We began at nine", "acceptedAnswers": ["We began at nine", "We began at nine o''clock"], "hint": "Begin est irrégulier, comme drink → drank et swim → swam.", "explanation": "Begin est irrégulier : begin → began (/bɪˈɡæn/). Begin veut dire comme start « commencer », mais began est irrégulier alors que started est régulier. Began est la même forme pour tous les sujets.", "tip": "Begin → began, comme drink → drank et swim → swam : le i devient a.", "extraExample": {"text": "Anna began work at seven.", "translation": "Anna a commencé à travailler à sept heures."}, "errorPatterns": [{"contains": "begined", "category": "conjugation", "feedback": "Begin est irrégulier : on n''ajoute pas -ed. Son passé est began."}, {"contains": "begun", "category": "conjugation", "feedback": "Begun est le participe passé de begin. Pour le passé simple, on dit began."}, {"contains": "we begin at", "category": "verb_tense", "feedback": "Begin est le présent. Pour une action finie, on dit began."}], "pool": "lesson", "lessonId": "en.l31", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l31.e10', 'en', 'en.l31', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.give']::text[], 'free_answer', 'lesson', 'Comment dit-on « Tom a donné un café à Anna » en anglais ?', array['Tom gave Anna a coffee','Tom gave a coffee to Anna','Tom gave Anna some coffee','Tom gave some coffee to Anna']::text[], 'Give est irrégulier : give → gave (/geɪv/). Après gave, on met la personne puis la chose (gave Anna a coffee), ou la chose puis to et la personne (gave a coffee to Anna).', 3, '{"id": "en.l31.e10", "unitIds": ["en.g22.irregular_verbs", "en.v.give"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Tom a donné un café à Anna » en anglais ?", "promptLanguage": "fr", "answer": "Tom gave Anna a coffee", "acceptedAnswers": ["Tom gave Anna a coffee", "Tom gave a coffee to Anna", "Tom gave Anna some coffee", "Tom gave some coffee to Anna"], "hint": "Give est irrégulier : le i devient a.", "explanation": "Give est irrégulier : give → gave (/geɪv/). Après gave, on met la personne puis la chose (gave Anna a coffee), ou la chose puis to et la personne (gave a coffee to Anna).", "tip": "gave + personne + chose, ou gave + chose + to + personne.", "extraExample": {"text": "My mother gave me the key.", "translation": "Ma mère m''a donné la clé."}, "errorPatterns": [{"contains": "gived", "category": "conjugation", "feedback": "Give est irrégulier : on n''ajoute pas -ed. Son passé est gave."}, {"contains": "given", "category": "conjugation", "feedback": "Given est le participe passé de give. Pour le passé simple, on dit gave."}, {"contains": "tom give", "category": "verb_tense", "feedback": "Give est le présent. Pour une action finie, on dit gave."}], "pool": "lesson", "lessonId": "en.l31", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l32.e01', 'en', 'en.l32', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.beach']::text[], 'mcq', 'lesson', '___ you go to the beach yesterday?', array['Did']::text[], 'Pour poser une question au passé avec un verbe d''action comme go, on commence par did : Did you go…? Do est le présent, et were s''utilise seulement avec to be (Were you at home ?).', 1, '{"id": "en.l32.e01", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.beach"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "___ you go to the beach yesterday?", "promptLanguage": "en", "options": ["Did", "Do", "Were"], "answer": "Did", "acceptedAnswers": ["Did"], "hint": "Yesterday : la question est au passé.", "explanation": "Pour poser une question au passé avec un verbe d''action comme go, on commence par did : Did you go…? Do est le présent, et were s''utilise seulement avec to be (Were you at home ?).", "tip": "Question au passé : Did + sujet + verbe de base.", "extraExample": {"text": "Did Anna call you last night?", "translation": "Est-ce qu''Anna t''a appelé hier soir ?"}, "errorPatterns": [{"equals": "do", "category": "verb_tense", "feedback": "Do est le présent. Yesterday parle du passé : on commence la question par did."}, {"equals": "were", "category": "grammar", "feedback": "Were s''utilise avec to be (Were you tired ?). Avec un verbe d''action comme go, on utilise did."}], "pool": "lesson", "lessonId": "en.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l32.e02', 'en', 'en.l32', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.trip']::text[], 'mcq', 'lesson', 'Did you ___ a good trip?', array['have']::text[], 'Après did, le verbe reste à la forme de base : have, et non had. Le passé est déjà dans did. Trip veut dire « voyage » ou « excursion ».', 2, '{"id": "en.l32.e02", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.trip"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme du verbe.", "prompt": "Did you ___ a good trip?", "promptLanguage": "en", "options": ["have", "had", "has"], "answer": "have", "acceptedAnswers": ["have"], "hint": "Did porte déjà le passé.", "explanation": "Après did, le verbe reste à la forme de base : have, et non had. Le passé est déjà dans did. Trip veut dire « voyage » ou « excursion ».", "tip": "Did porte le passé : le verbe qui suit reste à la base.", "extraExample": {"text": "Did you take the key?", "translation": "Est-ce que tu as pris la clé ?"}, "errorPatterns": [{"equals": "had", "category": "conjugation", "feedback": "Le passé est déjà porté par did : après did, on garde la base have, pas had."}, {"equals": "has", "category": "conjugation", "feedback": "Après did, il n''y a pas de -s : Did you have…? Le verbe reste à la forme de base."}], "pool": "lesson", "lessonId": "en.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l32.e03', 'en', 'en.l32', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.holiday','en.v.beach','en.v.hotel','en.v.trip','en.v.weather']::text[], 'match', 'lesson', 'Le vocabulaire des vacances', '{}'::text[], 'Holiday veut dire « vacances » : on dit on holiday (en vacances) en anglais britannique, et vacation en américain. Weather est le temps qu''il fait, alors que time est le temps qui passe. Le h de hotel se prononce.', 1, '{"id": "en.l32.e03", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.holiday", "en.v.beach", "en.v.hotel", "en.v.trip", "en.v.weather"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot anglais à sa traduction.", "prompt": "Le vocabulaire des vacances", "promptLanguage": "fr", "pairs": [{"left": "holiday", "right": "vacances"}, {"left": "beach", "right": "plage"}, {"left": "hotel", "right": "hôtel"}, {"left": "trip", "right": "voyage / excursion"}, {"left": "weather", "right": "le temps (la météo)"}], "answer": "holiday = vacances ; beach = plage ; hotel = hôtel ; trip = voyage / excursion ; weather = le temps (la météo)", "acceptedAnswers": [], "explanation": "Holiday veut dire « vacances » : on dit on holiday (en vacances) en anglais britannique, et vacation en américain. Weather est le temps qu''il fait, alors que time est le temps qui passe. Le h de hotel se prononce.", "tip": "Le temps qu''il fait = weather ; le temps qui passe = time.", "extraExample": {"text": "The weather was cold at the beach.", "translation": "Il faisait froid à la plage."}, "pool": "lesson", "lessonId": "en.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l32.e04', 'en', 'en.l32', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.holiday']::text[], 'fill_blank', 'lesson', 'Did Anna go on holiday last week? — No, she ___.', array['didn''t']::text[], 'Pour répondre à une question en did, on reprend did dans une réponse courte : Yes, she did. / No, she didn''t. On ne répète pas le verbe go.', 2, '{"id": "en.l32.e04", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.holiday"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la réponse courte.", "prompt": "Did Anna go on holiday last week? — No, she ___.", "promptLanguage": "en", "options": ["didn''t", "wasn''t", "doesn''t"], "answer": "didn''t", "acceptedAnswers": ["didn''t"], "hint": "La question commence par did : la réponse reprend ce mot.", "explanation": "Pour répondre à une question en did, on reprend did dans une réponse courte : Yes, she did. / No, she didn''t. On ne répète pas le verbe go.", "tip": "Did you…? → Yes, I did. / No, I didn''t.", "extraExample": {"text": "Did you call Tom? — Yes, I did.", "translation": "Tu as appelé Tom ? — Oui."}, "errorPatterns": [{"equals": "wasn''t", "category": "grammar", "feedback": "Wasn''t est le passé de to be. La question commence par did : on répond avec didn''t."}, {"equals": "doesn''t", "category": "verb_tense", "feedback": "Doesn''t est le présent. La question est au passé : on répond avec didn''t."}], "pool": "lesson", "lessonId": "en.l32", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l32.e05', 'en', 'en.l32', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.hotel']::text[], 'fill_blank', 'lesson', 'I didn''t ___ my keys at the hotel. (find)', array['find']::text[], 'Après didn''t, le verbe reste à la forme de base : find, et non found. Le passé est déjà dans didn''t, comme il est dans did.', 2, '{"id": "en.l32.e05", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.hotel"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le verbe entre parenthèses, à la bonne forme.", "prompt": "I didn''t ___ my keys at the hotel. (find)", "promptLanguage": "en", "options": ["find", "found", "finded"], "answer": "find", "acceptedAnswers": ["find"], "hint": "Didn''t porte déjà le passé.", "explanation": "Après didn''t, le verbe reste à la forme de base : find, et non found. Le passé est déjà dans didn''t, comme il est dans did.", "tip": "didn''t + verbe de base : le passé du verbe ne sert plus.", "extraExample": {"text": "We didn''t see Anna at the beach.", "translation": "Nous n''avons pas vu Anna à la plage."}, "errorPatterns": [{"equals": "found", "category": "conjugation", "feedback": "Le passé est déjà porté par didn''t : le verbe garde sa forme de base, find."}, {"equals": "finded", "category": "conjugation", "feedback": "Après didn''t, on n''ajoute pas -ed : le verbe reste find."}], "pool": "lesson", "lessonId": "en.l32", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l32.e06', 'en', 'en.l32', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.trip']::text[], 'reorder', 'lesson', 'Qu''est-ce que tu as fait pendant ton voyage ?', array['What did you do on your trip']::text[], 'Avec un mot interrogatif, l''ordre est What + did + sujet + verbe de base. Le premier did est l''auxiliaire du passé, et do est le verbe « faire ».', 2, '{"id": "en.l32.e06", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.trip"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour poser la question.", "prompt": "Qu''est-ce que tu as fait pendant ton voyage ?", "promptLanguage": "fr", "tokens": ["What", "you", "did", "do", "on", "your", "trip"], "answer": "What did you do on your trip", "acceptedAnswers": ["What did you do on your trip"], "hint": "Mot interrogatif + did + sujet + verbe de base.", "explanation": "Avec un mot interrogatif, l''ordre est What + did + sujet + verbe de base. Le premier did est l''auxiliaire du passé, et do est le verbe « faire ».", "tip": "What did you do ? : did marque le passé, do veut dire « faire ».", "extraExample": {"text": "Where did you stay last week?", "translation": "Où as-tu séjourné la semaine dernière ?"}, "pool": "lesson", "lessonId": "en.l32", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l32.e07', 'en', 'en.l32', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.beach']::text[], 'translation', 'lesson', 'Est-ce que tu as aimé la plage ?', array['Did you like the beach','Did you enjoy the beach']::text[], 'Pour poser la question « est-ce que tu as aimé… ? » au passé, on utilise did + sujet + verbe de base : Did you like…? Like ne prend pas -ed, car did porte déjà le passé.', 2, '{"id": "en.l32.e07", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.beach"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Est-ce que tu as aimé la plage ?", "promptLanguage": "fr", "answer": "Did you like the beach", "acceptedAnswers": ["Did you like the beach", "Did you enjoy the beach"], "hint": "Une question au passé commence par did.", "explanation": "Pour poser la question « est-ce que tu as aimé… ? » au passé, on utilise did + sujet + verbe de base : Did you like…? Like ne prend pas -ed, car did porte déjà le passé.", "tip": "« Est-ce que tu as… ? » = Did you + verbe de base ?", "extraExample": {"text": "Did Tom like the hotel?", "translation": "Est-ce que Tom a aimé l''hôtel ?"}, "errorPatterns": [{"contains": "did you liked", "category": "conjugation", "feedback": "Après did, le verbe reste à la forme de base : Did you like…?"}, {"equals": "you liked the beach", "category": "word_order", "feedback": "Pour poser une question au passé, on commence par did : Did you like the beach ?"}, {"contains": "do you like", "category": "verb_tense", "feedback": "Do est le présent. Pour une question sur le passé, on utilise did."}], "pool": "lesson", "lessonId": "en.l32", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l32.e08', 'en', 'en.l32', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.weather']::text[], 'translation', 'lesson', 'Nous n''avons pas aimé la météo.', array['We didn''t like the weather','We didn''t enjoy the weather']::text[], 'Pour dire « nous n''avons pas aimé » au passé, on utilise didn''t + verbe de base : We didn''t like. Like ne prend pas -ed après didn''t. Weather est le temps qu''il fait.', 3, '{"id": "en.l32.e08", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.weather"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Nous n''avons pas aimé la météo.", "promptLanguage": "fr", "answer": "We didn''t like the weather", "acceptedAnswers": ["We didn''t like the weather", "We didn''t enjoy the weather"], "hint": "Didn''t + verbe de base. Le temps qu''il fait se dit weather.", "explanation": "Pour dire « nous n''avons pas aimé » au passé, on utilise didn''t + verbe de base : We didn''t like. Like ne prend pas -ed après didn''t. Weather est le temps qu''il fait.", "tip": "didn''t + base : We didn''t like, jamais We didn''t liked.", "extraExample": {"text": "Anna didn''t like the rain.", "translation": "Anna n''a pas aimé la pluie."}, "errorPatterns": [{"contains": "didn''t liked", "category": "conjugation", "feedback": "Après didn''t, le verbe reste à la forme de base : didn''t like."}, {"contains": "the time", "category": "word_confusion", "feedback": "Time est le temps qui passe ou l''heure. Le temps qu''il fait se dit weather."}, {"contains": "we don''t like", "category": "verb_tense", "feedback": "Don''t est le présent. Pour le passé, on utilise didn''t."}], "pool": "lesson", "lessonId": "en.l32", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l32.e09', 'en', 'en.l32', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.holiday']::text[], 'free_answer', 'lesson', 'Comment dit-on « Où es-tu allé en vacances ? » en anglais ?', array['Where did you go on holiday','Where did you go on your holiday','Where did you go for your holiday','Where did you go for your holidays','Where did you go on vacation','Where did you go on your vacation','Where did you go for your vacation']::text[], 'Avec where, l''ordre est Where + did + sujet + verbe de base. Go reste à la base (pas went), car le passé est déjà dans did. « En vacances » se dit on holiday.', 3, '{"id": "en.l32.e09", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.holiday"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la question en anglais.", "prompt": "Comment dit-on « Où es-tu allé en vacances ? » en anglais ?", "promptLanguage": "fr", "answer": "Where did you go on holiday", "acceptedAnswers": ["Where did you go on holiday", "Where did you go on your holiday", "Where did you go for your holiday", "Where did you go for your holidays", "Where did you go on vacation", "Where did you go on your vacation", "Where did you go for your vacation"], "hint": "Where + did + sujet + verbe de base. Quel est le verbe de base de « aller » ?", "explanation": "Avec where, l''ordre est Where + did + sujet + verbe de base. Go reste à la base (pas went), car le passé est déjà dans did. « En vacances » se dit on holiday.", "tip": "Where did you go ? : did porte le passé, go reste go.", "extraExample": {"text": "Where did Anna stay in London?", "translation": "Où Anna a-t-elle séjourné à Londres ?"}, "errorPatterns": [{"contains": "did you went", "category": "conjugation", "feedback": "Après did, le verbe reste à la forme de base : Where did you go ?"}, {"contains": "where you went", "category": "word_order", "feedback": "Une question au passé a besoin de did avant le sujet : Where did you go ?"}, {"contains": "in holiday", "category": "preposition", "feedback": "« En vacances » se dit on holiday, pas in holiday."}], "pool": "lesson", "lessonId": "en.l32", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l32.e10', 'en', 'en.l32', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.hotel']::text[], 'free_answer', 'lesson', 'Comment dit-on « Il n''a pas dormi à l''hôtel » en anglais ?', array['He didn''t sleep at the hotel','He didn''t sleep in the hotel']::text[], 'Pour la négation au passé, on utilise didn''t + verbe de base : He didn''t sleep. Le passé est déjà dans didn''t, donc on n''écrit pas slept. Il n''y a pas de -s avec he.', 3, '{"id": "en.l32.e10", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.hotel"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Il n''a pas dormi à l''hôtel » en anglais ?", "promptLanguage": "fr", "answer": "He didn''t sleep at the hotel", "acceptedAnswers": ["He didn''t sleep at the hotel", "He didn''t sleep in the hotel"], "hint": "Didn''t + verbe de base. Le passé de sleep n''est pas utilisé ici.", "explanation": "Pour la négation au passé, on utilise didn''t + verbe de base : He didn''t sleep. Le passé est déjà dans didn''t, donc on n''écrit pas slept. Il n''y a pas de -s avec he.", "tip": "didn''t + verbe de base, à toutes les personnes.", "extraExample": {"text": "She didn''t go to work yesterday.", "translation": "Elle n''est pas allée au travail hier."}, "errorPatterns": [{"contains": "didn''t slept", "category": "conjugation", "feedback": "Après didn''t, le verbe reste à la forme de base : didn''t sleep."}, {"contains": "doesn''t sleep", "category": "verb_tense", "feedback": "Doesn''t est le présent. Pour une action passée, on utilise didn''t."}, {"contains": "he not sleep", "category": "grammar", "feedback": "En anglais, on ne met pas not directement après le sujet : on utilise didn''t + verbe de base."}], "pool": "lesson", "lessonId": "en.l32", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l33.e01', 'en', 'en.l33', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.invite','en.v.party']::text[], 'mcq', 'lesson', 'Did you ___ Tom to the party?', array['invite']::text[], 'Après did, le verbe reste à la forme de base : invite. Le passé est déjà dans did, donc on n''ajoute ni -ed ni -s.', 1, '{"id": "en.l33.e01", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.invite", "en.v.party"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme du verbe.", "prompt": "Did you ___ Tom to the party?", "promptLanguage": "en", "options": ["invite", "invited", "invites"], "answer": "invite", "acceptedAnswers": ["invite"], "hint": "Did porte déjà le passé.", "explanation": "Après did, le verbe reste à la forme de base : invite. Le passé est déjà dans did, donc on n''ajoute ni -ed ni -s.", "tip": "Did + verbe de base : Did you invite…?", "extraExample": {"text": "Did Anna invite her parents?", "translation": "Est-ce qu''Anna a invité ses parents ?"}, "errorPatterns": [{"equals": "invited", "category": "conjugation", "feedback": "Le passé est déjà porté par did : après did, le verbe reste à la base, invite."}, {"equals": "invites", "category": "conjugation", "feedback": "Après did, il n''y a pas de -s : le verbe reste à la forme de base, invite."}], "pool": "lesson", "lessonId": "en.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l33.e02', 'en', 'en.l33', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.g20.was_were','en.v.party']::text[], 'mcq', 'lesson', '___ you at Anna''s party last night?', array['Were']::text[], 'Pour demander où quelqu''un était, on utilise to be : au passé, were avec you. Did s''utilise devant un verbe d''action (Did you go…?), pas devant to be.', 2, '{"id": "en.l33.e02", "unitIds": ["en.g23.past_simple_negative_questions", "en.g20.was_were", "en.v.party"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "___ you at Anna''s party last night?", "promptLanguage": "en", "options": ["Were", "Did", "Was"], "answer": "Were", "acceptedAnswers": ["Were"], "hint": "Il s''agit de dire où tu étais.", "explanation": "Pour demander où quelqu''un était, on utilise to be : au passé, were avec you. Did s''utilise devant un verbe d''action (Did you go…?), pas devant to be.", "tip": "Être quelque part → was / were ; faire une action → did.", "extraExample": {"text": "Was your brother at home last night?", "translation": "Ton frère était-il à la maison hier soir ?"}, "errorPatterns": [{"equals": "did", "category": "grammar", "feedback": "Did s''utilise avec un verbe d''action. Pour « être à un endroit », on garde to be : Were you…?"}, {"equals": "was", "category": "conjugation", "feedback": "Was s''utilise avec I, he, she et it. Avec you, le passé de to be est were."}], "pool": "lesson", "lessonId": "en.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l33.e03', 'en', 'en.l33', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.party','en.v.birthday','en.v.present','en.v.cake','en.v.invite']::text[], 'match', 'lesson', 'Le vocabulaire de la fête', '{}'::text[], 'Birthday est l''anniversaire de naissance : Happy birthday ! Present veut dire « cadeau » dans ce sens, pas « présent » comme dans le temps. Invite est le verbe : au passé, il devient invited.', 1, '{"id": "en.l33.e03", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.party", "en.v.birthday", "en.v.present", "en.v.cake", "en.v.invite"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot anglais à sa traduction.", "prompt": "Le vocabulaire de la fête", "promptLanguage": "fr", "pairs": [{"left": "party", "right": "fête"}, {"left": "birthday", "right": "anniversaire"}, {"left": "present", "right": "cadeau"}, {"left": "cake", "right": "gâteau"}, {"left": "invite", "right": "inviter"}], "answer": "party = fête ; birthday = anniversaire ; present = cadeau ; cake = gâteau ; invite = inviter", "acceptedAnswers": [], "explanation": "Birthday est l''anniversaire de naissance : Happy birthday ! Present veut dire « cadeau » dans ce sens, pas « présent » comme dans le temps. Invite est le verbe : au passé, il devient invited.", "tip": "Un cadeau = a present ; l''anniversaire de naissance = birthday.", "extraExample": {"text": "a birthday cake", "translation": "un gâteau d''anniversaire"}, "pool": "lesson", "lessonId": "en.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l33.e04', 'en', 'en.l33', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.g23.past_simple_negative_questions','en.v.invite']::text[], 'fill_blank', 'lesson', 'Lucy ___ me to her birthday party last week. (invite)', array['invited']::text[], 'Ici, il n''y a pas de did : le verbe est au passé simple. Invite finit déjà par un e, donc on ajoute seulement -d : invited, avec une syllabe en plus (/ɪnˈvaɪtɪd/) car le verbe se termine par t.', 2, '{"id": "en.l33.e04", "unitIds": ["en.g21.past_simple_regular", "en.g23.past_simple_negative_questions", "en.v.invite"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le passé du verbe entre parenthèses.", "prompt": "Lucy ___ me to her birthday party last week. (invite)", "promptLanguage": "en", "options": ["invited", "invite", "invites"], "answer": "invited", "acceptedAnswers": ["invited"], "hint": "Last week : l''action est terminée.", "explanation": "Ici, il n''y a pas de did : le verbe est au passé simple. Invite finit déjà par un e, donc on ajoute seulement -d : invited, avec une syllabe en plus (/ɪnˈvaɪtɪd/) car le verbe se termine par t.", "tip": "Question ou négation → did + base. Phrase simple au passé → verbe + -ed.", "extraExample": {"text": "Tom invited his friends to dinner.", "translation": "Tom a invité ses amis à dîner."}, "errorPatterns": [{"equals": "invite", "category": "verb_tense", "feedback": "Invite est le présent. Avec last week, la phrase est au passé : invited."}, {"equals": "invites", "category": "verb_tense", "feedback": "Le -s est réservé au présent. Au passé, tous les sujets prennent -ed : invited."}], "pool": "lesson", "lessonId": "en.l33", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l33.e05', 'en', 'en.l33', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.cake']::text[], 'fill_blank', 'lesson', 'Tom didn''t ___ the cake. He wasn''t hungry. (eat)', array['eat']::text[], 'Après didn''t, le verbe reste à la forme de base : eat, et non ate. Dans la phrase suivante, wasn''t est le passé de to be : to be n''a pas besoin de did.', 2, '{"id": "en.l33.e05", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.cake"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le verbe entre parenthèses, à la bonne forme.", "prompt": "Tom didn''t ___ the cake. He wasn''t hungry. (eat)", "promptLanguage": "en", "options": ["eat", "ate", "eaten"], "answer": "eat", "acceptedAnswers": ["eat"], "hint": "Didn''t porte déjà le passé.", "explanation": "Après didn''t, le verbe reste à la forme de base : eat, et non ate. Dans la phrase suivante, wasn''t est le passé de to be : to be n''a pas besoin de did.", "tip": "didn''t + base ; mais to be fait wasn''t / weren''t tout seul.", "extraExample": {"text": "Anna didn''t eat fish last night.", "translation": "Anna n''a pas mangé de poisson hier soir."}, "errorPatterns": [{"equals": "ate", "category": "conjugation", "feedback": "Le passé est déjà porté par didn''t : le verbe garde sa forme de base, eat."}, {"equals": "eaten", "category": "conjugation", "feedback": "Eaten est un participe passé. Après didn''t, on utilise la forme de base : eat."}], "pool": "lesson", "lessonId": "en.l33", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l33.e06', 'en', 'en.l33', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.present']::text[], 'reorder', 'lesson', 'Est-ce que tu as acheté un cadeau pour Anna ?', array['Did you buy a present for Anna']::text[], 'Question au passé : Did + sujet + verbe de base. Buy reste à la forme de base (pas bought), car did porte déjà le passé. For Anna veut dire « pour Anna ».', 2, '{"id": "en.l33.e06", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.present"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour poser la question.", "prompt": "Est-ce que tu as acheté un cadeau pour Anna ?", "promptLanguage": "fr", "tokens": ["present", "Did", "for", "you", "a", "Anna", "buy"], "answer": "Did you buy a present for Anna", "acceptedAnswers": ["Did you buy a present for Anna"], "hint": "La question commence par did. Le verbe suit le sujet, à la forme de base.", "explanation": "Question au passé : Did + sujet + verbe de base. Buy reste à la forme de base (pas bought), car did porte déjà le passé. For Anna veut dire « pour Anna ».", "tip": "Did + you + base : Did you buy…?", "extraExample": {"text": "Did Tom buy a cake?", "translation": "Est-ce que Tom a acheté un gâteau ?"}, "pool": "lesson", "lessonId": "en.l33", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l33.e07', 'en', 'en.l33', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.birthday','en.v.forget']::text[], 'translation', 'lesson', 'Il a oublié mon anniversaire.', array['He forgot my birthday']::text[], '« A oublié » se traduit par forgot, le passé irrégulier de forget, sans auxiliaire. Dans une phrase simple au passé, pas de did : did ne sert que pour les questions et les négations.', 2, '{"id": "en.l33.e07", "unitIds": ["en.g22.irregular_verbs", "en.v.birthday", "en.v.forget"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Il a oublié mon anniversaire.", "promptLanguage": "fr", "answer": "He forgot my birthday", "acceptedAnswers": ["He forgot my birthday"], "hint": "Forget est irrégulier. Pas d''auxiliaire en anglais.", "explanation": "« A oublié » se traduit par forgot, le passé irrégulier de forget, sans auxiliaire. Dans une phrase simple au passé, pas de did : did ne sert que pour les questions et les négations.", "tip": "Phrase simple au passé : pas de did, juste le verbe au passé.", "extraExample": {"text": "I forgot Anna''s present at home.", "translation": "J''ai oublié le cadeau d''Anna à la maison."}, "errorPatterns": [{"contains": "forgetted", "category": "conjugation", "feedback": "Forget est irrégulier : on n''ajoute pas -ed. Son passé est forgot."}, {"contains": "he forget my", "category": "verb_tense", "feedback": "Forget est le présent. Pour une action finie, on dit forgot."}, {"contains": "did forgot", "category": "grammar", "feedback": "Did n''est pas utilisé dans une phrase simple : dis directement He forgot."}], "pool": "lesson", "lessonId": "en.l33", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l33.e08', 'en', 'en.l33', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.invite','en.v.party']::text[], 'translation', 'lesson', 'Est-ce que tu as invité Anna à la fête ?', array['Did you invite Anna to the party','Did you invite Anna to your party']::text[], 'Pour une question au passé, on utilise did + sujet + verbe de base : Did you invite…? Invite reste à la base. On invite quelqu''un to (à) un événement : to the party.', 3, '{"id": "en.l33.e08", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.invite", "en.v.party"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Est-ce que tu as invité Anna à la fête ?", "promptLanguage": "fr", "answer": "Did you invite Anna to the party", "acceptedAnswers": ["Did you invite Anna to the party", "Did you invite Anna to your party"], "hint": "Did + sujet + verbe de base. Quelle préposition après invite ?", "explanation": "Pour une question au passé, on utilise did + sujet + verbe de base : Did you invite…? Invite reste à la base. On invite quelqu''un to (à) un événement : to the party.", "tip": "Invite quelqu''un to + événement : to the party, to dinner.", "extraExample": {"text": "Did Tom invite you to dinner?", "translation": "Est-ce que Tom t''a invité à dîner ?"}, "errorPatterns": [{"contains": "did you invited", "category": "conjugation", "feedback": "Après did, le verbe reste à la forme de base : Did you invite…?"}, {"equals": "you invited anna to the party", "category": "word_order", "feedback": "Pour poser la question, on commence par did : Did you invite Anna to the party ?"}, {"contains": "anna at the party", "category": "preposition", "feedback": "Après invite quelqu''un, on utilise to : invite Anna to the party."}], "pool": "lesson", "lessonId": "en.l33", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l33.e09', 'en', 'en.l33', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.party']::text[], 'free_answer', 'lesson', 'Comment dit-on « Qu''est-ce que tu as mangé à la fête ? » en anglais ?', array['What did you eat at the party','What did you have at the party']::text[], 'Avec un mot interrogatif, l''ordre est What + did + sujet + verbe de base. Eat reste à la base (pas ate), car did porte déjà le passé.', 3, '{"id": "en.l33.e09", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.party"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la question en anglais.", "prompt": "Comment dit-on « Qu''est-ce que tu as mangé à la fête ? » en anglais ?", "promptLanguage": "fr", "answer": "What did you eat at the party", "acceptedAnswers": ["What did you eat at the party", "What did you have at the party"], "hint": "What + did + sujet + verbe de base.", "explanation": "Avec un mot interrogatif, l''ordre est What + did + sujet + verbe de base. Eat reste à la base (pas ate), car did porte déjà le passé.", "tip": "What did you + verbe de base ? : did marque le passé.", "extraExample": {"text": "What did Anna buy for the party?", "translation": "Qu''est-ce qu''Anna a acheté pour la fête ?"}, "errorPatterns": [{"contains": "did you ate", "category": "conjugation", "feedback": "Après did, le verbe reste à la forme de base : What did you eat ?"}, {"contains": "what you ate", "category": "word_order", "feedback": "Une question au passé a besoin de did avant le sujet : What did you eat ?"}, {"contains": "did you eaten", "category": "conjugation", "feedback": "Eaten est un participe passé. Après did, on utilise la forme de base : eat."}], "pool": "lesson", "lessonId": "en.l33", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l33.e10', 'en', 'en.l33', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.cake']::text[], 'free_answer', 'lesson', 'Comment dit-on « Nous avons mangé du gâteau et nous avons chanté » en anglais ?', array['We ate cake and sang','We ate cake and we sang','We ate some cake and sang','We ate some cake and we sang','We had cake and sang','We had cake and we sang','We had some cake and sang','We had some cake and we sang']::text[], 'Eat et sing sont irréguliers : eat → ate, sing → sang. Phrase simple au passé : pas de did. Cake sans article veut dire « du gâteau ». Quand le sujet est le même, on peut ne pas le répéter après and.', 3, '{"id": "en.l33.e10", "unitIds": ["en.g22.irregular_verbs", "en.v.cake"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Nous avons mangé du gâteau et nous avons chanté » en anglais ?", "promptLanguage": "fr", "answer": "We ate cake and sang", "acceptedAnswers": ["We ate cake and sang", "We ate cake and we sang", "We ate some cake and sang", "We ate some cake and we sang", "We had cake and sang", "We had cake and we sang", "We had some cake and sang", "We had some cake and we sang"], "hint": "Deux verbes irréguliers : eat et sing.", "explanation": "Eat et sing sont irréguliers : eat → ate, sing → sang. Phrase simple au passé : pas de did. Cake sans article veut dire « du gâteau ». Quand le sujet est le même, on peut ne pas le répéter après and.", "tip": "sing → sang, drink → drank, swim → swam : le i devient a.", "extraExample": {"text": "They danced and sang all night.", "translation": "Ils ont dansé et chanté toute la nuit."}, "errorPatterns": [{"contains": "singed", "category": "conjugation", "feedback": "Sing est irrégulier : on n''ajoute pas -ed. Son passé est sang."}, {"contains": "sung", "category": "conjugation", "feedback": "Sung est le participe passé de sing. Pour le passé simple, on dit sang."}, {"contains": "eated", "category": "conjugation", "feedback": "Eat est irrégulier : on n''ajoute pas -ed. Son passé est ate."}], "pool": "lesson", "lessonId": "en.l33", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l34.e01', 'en', 'en.l34', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.feel','en.v.party']::text[], 'mcq', 'lesson', 'Did you ___ tired after the party?', array['feel']::text[], 'Après did, le verbe reste à la forme de base : feel, même s''il est irrégulier (felt). Le passé est déjà dans did.', 1, '{"id": "en.l34.e01", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.feel", "en.v.party"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme du verbe.", "prompt": "Did you ___ tired after the party?", "promptLanguage": "en", "options": ["feel", "felt", "feeled"], "answer": "feel", "acceptedAnswers": ["feel"], "hint": "Did porte déjà le passé.", "explanation": "Après did, le verbe reste à la forme de base : feel, même s''il est irrégulier (felt). Le passé est déjà dans did.", "tip": "Did + base, même pour un verbe irrégulier : Did you feel…? et non Did you felt…?", "extraExample": {"text": "Did Tom feel cold at the beach?", "translation": "Est-ce que Tom a eu froid à la plage ?"}, "errorPatterns": [{"equals": "felt", "category": "conjugation", "feedback": "Le passé est déjà porté par did : le verbe garde sa forme de base, feel."}, {"equals": "feeled", "category": "conjugation", "feedback": "Feel est irrégulier, et après did on utilise de toute façon la base : feel."}], "pool": "lesson", "lessonId": "en.l34", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l34.e02', 'en', 'en.l34', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.lose']::text[], 'mcq', 'lesson', 'Tom ___ his bag at the gym yesterday.', array['lost']::text[], 'Lose est irrégulier : son passé est lost (/lɒst/), sans -ed. Dans une phrase simple au passé, il n''y a pas de did : on met directement le verbe au passé.', 1, '{"id": "en.l34.e02", "unitIds": ["en.g22.irregular_verbs", "en.v.lose"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme du verbe.", "prompt": "Tom ___ his bag at the gym yesterday.", "promptLanguage": "en", "options": ["lost", "losed", "lose"], "answer": "lost", "acceptedAnswers": ["lost"], "hint": "Lose est un verbe irrégulier.", "explanation": "Lose est irrégulier : son passé est lost (/lɒst/), sans -ed. Dans une phrase simple au passé, il n''y a pas de did : on met directement le verbe au passé.", "tip": "Lose → lost : « perdre » au passé.", "extraExample": {"text": "Sam lost his phone at the party.", "translation": "Sam a perdu son téléphone à la fête."}, "errorPatterns": [{"equals": "losed", "category": "conjugation", "feedback": "Lose est irrégulier : on n''ajoute pas -ed. Son passé est lost."}, {"equals": "lose", "category": "verb_tense", "feedback": "Lose est le présent. Avec yesterday, on utilise le passé : lost."}], "pool": "lesson", "lessonId": "en.l34", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l34.e03', 'en', 'en.l34', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.story','en.v.happen','en.v.lose','en.v.win','en.v.feel']::text[], 'match', 'lesson', 'Raconter une histoire au passé', '{}'::text[], 'Après did ou didn''t, le verbe reste à la base (win, lose). Sans did, on utilise le passé : felt est le passé irrégulier de feel, et happened est le passé régulier de happen. Attention : won se prononce /wʌn/, comme one.', 1, '{"id": "en.l34.e03", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.story", "en.v.happen", "en.v.lose", "en.v.win", "en.v.feel"], "type": "match", "difficulty": 1, "instruction": "Associe chaque phrase anglaise à sa traduction.", "prompt": "Raconter une histoire au passé", "promptLanguage": "fr", "pairs": [{"left": "Did you win?", "right": "Tu as gagné ?"}, {"left": "I didn''t lose it", "right": "Je ne l''ai pas perdu"}, {"left": "What happened?", "right": "Qu''est-ce qui s''est passé ?"}, {"left": "He felt happy", "right": "Il s''est senti heureux"}, {"left": "a story", "right": "une histoire"}], "answer": "Did you win? = Tu as gagné ? ; I didn''t lose it = Je ne l''ai pas perdu ; What happened? = Qu''est-ce qui s''est passé ? ; He felt happy = Il s''est senti heureux ; a story = une histoire", "acceptedAnswers": [], "explanation": "Après did ou didn''t, le verbe reste à la base (win, lose). Sans did, on utilise le passé : felt est le passé irrégulier de feel, et happened est le passé régulier de happen. Attention : won se prononce /wʌn/, comme one.", "tip": "Avec did / didn''t : la base. Sans did : le verbe au passé.", "extraExample": {"text": "Tom won a present.", "translation": "Tom a gagné un cadeau."}, "pool": "lesson", "lessonId": "en.l34", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l34.e04', 'en', 'en.l34', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.win']::text[], 'fill_blank', 'lesson', 'Anna didn''t ___ a present at the party. (win)', array['win']::text[], 'Après didn''t, le verbe reste à la forme de base : win, et non won. Le passé est déjà dans didn''t.', 2, '{"id": "en.l34.e04", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.win"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le verbe entre parenthèses, à la bonne forme.", "prompt": "Anna didn''t ___ a present at the party. (win)", "promptLanguage": "en", "options": ["win", "won", "winned"], "answer": "win", "acceptedAnswers": ["win"], "hint": "Didn''t porte déjà le passé.", "explanation": "Après didn''t, le verbe reste à la forme de base : win, et non won. Le passé est déjà dans didn''t.", "tip": "didn''t + base : même pour un verbe irrégulier comme win.", "extraExample": {"text": "Sam didn''t win the cake.", "translation": "Sam n''a pas gagné le gâteau."}, "errorPatterns": [{"equals": "won", "category": "conjugation", "feedback": "Le passé est déjà porté par didn''t : le verbe garde sa forme de base, win."}, {"equals": "winned", "category": "conjugation", "feedback": "Win est irrégulier, et après didn''t on utilise de toute façon la base : win."}], "pool": "lesson", "lessonId": "en.l34", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l34.e05', 'en', 'en.l34', 'en.g20.was_were', array['en.g20.was_were','en.g23.past_simple_negative_questions']::text[], 'fill_blank', 'lesson', 'Anna ___ at the party last night, but her brother wasn''t.', array['was']::text[], 'Anna correspond à she : avec she, le passé de to be est was. Le verbe to be n''utilise pas did : il fait seul was / were et wasn''t / weren''t.', 2, '{"id": "en.l34.e05", "unitIds": ["en.g20.was_were", "en.g23.past_simple_negative_questions"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Anna ___ at the party last night, but her brother wasn''t.", "promptLanguage": "en", "options": ["was", "were", "did"], "answer": "was", "acceptedAnswers": ["was"], "hint": "Anna = she. Il s''agit d''être quelque part.", "explanation": "Anna correspond à she : avec she, le passé de to be est was. Le verbe to be n''utilise pas did : il fait seul was / were et wasn''t / weren''t.", "tip": "Être → was / were (pas de did) ; les autres verbes → did.", "extraExample": {"text": "We were at the beach, but Tom wasn''t.", "translation": "Nous étions à la plage, mais Tom n''y était pas."}, "errorPatterns": [{"equals": "were", "category": "conjugation", "feedback": "Were s''utilise avec you, we et they. Anna = she : on dit was."}, {"equals": "did", "category": "grammar", "feedback": "Did s''utilise avec un verbe d''action. Pour dire où quelqu''un était, on utilise was."}], "pool": "lesson", "lessonId": "en.l34", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l34.e06', 'en', 'en.l34', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.story','en.v.tell']::text[], 'reorder', 'lesson', 'Est-ce que Tom t''a raconté l''histoire ?', array['Did Tom tell you the story']::text[], 'Question au passé : Did + sujet + verbe de base. Tell reste à la base (pas told), car did porte déjà le passé. Après tell, on met la personne (you), puis la chose racontée (the story).', 2, '{"id": "en.l34.e06", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.story", "en.v.tell"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour poser la question.", "prompt": "Est-ce que Tom t''a raconté l''histoire ?", "promptLanguage": "fr", "tokens": ["story", "Did", "you", "the", "tell", "Tom"], "answer": "Did Tom tell you the story", "acceptedAnswers": ["Did Tom tell you the story"], "hint": "Did + sujet + verbe de base, puis la personne, puis ce qu''on raconte.", "explanation": "Question au passé : Did + sujet + verbe de base. Tell reste à la base (pas told), car did porte déjà le passé. Après tell, on met la personne (you), puis la chose racontée (the story).", "tip": "Did + sujet + base : Did Tom tell…?", "extraExample": {"text": "Did your mother tell you a story?", "translation": "Ta mère t''a-t-elle raconté une histoire ?"}, "pool": "lesson", "lessonId": "en.l34", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l34.e07', 'en', 'en.l34', 'en.g22.irregular_verbs', array['en.g22.irregular_verbs','en.v.party','en.v.birthday']::text[], 'translation', 'lesson', 'Hier soir, nous sommes allés à la fête d''anniversaire de Tom.', array['Last night we went to Tom''s birthday party','We went to Tom''s birthday party last night','Yesterday evening we went to Tom''s birthday party','We went to Tom''s birthday party yesterday evening']::text[], '« Sommes allés » se traduit par went, le passé irrégulier de go. Dans une phrase simple affirmative, on n''utilise pas did. Pour « la fête de Tom », on met le possesseur d''abord : Tom''s birthday party.', 2, '{"id": "en.l34.e07", "unitIds": ["en.g22.irregular_verbs", "en.v.party", "en.v.birthday"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Hier soir, nous sommes allés à la fête d''anniversaire de Tom.", "promptLanguage": "fr", "answer": "Last night we went to Tom''s birthday party", "acceptedAnswers": ["Last night we went to Tom''s birthday party", "We went to Tom''s birthday party last night", "Yesterday evening we went to Tom''s birthday party", "We went to Tom''s birthday party yesterday evening"], "hint": "Phrase simple au passé : pas de did. Quel est le passé de go ?", "explanation": "« Sommes allés » se traduit par went, le passé irrégulier de go. Dans une phrase simple affirmative, on n''utilise pas did. Pour « la fête de Tom », on met le possesseur d''abord : Tom''s birthday party.", "tip": "Phrase simple au passé : le verbe au passé, sans did.", "extraExample": {"text": "We went to Anna''s party last week.", "translation": "Nous sommes allés à la fête d''Anna la semaine dernière."}, "errorPatterns": [{"contains": "goed", "category": "conjugation", "feedback": "Go est irrégulier : son passé est went, sans -ed."}, {"contains": "we go to", "category": "verb_tense", "feedback": "Go est le présent. Hier soir, l''action est terminée : we went."}, {"contains": "we did go", "category": "grammar", "feedback": "Did n''est pas utilisé dans une phrase simple : dis directement we went."}], "pool": "lesson", "lessonId": "en.l34", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l34.e08', 'en', 'en.l34', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.find']::text[], 'translation', 'lesson', 'Tom n''a pas trouvé ses clés hier.', array['Tom didn''t find his keys yesterday','Yesterday Tom didn''t find his keys']::text[], 'La négation au passé se fait avec didn''t + verbe de base : Tom didn''t find. Le passé est déjà dans didn''t, donc on n''écrit pas found.', 3, '{"id": "en.l34.e08", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.find"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Tom n''a pas trouvé ses clés hier.", "promptLanguage": "fr", "answer": "Tom didn''t find his keys yesterday", "acceptedAnswers": ["Tom didn''t find his keys yesterday", "Yesterday Tom didn''t find his keys"], "hint": "Didn''t + verbe de base.", "explanation": "La négation au passé se fait avec didn''t + verbe de base : Tom didn''t find. Le passé est déjà dans didn''t, donc on n''écrit pas found.", "tip": "didn''t + base : find reste find.", "extraExample": {"text": "Anna didn''t forget the present.", "translation": "Anna n''a pas oublié le cadeau."}, "errorPatterns": [{"contains": "didn''t found", "category": "conjugation", "feedback": "Après didn''t, le verbe reste à la forme de base : didn''t find."}, {"contains": "didn''t finded", "category": "conjugation", "feedback": "Après didn''t, on n''ajoute pas -ed : didn''t find."}, {"contains": "tom not found", "category": "grammar", "feedback": "En anglais, on ne met pas not directement après le sujet : on utilise didn''t + verbe de base."}], "pool": "lesson", "lessonId": "en.l34", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l34.e09', 'en', 'en.l34', 'en.g21.past_simple_regular', array['en.g21.past_simple_regular','en.v.happen']::text[], 'free_answer', 'lesson', 'Comment dit-on « Qu''est-ce qui s''est passé hier ? » en anglais ?', array['What happened yesterday']::text[], 'Happen est régulier : happened. Dans What happened ?, le mot what est lui-même le sujet (c''est ce qui se passe) : on n''utilise pas did. On utilise did quand le sujet vient après, comme dans What did you do ?', 3, '{"id": "en.l34.e09", "unitIds": ["en.g21.past_simple_regular", "en.v.happen"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la question en anglais.", "prompt": "Comment dit-on « Qu''est-ce qui s''est passé hier ? » en anglais ?", "promptLanguage": "fr", "answer": "What happened yesterday", "acceptedAnswers": ["What happened yesterday"], "hint": "Happen est un verbe régulier. Ici, what est le sujet de la question.", "explanation": "Happen est régulier : happened. Dans What happened ?, le mot what est lui-même le sujet (c''est ce qui se passe) : on n''utilise pas did. On utilise did quand le sujet vient après, comme dans What did you do ?", "tip": "What happened ? : pas de did quand what est le sujet.", "extraExample": {"text": "What happened at the party?", "translation": "Qu''est-ce qui s''est passé à la fête ?"}, "errorPatterns": [{"contains": "what did happen", "category": "grammar", "feedback": "On dit simplement What happened ? : what est le sujet, donc pas de did."}, {"equals": "what happen yesterday", "category": "verb_tense", "feedback": "Happen est la forme de base. Hier, l''action est terminée : What happened ?"}, {"contains": "was happened", "category": "grammar", "feedback": "Pas de was devant happened : le verbe happened exprime déjà le passé."}], "pool": "lesson", "lessonId": "en.l34", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l34.e10', 'en', 'en.l34', 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.lose']::text[], 'free_answer', 'lesson', 'Comment dit-on « Où as-tu perdu tes clés ? » en anglais ?', array['Where did you lose your keys']::text[], 'Avec where, l''ordre est Where + did + sujet + verbe de base. Lose reste à la base (pas lost), car le passé est déjà porté par did.', 3, '{"id": "en.l34.e10", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.lose"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la question en anglais.", "prompt": "Comment dit-on « Où as-tu perdu tes clés ? » en anglais ?", "promptLanguage": "fr", "answer": "Where did you lose your keys", "acceptedAnswers": ["Where did you lose your keys"], "hint": "Where + did + sujet + verbe de base.", "explanation": "Avec where, l''ordre est Where + did + sujet + verbe de base. Lose reste à la base (pas lost), car le passé est déjà porté par did.", "tip": "Did porte le passé : lose reste lose.", "extraExample": {"text": "Where did Tom find his bag?", "translation": "Où Tom a-t-il trouvé son sac ?"}, "errorPatterns": [{"contains": "did you lost", "category": "conjugation", "feedback": "Après did, le verbe reste à la forme de base : Where did you lose…?"}, {"contains": "where you lost", "category": "word_order", "feedback": "Une question au passé a besoin de did avant le sujet : Where did you lose…?"}, {"contains": "loose", "category": "spelling", "feedback": "Loose veut dire « lâche ». « Perdre » s''écrit lose, avec un seul o."}], "pool": "lesson", "lessonId": "en.l34", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l35.e01', 'en', 'en.l35', 'en.g24.will_future', array['en.g24.will_future','en.v.later']::text[], 'mcq', 'lesson', 'Anna ___ you later.', array['will call']::text[], 'Pour parler du futur, on met will avant le verbe de base : will call. Will ne prend jamais de -s, même avec Anna (she), et il n''est pas suivi de to.', 1, '{"id": "en.l35.e01", "unitIds": ["en.g24.will_future", "en.v.later"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Anna ___ you later.", "promptLanguage": "en", "options": ["will call", "wills call", "will to call", "will calls"], "answer": "will call", "acceptedAnswers": ["will call"], "hint": "Will est suivi directement du verbe, tel qu''on le trouve dans le dictionnaire.", "explanation": "Pour parler du futur, on met will avant le verbe de base : will call. Will ne prend jamais de -s, même avec Anna (she), et il n''est pas suivi de to.", "tip": "Will + verbe de base, toujours : pas de -s, pas de to.", "extraExample": {"text": "Tom will help you later.", "translation": "Tom t''aidera plus tard."}, "errorPatterns": [{"equals": "wills call", "category": "conjugation", "feedback": "Will ne prend jamais de -s, même avec he, she ou un prénom. On dit Anna will call."}, {"equals": "will to call", "category": "grammar", "feedback": "Après will, on ne met pas to : le verbe suit directement, will call."}, {"equals": "will calls", "category": "conjugation", "feedback": "Après will, le verbe reste à sa forme de base : pas de -s. On dit will call."}], "pool": "lesson", "lessonId": "en.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l35.e02', 'en', 'en.l35', 'en.g24.will_future', array['en.g24.will_future','en.v.tomorrow']::text[], 'mcq', 'lesson', 'Comment dit-on « Tu viendras demain ? » en anglais ?', array['Will you come tomorrow?']::text[], 'Avec will, on fait la question en mettant will avant le sujet : Will you come…? On n''ajoute ni do ni are, et le verbe reste à la forme de base, sans to.', 2, '{"id": "en.l35.e02", "unitIds": ["en.g24.will_future", "en.v.tomorrow"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne question.", "prompt": "Comment dit-on « Tu viendras demain ? » en anglais ?", "promptLanguage": "fr", "options": ["Will you come tomorrow?", "Do you will come tomorrow?", "Will you to come tomorrow?", "Are you will come tomorrow?"], "answer": "Will you come tomorrow?", "acceptedAnswers": ["Will you come tomorrow?"], "hint": "Pour poser la question, will passe avant le sujet. Il n''y a pas de do.", "explanation": "Avec will, on fait la question en mettant will avant le sujet : Will you come…? On n''ajoute ni do ni are, et le verbe reste à la forme de base, sans to.", "tip": "Question au futur : Will + sujet + verbe de base.", "extraExample": {"text": "Will Anna call you later?", "translation": "Est-ce qu''Anna t''appellera plus tard ?"}, "errorPatterns": [{"equals": "do you will come tomorrow", "category": "grammar", "feedback": "Will remplace déjà do : on ne les met pas ensemble. On dit Will you come tomorrow ?"}, {"equals": "will you to come tomorrow", "category": "grammar", "feedback": "Après le sujet, le verbe est à la forme de base, sans to : Will you come ?"}, {"equals": "are you will come tomorrow", "category": "grammar", "feedback": "Are n''a rien à faire avec will. Pour la question, on met will avant le sujet : Will you come ?"}], "pool": "lesson", "lessonId": "en.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l35.e03', 'en', 'en.l35', 'en.g24.will_future', array['en.g24.will_future','en.v.tomorrow','en.v.next','en.v.soon','en.v.later','en.v.maybe']::text[], 'match', 'lesson', 'Les mots du futur : tomorrow, next week, soon, later, maybe', '{}'::text[], 'Ces mots situent une action dans le futur. Next veut dire « prochain » et s''emploie sans the : next week. Maybe exprime le doute : ce n''est pas sûr.', 1, '{"id": "en.l35.e03", "unitIds": ["en.g24.will_future", "en.v.tomorrow", "en.v.next", "en.v.soon", "en.v.later", "en.v.maybe"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les mots du futur : tomorrow, next week, soon, later, maybe", "promptLanguage": "fr", "pairs": [{"left": "tomorrow", "right": "demain"}, {"left": "next week", "right": "la semaine prochaine"}, {"left": "soon", "right": "bientôt"}, {"left": "later", "right": "plus tard"}, {"left": "maybe", "right": "peut-être"}], "answer": "tomorrow = demain ; next week = la semaine prochaine ; soon = bientôt ; later = plus tard ; maybe = peut-être", "acceptedAnswers": [], "explanation": "Ces mots situent une action dans le futur. Next veut dire « prochain » et s''emploie sans the : next week. Maybe exprime le doute : ce n''est pas sûr.", "tip": "Next + période, sans the : next week, next weekend.", "extraExample": {"text": "I''ll see you tomorrow.", "translation": "Je te verrai demain."}, "pool": "lesson", "lessonId": "en.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l35.e04', 'en', 'en.l35', 'en.g24.will_future', array['en.g24.will_future']::text[], 'fill_blank', 'lesson', 'Don''t worry. Tom ___ be late.', array['won''t','will not']::text[], 'Won''t est la forme courte de will not. Tom won''t be late veut dire « Tom ne sera pas en retard » : on rassure quelqu''un sur le futur.', 2, '{"id": "en.l35.e04", "unitIds": ["en.g24.will_future"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "Don''t worry. Tom ___ be late.", "promptLanguage": "en", "options": ["won''t", "doesn''t", "isn''t", "not"], "answer": "won''t", "acceptedAnswers": ["won''t", "will not"], "hint": "Ce petit mot exprime à la fois le futur et la négation.", "explanation": "Won''t est la forme courte de will not. Tom won''t be late veut dire « Tom ne sera pas en retard » : on rassure quelqu''un sur le futur.", "tip": "Won''t = will not : on le met avant le verbe de base.", "extraExample": {"text": "We won''t forget your birthday.", "translation": "Nous n''oublierons pas ton anniversaire."}, "errorPatterns": [{"equals": "does not", "category": "grammar", "feedback": "Doesn''t sert au présent simple, et on ne l''emploie pas devant be. Pour le futur négatif, on dit won''t."}, {"equals": "is not", "category": "grammar", "feedback": "Isn''t ne peut pas être suivi de be. Pour dire « ne sera pas », on utilise won''t be."}, {"equals": "not", "category": "grammar", "feedback": "Not seul ne suffit pas : il faut will not, ou plus simplement won''t."}], "pool": "lesson", "lessonId": "en.l35", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l35.e05', 'en', 'en.l35', 'en.g24.will_future', array['en.g24.will_future','en.v.maybe','en.v.later']::text[], 'fill_blank', 'lesson', 'Maybe it ___ rain later.', array['will','''ll']::text[], 'Pour une prédiction sur le futur, on utilise will + verbe de base : it will rain. Maybe montre seulement qu''on n''est pas sûr.', 2, '{"id": "en.l35.e05", "unitIds": ["en.g24.will_future", "en.v.maybe", "en.v.later"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot pour parler du futur.", "prompt": "Maybe it ___ rain later.", "promptLanguage": "en", "options": ["will", "wills", "to", "is"], "answer": "will", "acceptedAnswers": ["will", "''ll"], "hint": "On ne sait pas encore s''il va pleuvoir : on fait une prédiction.", "explanation": "Pour une prédiction sur le futur, on utilise will + verbe de base : it will rain. Maybe montre seulement qu''on n''est pas sûr.", "tip": "Une prédiction se fait avec will + verbe de base.", "extraExample": {"text": "Maybe Sam will come to the party.", "translation": "Peut-être que Sam viendra à la fête."}, "errorPatterns": [{"equals": "wills", "category": "conjugation", "feedback": "Will ne prend jamais de -s, même avec it. On dit it will rain."}, {"equals": "to", "category": "grammar", "feedback": "To ne marque pas le futur ici. Il faut l''auxiliaire will devant rain."}, {"equals": "is", "category": "verb_tense", "feedback": "It is rain n''existe pas : is n''est pas suivi du verbe de base. Pour le futur, on met will."}], "pool": "lesson", "lessonId": "en.l35", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l35.e06', 'en', 'en.l35', 'en.g24.will_future', array['en.g24.will_future','en.v.tomorrow']::text[], 'reorder', 'lesson', 'Nous ne partirons pas demain matin.', array['We won''t leave tomorrow morning','Tomorrow morning we won''t leave']::text[], 'On met won''t entre le sujet et le verbe de base : We won''t leave. Le moment (tomorrow morning) se place à la fin, ou au début de la phrase.', 2, '{"id": "en.l35.e06", "unitIds": ["en.g24.will_future", "en.v.tomorrow"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Nous ne partirons pas demain matin.", "promptLanguage": "fr", "tokens": ["tomorrow", "We", "leave", "morning", "won''t"], "answer": "We won''t leave tomorrow morning", "acceptedAnswers": ["We won''t leave tomorrow morning", "Tomorrow morning we won''t leave"], "hint": "Won''t se place juste après le sujet, avant le verbe.", "explanation": "On met won''t entre le sujet et le verbe de base : We won''t leave. Le moment (tomorrow morning) se place à la fin, ou au début de la phrase.", "tip": "Sujet + won''t + verbe de base : le verbe ne change jamais.", "extraExample": {"text": "They won''t arrive tonight.", "translation": "Ils n''arriveront pas ce soir."}, "pool": "lesson", "lessonId": "en.l35", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l35.e07', 'en', 'en.l35', 'en.g24.will_future', array['en.g24.will_future','en.v.tomorrow']::text[], 'translation', 'lesson', 'Il pleuvra demain.', array['It will rain tomorrow','Tomorrow it will rain','It will be rainy tomorrow','It is going to rain tomorrow','Tomorrow it is going to rain']::text[], 'Pour une prédiction, on met will avant le verbe de base : It will rain tomorrow. Le verbe rain ne prend pas de -s après will.', 3, '{"id": "en.l35.e07", "unitIds": ["en.g24.will_future", "en.v.tomorrow"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Il pleuvra demain.", "promptLanguage": "fr", "answer": "It will rain tomorrow", "acceptedAnswers": ["It will rain tomorrow", "Tomorrow it will rain", "It will be rainy tomorrow", "It is going to rain tomorrow", "Tomorrow it is going to rain"], "hint": "C''est une prédiction : quel mot du futur place-t-on avant rain ?", "explanation": "Pour une prédiction, on met will avant le verbe de base : It will rain tomorrow. Le verbe rain ne prend pas de -s après will.", "tip": "Prédiction sur demain : will + verbe de base.", "extraExample": {"text": "It will be cold tonight.", "translation": "Il fera froid cette nuit."}, "errorPatterns": [{"contains": "will rains", "category": "conjugation", "feedback": "Après will, le verbe reste à sa forme de base : will rain, sans -s."}, {"contains": "will to rain", "category": "grammar", "feedback": "Après will, on ne met pas to : it will rain."}, {"contains": "is raining tomorrow", "category": "verb_tense", "feedback": "It''s raining parle du moment présent. Pour une prédiction sur demain, on dit It will rain tomorrow."}, {"contains": "rains tomorrow", "category": "verb_tense", "feedback": "Le présent simple ne convient pas pour une prédiction. Utilise will : It will rain tomorrow."}], "pool": "lesson", "lessonId": "en.l35", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l35.e08', 'en', 'en.l35', 'en.g24.will_future', array['en.g24.will_future','en.v.later']::text[], 'translation', 'lesson', 'Je t''appellerai plus tard.', array['I will call you later','I will phone you later','I will call you back later','Later I will call you','I am going to call you later','I am going to phone you later']::text[], 'Pour une décision ou une promesse sur le futur, on utilise will + verbe de base : I will call you later. À l''oral, on dit surtout I''ll call you later.', 3, '{"id": "en.l35.e08", "unitIds": ["en.g24.will_future", "en.v.later"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Je t''appellerai plus tard.", "promptLanguage": "fr", "answer": "I will call you later", "acceptedAnswers": ["I will call you later", "I will phone you later", "I will call you back later", "Later I will call you", "I am going to call you later", "I am going to phone you later"], "hint": "Le futur se fait avec will. Le complément « te » se dit you.", "explanation": "Pour une décision ou une promesse sur le futur, on utilise will + verbe de base : I will call you later. À l''oral, on dit surtout I''ll call you later.", "tip": "Je + futur = I will (ou I''ll) + verbe de base.", "extraExample": {"text": "I''ll send you a message later.", "translation": "Je t''enverrai un message plus tard."}, "errorPatterns": [{"contains": "will to call", "category": "grammar", "feedback": "Après will, on ne met pas to : I will call."}, {"contains": "will calling", "category": "grammar", "feedback": "Après will, le verbe est à la forme de base, sans -ing : I will call."}, {"contains": "i call you", "category": "verb_tense", "feedback": "Le présent simple ne convient pas pour annoncer ce que tu feras. Utilise will : I will call you later."}], "pool": "lesson", "lessonId": "en.l35", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l35.e09', 'en', 'en.l35', 'en.g24.will_future', array['en.g24.will_future','en.v.next']::text[], 'free_answer', 'lesson', 'Comment dit-on « Nous partirons la semaine prochaine. » ?', array['We will leave next week','We will go next week','We will go away next week','Next week we will leave','We are going to leave next week','We are going to go next week','We are leaving next week']::text[], 'Pour annoncer ce qu''on fera plus tard, on utilise will + verbe de base : We will leave. Next week se place à la fin et ne prend ni the ni préposition.', 3, '{"id": "en.l35.e09", "unitIds": ["en.g24.will_future", "en.v.next"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Nous partirons la semaine prochaine. » ?", "promptLanguage": "fr", "answer": "We will leave next week", "acceptedAnswers": ["We will leave next week", "We will go next week", "We will go away next week", "Next week we will leave", "We are going to leave next week", "We are going to go next week", "We are leaving next week"], "hint": "« La semaine prochaine » se dit next week, sans the ni préposition.", "explanation": "Pour annoncer ce qu''on fera plus tard, on utilise will + verbe de base : We will leave. Next week se place à la fin et ne prend ni the ni préposition.", "tip": "Next week, sans the et sans in : on dit next week, pas in the next week.", "extraExample": {"text": "Anna will visit us next week.", "translation": "Anna nous rendra visite la semaine prochaine."}, "errorPatterns": [{"contains": "the next week", "category": "grammar", "feedback": "Dans « la semaine prochaine », on ne met pas the en anglais : next week."}, {"contains": "will to leave", "category": "grammar", "feedback": "Après will, on ne met pas to : we will leave."}, {"contains": "we leave next week", "category": "verb_tense", "feedback": "Le présent simple ne suffit pas pour annoncer ce que tu feras. Utilise will : We will leave next week."}], "pool": "lesson", "lessonId": "en.l35", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l35.e10', 'en', 'en.l35', 'en.g24.will_future', array['en.g24.will_future','en.v.tomorrow']::text[], 'free_answer', 'lesson', 'Que feras-tu demain ? Écris une phrase.', array['Tomorrow I will visit my friend.','I will cook dinner tomorrow.','I won''t work tomorrow.','Tomorrow I will stay at home.']::text[], 'Une phrase correcte contient will (ou won''t) suivi d''un verbe de base, et le mot tomorrow. Par exemple : Tomorrow I will visit my friend.', 3, '{"id": "en.l35.e10", "unitIds": ["en.g24.will_future", "en.v.tomorrow"], "type": "free_answer", "difficulty": 3, "instruction": "Écris une phrase en anglais avec will et tomorrow, pour dire ce que tu feras demain.", "prompt": "Que feras-tu demain ? Écris une phrase.", "promptLanguage": "fr", "requirements": {"mustInclude": [["will", "''ll", "won''t"], ["tomorrow"]], "minWords": 4}, "answer": "Tomorrow I will visit my friend.", "acceptedAnswers": ["Tomorrow I will visit my friend.", "I will cook dinner tomorrow.", "I won''t work tomorrow.", "Tomorrow I will stay at home."], "hint": "Commence par I will, puis choisis un verbe de base que tu connais (visit, work, cook, stay…).", "explanation": "Une phrase correcte contient will (ou won''t) suivi d''un verbe de base, et le mot tomorrow. Par exemple : Tomorrow I will visit my friend.", "tip": "Je + will + verbe + tomorrow : tu peux mettre tomorrow au début ou à la fin.", "extraExample": {"text": "I''ll cook dinner tomorrow.", "translation": "Je préparerai le dîner demain."}, "errorPatterns": [{"contains": "will to", "category": "grammar", "feedback": "Après will, on ne met pas to : le verbe de base suit directement."}, {"contains": "wills", "category": "conjugation", "feedback": "Will ne prend jamais de -s : I will, he will, they will."}], "pool": "lesson", "lessonId": "en.l35", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l36.e01', 'en', 'en.l36', 'en.g24.will_future', array['en.g24.will_future','en.v.borrow','en.v.lend']::text[], 'mcq', 'lesson', 'Tom, can I ___ your phone, please? I need to call my mother.', array['borrow']::text[], 'Le téléphone est à Tom, et tu veux l''utiliser un moment : tu l''empruntes, donc borrow. C''est Tom qui le prêtera (lend).', 1, '{"id": "en.l36.e01", "unitIds": ["en.g24.will_future", "en.v.borrow", "en.v.lend"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon verbe.", "prompt": "Tom, can I ___ your phone, please? I need to call my mother.", "promptLanguage": "en", "options": ["borrow", "lend", "send"], "answer": "borrow", "acceptedAnswers": ["borrow"], "hint": "À qui appartient le téléphone ? Tu veux le prendre pour un moment.", "explanation": "Le téléphone est à Tom, et tu veux l''utiliser un moment : tu l''empruntes, donc borrow. C''est Tom qui le prêtera (lend).", "tip": "Je prends pour un temps : borrow. Je donne pour un temps : lend.", "extraExample": {"text": "Can I borrow your book, please?", "translation": "Je peux t''emprunter ton livre, s''il te plaît ?"}, "errorPatterns": [{"equals": "lend", "category": "word_confusion", "feedback": "Lend veut dire « prêter » : c''est celui qui possède l''objet qui lend. Toi, tu empruntes : borrow."}, {"equals": "send", "category": "word_confusion", "feedback": "Send veut dire « envoyer ». Pour prendre le téléphone de Tom un moment, on dit borrow."}], "pool": "lesson", "lessonId": "en.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l36.e02', 'en', 'en.l36', 'en.g24.will_future', array['en.g24.will_future','en.v.promise','en.v.bring']::text[], 'mcq', 'lesson', 'Comment dit-on « Je te promets que j''apporterai le gâteau. » en anglais ?', array['I promise I will bring the cake.']::text[], 'On fait une promesse sur le futur avec will + verbe de base : I will bring. Le présent simple ne convient pas, et après will il n''y a ni to ni -s.', 2, '{"id": "en.l36.e02", "unitIds": ["en.g24.will_future", "en.v.promise", "en.v.bring"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne phrase.", "prompt": "Comment dit-on « Je te promets que j''apporterai le gâteau. » en anglais ?", "promptLanguage": "fr", "options": ["I promise I will bring the cake.", "I promise I bring the cake.", "I promise I will to bring the cake.", "I promise I will brings the cake."], "answer": "I promise I will bring the cake.", "acceptedAnswers": ["I promise I will bring the cake."], "hint": "Une promesse parle du futur : quel mot du futur faut-il avant bring ?", "explanation": "On fait une promesse sur le futur avec will + verbe de base : I will bring. Le présent simple ne convient pas, et après will il n''y a ni to ni -s.", "tip": "Je promets + I will + verbe de base.", "extraExample": {"text": "I promise I will call you tonight.", "translation": "Je te promets que je t''appellerai ce soir."}, "errorPatterns": [{"equals": "i promise i bring the cake", "category": "verb_tense", "feedback": "Le présent simple ne convient pas pour une promesse. Il faut will : I promise I will bring the cake."}, {"equals": "i promise i will to bring the cake", "category": "grammar", "feedback": "Après will, on ne met pas to : I will bring."}, {"equals": "i promise i will brings the cake", "category": "conjugation", "feedback": "Après will, le verbe reste à la forme de base : pas de -s."}], "pool": "lesson", "lessonId": "en.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l36.e03', 'en', 'en.l36', 'en.g24.will_future', array['en.g24.will_future','en.v.promise','en.v.bring','en.v.send','en.v.lend','en.v.borrow']::text[], 'match', 'lesson', 'Les verbes des promesses et des services : promise, bring, send, lend, borrow', '{}'::text[], 'Lend et borrow sont opposés : celui qui donne un objet pour un temps le lend, celui qui le reçoit le borrows. Après will, tous ces verbes restent à la forme de base.', 1, '{"id": "en.l36.e03", "unitIds": ["en.g24.will_future", "en.v.promise", "en.v.bring", "en.v.send", "en.v.lend", "en.v.borrow"], "type": "match", "difficulty": 1, "instruction": "Associe chaque verbe anglais à sa traduction.", "prompt": "Les verbes des promesses et des services : promise, bring, send, lend, borrow", "promptLanguage": "fr", "pairs": [{"left": "promise", "right": "promettre"}, {"left": "bring", "right": "apporter"}, {"left": "send", "right": "envoyer"}, {"left": "lend", "right": "prêter"}, {"left": "borrow", "right": "emprunter"}], "answer": "promise = promettre ; bring = apporter ; send = envoyer ; lend = prêter ; borrow = emprunter", "acceptedAnswers": [], "explanation": "Lend et borrow sont opposés : celui qui donne un objet pour un temps le lend, celui qui le reçoit le borrows. Après will, tous ces verbes restent à la forme de base.", "tip": "Je prête : lend. J''emprunte : borrow.", "extraExample": {"text": "I''ll lend you my bag.", "translation": "Je te prêterai mon sac."}, "pool": "lesson", "lessonId": "en.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l36.e04', 'en', 'en.l36', 'en.g24.will_future', array['en.g24.will_future','en.v.send','en.v.promise']::text[], 'fill_blank', 'lesson', 'I promise I will ___ you a message tonight.', array['send']::text[], 'Après will, on met le verbe à la forme de base : will send. Sent est le passé de send : il ne s''emploie pas après will.', 2, '{"id": "en.l36.e04", "unitIds": ["en.g24.will_future", "en.v.send", "en.v.promise"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme du verbe.", "prompt": "I promise I will ___ you a message tonight.", "promptLanguage": "en", "options": ["send", "sent", "sends", "sending"], "answer": "send", "acceptedAnswers": ["send"], "hint": "Après will, le verbe se trouve tel qu''il est dans le dictionnaire.", "explanation": "Après will, on met le verbe à la forme de base : will send. Sent est le passé de send : il ne s''emploie pas après will.", "tip": "Après will : forme de base, même pour un verbe irrégulier comme send.", "extraExample": {"text": "I will send you the photos tomorrow.", "translation": "Je t''enverrai les photos demain."}, "errorPatterns": [{"equals": "sent", "category": "verb_tense", "feedback": "Sent est le passé de send. Pour le futur, après will, on garde la forme de base : will send."}, {"equals": "sends", "category": "conjugation", "feedback": "Après will, le verbe ne prend pas de -s : will send."}, {"equals": "sending", "category": "grammar", "feedback": "Après will, pas de -ing : le verbe reste à la forme de base, will send."}], "pool": "lesson", "lessonId": "en.l36", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l36.e05', 'en', 'en.l36', 'en.g24.will_future', array['en.g24.will_future','en.v.lend','en.v.borrow']::text[], 'fill_blank', 'lesson', 'Will you ___ me your laptop tonight, please?', array['lend']::text[], 'Tu demandes à ton ami de te donner son ordinateur pour un temps : il te le prête, donc lend. Après Will you, le verbe est à la forme de base.', 3, '{"id": "en.l36.e05", "unitIds": ["en.g24.will_future", "en.v.lend", "en.v.borrow"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le bon verbe.", "prompt": "Will you ___ me your laptop tonight, please?", "promptLanguage": "en", "options": ["lend", "borrow", "lent", "lends"], "answer": "lend", "acceptedAnswers": ["lend"], "hint": "C''est ton ami qui possède l''ordinateur : que doit-il faire pour toi ?", "explanation": "Tu demandes à ton ami de te donner son ordinateur pour un temps : il te le prête, donc lend. Après Will you, le verbe est à la forme de base.", "tip": "Will you lend me… ? = Tu me prêteras… ? Borrow, c''est toi qui prends.", "extraExample": {"text": "Will you lend me ten pounds?", "translation": "Tu me prêteras dix livres ?"}, "errorPatterns": [{"equals": "borrow", "category": "word_confusion", "feedback": "Borrow veut dire « emprunter » : c''est toi qui prends. Ici, tu demandes à ton ami de te prêter son ordinateur : lend."}, {"equals": "lent", "category": "verb_tense", "feedback": "Lent est le passé de lend. Après Will you, le verbe reste à la forme de base : Will you lend… ?"}, {"equals": "lends", "category": "conjugation", "feedback": "Après Will you, pas de -s : le verbe reste à la forme de base, lend."}], "pool": "lesson", "lessonId": "en.l36", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l36.e06', 'en', 'en.l36', 'en.g24.will_future', array['en.g24.will_future','en.v.bring']::text[], 'reorder', 'lesson', 'Je t''apporterai un café.', array['I will bring you a coffee']::text[], 'Will + verbe de base sert aussi à proposer son aide : I will bring you a coffee. Après bring, le pronom you vient tout de suite, sans to.', 2, '{"id": "en.l36.e06", "unitIds": ["en.g24.will_future", "en.v.bring"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Je t''apporterai un café.", "promptLanguage": "fr", "tokens": ["coffee", "I", "bring", "a", "you", "will"], "answer": "I will bring you a coffee", "acceptedAnswers": ["I will bring you a coffee"], "hint": "Will se place juste après le sujet. You se place directement après bring.", "explanation": "Will + verbe de base sert aussi à proposer son aide : I will bring you a coffee. Après bring, le pronom you vient tout de suite, sans to.", "tip": "Pour proposer ton aide, dis I''ll + verbe de base.", "extraExample": {"text": "I''ll carry your bag.", "translation": "Je porterai ton sac."}, "context": "Anna is tired. Tom wants to help her.", "pool": "lesson", "lessonId": "en.l36", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l36.e07', 'en', 'en.l36', 'en.g24.will_future', array['en.g24.will_future','en.v.send']::text[], 'translation', 'lesson', 'Je t''enverrai un message ce soir.', array['I will send you a message tonight','I will send you a message this evening','Tonight I will send you a message','I will send a message to you tonight','I will send a message to you this evening','I am going to send you a message tonight','I am going to send you a message this evening','I will message you tonight','I will text you tonight']::text[], 'Pour annoncer ce qu''on fera, on utilise will + verbe de base : I will send. Après send, on met directement you (send you a message), sans to.', 3, '{"id": "en.l36.e07", "unitIds": ["en.g24.will_future", "en.v.send"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais. « message » = message.", "prompt": "Je t''enverrai un message ce soir.", "promptLanguage": "fr", "answer": "I will send you a message tonight", "acceptedAnswers": ["I will send you a message tonight", "I will send you a message this evening", "Tonight I will send you a message", "I will send a message to you tonight", "I will send a message to you this evening", "I am going to send you a message tonight", "I am going to send you a message this evening", "I will message you tonight", "I will text you tonight"], "hint": "« Ce soir » se dit tonight. Le futur se fait avec will.", "explanation": "Pour annoncer ce qu''on fera, on utilise will + verbe de base : I will send. Après send, on met directement you (send you a message), sans to.", "tip": "Send you a message : pas de to quand le pronom suit directement send.", "extraExample": {"text": "I''ll send you a photo tomorrow.", "translation": "Je t''enverrai une photo demain."}, "errorPatterns": [{"contains": "will sent", "category": "verb_tense", "feedback": "Après will, on garde la forme de base : will send, pas sent."}, {"contains": "will to send", "category": "grammar", "feedback": "Après will, on ne met pas to : I will send."}, {"contains": "send to you a", "category": "word_order", "feedback": "Quand you suit directement send, on n''ajoute pas to : send you a message."}, {"contains": "i send you", "category": "verb_tense", "feedback": "Le présent simple ne convient pas pour annoncer ce que tu feras. Utilise will : I will send you a message."}], "pool": "lesson", "lessonId": "en.l36", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l36.e08', 'en', 'en.l36', 'en.g24.will_future', array['en.g24.will_future','en.v.promise']::text[], 'translation', 'lesson', 'Je te promets que je t''aiderai.', array['I promise I will help you','I promise that I will help you','I promise you I will help you','I promise you that I will help you','I promise to help you','I will help you, I promise','I will help you I promise']::text[], 'Après I promise, on annonce ce qu''on fera avec will + verbe de base : I promise I will help you. On peut aussi dire I promise to help you.', 3, '{"id": "en.l36.e08", "unitIds": ["en.g24.will_future", "en.v.promise"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Je te promets que je t''aiderai.", "promptLanguage": "fr", "answer": "I promise I will help you", "acceptedAnswers": ["I promise I will help you", "I promise that I will help you", "I promise you I will help you", "I promise you that I will help you", "I promise to help you", "I will help you, I promise", "I will help you I promise"], "hint": "Qui aidera ? C''est « je » : I promise I…", "explanation": "Après I promise, on annonce ce qu''on fera avec will + verbe de base : I promise I will help you. On peut aussi dire I promise to help you.", "tip": "I promise (that) I will + verbe de base.", "extraExample": {"text": "I promise I will call you tonight.", "translation": "Je te promets que je t''appellerai ce soir."}, "errorPatterns": [{"contains": "promise i help", "category": "verb_tense", "feedback": "Pour une promesse, on utilise will : I promise I will help you."}, {"contains": "will to help", "category": "grammar", "feedback": "Après will, on ne met pas to : I will help you."}, {"contains": "promise you will help", "category": "grammar", "feedback": "I promise you will help veut dire « je te promets que tu aideras ». Pour dire que c''est moi qui aiderai : I promise I will help you."}], "pool": "lesson", "lessonId": "en.l36", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l36.e09', 'en', 'en.l36', 'en.g24.will_future', array['en.g24.will_future','en.v.lend']::text[], 'free_answer', 'lesson', 'Comment dit-on « Tu me prêteras ton livre ? » ?', array['Will you lend me your book','Will you lend your book to me','Can you lend me your book','Could you lend me your book','Would you lend me your book','Are you going to lend me your book']::text[], 'La personne qui donne l''objet pour un temps lend. Pour la question au futur, on met will avant you : Will you lend me… ? Le verbe reste à la forme de base.', 3, '{"id": "en.l36.e09", "unitIds": ["en.g24.will_future", "en.v.lend"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Tu me prêteras ton livre ? » ?", "promptLanguage": "fr", "answer": "Will you lend me your book", "acceptedAnswers": ["Will you lend me your book", "Will you lend your book to me", "Can you lend me your book", "Could you lend me your book", "Would you lend me your book", "Are you going to lend me your book"], "hint": "C''est l''autre personne qui te prête le livre : quel verbe est-ce ?", "explanation": "La personne qui donne l''objet pour un temps lend. Pour la question au futur, on met will avant you : Will you lend me… ? Le verbe reste à la forme de base.", "tip": "Tu me prêtes : you lend me. Je t''emprunte : I borrow from you.", "extraExample": {"text": "Will you lend me your bag?", "translation": "Tu me prêteras ton sac ?"}, "errorPatterns": [{"contains": "borrow me", "category": "word_confusion", "feedback": "Borrow veut dire « emprunter » et ne se construit pas avec me. Pour que l''autre te donne son livre un temps, il te le prête : lend me."}, {"contains": "you borrow", "category": "word_confusion", "feedback": "C''est ton ami qui possède le livre : lui, il te le prête (lend). Toi, tu l''empruntes (borrow)."}, {"contains": "will you lent", "category": "verb_tense", "feedback": "Après Will you, le verbe reste à la forme de base : Will you lend… ?"}], "pool": "lesson", "lessonId": "en.l36", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l36.e10', 'en', 'en.l36', 'en.g24.will_future', array['en.g24.will_future','en.v.promise']::text[], 'free_answer', 'lesson', 'Écris une promesse en anglais.', array['I promise I will bring your book tomorrow.','I promise I will send you a message tonight.','I promise I won''t forget your birthday.','I promise I will help you tomorrow.']::text[], 'Une promesse se fait avec I promise + will (ou won''t) + verbe de base : I promise I will help you. Le verbe après will reste à la forme de base.', 3, '{"id": "en.l36.e10", "unitIds": ["en.g24.will_future", "en.v.promise"], "type": "free_answer", "difficulty": 3, "instruction": "Fais une promesse à un ami : écris une phrase avec I promise et will (ou won''t).", "prompt": "Écris une promesse en anglais.", "promptLanguage": "fr", "requirements": {"mustInclude": [["promise"], ["will", "''ll", "won''t"]], "minWords": 5}, "answer": "I promise I will bring your book tomorrow.", "acceptedAnswers": ["I promise I will bring your book tomorrow.", "I promise I will send you a message tonight.", "I promise I won''t forget your birthday.", "I promise I will help you tomorrow."], "hint": "Commence par I promise I will, puis ajoute un verbe de base et un complément.", "explanation": "Une promesse se fait avec I promise + will (ou won''t) + verbe de base : I promise I will help you. Le verbe après will reste à la forme de base.", "tip": "I promise I will… pour s''engager, I promise I won''t… pour s''interdire quelque chose.", "extraExample": {"text": "I promise I won''t be late.", "translation": "Je promets que je ne serai pas en retard."}, "errorPatterns": [{"contains": "will to", "category": "grammar", "feedback": "Après will, on ne met pas to : le verbe de base suit directement."}, {"contains": "wills", "category": "conjugation", "feedback": "Will ne prend jamais de -s : I will, he will, they will."}], "pool": "lesson", "lessonId": "en.l36", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l37.e01', 'en', 'en.l37', 'en.g25.going_to', array['en.g25.going_to','en.v.learn']::text[], 'mcq', 'lesson', 'I ___ learn French.', array['am going to']::text[], 'Pour parler d''un projet, on utilise be + going to + verbe de base. Avec I, be devient am : I am going to learn French.', 1, '{"id": "en.l37.e01", "unitIds": ["en.g25.going_to", "en.v.learn"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "I ___ learn French.", "promptLanguage": "en", "options": ["am going to", "going to", "am going", "will going to"], "answer": "am going to", "acceptedAnswers": ["am going to"], "hint": "Pour un projet, il faut be, puis going to, puis le verbe.", "explanation": "Pour parler d''un projet, on utilise be + going to + verbe de base. Avec I, be devient am : I am going to learn French.", "tip": "Going to ne va jamais seul : il lui faut am, is ou are devant.", "extraExample": {"text": "I''m going to learn to drive.", "translation": "Je vais apprendre à conduire."}, "errorPatterns": [{"equals": "going to", "category": "grammar", "feedback": "Il manque be devant going to. Avec I, on dit am going to : I am going to learn."}, {"equals": "am going", "category": "grammar", "feedback": "Il manque to après going. La structure est be + going to + verbe : I am going to learn."}, {"equals": "will going to", "category": "grammar", "feedback": "On choisit will ou going to, jamais les deux ensemble. Avec going to, il faut be : I am going to learn."}], "pool": "lesson", "lessonId": "en.l37", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l37.e02', 'en', 'en.l37', 'en.g25.going_to', array['en.g25.going_to','en.v.move']::text[], 'mcq', 'lesson', 'Anna ___ move to London next week.', array['is going to']::text[], 'Avec Anna (she), be devient is : Anna is going to move. Going to et le verbe de base, eux, ne changent pas.', 2, '{"id": "en.l37.e02", "unitIds": ["en.g25.going_to", "en.v.move"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme.", "prompt": "Anna ___ move to London next week.", "promptLanguage": "en", "options": ["is going to", "are going to", "am going to", "going to"], "answer": "is going to", "acceptedAnswers": ["is going to"], "hint": "Anna se remplace par she : quelle forme de be va avec she ?", "explanation": "Avec Anna (she), be devient is : Anna is going to move. Going to et le verbe de base, eux, ne changent pas.", "tip": "Seul be change : I am, he / she / it is, you / we / they are.", "extraExample": {"text": "Tom is going to learn English.", "translation": "Tom va apprendre l''anglais."}, "errorPatterns": [{"equals": "are going to", "category": "conjugation", "feedback": "Are va avec you, we et they. Avec Anna (she), on dit is."}, {"equals": "am going to", "category": "conjugation", "feedback": "Am s''emploie seulement avec I. Avec Anna (she), on dit is."}, {"equals": "going to", "category": "grammar", "feedback": "Il manque be devant going to : Anna is going to move."}], "pool": "lesson", "lessonId": "en.l37", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l37.e03', 'en', 'en.l37', 'en.g25.going_to', array['en.g25.going_to','en.v.plan','en.v.move','en.v.learn','en.v.save','en.v.change']::text[], 'match', 'lesson', 'Les verbes des projets : plan, move, learn, save, change', '{}'::text[], 'Ces verbes servent à parler de projets. Après going to, ils restent à la forme de base : going to move, going to learn, going to save.', 1, '{"id": "en.l37.e03", "unitIds": ["en.g25.going_to", "en.v.plan", "en.v.move", "en.v.learn", "en.v.save", "en.v.change"], "type": "match", "difficulty": 1, "instruction": "Associe chaque verbe anglais à sa traduction.", "prompt": "Les verbes des projets : plan, move, learn, save, change", "promptLanguage": "fr", "pairs": [{"left": "plan", "right": "prévoir"}, {"left": "move", "right": "déménager"}, {"left": "learn", "right": "apprendre"}, {"left": "save", "right": "économiser"}, {"left": "change", "right": "changer"}], "answer": "plan = prévoir ; move = déménager ; learn = apprendre ; save = économiser ; change = changer", "acceptedAnswers": [], "explanation": "Ces verbes servent à parler de projets. Après going to, ils restent à la forme de base : going to move, going to learn, going to save.", "tip": "Après going to, le verbe ne change jamais.", "extraExample": {"text": "We plan to move soon.", "translation": "Nous prévoyons de déménager bientôt."}, "pool": "lesson", "lessonId": "en.l37", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l37.e04', 'en', 'en.l37', 'en.g25.going_to', array['en.g25.going_to','en.v.learn']::text[], 'fill_blank', 'lesson', '___ you going to learn to drive?', array['Are']::text[], 'Pour poser une question avec going to, on place be avant le sujet : Are you going to… ? Avec you, be s''écrit are.', 2, '{"id": "en.l37.e04", "unitIds": ["en.g25.going_to", "en.v.learn"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la question avec le bon mot.", "prompt": "___ you going to learn to drive?", "promptLanguage": "en", "options": ["Are", "Do", "Is", "Will"], "answer": "Are", "acceptedAnswers": ["Are"], "hint": "Pour la question, on met be avant le sujet. Quelle forme de be va avec you ?", "explanation": "Pour poser une question avec going to, on place be avant le sujet : Are you going to… ? Avec you, be s''écrit are.", "tip": "Question : Am / Are / Is + sujet + going to + verbe de base.", "extraExample": {"text": "Is Tom going to move?", "translation": "Est-ce que Tom va déménager ?"}, "errorPatterns": [{"equals": "do", "category": "grammar", "feedback": "Avec going to, la question se fait avec be, pas avec do : Are you going to… ?"}, {"equals": "is", "category": "conjugation", "feedback": "Is va avec he, she et it. Avec you, be devient are."}, {"equals": "will", "category": "grammar", "feedback": "Will ne se combine pas avec going to. Pour la question, on met be avant you : Are you going to… ?"}], "pool": "lesson", "lessonId": "en.l37", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l37.e05', 'en', 'en.l37', 'en.g25.going_to', array['en.g25.going_to','en.v.save']::text[], 'fill_blank', 'lesson', 'I''m going to ___ money for my holiday.', array['save']::text[], 'Après going to, le verbe reste à la forme de base : going to save. On n''ajoute ni -ed, ni -ing, ni -s.', 3, '{"id": "en.l37.e05", "unitIds": ["en.g25.going_to", "en.v.save"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la bonne forme du verbe.", "prompt": "I''m going to ___ money for my holiday.", "promptLanguage": "en", "options": ["save", "saved", "saving", "saves"], "answer": "save", "acceptedAnswers": ["save"], "hint": "Après going to, le verbe est tel qu''on le trouve dans le dictionnaire.", "explanation": "Après going to, le verbe reste à la forme de base : going to save. On n''ajoute ni -ed, ni -ing, ni -s.", "tip": "Going to + verbe de base : le verbe ne prend ni -s, ni -ed, ni -ing.", "extraExample": {"text": "Tom is going to save his homework on the laptop.", "translation": "Tom va sauvegarder ses devoirs sur l''ordinateur portable."}, "errorPatterns": [{"equals": "saved", "category": "verb_tense", "feedback": "Saved est le passé. Après going to, le verbe reste à la forme de base : going to save."}, {"equals": "saving", "category": "grammar", "feedback": "Après going to, pas de -ing : le verbe reste à la forme de base, going to save."}, {"equals": "saves", "category": "conjugation", "feedback": "Après going to, le verbe ne prend pas de -s, même avec he ou she. On dit going to save."}], "pool": "lesson", "lessonId": "en.l37", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l37.e06', 'en', 'en.l37', 'en.g25.going_to', array['en.g25.going_to','en.v.change','en.v.plan']::text[], 'reorder', 'lesson', 'Nous n''allons pas changer le plan.', array['We aren''t going to change the plan']::text[], 'Pour la négation, on ajoute not après be : We aren''t (are not) going to change. Le verbe change reste à la forme de base.', 3, '{"id": "en.l37.e06", "unitIds": ["en.g25.going_to", "en.v.change", "en.v.plan"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Nous n''allons pas changer le plan.", "promptLanguage": "fr", "tokens": ["plan", "We", "going", "the", "aren''t", "to", "change"], "answer": "We aren''t going to change the plan", "acceptedAnswers": ["We aren''t going to change the plan"], "hint": "La négation se place juste après be : aren''t.", "explanation": "Pour la négation, on ajoute not après be : We aren''t (are not) going to change. Le verbe change reste à la forme de base.", "tip": "Négation : be + not + going to + verbe de base.", "extraExample": {"text": "She isn''t going to move.", "translation": "Elle ne va pas déménager."}, "pool": "lesson", "lessonId": "en.l37", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l37.e07', 'en', 'en.l37', 'en.g25.going_to', array['en.g25.going_to','en.v.move']::text[], 'translation', 'lesson', 'Nous allons déménager la semaine prochaine.', array['We are going to move next week','Next week we are going to move','We are going to move house next week','We will move next week','We will move house next week','Next week we will move','We are moving next week','We are moving house next week']::text[], 'Pour un projet, on utilise be + going to + verbe de base : We are going to move. Avec we, be devient are.', 3, '{"id": "en.l37.e07", "unitIds": ["en.g25.going_to", "en.v.move"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Nous allons déménager la semaine prochaine.", "promptLanguage": "fr", "answer": "We are going to move next week", "acceptedAnswers": ["We are going to move next week", "Next week we are going to move", "We are going to move house next week", "We will move next week", "We will move house next week", "Next week we will move", "We are moving next week", "We are moving house next week"], "hint": "Déménager se dit move. Un projet se dit avec be + going to.", "explanation": "Pour un projet, on utilise be + going to + verbe de base : We are going to move. Avec we, be devient are.", "tip": "We are going to + verbe : seul be s''accorde, le verbe reste à la forme de base.", "extraExample": {"text": "They''re going to move to Paris.", "translation": "Ils vont déménager à Paris."}, "errorPatterns": [{"contains": "we going to", "category": "grammar", "feedback": "Il manque are devant going to : We are going to move."}, {"contains": "going to moved", "category": "verb_tense", "feedback": "Après going to, le verbe reste à la forme de base : going to move."}, {"contains": "going to moving", "category": "grammar", "feedback": "Après going to, pas de -ing : le verbe reste à la forme de base, going to move."}], "pool": "lesson", "lessonId": "en.l37", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l37.e08', 'en', 'en.l37', 'en.g25.going_to', array['en.g25.going_to','en.v.learn']::text[], 'translation', 'lesson', 'Elle va apprendre le français.', array['She is going to learn French','She will learn French','She is going to study French','She will study French']::text[], 'Pour un projet, on utilise be + going to + verbe de base : She is going to learn. Avec she, be devient is, et learn ne prend pas de -s.', 3, '{"id": "en.l37.e08", "unitIds": ["en.g25.going_to", "en.v.learn"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Elle va apprendre le français.", "promptLanguage": "fr", "answer": "She is going to learn French", "acceptedAnswers": ["She is going to learn French", "She will learn French", "She is going to study French", "She will study French"], "hint": "Avec she, be devient is. Le nom de la langue prend une majuscule en anglais.", "explanation": "Pour un projet, on utilise be + going to + verbe de base : She is going to learn. Avec she, be devient is, et learn ne prend pas de -s.", "tip": "She is going to + verbe de base : le -s n''est jamais sur le verbe.", "extraExample": {"text": "My son is going to learn to swim.", "translation": "Mon fils va apprendre à nager."}, "errorPatterns": [{"contains": "she going to", "category": "grammar", "feedback": "Il manque is devant going to : She is going to learn French."}, {"contains": "going to learns", "category": "conjugation", "feedback": "Après going to, le verbe ne prend pas de -s : going to learn."}, {"contains": "going to learned", "category": "verb_tense", "feedback": "Après going to, le verbe reste à la forme de base, pas au passé : going to learn."}], "pool": "lesson", "lessonId": "en.l37", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l37.e09', 'en', 'en.l37', 'en.g25.going_to', array['en.g25.going_to','en.v.save']::text[], 'free_answer', 'lesson', 'Comment dit-on « Ils vont économiser de l''argent pour leurs vacances. » ?', array['They are going to save money for their holiday','They are going to save money for their holidays','They are going to save money for their vacation','They will save money for their holiday','They will save money for their holidays','They will save money for their vacation','They are going to save money for the holidays','They are going to save money for the holiday']::text[], 'On utilise be + going to + verbe de base : They are going to save. Avec they, be devient are, et save reste à la forme de base.', 3, '{"id": "en.l37.e09", "unitIds": ["en.g25.going_to", "en.v.save"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Ils vont économiser de l''argent pour leurs vacances. » ?", "promptLanguage": "fr", "answer": "They are going to save money for their holiday", "acceptedAnswers": ["They are going to save money for their holiday", "They are going to save money for their holidays", "They are going to save money for their vacation", "They will save money for their holiday", "They will save money for their holidays", "They will save money for their vacation", "They are going to save money for the holidays", "They are going to save money for the holiday"], "hint": "Avec they, be devient are. « Économiser de l''argent » = save money.", "explanation": "On utilise be + going to + verbe de base : They are going to save. Avec they, be devient are, et save reste à la forme de base.", "tip": "They are going to + verbe de base : pas de -s, pas de -ing.", "extraExample": {"text": "We''re going to save money for a new car.", "translation": "Nous allons économiser de l''argent pour une nouvelle voiture."}, "errorPatterns": [{"contains": "they going to", "category": "grammar", "feedback": "Il manque are devant going to : They are going to save."}, {"contains": "going to saved", "category": "verb_tense", "feedback": "Après going to, le verbe reste à la forme de base : going to save."}, {"contains": "going to saving", "category": "grammar", "feedback": "Après going to, pas de -ing : le verbe reste à la forme de base, going to save."}], "pool": "lesson", "lessonId": "en.l37", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l37.e10', 'en', 'en.l37', 'en.g25.going_to', array['en.g25.going_to','en.v.plan']::text[], 'free_answer', 'lesson', 'Quel est ton projet ? Écris une phrase.', array['I''m going to learn to swim.','We''re going to move next week.','I''m going to save money for a holiday.','My sister is going to learn English.']::text[], 'Un projet se dit avec be + going to + verbe de base. Par exemple : I''m going to learn to swim. N''oublie pas be devant going to.', 3, '{"id": "en.l37.e10", "unitIds": ["en.g25.going_to", "en.v.plan"], "type": "free_answer", "difficulty": 3, "instruction": "Écris une phrase en anglais avec going to pour parler d''un projet que tu as.", "prompt": "Quel est ton projet ? Écris une phrase.", "promptLanguage": "fr", "requirements": {"mustInclude": [["going to"]], "minWords": 5}, "answer": "I''m going to learn to swim.", "acceptedAnswers": ["I''m going to learn to swim.", "We''re going to move next week.", "I''m going to save money for a holiday.", "My sister is going to learn English."], "hint": "Commence par I''m going to, puis choisis un verbe de base (learn, move, save, change…).", "explanation": "Un projet se dit avec be + going to + verbe de base. Par exemple : I''m going to learn to swim. N''oublie pas be devant going to.", "tip": "I''m / you''re / he''s… going to + verbe de base : be ne s''oublie jamais.", "extraExample": {"text": "Anna is going to change her name.", "translation": "Anna va changer de nom."}, "errorPatterns": [{"contains": "going to went", "category": "verb_tense", "feedback": "Après going to, le verbe reste à la forme de base, jamais au passé : going to go."}, {"contains": "i going to", "category": "grammar", "feedback": "Il manque be : I am going to… ou I''m going to…"}], "pool": "lesson", "lessonId": "en.l37", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l38.e01', 'en', 'en.l38', 'en.g25.going_to', array['en.g25.going_to','en.v.year','en.v.next']::text[], 'mcq', 'lesson', 'Comment dit-on « l''année prochaine » en anglais ?', array['next year']::text[], 'Pour parler de l''année qui vient, on dit next year : next devant le nom, sans the, et year au singulier. On l''emploie souvent avec going to pour un projet.', 1, '{"id": "en.l38.e01", "unitIds": ["en.g25.going_to", "en.v.year", "en.v.next"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « l''année prochaine » en anglais ?", "promptLanguage": "fr", "options": ["next year", "year next", "next years", "the next years"], "answer": "next year", "acceptedAnswers": ["next year"], "hint": "Next se place avant le nom, sans the, et year reste au singulier.", "explanation": "Pour parler de l''année qui vient, on dit next year : next devant le nom, sans the, et year au singulier. On l''emploie souvent avec going to pour un projet.", "tip": "Next + nom, sans the : next year, next week.", "extraExample": {"text": "Next year, Anna is going to learn French.", "translation": "L''année prochaine, Anna va apprendre le français."}, "errorPatterns": [{"equals": "year next", "category": "word_order", "feedback": "En anglais, next se place avant le nom : next year."}, {"equals": "next years", "category": "grammar", "feedback": "On parle d''une seule année : year reste au singulier. On dit next year."}, {"equals": "the next years", "category": "grammar", "feedback": "Pas de the dans « l''année prochaine », et year reste au singulier : next year."}], "pool": "lesson", "lessonId": "en.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l38.e02', 'en', 'en.l38', 'en.g25.going_to', array['en.g25.going_to','en.v.country','en.v.move']::text[], 'mcq', 'lesson', 'Anna ___ going to move to another country.', array['isn''t','is not']::text[], 'Avec going to, on fait la négation avec be + not : Anna isn''t going to move. On n''emploie pas do ni doesn''t, car be est déjà là.', 2, '{"id": "en.l38.e02", "unitIds": ["en.g25.going_to", "en.v.country", "en.v.move"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme.", "prompt": "Anna ___ going to move to another country.", "promptLanguage": "en", "options": ["isn''t", "doesn''t", "don''t", "not"], "answer": "isn''t", "acceptedAnswers": ["isn''t", "is not"], "hint": "Going to se construit avec be : la négation se place après be.", "explanation": "Avec going to, on fait la négation avec be + not : Anna isn''t going to move. On n''emploie pas do ni doesn''t, car be est déjà là.", "tip": "Négation avec going to : isn''t, aren''t ou I''m not, jamais don''t.", "extraExample": {"text": "They aren''t going to change their plan.", "translation": "Ils ne vont pas changer leur projet."}, "errorPatterns": [{"equals": "does not", "category": "grammar", "feedback": "Going to se construit avec be, pas avec do. La négation est isn''t : Anna isn''t going to move."}, {"equals": "do not", "category": "grammar", "feedback": "Don''t va avec I, you, we, they, et surtout pas avec going to, qui demande be. Avec Anna, on dit isn''t."}, {"equals": "not", "category": "grammar", "feedback": "Not seul ne suffit pas : il faut be + not, donc isn''t ou is not."}], "pool": "lesson", "lessonId": "en.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l38.e03', 'en', 'en.l38', 'en.g25.going_to', array['en.g25.going_to','en.v.year','en.v.job','en.v.apartment','en.v.city','en.v.country']::text[], 'match', 'lesson', 'Les mots des projets de vie : a year, a job, an apartment, a city, a country', '{}'::text[], 'Ces mots servent à parler de projets de vie. On dit an apartment, avec an, car apartment commence par un son de voyelle.', 1, '{"id": "en.l38.e03", "unitIds": ["en.g25.going_to", "en.v.year", "en.v.job", "en.v.apartment", "en.v.city", "en.v.country"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les mots des projets de vie : a year, a job, an apartment, a city, a country", "promptLanguage": "fr", "pairs": [{"left": "a year", "right": "une année"}, {"left": "a job", "right": "un emploi"}, {"left": "an apartment", "right": "un appartement"}, {"left": "a city", "right": "une ville"}, {"left": "a country", "right": "un pays"}], "answer": "a year = une année ; a job = un emploi ; an apartment = un appartement ; a city = une ville ; a country = un pays", "acceptedAnswers": [], "explanation": "Ces mots servent à parler de projets de vie. On dit an apartment, avec an, car apartment commence par un son de voyelle.", "tip": "Devant un son de voyelle, on dit an : an apartment.", "extraExample": {"text": "We''re going to buy an apartment.", "translation": "Nous allons acheter un appartement."}, "pool": "lesson", "lessonId": "en.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l38.e04', 'en', 'en.l38', 'en.g25.going_to', array['en.g25.going_to','en.v.country']::text[], 'fill_blank', 'lesson', 'Anna is going ___ live in another country.', array['to']::text[], 'La structure d''un projet est be + going to + verbe de base. Le petit mot to fait partie de going to : Anna is going to live.', 2, '{"id": "en.l38.e04", "unitIds": ["en.g25.going_to", "en.v.country"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "Anna is going ___ live in another country.", "promptLanguage": "en", "options": ["to", "for", "at", "in"], "answer": "to", "acceptedAnswers": ["to"], "hint": "Pour un projet, going est toujours suivi du même petit mot, puis du verbe.", "explanation": "La structure d''un projet est be + going to + verbe de base. Le petit mot to fait partie de going to : Anna is going to live.", "tip": "Going to : les deux mots vont ensemble, puis le verbe de base.", "extraExample": {"text": "My brother is going to work in another country.", "translation": "Mon frère va travailler dans un autre pays."}, "errorPatterns": [{"equals": "for", "category": "grammar", "feedback": "For ne convient pas ici. Pour un projet, on dit going to + verbe : going to live."}, {"equals": "at", "category": "grammar", "feedback": "At ne se met pas entre going et le verbe. La structure est going to + verbe de base."}, {"equals": "in", "category": "grammar", "feedback": "In ne se met pas entre going et le verbe. La structure est going to + verbe de base."}], "pool": "lesson", "lessonId": "en.l38", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l38.e05', 'en', 'en.l38', 'en.g25.going_to', array['en.g25.going_to','en.v.city']::text[], 'fill_blank', 'lesson', 'My parents ___ going to move to another city.', array['are','''re']::text[], 'My parents = they, donc be devient are : My parents are going to move. Will ne s''emploie jamais avec going to.', 2, '{"id": "en.l38.e05", "unitIds": ["en.g25.going_to", "en.v.city"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "My parents ___ going to move to another city.", "promptLanguage": "en", "options": ["are", "is", "am", "will"], "answer": "are", "acceptedAnswers": ["are", "''re"], "hint": "My parents se remplace par they : quelle forme de be va avec they ?", "explanation": "My parents = they, donc be devient are : My parents are going to move. Will ne s''emploie jamais avec going to.", "tip": "Un sujet pluriel (my parents, the children) se comporte comme they : are.", "extraExample": {"text": "My sisters are going to live in a big city.", "translation": "Mes sœurs vont vivre dans une grande ville."}, "errorPatterns": [{"equals": "is", "category": "conjugation", "feedback": "Parents est au pluriel : on dit are, comme avec they."}, {"equals": "am", "category": "conjugation", "feedback": "Am s''emploie seulement avec I. Avec my parents (they), on dit are."}, {"equals": "will", "category": "grammar", "feedback": "Will et going to ne s''emploient pas ensemble. Avec going to, il faut be : are going to."}], "pool": "lesson", "lessonId": "en.l38", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l38.e06', 'en', 'en.l38', 'en.g25.going_to', array['en.g25.going_to','en.v.year']::text[], 'reorder', 'lesson', 'Où vas-tu habiter l''année prochaine ?', array['Where are you going to live next year']::text[], 'Dans une question avec going to, on met le mot interrogatif, puis be avant le sujet : Where are you going to live ? Next year se place à la fin.', 3, '{"id": "en.l38.e06", "unitIds": ["en.g25.going_to", "en.v.year"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Où vas-tu habiter l''année prochaine ?", "promptLanguage": "fr", "tokens": ["year", "live", "you", "Where", "to", "going", "next", "are"], "answer": "Where are you going to live next year", "acceptedAnswers": ["Where are you going to live next year"], "hint": "Le mot interrogatif ouvre la phrase, puis be passe avant le sujet.", "explanation": "Dans une question avec going to, on met le mot interrogatif, puis be avant le sujet : Where are you going to live ? Next year se place à la fin.", "tip": "Question : mot interrogatif + be + sujet + going to + verbe de base.", "extraExample": {"text": "What are you going to learn next year?", "translation": "Qu''est-ce que tu vas apprendre l''année prochaine ?"}, "pool": "lesson", "lessonId": "en.l38", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l38.e07', 'en', 'en.l38', 'en.g25.going_to', array['en.g25.going_to','en.v.job','en.v.change','en.v.year']::text[], 'translation', 'lesson', 'Elle va changer de travail l''année prochaine.', array['She is going to change her job next year','She is going to change jobs next year','Next year she is going to change her job','Next year she is going to change jobs','She will change her job next year','She will change jobs next year','Next year she will change her job','She is changing her job next year','She is changing jobs next year']::text[], 'Pour un projet, on utilise be + going to + verbe de base : She is going to change. Après change, on met directement her job, sans préposition.', 3, '{"id": "en.l38.e07", "unitIds": ["en.g25.going_to", "en.v.job", "en.v.change", "en.v.year"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Elle va changer de travail l''année prochaine.", "promptLanguage": "fr", "answer": "She is going to change her job next year", "acceptedAnswers": ["She is going to change her job next year", "She is going to change jobs next year", "Next year she is going to change her job", "Next year she is going to change jobs", "She will change her job next year", "She will change jobs next year", "Next year she will change her job", "She is changing her job next year", "She is changing jobs next year"], "hint": "En anglais, on change son job : pas de « de ». Avec she, be devient is.", "explanation": "Pour un projet, on utilise be + going to + verbe de base : She is going to change. Après change, on met directement her job, sans préposition.", "tip": "Changer de travail : change her job (pas « change of »).", "extraExample": {"text": "Tom is going to change his phone next week.", "translation": "Tom va changer de téléphone la semaine prochaine."}, "errorPatterns": [{"contains": "she going to", "category": "grammar", "feedback": "Il manque is devant going to : She is going to change her job."}, {"contains": "change of", "category": "preposition", "feedback": "En anglais, on ne met pas « de » après change : change her job."}, {"contains": "the next year", "category": "grammar", "feedback": "Dans « l''année prochaine », on ne met pas the : next year."}], "pool": "lesson", "lessonId": "en.l38", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l38.e08', 'en', 'en.l38', 'en.g25.going_to', array['en.g25.going_to','en.v.country']::text[], 'translation', 'lesson', 'Nous allons habiter dans un autre pays.', array['We are going to live in another country','We are going to live in a different country','We will live in another country','We will live in a different country']::text[], 'On utilise be + going to + verbe de base : We are going to live. Another veut dire « un autre » et s''écrit en un seul mot, sans a devant.', 3, '{"id": "en.l38.e08", "unitIds": ["en.g25.going_to", "en.v.country"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Nous allons habiter dans un autre pays.", "promptLanguage": "fr", "answer": "We are going to live in another country", "acceptedAnswers": ["We are going to live in another country", "We are going to live in a different country", "We will live in another country", "We will live in a different country"], "hint": "« Un autre » se dit another, en un seul mot, et il remplace a.", "explanation": "On utilise be + going to + verbe de base : We are going to live. Another veut dire « un autre » et s''écrit en un seul mot, sans a devant.", "tip": "Another = an + other, en un seul mot : another country.", "extraExample": {"text": "They''re going to live in another city.", "translation": "Ils vont vivre dans une autre ville."}, "errorPatterns": [{"contains": "we going to", "category": "grammar", "feedback": "Il manque are devant going to : We are going to live."}, {"contains": "an other", "category": "spelling", "feedback": "« Un autre » s''écrit en un seul mot : another."}, {"contains": "in other country", "category": "grammar", "feedback": "Il faut un article : another country (« un autre pays »)."}], "pool": "lesson", "lessonId": "en.l38", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l38.e09', 'en', 'en.l38', 'en.g25.going_to', array['en.g25.going_to','en.v.apartment']::text[], 'free_answer', 'lesson', 'Comment dit-on « Ils ne vont pas acheter d''appartement. » ?', array['They aren''t going to buy an apartment','They are not going to buy an apartment','They aren''t going to buy a flat','They are not going to buy a flat','They won''t buy an apartment','They will not buy an apartment','They won''t buy a flat','They will not buy a flat']::text[], 'Pour la négation, on met not après be : They aren''t going to buy. Devant apartment, qui commence par un son de voyelle, on dit an.', 3, '{"id": "en.l38.e09", "unitIds": ["en.g25.going_to", "en.v.apartment"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Ils ne vont pas acheter d''appartement. » ?", "promptLanguage": "fr", "answer": "They aren''t going to buy an apartment", "acceptedAnswers": ["They aren''t going to buy an apartment", "They are not going to buy an apartment", "They aren''t going to buy a flat", "They are not going to buy a flat", "They won''t buy an apartment", "They will not buy an apartment", "They won''t buy a flat", "They will not buy a flat"], "hint": "Avec going to, la négation se place après be. Apartment commence par une voyelle.", "explanation": "Pour la négation, on met not après be : They aren''t going to buy. Devant apartment, qui commence par un son de voyelle, on dit an.", "tip": "Négation : be + not + going to + verbe de base.", "extraExample": {"text": "Tom isn''t going to buy a car.", "translation": "Tom ne va pas acheter de voiture."}, "errorPatterns": [{"contains": "do not going", "category": "grammar", "feedback": "Avec going to, la négation se fait avec be + not, pas avec do : They aren''t going to buy."}, {"contains": "a apartment", "category": "grammar", "feedback": "Apartment commence par un son de voyelle : on dit an apartment."}, {"contains": "they not going", "category": "grammar", "feedback": "Il manque be : They are not (aren''t) going to buy an apartment."}], "pool": "lesson", "lessonId": "en.l38", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l38.e10', 'en', 'en.l38', 'en.g25.going_to', array['en.g25.going_to','en.v.job','en.v.city']::text[], 'free_answer', 'lesson', 'Parle d''un de tes projets de vie.', array['I''m going to change my job next year.','We''re going to live in another country.','Anna is going to buy an apartment in London.','Tom is going to move to a new city.']::text[], 'Un projet se dit avec be + going to + verbe de base, et la phrase doit contenir un des mots demandés. Par exemple : I''m going to change my job next year.', 3, '{"id": "en.l38.e10", "unitIds": ["en.g25.going_to", "en.v.job", "en.v.city"], "type": "free_answer", "difficulty": 3, "instruction": "Écris une phrase en anglais avec going to et l''un de ces mots : year, job, apartment, city ou country.", "prompt": "Parle d''un de tes projets de vie.", "promptLanguage": "fr", "requirements": {"mustInclude": [["going to"], ["year", "years", "job", "jobs", "apartment", "apartments", "city", "cities", "country", "countries"]], "minWords": 6}, "answer": "I''m going to change my job next year.", "acceptedAnswers": ["I''m going to change my job next year.", "We''re going to live in another country.", "Anna is going to buy an apartment in London.", "Tom is going to move to a new city."], "hint": "Commence par I''m going to, puis un verbe de base (change, move, buy, live…) et un des cinq mots.", "explanation": "Un projet se dit avec be + going to + verbe de base, et la phrase doit contenir un des mots demandés. Par exemple : I''m going to change my job next year.", "tip": "I''m / he''s / we''re going to + verbe de base + ton projet.", "extraExample": {"text": "My sister is going to move to a big city.", "translation": "Ma sœur va déménager dans une grande ville."}, "errorPatterns": [{"contains": "going to went", "category": "verb_tense", "feedback": "Après going to, le verbe reste à la forme de base, jamais au passé : going to go."}, {"contains": "i going to", "category": "grammar", "feedback": "Il manque be : I am going to… ou I''m going to…"}], "pool": "lesson", "lessonId": "en.l38", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l39.e01', 'en', 'en.l39', 'en.g26.will_vs_going_to', array['en.g26.will_vs_going_to','en.g25.going_to']::text[], 'mcq', 'lesson', 'Tom ___ look for a new job.', array['is going to']::text[], 'Tom a déjà décidé hier : c''est un projet prévu avant qu''on en parle. Pour un projet déjà décidé, on utilise be going to : Tom is going to look for a new job.', 1, '{"id": "en.l39.e01", "unitIds": ["en.g26.will_vs_going_to", "en.g25.going_to"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "context": "Yesterday, Tom decided: he doesn''t like his job. He wants a new one.", "prompt": "Tom ___ look for a new job.", "promptLanguage": "en", "options": ["is going to", "will", "are going to", "is going"], "answer": "is going to", "acceptedAnswers": ["is going to"], "hint": "Tom a décidé hier : le projet existe déjà avant qu''il en parle.", "explanation": "Tom a déjà décidé hier : c''est un projet prévu avant qu''on en parle. Pour un projet déjà décidé, on utilise be going to : Tom is going to look for a new job.", "tip": "Décision déjà prise avant de parler : going to.", "extraExample": {"text": "Last week, Anna decided to move. She''s going to live in London.", "translation": "La semaine dernière, Anna a décidé de déménager. Elle va habiter à Londres."}, "errorPatterns": [{"equals": "will", "category": "grammar", "feedback": "Will sert à une décision prise à l''instant. Ici, Tom a déjà décidé hier : le projet est prévu, donc be going to."}, {"equals": "are going to", "category": "conjugation", "feedback": "Avec Tom (he), be devient is : Tom is going to look for…"}, {"equals": "is going", "category": "grammar", "feedback": "Il manque to après going : be + going to + verbe de base."}], "pool": "lesson", "lessonId": "en.l39", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l39.e02', 'en', 'en.l39', 'en.g26.will_vs_going_to', array['en.g26.will_vs_going_to','en.g24.will_future','en.v.idea','en.v.problem']::text[], 'mcq', 'lesson', 'Anna: « Wait! I ___ lend you my phone. »', array['will']::text[], 'Anna décide à l''instant, quand elle comprend le problème de Tom : c''est une décision spontanée et une proposition. On utilise will : I will lend you my phone.', 2, '{"id": "en.l39.e02", "unitIds": ["en.g26.will_vs_going_to", "en.g24.will_future", "en.v.idea", "en.v.problem"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme.", "context": "Tom has a problem: he needs to call his mother, but his phone is at home. Anna has an idea.", "prompt": "Anna: « Wait! I ___ lend you my phone. »", "promptLanguage": "en", "options": ["will", "am going to", "wills", "going to"], "answer": "will", "acceptedAnswers": ["will"], "hint": "Anna n''avait rien prévu : elle réagit au problème de Tom, à l''instant.", "explanation": "Anna décide à l''instant, quand elle comprend le problème de Tom : c''est une décision spontanée et une proposition. On utilise will : I will lend you my phone.", "tip": "Décision sur le moment, proposition ou promesse : will.", "extraExample": {"text": "You''re tired? I''ll make you a coffee.", "translation": "Tu es fatigué ? Je te prépare un café."}, "errorPatterns": [{"equals": "am going to", "category": "grammar", "feedback": "Anna n''avait rien prévu : elle décide maintenant pour aider Tom. Pour une décision à l''instant ou une proposition, on utilise will."}, {"equals": "wills", "category": "conjugation", "feedback": "Will ne prend jamais de -s : I will, he will, they will."}, {"equals": "going to", "category": "grammar", "feedback": "Going to a besoin de be (I am going to), et ici c''est une décision à l''instant : will."}], "pool": "lesson", "lessonId": "en.l39", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l39.e03', 'en', 'en.l39', 'en.g26.will_vs_going_to', array['en.g26.will_vs_going_to','en.v.probably','en.v.hope','en.v.guess','en.v.idea','en.v.problem']::text[], 'match', 'lesson', 'Les mots pour parler de l''avenir : probably, hope, guess, idea, problem', '{}'::text[], 'Probably, I hope et I guess annoncent une supposition sur le futur : on les utilise souvent avec will. Idea commence par un son de voyelle : an idea.', 1, '{"id": "en.l39.e03", "unitIds": ["en.g26.will_vs_going_to", "en.v.probably", "en.v.hope", "en.v.guess", "en.v.idea", "en.v.problem"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot anglais à sa traduction.", "prompt": "Les mots pour parler de l''avenir : probably, hope, guess, idea, problem", "promptLanguage": "fr", "pairs": [{"left": "probably", "right": "probablement"}, {"left": "hope", "right": "espérer"}, {"left": "guess", "right": "deviner, supposer"}, {"left": "an idea", "right": "une idée"}, {"left": "a problem", "right": "un problème"}], "answer": "probably = probablement ; hope = espérer ; guess = deviner, supposer ; an idea = une idée ; a problem = un problème", "acceptedAnswers": [], "explanation": "Probably, I hope et I guess annoncent une supposition sur le futur : on les utilise souvent avec will. Idea commence par un son de voyelle : an idea.", "tip": "I hope, I guess, probably : une supposition, donc souvent will.", "extraExample": {"text": "I guess Anna will like the idea.", "translation": "Je suppose que l''idée plaira à Anna."}, "pool": "lesson", "lessonId": "en.l39", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l39.e04', 'en', 'en.l39', 'en.g26.will_vs_going_to', array['en.g26.will_vs_going_to','en.g25.going_to']::text[], 'fill_blank', 'lesson', 'Look at the sky! It ___ rain.', array['is going to','''s going to']::text[], 'Anna voit un signe maintenant (le ciel est très sombre) : la pluie va arriver. Pour une prédiction fondée sur ce qu''on voit, on utilise be going to : It is going to rain.', 2, '{"id": "en.l39.e04", "unitIds": ["en.g26.will_vs_going_to", "en.g25.going_to"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme du futur.", "context": "The sky is very dark. Anna looks out of the window.", "prompt": "Look at the sky! It ___ rain.", "promptLanguage": "en", "options": ["is going to", "will", "are going to", "going to"], "answer": "is going to", "acceptedAnswers": ["is going to", "''s going to"], "hint": "Anna voit quelque chose en ce moment, et cela lui montre ce qui va arriver.", "explanation": "Anna voit un signe maintenant (le ciel est très sombre) : la pluie va arriver. Pour une prédiction fondée sur ce qu''on voit, on utilise be going to : It is going to rain.", "tip": "Je vois un signe maintenant : going to.", "extraExample": {"text": "Look at the time! We''re going to be late.", "translation": "Regarde l''heure ! Nous allons être en retard."}, "errorPatterns": [{"equals": "will", "category": "grammar", "feedback": "Anna voit le ciel sombre en ce moment : c''est un signe visible. Pour une prédiction avec un signe, on utilise be going to."}, {"equals": "are going to", "category": "conjugation", "feedback": "Avec it, be devient is : It is going to rain."}, {"equals": "going to", "category": "grammar", "feedback": "Il manque is devant going to : It is going to rain."}], "pool": "lesson", "lessonId": "en.l39", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l39.e05', 'en', 'en.l39', 'en.g26.will_vs_going_to', array['en.g26.will_vs_going_to','en.v.probably']::text[], 'fill_blank', 'lesson', 'Tom ___ probably be late.', array['will','''ll','is going to','''s going to']::text[], 'Probably annonce une supposition, pas un projet : on utilise will. Probably se place entre will et le verbe : Tom will probably be late.', 3, '{"id": "en.l39.e05", "unitIds": ["en.g26.will_vs_going_to", "en.v.probably"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le bon mot.", "prompt": "Tom ___ probably be late.", "promptLanguage": "en", "options": ["will", "is", "does", "going to"], "answer": "will", "acceptedAnswers": ["will", "''ll", "is going to", "''s going to"], "hint": "Probably exprime une supposition sur le futur. Il se place juste avant be.", "explanation": "Probably annonce une supposition, pas un projet : on utilise will. Probably se place entre will et le verbe : Tom will probably be late.", "tip": "Probably, I think, I hope, I guess : on utilise surtout will.", "extraExample": {"text": "Anna will probably call you tonight.", "translation": "Anna t''appellera probablement ce soir."}, "errorPatterns": [{"equals": "is", "category": "grammar", "feedback": "Is ne peut pas être suivi de probably be late pour parler du futur. Une supposition sur le futur se fait avec will."}, {"equals": "does", "category": "grammar", "feedback": "Does sert au présent simple (does not…). Pour une supposition sur le futur, on utilise will."}, {"equals": "going to", "category": "grammar", "feedback": "Going to a besoin de be (is going to). Pour une supposition avec probably, on utilise plutôt will."}], "pool": "lesson", "lessonId": "en.l39", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l39.e06', 'en', 'en.l39', 'en.g26.will_vs_going_to', array['en.g26.will_vs_going_to','en.v.hope']::text[], 'reorder', 'lesson', 'J''espère que tu aimeras le cadeau.', array['I hope you will like the present']::text[], 'On espère quelque chose qui n''est pas encore sûr : après I hope, on utilise will + verbe de base. I hope you will like the present veut dire « j''espère que tu aimeras le cadeau ».', 3, '{"id": "en.l39.e06", "unitIds": ["en.g26.will_vs_going_to", "en.v.hope"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "J''espère que tu aimeras le cadeau.", "promptLanguage": "fr", "tokens": ["hope", "I", "the", "you", "like", "present", "will"], "answer": "I hope you will like the present", "acceptedAnswers": ["I hope you will like the present"], "hint": "I hope ouvre la phrase. Will se place juste après you.", "explanation": "On espère quelque chose qui n''est pas encore sûr : après I hope, on utilise will + verbe de base. I hope you will like the present veut dire « j''espère que tu aimeras le cadeau ».", "tip": "I hope + sujet + will + verbe de base.", "extraExample": {"text": "I hope Anna will come to the party.", "translation": "J''espère qu''Anna viendra à la fête."}, "pool": "lesson", "lessonId": "en.l39", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l39.e07', 'en', 'en.l39', 'en.g26.will_vs_going_to', array['en.g26.will_vs_going_to','en.v.idea']::text[], 'translation', 'lesson', 'C''est une bonne idée, je viendrai avec toi.', array['That''s a good idea, I will come with you','That is a good idea, I will come with you','It''s a good idea, I will come with you','Good idea, I will come with you','That''s a good idea, I am going to come with you','That''s a good idea, I am coming with you','That''s a good idea, I will go with you']::text[], 'Tu décides sur le moment, juste après avoir entendu l''idée : c''est une décision spontanée, donc will + verbe de base : I will come.', 3, '{"id": "en.l39.e07", "unitIds": ["en.g26.will_vs_going_to", "en.v.idea"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "C''est une bonne idée, je viendrai avec toi.", "promptLanguage": "fr", "answer": "That''s a good idea, I will come with you", "acceptedAnswers": ["That''s a good idea, I will come with you", "That is a good idea, I will come with you", "It''s a good idea, I will come with you", "Good idea, I will come with you", "That''s a good idea, I am going to come with you", "That''s a good idea, I am coming with you", "That''s a good idea, I will go with you"], "hint": "Tu décides à l''instant, en réponse à une idée : quel mot du futur ?", "explanation": "Tu décides sur le moment, juste après avoir entendu l''idée : c''est une décision spontanée, donc will + verbe de base : I will come.", "tip": "Réaction immédiate à une idée ou à un problème : I''ll + verbe de base.", "extraExample": {"text": "Good idea! I''ll bring the cake.", "translation": "Bonne idée ! J''apporterai le gâteau."}, "errorPatterns": [{"contains": "will to come", "category": "grammar", "feedback": "Après will, on ne met pas to : I will come."}, {"contains": "an good idea", "category": "grammar", "feedback": "Devant good, qui commence par une consonne, on dit a : a good idea."}, {"contains": "idea i come", "category": "verb_tense", "feedback": "Pour une décision à l''instant, le présent simple ne convient pas : I will come with you."}], "pool": "lesson", "lessonId": "en.l39", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l39.e08', 'en', 'en.l39', 'en.g26.will_vs_going_to', array['en.g26.will_vs_going_to','en.v.guess']::text[], 'translation', 'lesson', 'Je suppose qu''il sera en retard.', array['I guess he will be late','I guess that he will be late','I guess he is going to be late','I suppose he will be late','I think he will be late','I think he is going to be late']::text[], 'I guess annonce une supposition : on utilise will + be. He will be late veut dire « il sera en retard ». Après will, be reste à la forme de base.', 3, '{"id": "en.l39.e08", "unitIds": ["en.g26.will_vs_going_to", "en.v.guess"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Je suppose qu''il sera en retard.", "promptLanguage": "fr", "answer": "I guess he will be late", "acceptedAnswers": ["I guess he will be late", "I guess that he will be late", "I guess he is going to be late", "I suppose he will be late", "I think he will be late", "I think he is going to be late"], "hint": "« Je suppose que » se dit I guess. Pour le futur de être, on dit will be.", "explanation": "I guess annonce une supposition : on utilise will + be. He will be late veut dire « il sera en retard ». Après will, be reste à la forme de base.", "tip": "I guess / I think + sujet + will + verbe de base.", "extraExample": {"text": "I guess Tom will be home soon.", "translation": "Je suppose que Tom sera bientôt à la maison."}, "errorPatterns": [{"contains": "will to be", "category": "grammar", "feedback": "Après will, on ne met pas to : he will be late."}, {"contains": "wills be", "category": "conjugation", "feedback": "Will ne prend jamais de -s : he will be late."}, {"contains": "will is", "category": "grammar", "feedback": "Après will, on met be (forme de base), pas is : he will be late."}], "pool": "lesson", "lessonId": "en.l39", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l39.e09', 'en', 'en.l39', 'en.g26.will_vs_going_to', array['en.g26.will_vs_going_to','en.g25.going_to']::text[], 'free_answer', 'lesson', 'Comment dit-on « Il va dormir. » ?', array['He is going to sleep','He is going to go to sleep','He is going to go to bed','He is going to have a sleep']::text[], 'On voit un signe maintenant (Tom est très fatigué) : on prédit ce qui va arriver avec be going to. Avec he, be devient is : He is going to sleep.', 3, '{"id": "en.l39.e09", "unitIds": ["en.g26.will_vs_going_to", "en.g25.going_to"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "context": "Look at Tom! He is very tired.", "prompt": "Comment dit-on « Il va dormir. » ?", "promptLanguage": "fr", "answer": "He is going to sleep", "acceptedAnswers": ["He is going to sleep", "He is going to go to sleep", "He is going to go to bed", "He is going to have a sleep"], "hint": "On voit que Tom est très fatigué : un signe visible annonce ce qui va arriver.", "explanation": "On voit un signe maintenant (Tom est très fatigué) : on prédit ce qui va arriver avec be going to. Avec he, be devient is : He is going to sleep.", "tip": "Je vois un signe maintenant : be + going to + verbe de base.", "extraExample": {"text": "Look! The dog is going to run.", "translation": "Regarde ! Le chien va courir."}, "errorPatterns": [{"equals": "he will sleep", "category": "grammar", "feedback": "Tu vois que Tom est très fatigué : c''est un signe visible. Pour une prédiction avec un signe, on utilise be going to : He is going to sleep."}, {"contains": "he going to", "category": "grammar", "feedback": "Il manque is devant going to : He is going to sleep."}, {"contains": "going to sleeps", "category": "conjugation", "feedback": "Après going to, le verbe reste à la forme de base : going to sleep."}], "pool": "lesson", "lessonId": "en.l39", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l39.e10', 'en', 'en.l39', 'en.g26.will_vs_going_to', array['en.g26.will_vs_going_to','en.g24.will_future','en.g25.going_to']::text[], 'free_answer', 'lesson', 'Écris ton projet, puis une promesse.', array['I''m going to learn French. I will help you tomorrow.','We''re going to move next week. I promise I will call you.','Anna is going to change her job. I won''t forget your birthday.']::text[], 'Un projet déjà décidé se dit avec be going to + verbe de base. Une promesse ou une proposition faite maintenant se dit avec will + verbe de base. Par exemple : I''m going to learn French. I will help you tomorrow.', 4, '{"id": "en.l39.e10", "unitIds": ["en.g26.will_vs_going_to", "en.g24.will_future", "en.g25.going_to"], "type": "free_answer", "difficulty": 4, "instruction": "Écris deux phrases en anglais : un projet déjà décidé avec going to, puis une promesse ou une proposition avec will.", "prompt": "Écris ton projet, puis une promesse.", "promptLanguage": "fr", "requirements": {"mustInclude": [["going to"], ["will", "''ll", "won''t"]], "minWords": 8}, "answer": "I''m going to learn French. I will help you tomorrow.", "acceptedAnswers": ["I''m going to learn French. I will help you tomorrow.", "We''re going to move next week. I promise I will call you.", "Anna is going to change her job. I won''t forget your birthday."], "hint": "Première phrase : I''m going to + verbe (ton projet). Deuxième phrase : I will + verbe (ta promesse).", "explanation": "Un projet déjà décidé se dit avec be going to + verbe de base. Une promesse ou une proposition faite maintenant se dit avec will + verbe de base. Par exemple : I''m going to learn French. I will help you tomorrow.", "tip": "Projet déjà décidé : going to. Promesse ou proposition : will.", "extraExample": {"text": "I''m going to visit my mother. I''ll call you later.", "translation": "Je vais rendre visite à ma mère. Je t''appellerai plus tard."}, "errorPatterns": [{"contains": "will going to", "category": "grammar", "feedback": "On choisit will ou going to, jamais les deux ensemble dans la même phrase."}, {"contains": "will to", "category": "grammar", "feedback": "Après will, on ne met pas to : le verbe de base suit directement."}], "pool": "lesson", "lessonId": "en.l39", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l40.e01', 'en', 'en.l40', 'en.g27.present_continuous_future', array['en.g27.present_continuous_future','en.v.dentist']::text[], 'mcq', 'lesson', 'I ___ the dentist tomorrow.', array['am seeing']::text[], 'Pour un rendez-vous déjà fixé, on utilise le présent continu avec un moment du futur : I am seeing the dentist tomorrow. Le présent simple ne convient pas pour un rendez-vous personnel.', 1, '{"id": "en.l40.e01", "unitIds": ["en.g27.present_continuous_future", "en.v.dentist"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "I ___ the dentist tomorrow.", "promptLanguage": "en", "options": ["am seeing", "see", "seeing", "am see"], "answer": "am seeing", "acceptedAnswers": ["am seeing"], "hint": "Le rendez-vous est déjà fixé : be, puis le verbe avec -ing.", "explanation": "Pour un rendez-vous déjà fixé, on utilise le présent continu avec un moment du futur : I am seeing the dentist tomorrow. Le présent simple ne convient pas pour un rendez-vous personnel.", "tip": "Rendez-vous fixé : be + verbe en -ing + tomorrow.", "extraExample": {"text": "Anna is seeing the doctor tonight.", "translation": "Anna voit le médecin ce soir."}, "errorPatterns": [{"equals": "see", "category": "verb_tense", "feedback": "Pour un rendez-vous personnel déjà fixé, on n''utilise pas le présent simple : on dit I am seeing."}, {"equals": "seeing", "category": "grammar", "feedback": "Il manque be devant seeing : I am seeing the dentist tomorrow."}, {"equals": "am see", "category": "grammar", "feedback": "Après am, le verbe prend -ing : I am seeing."}], "pool": "lesson", "lessonId": "en.l40", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l40.e02', 'en', 'en.l40', 'en.g27.present_continuous_future', array['en.g27.present_continuous_future','en.g24.will_future']::text[], 'mcq', 'lesson', 'Comment dit-on « Il pleuvra demain. » en anglais ?', array['It will rain tomorrow.']::text[], 'Le présent continu sert à parler d''un projet organisé. La pluie est une simple prédiction : on utilise will (ou going to) : It will rain tomorrow.', 2, '{"id": "en.l40.e02", "unitIds": ["en.g27.present_continuous_future", "en.g24.will_future"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Il pleuvra demain. » en anglais ?", "promptLanguage": "fr", "options": ["It will rain tomorrow.", "It''s raining tomorrow.", "It rains tomorrow.", "It is rain tomorrow."], "answer": "It will rain tomorrow.", "acceptedAnswers": ["It will rain tomorrow."], "hint": "Personne n''a organisé la pluie : c''est une prédiction, pas un rendez-vous.", "explanation": "Le présent continu sert à parler d''un projet organisé. La pluie est une simple prédiction : on utilise will (ou going to) : It will rain tomorrow.", "tip": "Présent continu = rendez-vous ou projet organisé. Prédiction = will ou going to.", "extraExample": {"text": "It will be cold tonight.", "translation": "Il fera froid cette nuit."}, "errorPatterns": [{"equals": "it is raining tomorrow", "category": "verb_tense", "feedback": "Le présent continu parle d''un projet organisé. Pour la météo de demain, c''est une prédiction : It will rain tomorrow."}, {"equals": "it rains tomorrow", "category": "verb_tense", "feedback": "Le présent simple ne convient pas pour une prédiction. Utilise will : It will rain tomorrow."}, {"equals": "it is rain tomorrow", "category": "grammar", "feedback": "Is ne s''emploie pas avec le verbe de base rain. Pour une prédiction, on dit It will rain."}], "pool": "lesson", "lessonId": "en.l40", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l40.e03', 'en', 'en.l40', 'en.g27.present_continuous_future', array['en.g27.present_continuous_future','en.v.appointment','en.v.meeting','en.v.dentist','en.v.doctor','en.v.flight']::text[], 'match', 'lesson', 'Les mots de l''agenda : an appointment, a meeting, a dentist, a doctor, a flight', '{}'::text[], 'Appointment est un rendez-vous chez un professionnel (médecin, dentiste). Meeting est une réunion, souvent au travail. On dit an appointment avec an, car appointment commence par un son de voyelle.', 1, '{"id": "en.l40.e03", "unitIds": ["en.g27.present_continuous_future", "en.v.appointment", "en.v.meeting", "en.v.dentist", "en.v.doctor", "en.v.flight"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les mots de l''agenda : an appointment, a meeting, a dentist, a doctor, a flight", "promptLanguage": "fr", "pairs": [{"left": "an appointment", "right": "un rendez-vous (médical, administratif)"}, {"left": "a meeting", "right": "une réunion"}, {"left": "a dentist", "right": "un dentiste"}, {"left": "a doctor", "right": "un médecin"}, {"left": "a flight", "right": "un vol"}], "answer": "an appointment = un rendez-vous (médical, administratif) ; a meeting = une réunion ; a dentist = un dentiste ; a doctor = un médecin ; a flight = un vol", "acceptedAnswers": [], "explanation": "Appointment est un rendez-vous chez un professionnel (médecin, dentiste). Meeting est une réunion, souvent au travail. On dit an appointment avec an, car appointment commence par un son de voyelle.", "tip": "Rendez-vous chez le médecin : appointment. Réunion de travail : meeting.", "extraExample": {"text": "I have an appointment at ten.", "translation": "J''ai un rendez-vous à dix heures."}, "pool": "lesson", "lessonId": "en.l40", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l40.e04', 'en', 'en.l40', 'en.g27.present_continuous_future', array['en.g27.present_continuous_future','en.v.meeting']::text[], 'fill_blank', 'lesson', 'Anna is ___ her colleagues at the office tomorrow.', array['meeting']::text[], 'Le présent continu se forme avec be + verbe en -ing : Anna is meeting. Avec un moment du futur (tomorrow), il parle d''un projet déjà fixé.', 2, '{"id": "en.l40.e04", "unitIds": ["en.g27.present_continuous_future", "en.v.meeting"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le verbe « retrouver » (meet) à la bonne forme.", "context": "Anna and her colleagues have a meeting at the office tomorrow.", "prompt": "Anna is ___ her colleagues at the office tomorrow.", "promptLanguage": "en", "options": ["meeting", "meet", "meets", "met"], "answer": "meeting", "acceptedAnswers": ["meeting"], "hint": "Après is, le verbe prend une terminaison particulière.", "explanation": "Le présent continu se forme avec be + verbe en -ing : Anna is meeting. Avec un moment du futur (tomorrow), il parle d''un projet déjà fixé.", "tip": "Be + -ing + moment du futur : le projet est déjà organisé.", "extraExample": {"text": "We''re meeting Tom at six.", "translation": "Nous retrouvons Tom à six heures."}, "errorPatterns": [{"equals": "meet", "category": "grammar", "feedback": "Après is, le verbe prend -ing : is meeting."}, {"equals": "meets", "category": "conjugation", "feedback": "Après is, on n''ajoute pas -s : le verbe prend -ing, is meeting."}, {"equals": "met", "category": "verb_tense", "feedback": "Met est le passé. Pour un projet fixé, on utilise be + -ing : is meeting."}], "pool": "lesson", "lessonId": "en.l40", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l40.e05', 'en', 'en.l40', 'en.g27.present_continuous_future', array['en.g27.present_continuous_future','en.v.appointment','en.v.dentist']::text[], 'fill_blank', 'lesson', 'Tom ___ working tomorrow. He has an appointment with the dentist.', array['isn''t','is not']::text[], 'Le présent continu se nie avec be + not : Tom isn''t working tomorrow. On n''emploie ni doesn''t ni won''t devant un verbe en -ing.', 3, '{"id": "en.l40.e05", "unitIds": ["en.g27.present_continuous_future", "en.v.appointment", "en.v.dentist"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le bon mot.", "prompt": "Tom ___ working tomorrow. He has an appointment with the dentist.", "promptLanguage": "en", "options": ["isn''t", "doesn''t", "won''t", "not"], "answer": "isn''t", "acceptedAnswers": ["isn''t", "is not"], "hint": "Le verbe working a une terminaison -ing : quel auxiliaire l''accompagne, avec la négation ?", "explanation": "Le présent continu se nie avec be + not : Tom isn''t working tomorrow. On n''emploie ni doesn''t ni won''t devant un verbe en -ing.", "tip": "Négation du présent continu : isn''t / aren''t / I''m not + -ing.", "extraExample": {"text": "We aren''t having lunch with Tom today.", "translation": "Nous ne déjeunons pas avec Tom aujourd''hui."}, "errorPatterns": [{"equals": "does not", "category": "grammar", "feedback": "Doesn''t est suivi du verbe de base, pas du -ing. Avec working, il faut be + not : isn''t working."}, {"equals": "will not", "category": "grammar", "feedback": "Won''t est suivi du verbe de base, pas du -ing. Avec working, il faut isn''t : Tom isn''t working."}, {"equals": "not", "category": "grammar", "feedback": "Not seul ne suffit pas : il faut be + not, donc isn''t."}], "pool": "lesson", "lessonId": "en.l40", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l40.e06', 'en', 'en.l40', 'en.g27.present_continuous_future', array['en.g27.present_continuous_future','en.v.doctor']::text[], 'reorder', 'lesson', 'Tom voit le médecin demain matin.', array['Tom is seeing the doctor tomorrow morning','Tomorrow morning Tom is seeing the doctor']::text[], 'On utilise be + verbe en -ing pour un rendez-vous fixé : Tom is seeing the doctor. Le moment (tomorrow morning) se place à la fin ou au début.', 3, '{"id": "en.l40.e06", "unitIds": ["en.g27.present_continuous_future", "en.v.doctor"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Tom voit le médecin demain matin.", "promptLanguage": "fr", "tokens": ["doctor", "Tom", "morning", "the", "seeing", "is", "tomorrow"], "answer": "Tom is seeing the doctor tomorrow morning", "acceptedAnswers": ["Tom is seeing the doctor tomorrow morning", "Tomorrow morning Tom is seeing the doctor"], "hint": "Be se place juste après le sujet, suivi du verbe en -ing.", "explanation": "On utilise be + verbe en -ing pour un rendez-vous fixé : Tom is seeing the doctor. Le moment (tomorrow morning) se place à la fin ou au début.", "tip": "Sujet + be + -ing + complément + moment du futur.", "extraExample": {"text": "I''m meeting my colleagues at six.", "translation": "Je retrouve mes collègues à six heures."}, "pool": "lesson", "lessonId": "en.l40", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l40.e07', 'en', 'en.l40', 'en.g27.present_continuous_future', array['en.g27.present_continuous_future','en.v.dentist']::text[], 'translation', 'lesson', 'Je vois le dentiste demain.', array['I am seeing the dentist tomorrow','Tomorrow I am seeing the dentist','I am meeting the dentist tomorrow','I am going to see the dentist tomorrow','I am going to the dentist tomorrow','I am going to the dentist''s tomorrow','I will see the dentist tomorrow','I have an appointment with the dentist tomorrow','I have a dentist appointment tomorrow']::text[], 'Pour un rendez-vous fixé, on utilise be + verbe en -ing avec un moment du futur : I am seeing the dentist tomorrow. On peut aussi dire I am meeting the dentist.', 3, '{"id": "en.l40.e07", "unitIds": ["en.g27.present_continuous_future", "en.v.dentist"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Je vois le dentiste demain.", "promptLanguage": "fr", "answer": "I am seeing the dentist tomorrow", "acceptedAnswers": ["I am seeing the dentist tomorrow", "Tomorrow I am seeing the dentist", "I am meeting the dentist tomorrow", "I am going to see the dentist tomorrow", "I am going to the dentist tomorrow", "I am going to the dentist''s tomorrow", "I will see the dentist tomorrow", "I have an appointment with the dentist tomorrow", "I have a dentist appointment tomorrow"], "hint": "Un rendez-vous déjà fixé se dit avec be + un verbe en -ing.", "explanation": "Pour un rendez-vous fixé, on utilise be + verbe en -ing avec un moment du futur : I am seeing the dentist tomorrow. On peut aussi dire I am meeting the dentist.", "tip": "Rendez-vous fixé = be + -ing + tomorrow, pas de présent simple.", "extraExample": {"text": "I''m seeing the doctor at nine.", "translation": "Je vois le médecin à neuf heures."}, "errorPatterns": [{"contains": "i see the dentist", "category": "verb_tense", "feedback": "Pour un rendez-vous fixé, on n''utilise pas le présent simple : I am seeing the dentist tomorrow."}, {"contains": "am see", "category": "grammar", "feedback": "Après am, le verbe prend -ing : I am seeing."}, {"contains": "i seeing", "category": "grammar", "feedback": "Il manque am devant seeing : I am seeing the dentist."}], "pool": "lesson", "lessonId": "en.l40", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l40.e08', 'en', 'en.l40', 'en.g27.present_continuous_future', array['en.g27.present_continuous_future']::text[], 'translation', 'lesson', 'Qu''est-ce que tu fais demain soir ?', array['What are you doing tomorrow evening','What are you doing tomorrow night','What are you going to do tomorrow evening','What are you going to do tomorrow night','What will you do tomorrow evening','What will you do tomorrow night']::text[], 'Pour demander les projets de quelqu''un, on utilise le présent continu avec un moment du futur : What are you doing tomorrow evening ? On place are avant you.', 3, '{"id": "en.l40.e08", "unitIds": ["en.g27.present_continuous_future"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Qu''est-ce que tu fais demain soir ?", "promptLanguage": "fr", "answer": "What are you doing tomorrow evening", "acceptedAnswers": ["What are you doing tomorrow evening", "What are you doing tomorrow night", "What are you going to do tomorrow evening", "What are you going to do tomorrow night", "What will you do tomorrow evening", "What will you do tomorrow night"], "hint": "Pour demander ce que quelqu''un a prévu, on utilise be + -ing : quelle forme de be avec you ?", "explanation": "Pour demander les projets de quelqu''un, on utilise le présent continu avec un moment du futur : What are you doing tomorrow evening ? On place are avant you.", "tip": "What are you doing + moment du futur ? : la question classique sur l''agenda.", "extraExample": {"text": "What is Anna doing tonight?", "translation": "Qu''est-ce qu''Anna fait ce soir ?"}, "errorPatterns": [{"contains": "do you doing", "category": "grammar", "feedback": "Le présent continu se fait avec be, pas avec do : What are you doing ?"}, {"contains": "are you do", "category": "grammar", "feedback": "Après are you, le verbe prend -ing : What are you doing ?"}, {"contains": "what you doing", "category": "word_order", "feedback": "Il manque are : What are you doing tomorrow evening ?"}], "pool": "lesson", "lessonId": "en.l40", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l40.e09', 'en', 'en.l40', 'en.g27.present_continuous_future', array['en.g27.present_continuous_future','en.v.flight']::text[], 'free_answer', 'lesson', 'Comment dit-on « Mes parents prennent un vol pour Paris demain. » ?', array['My parents are taking a flight to Paris tomorrow','Tomorrow my parents are taking a flight to Paris','My parents are flying to Paris tomorrow','My parents are going to Paris tomorrow','My parents have a flight to Paris tomorrow','My parents are going to take a flight to Paris tomorrow','My parents will take a flight to Paris tomorrow']::text[], 'Un voyage déjà organisé se dit avec be + verbe en -ing : My parents are taking a flight. Avec my parents (they), be devient are. Pour Paris, on dit to Paris.', 3, '{"id": "en.l40.e09", "unitIds": ["en.g27.present_continuous_future", "en.v.flight"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Mes parents prennent un vol pour Paris demain. » ?", "promptLanguage": "fr", "answer": "My parents are taking a flight to Paris tomorrow", "acceptedAnswers": ["My parents are taking a flight to Paris tomorrow", "Tomorrow my parents are taking a flight to Paris", "My parents are flying to Paris tomorrow", "My parents are going to Paris tomorrow", "My parents have a flight to Paris tomorrow", "My parents are going to take a flight to Paris tomorrow", "My parents will take a flight to Paris tomorrow"], "hint": "My parents se remplace par they : quelle forme de be, suivie d''un verbe en -ing ?", "explanation": "Un voyage déjà organisé se dit avec be + verbe en -ing : My parents are taking a flight. Avec my parents (they), be devient are. Pour Paris, on dit to Paris.", "tip": "Voyage organisé = be + -ing + moment du futur.", "extraExample": {"text": "Anna is taking a flight to London tonight.", "translation": "Anna prend un vol pour Londres ce soir."}, "errorPatterns": [{"contains": "parents is", "category": "conjugation", "feedback": "Parents est au pluriel : on dit my parents are."}, {"contains": "parents taking", "category": "grammar", "feedback": "Il manque are devant taking : My parents are taking a flight."}, {"contains": "flight in paris", "category": "preposition", "feedback": "Pour aller vers une ville, on dit to : a flight to Paris."}], "pool": "lesson", "lessonId": "en.l40", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l40.e10', 'en', 'en.l40', 'en.g27.present_continuous_future', array['en.g27.present_continuous_future','en.v.meeting','en.v.appointment']::text[], 'free_answer', 'lesson', 'Que fais-tu demain ? Un rendez-vous, une réunion, un vol… Écris une phrase.', array['I''m seeing the dentist tomorrow morning.','We''re having a meeting tomorrow.','Anna is seeing the doctor tonight.','I''m meeting my colleagues next week.']::text[], 'Pour un rendez-vous ou une réunion déjà fixés, on utilise be + verbe en -ing avec un moment du futur. Par exemple : I''m seeing the dentist tomorrow morning.', 4, '{"id": "en.l40.e10", "unitIds": ["en.g27.present_continuous_future", "en.v.meeting", "en.v.appointment"], "type": "free_answer", "difficulty": 4, "instruction": "Écris une phrase en anglais avec le présent continu (be + -ing) et tomorrow, tonight ou next week.", "prompt": "Que fais-tu demain ? Un rendez-vous, une réunion, un vol… Écris une phrase.", "promptLanguage": "fr", "requirements": {"mustInclude": [["tomorrow", "tonight", "next week", "next weekend"]], "minWords": 5}, "answer": "I''m seeing the dentist tomorrow morning.", "acceptedAnswers": ["I''m seeing the dentist tomorrow morning.", "We''re having a meeting tomorrow.", "Anna is seeing the doctor tonight.", "I''m meeting my colleagues next week."], "hint": "Commence par I''m + verbe en -ing (seeing, meeting, having…), puis ajoute ton moment du futur.", "explanation": "Pour un rendez-vous ou une réunion déjà fixés, on utilise be + verbe en -ing avec un moment du futur. Par exemple : I''m seeing the dentist tomorrow morning.", "tip": "Be + -ing + tomorrow : ton agenda se dit au présent continu.", "extraExample": {"text": "We''re having a meeting next week.", "translation": "Nous avons une réunion la semaine prochaine."}, "errorPatterns": [{"contains": "am meet", "category": "grammar", "feedback": "Après am, le verbe prend -ing : I am meeting."}, {"contains": "am see", "category": "grammar", "feedback": "Après am, le verbe prend -ing : I am seeing."}], "pool": "lesson", "lessonId": "en.l40", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l41.e01', 'en', 'en.l41', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.garden']::text[], 'mcq', 'lesson', 'Comment dit-on « Il y a un jardin. » en anglais ?', array['There is a garden.']::text[], '« Il y a » se dit there is devant un seul élément. Ici il y a un seul jardin, donc There is a garden.', 1, '{"id": "en.l41.e01", "unitIds": ["en.g28.there_is_are", "en.v.garden"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Il y a un jardin. » en anglais ?", "promptLanguage": "fr", "options": ["There is a garden.", "There have a garden.", "It is a garden.", "There are a garden."], "answer": "There is a garden.", "acceptedAnswers": ["There is a garden."], "hint": "« Il y a » + un seul élément : there + is.", "explanation": "« Il y a » se dit there is devant un seul élément. Ici il y a un seul jardin, donc There is a garden.", "tip": "« Il y a » = there is (un seul) ; on n''utilise jamais have.", "extraExample": {"text": "There is a phone in my bag.", "translation": "Il y a un téléphone dans mon sac."}, "errorPatterns": [{"equals": "there have a garden", "category": "grammar", "feedback": "En anglais, « il y a » ne se dit pas avec have. On utilise there is (un seul) ou there are (plusieurs)."}, {"equals": "it is a garden", "category": "grammar", "feedback": "It is a garden veut dire « c''est un jardin ». Pour « il y a », on commence par there is."}, {"equals": "there are a garden", "category": "grammar", "feedback": "There are s''utilise avec plusieurs éléments. Pour un seul jardin, on dit there is."}], "pool": "lesson", "lessonId": "en.l41", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l41.e02', 'en', 'en.l41', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.bedroom']::text[], 'mcq', 'lesson', 'There ___ two bedrooms in the house.', array['are']::text[], 'Two bedrooms est un pluriel : on dit there are. Le verbe s''accorde avec ce qui vient après there (two bedrooms), pas avec there lui-même.', 2, '{"id": "en.l41.e02", "unitIds": ["en.g28.there_is_are", "en.v.bedroom"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme.", "prompt": "There ___ two bedrooms in the house.", "promptLanguage": "en", "options": ["are", "is", "have", "has"], "answer": "are", "acceptedAnswers": ["are"], "hint": "Deux chambres : un seul élément ou plusieurs ?", "explanation": "Two bedrooms est un pluriel : on dit there are. Le verbe s''accorde avec ce qui vient après there (two bedrooms), pas avec there lui-même.", "tip": "Regarde ce qui suit there : un seul → is, plusieurs → are.", "extraExample": {"text": "There are three bathrooms in this hotel.", "translation": "Il y a trois salles de bain dans cet hôtel."}, "errorPatterns": [{"equals": "is", "category": "grammar", "feedback": "There is s''utilise devant un seul élément. Ici, two bedrooms est un pluriel : there are."}, {"equals": "have", "category": "grammar", "feedback": "Pour dire « il y a », on n''utilise pas have. On dit there is ou there are."}, {"equals": "has", "category": "grammar", "feedback": "Pour dire « il y a », on n''utilise pas has. Avec un pluriel, on dit there are."}], "pool": "lesson", "lessonId": "en.l41", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l41.e03', 'en', 'en.l41', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.kitchen','en.v.bedroom','en.v.bathroom','en.v.living_room','en.v.garden']::text[], 'match', 'lesson', 'Les pièces de la maison', '{}'::text[], 'On cuisine dans la kitchen, on dort dans la bedroom, on se lave dans la bathroom et on se détend dans la living room. Le garden est à l''extérieur de la maison. Bathroom = bath (bain) + room (pièce).', 1, '{"id": "en.l41.e03", "unitIds": ["en.g28.there_is_are", "en.v.kitchen", "en.v.bedroom", "en.v.bathroom", "en.v.living_room", "en.v.garden"], "type": "match", "difficulty": 1, "instruction": "Associe chaque pièce à sa traduction.", "prompt": "Les pièces de la maison", "promptLanguage": "fr", "pairs": [{"left": "kitchen", "right": "cuisine"}, {"left": "bedroom", "right": "chambre"}, {"left": "bathroom", "right": "salle de bain"}, {"left": "living room", "right": "salon"}, {"left": "garden", "right": "jardin"}], "answer": "kitchen = cuisine ; bedroom = chambre ; bathroom = salle de bain ; living room = salon ; garden = jardin", "acceptedAnswers": [], "explanation": "On cuisine dans la kitchen, on dort dans la bedroom, on se lave dans la bathroom et on se détend dans la living room. Le garden est à l''extérieur de la maison. Bathroom = bath (bain) + room (pièce).", "tip": "Bed + room = chambre (la pièce du lit) ; bath + room = salle de bain.", "extraExample": {"text": "There is a garden near the house.", "translation": "Il y a un jardin près de la maison."}, "pool": "lesson", "lessonId": "en.l41", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l41.e04', 'en', 'en.l41', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.garden']::text[], 'fill_blank', 'lesson', 'There ___ a dog in the garden.', array['is']::text[], 'A dog est un seul chien : on utilise there is. On ne dit jamais « there have » pour « il y a ».', 2, '{"id": "en.l41.e04", "unitIds": ["en.g28.there_is_are", "en.v.garden"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec is, are ou have.", "prompt": "There ___ a dog in the garden.", "promptLanguage": "en", "options": ["is", "are", "have"], "answer": "is", "acceptedAnswers": ["is"], "hint": "Combien de chiens ? Regarde l''article a.", "explanation": "A dog est un seul chien : on utilise there is. On ne dit jamais « there have » pour « il y a ».", "tip": "A devant le nom ? There is. Un nombre ou -s ? There are.", "extraExample": {"text": "There is a book in the bedroom.", "translation": "Il y a un livre dans la chambre."}, "errorPatterns": [{"equals": "are", "category": "grammar", "feedback": "There are s''utilise avec plusieurs éléments. A dog est un seul chien : there is."}, {"equals": "have", "category": "grammar", "feedback": "« Il y a » ne se traduit pas par have. On dit there is (un seul) ou there are (plusieurs)."}], "pool": "lesson", "lessonId": "en.l41", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l41.e05', 'en', 'en.l41', 'en.g28.there_is_are', array['en.g28.there_is_are','en.g04.be_negative_questions']::text[], 'fill_blank', 'lesson', 'There ___ a garden at the hotel, but there is a beach.', array['isn''t','is not']::text[], 'Pour dire « il n''y a pas », on ajoute not après is : there isn''t. Ici, a garden est un seul élément, donc isn''t (et non aren''t).', 2, '{"id": "en.l41.e05", "unitIds": ["en.g28.there_is_are", "en.g04.be_negative_questions"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la forme négative.", "prompt": "There ___ a garden at the hotel, but there is a beach.", "promptLanguage": "en", "options": ["isn''t", "aren''t", "haven''t"], "answer": "isn''t", "acceptedAnswers": ["isn''t", "is not"], "hint": "« But » annonce un contraste : il n''y a pas de jardin.", "explanation": "Pour dire « il n''y a pas », on ajoute not après is : there isn''t. Ici, a garden est un seul élément, donc isn''t (et non aren''t).", "tip": "Négation : there isn''t (un seul) / there aren''t (plusieurs).", "extraExample": {"text": "There isn''t a bathroom in the house.", "translation": "Il n''y a pas de salle de bain dans la maison."}, "errorPatterns": [{"equals": "aren''t", "category": "grammar", "feedback": "There aren''t s''utilise avec plusieurs éléments. A garden est un seul élément : there isn''t."}, {"equals": "are not", "category": "grammar", "feedback": "There are not s''utilise avec plusieurs éléments. A garden est un seul élément : there is not."}, {"equals": "haven''t", "category": "grammar", "feedback": "There haven''t n''existe pas. Pour « il n''y a pas », on dit there isn''t ou there aren''t."}], "pool": "lesson", "lessonId": "en.l41", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l41.e06', 'en', 'en.l41', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.bathroom']::text[], 'reorder', 'lesson', 'Y a-t-il une salle de bain dans la maison ?', array['Is there a bathroom in the house']::text[], 'Pour poser une question avec there is, on inverse : Is there… ? au lieu de There is… Le lieu (in the house) vient en dernier.', 2, '{"id": "en.l41.e06", "unitIds": ["en.g28.there_is_are", "en.v.bathroom"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la question.", "prompt": "Y a-t-il une salle de bain dans la maison ?", "promptLanguage": "fr", "tokens": ["there", "the", "Is", "bathroom", "a", "house", "in"], "answer": "Is there a bathroom in the house", "acceptedAnswers": ["Is there a bathroom in the house"], "hint": "Pour poser la question, is passe avant there.", "explanation": "Pour poser une question avec there is, on inverse : Is there… ? au lieu de There is… Le lieu (in the house) vient en dernier.", "tip": "Question : Is there… ? / Are there… ? (le verbe passe devant there).", "extraExample": {"text": "Is there a kitchen in the apartment?", "translation": "Y a-t-il une cuisine dans l''appartement ?"}, "pool": "lesson", "lessonId": "en.l41", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l41.e07', 'en', 'en.l41', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.kitchen','en.v.living_room']::text[], 'translation', 'lesson', 'Il y a une cuisine et un salon.', array['There is a kitchen and a living room.','There''s a kitchen and a living room.','There is a kitchen and living room.','There is a kitchen and a lounge.','There is a kitchen and a sitting room.']::text[], '« Il y a » se traduit there is devant un élément. On répète a devant chaque nom : a kitchen and a living room. And veut dire « et ».', 2, '{"id": "en.l41.e07", "unitIds": ["en.g28.there_is_are", "en.v.kitchen", "en.v.living_room"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais. « il y a » = there is.", "prompt": "Il y a une cuisine et un salon.", "promptLanguage": "fr", "answer": "There is a kitchen and a living room.", "acceptedAnswers": ["There is a kitchen and a living room.", "There''s a kitchen and a living room.", "There is a kitchen and living room.", "There is a kitchen and a lounge.", "There is a kitchen and a sitting room."], "hint": "Salon = living room (deux mots). N''oublie pas a devant chaque nom.", "explanation": "« Il y a » se traduit there is devant un élément. On répète a devant chaque nom : a kitchen and a living room. And veut dire « et ».", "tip": "Pense « there is » dès que tu vois « il y a ».", "extraExample": {"text": "There is a bedroom and a bathroom.", "translation": "Il y a une chambre et une salle de bain."}, "errorPatterns": [{"contains": "there have", "category": "grammar", "feedback": "« Il y a » ne se dit pas avec have. Écris there is."}, {"contains": "it is a kitchen", "category": "grammar", "feedback": "It is veut dire « c''est ». Pour « il y a », on dit there is."}, {"contains": "there are a", "category": "grammar", "feedback": "There are s''utilise avec un pluriel. Pour un seul élément (a kitchen), on dit there is."}], "pool": "lesson", "lessonId": "en.l41", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l41.e08', 'en', 'en.l41', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.bathroom']::text[], 'translation', 'lesson', 'Il n''y a pas de salle de bain dans la maison.', array['There isn''t a bathroom in the house.','There is not a bathroom in the house.','There''s not a bathroom in the house.','There isn''t any bathroom in the house.','There is no bathroom in the house.','There''s no bathroom in the house.']::text[], '« Il n''y a pas de » se dit there isn''t (there is not) devant un seul élément. On garde a devant bathroom : There isn''t a bathroom.', 3, '{"id": "en.l41.e08", "unitIds": ["en.g28.there_is_are", "en.v.bathroom"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais. Pense à la négation de there is.", "prompt": "Il n''y a pas de salle de bain dans la maison.", "promptLanguage": "fr", "answer": "There isn''t a bathroom in the house.", "acceptedAnswers": ["There isn''t a bathroom in the house.", "There is not a bathroom in the house.", "There''s not a bathroom in the house.", "There isn''t any bathroom in the house.", "There is no bathroom in the house.", "There''s no bathroom in the house."], "hint": "Négation : there + is + not.", "explanation": "« Il n''y a pas de » se dit there isn''t (there is not) devant un seul élément. On garde a devant bathroom : There isn''t a bathroom.", "tip": "Pour nier there is, on ajoute n''t : there isn''t.", "extraExample": {"text": "There isn''t a key in the bag.", "translation": "Il n''y a pas de clé dans le sac."}, "errorPatterns": [{"contains": "there have", "category": "grammar", "feedback": "« Il n''y a pas » ne se dit pas avec have. Écris there isn''t."}, {"contains": "there aren''t a", "category": "grammar", "feedback": "There aren''t s''utilise avec un pluriel. Une seule salle de bain : there isn''t."}, {"equals": "isn''t a bathroom in the house", "category": "grammar", "feedback": "Il manque there au début : there isn''t a bathroom in the house."}], "pool": "lesson", "lessonId": "en.l41", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l41.e09', 'en', 'en.l41', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.garden']::text[], 'free_answer', 'lesson', 'Comment dit-on « Y a-t-il un jardin ? » en anglais ?', array['Is there a garden?','Is there a garden here?']::text[], 'Pour poser la question, on place is avant there : Is there a garden ? Il y a un seul jardin, donc is (et non are).', 3, '{"id": "en.l41.e09", "unitIds": ["en.g28.there_is_are", "en.v.garden"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la question en anglais.", "prompt": "Comment dit-on « Y a-t-il un jardin ? » en anglais ?", "promptLanguage": "fr", "answer": "Is there a garden?", "acceptedAnswers": ["Is there a garden?", "Is there a garden here?"], "hint": "Le verbe is passe devant there.", "explanation": "Pour poser la question, on place is avant there : Is there a garden ? Il y a un seul jardin, donc is (et non are).", "tip": "There is → Is there ? On inverse, comme avec to be.", "extraExample": {"text": "Is there a hotel in the city?", "translation": "Y a-t-il un hôtel dans la ville ?"}, "errorPatterns": [{"equals": "there is a garden", "category": "word_order", "feedback": "Pour poser une question, inverse : is passe devant there. Écris Is there a garden ?"}, {"equals": "have a garden", "category": "grammar", "feedback": "« Y a-t-il » ne se dit pas avec have. Écris Is there a garden ?"}, {"equals": "are there a garden", "category": "grammar", "feedback": "Are there s''utilise avec un pluriel. Un seul jardin : Is there a garden ?"}], "pool": "lesson", "lessonId": "en.l41", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l41.e10', 'en', 'en.l41', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.bedroom']::text[], 'free_answer', 'lesson', 'Comment dit-on « Il y a trois chambres dans la maison. » en anglais ?', array['There are three bedrooms in the house.','There are three bedrooms in this house.','There are 3 bedrooms in the house.']::text[], 'Three bedrooms est un pluriel : on dit there are, et bedroom prend un -s. There are three bedrooms in the house.', 3, '{"id": "en.l41.e10", "unitIds": ["en.g28.there_is_are", "en.v.bedroom"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Il y a trois chambres dans la maison. » en anglais ?", "promptLanguage": "fr", "answer": "There are three bedrooms in the house.", "acceptedAnswers": ["There are three bedrooms in the house.", "There are three bedrooms in this house.", "There are 3 bedrooms in the house."], "hint": "Trois chambres : un seul élément ou plusieurs ? Pense au -s de bedrooms.", "explanation": "Three bedrooms est un pluriel : on dit there are, et bedroom prend un -s. There are three bedrooms in the house.", "tip": "Avec un nombre supérieur à un : there are + nom au pluriel.", "extraExample": {"text": "There are two dogs in the garden.", "translation": "Il y a deux chiens dans le jardin."}, "errorPatterns": [{"contains": "there is three", "category": "grammar", "feedback": "Trois chambres, c''est un pluriel : on dit there are three bedrooms."}, {"contains": "there have", "category": "grammar", "feedback": "« Il y a » ne se dit pas avec have. Écris there are devant un pluriel."}, {"contains": "three bedroom in", "category": "grammar", "feedback": "Après un nombre supérieur à un, le nom prend un -s : three bedrooms."}], "pool": "lesson", "lessonId": "en.l41", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l42.e01', 'en', 'en.l42', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.chair','en.v.kitchen']::text[], 'mcq', 'lesson', 'Il y a quatre chaises dans la cuisine.', array['There are four chairs in the kitchen.']::text[], 'Quatre chaises, c''est un pluriel : on dit there are. Le verbe s''accorde avec four chairs, et chair prend un -s.', 1, '{"id": "en.l42.e01", "unitIds": ["en.g28.there_is_are", "en.v.chair", "en.v.kitchen"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la phrase correcte.", "prompt": "Il y a quatre chaises dans la cuisine.", "promptLanguage": "fr", "options": ["There are four chairs in the kitchen.", "There is four chairs in the kitchen.", "There have four chairs in the kitchen.", "Are four chairs in the kitchen."], "answer": "There are four chairs in the kitchen.", "acceptedAnswers": ["There are four chairs in the kitchen."], "hint": "Quatre chaises : un seul élément ou plusieurs ?", "explanation": "Quatre chaises, c''est un pluriel : on dit there are. Le verbe s''accorde avec four chairs, et chair prend un -s.", "tip": "Un nombre supérieur à un ? There are, jamais there is.", "extraExample": {"text": "There are five books on the table.", "translation": "Il y a cinq livres sur la table."}, "errorPatterns": [{"equals": "there is four chairs in the kitchen", "category": "grammar", "feedback": "There is s''utilise avec un seul élément. Avec four chairs, on dit there are."}, {"equals": "there have four chairs in the kitchen", "category": "grammar", "feedback": "« Il y a » ne se dit pas avec have. On utilise there is ou there are."}, {"equals": "are four chairs in the kitchen", "category": "grammar", "feedback": "Il manque there au début de la phrase : there are four chairs."}], "pool": "lesson", "lessonId": "en.l42", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l42.e02', 'en', 'en.l42', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.fridge']::text[], 'mcq', 'lesson', 'Is there a fridge in the kitchen? Yes, ___.', array['there is']::text[], 'Dans une réponse courte, on reprend le verbe de la question : Is there… ? donne Yes, there is. Un seul frigo, donc is et non are.', 2, '{"id": "en.l42.e02", "unitIds": ["en.g28.there_is_are", "en.v.fridge"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse courte.", "prompt": "Is there a fridge in the kitchen? Yes, ___.", "promptLanguage": "en", "options": ["there is", "it is", "there are", "I have"], "answer": "there is", "acceptedAnswers": ["there is"], "hint": "La réponse courte reprend there et le verbe de la question.", "explanation": "Dans une réponse courte, on reprend le verbe de la question : Is there… ? donne Yes, there is. Un seul frigo, donc is et non are.", "tip": "Is there… ? → Yes, there is. / No, there isn''t.", "extraExample": {"text": "Is there a garden at the hotel? Yes, there is.", "translation": "Y a-t-il un jardin à l''hôtel ? Oui, il y en a un."}, "errorPatterns": [{"equals": "it is", "category": "grammar", "feedback": "It is veut dire « c''est ». Pour répondre à Is there… ?, on reprend there : Yes, there is."}, {"equals": "there are", "category": "grammar", "feedback": "There are s''utilise avec plusieurs éléments. La question parle d''un seul frigo : Yes, there is."}, {"equals": "i have", "category": "grammar", "feedback": "Pour répondre à Is there… ?, on n''utilise pas have. On dit Yes, there is."}], "pool": "lesson", "lessonId": "en.l42", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l42.e03', 'en', 'en.l42', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.table','en.v.chair','en.v.sofa','en.v.fridge','en.v.lamp']::text[], 'match', 'lesson', 'Les objets de la maison', '{}'::text[], 'Table s''écrit comme en français mais se prononce « téïbeul ». Fridge est la forme courte de refrigerator (réfrigérateur). A sofa est un canapé et a chair est une chaise.', 1, '{"id": "en.l42.e03", "unitIds": ["en.g28.there_is_are", "en.v.table", "en.v.chair", "en.v.sofa", "en.v.fridge", "en.v.lamp"], "type": "match", "difficulty": 1, "instruction": "Associe chaque objet à sa traduction.", "prompt": "Les objets de la maison", "promptLanguage": "fr", "pairs": [{"left": "table", "right": "table"}, {"left": "chair", "right": "chaise"}, {"left": "sofa", "right": "canapé"}, {"left": "fridge", "right": "frigo"}, {"left": "lamp", "right": "lampe"}], "answer": "table = table ; chair = chaise ; sofa = canapé ; fridge = frigo ; lamp = lampe", "acceptedAnswers": [], "explanation": "Table s''écrit comme en français mais se prononce « téïbeul ». Fridge est la forme courte de refrigerator (réfrigérateur). A sofa est un canapé et a chair est une chaise.", "tip": "Fridge, c''est le « frigo » : un mot court que tout le monde utilise.", "extraExample": {"text": "There is a lamp on the table.", "translation": "Il y a une lampe sur la table."}, "pool": "lesson", "lessonId": "en.l42", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l42.e04', 'en', 'en.l42', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.lamp','en.v.bedroom']::text[], 'fill_blank', 'lesson', 'There ___ two lamps in the bedroom.', array['are']::text[], 'Two lamps est un pluriel : on dit there are. On n''utilise jamais has ou have pour dire « il y a ».', 2, '{"id": "en.l42.e04", "unitIds": ["en.g28.there_is_are", "en.v.lamp", "en.v.bedroom"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec is, are ou has.", "prompt": "There ___ two lamps in the bedroom.", "promptLanguage": "en", "options": ["is", "are", "has"], "answer": "are", "acceptedAnswers": ["are"], "hint": "Two lamps : regarde le nombre et le -s.", "explanation": "Two lamps est un pluriel : on dit there are. On n''utilise jamais has ou have pour dire « il y a ».", "tip": "Nombre + nom en -s : there are.", "extraExample": {"text": "There are three phones on the table.", "translation": "Il y a trois téléphones sur la table."}, "errorPatterns": [{"equals": "is", "category": "grammar", "feedback": "There is s''utilise avec un seul élément. Ici two lamps est un pluriel : there are."}, {"equals": "has", "category": "grammar", "feedback": "« Il y a » ne se dit pas avec has. On dit there is ou there are."}], "pool": "lesson", "lessonId": "en.l42", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l42.e05', 'en', 'en.l42', 'en.g28.there_is_are', array['en.g28.there_is_are','en.g04.be_negative_questions','en.v.chair']::text[], 'fill_blank', 'lesson', 'There ___ four chairs in the kitchen, but there are two.', array['aren''t','are not']::text[], 'Pour nier there are, on ajoute not : there aren''t. On utilise aren''t parce que four chairs est un pluriel.', 2, '{"id": "en.l42.e05", "unitIds": ["en.g28.there_is_are", "en.g04.be_negative_questions", "en.v.chair"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la forme négative.", "prompt": "There ___ four chairs in the kitchen, but there are two.", "promptLanguage": "en", "options": ["isn''t", "aren''t", "haven''t"], "answer": "aren''t", "acceptedAnswers": ["aren''t", "are not"], "hint": "Il y a deux chaises, pas quatre : la première partie est négative.", "explanation": "Pour nier there are, on ajoute not : there aren''t. On utilise aren''t parce que four chairs est un pluriel.", "tip": "Négation : there isn''t (un seul) / there aren''t (plusieurs).", "extraExample": {"text": "There aren''t five books in the bag, but there are three.", "translation": "Il n''y a pas cinq livres dans le sac, mais il y en a trois."}, "errorPatterns": [{"equals": "isn''t", "category": "grammar", "feedback": "There isn''t s''utilise avec un seul élément. Four chairs est un pluriel : there aren''t."}, {"equals": "is not", "category": "grammar", "feedback": "There is not s''utilise avec un seul élément. Four chairs est un pluriel : there are not."}, {"equals": "haven''t", "category": "grammar", "feedback": "There haven''t n''existe pas. Pour « il n''y a pas » avec un pluriel, on dit there aren''t."}], "pool": "lesson", "lessonId": "en.l42", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l42.e06', 'en', 'en.l42', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.chair','en.v.kitchen']::text[], 'reorder', 'lesson', 'Y a-t-il quatre chaises dans la cuisine ?', array['Are there four chairs in the kitchen']::text[], 'Pour poser la question avec there are, on inverse : Are there… ? Les chaises sont plusieurs (four chairs), donc on utilise are et non is.', 2, '{"id": "en.l42.e06", "unitIds": ["en.g28.there_is_are", "en.v.chair", "en.v.kitchen"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la question.", "prompt": "Y a-t-il quatre chaises dans la cuisine ?", "promptLanguage": "fr", "tokens": ["chairs", "Are", "in", "four", "the", "there", "kitchen"], "answer": "Are there four chairs in the kitchen", "acceptedAnswers": ["Are there four chairs in the kitchen"], "hint": "Avec un pluriel, la question commence par are.", "explanation": "Pour poser la question avec there are, on inverse : Are there… ? Les chaises sont plusieurs (four chairs), donc on utilise are et non is.", "tip": "Plusieurs éléments ? Are there… ? Un seul ? Is there… ?", "extraExample": {"text": "Are there two bathrooms in the apartment?", "translation": "Y a-t-il deux salles de bain dans l''appartement ?"}, "pool": "lesson", "lessonId": "en.l42", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l42.e07', 'en', 'en.l42', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.lamp','en.v.table']::text[], 'translation', 'lesson', 'Il y a une lampe sur la table.', array['There is a lamp on the table.','There''s a lamp on the table.']::text[], '« Il y a » se traduit there is devant un seul élément : there is a lamp. « Sur la table » se dit on the table.', 2, '{"id": "en.l42.e07", "unitIds": ["en.g28.there_is_are", "en.v.lamp", "en.v.table"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais. « il y a » = there is.", "prompt": "Il y a une lampe sur la table.", "promptLanguage": "fr", "answer": "There is a lamp on the table.", "acceptedAnswers": ["There is a lamp on the table.", "There''s a lamp on the table."], "hint": "« Sur » se dit on.", "explanation": "« Il y a » se traduit there is devant un seul élément : there is a lamp. « Sur la table » se dit on the table.", "tip": "Pour dire où se trouve une chose : there is + nom + on / in + lieu.", "extraExample": {"text": "There is a key on the table.", "translation": "Il y a une clé sur la table."}, "errorPatterns": [{"contains": "there have", "category": "grammar", "feedback": "« Il y a » ne se dit pas avec have. Écris there is."}, {"contains": "there are a", "category": "grammar", "feedback": "There are s''utilise avec un pluriel. Une seule lampe : there is a lamp."}, {"contains": "in the table", "category": "preposition", "feedback": "Pour une chose posée sur la table, on dit on the table, pas in the table."}], "pool": "lesson", "lessonId": "en.l42", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l42.e08', 'en', 'en.l42', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.lamp','en.v.sofa','en.v.living_room']::text[], 'translation', 'lesson', 'Il y a deux lampes et un canapé dans le salon.', array['There are two lamps and a sofa in the living room.','There is a sofa and two lamps in the living room.','There''s a sofa and two lamps in the living room.','There are two lamps and a couch in the living room.','There is a couch and two lamps in the living room.','There are two lamps and a sofa in the lounge.']::text[], 'Avec plusieurs éléments, on utilise there are. Two lamps est un pluriel : lamps prend un -s. On ne dit jamais there is devant two lamps.', 3, '{"id": "en.l42.e08", "unitIds": ["en.g28.there_is_are", "en.v.lamp", "en.v.sofa", "en.v.living_room"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Il y a deux lampes et un canapé dans le salon.", "promptLanguage": "fr", "answer": "There are two lamps and a sofa in the living room.", "acceptedAnswers": ["There are two lamps and a sofa in the living room.", "There is a sofa and two lamps in the living room.", "There''s a sofa and two lamps in the living room.", "There are two lamps and a couch in the living room.", "There is a couch and two lamps in the living room.", "There are two lamps and a sofa in the lounge."], "hint": "Commence par there are si tu cites d''abord les deux lampes.", "explanation": "Avec plusieurs éléments, on utilise there are. Two lamps est un pluriel : lamps prend un -s. On ne dit jamais there is devant two lamps.", "tip": "Le verbe suit le premier nom : there are two lamps…, there is a sofa and…", "extraExample": {"text": "There are two dogs and a child in the garden.", "translation": "Il y a deux chiens et un enfant dans le jardin."}, "errorPatterns": [{"contains": "there is two", "category": "grammar", "feedback": "Two lamps est un pluriel : on dit there are two lamps."}, {"contains": "there have", "category": "grammar", "feedback": "« Il y a » ne se dit pas avec have. Écris there are ou there is."}, {"contains": "two lamp and", "category": "grammar", "feedback": "Après un nombre supérieur à un, le nom prend un -s : two lamps."}], "pool": "lesson", "lessonId": "en.l42", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l42.e09', 'en', 'en.l42', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.sofa','en.v.kitchen']::text[], 'free_answer', 'lesson', 'Comment dit-on « Il n''y a pas de canapé dans la cuisine. » en anglais ?', array['There isn''t a sofa in the kitchen.','There is not a sofa in the kitchen.','There''s not a sofa in the kitchen.','There isn''t a couch in the kitchen.','There is no sofa in the kitchen.','There''s no sofa in the kitchen.','There is no couch in the kitchen.']::text[], '« Il n''y a pas de » se dit there isn''t devant un seul élément. On garde a devant sofa : There isn''t a sofa in the kitchen.', 3, '{"id": "en.l42.e09", "unitIds": ["en.g28.there_is_are", "en.v.sofa", "en.v.kitchen"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Il n''y a pas de canapé dans la cuisine. » en anglais ?", "promptLanguage": "fr", "answer": "There isn''t a sofa in the kitchen.", "acceptedAnswers": ["There isn''t a sofa in the kitchen.", "There is not a sofa in the kitchen.", "There''s not a sofa in the kitchen.", "There isn''t a couch in the kitchen.", "There is no sofa in the kitchen.", "There''s no sofa in the kitchen.", "There is no couch in the kitchen."], "hint": "Négation de there is : there isn''t.", "explanation": "« Il n''y a pas de » se dit there isn''t devant un seul élément. On garde a devant sofa : There isn''t a sofa in the kitchen.", "tip": "Nie there is avec n''t : there isn''t.", "extraExample": {"text": "There isn''t a phone in the bag.", "translation": "Il n''y a pas de téléphone dans le sac."}, "errorPatterns": [{"contains": "there have", "category": "grammar", "feedback": "« Il n''y a pas » ne se dit pas avec have. Écris there isn''t."}, {"contains": "there aren''t a", "category": "grammar", "feedback": "There aren''t s''utilise avec un pluriel. Un seul canapé : there isn''t."}, {"equals": "isn''t a sofa in the kitchen", "category": "grammar", "feedback": "Il manque there au début : there isn''t a sofa in the kitchen."}], "pool": "lesson", "lessonId": "en.l42", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l42.e10', 'en', 'en.l42', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.sofa','en.v.living_room']::text[], 'free_answer', 'lesson', 'Comment dit-on « Il y a deux canapés dans le salon. » en anglais ?', array['There are two sofas in the living room.','There are two couches in the living room.','There are two sofas in the lounge.']::text[], 'Two sofas est un pluriel : on dit there are, et sofa prend un -s. There are two sofas in the living room.', 3, '{"id": "en.l42.e10", "unitIds": ["en.g28.there_is_are", "en.v.sofa", "en.v.living_room"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Il y a deux canapés dans le salon. » en anglais ?", "promptLanguage": "fr", "answer": "There are two sofas in the living room.", "acceptedAnswers": ["There are two sofas in the living room.", "There are two couches in the living room.", "There are two sofas in the lounge."], "hint": "Deux canapés : pense au pluriel de sofa.", "explanation": "Two sofas est un pluriel : on dit there are, et sofa prend un -s. There are two sofas in the living room.", "tip": "Nombre supérieur à un : there are + nom au pluriel.", "extraExample": {"text": "There are two cars in the garden.", "translation": "Il y a deux voitures dans le jardin."}, "errorPatterns": [{"contains": "there is two", "category": "grammar", "feedback": "Two sofas est un pluriel : on dit there are two sofas."}, {"contains": "there have", "category": "grammar", "feedback": "« Il y a » ne se dit pas avec have. Écris there are devant un pluriel."}, {"contains": "two sofa in", "category": "grammar", "feedback": "Après un nombre supérieur à un, le nom prend un -s : two sofas."}], "pool": "lesson", "lessonId": "en.l42", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l43.e01', 'en', 'en.l43', 'en.g29.some_any', array['en.g29.some_any','en.v.bread']::text[], 'mcq', 'lesson', 'Can I have ___ bread, please?', array['some']::text[], 'Quand on demande ou qu''on offre quelque chose poliment, on utilise some, même dans une question : Can I have some bread ? Bread ne se compte pas, donc pas de a.', 1, '{"id": "en.l43.e01", "unitIds": ["en.g29.some_any", "en.v.bread"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Can I have ___ bread, please?", "promptLanguage": "en", "options": ["some", "any", "a"], "answer": "some", "acceptedAnswers": ["some"], "hint": "Tu demandes poliment quelque chose.", "explanation": "Quand on demande ou qu''on offre quelque chose poliment, on utilise some, même dans une question : Can I have some bread ? Bread ne se compte pas, donc pas de a.", "tip": "Demande polie (Can I have… ?) : some, pas any.", "extraExample": {"text": "Can I have some milk, please?", "translation": "Puis-je avoir du lait, s''il vous plaît ?"}, "errorPatterns": [{"equals": "any", "category": "grammar", "feedback": "Any s''utilise dans les négations et les questions simples. Dans une demande polie comme Can I have… ?, on dit some."}, {"equals": "a", "category": "grammar", "feedback": "Bread est un nom qu''on ne compte pas : on ne dit pas « a bread ». Pour « du pain », on dit some bread."}], "pool": "lesson", "lessonId": "en.l43", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l43.e02', 'en', 'en.l43', 'en.g29.some_any', array['en.g29.some_any','en.g28.there_is_are']::text[], 'mcq', 'lesson', 'There isn''t ___ milk in the fridge.', array['any']::text[], 'Dans une phrase négative, on utilise any : There isn''t any milk veut dire « il n''y a pas de lait ». Some est réservé aux phrases affirmatives.', 2, '{"id": "en.l43.e02", "unitIds": ["en.g29.some_any", "en.g28.there_is_are"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "There isn''t ___ milk in the fridge.", "promptLanguage": "en", "options": ["any", "some", "a"], "answer": "any", "acceptedAnswers": ["any"], "hint": "La phrase est négative.", "explanation": "Dans une phrase négative, on utilise any : There isn''t any milk veut dire « il n''y a pas de lait ». Some est réservé aux phrases affirmatives.", "tip": "Négation (isn''t, don''t…) : any.", "extraExample": {"text": "We don''t have any meat today.", "translation": "Nous n''avons pas de viande aujourd''hui."}, "errorPatterns": [{"equals": "some", "category": "grammar", "feedback": "Some ne s''utilise pas dans une phrase négative. Après isn''t, on dit any."}, {"equals": "a", "category": "grammar", "feedback": "Milk ne se compte pas : on ne dit pas « a milk ». Pour « pas de lait », on dit isn''t any milk."}], "pool": "lesson", "lessonId": "en.l43", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l43.e03', 'en', 'en.l43', 'en.g29.some_any', array['en.g29.some_any','en.v.menu','en.v.bill','en.v.waiter','en.v.bread','en.v.order']::text[], 'match', 'lesson', 'Au restaurant', '{}'::text[], 'Au restaurant, le menu est la carte (le choix de plats). Le waiter apporte les plats et la bill est l''addition. Attention : order est ici un verbe, « commander ».', 1, '{"id": "en.l43.e03", "unitIds": ["en.g29.some_any", "en.v.menu", "en.v.bill", "en.v.waiter", "en.v.bread", "en.v.order"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot du restaurant à sa traduction.", "prompt": "Au restaurant", "promptLanguage": "fr", "pairs": [{"left": "menu", "right": "la carte"}, {"left": "bill", "right": "l''addition"}, {"left": "waiter", "right": "le serveur"}, {"left": "bread", "right": "le pain"}, {"left": "order", "right": "commander"}], "answer": "menu = la carte ; bill = l''addition ; waiter = le serveur ; bread = le pain ; order = commander", "acceptedAnswers": [], "explanation": "Au restaurant, le menu est la carte (le choix de plats). Le waiter apporte les plats et la bill est l''addition. Attention : order est ici un verbe, « commander ».", "tip": "Bill = l''addition : au restaurant, on la demande à la fin du repas.", "extraExample": {"text": "The waiter has the menu.", "translation": "Le serveur a la carte."}, "pool": "lesson", "lessonId": "en.l43", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l43.e04', 'en', 'en.l43', 'en.g29.some_any', array['en.g29.some_any','en.g28.there_is_are']::text[], 'fill_blank', 'lesson', 'Look! There is ___ meat in the fridge.', array['some']::text[], 'Dans une phrase affirmative, on utilise some pour « du, de la, des » : There is some meat. Meat ne se compte pas, donc pas de a.', 2, '{"id": "en.l43.e04", "unitIds": ["en.g29.some_any", "en.g28.there_is_are"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec some, any ou a.", "prompt": "Look! There is ___ meat in the fridge.", "promptLanguage": "en", "options": ["some", "any", "a"], "answer": "some", "acceptedAnswers": ["some"], "hint": "La phrase est affirmative.", "explanation": "Dans une phrase affirmative, on utilise some pour « du, de la, des » : There is some meat. Meat ne se compte pas, donc pas de a.", "tip": "Phrase affirmative avec « du / de la / des » : some.", "extraExample": {"text": "There is some fish in the kitchen.", "translation": "Il y a du poisson dans la cuisine."}, "errorPatterns": [{"equals": "any", "category": "grammar", "feedback": "Any s''utilise dans les négations et les questions. Ta phrase est affirmative : on dit some."}, {"equals": "a", "category": "grammar", "feedback": "Meat ne se compte pas : on ne dit pas « a meat ». Pour « de la viande », on dit some meat."}], "pool": "lesson", "lessonId": "en.l43", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l43.e05', 'en', 'en.l43', 'en.g29.some_any', array['en.g29.some_any','en.v.waiter','en.v.bread']::text[], 'fill_blank', 'lesson', 'Do you have ___ bread today?', array['any']::text[], 'Dans une question simple (on veut savoir s''il y en a), on utilise any : Do you have any bread ? Some sert plutôt aux demandes et aux offres polies.', 2, '{"id": "en.l43.e05", "unitIds": ["en.g29.some_any", "en.v.waiter", "en.v.bread"], "type": "fill_blank", "difficulty": 2, "context": "Anna is at a restaurant. She speaks to the waiter.", "instruction": "Complète : c''est une vraie question, Anna ne sait pas s''il y en a.", "prompt": "Do you have ___ bread today?", "promptLanguage": "en", "options": ["any", "some", "a"], "answer": "any", "acceptedAnswers": ["any"], "hint": "C''est une question simple, pas une demande polie.", "explanation": "Dans une question simple (on veut savoir s''il y en a), on utilise any : Do you have any bread ? Some sert plutôt aux demandes et aux offres polies.", "tip": "Question simple pour savoir s''il y en a : any.", "extraExample": {"text": "Is there any coffee in the kitchen?", "translation": "Y a-t-il du café dans la cuisine ?"}, "errorPatterns": [{"equals": "some", "category": "grammar", "feedback": "Anna veut savoir si le serveur a du pain : c''est une question simple, donc any. Some s''emploie dans les demandes polies comme Can I have some… ?"}, {"equals": "a", "category": "grammar", "feedback": "Bread ne se compte pas : on ne dit pas « a bread ». Pour « du pain » dans une question, on dit any bread."}], "pool": "lesson", "lessonId": "en.l43", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l43.e06', 'en', 'en.l43', 'en.g29.some_any', array['en.g29.some_any']::text[], 'reorder', 'lesson', 'Puis-je avoir de l''eau, s''il vous plaît ?', array['Can I have some water please','Please can I have some water']::text[], 'Pour demander poliment, on dit Can I have some… please ? On garde some dans une demande polie, même si c''est une question.', 2, '{"id": "en.l43.e06", "unitIds": ["en.g29.some_any"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la demande polie.", "prompt": "Puis-je avoir de l''eau, s''il vous plaît ?", "promptLanguage": "fr", "tokens": ["water", "Can", "some", "I", "please", "have"], "answer": "Can I have some water please", "acceptedAnswers": ["Can I have some water please", "Please can I have some water"], "hint": "La phrase commence par Can I have. Please se place à la fin.", "explanation": "Pour demander poliment, on dit Can I have some… please ? On garde some dans une demande polie, même si c''est une question.", "tip": "Can I have some… , please ? : la formule du restaurant.", "extraExample": {"text": "Can I have some coffee, please?", "translation": "Puis-je avoir du café, s''il vous plaît ?"}, "pool": "lesson", "lessonId": "en.l43", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l43.e07', 'en', 'en.l43', 'en.g29.some_any', array['en.g29.some_any','en.v.menu','en.v.bread']::text[], 'translation', 'lesson', 'Je peux avoir du pain et la carte, s''il vous plaît ?', array['Can I have some bread and the menu, please?','Can I have the menu and some bread, please?','Please can I have some bread and the menu?','Please can I have the menu and some bread?','Could I have some bread and the menu, please?','Could I have the menu and some bread, please?','May I have some bread and the menu, please?','May I have the menu and some bread, please?','Can I get some bread and the menu, please?','Can I have some bread and a menu, please?','Can I have a menu and some bread, please?']::text[], 'Pour demander poliment, on dit Can I have some… ? : some bread. Le menu est précis (la carte du restaurant), donc the menu. Please termine la phrase.', 2, '{"id": "en.l43.e07", "unitIds": ["en.g29.some_any", "en.v.menu", "en.v.bread"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais. « s''il vous plaît » = please.", "prompt": "Je peux avoir du pain et la carte, s''il vous plaît ?", "promptLanguage": "fr", "answer": "Can I have some bread and the menu, please?", "acceptedAnswers": ["Can I have some bread and the menu, please?", "Can I have the menu and some bread, please?", "Please can I have some bread and the menu?", "Please can I have the menu and some bread?", "Could I have some bread and the menu, please?", "Could I have the menu and some bread, please?", "May I have some bread and the menu, please?", "May I have the menu and some bread, please?", "Can I get some bread and the menu, please?", "Can I have some bread and a menu, please?", "Can I have a menu and some bread, please?"], "hint": "Dans une demande polie, on dit some, pas any.", "explanation": "Pour demander poliment, on dit Can I have some… ? : some bread. Le menu est précis (la carte du restaurant), donc the menu. Please termine la phrase.", "tip": "Demande polie : Can I have some… , please ?", "extraExample": {"text": "Can I have some water and a menu, please?", "translation": "Puis-je avoir de l''eau et une carte, s''il vous plaît ?"}, "errorPatterns": [{"contains": "any bread", "category": "grammar", "feedback": "Dans une demande polie, on garde some, même dans une question : Can I have some bread ?"}, {"contains": "a bread", "category": "grammar", "feedback": "Bread ne se compte pas : on ne dit pas « a bread ». Pour « du pain », on dit some bread."}, {"contains": "have bread", "category": "grammar", "feedback": "Il manque some pour « du pain » dans une demande polie : Can I have some bread ?"}], "pool": "lesson", "lessonId": "en.l43", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l43.e08', 'en', 'en.l43', 'en.g29.some_any', array['en.g29.some_any','en.v.waiter']::text[], 'translation', 'lesson', 'Le serveur n''a pas de poisson aujourd''hui.', array['The waiter doesn''t have any fish today.','The waiter does not have any fish today.','The waiter hasn''t got any fish today.','Today the waiter doesn''t have any fish.','The waiter doesn''t have any fish.']::text[], 'Dans une phrase négative, « de, du » se dit any : doesn''t have any fish. Avec un sujet à la 3e personne (the waiter), on utilise doesn''t et have reste à la forme de base.', 3, '{"id": "en.l43.e08", "unitIds": ["en.g29.some_any", "en.v.waiter"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais, avec any.", "prompt": "Le serveur n''a pas de poisson aujourd''hui.", "promptLanguage": "fr", "answer": "The waiter doesn''t have any fish today.", "acceptedAnswers": ["The waiter doesn''t have any fish today.", "The waiter does not have any fish today.", "The waiter hasn''t got any fish today.", "Today the waiter doesn''t have any fish.", "The waiter doesn''t have any fish."], "hint": "Phrase négative : doesn''t have + any.", "explanation": "Dans une phrase négative, « de, du » se dit any : doesn''t have any fish. Avec un sujet à la 3e personne (the waiter), on utilise doesn''t et have reste à la forme de base.", "tip": "Négation + « pas de… » : not + any.", "extraExample": {"text": "We don''t have any milk today.", "translation": "Nous n''avons pas de lait aujourd''hui."}, "errorPatterns": [{"contains": "some fish", "category": "grammar", "feedback": "Dans une phrase négative, on utilise any, pas some : doesn''t have any fish."}, {"contains": "doesn''t has", "category": "conjugation", "feedback": "Après doesn''t, le verbe reste à la forme de base : doesn''t have, pas doesn''t has."}, {"equals": "the waiter doesn''t have fish today", "category": "instruction", "feedback": "Ta phrase est correcte, mais la consigne demande d''utiliser any : The waiter doesn''t have any fish today."}], "pool": "lesson", "lessonId": "en.l43", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l43.e09', 'en', 'en.l43', 'en.g29.some_any', array['en.g29.some_any','en.v.bill']::text[], 'free_answer', 'lesson', 'Comment demander poliment l''addition au serveur ?', array['Can I have the bill, please?','Can we have the bill, please?','Could I have the bill, please?','Could we have the bill, please?','Please can I have the bill?','Please can we have the bill?','The bill, please.','Can I get the bill, please?','Can we get the bill, please?','Can I have the check, please?','Can we have the check, please?','Excuse me, can I have the bill, please?','Excuse me, can we have the bill, please?','May I have the bill, please?','May we have the bill, please?','I would like the bill, please.','Could I get the bill, please?']::text[], 'Pour demander l''addition, on dit Can I have the bill, please ? The bill est précis (l''addition de ce repas). N''oublie pas please pour rester poli. (Aux États-Unis : the check.)', 3, '{"id": "en.l43.e09", "unitIds": ["en.g29.some_any", "en.v.bill"], "type": "free_answer", "difficulty": 3, "context": "Tom and Anna finish their dinner. They want to leave.", "instruction": "Écris la demande polie en anglais.", "prompt": "Comment demander poliment l''addition au serveur ?", "promptLanguage": "fr", "answer": "Can I have the bill, please?", "acceptedAnswers": ["Can I have the bill, please?", "Can we have the bill, please?", "Could I have the bill, please?", "Could we have the bill, please?", "Please can I have the bill?", "Please can we have the bill?", "The bill, please.", "Can I get the bill, please?", "Can we get the bill, please?", "Can I have the check, please?", "Can we have the check, please?", "Excuse me, can I have the bill, please?", "Excuse me, can we have the bill, please?", "May I have the bill, please?", "May we have the bill, please?", "I would like the bill, please.", "Could I get the bill, please?"], "hint": "Commence par Can I have et termine par please.", "explanation": "Pour demander l''addition, on dit Can I have the bill, please ? The bill est précis (l''addition de ce repas). N''oublie pas please pour rester poli. (Aux États-Unis : the check.)", "tip": "Pour demander poliment : Can I have… , please ?", "extraExample": {"text": "Can we have the menu, please?", "translation": "Pouvons-nous avoir la carte, s''il vous plaît ?"}, "errorPatterns": [{"contains": "i want the bill", "category": "grammar", "feedback": "I want est trop direct pour demander l''addition. Dis plutôt Can I have the bill, please ?"}, {"contains": "a bill", "category": "grammar", "feedback": "On demande l''addition du repas, donc the bill (la), pas a bill."}], "pool": "lesson", "lessonId": "en.l43", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l43.e10', 'en', 'en.l43', 'en.g29.some_any', array['en.g29.some_any','en.v.order']::text[], 'free_answer', 'lesson', 'Comment dit-on « Je veux commander du poisson et du pain. » en anglais ?', array['I want to order some fish and some bread.','I want to order some fish and bread.','I want to order fish and bread.','I want to order some bread and some fish.','I want to order some bread and fish.','I want to order bread and fish.','I would like to order some fish and some bread.','I would like to order some fish and bread.']::text[], 'Dans une phrase affirmative, « du poisson » se dit some fish, et « du pain » some bread. Commander se dit order, après want to.', 3, '{"id": "en.l43.e10", "unitIds": ["en.g29.some_any", "en.v.order"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Je veux commander du poisson et du pain. » en anglais ?", "promptLanguage": "fr", "answer": "I want to order some fish and some bread.", "acceptedAnswers": ["I want to order some fish and some bread.", "I want to order some fish and bread.", "I want to order fish and bread.", "I want to order some bread and some fish.", "I want to order some bread and fish.", "I want to order bread and fish.", "I would like to order some fish and some bread.", "I would like to order some fish and bread."], "hint": "Want + to + verbe. Commander = order.", "explanation": "Dans une phrase affirmative, « du poisson » se dit some fish, et « du pain » some bread. Commander se dit order, après want to.", "tip": "Affirmatif : I want to order some… (jamais any).", "extraExample": {"text": "We want to order some coffee and some cake.", "translation": "Nous voulons commander du café et du gâteau."}, "errorPatterns": [{"contains": "any fish", "category": "grammar", "feedback": "Any ne s''utilise pas dans une phrase affirmative. On dit some fish."}, {"contains": "i want to order a bread", "category": "grammar", "feedback": "Bread ne se compte pas : on ne dit pas « a bread ». On dit some bread."}, {"contains": "i want some", "category": "vocabulary", "feedback": "Il manque le verbe commander : to order. I want to order some fish…"}], "pool": "lesson", "lessonId": "en.l43", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l44.e01', 'en', 'en.l44', 'en.g30.how_much_many', array['en.g30.how_much_many']::text[], 'mcq', 'lesson', '___ milk do we need?', array['How much']::text[], 'Milk ne se compte pas (on ne dit pas « two milks »). Devant un nom qu''on ne compte pas, on utilise how much : How much milk do we need ?', 1, '{"id": "en.l44.e01", "unitIds": ["en.g30.how_much_many"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne expression.", "prompt": "___ milk do we need?", "promptLanguage": "en", "options": ["How much", "How many", "How"], "answer": "How much", "acceptedAnswers": ["How much"], "hint": "Peut-on compter le lait : un lait, deux laits ?", "explanation": "Milk ne se compte pas (on ne dit pas « two milks »). Devant un nom qu''on ne compte pas, on utilise how much : How much milk do we need ?", "tip": "On ne peut pas compter ? How much.", "extraExample": {"text": "How much water do you drink?", "translation": "Combien d''eau bois-tu ?"}, "errorPatterns": [{"equals": "how many", "category": "grammar", "feedback": "How many s''utilise avec un pluriel qu''on peut compter (how many bags). Milk ne se compte pas : how much."}, {"equals": "how", "category": "grammar", "feedback": "How tout seul ne demande pas la quantité. Pour « combien de lait », on dit how much milk."}], "pool": "lesson", "lessonId": "en.l44", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l44.e02', 'en', 'en.l44', 'en.g30.how_much_many', array['en.g30.how_much_many','en.v.shop','en.v.price']::text[], 'mcq', 'lesson', 'Que dis-tu au vendeur ?', array['How much is the book?']::text[], 'Pour demander le prix, on dit How much is… ? avec un objet (the book), et How much are… ? avec plusieurs objets. Ici, un seul livre : How much is the book ?', 2, '{"id": "en.l44.e02", "unitIds": ["en.g30.how_much_many", "en.v.shop", "en.v.price"], "type": "mcq", "difficulty": 2, "context": "You are in a shop. You want to know the price of a book.", "instruction": "Choisis la bonne question.", "prompt": "Que dis-tu au vendeur ?", "promptLanguage": "fr", "options": ["How much is the book?", "How many is the book?", "How much are the book?", "How price is the book?"], "answer": "How much is the book?", "acceptedAnswers": ["How much is the book?"], "hint": "Pour demander un prix, on commence par how much + is.", "explanation": "Pour demander le prix, on dit How much is… ? avec un objet (the book), et How much are… ? avec plusieurs objets. Ici, un seul livre : How much is the book ?", "tip": "Le prix : How much is it ? (un objet) / How much are they ? (plusieurs).", "extraExample": {"text": "How much are the books? They''re ten pounds.", "translation": "Combien coûtent les livres ? Ils coûtent dix livres."}, "errorPatterns": [{"equals": "how many is the book", "category": "grammar", "feedback": "How many sert à compter des objets. Pour demander un prix, on dit how much."}, {"equals": "how much are the book", "category": "grammar", "feedback": "Un seul livre : on dit is, pas are. How much is the book ?"}, {"equals": "how price is the book", "category": "grammar", "feedback": "En anglais, on ne dit pas « how price ». Pour demander le prix, on dit How much is… ?"}], "pool": "lesson", "lessonId": "en.l44", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l44.e03', 'en', 'en.l44', 'en.v.price', array['en.v.price','en.v.cheap','en.v.expensive','en.v.shop','en.v.money','en.g30.how_much_many']::text[], 'match', 'lesson', 'Les achats', '{}'::text[], 'Cheap veut dire « pas cher, bon marché » et expensive veut dire « cher » : ce sont des contraires. Money (l''argent) ne se compte pas et n''a jamais de -s.', 1, '{"id": "en.l44.e03", "unitIds": ["en.v.price", "en.v.cheap", "en.v.expensive", "en.v.shop", "en.v.money", "en.g30.how_much_many"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Les achats", "promptLanguage": "fr", "pairs": [{"left": "price", "right": "le prix"}, {"left": "cheap", "right": "bon marché"}, {"left": "expensive", "right": "cher"}, {"left": "shop", "right": "le magasin"}, {"left": "money", "right": "l''argent"}], "answer": "price = le prix ; cheap = bon marché ; expensive = cher ; shop = le magasin ; money = l''argent", "acceptedAnswers": [], "explanation": "Cheap veut dire « pas cher, bon marché » et expensive veut dire « cher » : ce sont des contraires. Money (l''argent) ne se compte pas et n''a jamais de -s.", "tip": "Expensive = cher (beaucoup d''argent) ; cheap = pas cher.", "extraExample": {"text": "The shop is cheap.", "translation": "Le magasin est bon marché."}, "pool": "lesson", "lessonId": "en.l44", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l44.e04', 'en', 'en.l44', 'en.g30.how_much_many', array['en.g30.how_much_many']::text[], 'fill_blank', 'lesson', 'How ___ books do you want?', array['many']::text[], 'Books se compte (one book, two books) : on utilise how many + pluriel. How much est réservé aux noms qu''on ne compte pas.', 2, '{"id": "en.l44.e04", "unitIds": ["en.g30.how_much_many"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "How ___ books do you want?", "promptLanguage": "en", "options": ["many", "much", "of"], "answer": "many", "acceptedAnswers": ["many"], "hint": "Books est au pluriel : on peut les compter.", "explanation": "Books se compte (one book, two books) : on utilise how many + pluriel. How much est réservé aux noms qu''on ne compte pas.", "tip": "On peut compter ? How many + nom au pluriel.", "extraExample": {"text": "How many cakes do you want?", "translation": "Combien de gâteaux veux-tu ?"}, "errorPatterns": [{"equals": "much", "category": "grammar", "feedback": "How much s''utilise avec un nom qu''on ne compte pas (money, milk). Books se compte : how many."}, {"equals": "of", "category": "grammar", "feedback": "« Combien de » se dit how many ou how much, sans of : How many books ?"}], "pool": "lesson", "lessonId": "en.l44", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l44.e05', 'en', 'en.l44', 'en.g30.how_much_many', array['en.g30.how_much_many','en.v.price','en.v.cheap','en.v.expensive']::text[], 'fill_blank', 'lesson', 'How ___ is the bag? It''s five pounds.', array['much']::text[], 'Pour demander un prix, on dit How much is… ? On répond It''s five pounds. How many sert seulement à compter des objets.', 2, '{"id": "en.l44.e05", "unitIds": ["en.g30.how_much_many", "en.v.price", "en.v.cheap", "en.v.expensive"], "type": "fill_blank", "difficulty": 2, "context": "The shop is expensive, but the bag is cheap. The price is five pounds.", "instruction": "Complète avec le bon mot.", "prompt": "How ___ is the bag? It''s five pounds.", "promptLanguage": "en", "options": ["much", "many", "a lot of"], "answer": "much", "acceptedAnswers": ["much"], "hint": "Tu demandes un prix.", "explanation": "Pour demander un prix, on dit How much is… ? On répond It''s five pounds. How many sert seulement à compter des objets.", "tip": "Un prix se demande avec How much is… ?", "extraExample": {"text": "How much is the coffee? It''s two pounds.", "translation": "Combien coûte le café ? Il coûte deux livres."}, "errorPatterns": [{"equals": "many", "category": "grammar", "feedback": "How many sert à compter des objets (how many bags). Pour un prix, on dit how much."}, {"equals": "a lot of", "category": "grammar", "feedback": "A lot of veut dire « beaucoup de » et ne se met pas ici. Pour demander un prix : How much is… ?"}], "pool": "lesson", "lessonId": "en.l44", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l44.e06', 'en', 'en.l44', 'en.g30.how_much_many', array['en.g30.how_much_many','en.v.money']::text[], 'reorder', 'lesson', 'Combien d''argent as-tu ?', array['How much money do you have']::text[], 'Money ne se compte pas : on dit how much money. Après how much + nom, la question se construit comme d''habitude : do you have ?', 2, '{"id": "en.l44.e06", "unitIds": ["en.g30.how_much_many", "en.v.money"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la question.", "prompt": "Combien d''argent as-tu ?", "promptLanguage": "fr", "tokens": ["do", "money", "How", "have", "you", "much"], "answer": "How much money do you have", "acceptedAnswers": ["How much money do you have"], "hint": "How much + nom, puis do you have.", "explanation": "Money ne se compte pas : on dit how much money. Après how much + nom, la question se construit comme d''habitude : do you have ?", "tip": "How much / how many + nom + do you have ?", "extraExample": {"text": "How much bread do we need?", "translation": "De combien de pain avons-nous besoin ?"}, "pool": "lesson", "lessonId": "en.l44", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l44.e07', 'en', 'en.l44', 'en.g30.how_much_many', array['en.g30.how_much_many','en.v.shop']::text[], 'translation', 'lesson', 'Combien de sacs as-tu ?', array['How many bags do you have?','How many bags have you got?']::text[], 'Les sacs se comptent (one bag, two bags) : on utilise how many + pluriel. Le nom prend un -s : how many bags.', 2, '{"id": "en.l44.e07", "unitIds": ["en.g30.how_much_many", "en.v.shop"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Combien de sacs as-tu ?", "promptLanguage": "fr", "answer": "How many bags do you have?", "acceptedAnswers": ["How many bags do you have?", "How many bags have you got?"], "hint": "Un sac, deux sacs : on peut compter.", "explanation": "Les sacs se comptent (one bag, two bags) : on utilise how many + pluriel. Le nom prend un -s : how many bags.", "tip": "Après how many, le nom est toujours au pluriel.", "extraExample": {"text": "How many books do you have?", "translation": "Combien de livres as-tu ?"}, "errorPatterns": [{"contains": "how much bags", "category": "grammar", "feedback": "Les sacs se comptent : on utilise how many bags, pas how much."}, {"contains": "how many bag do", "category": "grammar", "feedback": "Après how many, le nom est au pluriel : how many bags."}, {"contains": "how many of bags", "category": "grammar", "feedback": "« Combien de » ne se traduit pas avec of : how many bags."}], "pool": "lesson", "lessonId": "en.l44", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l44.e08', 'en', 'en.l44', 'en.g30.how_much_many', array['en.g30.how_much_many','en.g28.there_is_are','en.v.shop']::text[], 'translation', 'lesson', 'Il y a beaucoup de magasins dans cette ville.', array['There are a lot of shops in this city.','There are lots of shops in this city.','There are many shops in this city.','There are plenty of shops in this city.','There are a lot of shops in the city.','There are lots of shops in the city.','There are many shops in the city.']::text[], 'Dans une phrase affirmative, on préfère a lot of à many : There are a lot of shops. Shops est un pluriel, donc there are et non there is.', 3, '{"id": "en.l44.e08", "unitIds": ["en.g30.how_much_many", "en.g28.there_is_are", "en.v.shop"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais. « beaucoup de » = a lot of.", "prompt": "Il y a beaucoup de magasins dans cette ville.", "promptLanguage": "fr", "answer": "There are a lot of shops in this city.", "acceptedAnswers": ["There are a lot of shops in this city.", "There are lots of shops in this city.", "There are many shops in this city.", "There are plenty of shops in this city.", "There are a lot of shops in the city.", "There are lots of shops in the city.", "There are many shops in the city."], "hint": "Magasins est au pluriel : there are.", "explanation": "Dans une phrase affirmative, on préfère a lot of à many : There are a lot of shops. Shops est un pluriel, donc there are et non there is.", "tip": "Beaucoup de, dans une phrase affirmative : a lot of (n''oublie pas of).", "extraExample": {"text": "There are a lot of books in my bedroom.", "translation": "Il y a beaucoup de livres dans ma chambre."}, "errorPatterns": [{"contains": "there is a lot of shops", "category": "grammar", "feedback": "Shops est un pluriel : on dit there are a lot of shops."}, {"contains": "much shops", "category": "grammar", "feedback": "Les magasins se comptent : on dit many shops ou a lot of shops, jamais much shops."}, {"contains": "a lot shops", "category": "grammar", "feedback": "Il manque of : a lot of shops."}], "pool": "lesson", "lessonId": "en.l44", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l44.e09', 'en', 'en.l44', 'en.g30.how_much_many', array['en.g30.how_much_many','en.v.price']::text[], 'free_answer', 'lesson', 'Comment demande-t-elle le prix de l''ordinateur portable ?', array['How much is the laptop?','How much is this laptop?','How much is that laptop?','How much does the laptop cost?','How much does this laptop cost?']::text[], 'Pour demander le prix d''un objet, on dit How much is… ? Un seul ordinateur, donc is. On pourrait aussi dire How much does it cost ?', 3, '{"id": "en.l44.e09", "unitIds": ["en.g30.how_much_many", "en.v.price"], "type": "free_answer", "difficulty": 3, "context": "Anna is in a shop. She wants to know the price of the laptop.", "instruction": "Écris la question en anglais.", "prompt": "Comment demande-t-elle le prix de l''ordinateur portable ?", "promptLanguage": "fr", "answer": "How much is the laptop?", "acceptedAnswers": ["How much is the laptop?", "How much is this laptop?", "How much is that laptop?", "How much does the laptop cost?", "How much does this laptop cost?"], "hint": "Pour demander un prix : How + much + is…", "explanation": "Pour demander le prix d''un objet, on dit How much is… ? Un seul ordinateur, donc is. On pourrait aussi dire How much does it cost ?", "tip": "Le prix d''un objet : How much is…  ? (jamais how many).", "extraExample": {"text": "How much is the phone?", "translation": "Combien coûte le téléphone ?"}, "errorPatterns": [{"contains": "how many", "category": "grammar", "feedback": "How many sert à compter des objets. Pour demander un prix, on dit how much."}, {"contains": "how much are the laptop", "category": "grammar", "feedback": "Un seul ordinateur : on dit is, pas are. How much is the laptop ?"}, {"equals": "how much the laptop", "category": "grammar", "feedback": "Il manque le verbe is : How much is the laptop ?"}], "pool": "lesson", "lessonId": "en.l44", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l44.e10', 'en', 'en.l44', 'en.v.expensive', array['en.v.expensive','en.v.cheap','en.g30.how_much_many']::text[], 'free_answer', 'lesson', 'Comment dit-on « L''ordinateur est cher, mais le livre est bon marché. » en anglais ?', array['The laptop is expensive, but the book is cheap.','The laptop is expensive but the book is cheap.']::text[], 'Expensive veut dire « cher » et cheap veut dire « bon marché ». Les deux sont des adjectifs : ils se placent après is et ne prennent pas de -s.', 3, '{"id": "en.l44.e10", "unitIds": ["en.v.expensive", "en.v.cheap", "en.g30.how_much_many"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « L''ordinateur est cher, mais le livre est bon marché. » en anglais ?", "promptLanguage": "fr", "answer": "The laptop is expensive, but the book is cheap.", "acceptedAnswers": ["The laptop is expensive, but the book is cheap.", "The laptop is expensive but the book is cheap."], "hint": "Il te faut deux adjectifs contraires, après is.", "explanation": "Expensive veut dire « cher » et cheap veut dire « bon marché ». Les deux sont des adjectifs : ils se placent après is et ne prennent pas de -s.", "tip": "Expensive = cher ; cheap = pas cher : ne les inverse pas.", "extraExample": {"text": "The coffee is cheap, but the cake is expensive.", "translation": "Le café est bon marché, mais le gâteau est cher."}, "errorPatterns": [{"contains": "laptop is cheap", "category": "vocabulary", "feedback": "Cheap veut dire « bon marché ». L''ordinateur est cher : the laptop is expensive."}, {"contains": "book is expensive", "category": "vocabulary", "feedback": "Expensive veut dire « cher ». Le livre est bon marché : the book is cheap."}], "pool": "lesson", "lessonId": "en.l44", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l45.e01', 'en', 'en.l45', 'en.g30.how_much_many', array['en.g30.how_much_many','en.v.luggage']::text[], 'mcq', 'lesson', 'Comment dit-on « J''ai beaucoup de bagages. » en anglais ?', array['I have a lot of luggage.']::text[], 'Luggage est un nom qu''on ne compte pas : il n''a jamais de -s, même si on pense à plusieurs sacs. Dans une phrase affirmative, « beaucoup de » se dit a lot of.', 1, '{"id": "en.l45.e01", "unitIds": ["en.g30.how_much_many", "en.v.luggage"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « J''ai beaucoup de bagages. » en anglais ?", "promptLanguage": "fr", "options": ["I have a lot of luggage.", "I have a lot of luggages.", "I have a lot luggage.", "I have many luggages."], "answer": "I have a lot of luggage.", "acceptedAnswers": ["I have a lot of luggage."], "hint": "En français, « bagages » est pluriel. En anglais, luggage ne l''est jamais.", "explanation": "Luggage est un nom qu''on ne compte pas : il n''a jamais de -s, même si on pense à plusieurs sacs. Dans une phrase affirmative, « beaucoup de » se dit a lot of.", "tip": "Luggage ne prend jamais de -s : pas de « luggages ».", "extraExample": {"text": "He has a lot of luggage for the trip.", "translation": "Il a beaucoup de bagages pour le voyage."}, "errorPatterns": [{"equals": "i have a lot of luggages", "category": "grammar", "feedback": "Luggage ne prend jamais de -s : c''est un nom qu''on ne compte pas. On dit a lot of luggage."}, {"equals": "i have a lot luggage", "category": "grammar", "feedback": "Il manque of : on dit a lot of luggage."}, {"equals": "i have many luggages", "category": "grammar", "feedback": "Luggage n''a pas de pluriel (pas de -s). Et dans une phrase affirmative, on préfère a lot of : a lot of luggage."}], "pool": "lesson", "lessonId": "en.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l45.e02', 'en', 'en.l45', 'en.g29.some_any', array['en.g29.some_any','en.v.ticket','en.v.station']::text[], 'mcq', 'lesson', 'Can I have ___ tickets for tomorrow, please?', array['some']::text[], 'Dans une demande polie (Can I have… ?), on garde some, même dans une question. Tickets est au pluriel, donc pas de a.', 2, '{"id": "en.l45.e02", "unitIds": ["en.g29.some_any", "en.v.ticket", "en.v.station"], "type": "mcq", "difficulty": 2, "context": "Anna is at the station. She speaks to a woman.", "instruction": "Choisis le bon mot.", "prompt": "Can I have ___ tickets for tomorrow, please?", "promptLanguage": "en", "options": ["some", "any", "a"], "answer": "some", "acceptedAnswers": ["some"], "hint": "Anna fait une demande polie.", "explanation": "Dans une demande polie (Can I have… ?), on garde some, même dans une question. Tickets est au pluriel, donc pas de a.", "tip": "Demande polie : some. Négation ou question simple : any.", "extraExample": {"text": "Can I have some water, please?", "translation": "Puis-je avoir de l''eau, s''il vous plaît ?"}, "errorPatterns": [{"equals": "any", "category": "grammar", "feedback": "Any s''utilise dans les négations et les questions simples. Anna demande poliment quelque chose : on dit some."}, {"equals": "a", "category": "grammar", "feedback": "A s''utilise avec un seul billet. Tickets est un pluriel : some tickets."}], "pool": "lesson", "lessonId": "en.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l45.e03', 'en', 'en.l45', 'en.g30.how_much_many', array['en.g30.how_much_many','en.v.ticket','en.v.station','en.v.airport','en.v.passport','en.v.luggage']::text[], 'match', 'lesson', 'Transport et voyage', '{}'::text[], 'Ticket est le billet (de train, d''avion…), station la gare et airport l''aéroport. Luggage veut dire « les bagages » mais reste singulier en anglais : jamais de -s.', 1, '{"id": "en.l45.e03", "unitIds": ["en.g30.how_much_many", "en.v.ticket", "en.v.station", "en.v.airport", "en.v.passport", "en.v.luggage"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot du voyage à sa traduction.", "prompt": "Transport et voyage", "promptLanguage": "fr", "pairs": [{"left": "ticket", "right": "le billet"}, {"left": "station", "right": "la gare"}, {"left": "airport", "right": "l''aéroport"}, {"left": "passport", "right": "le passeport"}, {"left": "luggage", "right": "les bagages"}], "answer": "ticket = le billet ; station = la gare ; airport = l''aéroport ; passport = le passeport ; luggage = les bagages", "acceptedAnswers": [], "explanation": "Ticket est le billet (de train, d''avion…), station la gare et airport l''aéroport. Luggage veut dire « les bagages » mais reste singulier en anglais : jamais de -s.", "tip": "En français « les bagages » est pluriel ; en anglais luggage ne l''est jamais.", "extraExample": {"text": "I have my passport and my ticket.", "translation": "J''ai mon passeport et mon billet."}, "pool": "lesson", "lessonId": "en.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l45.e04', 'en', 'en.l45', 'en.g30.how_much_many', array['en.g30.how_much_many','en.v.ticket']::text[], 'fill_blank', 'lesson', 'How ___ tickets do you need?', array['many']::text[], 'Les billets se comptent (one ticket, two tickets) : on utilise how many + pluriel. How much est réservé aux noms qu''on ne compte pas.', 2, '{"id": "en.l45.e04", "unitIds": ["en.g30.how_much_many", "en.v.ticket"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "How ___ tickets do you need?", "promptLanguage": "en", "options": ["many", "much", "of"], "answer": "many", "acceptedAnswers": ["many"], "hint": "Tickets est au pluriel : on peut compter les billets.", "explanation": "Les billets se comptent (one ticket, two tickets) : on utilise how many + pluriel. How much est réservé aux noms qu''on ne compte pas.", "tip": "Un -s à la fin du nom ? How many.", "extraExample": {"text": "How many bags do you have?", "translation": "Combien de sacs as-tu ?"}, "errorPatterns": [{"equals": "much", "category": "grammar", "feedback": "How much s''utilise avec un nom qu''on ne compte pas (money, luggage). Tickets se compte : how many."}, {"equals": "of", "category": "grammar", "feedback": "« Combien de » se dit how many ou how much, sans of : How many tickets ?"}], "pool": "lesson", "lessonId": "en.l45", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l45.e05', 'en', 'en.l45', 'en.g30.how_much_many', array['en.g30.how_much_many','en.g28.there_is_are','en.v.luggage','en.v.airport']::text[], 'fill_blank', 'lesson', 'There ___ a lot of luggage at the airport.', array['is']::text[], 'Luggage ne se compte pas et n''a pas de pluriel : le verbe reste au singulier. On dit donc there is a lot of luggage, même s''il y a beaucoup de sacs.', 3, '{"id": "en.l45.e05", "unitIds": ["en.g30.how_much_many", "en.g28.there_is_are", "en.v.luggage", "en.v.airport"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec is, are ou have.", "prompt": "There ___ a lot of luggage at the airport.", "promptLanguage": "en", "options": ["is", "are", "have"], "answer": "is", "acceptedAnswers": ["is"], "hint": "Luggage a-t-il un pluriel ?", "explanation": "Luggage ne se compte pas et n''a pas de pluriel : le verbe reste au singulier. On dit donc there is a lot of luggage, même s''il y a beaucoup de sacs.", "tip": "Nom qu''on ne compte pas (luggage, money, bread) : there is.", "extraExample": {"text": "There is a lot of food on the table.", "translation": "Il y a beaucoup de nourriture sur la table."}, "errorPatterns": [{"equals": "are", "category": "grammar", "feedback": "Luggage n''a pas de pluriel : on ne dit pas « luggages ». Avec un nom qu''on ne compte pas, on utilise there is."}, {"equals": "have", "category": "grammar", "feedback": "« Il y a » ne se dit pas avec have. Ici, on dit there is."}], "pool": "lesson", "lessonId": "en.l45", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l45.e06', 'en', 'en.l45', 'en.g29.some_any', array['en.g29.some_any','en.g28.there_is_are','en.v.passport']::text[], 'reorder', 'lesson', 'Il n''y a pas de passeports sur la table.', array['There aren''t any passports on the table']::text[], 'Pour dire « il n''y a pas de » devant un pluriel, on dit there aren''t any + nom. Any remplace some dans une phrase négative.', 2, '{"id": "en.l45.e06", "unitIds": ["en.g29.some_any", "en.g28.there_is_are", "en.v.passport"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Il n''y a pas de passeports sur la table.", "promptLanguage": "fr", "tokens": ["any", "There", "passports", "table", "aren''t", "on", "the"], "answer": "There aren''t any passports on the table", "acceptedAnswers": ["There aren''t any passports on the table"], "hint": "There aren''t + any + nom au pluriel.", "explanation": "Pour dire « il n''y a pas de » devant un pluriel, on dit there aren''t any + nom. Any remplace some dans une phrase négative.", "tip": "Négation + pluriel : there aren''t any + nom en -s.", "extraExample": {"text": "There aren''t any hotels in this city.", "translation": "Il n''y a pas d''hôtels dans cette ville."}, "pool": "lesson", "lessonId": "en.l45", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l45.e07', 'en', 'en.l45', 'en.g30.how_much_many', array['en.g30.how_much_many','en.v.ticket','en.v.airport','en.v.price']::text[], 'translation', 'lesson', 'Combien coûte le billet pour l''aéroport ?', array['How much is the ticket to the airport?','How much is the ticket for the airport?','How much is the airport ticket?','How much does the ticket to the airport cost?']::text[], 'Pour demander le prix d''un objet, on dit How much is… ? Un seul billet, donc is. « Pour l''aéroport » se dit to the airport.', 2, '{"id": "en.l45.e07", "unitIds": ["en.g30.how_much_many", "en.v.ticket", "en.v.airport", "en.v.price"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Combien coûte le billet pour l''aéroport ?", "promptLanguage": "fr", "answer": "How much is the ticket to the airport?", "acceptedAnswers": ["How much is the ticket to the airport?", "How much is the ticket for the airport?", "How much is the airport ticket?", "How much does the ticket to the airport cost?"], "hint": "Pour demander un prix : How much is… ?", "explanation": "Pour demander le prix d''un objet, on dit How much is… ? Un seul billet, donc is. « Pour l''aéroport » se dit to the airport.", "tip": "Le prix : How much is… ? Compter des objets : How many… ?", "extraExample": {"text": "How much is the ticket to Paris?", "translation": "Combien coûte le billet pour Paris ?"}, "errorPatterns": [{"contains": "how many", "category": "grammar", "feedback": "How many sert à compter des objets. Pour demander un prix, on dit how much."}, {"contains": "how much are the ticket", "category": "grammar", "feedback": "Un seul billet : on dit is, pas are. How much is the ticket ?"}, {"equals": "how much the ticket to the airport", "category": "grammar", "feedback": "Il manque le verbe is : How much is the ticket to the airport ?"}], "pool": "lesson", "lessonId": "en.l45", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l45.e08', 'en', 'en.l45', 'en.g29.some_any', array['en.g29.some_any','en.v.luggage']::text[], 'translation', 'lesson', 'Je n''ai pas de bagages.', array['I don''t have any luggage.','I do not have any luggage.','I haven''t got any luggage.','I have no luggage.']::text[], 'Dans une phrase négative, « de, des » se dit any : I don''t have any luggage. Luggage ne prend jamais de -s.', 3, '{"id": "en.l45.e08", "unitIds": ["en.g29.some_any", "en.v.luggage"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais, avec any.", "prompt": "Je n''ai pas de bagages.", "promptLanguage": "fr", "answer": "I don''t have any luggage.", "acceptedAnswers": ["I don''t have any luggage.", "I do not have any luggage.", "I haven''t got any luggage.", "I have no luggage."], "hint": "Négation : don''t have + any + luggage (sans -s).", "explanation": "Dans une phrase négative, « de, des » se dit any : I don''t have any luggage. Luggage ne prend jamais de -s.", "tip": "Négation + nom non compté : not + any + luggage / money / bread.", "extraExample": {"text": "I don''t have any money.", "translation": "Je n''ai pas d''argent."}, "errorPatterns": [{"contains": "luggages", "category": "grammar", "feedback": "Luggage ne prend jamais de -s. Écris any luggage."}, {"contains": "some luggage", "category": "grammar", "feedback": "Dans une phrase négative, on utilise any, pas some : I don''t have any luggage."}, {"equals": "i don''t have luggage", "category": "instruction", "feedback": "Ta phrase est correcte, mais la consigne demande d''utiliser any : I don''t have any luggage."}], "pool": "lesson", "lessonId": "en.l45", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l45.e09', 'en', 'en.l45', 'en.g30.how_much_many', array['en.g30.how_much_many','en.v.luggage']::text[], 'free_answer', 'lesson', 'Comment demande-t-il « Combien de bagages as-tu ? » en anglais ?', array['How much luggage do you have?','How much luggage have you got?','How many bags do you have?','How many bags have you got?']::text[], 'Luggage est un nom qu''on ne compte pas : on dit how much luggage, sans -s. Si tu veux compter, tu peux parler de bags : How many bags ?', 3, '{"id": "en.l45.e09", "unitIds": ["en.g30.how_much_many", "en.v.luggage"], "type": "free_answer", "difficulty": 3, "context": "At the airport, a man asks Anna a question about her bags.", "instruction": "Écris la question en anglais.", "prompt": "Comment demande-t-il « Combien de bagages as-tu ? » en anglais ?", "promptLanguage": "fr", "answer": "How much luggage do you have?", "acceptedAnswers": ["How much luggage do you have?", "How much luggage have you got?", "How many bags do you have?", "How many bags have you got?"], "hint": "Luggage ne se compte pas.", "explanation": "Luggage est un nom qu''on ne compte pas : on dit how much luggage, sans -s. Si tu veux compter, tu peux parler de bags : How many bags ?", "tip": "How much luggage… ? : jamais « how many luggages ».", "extraExample": {"text": "How much money do you have?", "translation": "Combien d''argent as-tu ?"}, "errorPatterns": [{"contains": "luggages", "category": "grammar", "feedback": "Luggage ne prend jamais de -s. Écris how much luggage."}, {"equals": "how many luggage do you have", "category": "grammar", "feedback": "How many s''utilise avec un pluriel qu''on compte. Luggage ne se compte pas : how much luggage."}, {"contains": "how much bags", "category": "grammar", "feedback": "Les sacs se comptent : how many bags. Avec luggage, on dit how much luggage."}], "pool": "lesson", "lessonId": "en.l45", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l45.e10', 'en', 'en.l45', 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.station']::text[], 'free_answer', 'lesson', 'Comment dit-on « Y a-t-il une gare près de l''hôtel ? » en anglais ?', array['Is there a station near the hotel?','Is there a station close to the hotel?','Is there a station near our hotel?','Is there a station near my hotel?']::text[], 'Pour poser la question avec there is, on inverse : Is there a station… ? « Près de » se dit near. Une seule gare, donc is.', 3, '{"id": "en.l45.e10", "unitIds": ["en.g28.there_is_are", "en.v.station"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la question en anglais.", "prompt": "Comment dit-on « Y a-t-il une gare près de l''hôtel ? » en anglais ?", "promptLanguage": "fr", "answer": "Is there a station near the hotel?", "acceptedAnswers": ["Is there a station near the hotel?", "Is there a station close to the hotel?", "Is there a station near our hotel?", "Is there a station near my hotel?"], "hint": "Pour poser la question, is passe devant there.", "explanation": "Pour poser la question avec there is, on inverse : Is there a station… ? « Près de » se dit near. Une seule gare, donc is.", "tip": "There is → Is there ? : le verbe passe devant there.", "extraExample": {"text": "Is there a shop near the airport?", "translation": "Y a-t-il un magasin près de l''aéroport ?"}, "errorPatterns": [{"equals": "there is a station near the hotel", "category": "word_order", "feedback": "Pour poser une question, inverse : is passe devant there. Is there a station near the hotel ?"}, {"contains": "have a station", "category": "grammar", "feedback": "« Y a-t-il » ne se dit pas avec have. Écris Is there a station… ?"}, {"contains": "are there a", "category": "grammar", "feedback": "Are there s''utilise avec un pluriel. Une seule gare : Is there a station… ?"}], "pool": "lesson", "lessonId": "en.l45", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l46.e01', 'en', 'en.l46', 'en.g31.time_and_dates', array['en.g31.time_and_dates']::text[], 'mcq', 'lesson', 'Comment dit-on « Il est sept heures. » en anglais ?', array['It''s seven o''clock.']::text[], 'Pour dire l''heure pile, on dit It''s + nombre + o''clock : It''s seven o''clock. Hour (hours) désigne une durée (une heure de temps), pas l''heure qu''il est.', 1, '{"id": "en.l46.e01", "unitIds": ["en.g31.time_and_dates"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Il est sept heures. » en anglais ?", "promptLanguage": "fr", "options": ["It''s seven o''clock.", "It''s seven hours.", "It''s seven clock.", "It''s at seven."], "answer": "It''s seven o''clock.", "acceptedAnswers": ["It''s seven o''clock."], "hint": "Pour une heure pile, il faut un mot après le nombre.", "explanation": "Pour dire l''heure pile, on dit It''s + nombre + o''clock : It''s seven o''clock. Hour (hours) désigne une durée (une heure de temps), pas l''heure qu''il est.", "tip": "L''heure pile : nombre + o''clock, jamais « hours ».", "extraExample": {"text": "It''s nine o''clock.", "translation": "Il est neuf heures."}, "errorPatterns": [{"contains": "seven hours", "category": "word_confusion", "feedback": "Hours veut dire « durée » (an hour = 60 minutes). Pour l''heure qu''il est, on dit seven o''clock."}, {"contains": "seven clock", "category": "spelling", "feedback": "Il manque le o'' : on écrit o''clock. It''s seven o''clock."}, {"contains": "at seven", "category": "grammar", "feedback": "On utilise at pour dire « à quelle heure » (at seven). Pour dire l''heure qu''il est, on dit It''s seven o''clock."}], "pool": "lesson", "lessonId": "en.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l46.e02', 'en', 'en.l46', 'en.g31.time_and_dates', array['en.g31.time_and_dates','en.v.half']::text[], 'mcq', 'lesson', 'Comment dit-on « Il est six heures et demie. » en anglais ?', array['It''s half past six.']::text[], '« Et demie » se dit half past devant l''heure : half past six (6 h 30). On place half past avant le nombre, et on n''utilise pas and.', 2, '{"id": "en.l46.e02", "unitIds": ["en.g31.time_and_dates", "en.v.half"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Il est six heures et demie. » en anglais ?", "promptLanguage": "fr", "options": ["It''s half past six.", "It''s six and half.", "It''s half to six.", "It''s six half."], "answer": "It''s half past six.", "acceptedAnswers": ["It''s half past six."], "hint": "En anglais, on dit « demie passée » devant l''heure.", "explanation": "« Et demie » se dit half past devant l''heure : half past six (6 h 30). On place half past avant le nombre, et on n''utilise pas and.", "tip": "« Six heures et demie » = half past six : la demi-heure vient avant l''heure.", "extraExample": {"text": "It''s half past ten.", "translation": "Il est dix heures et demie."}, "errorPatterns": [{"contains": "six and half", "category": "word_order", "feedback": "En anglais, on ne dit pas « six and half ». La demie se place avant l''heure : half past six."}, {"contains": "half to six", "category": "grammar", "feedback": "To veut dire « moins » (quarter to six = 5 h 45). Pour 6 h 30, on dit half past six."}, {"contains": "six half", "category": "word_order", "feedback": "La demie se place avant l''heure et s''accompagne de past : half past six."}], "pool": "lesson", "lessonId": "en.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l46.e03', 'en', 'en.l46', 'en.v.twenty', array['en.v.twenty','en.v.hundred','en.v.hour','en.v.minute','en.v.half','en.g31.time_and_dates']::text[], 'match', 'lesson', 'L''heure et les nombres', '{}'::text[], 'Twenty (20) et hundred (100) sont des nombres. Hour est une durée (an hour = 60 minutes) : pour l''heure qu''il est, on dit o''clock. Half veut dire « la moitié, demi ».', 1, '{"id": "en.l46.e03", "unitIds": ["en.v.twenty", "en.v.hundred", "en.v.hour", "en.v.minute", "en.v.half", "en.g31.time_and_dates"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa traduction.", "prompt": "L''heure et les nombres", "promptLanguage": "fr", "pairs": [{"left": "twenty", "right": "vingt"}, {"left": "hundred", "right": "cent"}, {"left": "hour", "right": "l''heure (durée)"}, {"left": "minute", "right": "la minute"}, {"left": "half", "right": "la moitié, demi"}], "answer": "twenty = vingt ; hundred = cent ; hour = l''heure (durée) ; minute = la minute ; half = la moitié, demi", "acceptedAnswers": [], "explanation": "Twenty (20) et hundred (100) sont des nombres. Hour est une durée (an hour = 60 minutes) : pour l''heure qu''il est, on dit o''clock. Half veut dire « la moitié, demi ».", "tip": "Hour = une durée ; o''clock = l''heure sur l''horloge.", "extraExample": {"text": "It''s half past seven.", "translation": "Il est sept heures et demie."}, "pool": "lesson", "lessonId": "en.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l46.e04', 'en', 'en.l46', 'en.g31.time_and_dates', array['en.g31.time_and_dates']::text[], 'fill_blank', 'lesson', 'It''s quarter ___ eight. (7:45)', array['to']::text[], 'Avant l''heure suivante, on dit to : quarter to eight (huit heures moins le quart = 7 h 45). Past sert après l''heure : quarter past eight = 8 h 15.', 2, '{"id": "en.l46.e04", "unitIds": ["en.g31.time_and_dates"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète pour dire l''heure indiquée.", "prompt": "It''s quarter ___ eight. (7:45)", "promptLanguage": "en", "options": ["to", "past", "at"], "answer": "to", "acceptedAnswers": ["to"], "hint": "7 h 45, c''est huit heures moins le quart.", "explanation": "Avant l''heure suivante, on dit to : quarter to eight (huit heures moins le quart = 7 h 45). Past sert après l''heure : quarter past eight = 8 h 15.", "tip": "to = « moins » (avant l''heure suivante) ; past = « et » (après l''heure).", "extraExample": {"text": "It''s quarter to ten.", "translation": "Il est dix heures moins le quart."}, "errorPatterns": [{"equals": "past", "category": "grammar", "feedback": "Quarter past eight veut dire 8 h 15. Pour 7 h 45 (huit heures moins le quart), on dit quarter to eight."}, {"equals": "at", "category": "grammar", "feedback": "At ne s''utilise pas ici. Pour donner l''heure, on dit past (après) ou to (avant) : quarter to eight."}], "pool": "lesson", "lessonId": "en.l46", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l46.e05', 'en', 'en.l46', 'en.v.hundred', array['en.v.hundred']::text[], 'fill_blank', 'lesson', 'The laptop is a ___ pounds.', array['hundred']::text[], 'Cent se dit hundred. On dit a hundred ou one hundred, et hundred ne prend pas de -s après a ou un nombre : a hundred pounds.', 2, '{"id": "en.l46.e05", "unitIds": ["en.v.hundred"], "type": "fill_blank", "difficulty": 2, "context": "Tom is in a shop. He looks at a laptop.", "instruction": "Complète avec le nombre 100.", "prompt": "The laptop is a ___ pounds.", "promptLanguage": "en", "options": ["hundred", "twenty", "ten"], "answer": "hundred", "acceptedAnswers": ["hundred"], "hint": "Cent = 100.", "explanation": "Cent se dit hundred. On dit a hundred ou one hundred, et hundred ne prend pas de -s après a ou un nombre : a hundred pounds.", "tip": "100 = a hundred (ou one hundred) ; 20 = twenty.", "extraExample": {"text": "There are a hundred books in the shop.", "translation": "Il y a cent livres dans le magasin."}, "errorPatterns": [{"equals": "twenty", "category": "vocabulary", "feedback": "Twenty veut dire 20. Pour 100, on dit a hundred."}, {"equals": "ten", "category": "vocabulary", "feedback": "Ten veut dire 10. Pour 100, on dit a hundred."}], "pool": "lesson", "lessonId": "en.l46", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l46.e06', 'en', 'en.l46', 'en.g31.time_and_dates', array['en.g31.time_and_dates']::text[], 'reorder', 'lesson', 'Le vol est à six heures et demie.', array['The flight is at half past six']::text[], 'Pour dire à quelle heure, on utilise at, puis l''heure : at half past six. La demie (half past) se place avant le nombre.', 2, '{"id": "en.l46.e06", "unitIds": ["en.g31.time_and_dates"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Le vol est à six heures et demie.", "promptLanguage": "fr", "tokens": ["half", "The", "at", "is", "six", "flight", "past"], "answer": "The flight is at half past six", "acceptedAnswers": ["The flight is at half past six"], "hint": "At + la demie + past + l''heure.", "explanation": "Pour dire à quelle heure, on utilise at, puis l''heure : at half past six. La demie (half past) se place avant le nombre.", "tip": "À quelle heure ? at + heure : at half past six.", "extraExample": {"text": "The meeting is at half past nine.", "translation": "La réunion est à neuf heures et demie."}, "pool": "lesson", "lessonId": "en.l46", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l46.e07', 'en', 'en.l46', 'en.g31.time_and_dates', array['en.g31.time_and_dates']::text[], 'translation', 'lesson', 'Il est huit heures et quart.', array['It''s quarter past eight.','It''s a quarter past eight.','It''s eight fifteen.']::text[], '« Et quart » se dit quarter past + l''heure : It''s quarter past eight (8 h 15). Past veut dire « après » l''heure pile.', 2, '{"id": "en.l46.e07", "unitIds": ["en.g31.time_and_dates"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Il est huit heures et quart.", "promptLanguage": "fr", "answer": "It''s quarter past eight.", "acceptedAnswers": ["It''s quarter past eight.", "It''s a quarter past eight.", "It''s eight fifteen."], "hint": "« Et quart » se dit quarter past.", "explanation": "« Et quart » se dit quarter past + l''heure : It''s quarter past eight (8 h 15). Past veut dire « après » l''heure pile.", "tip": "Heure + et quart = quarter past + heure.", "extraExample": {"text": "It''s quarter past nine.", "translation": "Il est neuf heures et quart."}, "errorPatterns": [{"contains": "eight and quarter", "category": "word_order", "feedback": "En anglais, on ne dit pas « eight and quarter ». Le quart se place avant l''heure : quarter past eight."}, {"contains": "quarter to eight", "category": "grammar", "feedback": "Quarter to eight veut dire 7 h 45. Pour 8 h 15, on dit quarter past eight."}, {"contains": "eight hours", "category": "word_confusion", "feedback": "Hours désigne une durée. Pour dire l''heure, on dit quarter past eight ou eight o''clock."}], "pool": "lesson", "lessonId": "en.l46", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l46.e08', 'en', 'en.l46', 'en.g31.time_and_dates', array['en.g31.time_and_dates']::text[], 'translation', 'lesson', 'Je me lève à sept heures.', array['I get up at seven o''clock.','I get up at seven.']::text[], 'Pour dire à quelle heure on fait quelque chose, on utilise at + l''heure : at seven o''clock (ou simplement at seven). On ne dit pas « at 7 hours » : hours désigne une durée.', 3, '{"id": "en.l46.e08", "unitIds": ["en.g31.time_and_dates"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Je me lève à sept heures.", "promptLanguage": "fr", "answer": "I get up at seven o''clock.", "acceptedAnswers": ["I get up at seven o''clock.", "I get up at seven."], "hint": "Pour dire « à sept heures », pense à at et à o''clock.", "explanation": "Pour dire à quelle heure on fait quelque chose, on utilise at + l''heure : at seven o''clock (ou simplement at seven). On ne dit pas « at 7 hours » : hours désigne une durée.", "tip": "« À sept heures » = at seven o''clock, jamais « at 7 hours ».", "extraExample": {"text": "We have dinner at eight o''clock.", "translation": "Nous dînons à huit heures."}, "errorPatterns": [{"contains": "seven hours", "category": "word_confusion", "feedback": "Hours veut dire « durée ». Pour l''heure, on dit at seven o''clock (ou at seven)."}, {"contains": "7 hours", "category": "word_confusion", "feedback": "Hours veut dire « durée ». Pour l''heure, on dit at seven o''clock (ou at seven)."}, {"contains": "at seven clock", "category": "spelling", "feedback": "Il manque le o'' : on écrit o''clock."}], "pool": "lesson", "lessonId": "en.l46", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l46.e09', 'en', 'en.l46', 'en.v.twenty', array['en.v.twenty','en.v.minute','en.g31.time_and_dates']::text[], 'free_answer', 'lesson', 'Comment dit-on « Le vol part dans vingt minutes. » en anglais ?', array['The flight leaves in twenty minutes.','The flight is in twenty minutes.','The plane leaves in twenty minutes.','The flight leaves in 20 minutes.']::text[], '« Dans vingt minutes » se dit in twenty minutes : on utilise in pour une durée à venir. Après un nombre supérieur à un, minute prend un -s : twenty minutes.', 3, '{"id": "en.l46.e09", "unitIds": ["en.v.twenty", "en.v.minute", "en.g31.time_and_dates"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Le vol part dans vingt minutes. » en anglais ?", "promptLanguage": "fr", "answer": "The flight leaves in twenty minutes.", "acceptedAnswers": ["The flight leaves in twenty minutes.", "The flight is in twenty minutes.", "The plane leaves in twenty minutes.", "The flight leaves in 20 minutes."], "hint": "« Dans » + une durée se dit in. Minute prend un -s après vingt.", "explanation": "« Dans vingt minutes » se dit in twenty minutes : on utilise in pour une durée à venir. Après un nombre supérieur à un, minute prend un -s : twenty minutes.", "tip": "À quelle heure ? at + heure. Dans combien de temps ? in + durée.", "extraExample": {"text": "I arrive in ten minutes.", "translation": "J''arrive dans dix minutes."}, "errorPatterns": [{"contains": "at twenty minutes", "category": "preposition", "feedback": "At sert pour une heure précise (at seven). Pour « dans vingt minutes », on dit in twenty minutes."}, {"contains": "twenty minute ", "category": "grammar", "feedback": "Après un nombre supérieur à un, minute prend un -s : twenty minutes."}, {"contains": "twenty hours", "category": "vocabulary", "feedback": "Hours veut dire « heures » (durée). Vingt minutes se dit twenty minutes."}], "pool": "lesson", "lessonId": "en.l46", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l46.e10', 'en', 'en.l46', 'en.v.half', array['en.v.half','en.v.hour','en.g31.time_and_dates']::text[], 'free_answer', 'lesson', 'Comment dit-on « une demi-heure » en anglais ?', array['half an hour','a half hour','a half-hour','half hour','thirty minutes','30 minutes']::text[], '« Une demi-heure » se dit half an hour. On dit an hour (et non a hour) car le h de hour est muet : on entend un son de voyelle.', 3, '{"id": "en.l46.e10", "unitIds": ["en.v.half", "en.v.hour", "en.g31.time_and_dates"], "type": "free_answer", "difficulty": 3, "instruction": "Écris l''expression en anglais.", "prompt": "Comment dit-on « une demi-heure » en anglais ?", "promptLanguage": "fr", "answer": "half an hour", "acceptedAnswers": ["half an hour", "a half hour", "a half-hour", "half hour", "thirty minutes", "30 minutes"], "hint": "Fais attention à l''article devant hour : le h est muet.", "explanation": "« Une demi-heure » se dit half an hour. On dit an hour (et non a hour) car le h de hour est muet : on entend un son de voyelle.", "tip": "Half an hour : hour commence par un son de voyelle, donc an.", "extraExample": {"text": "The flight is in half an hour.", "translation": "Le vol est dans une demi-heure."}, "errorPatterns": [{"contains": "half a hour", "category": "grammar", "feedback": "Le h de hour est muet : on dit an hour, donc half an hour."}, {"contains": "an half hour", "category": "word_order", "feedback": "On dit half an hour (half avant an) ou a half hour, mais pas an half hour."}, {"contains": "hours", "category": "grammar", "feedback": "Une demi-heure, c''est une seule heure partagée en deux : half an hour, sans -s."}], "pool": "lesson", "lessonId": "en.l46", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l47.e01', 'en', 'en.l47', 'en.g32.word_order', array['en.g32.word_order','en.v.small']::text[], 'mcq', 'lesson', 'Comment dit-on « un petit chien » en anglais ?', array['a small dog']::text[], 'L''adjectif se met devant le nom : small dog. Il ne change pas et on choisit l''article d''après le premier mot qui suit : small commence par une consonne, donc a.', 1, '{"id": "en.l47.e01", "unitIds": ["en.g32.word_order", "en.v.small"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « un petit chien » en anglais ?", "promptLanguage": "fr", "options": ["a small dog", "a dog small", "a smalls dog", "an small dog"], "answer": "a small dog", "acceptedAnswers": ["a small dog"], "hint": "En anglais, l''adjectif se place avant le nom.", "explanation": "L''adjectif se met devant le nom : small dog. Il ne change pas et on choisit l''article d''après le premier mot qui suit : small commence par une consonne, donc a.", "tip": "L''adjectif passe devant le nom, comme dans « a small dog » : on lit d''abord la qualité, puis la chose.", "extraExample": {"text": "a small house", "translation": "une petite maison"}, "errorPatterns": [{"equals": "a dog small", "category": "word_order", "feedback": "En français l''adjectif suit souvent le nom, mais en anglais il se place avant : a small dog."}, {"equals": "a smalls dog", "category": "grammar", "feedback": "L''adjectif anglais ne prend jamais de -s. On dit a small dog."}, {"equals": "an small dog", "category": "grammar", "feedback": "An s''utilise devant un son de voyelle. Small commence par le son « s » : a small dog."}], "pool": "lesson", "lessonId": "en.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l47.e02', 'en', 'en.l47', 'en.g32.word_order', array['en.g32.word_order','en.v.big','en.v.small','en.v.new','en.v.old','en.v.beautiful']::text[], 'match', 'lesson', 'Les adjectifs devant le nom : big, small, new, old, beautiful', '{}'::text[], 'En anglais, l''adjectif vient avant le nom et ne change pas, qu''il soit masculin ou féminin. On dit an old book car old commence par un son de voyelle.', 1, '{"id": "en.l47.e02", "unitIds": ["en.g32.word_order", "en.v.big", "en.v.small", "en.v.new", "en.v.old", "en.v.beautiful"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les adjectifs devant le nom : big, small, new, old, beautiful", "promptLanguage": "fr", "pairs": [{"left": "a big house", "right": "une grande maison"}, {"left": "a small car", "right": "une petite voiture"}, {"left": "a new phone", "right": "un téléphone neuf"}, {"left": "an old book", "right": "un vieux livre"}, {"left": "a beautiful city", "right": "une belle ville"}], "answer": "a big house = une grande maison ; a small car = une petite voiture ; a new phone = un téléphone neuf ; an old book = un vieux livre ; a beautiful city = une belle ville", "acceptedAnswers": [], "explanation": "En anglais, l''adjectif vient avant le nom et ne change pas, qu''il soit masculin ou féminin. On dit an old book car old commence par un son de voyelle.", "tip": "Big, small, new, old, beautiful : un seul mot pour le masculin et le féminin.", "pool": "lesson", "lessonId": "en.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l47.e03', 'en', 'en.l47', 'en.g32.word_order', array['en.g32.word_order']::text[], 'mcq', 'lesson', 'Comment dit-on « J''aime beaucoup l''anglais. » en anglais ?', array['I like English very much.']::text[], 'En anglais, on ne met pas l''adverbe entre le verbe et son complément. On garde I like English ensemble et on ajoute very much à la fin.', 2, '{"id": "en.l47.e03", "unitIds": ["en.g32.word_order"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « J''aime beaucoup l''anglais. » en anglais ?", "promptLanguage": "fr", "options": ["I like English very much.", "I like very much English.", "I very like English.", "I like English very."], "answer": "I like English very much.", "acceptedAnswers": ["I like English very much."], "hint": "Le verbe et son complément (like English) restent ensemble.", "explanation": "En anglais, on ne met pas l''adverbe entre le verbe et son complément. On garde I like English ensemble et on ajoute very much à la fin.", "tip": "Verbe + complément d''abord, very much ensuite : I like English very much.", "extraExample": {"text": "We love our new house very much.", "translation": "Nous aimons beaucoup notre nouvelle maison."}, "errorPatterns": [{"equals": "i like very much english", "category": "word_order", "feedback": "C''est le calque du français. En anglais, very much va à la fin : I like English very much."}, {"equals": "i very like english", "category": "word_order", "feedback": "Very ne se place pas devant like seul. Pour « beaucoup », on dit very much à la fin de la phrase."}, {"equals": "i like english very", "category": "grammar", "feedback": "Very doit être suivi d''un adjectif ou de much. Il faut dire very much."}], "pool": "lesson", "lessonId": "en.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l47.e04', 'en', 'en.l47', 'en.g32.word_order', array['en.g32.word_order','en.v.new']::text[], 'fill_blank', 'lesson', 'Anna has a ___ car. (une voiture neuve)', array['new']::text[], 'New veut dire « neuf, nouveau ». L''adjectif se place entre l''article et le nom : a new car.', 2, '{"id": "en.l47.e04", "unitIds": ["en.g32.word_order", "en.v.new"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec l''adjectif qui correspond à la traduction.", "prompt": "Anna has a ___ car. (une voiture neuve)", "promptLanguage": "en", "options": ["new", "old", "small", "beautiful"], "answer": "new", "acceptedAnswers": ["new"], "hint": "Le contraire de old.", "explanation": "New veut dire « neuf, nouveau ». L''adjectif se place entre l''article et le nom : a new car.", "tip": "Article + adjectif + nom : a new car.", "extraExample": {"text": "Tom has a new phone.", "translation": "Tom a un téléphone neuf."}, "errorPatterns": [{"equals": "old", "category": "vocabulary", "feedback": "Old veut dire « vieux ». Pour « neuve », on dit new."}, {"equals": "small", "category": "vocabulary", "feedback": "Small veut dire « petit ». Pour « neuve », on dit new."}], "pool": "lesson", "lessonId": "en.l47", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l47.e05', 'en', 'en.l47', 'en.g32.word_order', array['en.g32.word_order']::text[], 'fill_blank', 'lesson', 'Tom ___ late.', array['is never']::text[], 'L''adverbe de fréquence se place après be : Tom is never late. Never est déjà négatif : on n''ajoute pas not.', 2, '{"id": "en.l47.e05", "unitIds": ["en.g32.word_order"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète pour dire que Tom n''est jamais en retard.", "prompt": "Tom ___ late.", "promptLanguage": "en", "options": ["is never", "never is", "is not never"], "answer": "is never", "acceptedAnswers": ["is never"], "hint": "Avec le verbe be, l''adverbe de fréquence se place après.", "explanation": "L''adverbe de fréquence se place après be : Tom is never late. Never est déjà négatif : on n''ajoute pas not.", "tip": "Après be, l''adverbe : is never, is always. Avec les autres verbes, il se place avant : never eats.", "extraExample": {"text": "My sister is always happy.", "translation": "Ma sœur est toujours contente."}, "errorPatterns": [{"equals": "never is", "category": "word_order", "feedback": "Avec be, l''adverbe de fréquence se met après le verbe : is never."}, {"equals": "is not never", "category": "grammar", "feedback": "Never est déjà négatif : on ne met pas not en plus. On dit is never."}], "pool": "lesson", "lessonId": "en.l47", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l47.e06', 'en', 'en.l47', 'en.g32.word_order', array['en.g32.word_order','en.v.new']::text[], 'reorder', 'lesson', 'J''aime beaucoup ma nouvelle maison.', array['I like my new house very much','I very much like my new house']::text[], 'L''ordre normal est sujet + verbe + complément : I like my new house. Ensuite on ajoute very much à la fin. L''adjectif new se place devant house.', 2, '{"id": "en.l47.e06", "unitIds": ["en.g32.word_order", "en.v.new"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "J''aime beaucoup ma nouvelle maison.", "promptLanguage": "fr", "tokens": ["house", "very", "I", "my", "much", "new", "like"], "answer": "I like my new house very much", "acceptedAnswers": ["I like my new house very much", "I very much like my new house"], "hint": "Commence par le sujet et le verbe, termine par very much.", "explanation": "L''ordre normal est sujet + verbe + complément : I like my new house. Ensuite on ajoute very much à la fin. L''adjectif new se place devant house.", "tip": "Sujet, verbe, complément, puis l''adverbe à la fin.", "extraExample": {"text": "She likes her small apartment very much.", "translation": "Elle aime beaucoup son petit appartement."}, "pool": "lesson", "lessonId": "en.l47", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l47.e07', 'en', 'en.l47', 'en.g32.word_order', array['en.g32.word_order','en.v.big']::text[], 'translation', 'lesson', 'Nous avons un grand appartement.', array['We have a big apartment.','We have a large apartment.','We have got a big apartment.','We have got a large apartment.','We have a big flat.','We have a large flat.','We have got a big flat.','We have got a large flat.']::text[], 'En anglais, l''adjectif big se place devant le nom : a big apartment. L''article a est correct car big commence par une consonne.', 2, '{"id": "en.l47.e07", "unitIds": ["en.g32.word_order", "en.v.big"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Nous avons un grand appartement.", "promptLanguage": "fr", "answer": "We have a big apartment.", "acceptedAnswers": ["We have a big apartment.", "We have a large apartment.", "We have got a big apartment.", "We have got a large apartment.", "We have a big flat.", "We have a large flat.", "We have got a big flat.", "We have got a large flat."], "hint": "Grand se place avant appartement.", "explanation": "En anglais, l''adjectif big se place devant le nom : a big apartment. L''article a est correct car big commence par une consonne.", "tip": "Grand appartement ? Big d''abord, apartment ensuite.", "extraExample": {"text": "They have a big garden.", "translation": "Ils ont un grand jardin."}, "errorPatterns": [{"contains": "apartment big", "category": "word_order", "feedback": "L''adjectif se place avant le nom : a big apartment."}, {"contains": "bigs", "category": "grammar", "feedback": "L''adjectif anglais ne prend jamais de -s : big."}, {"contains": "an big", "category": "grammar", "feedback": "Big commence par un son de consonne : on dit a big apartment."}], "pool": "lesson", "lessonId": "en.l47", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l47.e08', 'en', 'en.l47', 'en.g32.word_order', array['en.g32.word_order','en.v.old']::text[], 'translation', 'lesson', 'Nous aimons beaucoup notre vieille maison.', array['We like our old house very much.','We like our old house a lot.','We very much like our old house.','We love our old house.','We love our old house a lot.','We love our old house very much.','We really like our old house.']::text[], 'Le verbe like et son complément our old house restent ensemble, et very much vient à la fin. L''adjectif old se place avant house et ne change pas au féminin.', 3, '{"id": "en.l47.e08", "unitIds": ["en.g32.word_order", "en.v.old"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Nous aimons beaucoup notre vieille maison.", "promptLanguage": "fr", "answer": "We like our old house very much.", "acceptedAnswers": ["We like our old house very much.", "We like our old house a lot.", "We very much like our old house.", "We love our old house.", "We love our old house a lot.", "We love our old house very much.", "We really like our old house."], "hint": "Garde « like our old house » ensemble.", "explanation": "Le verbe like et son complément our old house restent ensemble, et very much vient à la fin. L''adjectif old se place avant house et ne change pas au féminin.", "tip": "Beaucoup se met à la fin : ... very much.", "extraExample": {"text": "I like my new job very much.", "translation": "J''aime beaucoup mon nouveau travail."}, "errorPatterns": [{"contains": "like very much", "category": "word_order", "feedback": "Very much ne se place pas entre le verbe et son complément. Mets-le à la fin : We like our old house very much."}, {"contains": "house old", "category": "word_order", "feedback": "L''adjectif se place avant le nom : our old house."}, {"contains": "olds", "category": "grammar", "feedback": "L''adjectif ne prend jamais de -s ni de féminin : our old house."}], "pool": "lesson", "lessonId": "en.l47", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l47.e09', 'en', 'en.l47', 'en.g32.word_order', array['en.g32.word_order','en.v.old']::text[], 'free_answer', 'lesson', 'Comment dit-on « un vieux livre » en anglais ?', array['an old book']::text[], 'L''adjectif old se place devant book. Comme old commence par un son de voyelle, l''article est an : an old book.', 3, '{"id": "en.l47.e09", "unitIds": ["en.g32.word_order", "en.v.old"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais, avec l''article qui convient.", "prompt": "Comment dit-on « un vieux livre » en anglais ?", "promptLanguage": "fr", "answer": "an old book", "acceptedAnswers": ["an old book"], "hint": "Old commence par un son de voyelle.", "explanation": "L''adjectif old se place devant book. Comme old commence par un son de voyelle, l''article est an : an old book.", "tip": "L''article s''accorde avec le mot qui le suit, donc avec l''adjectif : an old book, a good book.", "extraExample": {"text": "an old house", "translation": "une vieille maison"}, "errorPatterns": [{"equals": "a old book", "category": "grammar", "feedback": "Old commence par un son de voyelle : on dit an old book."}, {"equals": "a book old", "category": "word_order", "feedback": "L''adjectif se place avant le nom : an old book."}, {"equals": "an olds book", "category": "grammar", "feedback": "L''adjectif ne prend jamais de -s : an old book."}], "pool": "lesson", "lessonId": "en.l47", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = exclude