insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l47.e10', 'en', 'en.l47', 'en.g32.word_order', array['en.g32.word_order','en.v.beautiful']::text[], 'free_answer', 'lesson', 'Elle habite dans une belle ville.', array['She lives in a beautiful city.','She is living in a beautiful city.','She lives in a lovely city.','She is living in a lovely city.','She lives in a beautiful town.','She lives in a lovely town.']::text[], 'Beautiful reste devant le nom et ne change pas : a beautiful city. Avec she, le verbe prend un -s : lives.', 3, '{"id": "en.l47.e10", "unitIds": ["en.g32.word_order", "en.v.beautiful"], "type": "free_answer", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Elle habite dans une belle ville.", "promptLanguage": "fr", "answer": "She lives in a beautiful city.", "acceptedAnswers": ["She lives in a beautiful city.", "She is living in a beautiful city.", "She lives in a lovely city.", "She is living in a lovely city.", "She lives in a beautiful town.", "She lives in a lovely town."], "hint": "Beautiful se place entre a et city.", "explanation": "Beautiful reste devant le nom et ne change pas : a beautiful city. Avec she, le verbe prend un -s : lives.", "tip": "Beautiful est le même pour une belle ville ou un bel homme : adjectif devant le nom.", "extraExample": {"text": "He has a beautiful house.", "translation": "Il a une belle maison."}, "errorPatterns": [{"contains": "city beautiful", "category": "word_order", "feedback": "L''adjectif se place avant le nom : a beautiful city."}, {"contains": "she live in", "category": "conjugation", "feedback": "Avec she, le verbe prend un -s : she lives."}], "pool": "lesson", "lessonId": "en.l47", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_un