insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l48.e01', 'en', 'en.l48', 'en.g33.prepositions_place', array['en.g33.prepositions_place']::text[], 'mcq', 'lesson', 'Comment dit-on « Les clés sont sur la table. » en anglais ?', array['The keys are on the table.']::text[], '« Sur » une surface se dit on : on the table. In veut dire « dans » (à l''intérieur) et under veut dire « sous ».', 1, '{"id": "en.l48.e01", "unitIds": ["en.g33.prepositions_place"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Les clés sont sur la table. » en anglais ?", "promptLanguage": "fr", "options": ["The keys are on the table.", "The keys are in the table.", "The keys are under the table."], "answer": "The keys are on the table.", "acceptedAnswers": ["The keys are on the table."], "hint": "Les clés sont posées sur une surface.", "explanation": "« Sur » une surface se dit on : on the table. In veut dire « dans » (à l''intérieur) et under veut dire « sous ».", "tip": "Sur une surface plate : on. À l''intérieur : in.", "extraExample": {"text": "The book is on the sofa.", "translation": "Le livre est sur le canapé."}, "errorPatterns": [{"equals": "the keys are in the table", "category": "preposition", "feedback": "In veut dire « à l''intérieur de ». Les clés sont sur la surface de la table : on the table."}, {"equals": "the keys are under the table", "category": "vocabulary", "feedback": "Under veut dire « sous ». Pour « sur », on dit on."}], "pool": "lesson", "lessonId": "en.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = ex