insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l48.e02', 'en', 'en.l48', 'en.g33.prepositions_place', array['en.g33.prepositions_place']::text[], 'match', 'lesson', 'Où est le chien ? Les prépositions de position.', '{}'::text[], 'Ces cinq mots disent la position exacte d''une chose. Devant se dit in front of, en trois mots, avec of à la fin.', 1, '{"id": "en.l48.e02", "unitIds": ["en.g33.prepositions_place"], "type": "match", "difficulty": 1, "instruction": "Associe chaque préposition anglaise à sa traduction.", "prompt": "Où est le chien ? Les prépositions de position.", "promptLanguage": "fr", "pairs": [{"left": "in front of", "right": "devant"}, {"left": "behind", "right": "derrière"}, {"left": "next to", "right": "à côté de"}, {"left": "between", "right": "entre"}, {"left": "under", "right": "sous"}], "answer": "in front of = devant ; behind = derrière ; next to = à côté de ; between = entre ; under = sous", "acceptedAnswers": [], "explanation": "Ces cinq mots disent la position exacte d''une chose. Devant se dit in front of, en trois mots, avec of à la fin.", "tip": "Behind et in front of sont contraires : derrière et devant.", "pool": "lesson", "lessonId": "en.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l48.e03', 'en', 'en.l48', 'en.g33.prepositions_place', array['en.g33.prepositions_place','en.v.floor']::text[], 'mcq', 'lesson', 'The bedroom is ___ the second floor.', array['on']::text[], 'Pour un étage, on utilise on : on the second floor. Floor veut dire « étage » ou « sol ».', 2, '{"id": "en.l48.e03", "unitIds": ["en.g33.prepositions_place", "en.v.floor"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne préposition.", "prompt": "The bedroom is ___ the second floor.", "promptLanguage": "en", "options": ["on", "in", "at"], "answer": "on", "acceptedAnswers": ["on"], "hint": "Un étage est comme une surface sur laquelle on se trouve.", "explanation": "Pour un étage, on utilise on : on the second floor. Floor veut dire « étage » ou « sol ».", "tip": "Les étages se comptent avec on : on the first floor, on the third floor.", "extraExample": {"text": "The kitchen is on the first floor.", "translation": "La cuisine est au premier étage."}, "errorPatterns": [{"equals": "in", "category": "preposition", "feedback": "Avec un étage, on dit on, pas in : on the second floor."}, {"equals": "at", "category": "preposition", "feedback": "At s''utilise pour un point précis (at the door). Pour un étage, on dit on the second floor."}], "pool": "lesson", "lessonId": "en.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l48.e04', 'en', 'en.l48', 'en.g33.prepositions_place', array['en.g33.prepositions_place','en.v.park']::text[], 'fill_blank', 'lesson', 'The park is ___ the school and the station. (entre l''école et la gare)', array['between']::text[], 'Between veut dire « entre ». On l''utilise avec deux éléments reliés par and : between the school and the station.', 2, '{"id": "en.l48.e04", "unitIds": ["en.g33.prepositions_place", "en.v.park"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la préposition qui correspond à la traduction.", "prompt": "The park is ___ the school and the station. (entre l''école et la gare)", "promptLanguage": "en", "options": ["between", "behind", "under", "in"], "answer": "between", "acceptedAnswers": ["between"], "hint": "Il y a deux lieux, un de chaque côté.", "explanation": "Between veut dire « entre ». On l''utilise avec deux éléments reliés par and : between the school and the station.", "tip": "Between prend toujours deux éléments : between A and B.", "extraExample": {"text": "The shop is between the hotel and the park.", "translation": "Le magasin est entre l''hôtel et le parc."}, "errorPatterns": [{"equals": "behind", "category": "vocabulary", "feedback": "Behind veut dire « derrière ». Pour « entre », on dit between."}, {"equals": "in", "category": "preposition", "feedback": "In veut dire « dans ». Pour « entre deux lieux », on dit between."}], "pool": "lesson", "lessonId": "en.l48", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l48.e05', 'en', 'en.l48', 'en.g33.prepositions_place', array['en.g33.prepositions_place','en.v.building']::text[], 'fill_blank', 'lesson', 'There is a car ___ the building. (devant l''immeuble)', array['in front of']::text[], '« Devant » se dit in front of. Il faut les trois mots, et of reste avant the building.', 2, '{"id": "en.l48.e05", "unitIds": ["en.g33.prepositions_place", "en.v.building"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec l''expression qui correspond à la traduction.", "prompt": "There is a car ___ the building. (devant l''immeuble)", "promptLanguage": "en", "options": ["in front of", "in front", "front of"], "answer": "in front of", "acceptedAnswers": ["in front of"], "hint": "Cette expression s''écrit en trois mots.", "explanation": "« Devant » se dit in front of. Il faut les trois mots, et of reste avant the building.", "tip": "In front of : n''oublie jamais of. In front the building est faux.", "extraExample": {"text": "The dog is in front of the door.", "translation": "Le chien est devant la porte."}, "errorPatterns": [{"equals": "in front", "category": "preposition", "feedback": "Il manque of. On dit in front of the building."}, {"equals": "front of", "category": "preposition", "feedback": "Il manque in au début : in front of the building."}], "pool": "lesson", "lessonId": "en.l48", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l48.e06', 'en', 'en.l48', 'en.g33.prepositions_place', array['en.g33.prepositions_place','en.v.street','en.v.corner']::text[], 'reorder', 'lesson', 'Il y a un parc au coin de la rue.', array['There is a park at the corner of the street','At the corner of the street there is a park']::text[], 'There is a park dit qu''il y a un parc. At the corner of the street donne son emplacement : at pour un point précis, of the street pour « de la rue ».', 3, '{"id": "en.l48.e06", "unitIds": ["en.g33.prepositions_place", "en.v.street", "en.v.corner"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Il y a un parc au coin de la rue.", "promptLanguage": "fr", "tokens": ["corner", "the", "a", "There", "is", "park", "of", "street", "at", "the"], "answer": "There is a park at the corner of the street", "acceptedAnswers": ["There is a park at the corner of the street", "At the corner of the street there is a park"], "hint": "Commence par There is. Le coin se dit the corner of the street.", "explanation": "There is a park dit qu''il y a un parc. At the corner of the street donne son emplacement : at pour un point précis, of the street pour « de la rue ».", "tip": "Au coin de la rue : at the corner of the street.", "extraExample": {"text": "There is a shop at the corner of the street.", "translation": "Il y a un magasin au coin de la rue."}, "pool": "lesson", "lessonId": "en.l48", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l48.e07', 'en', 'en.l48', 'en.g33.prepositions_place', array['en.g33.prepositions_place','en.v.building']::text[], 'translation', 'lesson', 'Mon appartement est dans un grand bâtiment.', array['My apartment is in a big building.','My apartment is in a large building.','My flat is in a big building.','My flat is in a large building.','My apartment is inside a big building.','My apartment is in a big apartment building.']::text[], 'Un bâtiment est un espace fermé : on dit in a building. L''adjectif big se place avant building.', 2, '{"id": "en.l48.e07", "unitIds": ["en.g33.prepositions_place", "en.v.building"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Mon appartement est dans un grand bâtiment.", "promptLanguage": "fr", "answer": "My apartment is in a big building.", "acceptedAnswers": ["My apartment is in a big building.", "My apartment is in a large building.", "My flat is in a big building.", "My flat is in a large building.", "My apartment is inside a big building.", "My apartment is in a big apartment building."], "hint": "Dans un bâtiment, c''est à l''intérieur.", "explanation": "Un bâtiment est un espace fermé : on dit in a building. L''adjectif big se place avant building.", "tip": "À l''intérieur d''un lieu fermé (bâtiment, ville, pièce), on utilise in.", "extraExample": {"text": "My office is in a new building.", "translation": "Mon bureau est dans un nouvel immeuble."}, "errorPatterns": [{"contains": "on a big building", "category": "preposition", "feedback": "Ton appartement est à l''intérieur du bâtiment : in a big building, pas on."}, {"contains": "at a big building", "category": "preposition", "feedback": "At s''utilise pour un point précis. À l''intérieur d''un bâtiment, on dit in."}, {"contains": "building big", "category": "word_order", "feedback": "L''adjectif se place avant le nom : a big building."}], "pool": "lesson", "lessonId": "en.l48", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l48.e08', 'en', 'en.l48', 'en.g33.prepositions_place', array['en.g33.prepositions_place','en.v.park']::text[], 'translation', 'lesson', 'La gare est à côté du parc.', array['The station is next to the park.','The station is beside the park.','The station is near the park.','The station is by the park.']::text[], 'À côté de se dit next to. En anglais, il n''y a pas d''équivalent de « du » : on garde the park.', 3, '{"id": "en.l48.e08", "unitIds": ["en.g33.prepositions_place", "en.v.park"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "La gare est à côté du parc.", "promptLanguage": "fr", "answer": "The station is next to the park.", "acceptedAnswers": ["The station is next to the park.", "The station is beside the park.", "The station is near the park.", "The station is by the park."], "hint": "« À côté de » se dit en deux mots : next ... .", "explanation": "À côté de se dit next to. En anglais, il n''y a pas d''équivalent de « du » : on garde the park.", "tip": "À côté de ? Next to, avec to à la fin.", "extraExample": {"text": "The shop is next to the station.", "translation": "Le magasin est à côté de la gare."}, "errorPatterns": [{"contains": "next the", "category": "preposition", "feedback": "Il manque to : next to the park."}, {"contains": "next of", "category": "preposition", "feedback": "À côté de se dit next to, pas next of."}, {"contains": "in front of", "category": "vocabulary", "feedback": "In front of veut dire « devant ». Pour « à côté de », on dit next to."}], "pool": "lesson", "lessonId": "en.l48", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l48.e09', 'en', 'en.l48', 'en.g33.prepositions_place', array['en.g33.prepositions_place','en.v.floor']::text[], 'free_answer', 'lesson', 'Il habite au troisième étage.', array['He lives on the third floor.','He lives on the 3rd floor.','He is living on the third floor.','He is living on the 3rd floor.']::text[], 'Un étage se dit avec on : on the third floor. Avec he, le verbe live prend un -s.', 3, '{"id": "en.l48.e09", "unitIds": ["en.g33.prepositions_place", "en.v.floor"], "type": "free_answer", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Il habite au troisième étage.", "promptLanguage": "fr", "answer": "He lives on the third floor.", "acceptedAnswers": ["He lives on the third floor.", "He lives on the 3rd floor.", "He is living on the third floor.", "He is living on the 3rd floor."], "hint": "Pour un étage, on utilise la même préposition que pour une surface.", "explanation": "Un étage se dit avec on : on the third floor. Avec he, le verbe live prend un -s.", "tip": "Étage = on the ... floor. Ville = in. Maison ou travail = at.", "extraExample": {"text": "My parents live on the second floor.", "translation": "Mes parents habitent au deuxième étage."}, "errorPatterns": [{"contains": "in the third floor", "category": "preposition", "feedback": "Pour un étage, on dit on, pas in : on the third floor."}, {"contains": "at the third floor", "category": "preposition", "feedback": "Pour un étage, on dit on, pas at : on the third floor."}, {"contains": "he live on", "category": "conjugation", "feedback": "Avec he, le verbe prend un -s : he lives."}], "pool": "lesson", "lessonId": "en.l48", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l48.e10', 'en', 'en.l48', 'en.g33.prepositions_place', array['en.g33.prepositions_place']::text[], 'free_answer', 'lesson', 'Dis où est ton téléphone ou ton sac dans ta maison, avec une préposition de lieu (in, on, under, next to, behind...).', array['My phone is on the sofa.','My bag is under the table.','My phone is next to the lamp.','My bag is in the bedroom.','My keys are behind the door.']::text[], 'Pour situer un objet, on utilise be + préposition + lieu : My phone is on the sofa. Choisis in pour l''intérieur, on pour une surface, under pour dessous.', 3, '{"id": "en.l48.e10", "unitIds": ["en.g33.prepositions_place"], "type": "free_answer", "difficulty": 3, "instruction": "Écris une phrase en anglais.", "prompt": "Dis où est ton téléphone ou ton sac dans ta maison, avec une préposition de lieu (in, on, under, next to, behind...).", "promptLanguage": "fr", "requirements": {"mustInclude": [["in", "on", "at", "under", "next to", "between", "behind", "in front of"]], "minWords": 4}, "answer": "My phone is on the sofa.", "acceptedAnswers": ["My phone is on the sofa.", "My bag is under the table.", "My phone is next to the lamp.", "My bag is in the bedroom.", "My keys are behind the door."], "hint": "Commence par My phone is ... ou My bag is ...", "explanation": "Pour situer un objet, on utilise be + préposition + lieu : My phone is on the sofa. Choisis in pour l''intérieur, on pour une surface, under pour dessous.", "tip": "Sujet + is / are + préposition + the + lieu.", "extraExample": {"text": "The lamp is next to the chair.", "translation": "La lampe est à côté de la chaise."}, "errorPatterns": [{"contains": "in the table", "category": "preposition", "feedback": "Pour un objet posé sur la table, on dit on the table."}, {"contains": "in front the", "category": "preposition", "feedback": "Devant se dit in front of : n''oublie pas of."}, {"contains": "in home", "category": "preposition", "feedback": "À la maison se dit at home."}], "pool": "lesson", "lessonId": "en.l48", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l49.e01', 'en', 'en.l49', 'en.g34.prepositions_time', array['en.g34.prepositions_time','en.v.monday']::text[], 'mcq', 'lesson', 'She has a meeting ___ Monday.', array['on']::text[], 'Avec un jour de la semaine, on utilise on : on Monday. Monday prend aussi une majuscule en anglais.', 1, '{"id": "en.l49.e01", "unitIds": ["en.g34.prepositions_time", "en.v.monday"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne préposition.", "prompt": "She has a meeting ___ Monday.", "promptLanguage": "en", "options": ["on", "in", "at"], "answer": "on", "acceptedAnswers": ["on"], "hint": "Monday est un jour de la semaine.", "explanation": "Avec un jour de la semaine, on utilise on : on Monday. Monday prend aussi une majuscule en anglais.", "tip": "Un jour = on. Le lundi, c''est on Monday.", "extraExample": {"text": "We have a party on Sunday.", "translation": "Nous avons une fête dimanche."}, "errorPatterns": [{"equals": "in", "category": "preposition", "feedback": "In sert pour les mois, les saisons et les années. Pour un jour de la semaine, on dit on Monday."}, {"equals": "at", "category": "preposition", "feedback": "At sert pour l''heure exacte (at 8 o''clock). Pour un jour de la semaine, on dit on Monday."}], "pool": "lesson", "lessonId": "en.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l49.e02', 'en', 'en.l49', 'en.g34.prepositions_time', array['en.g34.prepositions_time','en.v.sunday','en.v.january','en.v.winter']::text[], 'match', 'lesson', 'Les prépositions de temps : at, on, in', '{}'::text[], 'At va avec l''heure, on avec un jour, in avec un mois, une saison ou un moment de la journée. En français, « le dimanche » et « le matin » se disent sans préposition, mais en anglais il en faut une.', 1, '{"id": "en.l49.e02", "unitIds": ["en.g34.prepositions_time", "en.v.sunday", "en.v.january", "en.v.winter"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les prépositions de temps : at, on, in", "promptLanguage": "fr", "pairs": [{"left": "at 7 o''clock", "right": "à 7 heures"}, {"left": "on Sunday", "right": "le dimanche"}, {"left": "in January", "right": "en janvier"}, {"left": "in winter", "right": "en hiver"}, {"left": "in the morning", "right": "le matin"}], "answer": "at 7 o''clock = à 7 heures ; on Sunday = le dimanche ; in January = en janvier ; in winter = en hiver ; in the morning = le matin", "acceptedAnswers": [], "explanation": "At va avec l''heure, on avec un jour, in avec un mois, une saison ou un moment de la journée. En français, « le dimanche » et « le matin » se disent sans préposition, mais en anglais il en faut une.", "tip": "At 7 o''clock, on Sunday, in January : de plus précis à plus large.", "pool": "lesson", "lessonId": "en.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l49.e03', 'en', 'en.l49', 'en.g34.prepositions_time', array['en.g34.prepositions_time','en.v.summer']::text[], 'mcq', 'lesson', 'We go to the beach ___ summer.', array['in']::text[], 'Pour une saison, un mois ou une année, on utilise in : in summer. On peut aussi dire in the summer.', 2, '{"id": "en.l49.e03", "unitIds": ["en.g34.prepositions_time", "en.v.summer"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne préposition.", "prompt": "We go to the beach ___ summer.", "promptLanguage": "en", "options": ["in", "on", "at"], "answer": "in", "acceptedAnswers": ["in"], "hint": "Une saison dure plusieurs mois.", "explanation": "Pour une saison, un mois ou une année, on utilise in : in summer. On peut aussi dire in the summer.", "tip": "Saison, mois, année : in. Les saisons s''écrivent sans majuscule.", "extraExample": {"text": "I like the beach in winter.", "translation": "J''aime la plage en hiver."}, "errorPatterns": [{"equals": "on", "category": "preposition", "feedback": "On sert pour un jour (on Monday) ou une date. Pour une saison, on dit in summer."}, {"equals": "at", "category": "preposition", "feedback": "At sert pour l''heure exacte (at 8 o''clock). Pour une saison, on dit in summer."}], "pool": "lesson", "lessonId": "en.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l49.e04', 'en', 'en.l49', 'en.g34.prepositions_time', array['en.g34.prepositions_time']::text[], 'fill_blank', 'lesson', 'I never drink coffee ___ night.', array['at']::text[], 'La nuit se dit at night, sans the. C''est une exception : le matin, l''après-midi et le soir se disent avec in, mais la nuit se dit avec at.', 2, '{"id": "en.l49.e04", "unitIds": ["en.g34.prepositions_time"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la préposition qui convient.", "prompt": "I never drink coffee ___ night.", "promptLanguage": "en", "options": ["at", "in", "on"], "answer": "at", "acceptedAnswers": ["at"], "hint": "C''est une expression fixe, sans article.", "explanation": "La nuit se dit at night, sans the. C''est une exception : le matin, l''après-midi et le soir se disent avec in, mais la nuit se dit avec at.", "tip": "In the morning, in the evening, mais at night.", "extraExample": {"text": "My dog sleeps at night.", "translation": "Mon chien dort la nuit."}, "errorPatterns": [{"equals": "in", "category": "preposition", "feedback": "On dit in the morning et in the evening, mais pour la nuit c''est une exception : at night."}, {"equals": "on", "category": "preposition", "feedback": "On sert pour un jour ou une date. La nuit se dit at night."}], "pool": "lesson", "lessonId": "en.l49", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l49.e05', 'en', 'en.l49', 'en.g34.prepositions_time', array['en.g34.prepositions_time']::text[], 'fill_blank', 'lesson', 'I always read ___ dinner. (après le dîner)', array['after']::text[], 'After veut dire « après ». Before veut dire « avant » et during veut dire « pendant ». Aucun des trois ne demande de petit mot en plus : after dinner.', 2, '{"id": "en.l49.e05", "unitIds": ["en.g34.prepositions_time"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le mot qui correspond à la traduction.", "prompt": "I always read ___ dinner. (après le dîner)", "promptLanguage": "en", "options": ["after", "before", "during"], "answer": "after", "acceptedAnswers": ["after"], "hint": "Le contraire de before.", "explanation": "After veut dire « après ». Before veut dire « avant » et during veut dire « pendant ». Aucun des trois ne demande de petit mot en plus : after dinner.", "tip": "Before = avant, after = après, during = pendant.", "extraExample": {"text": "I watch TV before dinner.", "translation": "Je regarde la télé avant le dîner."}, "errorPatterns": [{"equals": "before", "category": "vocabulary", "feedback": "Before veut dire « avant ». Pour « après », on dit after."}, {"equals": "during", "category": "vocabulary", "feedback": "During veut dire « pendant ». Pour « après », on dit after."}], "pool": "lesson", "lessonId": "en.l49", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l49.e06', 'en', 'en.l49', 'en.g34.prepositions_time', array['en.g34.prepositions_time','en.v.monday']::text[], 'reorder', 'lesson', 'Je travaille au bureau le lundi matin.', array['I work at the office on Monday morning','On Monday morning I work at the office','I work on Monday morning at the office']::text[], 'Un jour de la semaine, même suivi du matin, se construit avec on : on Monday morning. At the office dit où tu travailles.', 3, '{"id": "en.l49.e06", "unitIds": ["en.g34.prepositions_time", "en.v.monday"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Je travaille au bureau le lundi matin.", "promptLanguage": "fr", "tokens": ["morning", "I", "on", "the", "Monday", "work", "at", "office"], "answer": "I work at the office on Monday morning", "acceptedAnswers": ["I work at the office on Monday morning", "On Monday morning I work at the office", "I work on Monday morning at the office"], "hint": "Le lundi matin se dit on Monday morning.", "explanation": "Un jour de la semaine, même suivi du matin, se construit avec on : on Monday morning. At the office dit où tu travailles.", "tip": "Jour + moment de la journée : on Monday morning, on Sunday evening.", "extraExample": {"text": "I go to the gym on Sunday morning.", "translation": "Je vais à la salle de sport le dimanche matin."}, "pool": "lesson", "lessonId": "en.l49", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l49.e07', 'en', 'en.l49', 'en.g34.prepositions_time', array['en.g34.prepositions_time','en.v.january']::text[], 'translation', 'lesson', 'Mon anniversaire est en janvier.', array['My birthday is in January.']::text[], 'Pour un mois, on utilise in : in January. Les mois prennent toujours une majuscule en anglais.', 2, '{"id": "en.l49.e07", "unitIds": ["en.g34.prepositions_time", "en.v.january"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Mon anniversaire est en janvier.", "promptLanguage": "fr", "answer": "My birthday is in January.", "acceptedAnswers": ["My birthday is in January."], "hint": "Janvier est un mois. N''oublie pas la majuscule.", "explanation": "Pour un mois, on utilise in : in January. Les mois prennent toujours une majuscule en anglais.", "tip": "Un mois = in, avec une majuscule : in January.", "extraExample": {"text": "The shop is closed in January.", "translation": "Le magasin est fermé en janvier."}, "errorPatterns": [{"contains": "on january", "category": "preposition", "feedback": "On s''utilise pour une date précise (on 5 January). Pour un mois seul, on dit in January."}, {"contains": "at january", "category": "preposition", "feedback": "At sert pour l''heure exacte. Pour un mois, on dit in January."}, {"contains": "birthday are", "category": "conjugation", "feedback": "Birthday est au singulier : my birthday is."}], "pool": "lesson", "lessonId": "en.l49", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l49.e08', 'en', 'en.l49', 'en.g34.prepositions_time', array['en.g34.prepositions_time','en.v.sunday']::text[], 'translation', 'lesson', 'Le dimanche, je reste à la maison.', array['On Sunday I stay at home.','On Sundays I stay at home.','I stay at home on Sunday.','I stay at home on Sundays.','On Sunday I stay home.','On Sundays I stay home.','I stay home on Sunday.','I stay home on Sundays.']::text[], 'Le dimanche se dit on Sunday (ou on Sundays pour une habitude). Rester à la maison se dit stay at home.', 3, '{"id": "en.l49.e08", "unitIds": ["en.g34.prepositions_time", "en.v.sunday"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Le dimanche, je reste à la maison.", "promptLanguage": "fr", "answer": "On Sunday I stay at home.", "acceptedAnswers": ["On Sunday I stay at home.", "On Sundays I stay at home.", "I stay at home on Sunday.", "I stay at home on Sundays.", "On Sunday I stay home.", "On Sundays I stay home.", "I stay home on Sunday.", "I stay home on Sundays."], "hint": "En français, il n''y a pas de préposition devant dimanche. En anglais, si.", "explanation": "Le dimanche se dit on Sunday (ou on Sundays pour une habitude). Rester à la maison se dit stay at home.", "tip": "Même sans préposition en français, on ajoute on devant un jour : on Sunday.", "extraExample": {"text": "On Monday I work at the office.", "translation": "Le lundi, je travaille au bureau."}, "errorPatterns": [{"contains": "in sunday", "category": "preposition", "feedback": "Pour un jour de la semaine, on dit on Sunday, pas in."}, {"contains": "at sunday", "category": "preposition", "feedback": "At sert pour l''heure exacte. Pour un jour de la semaine, on dit on Sunday."}, {"contains": "in home", "category": "preposition", "feedback": "À la maison se dit at home."}], "pool": "lesson", "lessonId": "en.l49", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l49.e09', 'en', 'en.l49', 'en.g34.prepositions_time', array['en.g34.prepositions_time','en.v.winter']::text[], 'free_answer', 'lesson', 'Il fait froid en hiver.', array['It is cold in winter.','It is cold in the winter.','It is cold during winter.','It is cold during the winter.']::text[], 'Il fait froid se dit it is cold. Pour une saison, on utilise in : in winter. Winter s''écrit sans majuscule.', 3, '{"id": "en.l49.e09", "unitIds": ["en.g34.prepositions_time", "en.v.winter"], "type": "free_answer", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Il fait froid en hiver.", "promptLanguage": "fr", "answer": "It is cold in winter.", "acceptedAnswers": ["It is cold in winter.", "It is cold in the winter.", "It is cold during winter.", "It is cold during the winter."], "hint": "Pour parler de la météo, on commence par it is.", "explanation": "Il fait froid se dit it is cold. Pour une saison, on utilise in : in winter. Winter s''écrit sans majuscule.", "tip": "Météo : it is + adjectif. Saison : in + nom de la saison.", "extraExample": {"text": "Anna travels in summer.", "translation": "Anna voyage en été."}, "errorPatterns": [{"contains": "on winter", "category": "preposition", "feedback": "On sert pour un jour ou une date. Pour une saison, on dit in winter."}, {"contains": "at winter", "category": "preposition", "feedback": "At sert pour l''heure exacte. Pour une saison, on dit in winter."}, {"contains": "has cold", "category": "grammar", "feedback": "On ne dit pas « il a froid » pour la météo : it is cold."}], "pool": "lesson", "lessonId": "en.l49", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l49.e10', 'en', 'en.l49', 'en.g34.prepositions_time', array['en.g34.prepositions_time','en.v.monday']::text[], 'free_answer', 'lesson', 'Dis ce que tu fais le lundi, avec on Monday.', array['On Monday I go to work.','I work at the office on Monday.','I go to the gym on Monday.','On Mondays I study English.']::text[], 'Un jour de la semaine demande on : on Monday. Ensuite, la phrase suit l''ordre habituel sujet + verbe + complément.', 3, '{"id": "en.l49.e10", "unitIds": ["en.g34.prepositions_time", "en.v.monday"], "type": "free_answer", "difficulty": 3, "instruction": "Écris une phrase en anglais.", "prompt": "Dis ce que tu fais le lundi, avec on Monday.", "promptLanguage": "fr", "requirements": {"mustInclude": [["monday", "mondays"], ["on"]], "minWords": 4}, "answer": "On Monday I go to work.", "acceptedAnswers": ["On Monday I go to work.", "I work at the office on Monday.", "I go to the gym on Monday.", "On Mondays I study English."], "hint": "Tu peux commencer par On Monday I ...", "explanation": "Un jour de la semaine demande on : on Monday. Ensuite, la phrase suit l''ordre habituel sujet + verbe + complément.", "tip": "On Monday au début ou à la fin de la phrase : les deux sont possibles.", "extraExample": {"text": "I play music on Sunday.", "translation": "Je joue de la musique le dimanche."}, "errorPatterns": [{"contains": "in monday", "category": "preposition", "feedback": "Pour un jour de la semaine, on dit on Monday, pas in."}, {"contains": "at monday", "category": "preposition", "feedback": "At sert pour l''heure exacte. Pour un jour de la semaine, on dit on Monday."}], "pool": "lesson", "lessonId": "en.l49", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l50.e01', 'en', 'en.l50', 'en.g35.question_words', array['en.g35.question_words']::text[], 'mcq', 'lesson', 'Comment dit-on « Où habites-tu ? » en anglais ?', array['Where do you live?']::text[], 'Une question avec where suit l''ordre : where + do + sujet + verbe. Avec you, on utilise do, pas does.', 1, '{"id": "en.l50.e01", "unitIds": ["en.g35.question_words"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Où habites-tu ? » en anglais ?", "promptLanguage": "fr", "options": ["Where do you live?", "Where you live?", "Where live you?", "Where does you live?"], "answer": "Where do you live?", "acceptedAnswers": ["Where do you live?"], "hint": "Il faut un auxiliaire entre where et you.", "explanation": "Une question avec where suit l''ordre : where + do + sujet + verbe. Avec you, on utilise do, pas does.", "tip": "Mot interrogatif + do / does + sujet + verbe.", "extraExample": {"text": "Where do they work?", "translation": "Où travaillent-ils ?"}, "errorPatterns": [{"equals": "where you live", "category": "word_order", "feedback": "En anglais, il faut l''auxiliaire do : Where do you live?"}, {"equals": "where live you", "category": "word_order", "feedback": "L''inversion verbe-sujet n''existe pas ainsi en anglais. On dit Where do you live?"}, {"equals": "where does you live", "category": "grammar", "feedback": "Does s''utilise avec he, she, it. Avec you, on dit do : Where do you live?"}], "pool": "lesson", "lessonId": "en.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l50.e02', 'en', 'en.l50', 'en.g35.question_words', array['en.g35.question_words']::text[], 'match', 'lesson', 'Les mots interrogatifs : what, where, when, who, why', '{}'::text[], 'Ces cinq mots commencent presque tous par wh-. Ils se placent au début de la question. Why pose la question « pourquoi », et on répond avec because.', 1, '{"id": "en.l50.e02", "unitIds": ["en.g35.question_words"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot interrogatif à sa traduction.", "prompt": "Les mots interrogatifs : what, where, when, who, why", "promptLanguage": "fr", "pairs": [{"left": "what", "right": "quoi / que / quel"}, {"left": "where", "right": "où"}, {"left": "when", "right": "quand"}, {"left": "who", "right": "qui"}, {"left": "why", "right": "pourquoi"}], "answer": "what = quoi / que / quel ; where = où ; when = quand ; who = qui ; why = pourquoi", "acceptedAnswers": [], "explanation": "Ces cinq mots commencent presque tous par wh-. Ils se placent au début de la question. Why pose la question « pourquoi », et on répond avec because.", "tip": "Where = où (lieu), when = quand (moment), who = qui (personne), why = pourquoi (raison).", "pool": "lesson", "lessonId": "en.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l50.e03', 'en', 'en.l50', 'en.g35.question_words', array['en.g35.question_words','en.v.place']::text[], 'mcq', 'lesson', '___ place do you like, the park or the beach?', array['Which']::text[], 'Which veut dire « lequel, laquelle ». On l''utilise quand on choisit entre quelques possibilités connues, ici le parc ou la plage. Place veut dire « endroit, lieu ».', 2, '{"id": "en.l50.e03", "unitIds": ["en.g35.question_words", "en.v.place"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot interrogatif.", "prompt": "___ place do you like, the park or the beach?", "promptLanguage": "en", "options": ["Which", "Who", "Why"], "answer": "Which", "acceptedAnswers": ["Which"], "hint": "Il faut choisir entre deux possibilités.", "explanation": "Which veut dire « lequel, laquelle ». On l''utilise quand on choisit entre quelques possibilités connues, ici le parc ou la plage. Place veut dire « endroit, lieu ».", "tip": "Choix entre quelques options : which. Question ouverte : what.", "extraExample": {"text": "Which book do you want, the old book or the new book?", "translation": "Quel livre veux-tu, le vieux livre ou le nouveau ?"}, "errorPatterns": [{"equals": "who", "category": "word_confusion", "feedback": "Who veut dire « qui » et ne s''emploie que pour une personne. Ici, on choisit entre deux lieux : which."}, {"equals": "why", "category": "word_confusion", "feedback": "Why veut dire « pourquoi ». Pour choisir entre deux possibilités, on dit which."}], "pool": "lesson", "lessonId": "en.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l50.e04', 'en', 'en.l50', 'en.g35.question_words', array['en.g35.question_words','en.v.time']::text[], 'fill_blank', 'lesson', 'What ___ is it? It is ten o''clock.', array['time']::text[], 'Pour demander l''heure, on dit What time is it? Time veut dire ici « heure ». On ne dit pas what hour.', 2, '{"id": "en.l50.e04", "unitIds": ["en.g35.question_words", "en.v.time"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la question pour demander l''heure.", "prompt": "What ___ is it? It is ten o''clock.", "promptLanguage": "en", "options": ["time", "hour", "age"], "answer": "time", "acceptedAnswers": ["time"], "hint": "Time veut dire « heure » ou « temps ».", "explanation": "Pour demander l''heure, on dit What time is it? Time veut dire ici « heure ». On ne dit pas what hour.", "tip": "Quelle heure est-il ? What time is it ?", "extraExample": {"text": "What time do you get up?", "translation": "À quelle heure te lèves-tu ?"}, "errorPatterns": [{"equals": "hour", "category": "word_confusion", "feedback": "Hour désigne une durée de 60 minutes. Pour demander l''heure, on dit what time."}, {"equals": "age", "category": "vocabulary", "feedback": "Age veut dire « âge ». Pour l''heure, on dit what time is it?"}], "pool": "lesson", "lessonId": "en.l50", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l50.e05', 'en', 'en.l50', 'en.g35.question_words', array['en.g35.question_words','en.v.address']::text[], 'fill_blank', 'lesson', '___ is your address? (Quelle est ton adresse ?)', array['What']::text[], 'On utilise what pour demander une information sur une chose : What is your address? Where veut dire « où » et who veut dire « qui ».', 2, '{"id": "en.l50.e05", "unitIds": ["en.g35.question_words", "en.v.address"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot interrogatif.", "prompt": "___ is your address? (Quelle est ton adresse ?)", "promptLanguage": "en", "options": ["What", "Where", "Who"], "answer": "What", "acceptedAnswers": ["What"], "hint": "On demande quelle chose, pas un lieu ni une personne.", "explanation": "On utilise what pour demander une information sur une chose : What is your address? Where veut dire « où » et who veut dire « qui ».", "tip": "Quelle est ton adresse, ton nom, ton âge ? What is your ... ?", "extraExample": {"text": "What is your name?", "translation": "Comment t''appelles-tu ?"}, "errorPatterns": [{"equals": "where", "category": "word_confusion", "feedback": "Where veut dire « où ». Pour « quelle est ton adresse ? », on dit What is your address?"}, {"equals": "who", "category": "word_confusion", "feedback": "Who veut dire « qui » et concerne une personne. Pour une adresse, on dit what."}], "pool": "lesson", "lessonId": "en.l50", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l50.e06', 'en', 'en.l50', 'en.g35.question_words', array['en.g35.question_words','en.v.time']::text[], 'reorder', 'lesson', 'À quelle heure commence la réunion ?', array['What time does the meeting start']::text[], 'L''ordre est : what time + does + sujet + verbe. Meeting est au singulier, donc on utilise does, et le verbe start reste à la forme de base.', 3, '{"id": "en.l50.e06", "unitIds": ["en.g35.question_words", "en.v.time"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "À quelle heure commence la réunion ?", "promptLanguage": "fr", "tokens": ["does", "What", "start", "the", "time", "meeting"], "answer": "What time does the meeting start", "acceptedAnswers": ["What time does the meeting start"], "hint": "Commence par what time, puis l''auxiliaire, puis le sujet.", "explanation": "L''ordre est : what time + does + sujet + verbe. Meeting est au singulier, donc on utilise does, et le verbe start reste à la forme de base.", "tip": "What time + auxiliaire + sujet + verbe de base.", "extraExample": {"text": "What time does the shop open?", "translation": "À quelle heure ouvre le magasin ?"}, "pool": "lesson", "lessonId": "en.l50", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l50.e07', 'en', 'en.l50', 'en.g35.question_words', array['en.g35.question_words']::text[], 'translation', 'lesson', 'Pourquoi es-tu en retard ?', array['Why are you late?']::text[], 'Avec le verbe be, on inverse be et le sujet, sans auxiliaire : Why are you late? On ne dit pas why do you are.', 2, '{"id": "en.l50.e07", "unitIds": ["en.g35.question_words"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Pourquoi es-tu en retard ?", "promptLanguage": "fr", "answer": "Why are you late?", "acceptedAnswers": ["Why are you late?"], "hint": "Avec be, on inverse le verbe et le sujet.", "explanation": "Avec le verbe be, on inverse be et le sujet, sans auxiliaire : Why are you late? On ne dit pas why do you are.", "tip": "Avec be, pas de do : Why are you ... ?", "extraExample": {"text": "Why is Tom tired?", "translation": "Pourquoi Tom est-il fatigué ?"}, "errorPatterns": [{"contains": "why you are", "category": "word_order", "feedback": "Il faut inverser : Why are you late?"}, {"contains": "why do you are", "category": "grammar", "feedback": "Avec be, on n''utilise pas do. On inverse simplement : Why are you late?"}, {"contains": "why you late", "category": "grammar", "feedback": "Il manque le verbe be : Why are you late?"}], "pool": "lesson", "lessonId": "en.l50", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l50.e08', 'en', 'en.l50', 'en.g35.question_words', array['en.g35.question_words','en.v.age']::text[], 'translation', 'lesson', 'Quel âge a ton frère ?', array['How old is your brother?','What is your brother''s age?','What age is your brother?']::text[], 'Pour demander l''âge, on dit How old + be + sujet : How old is your brother? Le mot age existe, mais on dit plus naturellement how old.', 3, '{"id": "en.l50.e08", "unitIds": ["en.g35.question_words", "en.v.age"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Quel âge a ton frère ?", "promptLanguage": "fr", "answer": "How old is your brother?", "acceptedAnswers": ["How old is your brother?", "What is your brother''s age?", "What age is your brother?"], "hint": "En anglais, on ne « possède » pas un âge : on utilise be.", "explanation": "Pour demander l''âge, on dit How old + be + sujet : How old is your brother? Le mot age existe, mais on dit plus naturellement how old.", "tip": "Âge ? How old + be, jamais have.", "extraExample": {"text": "How old are your parents?", "translation": "Quel âge ont tes parents ?"}, "errorPatterns": [{"contains": "what age has", "category": "grammar", "feedback": "En anglais, on ne dit pas « quel âge a-t-il » avec have. On dit How old is your brother?"}, {"contains": "how old has", "category": "grammar", "feedback": "Avec how old, on utilise be : How old is your brother?"}, {"contains": "how old does", "category": "grammar", "feedback": "Avec how old, on utilise be, pas do : How old is your brother?"}], "pool": "lesson", "lessonId": "en.l50", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l50.e09', 'en', 'en.l50', 'en.g35.question_words', array['en.g35.question_words']::text[], 'free_answer', 'lesson', 'Quand est-ce que tu finis le travail ?', array['When do you finish work?','When do you finish your work?','When do you stop work?']::text[], 'When veut dire « quand ». L''ordre est : when + do + sujet + verbe. Après do, le verbe finish reste à la forme de base.', 3, '{"id": "en.l50.e09", "unitIds": ["en.g35.question_words"], "type": "free_answer", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Quand est-ce que tu finis le travail ?", "promptLanguage": "fr", "answer": "When do you finish work?", "acceptedAnswers": ["When do you finish work?", "When do you finish your work?", "When do you stop work?"], "hint": "Commence par when, puis do.", "explanation": "When veut dire « quand ». L''ordre est : when + do + sujet + verbe. Après do, le verbe finish reste à la forme de base.", "tip": "Quand ? When + do + sujet + verbe.", "extraExample": {"text": "When does your sister arrive?", "translation": "Quand ta sœur arrive-t-elle ?"}, "errorPatterns": [{"contains": "when you finish", "category": "word_order", "feedback": "Il faut l''auxiliaire do : When do you finish work?"}, {"contains": "when do you finishes", "category": "conjugation", "feedback": "Après do, le verbe reste à la forme de base : finish."}, {"contains": "when finish", "category": "word_order", "feedback": "Il faut un auxiliaire et un sujet : When do you finish work?"}], "pool": "lesson", "lessonId": "en.l50", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l50.e10', 'en', 'en.l50', 'en.g35.question_words', array['en.g35.question_words','en.v.reason']::text[], 'free_answer', 'lesson', 'Comment dit-on « Quelle est la raison ? » en anglais ?', array['What is the reason?','What is the reason for that?']::text[], 'On demande une information avec what. Reason veut dire « raison ». Avec be, l''ordre est : what + is + sujet : What is the reason?', 3, '{"id": "en.l50.e10", "unitIds": ["en.g35.question_words", "en.v.reason"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Quelle est la raison ? » en anglais ?", "promptLanguage": "fr", "answer": "What is the reason?", "acceptedAnswers": ["What is the reason?", "What is the reason for that?"], "hint": "On commence par what, et il faut le verbe be.", "explanation": "On demande une information avec what. Reason veut dire « raison ». Avec be, l''ordre est : what + is + sujet : What is the reason?", "tip": "What is + nom : What is the reason? What is your name?", "extraExample": {"text": "What is the reason for the problem?", "translation": "Quelle est la raison du problème ?"}, "errorPatterns": [{"equals": "what the reason", "category": "grammar", "feedback": "Il manque le verbe be : What is the reason?"}, {"equals": "which is the reason", "category": "word_confusion", "feedback": "Which sert à choisir parmi quelques possibilités. Ici, la question est ouverte : What is the reason?"}, {"equals": "why is the reason", "category": "word_confusion", "feedback": "Why veut dire « pourquoi ». Pour « quelle est la raison », on dit What is the reason?"}], "pool": "lesson", "lessonId": "en.l50", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l51.e01', 'en', 'en.l51', 'en.g36.connectors', array['en.g36.connectors','en.v.hot']::text[], 'mcq', 'lesson', 'Comment dit-on « Il fait chaud, donc je bois de l''eau. » en anglais ?', array['It is hot, so I drink water.']::text[], '« Donc » se dit so : il introduit la conséquence. La chaleur est la cause, et boire de l''eau est le résultat.', 1, '{"id": "en.l51.e01", "unitIds": ["en.g36.connectors", "en.v.hot"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Il fait chaud, donc je bois de l''eau. » en anglais ?", "promptLanguage": "fr", "options": ["It is hot, so I drink water.", "It is hot, because I drink water.", "It is hot, but I drink water.", "It is hot, or I drink water."], "answer": "It is hot, so I drink water.", "acceptedAnswers": ["It is hot, so I drink water."], "hint": "Boire de l''eau est la conséquence de la chaleur.", "explanation": "« Donc » se dit so : il introduit la conséquence. La chaleur est la cause, et boire de l''eau est le résultat.", "tip": "So = donc : il vient après la cause et annonce le résultat.", "extraExample": {"text": "I am tired, so I go to bed.", "translation": "Je suis fatigué, donc je vais me coucher."}, "errorPatterns": [{"equals": "it is hot because i drink water", "category": "grammar", "feedback": "Because introduit la cause. Ici, boire de l''eau est la conséquence de la chaleur : on utilise so."}, {"equals": "it is hot but i drink water", "category": "grammar", "feedback": "But marque une opposition. Ici, c''est une conséquence : so."}, {"equals": "it is hot or i drink water", "category": "grammar", "feedback": "Or veut dire « ou » et propose un choix. Pour « donc », on dit so."}], "pool": "lesson", "lessonId": "en.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l51.e02', 'en', 'en.l51', 'en.g36.connectors', array['en.g36.connectors']::text[], 'match', 'lesson', 'Les connecteurs : and, but, or, because, so', '{}'::text[], 'And ajoute, but oppose, or propose un choix, because donne la raison et so donne le résultat. Ces mots relient deux phrases ou deux idées.', 1, '{"id": "en.l51.e02", "unitIds": ["en.g36.connectors"], "type": "match", "difficulty": 1, "instruction": "Associe chaque connecteur à sa traduction.", "prompt": "Les connecteurs : and, but, or, because, so", "promptLanguage": "fr", "pairs": [{"left": "and", "right": "et"}, {"left": "but", "right": "mais"}, {"left": "or", "right": "ou"}, {"left": "because", "right": "parce que"}, {"left": "so", "right": "donc, alors"}], "answer": "and = et ; but = mais ; or = ou ; because = parce que ; so = donc, alors", "acceptedAnswers": [], "explanation": "And ajoute, but oppose, or propose un choix, because donne la raison et so donne le résultat. Ces mots relient deux phrases ou deux idées.", "tip": "Because = la cause, so = la conséquence.", "pool": "lesson", "lessonId": "en.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l51.e03', 'en', 'en.l51', 'en.g36.connectors', array['en.g36.connectors','en.v.snow']::text[], 'mcq', 'lesson', 'Comment dit-on « Je reste à la maison parce qu''il neige. » en anglais ?', array['I stay at home because it snows.']::text[], 'Because veut dire « parce que » et il est suivi d''une phrase complète : sujet + verbe (it snows). Snow est ici un verbe : it snows veut dire « il neige ».', 2, '{"id": "en.l51.e03", "unitIds": ["en.g36.connectors", "en.v.snow"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Je reste à la maison parce qu''il neige. » en anglais ?", "promptLanguage": "fr", "options": ["I stay at home because it snows.", "I stay at home because the snow.", "I stay at home so it snows.", "I stay at home but it snows."], "answer": "I stay at home because it snows.", "acceptedAnswers": ["I stay at home because it snows."], "hint": "Après because, il faut un sujet et un verbe.", "explanation": "Because veut dire « parce que » et il est suivi d''une phrase complète : sujet + verbe (it snows). Snow est ici un verbe : it snows veut dire « il neige ».", "tip": "Because + sujet + verbe : because it snows, because I am tired.", "extraExample": {"text": "We stay in because it rains.", "translation": "Nous restons à l''intérieur parce qu''il pleut."}, "errorPatterns": [{"equals": "i stay at home because the snow", "category": "grammar", "feedback": "Après because, il faut un sujet et un verbe : because it snows."}, {"equals": "i stay at home so it snows", "category": "grammar", "feedback": "So annonce un résultat. Ici, la neige est la cause : because it snows."}, {"equals": "i stay at home but it snows", "category": "grammar", "feedback": "But marque une opposition. Ici, la neige est la raison de rester : because."}], "pool": "lesson", "lessonId": "en.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l51.e04', 'en', 'en.l51', 'en.g36.connectors', array['en.g36.connectors','en.v.sun']::text[], 'fill_blank', 'lesson', 'I like summer, ___ I don''t like the sun. (mais)', array['but']::text[], 'But veut dire « mais » : il relie deux idées qui s''opposent. J''aime l''été, mais je n''aime pas le soleil.', 2, '{"id": "en.l51.e04", "unitIds": ["en.g36.connectors", "en.v.sun"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le connecteur qui correspond à la traduction.", "prompt": "I like summer, ___ I don''t like the sun. (mais)", "promptLanguage": "en", "options": ["but", "so", "because"], "answer": "but", "acceptedAnswers": ["but"], "hint": "Les deux idées s''opposent.", "explanation": "But veut dire « mais » : il relie deux idées qui s''opposent. J''aime l''été, mais je n''aime pas le soleil.", "tip": "Deux idées opposées ? But.", "extraExample": {"text": "The apartment is small, but it is beautiful.", "translation": "L''appartement est petit, mais il est beau."}, "errorPatterns": [{"equals": "so", "category": "grammar", "feedback": "So donne une conséquence. Ici, les deux idées s''opposent : on utilise but."}, {"equals": "because", "category": "grammar", "feedback": "Because donne une cause. Ici, les deux idées s''opposent : on utilise but."}], "pool": "lesson", "lessonId": "en.l51", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l51.e05', 'en', 'en.l51', 'en.g36.connectors', array['en.g36.connectors']::text[], 'fill_blank', 'lesson', 'First I eat breakfast, ___ I go to work. (puis)', array['then','and then']::text[], 'Then veut dire « puis, ensuite » : il montre qu''une action vient après une autre. Than s''écrit presque pareil mais sert aux comparaisons (taller than).', 2, '{"id": "en.l51.e05", "unitIds": ["en.g36.connectors"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le mot qui correspond à la traduction.", "prompt": "First I eat breakfast, ___ I go to work. (puis)", "promptLanguage": "en", "options": ["then", "than", "because"], "answer": "then", "acceptedAnswers": ["then", "and then"], "hint": "Il montre l''ordre des actions. Attention à l''orthographe : then, pas than.", "explanation": "Then veut dire « puis, ensuite » : il montre qu''une action vient après une autre. Than s''écrit presque pareil mais sert aux comparaisons (taller than).", "tip": "Then (avec e) = puis ; than (avec a) = que, dans une comparaison.", "extraExample": {"text": "I finish my homework, then I watch TV.", "translation": "Je finis mes devoirs, puis je regarde la télé."}, "errorPatterns": [{"equals": "than", "category": "spelling", "feedback": "Than sert aux comparaisons (taller than). Pour « puis », on écrit then."}, {"equals": "because", "category": "grammar", "feedback": "Because veut dire « parce que ». Pour « puis, ensuite », on dit then."}], "pool": "lesson", "lessonId": "en.l51", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l51.e06', 'en', 'en.l51', 'en.g36.connectors', array['en.g36.connectors','en.v.warm']::text[], 'reorder', 'lesson', 'Il fait doux aujourd''hui, donc nous allons à la plage.', array['It is warm today so we go to the beach','Today it is warm so we go to the beach','It is warm so we go to the beach today','It is warm so today we go to the beach']::text[], 'So relie la cause et le résultat : It is warm today (cause), so we go to the beach (résultat). Warm veut dire « doux, agréablement chaud ». Today peut se placer au début ou à la fin.', 3, '{"id": "en.l51.e06", "unitIds": ["en.g36.connectors", "en.v.warm"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Il fait doux aujourd''hui, donc nous allons à la plage.", "promptLanguage": "fr", "tokens": ["beach", "we", "It", "so", "warm", "go", "today", "is", "the", "to"], "answer": "It is warm today so we go to the beach", "acceptedAnswers": ["It is warm today so we go to the beach", "Today it is warm so we go to the beach", "It is warm so we go to the beach today", "It is warm so today we go to the beach"], "hint": "So sépare la cause (il fait doux) du résultat (nous allons à la plage).", "explanation": "So relie la cause et le résultat : It is warm today (cause), so we go to the beach (résultat). Warm veut dire « doux, agréablement chaud ». Today peut se placer au début ou à la fin.", "tip": "Cause d''abord, puis so, puis résultat.", "extraExample": {"text": "It is hot, so we swim.", "translation": "Il fait chaud, donc nous nageons."}, "pool": "lesson", "lessonId": "en.l51", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l51.e07', 'en', 'en.l51', 'en.g36.connectors', array['en.g36.connectors','en.v.wind']::text[], 'translation', 'lesson', 'Il y a du vent, donc je ferme la fenêtre.', array['There is wind, so I close the window.','There is a lot of wind, so I close the window.','It is windy, so I close the window.','There is wind, so I am closing the window.','It is windy, so I am closing the window.']::text[], 'Le vent est la cause et fermer la fenêtre est la conséquence : on utilise so. Wind est un nom, il faut donc there is wind (ou it is windy).', 2, '{"id": "en.l51.e07", "unitIds": ["en.g36.connectors", "en.v.wind"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Il y a du vent, donc je ferme la fenêtre.", "promptLanguage": "fr", "answer": "There is wind, so I close the window.", "acceptedAnswers": ["There is wind, so I close the window.", "There is a lot of wind, so I close the window.", "It is windy, so I close the window.", "There is wind, so I am closing the window.", "It is windy, so I am closing the window."], "hint": "Donc se dit so. Wind veut dire « vent ».", "explanation": "Le vent est la cause et fermer la fenêtre est la conséquence : on utilise so. Wind est un nom, il faut donc there is wind (ou it is windy).", "tip": "Donc = so, et on met so entre la cause et la conséquence.", "extraExample": {"text": "There is snow, so we stay at home.", "translation": "Il y a de la neige, donc nous restons à la maison."}, "errorPatterns": [{"contains": "because i close", "category": "grammar", "feedback": "Because introduit la cause. Ici, fermer la fenêtre est la conséquence du vent : on utilise so."}, {"contains": "the wind is", "category": "grammar", "feedback": "Pour dire « il y a du vent », on dit there is wind (ou it is windy)."}], "pool": "lesson", "lessonId": "en.l51", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l51.e08', 'en', 'en.l51', 'en.g36.connectors', array['en.g36.connectors','en.v.snow']::text[], 'translation', 'lesson', 'J''aime l''hiver, mais je n''aime pas la neige.', array['I like winter, but I don''t like snow.','I like winter, but I don''t like the snow.','I like the winter, but I don''t like snow.','I like the winter, but I don''t like the snow.','I love winter, but I don''t like snow.','I love winter, but I don''t like the snow.','I love the winter, but I don''t like snow.','I love the winter, but I don''t like the snow.']::text[], 'But relie deux idées opposées. La négation se fait avec don''t + like. En anglais, on dit souvent winter et snow sans the quand on parle en général.', 3, '{"id": "en.l51.e08", "unitIds": ["en.g36.connectors", "en.v.snow"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "J''aime l''hiver, mais je n''aime pas la neige.", "promptLanguage": "fr", "answer": "I like winter, but I don''t like snow.", "acceptedAnswers": ["I like winter, but I don''t like snow.", "I like winter, but I don''t like the snow.", "I like the winter, but I don''t like snow.", "I like the winter, but I don''t like the snow.", "I love winter, but I don''t like snow.", "I love winter, but I don''t like the snow.", "I love the winter, but I don''t like snow.", "I love the winter, but I don''t like the snow."], "hint": "Mais se dit but. Pour la négation, utilise don''t.", "explanation": "But relie deux idées opposées. La négation se fait avec don''t + like. En anglais, on dit souvent winter et snow sans the quand on parle en général.", "tip": "But oppose deux idées : I like ..., but I don''t like ...", "extraExample": {"text": "I like summer, but I don''t like the sun.", "translation": "J''aime l''été, mais je n''aime pas le soleil."}, "errorPatterns": [{"contains": "because i don''t", "category": "grammar", "feedback": "Because veut dire « parce que ». Pour « mais », on dit but."}, {"contains": "i not like", "category": "grammar", "feedback": "La négation se fait avec don''t : I don''t like snow."}, {"contains": "i no like", "category": "grammar", "feedback": "En anglais, on ne dit pas « no like ». On dit I don''t like."}], "pool": "lesson", "lessonId": "en.l51", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l51.e09', 'en', 'en.l51', 'en.g36.connectors', array['en.g36.connectors','en.v.hot']::text[], 'free_answer', 'lesson', 'Nous allons à la plage parce qu''il fait chaud.', array['We go to the beach because it is hot.','We are going to the beach because it is hot.','We go to the beach because it is warm.','We are going to the beach because it is warm.']::text[], 'Because donne la cause : il fait chaud est la raison d''aller à la plage. Après because, il faut un sujet et un verbe : it is hot.', 3, '{"id": "en.l51.e09", "unitIds": ["en.g36.connectors", "en.v.hot"], "type": "free_answer", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Nous allons à la plage parce qu''il fait chaud.", "promptLanguage": "fr", "answer": "We go to the beach because it is hot.", "acceptedAnswers": ["We go to the beach because it is hot.", "We are going to the beach because it is hot.", "We go to the beach because it is warm.", "We are going to the beach because it is warm."], "hint": "Après because, mets un sujet et un verbe : it is hot.", "explanation": "Because donne la cause : il fait chaud est la raison d''aller à la plage. Après because, il faut un sujet et un verbe : it is hot.", "tip": "Because est toujours suivi d''un sujet et d''un verbe : because it is hot.", "extraExample": {"text": "We stay at home because it is cold.", "translation": "Nous restons à la maison parce qu''il fait froid."}, "errorPatterns": [{"contains": "because of", "category": "grammar", "feedback": "Ici, because est suivi d''une phrase complète : because it is hot."}, {"contains": "because hot", "category": "grammar", "feedback": "Il manque un sujet et un verbe après because : because it is hot."}, {"contains": "so it is hot", "category": "grammar", "feedback": "So annonce un résultat. Ici, il fait chaud est la cause : because it is hot."}], "pool": "lesson", "lessonId": "en.l51", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l51.e10', 'en', 'en.l51', 'en.g36.connectors', array['en.g36.connectors']::text[], 'free_answer', 'lesson', 'Dis quelle saison tu aimes et pourquoi, avec because.', array['I like summer because it is warm.','I like winter because it snows.','I like summer because I go to the beach.','I like winter because I stay at home.']::text[], 'Because donne la raison : I like summer because it is warm. Après because, on écrit une phrase complète avec un sujet et un verbe.', 3, '{"id": "en.l51.e10", "unitIds": ["en.g36.connectors"], "type": "free_answer", "difficulty": 3, "instruction": "Écris une phrase en anglais.", "prompt": "Dis quelle saison tu aimes et pourquoi, avec because.", "promptLanguage": "fr", "requirements": {"mustInclude": [["because"]], "minWords": 5}, "answer": "I like summer because it is warm.", "acceptedAnswers": ["I like summer because it is warm.", "I like winter because it snows.", "I like summer because I go to the beach.", "I like winter because I stay at home."], "hint": "Commence par I like ... because ...", "explanation": "Because donne la raison : I like summer because it is warm. Après because, on écrit une phrase complète avec un sujet et un verbe.", "tip": "I like + saison + because + sujet + verbe.", "extraExample": {"text": "I like Sunday because I don''t work.", "translation": "J''aime le dimanche parce que je ne travaille pas."}, "errorPatterns": [{"contains": "because of", "category": "grammar", "feedback": "Ici, because est suivi d''une phrase complète avec sujet et verbe : because it is warm."}, {"contains": "because so", "category": "grammar", "feedback": "Because et so ne s''utilisent pas ensemble. Choisis because pour la raison."}], "pool": "lesson", "lessonId": "en.l51", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l52.e01', 'en', 'en.l52', 'en.g37.comparatives_superlatives', array['en.g37.comparatives_superlatives','en.v.tall']::text[], 'mcq', 'lesson', 'Comment dit-on « Tom est plus grand qu''Anna. » en anglais ?', array['Tom is taller than Anna.']::text[], 'Avec un adjectif court comme tall, on ajoute -er : taller. Pour comparer, on utilise than (« que »). Tom is taller than Anna.', 1, '{"id": "en.l52.e01", "unitIds": ["en.g37.comparatives_superlatives", "en.v.tall"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Tom est plus grand qu''Anna. » en anglais ?", "promptLanguage": "fr", "options": ["Tom is taller than Anna.", "Tom is more tall than Anna.", "Tom is taller that Anna.", "Tom is tallest than Anna."], "answer": "Tom is taller than Anna.", "acceptedAnswers": ["Tom is taller than Anna."], "hint": "Tall est un adjectif court : on ajoute -er. Et « que » se dit than.", "explanation": "Avec un adjectif court comme tall, on ajoute -er : taller. Pour comparer, on utilise than (« que »). Tom is taller than Anna.", "tip": "Adjectif court + -er + than : taller than.", "extraExample": {"text": "My father is older than my mother.", "translation": "Mon père est plus âgé que ma mère."}, "errorPatterns": [{"equals": "tom is more tall than anna", "category": "grammar", "feedback": "Tall est un adjectif court : on ajoute -er (taller), on n''utilise pas more."}, {"equals": "tom is taller that anna", "category": "spelling", "feedback": "« Que » dans une comparaison se dit than, pas that."}, {"equals": "tom is tallest than anna", "category": "grammar", "feedback": "Tallest veut dire « le plus grand ». Pour comparer deux personnes avec than, on dit taller."}], "pool": "lesson", "lessonId": "en.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l52.e02', 'en', 'en.l52', 'en.g37.comparatives_superlatives', array['en.g37.comparatives_superlatives','en.v.fast','en.v.slow','en.v.tall','en.v.short','en.v.easy']::text[], 'match', 'lesson', 'Les comparatifs : faster, slower, taller, shorter, easier', '{}'::text[], 'Pour fast, slow, tall et short, on ajoute simplement -er. Pour easy, le y devient i : easier.', 1, '{"id": "en.l52.e02", "unitIds": ["en.g37.comparatives_superlatives", "en.v.fast", "en.v.slow", "en.v.tall", "en.v.short", "en.v.easy"], "type": "match", "difficulty": 1, "instruction": "Associe chaque comparatif à sa traduction.", "prompt": "Les comparatifs : faster, slower, taller, shorter, easier", "promptLanguage": "fr", "pairs": [{"left": "faster", "right": "plus rapide"}, {"left": "slower", "right": "plus lent"}, {"left": "taller", "right": "plus grand (taille)"}, {"left": "shorter", "right": "plus court, plus petit (taille)"}, {"left": "easier", "right": "plus facile"}], "answer": "faster = plus rapide ; slower = plus lent ; taller = plus grand (taille) ; shorter = plus court, plus petit (taille) ; easier = plus facile", "acceptedAnswers": [], "explanation": "Pour fast, slow, tall et short, on ajoute simplement -er. Pour easy, le y devient i : easier.", "tip": "Mot court + -er. Mot en -y : y devient i (easy, easier).", "pool": "lesson", "lessonId": "en.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l52.e03', 'en', 'en.l52', 'en.g37.comparatives_superlatives', array['en.g37.comparatives_superlatives','en.v.easy']::text[], 'mcq', 'lesson', 'Comment dit-on « le plus facile » en anglais ?', array['the easiest']::text[], 'Easy est un adjectif court qui finit par -y : le y devient i, puis on ajoute -est. Le superlatif se forme avec the : the easiest.', 2, '{"id": "en.l52.e03", "unitIds": ["en.g37.comparatives_superlatives", "en.v.easy"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « le plus facile » en anglais ?", "promptLanguage": "fr", "options": ["the easiest", "the most easy", "the easyest", "the easier"], "answer": "the easiest", "acceptedAnswers": ["the easiest"], "hint": "Quand l''adjectif finit par -y, le y devient i.", "explanation": "Easy est un adjectif court qui finit par -y : le y devient i, puis on ajoute -est. Le superlatif se forme avec the : the easiest.", "tip": "Easy, easier, the easiest : le y devient i.", "extraExample": {"text": "This is the easiest book.", "translation": "C''est le livre le plus facile."}, "errorPatterns": [{"equals": "the most easy", "category": "grammar", "feedback": "Easy est un adjectif court : on ne met pas most. Le y devient i, et on ajoute -est : the easiest."}, {"equals": "the easyest", "category": "spelling", "feedback": "Le y de easy devient i : easiest."}, {"equals": "the easier", "category": "grammar", "feedback": "Easier est le comparatif (plus facile). Pour « le plus facile », on dit the easiest."}], "pool": "lesson", "lessonId": "en.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l52.e04', 'en', 'en.l52', 'en.g37.comparatives_superlatives', array['en.g37.comparatives_superlatives','en.v.fast']::text[], 'fill_blank', 'lesson', 'My new car is ___ than my old car. (plus rapide)', array['faster']::text[], 'Avec un adjectif court, on ajoute -er pour comparer : fast, faster. Than introduit le deuxième terme de la comparaison.', 2, '{"id": "en.l52.e04", "unitIds": ["en.g37.comparatives_superlatives", "en.v.fast"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme de fast.", "prompt": "My new car is ___ than my old car. (plus rapide)", "promptLanguage": "en", "options": ["faster", "more fast", "fastest"], "answer": "faster", "acceptedAnswers": ["faster"], "hint": "Fast est un adjectif court.", "explanation": "Avec un adjectif court, on ajoute -er pour comparer : fast, faster. Than introduit le deuxième terme de la comparaison.", "tip": "Une seule syllabe ? On ajoute -er.", "extraExample": {"text": "Anna is faster than Tom.", "translation": "Anna est plus rapide que Tom."}, "errorPatterns": [{"equals": "more fast", "category": "grammar", "feedback": "Fast est un adjectif court : on ajoute -er, on n''utilise pas more. On dit faster."}, {"equals": "fastest", "category": "grammar", "feedback": "Fastest veut dire « le plus rapide ». Avec than, on utilise le comparatif : faster."}], "pool": "lesson", "lessonId": "en.l52", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l52.e05', 'en', 'en.l52', 'en.g37.comparatives_superlatives', array['en.g37.comparatives_superlatives','en.v.tall']::text[], 'fill_blank', 'lesson', 'Tom is the ___ in the family. (le plus grand)', array['tallest']::text[], 'Pour dire « le plus grand », on utilise the + -est : the tallest. Taller sert à comparer deux personnes avec than.', 2, '{"id": "en.l52.e05", "unitIds": ["en.g37.comparatives_superlatives", "en.v.tall"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme de tall.", "prompt": "Tom is the ___ in the family. (le plus grand)", "promptLanguage": "en", "options": ["tallest", "taller", "most tall"], "answer": "tallest", "acceptedAnswers": ["tallest"], "hint": "Après the, on utilise le superlatif.", "explanation": "Pour dire « le plus grand », on utilise the + -est : the tallest. Taller sert à comparer deux personnes avec than.", "tip": "the + adjectif court + -est : the tallest, the oldest.", "extraExample": {"text": "Anna is the oldest in the family.", "translation": "Anna est la plus âgée de la famille."}, "errorPatterns": [{"equals": "taller", "category": "grammar", "feedback": "Taller veut dire « plus grand » et s''utilise avec than. Après the, il faut le superlatif : the tallest."}, {"equals": "most tall", "category": "grammar", "feedback": "Tall est un adjectif court : on ajoute -est (tallest), on n''utilise pas most."}], "pool": "lesson", "lessonId": "en.l52", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l52.e06', 'en', 'en.l52', 'en.g37.comparatives_superlatives', array['en.g37.comparatives_superlatives','en.v.beautiful']::text[], 'reorder', 'lesson', 'C''est la plus belle ville du pays.', array['It is the most beautiful city in the country']::text[], 'Beautiful est un adjectif long, donc on utilise the most : the most beautiful. Pour dire « du pays », on dit in the country, avec in.', 3, '{"id": "en.l52.e06", "unitIds": ["en.g37.comparatives_superlatives", "en.v.beautiful"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "C''est la plus belle ville du pays.", "promptLanguage": "fr", "tokens": ["city", "the", "country", "It", "beautiful", "in", "most", "is", "the"], "answer": "It is the most beautiful city in the country", "acceptedAnswers": ["It is the most beautiful city in the country"], "hint": "Beautiful est un mot long : on utilise the most devant.", "explanation": "Beautiful est un adjectif long, donc on utilise the most : the most beautiful. Pour dire « du pays », on dit in the country, avec in.", "tip": "Mot long : the most + adjectif. Et on dit in the country, pas of.", "extraExample": {"text": "It is the most expensive hotel in the city.", "translation": "C''est l''hôtel le plus cher de la ville."}, "pool": "lesson", "lessonId": "en.l52", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l52.e07', 'en', 'en.l52', 'en.g37.comparatives_superlatives', array['en.g37.comparatives_superlatives','en.v.slow']::text[], 'translation', 'lesson', 'Mon frère est plus lent que moi.', array['My brother is slower than me.','My brother is slower than I am.','My brother is slower than I.']::text[], 'Slow est un adjectif court : on ajoute -er, ce qui donne slower. On compare avec than : slower than me.', 2, '{"id": "en.l52.e07", "unitIds": ["en.g37.comparatives_superlatives", "en.v.slow"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Mon frère est plus lent que moi.", "promptLanguage": "fr", "answer": "My brother is slower than me.", "acceptedAnswers": ["My brother is slower than me.", "My brother is slower than I am.", "My brother is slower than I."], "hint": "Slow est un adjectif court. « Que » se dit than.", "explanation": "Slow est un adjectif court : on ajoute -er, ce qui donne slower. On compare avec than : slower than me.", "tip": "Plus lent que : slower than. Pas de more devant un adjectif court.", "extraExample": {"text": "My sister is shorter than my brother.", "translation": "Ma sœur est plus petite que mon frère."}, "errorPatterns": [{"contains": "more slow", "category": "grammar", "feedback": "Slow est un adjectif court : on ajoute -er (slower), on n''utilise pas more."}, {"contains": "slower that", "category": "spelling", "feedback": "« Que » dans une comparaison se dit than, pas that."}, {"contains": "slower of", "category": "grammar", "feedback": "Après un comparatif, on utilise than : slower than me."}], "pool": "lesson", "lessonId": "en.l52", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l52.e08', 'en', 'en.l52', 'en.g37.comparatives_superlatives', array['en.g37.comparatives_superlatives','en.v.big']::text[], 'translation', 'lesson', 'L''appartement est plus grand et plus cher que la maison.', array['The apartment is bigger and more expensive than the house.','The apartment is larger and more expensive than the house.','The flat is bigger and more expensive than the house.','The flat is larger and more expensive than the house.']::text[], 'Big est un adjectif court qui finit par une consonne après une voyelle : on double le g, bigger. Expensive est long : more expensive. Than se place à la fin.', 3, '{"id": "en.l52.e08", "unitIds": ["en.g37.comparatives_superlatives", "en.v.big"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "L''appartement est plus grand et plus cher que la maison.", "promptLanguage": "fr", "answer": "The apartment is bigger and more expensive than the house.", "acceptedAnswers": ["The apartment is bigger and more expensive than the house.", "The apartment is larger and more expensive than the house.", "The flat is bigger and more expensive than the house.", "The flat is larger and more expensive than the house."], "hint": "Big est court (double le g). Expensive est long : more.", "explanation": "Big est un adjectif court qui finit par une consonne après une voyelle : on double le g, bigger. Expensive est long : more expensive. Than se place à la fin.", "tip": "Big devient bigger (g doublé). Mot long : more + adjectif.", "extraExample": {"text": "The hotel is smaller and cheaper than the apartment.", "translation": "L''hôtel est plus petit et moins cher que l''appartement."}, "errorPatterns": [{"contains": "more big", "category": "grammar", "feedback": "Big est un adjectif court : on double le g et on ajoute -er. On dit bigger."}, {"contains": "biger", "category": "spelling", "feedback": "Avec big, on double le g avant -er : bigger."}, {"contains": "bigger that", "category": "spelling", "feedback": "« Que » dans une comparaison se dit than, pas that."}], "pool": "lesson", "lessonId": "en.l52", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l52.e09', 'en', 'en.l52', 'en.g37.comparatives_superlatives', array['en.g37.comparatives_superlatives']::text[], 'free_answer', 'lesson', 'Anna est la meilleure étudiante.', array['Anna is the best student.']::text[], 'Good est irrégulier : son superlatif est the best. On ne dit pas the most good ni the goodest.', 3, '{"id": "en.l52.e09", "unitIds": ["en.g37.comparatives_superlatives"], "type": "free_answer", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Anna est la meilleure étudiante.", "promptLanguage": "fr", "answer": "Anna is the best student.", "acceptedAnswers": ["Anna is the best student."], "hint": "Good est irrégulier : good, better, ...", "explanation": "Good est irrégulier : son superlatif est the best. On ne dit pas the most good ni the goodest.", "tip": "good, better, the best : à apprendre par cœur.", "extraExample": {"text": "Tom is the best cook.", "translation": "Tom est le meilleur cuisinier."}, "errorPatterns": [{"contains": "most good", "category": "grammar", "feedback": "Good est irrégulier : « le meilleur » se dit the best."}, {"contains": "goodest", "category": "grammar", "feedback": "Good est irrégulier : « le meilleur » se dit the best."}, {"contains": "the better", "category": "grammar", "feedback": "Better veut dire « meilleur que » et s''utilise avec than. Pour « la meilleure », on dit the best."}], "pool": "lesson", "lessonId": "en.l52", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l52.e10', 'en', 'en.l52', 'en.g37.comparatives_superlatives', array['en.g37.comparatives_superlatives']::text[], 'free_answer', 'lesson', 'Le temps est pire aujourd''hui qu''hier.', array['The weather is worse today than yesterday.','The weather is worse today than it was yesterday.','Today the weather is worse than yesterday.','Today the weather is worse than it was yesterday.']::text[], 'Bad est irrégulier : son comparatif est worse. On compare avec than : worse today than yesterday.', 3, '{"id": "en.l52.e10", "unitIds": ["en.g37.comparatives_superlatives"], "type": "free_answer", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Le temps est pire aujourd''hui qu''hier.", "promptLanguage": "fr", "answer": "The weather is worse today than yesterday.", "acceptedAnswers": ["The weather is worse today than yesterday.", "The weather is worse today than it was yesterday.", "Today the weather is worse than yesterday.", "Today the weather is worse than it was yesterday."], "hint": "Bad est irrégulier : bad, worse, ...", "explanation": "Bad est irrégulier : son comparatif est worse. On compare avec than : worse today than yesterday.", "tip": "bad, worse, the worst : on ne dit pas more bad.", "extraExample": {"text": "The weather is worse in winter than in summer.", "translation": "Le temps est pire en hiver qu''en été."}, "errorPatterns": [{"contains": "more bad", "category": "grammar", "feedback": "Bad est irrégulier : « pire » se dit worse."}, {"contains": "badder", "category": "grammar", "feedback": "Bad est irrégulier : « pire » se dit worse."}, {"contains": "worse that", "category": "spelling", "feedback": "« Que » dans une comparaison se dit than, pas that."}], "pool": "lesson", "lessonId": "en.l52", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l53.e01', 'en', 'en.l53', 'en.g38.should_could', array['en.g38.should_could','en.v.rest']::text[], 'mcq', 'lesson', 'Comment dit-on « Tu devrais te reposer. » en anglais ?', array['You should rest.']::text[], 'Should sert à donner un conseil (« tu devrais »). Il est suivi du verbe de base, sans to et sans -s : You should rest.', 1, '{"id": "en.l53.e01", "unitIds": ["en.g38.should_could", "en.v.rest"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Tu devrais te reposer. » en anglais ?", "promptLanguage": "fr", "options": ["You should rest.", "You should to rest.", "You should rests.", "You shoulds rest."], "answer": "You should rest.", "acceptedAnswers": ["You should rest."], "hint": "Après should, le verbe reste tout seul.", "explanation": "Should sert à donner un conseil (« tu devrais »). Il est suivi du verbe de base, sans to et sans -s : You should rest.", "tip": "Should + verbe de base : jamais de to, jamais de -s.", "extraExample": {"text": "You should sleep.", "translation": "Tu devrais dormir."}, "errorPatterns": [{"equals": "you should to rest", "category": "grammar", "feedback": "Après should, on ne met pas to : You should rest."}, {"equals": "you should rests", "category": "conjugation", "feedback": "Après should, le verbe reste à la forme de base : rest, sans -s."}, {"equals": "you shoulds rest", "category": "conjugation", "feedback": "Should ne prend jamais de -s, même avec he, she ou it."}], "pool": "lesson", "lessonId": "en.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l53.e02', 'en', 'en.l53', 'en.g38.should_could', array['en.g38.should_could','en.v.ill','en.v.medicine','en.v.advice','en.v.rest','en.v.exercise']::text[], 'match', 'lesson', 'Les mots de la santé : ill, medicine, advice, rest, exercise', '{}'::text[], 'Ces mots servent souvent à donner un conseil avec should : You should rest, You should take your medicine. Advice est un mot indénombrable : on ne dit pas an advice ni advices.', 1, '{"id": "en.l53.e02", "unitIds": ["en.g38.should_could", "en.v.ill", "en.v.medicine", "en.v.advice", "en.v.rest", "en.v.exercise"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot anglais à sa traduction.", "prompt": "Les mots de la santé : ill, medicine, advice, rest, exercise", "promptLanguage": "fr", "pairs": [{"left": "ill", "right": "malade"}, {"left": "medicine", "right": "un médicament"}, {"left": "advice", "right": "un conseil, des conseils"}, {"left": "rest", "right": "se reposer"}, {"left": "exercise", "right": "faire de l''exercice"}], "answer": "ill = malade ; medicine = un médicament ; advice = un conseil, des conseils ; rest = se reposer ; exercise = faire de l''exercice", "acceptedAnswers": [], "explanation": "Ces mots servent souvent à donner un conseil avec should : You should rest, You should take your medicine. Advice est un mot indénombrable : on ne dit pas an advice ni advices.", "tip": "Advice ne prend ni a, ni an, ni -s : some advice.", "pool": "lesson", "lessonId": "en.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l53.e03', 'en', 'en.l53', 'en.g38.should_could', array['en.g38.should_could']::text[], 'mcq', 'lesson', 'She is tired, so she ___ go to bed early.', array['should']::text[], 'Should est un verbe qui ne change jamais. On le place après le sujet, puis on met le verbe de base : she should go.', 2, '{"id": "en.l53.e03", "unitIds": ["en.g38.should_could"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme.", "prompt": "She is tired, so she ___ go to bed early.", "promptLanguage": "en", "options": ["should", "should to", "shoulds", "is should"], "answer": "should", "acceptedAnswers": ["should"], "hint": "Should se place juste après le sujet, sans rien ajouter.", "explanation": "Should est un verbe qui ne change jamais. On le place après le sujet, puis on met le verbe de base : she should go.", "tip": "She should go, he should go : should ne change jamais.", "extraExample": {"text": "He should eat breakfast.", "translation": "Il devrait prendre son petit-déjeuner."}, "errorPatterns": [{"equals": "should to", "category": "grammar", "feedback": "Après should, on ne met pas to : she should go."}, {"equals": "shoulds", "category": "conjugation", "feedback": "Should ne prend jamais de -s, même avec she."}, {"equals": "is should", "category": "grammar", "feedback": "Should se suffit à lui-même : on n''ajoute pas be. On dit she should go."}], "pool": "lesson", "lessonId": "en.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l53.e04', 'en', 'en.l53', 'en.g38.should_could', array['en.g38.should_could','en.v.medicine']::text[], 'fill_blank', 'lesson', 'You are ill. You should take your ___. (médicament)', array['medicine']::text[], 'Medicine veut dire « médicament ». Le conseil est donné avec should : you should take your medicine.', 2, '{"id": "en.l53.e04", "unitIds": ["en.g38.should_could", "en.v.medicine"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le mot qui correspond à la traduction.", "prompt": "You are ill. You should take your ___. (médicament)", "promptLanguage": "en", "options": ["medicine", "advice", "doctor"], "answer": "medicine", "acceptedAnswers": ["medicine"], "hint": "On le prend quand on est malade.", "explanation": "Medicine veut dire « médicament ». Le conseil est donné avec should : you should take your medicine.", "tip": "Médicament = medicine. Médecin = doctor.", "extraExample": {"text": "My mother should take her medicine.", "translation": "Ma mère devrait prendre son médicament."}, "errorPatterns": [{"equals": "doctor", "category": "word_confusion", "feedback": "Doctor veut dire « médecin ». Le médicament se dit medicine."}, {"equals": "advice", "category": "vocabulary", "feedback": "Advice veut dire « conseil ». Le médicament se dit medicine."}], "pool": "lesson", "lessonId": "en.l53", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l53.e05', 'en', 'en.l53', 'en.g38.should_could', array['en.g38.should_could']::text[], 'fill_blank', 'lesson', 'We ___ go to the beach tomorrow. (on pourrait)', array['could']::text[], 'Could exprime une possibilité ou une idée : « on pourrait ». Should donnerait un conseil (« on devrait ») et must une obligation.', 2, '{"id": "en.l53.e05", "unitIds": ["en.g38.should_could"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le mot qui correspond à la traduction.", "prompt": "We ___ go to the beach tomorrow. (on pourrait)", "promptLanguage": "en", "options": ["could", "should", "must"], "answer": "could", "acceptedAnswers": ["could"], "hint": "Il s''agit d''une possibilité, pas d''un devoir.", "explanation": "Could exprime une possibilité ou une idée : « on pourrait ». Should donnerait un conseil (« on devrait ») et must une obligation.", "tip": "Could = on pourrait (une idée). Should = on devrait (un conseil).", "extraExample": {"text": "We could watch TV tonight.", "translation": "On pourrait regarder la télé ce soir."}, "errorPatterns": [{"equals": "should", "category": "word_confusion", "feedback": "Should veut dire « devrait » (un conseil). Pour une possibilité, « on pourrait », on dit could."}, {"equals": "must", "category": "word_confusion", "feedback": "Must veut dire « doit » (obligation). Pour une possibilité, « on pourrait », on dit could."}, {"equals": "can", "category": "word_confusion", "feedback": "Can veut dire « peut ». Pour proposer une idée, « on pourrait », on dit could."}], "pool": "lesson", "lessonId": "en.l53", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l53.e06', 'en', 'en.l53', 'en.g38.should_could', array['en.g38.should_could','en.v.exercise']::text[], 'reorder', 'lesson', 'Tu devrais faire de l''exercice tous les jours.', array['You should exercise every day','Every day you should exercise']::text[], 'Après should, on met le verbe de base : exercise. Every day peut se placer à la fin ou au début de la phrase.', 2, '{"id": "en.l53.e06", "unitIds": ["en.g38.should_could", "en.v.exercise"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Tu devrais faire de l''exercice tous les jours.", "promptLanguage": "fr", "tokens": ["every", "You", "exercise", "day", "should"], "answer": "You should exercise every day", "acceptedAnswers": ["You should exercise every day", "Every day you should exercise"], "hint": "Commence par You should, puis le verbe.", "explanation": "Après should, on met le verbe de base : exercise. Every day peut se placer à la fin ou au début de la phrase.", "tip": "Exercise est lui-même un verbe : You should exercise, sans rien ajouter.", "extraExample": {"text": "He should exercise on Sunday.", "translation": "Il devrait faire de l''exercice dimanche."}, "pool": "lesson", "lessonId": "en.l53", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l53.e07', 'en', 'en.l53', 'en.g38.should_could', array['en.g38.should_could','en.v.ill','en.v.rest']::text[], 'translation', 'lesson', 'Elle est malade, elle devrait se reposer.', array['She is ill, so she should rest.','She is ill, she should rest.','She is ill and she should rest.']::text[], 'Ill veut dire « malade ». Should donne le conseil et reste identique avec she. Rest veut dire ici « se reposer », sans pronom.', 2, '{"id": "en.l53.e07", "unitIds": ["en.g38.should_could", "en.v.ill", "en.v.rest"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Elle est malade, elle devrait se reposer.", "promptLanguage": "fr", "answer": "She is ill, so she should rest.", "acceptedAnswers": ["She is ill, so she should rest.", "She is ill, she should rest.", "She is ill and she should rest."], "hint": "Devrait se dit should, suivi du verbe de base.", "explanation": "Ill veut dire « malade ». Should donne le conseil et reste identique avec she. Rest veut dire ici « se reposer », sans pronom.", "tip": "Se reposer = rest, tout simplement. Pas de pronom réfléchi.", "extraExample": {"text": "My father is ill, so he should stay at home.", "translation": "Mon père est malade, donc il devrait rester à la maison."}, "errorPatterns": [{"contains": "should to", "category": "grammar", "feedback": "Après should, on ne met pas to : she should rest."}, {"contains": "shoulds", "category": "conjugation", "feedback": "Should ne prend jamais de -s, même avec she."}, {"contains": "rest herself", "category": "vocabulary", "feedback": "En anglais, « se reposer » se dit rest, sans herself."}], "pool": "lesson", "lessonId": "en.l53", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l53.e08', 'en', 'en.l53', 'en.g38.should_could', array['en.g38.should_could','en.v.advice']::text[], 'translation', 'lesson', 'Mon docteur me donne un conseil.', array['My doctor gives me some advice.','My doctor gives me advice.','My doctor gives me a piece of advice.','My doctor is giving me some advice.','My doctor is giving me advice.','My doctor is giving me a piece of advice.']::text[], 'Advice est un mot indénombrable : il n''a pas de pluriel et on ne dit pas an advice. Pour « un conseil », on dit some advice ou a piece of advice.', 3, '{"id": "en.l53.e08", "unitIds": ["en.g38.should_could", "en.v.advice"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Mon docteur me donne un conseil.", "promptLanguage": "fr", "answer": "My doctor gives me some advice.", "acceptedAnswers": ["My doctor gives me some advice.", "My doctor gives me advice.", "My doctor gives me a piece of advice.", "My doctor is giving me some advice.", "My doctor is giving me advice.", "My doctor is giving me a piece of advice."], "hint": "Advice est indénombrable : on utilise some, pas a ni an.", "explanation": "Advice est un mot indénombrable : il n''a pas de pluriel et on ne dit pas an advice. Pour « un conseil », on dit some advice ou a piece of advice.", "tip": "Un conseil = some advice ou a piece of advice, jamais an advice.", "extraExample": {"text": "I need some advice.", "translation": "J''ai besoin d''un conseil."}, "errorPatterns": [{"contains": "an advice", "category": "grammar", "feedback": "Advice est indénombrable : pas de an. On dit some advice ou a piece of advice."}, {"contains": "advices", "category": "grammar", "feedback": "Advice n''a pas de pluriel. On dit some advice."}, {"contains": "give me", "category": "conjugation", "feedback": "Avec my doctor (3e personne), le verbe prend un -s : gives."}], "pool": "lesson", "lessonId": "en.l53", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l53.e09', 'en', 'en.l53', 'en.g38.should_could', array['en.g38.should_could']::text[], 'free_answer', 'lesson', 'Nous pourrions manger à la maison ce soir.', array['We could eat at home tonight.','We could eat home tonight.','We could eat at home this evening.','We could eat home this evening.','We could have dinner at home tonight.','We could have dinner home tonight.','We could have dinner at home this evening.','We could have dinner home this evening.']::text[], 'Could exprime une possibilité, une idée : « nous pourrions ». Il est suivi du verbe de base, sans to : we could eat.', 3, '{"id": "en.l53.e09", "unitIds": ["en.g38.should_could"], "type": "free_answer", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Nous pourrions manger à la maison ce soir.", "promptLanguage": "fr", "answer": "We could eat at home tonight.", "acceptedAnswers": ["We could eat at home tonight.", "We could eat home tonight.", "We could eat at home this evening.", "We could eat home this evening.", "We could have dinner at home tonight.", "We could have dinner home tonight.", "We could have dinner at home this evening.", "We could have dinner home this evening."], "hint": "Pourrions se dit could, suivi du verbe de base.", "explanation": "Could exprime une possibilité, une idée : « nous pourrions ». Il est suivi du verbe de base, sans to : we could eat.", "tip": "Could + verbe de base, comme can : we could eat, he could come.", "extraExample": {"text": "He could come on Sunday.", "translation": "Il pourrait venir dimanche."}, "errorPatterns": [{"contains": "could to", "category": "grammar", "feedback": "Après could, on ne met pas to : we could eat."}, {"contains": "could eating", "category": "grammar", "feedback": "Après could, le verbe reste à la forme de base : we could eat."}, {"contains": "could eats", "category": "conjugation", "feedback": "Après could, le verbe reste à la forme de base : eat, sans -s."}], "pool": "lesson", "lessonId": "en.l53", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l53.e10', 'en', 'en.l53', 'en.g38.should_could', array['en.g38.should_could','en.v.ill']::text[], 'free_answer', 'lesson', 'Ton ami est malade. Donne-lui un conseil avec should.', array['You should rest.','You should take your medicine.','You should go to the doctor.','You should drink water and sleep.']::text[], 'Pour donner un conseil à un ami, on utilise You should + verbe de base : You should rest, You should take your medicine.', 3, '{"id": "en.l53.e10", "unitIds": ["en.g38.should_could", "en.v.ill"], "type": "free_answer", "difficulty": 3, "instruction": "Écris une phrase en anglais.", "prompt": "Ton ami est malade. Donne-lui un conseil avec should.", "promptLanguage": "fr", "requirements": {"mustInclude": [["should"]], "minWords": 3}, "answer": "You should rest.", "acceptedAnswers": ["You should rest.", "You should take your medicine.", "You should go to the doctor.", "You should drink water and sleep."], "hint": "Commence par You should ...", "explanation": "Pour donner un conseil à un ami, on utilise You should + verbe de base : You should rest, You should take your medicine.", "tip": "You should + verbe : jamais de to après should.", "extraExample": {"text": "You should go to bed early.", "translation": "Tu devrais te coucher tôt."}, "errorPatterns": [{"contains": "should to", "category": "grammar", "feedback": "Après should, on ne met pas to : You should rest."}, {"contains": "shoulds", "category": "conjugation", "feedback": "Should ne prend jamais de -s."}, {"contains": "you should rests", "category": "conjugation", "feedback": "Après should, le verbe reste à la forme de base : rest."}], "pool": "lesson", "lessonId": "en.l53", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l54.e01', 'en', 'en.l54', 'en.g38.should_could', array['en.g38.should_could']::text[], 'mcq', 'lesson', 'Comment dit-on « Pourriez-vous m''aider, s''il vous plaît ? » en anglais ?', array['Could you help me, please?']::text[], 'Pour demander poliment, on utilise Could you + verbe de base ? On place could avant le sujet you, et on ne met ni to ni -ing devant help.', 1, '{"id": "en.l54.e01", "unitIds": ["en.g38.should_could"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Pourriez-vous m''aider, s''il vous plaît ? » en anglais ?", "promptLanguage": "fr", "options": ["Could you help me, please?", "Could you to help me, please?", "Could you helping me, please?", "You could help me, please?"], "answer": "Could you help me, please?", "acceptedAnswers": ["Could you help me, please?"], "hint": "Could se place avant you, et le verbe reste à la forme de base.", "explanation": "Pour demander poliment, on utilise Could you + verbe de base ? On place could avant le sujet you, et on ne met ni to ni -ing devant help.", "tip": "Could you + verbe de base : la demande polie à retenir.", "extraExample": {"text": "Could you open the window, please?", "translation": "Pourriez-vous ouvrir la fenêtre, s''il vous plaît ?"}, "errorPatterns": [{"equals": "could you to help me please", "category": "grammar", "feedback": "Après could, on ne met pas to : Could you help me?"}, {"equals": "could you helping me please", "category": "grammar", "feedback": "Après could, le verbe reste à la forme de base : help, sans -ing."}, {"equals": "you could help me please", "category": "word_order", "feedback": "Pour poser la question, on place could avant you : Could you help me?"}], "pool": "lesson", "lessonId": "en.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l54.e02', 'en', 'en.l54', 'en.g38.should_could', array['en.g38.should_could','en.v.would_like','en.v.glass','en.v.cup','en.v.dessert','en.v.salad']::text[], 'match', 'lesson', 'Au restaurant : I''d like, glass, cup, dessert, salad', '{}'::text[], 'I''d like est la forme courte de I would like : c''est une façon polie de demander quelque chose. On dit a glass of ou a cup of pour « un verre de » ou « une tasse de ».', 1, '{"id": "en.l54.e02", "unitIds": ["en.g38.should_could", "en.v.would_like", "en.v.glass", "en.v.cup", "en.v.dessert", "en.v.salad"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Au restaurant : I''d like, glass, cup, dessert, salad", "promptLanguage": "fr", "pairs": [{"left": "I''d like", "right": "je voudrais"}, {"left": "a glass of water", "right": "un verre d''eau"}, {"left": "a cup of coffee", "right": "une tasse de café"}, {"left": "a dessert", "right": "un dessert"}, {"left": "a salad", "right": "une salade"}], "answer": "I''d like = je voudrais ; a glass of water = un verre d''eau ; a cup of coffee = une tasse de café ; a dessert = un dessert ; a salad = une salade", "acceptedAnswers": [], "explanation": "I''d like est la forme courte de I would like : c''est une façon polie de demander quelque chose. On dit a glass of ou a cup of pour « un verre de » ou « une tasse de ».", "tip": "I''d like = I would like : plus poli que I want.", "pool": "lesson", "lessonId": "en.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l54.e03', 'en', 'en.l54', 'en.g38.should_could', array['en.g38.should_could','en.v.would_like','en.v.cup']::text[], 'mcq', 'lesson', 'Comment dit-on « Voulez-vous une tasse de café ? » en anglais ?', array['Would you like a cup of coffee?']::text[], 'Would you like...? sert à proposer quelque chose poliment. Do you like...? demande ce que la personne aime en général, ce n''est pas une proposition.', 2, '{"id": "en.l54.e03", "unitIds": ["en.g38.should_could", "en.v.would_like", "en.v.cup"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Voulez-vous une tasse de café ? » en anglais ?", "promptLanguage": "fr", "options": ["Would you like a cup of coffee?", "Do you like a cup of coffee?", "Would you to like a cup of coffee?", "Could you like a cup of coffee?"], "answer": "Would you like a cup of coffee?", "acceptedAnswers": ["Would you like a cup of coffee?"], "hint": "Pour proposer poliment, on commence par would.", "explanation": "Would you like...? sert à proposer quelque chose poliment. Do you like...? demande ce que la personne aime en général, ce n''est pas une proposition.", "tip": "Proposer quelque chose : Would you like ... ?", "extraExample": {"text": "Would you like some water?", "translation": "Voulez-vous de l''eau ?"}, "errorPatterns": [{"equals": "do you like a cup of coffee", "category": "word_confusion", "feedback": "Do you like...? demande si on aime en général. Pour proposer, on dit Would you like...?"}, {"equals": "would you to like a cup of coffee", "category": "grammar", "feedback": "Après would, on ne met pas to : Would you like a cup of coffee?"}, {"equals": "could you like a cup of coffee", "category": "word_confusion", "feedback": "Could you sert à demander un service. Pour proposer quelque chose, on dit Would you like...?"}], "pool": "lesson", "lessonId": "en.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l54.e04', 'en', 'en.l54', 'en.g38.should_could', array['en.g38.should_could','en.v.would_like','en.v.glass']::text[], 'fill_blank', 'lesson', 'I''d ___ a glass of water, please. (je voudrais)', array['like']::text[], 'I''d like est la forme courte de I would like. Cette expression est polie et veut dire « je voudrais ». On ne dit pas I''d want.', 2, '{"id": "en.l54.e04", "unitIds": ["en.g38.should_could", "en.v.would_like", "en.v.glass"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le mot qui correspond à la traduction.", "prompt": "I''d ___ a glass of water, please. (je voudrais)", "promptLanguage": "en", "options": ["like", "want", "likes"], "answer": "like", "acceptedAnswers": ["like"], "hint": "I''d est la forme courte de I would.", "explanation": "I''d like est la forme courte de I would like. Cette expression est polie et veut dire « je voudrais ». On ne dit pas I''d want.", "tip": "I''d like : jamais I''d want, jamais I''d likes.", "extraExample": {"text": "I''d like a salad, please.", "translation": "Je voudrais une salade, s''il vous plaît."}, "errorPatterns": [{"equals": "want", "category": "grammar", "feedback": "I''d est I would : il se combine avec like, pas avec want. On dit I''d like."}, {"equals": "likes", "category": "conjugation", "feedback": "Après would, le verbe reste à la forme de base : I''d like, sans -s."}], "pool": "lesson", "lessonId": "en.l54", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = exc