insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l54.e05', 'en', 'en.l54', 'en.g38.should_could', array['en.g38.should_could']::text[], 'fill_blank', 'lesson', 'Could you ___ the window, please? (ouvrir)', array['open']::text[], 'Après could you, on met le verbe de base : open. On n''ajoute ni to ni -s.', 2, '{"id": "en.l54.e05", "unitIds": ["en.g38.should_could"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le mot qui correspond à la traduction.", "prompt": "Could you ___ the window, please? (ouvrir)", "promptLanguage": "en", "options": ["open", "to open", "opens"], "answer": "open", "acceptedAnswers": ["open"], "hint": "Après could you, le verbe est tout seul.", "explanation": "Après could you, on met le verbe de base : open. On n''ajoute ni to ni -s.", "tip": "Could you + verbe de base, sans to.", "extraExample": {"text": "Could you close the door, please?", "translation": "Pourriez-vous fermer la porte, s''il vous plaît ?"}, "errorPatterns": [{"equals": "to open", "category": "grammar", "feedback": "Après could, on ne met pas to : Could you open the window?"}, {"equals": "opens", "category": "conjugation", "feedback": "Après could, le verbe reste à la forme de base : open, sans -s."}], "pool": "lesson", "lessonId": "en.l54", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l54.e06', 'en', 'en.l54', 'en.g38.should_could', array['en.g38.should_could','en.v.salad','en.v.dessert','en.v.would_like']::text[], 'reorder', 'lesson', 'Je voudrais une salade et un dessert, s''il vous plaît.', array['I would like a salad and a dessert please','I would like a dessert and a salad please']::text[], 'I would like (ou I''d like) veut dire « je voudrais » : c''est une demande polie. Ensuite viennent les deux choses demandées, puis please.', 3, '{"id": "en.l54.e06", "unitIds": ["en.g38.should_could", "en.v.salad", "en.v.dessert", "en.v.would_like"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Je voudrais une salade et un dessert, s''il vous plaît.", "promptLanguage": "fr", "tokens": ["please", "I", "like", "salad", "a", "would", "and", "dessert", "a"], "answer": "I would like a salad and a dessert please", "acceptedAnswers": ["I would like a salad and a dessert please", "I would like a dessert and a salad please"], "hint": "I would like se dit pour « je voudrais ». Please vient à la fin.", "explanation": "I would like (ou I''d like) veut dire « je voudrais » : c''est une demande polie. Ensuite viennent les deux choses demandées, puis please.", "tip": "I would like + ce que tu veux + please.", "extraExample": {"text": "I would like a cup of coffee and a cake, please.", "translation": "Je voudrais une tasse de café et un gâteau, s''il vous plaît."}, "pool": "lesson", "lessonId": "en.l54", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l54.e07', 'en', 'en.l54', 'en.g38.should_could', array['en.g38.should_could','en.v.glass']::text[], 'translation', 'lesson', 'Pourriez-vous m''apporter un verre d''eau, s''il vous plaît ?', array['Could you bring me a glass of water, please?','Could you please bring me a glass of water?','Would you bring me a glass of water, please?','Would you please bring me a glass of water?','Can you bring me a glass of water, please?','Can you please bring me a glass of water?','Could you give me a glass of water, please?','Could you please give me a glass of water?','Would you give me a glass of water, please?','Would you please give me a glass of water?','Can you give me a glass of water, please?','Can you please give me a glass of water?','Could you get me a glass of water, please?','Could you please get me a glass of water?','Would you get me a glass of water, please?','Would you please get me a glass of water?','Can you get me a glass of water, please?','Can you please get me a glass of water?']::text[], 'Could you + verbe de base est la façon polie de demander un service. Un verre d''eau se dit a glass of water.', 2, '{"id": "en.l54.e07", "unitIds": ["en.g38.should_could", "en.v.glass"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Pourriez-vous m''apporter un verre d''eau, s''il vous plaît ?", "promptLanguage": "fr", "answer": "Could you bring me a glass of water, please?", "acceptedAnswers": ["Could you bring me a glass of water, please?", "Could you please bring me a glass of water?", "Would you bring me a glass of water, please?", "Would you please bring me a glass of water?", "Can you bring me a glass of water, please?", "Can you please bring me a glass of water?", "Could you give me a glass of water, please?", "Could you please give me a glass of water?", "Would you give me a glass of water, please?", "Would you please give me a glass of water?", "Can you give me a glass of water, please?", "Can you please give me a glass of water?", "Could you get me a glass of water, please?", "Could you please get me a glass of water?", "Would you get me a glass of water, please?", "Would you please get me a glass of water?", "Can you get me a glass of water, please?", "Can you please get me a glass of water?"], "hint": "Pourriez-vous se dit could you, suivi du verbe de base.", "explanation": "Could you + verbe de base est la façon polie de demander un service. Un verre d''eau se dit a glass of water.", "tip": "Could you + verbe + please : une demande polie.", "extraExample": {"text": "Could you bring me the menu, please?", "translation": "Pourriez-vous m''apporter le menu, s''il vous plaît ?"}, "errorPatterns": [{"contains": "could you to", "category": "grammar", "feedback": "Après could you, on ne met pas to : Could you bring me ...?"}, {"contains": "could you brings", "category": "conjugation", "feedback": "Après could, le verbe reste à la forme de base : bring, sans -s."}, {"contains": "water glass", "category": "word_order", "feedback": "« Un verre d''eau » se dit a glass of water."}], "pool": "lesson", "lessonId": "en.l54", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l54.e08', 'en', 'en.l54', 'en.g38.should_could', array['en.g38.should_could','en.v.would_like','en.v.dessert']::text[], 'translation', 'lesson', 'Je voudrais un dessert, s''il vous plaît.', array['I''d like a dessert, please.','I would like a dessert, please.','I''d like to have a dessert, please.','Could I have a dessert, please?','Can I have a dessert, please?','May I have a dessert, please?']::text[], 'Pour demander poliment, on dit I''d like (I would like), qui veut dire « je voudrais ». I want est trop direct pour parler à un serveur.', 3, '{"id": "en.l54.e08", "unitIds": ["en.g38.should_could", "en.v.would_like", "en.v.dessert"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Je voudrais un dessert, s''il vous plaît.", "promptLanguage": "fr", "answer": "I''d like a dessert, please.", "acceptedAnswers": ["I''d like a dessert, please.", "I would like a dessert, please.", "I''d like to have a dessert, please.", "Could I have a dessert, please?", "Can I have a dessert, please?", "May I have a dessert, please?"], "hint": "Utilise une forme polie de want.", "explanation": "Pour demander poliment, on dit I''d like (I would like), qui veut dire « je voudrais ». I want est trop direct pour parler à un serveur.", "tip": "Poli : I''d like. Trop direct : I want.", "extraExample": {"text": "I''d like a cup of coffee, please.", "translation": "Je voudrais une tasse de café, s''il vous plaît."}, "errorPatterns": [{"contains": "i want", "category": "word_confusion", "feedback": "I want veut dire « je veux » et sonne trop direct. Pour « je voudrais », dis I''d like."}, {"contains": "i like a", "category": "word_confusion", "feedback": "I like veut dire « j''aime ». Pour « je voudrais », il faut I''d like (I would like)."}, {"contains": "would to like", "category": "grammar", "feedback": "Après would, on ne met pas to : I would like a dessert."}], "pool": "lesson", "lessonId": "en.l54", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l54.e09', 'en', 'en.l54', 'en.g38.should_could', array['en.g38.should_could','en.v.salad','en.v.dessert']::text[], 'free_answer', 'lesson', 'Voulez-vous une salade ou un dessert ?', array['Would you like a salad or a dessert?','Would you like a salad or dessert?','Would you like salad or dessert?']::text[], 'Would you like...? est la façon polie de proposer quelque chose. Or relie les deux choix : un salad ou un dessert.', 3, '{"id": "en.l54.e09", "unitIds": ["en.g38.should_could", "en.v.salad", "en.v.dessert"], "type": "free_answer", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Voulez-vous une salade ou un dessert ?", "promptLanguage": "fr", "answer": "Would you like a salad or a dessert?", "acceptedAnswers": ["Would you like a salad or a dessert?", "Would you like a salad or dessert?", "Would you like salad or dessert?"], "hint": "Pour proposer poliment, on commence par would you like.", "explanation": "Would you like...? est la façon polie de proposer quelque chose. Or relie les deux choix : un salad ou un dessert.", "tip": "Would you like ... ? pour proposer, or pour le choix.", "extraExample": {"text": "Would you like milk or water?", "translation": "Voulez-vous du lait ou de l''eau ?"}, "errorPatterns": [{"contains": "do you like", "category": "word_confusion", "feedback": "Do you like...? demande si on aime en général. Pour proposer, on dit Would you like...?"}, {"contains": "would you to like", "category": "grammar", "feedback": "Après would, on ne met pas to : Would you like a salad?"}, {"contains": "salad and", "category": "vocabulary", "feedback": "And veut dire « et ». Pour proposer un choix entre deux plats, on dit or."}], "pool": "lesson", "lessonId": "en.l54", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l54.e10', 'en', 'en.l54', 'en.g38.should_could', array['en.g38.should_could','en.v.would_like','en.v.cup']::text[], 'free_answer', 'lesson', 'Tu es au restaurant. Demande poliment quelque chose à boire (une tasse de café, un verre d''eau...).', array['I''d like a cup of coffee, please.','I would like a glass of water, please.','Could I have a cup of coffee, please?','Could you bring me a glass of water, please?']::text[], 'Pour demander poliment, utilise I''d like + ce que tu veux, ou Could you / Could I + verbe de base. Termine par please.', 3, '{"id": "en.l54.e10", "unitIds": ["en.g38.should_could", "en.v.would_like", "en.v.cup"], "type": "free_answer", "difficulty": 3, "instruction": "Écris une phrase en anglais.", "prompt": "Tu es au restaurant. Demande poliment quelque chose à boire (une tasse de café, un verre d''eau...).", "promptLanguage": "fr", "requirements": {"mustInclude": [["would like", "i''d like", "could you", "could i"]], "minWords": 4}, "answer": "I''d like a cup of coffee, please.", "acceptedAnswers": ["I''d like a cup of coffee, please.", "I would like a glass of water, please.", "Could I have a cup of coffee, please?", "Could you bring me a glass of water, please?"], "hint": "Commence par I''d like ... ou Could I have ...", "explanation": "Pour demander poliment, utilise I''d like + ce que tu veux, ou Could you / Could I + verbe de base. Termine par please.", "tip": "I''d like ... please ou Could you ... please : deux formules polies.", "extraExample": {"text": "Could I have a glass of milk, please?", "translation": "Pourrais-je avoir un verre de lait, s''il vous plaît ?"}, "errorPatterns": [{"contains": "i want", "category": "word_confusion", "feedback": "I want est trop direct. Pour demander poliment, dis I''d like."}, {"contains": "could you to", "category": "grammar", "feedback": "Après could you, on ne met pas to : Could you bring me a cup of coffee?"}, {"contains": "would to like", "category": "grammar", "feedback": "Après would, on ne met pas to : I would like a cup of coffee."}], "pool": "lesson", "lessonId": "en.l54", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l55.e01', 'en', 'en.l55', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.film','en.v.ever']::text[], 'mcq', 'lesson', 'Comment demander « As-tu déjà vu ce film ? » en anglais ?', array['Have you ever seen this film?']::text[], 'Pour demander si quelqu''un a déjà vécu quelque chose, on dit Have you ever + participe passé. Le participe passé de see est seen : saw est le past simple.', 2, '{"id": "en.l55.e01", "unitIds": ["en.g39.present_perfect_intro", "en.v.film", "en.v.ever"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne question.", "prompt": "Comment demander « As-tu déjà vu ce film ? » en anglais ?", "promptLanguage": "fr", "options": ["Have you ever seen this film?", "Have you ever saw this film?", "Did you ever seen this film?", "Have you ever see this film?"], "answer": "Have you ever seen this film?", "acceptedAnswers": ["Have you ever seen this film?"], "hint": "Pour demander une expérience de vie, on utilise have + participe passé.", "explanation": "Pour demander si quelqu''un a déjà vécu quelque chose, on dit Have you ever + participe passé. Le participe passé de see est seen : saw est le past simple.", "tip": "Have you ever + participe passé : « As-tu déjà… ? »", "extraExample": {"text": "Have you ever eaten fish for breakfast?", "translation": "As-tu déjà mangé du poisson au petit déjeuner ?"}, "errorPatterns": [{"equals": "have you ever saw this film", "category": "conjugation", "feedback": "Saw est le past simple. Après have, il faut le participe passé : seen."}, {"equals": "did you ever seen this film", "category": "grammar", "feedback": "Did se construit avec la forme de base, pas avec seen. Pour une expérience de vie, on dit Have you ever seen… ?"}, {"equals": "have you ever see this film", "category": "conjugation", "feedback": "Après have, le verbe ne reste pas à la forme de base : il faut le participe passé seen."}], "pool": "lesson", "lessonId": "en.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l55.e02', 'en', 'en.l55', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.try']::text[], 'match', 'lesson', 'Les participes passés à utiliser après have / has', '{}'::text[], 'Ces cinq mots sont des participes passés : on les utilise après have / has. Seen, eaten, done et gone sont irréguliers (à apprendre) ; tried est régulier (try devient tried).', 2, '{"id": "en.l55.e02", "unitIds": ["en.g39.present_perfect_intro", "en.v.try"], "type": "match", "difficulty": 2, "instruction": "Associe chaque participe passé à sa traduction.", "prompt": "Les participes passés à utiliser après have / has", "promptLanguage": "fr", "pairs": [{"left": "seen", "right": "vu"}, {"left": "eaten", "right": "mangé"}, {"left": "done", "right": "fait"}, {"left": "tried", "right": "essayé / goûté"}, {"left": "gone", "right": "parti"}], "answer": "seen = vu ; eaten = mangé ; done = fait ; tried = essayé / goûté ; gone = parti", "acceptedAnswers": [], "explanation": "Ces cinq mots sont des participes passés : on les utilise après have / has. Seen, eaten, done et gone sont irréguliers (à apprendre) ; tried est régulier (try devient tried).", "tip": "Avec have / has, on utilise le participe passé : have seen, has eaten, have done.", "extraExample": {"text": "I have done my homework.", "translation": "J''ai fait mes devoirs."}, "pool": "lesson", "lessonId": "en.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l55.e03', 'en', 'en.l55', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.abroad']::text[], 'mcq', 'lesson', 'Where is Tom? — He has ___ abroad. He is in Spain now.', array['gone']::text[], 'Tom est parti à l''étranger et il y est encore : on dit has gone. Been signifie qu''on y est allé et qu''on en est revenu.', 3, '{"id": "en.l55.e03", "unitIds": ["en.g39.present_perfect_intro", "en.v.abroad"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le mot qui convient.", "prompt": "Where is Tom? — He has ___ abroad. He is in Spain now.", "promptLanguage": "en", "options": ["gone", "been", "went", "go"], "answer": "gone", "acceptedAnswers": ["gone"], "hint": "Tom est parti et il n''est pas encore revenu.", "explanation": "Tom est parti à l''étranger et il y est encore : on dit has gone. Been signifie qu''on y est allé et qu''on en est revenu.", "tip": "Gone = parti (et toujours là-bas) ; been = allé et revenu.", "extraExample": {"text": "My parents have gone to London.", "translation": "Mes parents sont partis à Londres."}, "errorPatterns": [{"equals": "been", "category": "word_confusion", "feedback": "Has been abroad voudrait dire qu''il est revenu. Tom est encore en Espagne : on dit has gone."}, {"equals": "went", "category": "conjugation", "feedback": "Went est le past simple. Après has, il faut le participe passé : gone."}, {"equals": "go", "category": "conjugation", "feedback": "Après has, le verbe ne reste pas à la forme de base : il faut le participe passé gone."}], "pool": "lesson", "lessonId": "en.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l55.e04', 'en', 'en.l55', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro']::text[], 'fill_blank', 'lesson', 'She has never ___ fish. (eat)', array['eaten']::text[], 'Après has never, on utilise le participe passé. Celui de eat est eaten : eat – ate – eaten.', 2, '{"id": "en.l55.e04", "unitIds": ["en.g39.present_perfect_intro"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le participe passé du verbe entre parenthèses.", "prompt": "She has never ___ fish. (eat)", "promptLanguage": "en", "options": ["eaten", "ate", "eat", "eated"], "answer": "eaten", "acceptedAnswers": ["eaten"], "hint": "Eat est irrégulier : eat – ate – eaten.", "explanation": "Après has never, on utilise le participe passé. Celui de eat est eaten : eat – ate – eaten.", "tip": "Eat, eaten : comme seen, taken, given, le participe passé finit souvent en -en.", "extraExample": {"text": "Tom has never eaten meat.", "translation": "Tom n''a jamais mangé de viande."}, "errorPatterns": [{"equals": "ate", "category": "conjugation", "feedback": "Ate est le past simple. Après has, il faut le participe passé : eaten."}, {"equals": "eat", "category": "conjugation", "feedback": "Après has, le verbe ne reste pas à la forme de base : il faut le participe passé eaten."}, {"equals": "eated", "category": "spelling", "feedback": "Eat est irrégulier : on n''ajoute pas -ed. Le participe passé est eaten."}], "pool": "lesson", "lessonId": "en.l55", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l55.e05', 'en', 'en.l55', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.museum']::text[], 'fill_blank', 'lesson', 'I''m home! I have ___ to the museum with Anna.', array['been']::text[], 'Je suis déjà à la maison : je suis allé au musée et j''en suis revenu. On dit donc have been to. Gone voudrait dire que je suis encore là-bas.', 3, '{"id": "en.l55.e05", "unitIds": ["en.g39.present_perfect_intro", "en.v.museum"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "I''m home! I have ___ to the museum with Anna.", "promptLanguage": "en", "options": ["been", "gone", "went", "go"], "answer": "been", "acceptedAnswers": ["been"], "hint": "Je suis rentré à la maison : je suis allé au musée et je suis revenu.", "explanation": "Je suis déjà à la maison : je suis allé au musée et j''en suis revenu. On dit donc have been to. Gone voudrait dire que je suis encore là-bas.", "tip": "Been to = je suis allé là-bas et je suis de retour.", "extraExample": {"text": "Have you been to the new shop?", "translation": "Es-tu allé au nouveau magasin ?"}, "errorPatterns": [{"equals": "gone", "category": "word_confusion", "feedback": "Have gone voudrait dire que tu es encore au musée. Tu es à la maison : on dit have been."}, {"equals": "went", "category": "conjugation", "feedback": "Went est le past simple. Après have, il faut le participe passé : been."}, {"equals": "go", "category": "conjugation", "feedback": "Après have, il faut un participe passé, pas la forme de base."}], "pool": "lesson", "lessonId": "en.l55", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l55.e06', 'en', 'en.l55', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.abroad','en.v.ever']::text[], 'translation', 'lesson', 'Est-ce que Tom a déjà voyagé à l''étranger ?', array['Has Tom ever travelled abroad?','Has Tom ever traveled abroad?','Has Tom ever been abroad?','Has Tom ever gone abroad?','Has Tom travelled abroad before?','Has Tom traveled abroad before?','Has Tom been abroad before?','Has Tom ever been to another country?','Has Tom already travelled abroad?','Has Tom already traveled abroad?','Has Tom already been abroad?']::text[], 'On demande une expérience de vie, sans date : present perfect. Avec Tom (il), on utilise has, et ever se place entre Tom et le participe passé : Has Tom ever travelled abroad ?', 3, '{"id": "en.l55.e06", "unitIds": ["en.g39.present_perfect_intro", "en.v.abroad", "en.v.ever"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Est-ce que Tom a déjà voyagé à l''étranger ?", "promptLanguage": "fr", "answer": "Has Tom ever travelled abroad?", "acceptedAnswers": ["Has Tom ever travelled abroad?", "Has Tom ever traveled abroad?", "Has Tom ever been abroad?", "Has Tom ever gone abroad?", "Has Tom travelled abroad before?", "Has Tom traveled abroad before?", "Has Tom been abroad before?", "Has Tom ever been to another country?", "Has Tom already travelled abroad?", "Has Tom already traveled abroad?", "Has Tom already been abroad?"], "hint": "Pour parler d''une expérience de vie, utilise Has + sujet + ever + participe passé.", "explanation": "On demande une expérience de vie, sans date : present perfect. Avec Tom (il), on utilise has, et ever se place entre Tom et le participe passé : Has Tom ever travelled abroad ?", "tip": "Question d''expérience : Have / Has + sujet + ever + participe passé.", "extraExample": {"text": "Has Anna ever lived abroad?", "translation": "Anna a-t-elle déjà vécu à l''étranger ?"}, "errorPatterns": [{"contains": "have tom", "category": "grammar", "feedback": "Avec Tom (il), on utilise has, pas have."}, {"contains": "did tom ever", "category": "verb_tense", "feedback": "Pour une expérience de vie jusqu''à maintenant, on utilise Has Tom ever + participe passé. Did Tom ever… parle plutôt d''une période du passé qui est terminée."}, {"contains": "travel abroad", "category": "conjugation", "feedback": "Après has, il faut le participe passé : travelled (ou traveled), pas la forme de base."}], "pool": "lesson", "lessonId": "en.l55", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l55.e07', 'en', 'en.l55', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.museum','en.v.ever']::text[], 'reorder', 'lesson', 'As-tu déjà été dans un musée à Londres ?', array['Have you ever been to a museum in London']::text[], 'Une question au present perfect s''ouvre sur Have + sujet. Ever se place juste avant le participe passé been, puis to a museum in London.', 3, '{"id": "en.l55.e07", "unitIds": ["en.g39.present_perfect_intro", "en.v.museum", "en.v.ever"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "As-tu déjà été dans un musée à Londres ?", "promptLanguage": "fr", "tokens": ["museum", "Have", "London", "been", "a", "you", "in", "ever", "to"], "answer": "Have you ever been to a museum in London", "acceptedAnswers": ["Have you ever been to a museum in London"], "hint": "La question commence par Have, puis le sujet, puis ever.", "explanation": "Une question au present perfect s''ouvre sur Have + sujet. Ever se place juste avant le participe passé been, puis to a museum in London.", "tip": "Ordre d''une question d''expérience : Have + sujet + ever + participe passé.", "extraExample": {"text": "Have you ever been to a beach in winter?", "translation": "As-tu déjà été à la plage en hiver ?"}, "pool": "lesson", "lessonId": "en.l55", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l55.e08', 'en', 'en.l55', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.try']::text[], 'translation', 'lesson', 'Anna n''a jamais goûté le gâteau de Tom.', array['Anna has never tried Tom''s cake.','Anna has never tasted Tom''s cake.','Anna has never eaten Tom''s cake.','Anna has never tried the cake of Tom.','Anna hasn''t tried Tom''s cake.']::text[], 'Pour dire « jamais » avec le present perfect, on met never entre has et le participe passé. Le participe passé de try est tried (régulier).', 4, '{"id": "en.l55.e08", "unitIds": ["en.g39.present_perfect_intro", "en.v.try"], "type": "translation", "difficulty": 4, "instruction": "Traduis en anglais.", "prompt": "Anna n''a jamais goûté le gâteau de Tom.", "promptLanguage": "fr", "answer": "Anna has never tried Tom''s cake.", "acceptedAnswers": ["Anna has never tried Tom''s cake.", "Anna has never tasted Tom''s cake.", "Anna has never eaten Tom''s cake.", "Anna has never tried the cake of Tom.", "Anna hasn''t tried Tom''s cake."], "hint": "Never se place entre has et le participe passé.", "explanation": "Pour dire « jamais » avec le present perfect, on met never entre has et le participe passé. Le participe passé de try est tried (régulier).", "tip": "Has + never + participe passé : on n''ajoute pas de seconde négation.", "extraExample": {"text": "I have never tried French cheese.", "translation": "Je n''ai jamais goûté de fromage français."}, "errorPatterns": [{"contains": "never try tom''s", "category": "conjugation", "feedback": "Après has, il faut le participe passé : tried, pas try."}, {"contains": "never tryed", "category": "spelling", "feedback": "Try devient tried (le y se change en ied) : tried."}, {"contains": "hasn''t never", "category": "grammar", "feedback": "En anglais, on ne met pas deux négations. Avec never, la phrase reste affirmative : has never tried."}], "pool": "lesson", "lessonId": "en.l55", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l55.e09', 'en', 'en.l55', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.film']::text[], 'free_answer', 'lesson', 'Comment dit-on « Je n''ai jamais vu ce film » en anglais ?', array['I have never seen this film.','I have never seen that film.','I have never seen this movie.','I have never seen that movie.','I haven''t seen this film.','I haven''t seen that film.','I haven''t ever seen this film.','I have never watched this film.','I have never watched that film.']::text[], 'Pour dire qu''on n''a jamais vécu quelque chose, on utilise have never + participe passé. Le participe passé de see est seen, pas saw.', 4, '{"id": "en.l55.e09", "unitIds": ["en.g39.present_perfect_intro", "en.v.film"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Je n''ai jamais vu ce film » en anglais ?", "promptLanguage": "fr", "answer": "I have never seen this film.", "acceptedAnswers": ["I have never seen this film.", "I have never seen that film.", "I have never seen this movie.", "I have never seen that movie.", "I haven''t seen this film.", "I haven''t seen that film.", "I haven''t ever seen this film.", "I have never watched this film.", "I have never watched that film."], "hint": "Never se place entre have et le participe passé.", "explanation": "Pour dire qu''on n''a jamais vécu quelque chose, on utilise have never + participe passé. Le participe passé de see est seen, pas saw.", "tip": "Jamais + expérience = have never + participe passé.", "extraExample": {"text": "She has never seen the sea.", "translation": "Elle n''a jamais vu la mer."}, "errorPatterns": [{"contains": "never saw", "category": "conjugation", "feedback": "Saw est le past simple. Pour une expérience de vie, il faut le participe passé : have never seen."}, {"contains": "never see this", "category": "conjugation", "feedback": "Après have, il faut le participe passé : seen, pas see."}, {"contains": "i have ever seen", "category": "word_confusion", "feedback": "Ever s''emploie dans les questions. Pour dire « jamais » dans une phrase affirmative, on utilise never."}], "pool": "lesson", "lessonId": "en.l55", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l55.e10', 'en', 'en.l55', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.abroad','en.v.try']::text[], 'free_answer', 'lesson', 'Dis une chose que tu n''as jamais faite (par exemple : un endroit où tu n''es jamais allé, un plat que tu n''as jamais goûté).', array['I have never been abroad.','I have never tried sushi.','My brother has never seen a film in English.','We have never been to a museum in Paris.']::text[], 'Pour parler d''une chose que tu n''as jamais faite, utilise have / has + never + participe passé. Le participe passé doit être le bon : been, tried, eaten, seen…', 5, '{"id": "en.l55.e10", "unitIds": ["en.g39.present_perfect_intro", "en.v.abroad", "en.v.try"], "type": "free_answer", "difficulty": 5, "instruction": "Écris une phrase en anglais, au present perfect, avec never.", "prompt": "Dis une chose que tu n''as jamais faite (par exemple : un endroit où tu n''es jamais allé, un plat que tu n''as jamais goûté).", "promptLanguage": "fr", "requirements": {"mustInclude": [["never"], ["have", "has", "''ve"]], "minWords": 4}, "answer": "I have never been abroad.", "acceptedAnswers": ["I have never been abroad.", "I have never tried sushi.", "My brother has never seen a film in English.", "We have never been to a museum in Paris."], "hint": "Forme : sujet + have / has + never + participe passé.", "explanation": "Pour parler d''une chose que tu n''as jamais faite, utilise have / has + never + participe passé. Le participe passé doit être le bon : been, tried, eaten, seen…", "tip": "Never se place entre have / has et le participe passé.", "extraExample": {"text": "Tom has never driven a car.", "translation": "Tom n''a jamais conduit de voiture."}, "errorPatterns": [{"contains": "never went", "category": "conjugation", "feedback": "Went est le past simple. Pour le present perfect, il faut le participe passé : never been ou never gone."}, {"contains": "have went", "category": "conjugation", "feedback": "Went est le past simple. Après have, il faut le participe passé : gone ou been."}, {"contains": "never saw", "category": "conjugation", "feedback": "Saw est le past simple. Après have / has, il faut le participe passé : seen."}], "pool": "lesson", "lessonId": "en.l55", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l56.e01', 'en', 'en.l56', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.just','en.v.email']::text[], 'mcq', 'lesson', 'Dans « I have just sent the email », que veut dire just ?', array['je viens de']::text[], 'Avec le present perfect, just veut dire « à l''instant » : I have just sent the email = je viens d''envoyer l''e-mail. Il se place entre have et le participe passé.', 2, '{"id": "en.l56.e01", "unitIds": ["en.g39.present_perfect_intro", "en.v.just", "en.v.email"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Dans « I have just sent the email », que veut dire just ?", "promptLanguage": "fr", "options": ["je viens de", "déjà", "pas encore", "jamais"], "answer": "je viens de", "acceptedAnswers": ["je viens de"], "hint": "I have just sent = l''e-mail est parti il y a quelques secondes.", "explanation": "Avec le present perfect, just veut dire « à l''instant » : I have just sent the email = je viens d''envoyer l''e-mail. Il se place entre have et le participe passé.", "tip": "Have / has + just + participe passé = « venir de ».", "extraExample": {"text": "Anna has just called me.", "translation": "Anna vient de m''appeler."}, "errorPatterns": [{"equals": "déjà", "category": "word_confusion", "feedback": "« Déjà » se dit already. Just veut dire « à l''instant » : je viens de."}, {"equals": "pas encore", "category": "word_confusion", "feedback": "« Pas encore » se dit not … yet. Ici, la phrase est affirmative : just = je viens de."}, {"equals": "jamais", "category": "word_confusion", "feedback": "« Jamais » se dit never. Just veut dire « à l''instant » : je viens de."}], "pool": "lesson", "lessonId": "en.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l56.e02', 'en', 'en.l56', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro']::text[], 'mcq', 'lesson', 'Comment dit-on « J''ai vu Anna hier » en anglais ?', array['I saw Anna yesterday.']::text[], 'Yesterday donne un moment précis dans le passé : on utilise le past simple (saw). Le present perfect ne s''emploie pas avec yesterday, last year ou ago.', 3, '{"id": "en.l56.e02", "unitIds": ["en.g39.present_perfect_intro"], "type": "mcq", "difficulty": 3, "instruction": "Quelle phrase est correcte ?", "prompt": "Comment dit-on « J''ai vu Anna hier » en anglais ?", "promptLanguage": "fr", "options": ["I saw Anna yesterday.", "I have seen Anna yesterday.", "I have saw Anna yesterday.", "I seen Anna yesterday."], "answer": "I saw Anna yesterday.", "acceptedAnswers": ["I saw Anna yesterday."], "hint": "Hier est un moment précis du passé.", "explanation": "Yesterday donne un moment précis dans le passé : on utilise le past simple (saw). Le present perfect ne s''emploie pas avec yesterday, last year ou ago.", "tip": "Si tu donnes une date ou un moment précis, utilise le past simple.", "extraExample": {"text": "We visited the museum last year.", "translation": "Nous avons visité le musée l''année dernière."}, "errorPatterns": [{"equals": "i have seen anna yesterday", "category": "verb_tense", "feedback": "Avec yesterday, le present perfect est impossible en anglais, même si le français dit « j''ai vu ». Utilise le past simple : I saw."}, {"equals": "i have saw anna yesterday", "category": "conjugation", "feedback": "Deux erreurs : avec yesterday, on utilise le past simple (I saw), sans have ; et saw n''est pas un participe passé."}, {"equals": "i seen anna yesterday", "category": "conjugation", "feedback": "Seen est un participe passé : il s''emploie après have. Au past simple, on dit I saw."}], "pool": "lesson", "lessonId": "en.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l56.e03', 'en', 'en.l56', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.already','en.v.yet','en.v.just']::text[], 'match', 'lesson', 'Just, already et yet avec le present perfect', '{}'::text[], 'Just se place avant le participe passé : « je viens de ». Already veut dire « déjà » dans une phrase affirmative. Yet se met à la fin : il veut dire « pas encore » dans une négation et « déjà ? » dans une question.', 2, '{"id": "en.l56.e03", "unitIds": ["en.g39.present_perfect_intro", "en.v.already", "en.v.yet", "en.v.just"], "type": "match", "difficulty": 2, "instruction": "Associe chaque phrase anglaise à sa traduction.", "prompt": "Just, already et yet avec le present perfect", "promptLanguage": "fr", "pairs": [{"left": "I have just finished.", "right": "Je viens de finir."}, {"left": "I have already finished.", "right": "J''ai déjà fini."}, {"left": "I haven''t finished yet.", "right": "Je n''ai pas encore fini."}, {"left": "Have you finished yet?", "right": "As-tu déjà fini ?"}], "answer": "I have just finished. = Je viens de finir. ; I have already finished. = J''ai déjà fini. ; I haven''t finished yet. = Je n''ai pas encore fini. ; Have you finished yet? = As-tu déjà fini ?", "acceptedAnswers": [], "explanation": "Just se place avant le participe passé : « je viens de ». Already veut dire « déjà » dans une phrase affirmative. Yet se met à la fin : il veut dire « pas encore » dans une négation et « déjà ? » dans une question.", "tip": "Just = je viens de ; already = déjà ; not … yet = pas encore.", "extraExample": {"text": "Tom has already eaten.", "translation": "Tom a déjà mangé."}, "pool": "lesson", "lessonId": "en.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l56.e04', 'en', 'en.l56', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.just','en.v.email']::text[], 'fill_blank', 'lesson', 'Tom has ___ sent the email. (Tom vient d''envoyer l''e-mail.)', array['just']::text[], 'Pour dire qu''une action vient de se terminer, on utilise have / has just + participe passé. Just se place entre has et sent.', 2, '{"id": "en.l56.e04", "unitIds": ["en.g39.present_perfect_intro", "en.v.just", "en.v.email"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le mot qui correspond à la traduction entre parenthèses.", "prompt": "Tom has ___ sent the email. (Tom vient d''envoyer l''e-mail.)", "promptLanguage": "en", "options": ["just", "already", "yet", "ever"], "answer": "just", "acceptedAnswers": ["just"], "hint": "« Venir de » se dit avec le mot just.", "explanation": "Pour dire qu''une action vient de se terminer, on utilise have / has just + participe passé. Just se place entre has et sent.", "tip": "« Venir de » = have / has just + participe passé.", "extraExample": {"text": "They have just arrived at the hotel.", "translation": "Ils viennent d''arriver à l''hôtel."}, "errorPatterns": [{"equals": "already", "category": "word_confusion", "feedback": "Already veut dire « déjà ». Pour « vient de », on dit just."}, {"equals": "yet", "category": "word_confusion", "feedback": "Yet s''emploie à la fin d''une question ou d''une négation (pas encore). Pour « vient de », on dit just."}, {"equals": "ever", "category": "word_confusion", "feedback": "Ever s''emploie dans les questions d''expérience (Have you ever…?). Pour « vient de », on dit just."}], "pool": "lesson", "lessonId": "en.l56", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l56.e05', 'en', 'en.l56', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.yet','en.v.report']::text[], 'fill_blank', 'lesson', 'I haven''t written the report ___. (Je n''ai pas encore écrit le rapport.)', array['yet']::text[], 'Pour dire « pas encore », on utilise une phrase négative avec yet à la fin : I haven''t written the report yet. Already s''emploie plutôt dans les phrases affirmatives.', 3, '{"id": "en.l56.e05", "unitIds": ["en.g39.present_perfect_intro", "en.v.yet", "en.v.report"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le mot qui correspond à la traduction entre parenthèses.", "prompt": "I haven''t written the report ___. (Je n''ai pas encore écrit le rapport.)", "promptLanguage": "en", "options": ["yet", "already", "just", "ever"], "answer": "yet", "acceptedAnswers": ["yet"], "hint": "« Pas encore » se dit not … + un mot placé à la fin de la phrase.", "explanation": "Pour dire « pas encore », on utilise une phrase négative avec yet à la fin : I haven''t written the report yet. Already s''emploie plutôt dans les phrases affirmatives.", "tip": "Pas encore = not … yet, à la fin de la phrase.", "extraExample": {"text": "She hasn''t called me yet.", "translation": "Elle ne m''a pas encore appelé."}, "errorPatterns": [{"equals": "already", "category": "word_confusion", "feedback": "Already (déjà) s''emploie dans une phrase affirmative. Dans une négation, « pas encore » se dit yet."}, {"equals": "just", "category": "word_confusion", "feedback": "Just veut dire « venir de ». « Pas encore » se dit yet."}, {"equals": "ever", "category": "word_confusion", "feedback": "Ever s''emploie dans les questions d''expérience. « Pas encore » se dit yet."}], "pool": "lesson", "lessonId": "en.l56", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l56.e06', 'en', 'en.l56', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.already','en.v.email']::text[], 'translation', 'lesson', 'Elle a déjà envoyé l''e-mail.', array['She has already sent the email.','She has sent the email already.','She has already sent the e-mail.','She has sent the e-mail already.','She already sent the email.','She sent the email already.']::text[], 'Pour dire que quelque chose est déjà fait, on utilise has + already + participe passé : sent. Already peut aussi se mettre à la fin de la phrase. En anglais américain, on entend aussi le past simple (She already sent…), mais en anglais britannique on utilise le present perfect.', 3, '{"id": "en.l56.e06", "unitIds": ["en.g39.present_perfect_intro", "en.v.already", "en.v.email"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Elle a déjà envoyé l''e-mail.", "promptLanguage": "fr", "answer": "She has already sent the email.", "acceptedAnswers": ["She has already sent the email.", "She has sent the email already.", "She has already sent the e-mail.", "She has sent the e-mail already.", "She already sent the email.", "She sent the email already."], "hint": "Already se place entre has et le participe passé de send.", "explanation": "Pour dire que quelque chose est déjà fait, on utilise has + already + participe passé : sent. Already peut aussi se mettre à la fin de la phrase. En anglais américain, on entend aussi le past simple (She already sent…), mais en anglais britannique on utilise le present perfect.", "tip": "Already se place entre have / has et le participe passé.", "extraExample": {"text": "I have already eaten lunch.", "translation": "J''ai déjà mangé le déjeuner."}, "errorPatterns": [{"contains": "has already send", "category": "conjugation", "feedback": "Après has, il faut le participe passé : sent (send – sent – sent)."}, {"contains": "have already sent", "category": "grammar", "feedback": "Avec she (elle), on utilise has, pas have."}, {"contains": "already sended", "category": "conjugation", "feedback": "Send est irrégulier : le participe passé est sent, pas sended."}], "pool": "lesson", "lessonId": "en.l56", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l56.e07', 'en', 'en.l56', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.just','en.v.email']::text[], 'reorder', 'lesson', 'Anna vient d''envoyer un e-mail à Tom.', array['Anna has just sent an email to Tom']::text[], 'On commence par le sujet Anna, puis has just + participe passé sent. Just reste collé à has, avant le participe passé. An se place devant email (son de voyelle).', 3, '{"id": "en.l56.e07", "unitIds": ["en.g39.present_perfect_intro", "en.v.just", "en.v.email"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Anna vient d''envoyer un e-mail à Tom.", "promptLanguage": "fr", "tokens": ["Tom", "has", "an", "Anna", "sent", "email", "to", "just"], "answer": "Anna has just sent an email to Tom", "acceptedAnswers": ["Anna has just sent an email to Tom"], "hint": "Just se place entre has et le participe passé.", "explanation": "On commence par le sujet Anna, puis has just + participe passé sent. Just reste collé à has, avant le participe passé. An se place devant email (son de voyelle).", "tip": "Sujet + has / have + just + participe passé.", "extraExample": {"text": "Tom has just left the office.", "translation": "Tom vient de quitter le bureau."}, "pool": "lesson", "lessonId": "en.l56", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l56.e08', 'en', 'en.l56', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.yet','en.v.report']::text[], 'translation', 'lesson', 'Je n''ai pas encore lu le rapport.', array['I haven''t read the report yet.','I haven''t yet read the report.','I didn''t read the report yet.']::text[], '« Pas encore » se traduit par une négation avec yet : I haven''t read the report yet. Le participe passé de read s''écrit comme l''infinitif (read), mais il se prononce « red ».', 4, '{"id": "en.l56.e08", "unitIds": ["en.g39.present_perfect_intro", "en.v.yet", "en.v.report"], "type": "translation", "difficulty": 4, "instruction": "Traduis en anglais.", "prompt": "Je n''ai pas encore lu le rapport.", "promptLanguage": "fr", "answer": "I haven''t read the report yet.", "acceptedAnswers": ["I haven''t read the report yet.", "I haven''t yet read the report.", "I didn''t read the report yet."], "hint": "Utilise une phrase négative avec le mot yet.", "explanation": "« Pas encore » se traduit par une négation avec yet : I haven''t read the report yet. Le participe passé de read s''écrit comme l''infinitif (read), mais il se prononce « red ».", "tip": "Pas encore = haven''t / hasn''t + participe passé + yet.", "extraExample": {"text": "We haven''t seen the new film yet.", "translation": "Nous n''avons pas encore vu le nouveau film."}, "errorPatterns": [{"contains": "report already", "category": "word_confusion", "feedback": "Already (déjà) s''emploie dans une phrase affirmative. Pour « pas encore », on dit yet."}, {"contains": "don''t have read", "category": "grammar", "feedback": "Pour le present perfect négatif, on dit haven''t + participe passé, pas don''t have."}, {"contains": "readed", "category": "spelling", "feedback": "Read est irrégulier : le participe passé s''écrit read (et se prononce « red »), pas readed."}], "pool": "lesson", "lessonId": "en.l56", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l56.e09', 'en', 'en.l56', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.just','en.v.report']::text[], 'free_answer', 'lesson', 'Comment dit-on « Je viens de finir mon rapport » en anglais ?', array['I have just finished my report.','I just finished my report.','I have just completed my report.','I have just written my report.']::text[], 'Pour « venir de », on utilise have just + participe passé : finished. On ne traduit pas « venir de » mot à mot avec come.', 4, '{"id": "en.l56.e09", "unitIds": ["en.g39.present_perfect_intro", "en.v.just", "en.v.report"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Je viens de finir mon rapport » en anglais ?", "promptLanguage": "fr", "answer": "I have just finished my report.", "acceptedAnswers": ["I have just finished my report.", "I just finished my report.", "I have just completed my report.", "I have just written my report."], "hint": "« Venir de » = have + just + participe passé.", "explanation": "Pour « venir de », on utilise have just + participe passé : finished. On ne traduit pas « venir de » mot à mot avec come.", "tip": "Je viens de… = I have just + participe passé.", "extraExample": {"text": "She has just finished her homework.", "translation": "Elle vient de finir ses devoirs."}, "errorPatterns": [{"contains": "i come to", "category": "vocabulary", "feedback": "« Je viens de » ne se traduit pas avec come. On dit I have just + participe passé."}, {"contains": "just finish my", "category": "conjugation", "feedback": "Après have just, il faut le participe passé : finished."}, {"contains": "finished just", "category": "word_order", "feedback": "Just se place entre have et le participe passé : have just finished."}], "pool": "lesson", "lessonId": "en.l56", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l56.e10', 'en', 'en.l56', 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.v.already','en.v.just']::text[], 'free_answer', 'lesson', 'Dis ce que tu viens de faire, ou ce que tu as déjà fait aujourd''hui.', array['I have already eaten breakfast.','I have just finished my homework.','Anna has just sent an email.','We have already cleaned the kitchen.']::text[], 'Pour parler de ce qui vient d''arriver ou de ce qui est déjà fait, on utilise have / has + just ou already + participe passé. Ne donne pas de moment précis comme yesterday.', 5, '{"id": "en.l56.e10", "unitIds": ["en.g39.present_perfect_intro", "en.v.already", "en.v.just"], "type": "free_answer", "difficulty": 5, "instruction": "Écris une phrase en anglais avec just ou already et un participe passé.", "prompt": "Dis ce que tu viens de faire, ou ce que tu as déjà fait aujourd''hui.", "promptLanguage": "fr", "requirements": {"mustInclude": [["just", "already"], ["have", "has", "''ve"]], "minWords": 4}, "answer": "I have already eaten breakfast.", "acceptedAnswers": ["I have already eaten breakfast.", "I have just finished my homework.", "Anna has just sent an email.", "We have already cleaned the kitchen."], "hint": "Forme : sujet + have / has + just (ou already) + participe passé.", "explanation": "Pour parler de ce qui vient d''arriver ou de ce qui est déjà fait, on utilise have / has + just ou already + participe passé. Ne donne pas de moment précis comme yesterday.", "tip": "Just ou already se place entre have / has et le participe passé.", "extraExample": {"text": "Tom has already read the report.", "translation": "Tom a déjà lu le rapport."}, "errorPatterns": [{"contains": "already went", "category": "conjugation", "feedback": "Went est le past simple. Avec have / has, il faut le participe passé : gone ou been."}, {"contains": "just went", "category": "conjugation", "feedback": "Went est le past simple. Avec have / has just, il faut le participe passé : gone ou been."}, {"contains": "yesterday", "category": "verb_tense", "feedback": "Yesterday est un moment précis : on n''utilise pas le present perfect avec lui. Ici, écris sans date ce que tu viens de faire ou as déjà fait."}], "pool": "lesson", "lessonId": "en.l56", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l57.e01', 'en', 'en.l57', 'en.g40.short_answers', array['en.g40.short_answers','en.v.how_are_you']::text[], 'mcq', 'lesson', 'Hi Anna! How are you? — ___', array['I''m fine, thanks.']::text[], 'How are you? veut dire « comment ça va ? » : on répond avec une phrase (I''m fine, thanks). On ne répond pas Yes ou No, car ce n''est pas une question fermée.', 2, '{"id": "en.l57.e01", "unitIds": ["en.g40.short_answers", "en.v.how_are_you"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Hi Anna! How are you? — ___", "promptLanguage": "en", "options": ["I''m fine, thanks.", "Yes, I am.", "Yes, I do.", "No, I don''t."], "answer": "I''m fine, thanks.", "acceptedAnswers": ["I''m fine, thanks."], "hint": "How are you? n''est pas une question à laquelle on répond par oui ou non.", "explanation": "How are you? veut dire « comment ça va ? » : on répond avec une phrase (I''m fine, thanks). On ne répond pas Yes ou No, car ce n''est pas une question fermée.", "tip": "How are you? → I''m fine, thanks. Les réponses Yes / No sont pour les questions fermées.", "extraExample": {"text": "How are you today? — I''m tired, but I''m fine.", "translation": "Comment vas-tu aujourd''hui ? — Je suis fatigué, mais ça va."}, "errorPatterns": [{"equals": "yes i am", "category": "grammar", "feedback": "How are you? n''attend pas oui ou non : elle demande comment tu vas. Réponds par I''m fine, thanks."}, {"equals": "yes i do", "category": "grammar", "feedback": "Yes, I do répond à une question avec do (Do you…?). How are you? demande comment tu vas : I''m fine, thanks."}, {"equals": "no i don''t", "category": "grammar", "feedback": "How are you? n''attend pas oui ou non. Réponds par I''m fine, thanks (ou I''m tired, I''m busy…)."}], "pool": "lesson", "lessonId": "en.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l57.e02', 'en', 'en.l57', 'en.g40.short_answers', array['en.g40.short_answers']::text[], 'mcq', 'lesson', 'I don''t like cold coffee. — ___', array['Me neither.']::text[], 'Après une phrase négative, « moi non plus » se dit Me neither. Me too veut dire « moi aussi » et répond à une phrase affirmative.', 3, '{"id": "en.l57.e02", "unitIds": ["en.g40.short_answers"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réaction.", "prompt": "I don''t like cold coffee. — ___", "promptLanguage": "en", "options": ["Me neither.", "Me too.", "So do I.", "Me not."], "answer": "Me neither.", "acceptedAnswers": ["Me neither."], "hint": "Tu veux dire « moi non plus » : la phrase de départ est négative.", "explanation": "Après une phrase négative, « moi non plus » se dit Me neither. Me too veut dire « moi aussi » et répond à une phrase affirmative.", "tip": "Phrase affirmative → Me too ; phrase négative → Me neither.", "extraExample": {"text": "I can''t swim. — Me neither.", "translation": "Je ne sais pas nager. — Moi non plus."}, "errorPatterns": [{"equals": "me too", "category": "grammar", "feedback": "Me too veut dire « moi aussi » et répond à une phrase affirmative. Après I don''t, « moi non plus » se dit Me neither."}, {"equals": "so do i", "category": "grammar", "feedback": "So do I veut dire « moi aussi » et répond à une phrase affirmative. Après une phrase négative, on dit Me neither."}, {"equals": "me not", "category": "grammar", "feedback": "On ne dit pas Me not. « Moi non plus » se dit Me neither."}], "pool": "lesson", "lessonId": "en.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l57.e03', 'en', 'en.l57', 'en.g40.short_answers', array['en.g40.short_answers','en.v.nice_to_meet_you','en.v.how_are_you','en.v.excuse_me','en.v.of_course','en.v.no_problem']::text[], 'match', 'lesson', 'Les formules de politesse à connaître', '{}'::text[], 'Ce sont des formules toutes faites : on les apprend telles quelles. Nice to meet you se dit à une première rencontre ; excuse me, pour attirer l''attention ou passer poliment.', 2, '{"id": "en.l57.e03", "unitIds": ["en.g40.short_answers", "en.v.nice_to_meet_you", "en.v.how_are_you", "en.v.excuse_me", "en.v.of_course", "en.v.no_problem"], "type": "match", "difficulty": 2, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les formules de politesse à connaître", "promptLanguage": "fr", "pairs": [{"left": "Nice to meet you.", "right": "Enchanté."}, {"left": "How are you?", "right": "Comment ça va ?"}, {"left": "Excuse me.", "right": "Excusez-moi."}, {"left": "Of course.", "right": "Bien sûr."}, {"left": "No problem.", "right": "Pas de problème."}], "answer": "Nice to meet you. = Enchanté. ; How are you? = Comment ça va ? ; Excuse me. = Excusez-moi. ; Of course. = Bien sûr. ; No problem. = Pas de problème.", "acceptedAnswers": [], "explanation": "Ce sont des formules toutes faites : on les apprend telles quelles. Nice to meet you se dit à une première rencontre ; excuse me, pour attirer l''attention ou passer poliment.", "tip": "Ces formules ne se traduisent pas mot à mot : apprends-les comme un bloc.", "extraExample": {"text": "Can you help me? — Of course.", "translation": "Peux-tu m''aider ? — Bien sûr."}, "pool": "lesson", "lessonId": "en.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l57.e04', 'en', 'en.l57', 'en.g40.short_answers', array['en.g40.short_answers','en.v.nice_to_meet_you']::text[], 'fill_blank', 'lesson', 'Nice to meet you, Tom. — Nice to meet you, ___.', array['too']::text[], 'Too veut dire « aussi » et se place à la fin d''une phrase affirmative : Nice to meet you, too = enchanté aussi.', 2, '{"id": "en.l57.e04", "unitIds": ["en.g40.short_answers", "en.v.nice_to_meet_you"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la réponse.", "prompt": "Nice to meet you, Tom. — Nice to meet you, ___.", "promptLanguage": "en", "options": ["too", "either", "neither", "yet"], "answer": "too", "acceptedAnswers": ["too"], "hint": "La phrase est affirmative : « aussi ».", "explanation": "Too veut dire « aussi » et se place à la fin d''une phrase affirmative : Nice to meet you, too = enchanté aussi.", "tip": "Phrase affirmative → too (aussi) ; phrase négative → either (non plus).", "extraExample": {"text": "I''m hungry. — I''m hungry too.", "translation": "J''ai faim. — Moi aussi, j''ai faim."}, "errorPatterns": [{"equals": "either", "category": "word_confusion", "feedback": "Either veut dire « non plus » et s''emploie dans une phrase négative. Ici, la phrase est affirmative : on dit too."}, {"equals": "neither", "category": "word_confusion", "feedback": "Neither s''emploie dans Me neither (« moi non plus »), pas à la fin d''une phrase affirmative. Ici : too."}, {"equals": "yet", "category": "word_confusion", "feedback": "Yet veut dire « déjà ? » ou « pas encore ». Pour « aussi », on dit too."}], "pool": "lesson", "lessonId": "en.l57", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l57.e05', 'en', 'en.l57', 'en.g40.short_answers', array['en.g40.short_answers']::text[], 'fill_blank', 'lesson', 'Did you call Anna yesterday? — No, I ___.', array['didn''t']::text[], 'Dans une réponse courte, on reprend l''auxiliaire de la question. La question commence par Did : on répond No, I didn''t.', 3, '{"id": "en.l57.e05", "unitIds": ["en.g40.short_answers"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la réponse courte.", "prompt": "Did you call Anna yesterday? — No, I ___.", "promptLanguage": "en", "options": ["didn''t", "don''t", "haven''t", "wasn''t"], "answer": "didn''t", "acceptedAnswers": ["didn''t"], "hint": "La question commence par Did.", "explanation": "Dans une réponse courte, on reprend l''auxiliaire de la question. La question commence par Did : on répond No, I didn''t.", "tip": "Did → I did / I didn''t ; Do → I do / I don''t ; Is → it is / it isn''t.", "extraExample": {"text": "Did Tom win the game? — Yes, he did.", "translation": "Tom a-t-il gagné le match ? — Oui."}, "errorPatterns": [{"equals": "don''t", "category": "verb_tense", "feedback": "Don''t reprend une question avec do (présent). La question est au passé (Did) : on répond didn''t."}, {"equals": "haven''t", "category": "grammar", "feedback": "Haven''t répond à une question avec have. Ici, la question commence par Did : on répond didn''t."}, {"equals": "wasn''t", "category": "grammar", "feedback": "Wasn''t est le passé de be. La question commence par Did : on répond didn''t."}], "pool": "lesson", "lessonId": "en.l57", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l57.e06', 'en', 'en.l57', 'en.g40.short_answers', array['en.g40.short_answers','en.v.excuse_me']::text[], 'translation', 'lesson', 'Excusez-moi, où est la gare ?', array['Excuse me, where is the station?','Excuse me, where is the train station?','Excuse me, where is the railway station?','Sorry, where is the station?','Sorry, where is the train station?']::text[], 'Excuse me sert à attirer l''attention de quelqu''un ou à lui parler poliment. Ensuite, la question suit : where is the station ? (avec the devant station).', 3, '{"id": "en.l57.e06", "unitIds": ["en.g40.short_answers", "en.v.excuse_me"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Excusez-moi, où est la gare ?", "promptLanguage": "fr", "answer": "Excuse me, where is the station?", "acceptedAnswers": ["Excuse me, where is the station?", "Excuse me, where is the train station?", "Excuse me, where is the railway station?", "Sorry, where is the station?", "Sorry, where is the train station?"], "hint": "Pour attirer l''attention de quelqu''un, on commence par excuse me.", "explanation": "Excuse me sert à attirer l''attention de quelqu''un ou à lui parler poliment. Ensuite, la question suit : where is the station ? (avec the devant station).", "tip": "Excuse me pour attirer l''attention ; sorry pour s''excuser d''une erreur.", "extraExample": {"text": "Excuse me, is this seat free?", "translation": "Excusez-moi, cette place est-elle libre ?"}, "errorPatterns": [{"contains": "where are", "category": "grammar", "feedback": "Station est au singulier : on dit where is the station ?"}, {"contains": "where is station", "category": "grammar", "feedback": "Il manque l''article : where is the station ?"}, {"contains": "where station", "category": "word_order", "feedback": "Une question avec where garde is : where is the station ?"}], "pool": "lesson", "lessonId": "en.l57", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l57.e07', 'en', 'en.l57', 'en.g40.short_answers', array['en.g40.short_answers']::text[], 'reorder', 'lesson', 'Je n''aime pas le poisson, et mon frère non plus.', array['I don''t like fish and my brother doesn''t either','My brother doesn''t like fish and I don''t either']::text[], 'Either veut dire « non plus » et se place à la fin d''une phrase négative. Chaque partie garde sa propre négation : I don''t … and my brother doesn''t either.', 3, '{"id": "en.l57.e07", "unitIds": ["en.g40.short_answers"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Je n''aime pas le poisson, et mon frère non plus.", "promptLanguage": "fr", "tokens": ["fish", "I", "my", "and", "brother", "doesn''t", "like", "either", "don''t"], "answer": "I don''t like fish and my brother doesn''t either", "acceptedAnswers": ["I don''t like fish and my brother doesn''t either", "My brother doesn''t like fish and I don''t either"], "hint": "« Non plus » se dit either, tout à la fin.", "explanation": "Either veut dire « non plus » et se place à la fin d''une phrase négative. Chaque partie garde sa propre négation : I don''t … and my brother doesn''t either.", "tip": "Négation + either à la fin = « non plus ».", "extraExample": {"text": "Anna doesn''t eat meat, and I don''t either.", "translation": "Anna ne mange pas de viande, et moi non plus."}, "pool": "lesson", "lessonId": "en.l57", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l57.e08', 'en', 'en.l57', 'en.g40.short_answers', array['en.g40.short_answers','en.g39.present_perfect_intro','en.v.abroad']::text[], 'translation', 'lesson', 'Je n''ai jamais été à l''étranger, et Anna non plus.', array['I have never been abroad, and Anna hasn''t either.','I have never been abroad, and neither has Anna.','I have never been abroad, and nor has Anna.','I have never been abroad, and Anna hasn''t been either.','I have never been abroad, and Anna has never been abroad either.','I haven''t been abroad, and Anna hasn''t either.','I have never gone abroad, and Anna hasn''t either.']::text[], 'Pour dire « non plus » après une phrase au present perfect, on reprend l''auxiliaire : Anna hasn''t either. On peut aussi dire neither has Anna.', 4, '{"id": "en.l57.e08", "unitIds": ["en.g40.short_answers", "en.g39.present_perfect_intro", "en.v.abroad"], "type": "translation", "difficulty": 4, "instruction": "Traduis en anglais.", "prompt": "Je n''ai jamais été à l''étranger, et Anna non plus.", "promptLanguage": "fr", "answer": "I have never been abroad, and Anna hasn''t either.", "acceptedAnswers": ["I have never been abroad, and Anna hasn''t either.", "I have never been abroad, and neither has Anna.", "I have never been abroad, and nor has Anna.", "I have never been abroad, and Anna hasn''t been either.", "I have never been abroad, and Anna has never been abroad either.", "I haven''t been abroad, and Anna hasn''t either.", "I have never gone abroad, and Anna hasn''t either."], "hint": "Pour « non plus », reprends have / has avec n''t, puis ajoute either.", "explanation": "Pour dire « non plus » après une phrase au present perfect, on reprend l''auxiliaire : Anna hasn''t either. On peut aussi dire neither has Anna.", "tip": "Une seule négation : hasn''t either ou neither has, jamais hasn''t neither.", "extraExample": {"text": "Tom hasn''t seen this film, and I haven''t either.", "translation": "Tom n''a pas vu ce film, et moi non plus."}, "errorPatterns": [{"contains": "hasn''t neither", "category": "grammar", "feedback": "Ne mets pas deux négations. Dis Anna hasn''t either, ou neither has Anna."}, {"contains": "hasn''t too", "category": "word_confusion", "feedback": "Too veut dire « aussi ». Dans une phrase négative, « non plus » se dit either."}, {"contains": "anna too", "category": "word_confusion", "feedback": "Too veut dire « aussi ». Après une phrase négative, « non plus » se dit either : Anna hasn''t either."}], "pool": "lesson", "lessonId": "en.l57", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l57.e09', 'en', 'en.l57', 'en.g40.short_answers', array['en.g40.short_answers','en.v.of_course','en.v.no_problem']::text[], 'free_answer', 'lesson', 'Comment dit-on « Bien sûr, pas de problème » en anglais ?', array['Of course, no problem.','Yes, of course, no problem.','Of course, it''s no problem.','Of course, that''s no problem.','Sure, no problem.','Certainly, no problem.','Of course, no worries.','Yes, of course. No problem.']::text[], 'Bien sûr se dit of course, et pas de problème se dit no problem. Ce sont des formules toutes faites qu''on utilise pour répondre à une demande.', 4, '{"id": "en.l57.e09", "unitIds": ["en.g40.short_answers", "en.v.of_course", "en.v.no_problem"], "type": "free_answer", "difficulty": 4, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Bien sûr, pas de problème » en anglais ?", "promptLanguage": "fr", "answer": "Of course, no problem.", "acceptedAnswers": ["Of course, no problem.", "Yes, of course, no problem.", "Of course, it''s no problem.", "Of course, that''s no problem.", "Sure, no problem.", "Certainly, no problem.", "Of course, no worries.", "Yes, of course. No problem."], "hint": "Ce sont deux formules à apprendre par cœur.", "explanation": "Bien sûr se dit of course, et pas de problème se dit no problem. Ce sont des formules toutes faites qu''on utilise pour répondre à une demande.", "tip": "Of course = bien sûr ; no problem = pas de problème.", "extraExample": {"text": "Can you wait a moment? — Of course, no problem.", "translation": "Peux-tu attendre un instant ? — Bien sûr, pas de problème."}, "errorPatterns": [{"contains": "of course not", "category": "word_confusion", "feedback": "Of course not veut dire « bien sûr que non ! » : le contraire de ce que tu veux dire. Pour « bien sûr », dis of course."}, {"contains": "no problems", "category": "grammar", "feedback": "On dit no problem au singulier."}, {"contains": "not problem", "category": "grammar", "feedback": "« Pas de problème » se dit no problem (ou not a problem)."}], "pool": "lesson", "lessonId": "en.l57", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l57.e10', 'en', 'en.l57', 'en.g40.short_answers', array['en.g40.short_answers']::text[], 'free_answer', 'lesson', 'On te demande : « Do you watch films in English? »', array['Yes, I do. I watch a film every weekend.','Yes, I do. I love English films.','No, I don''t. I watch films in French.','No, I don''t. I like music.']::text[], 'La question commence par Do : la réponse courte reprend do. Dis Yes, I do ou No, I don''t, puis ajoute une phrase pour donner plus de détails.', 5, '{"id": "en.l57.e10", "unitIds": ["en.g40.short_answers"], "type": "free_answer", "difficulty": 5, "instruction": "Réponds par une réponse courte, puis ajoute une phrase.", "prompt": "On te demande : « Do you watch films in English? »", "promptLanguage": "fr", "requirements": {"mustInclude": [["yes", "no"], ["do", "don''t"]], "minWords": 4}, "answer": "Yes, I do. I watch a film every weekend.", "acceptedAnswers": ["Yes, I do. I watch a film every weekend.", "Yes, I do. I love English films.", "No, I don''t. I watch films in French.", "No, I don''t. I like music."], "hint": "Commence par Yes, I … ou No, I … avec le même auxiliaire que la question.", "explanation": "La question commence par Do : la réponse courte reprend do. Dis Yes, I do ou No, I don''t, puis ajoute une phrase pour donner plus de détails.", "tip": "Do you…? → Yes, I do / No, I don''t, et une phrase en plus pour continuer la conversation.", "extraExample": {"text": "Do you like coffee? — Yes, I do. I drink it every morning.", "translation": "Tu aimes le café ? — Oui. J''en bois tous les matins."}, "errorPatterns": [{"contains": "yes i am", "category": "grammar", "feedback": "La question commence par Do, pas par Are : la réponse courte est Yes, I do."}, {"contains": "no i''m not", "category": "grammar", "feedback": "La question commence par Do, pas par Are : la réponse courte est No, I don''t."}, {"contains": "yes i watch", "category": "instruction", "feedback": "Ta phrase est correcte, mais la consigne demande d''abord une réponse courte avec do : Yes, I do."}], "pool": "lesson", "lessonId": "en.l57", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l58.e01', 'en', 'en.l58', 'en.g40.short_answers', array['en.g40.short_answers','en.v.i_dont_know']::text[], 'mcq', 'lesson', 'Where is Tom? — ___', array['I don''t know.']::text[], 'Quand on ne connaît pas la réponse, on dit I don''t know. Les trois autres expressions ne répondent pas à la question « Où est Tom ? ».', 2, '{"id": "en.l58.e01", "unitIds": ["en.g40.short_answers", "en.v.i_dont_know"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la réponse qui convient.", "prompt": "Where is Tom? — ___", "promptLanguage": "en", "options": ["I don''t know.", "Never mind.", "Good luck.", "See you later."], "answer": "I don''t know.", "acceptedAnswers": ["I don''t know."], "hint": "Tu n''as pas l''information.", "explanation": "Quand on ne connaît pas la réponse, on dit I don''t know. Les trois autres expressions ne répondent pas à la question « Où est Tom ? ».", "tip": "Tu n''as pas l''information ? Réponds simplement I don''t know.", "extraExample": {"text": "What time is it? — I don''t know.", "translation": "Quelle heure est-il ? — Je ne sais pas."}, "errorPatterns": [{"equals": "never mind", "category": "vocabulary", "feedback": "Never mind veut dire « ce n''est pas grave ». Pour « je ne sais pas », on dit I don''t know."}, {"equals": "good luck", "category": "vocabulary", "feedback": "Good luck veut dire « bonne chance ». Pour « je ne sais pas », on dit I don''t know."}, {"equals": "see you later", "category": "vocabulary", "feedback": "See you later veut dire « à plus tard ». Pour « je ne sais pas », on dit I don''t know."}], "pool": "lesson", "lessonId": "en.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l58.e02', 'en', 'en.l58', 'en.g40.short_answers', array['en.g40.short_answers','en.v.never_mind']::text[], 'mcq', 'lesson', 'Sorry, I forgot your book. — ___', array['Never mind.']::text[], 'Quelqu''un s''excuse d''un petit oubli : on peut répondre Never mind, c''est-à-dire « ce n''est pas grave ».', 3, '{"id": "en.l58.e02", "unitIds": ["en.g40.short_answers", "en.v.never_mind"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la réponse qui convient.", "prompt": "Sorry, I forgot your book. — ___", "promptLanguage": "en", "options": ["Never mind.", "Good luck.", "Me neither.", "Nice to meet you."], "answer": "Never mind.", "acceptedAnswers": ["Never mind."], "hint": "Tu veux dire que ce n''est pas important.", "explanation": "Quelqu''un s''excuse d''un petit oubli : on peut répondre Never mind, c''est-à-dire « ce n''est pas grave ».", "tip": "Never mind = ce n''est pas grave, laisse tomber.", "extraExample": {"text": "I''m late, sorry! — Never mind.", "translation": "Je suis en retard, désolé ! — Ce n''est pas grave."}, "errorPatterns": [{"equals": "good luck", "category": "vocabulary", "feedback": "Good luck se dit avant un examen ou une épreuve. Pour dire « ce n''est pas grave », on dit never mind."}, {"equals": "me neither", "category": "vocabulary", "feedback": "Me neither veut dire « moi non plus » et répond à une phrase négative. Ici : never mind."}, {"equals": "nice to meet you", "category": "vocabulary", "feedback": "Nice to meet you se dit à une première rencontre. Pour « ce n''est pas grave », on dit never mind."}], "pool": "lesson", "lessonId": "en.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l58.e03', 'en', 'en.l58', 'en.g40.short_answers', array['en.g40.short_answers','en.v.i_understand','en.v.i_dont_know','en.v.never_mind','en.v.see_you_later','en.v.good_luck']::text[], 'match', 'lesson', 'Les expressions du quotidien', '{}'::text[], 'Ces expressions sont des réponses très courtes qu''on utilise tout le temps à l''oral. On les apprend en bloc, sans les traduire mot à mot.', 2, '{"id": "en.l58.e03", "unitIds": ["en.g40.short_answers", "en.v.i_understand", "en.v.i_dont_know", "en.v.never_mind", "en.v.see_you_later", "en.v.good_luck"], "type": "match", "difficulty": 2, "instruction": "Associe chaque expression anglaise à sa traduction.", "prompt": "Les expressions du quotidien", "promptLanguage": "fr", "pairs": [{"left": "I understand.", "right": "Je comprends."}, {"left": "I don''t know.", "right": "Je ne sais pas."}, {"left": "Never mind.", "right": "Ce n''est pas grave."}, {"left": "See you later.", "right": "À plus tard."}, {"left": "Good luck!", "right": "Bonne chance !"}], "answer": "I understand. = Je comprends. ; I don''t know. = Je ne sais pas. ; Never mind. = Ce n''est pas grave. ; See you later. = À plus tard. ; Good luck! = Bonne chance !", "acceptedAnswers": [], "explanation": "Ces expressions sont des réponses très courtes qu''on utilise tout le temps à l''oral. On les apprend en bloc, sans les traduire mot à mot.", "tip": "Apprends ces expressions comme des blocs : elles servent à réagir vite.", "extraExample": {"text": "See you later, Tom. Good luck!", "translation": "À plus tard, Tom. Bonne chance !"}, "pool": "lesson", "lessonId": "en.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l58.e04', 'en', 'en.l58', 'en.g40.short_answers', array['en.g40.short_answers','en.v.good_luck']::text[], 'fill_blank', 'lesson', 'You have an exam today? Good ___!', array['luck']::text[], 'On dit good luck, avec le nom luck. Lucky est un adjectif (chanceux) et ne convient pas ici.', 2, '{"id": "en.l58.e04", "unitIds": ["en.g40.short_answers", "en.v.good_luck"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète l''expression.", "prompt": "You have an exam today? Good ___!", "promptLanguage": "en", "options": ["luck", "lucky", "lucks", "good"], "answer": "luck", "acceptedAnswers": ["luck"], "hint": "« Bonne chance » : good + un nom.", "explanation": "On dit good luck, avec le nom luck. Lucky est un adjectif (chanceux) et ne convient pas ici.", "tip": "Good luck : un adjectif (good) + un nom (luck).", "extraExample": {"text": "Good luck with your new job!", "translation": "Bonne chance pour ton nouveau travail !"}, "errorPatterns": [{"equals": "lucky", "category": "word_confusion", "feedback": "Lucky veut dire « chanceux ». Pour souhaiter bonne chance, on dit good luck."}, {"equals": "lucks", "category": "grammar", "feedback": "Luck est un nom qu''on n''accorde pas ici : good luck, sans -s."}, {"equals": "good", "category": "grammar", "feedback": "Good est déjà dans la phrase. Il manque le nom : good luck."}], "pool": "lesson", "lessonId": "en.l58", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l58.e05', 'en', 'en.l58', 'en.g40.short_answers', array['en.g40.short_answers','en.v.i_understand']::text[], 'fill_blank', 'lesson', 'Do you understand the rule? — Yes, I ___.', array['do']::text[], 'La question commence par Do : la réponse courte reprend do. On dit Yes, I do.', 3, '{"id": "en.l58.e05", "unitIds": ["en.g40.short_answers", "en.v.i_understand"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la réponse courte.", "prompt": "Do you understand the rule? — Yes, I ___.", "promptLanguage": "en", "options": ["do", "am", "can", "have"], "answer": "do", "acceptedAnswers": ["do"], "hint": "La question commence par Do.", "explanation": "La question commence par Do : la réponse courte reprend do. On dit Yes, I do.", "tip": "On répète l''auxiliaire de la question : Do you…? → Yes, I do.", "extraExample": {"text": "Do you speak French? — Yes, I do.", "translation": "Parles-tu français ? — Oui."}, "errorPatterns": [{"equals": "am", "category": "grammar", "feedback": "Am répond à une question avec be (Are you…?). Ici, la question commence par Do : Yes, I do."}, {"equals": "can", "category": "grammar", "feedback": "Can répond à une question avec can. La question commence par Do : Yes, I do."}, {"equals": "have", "category": "grammar", "feedback": "Have répond à une question avec have. La question commence par Do : Yes, I do."}], "pool": "lesson", "lessonId": "en.l58", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l58.e06', 'en', 'en.l58', 'en.g40.short_answers', array['en.g40.short_answers','en.v.i_understand']::text[], 'translation', 'lesson', 'Désolé, je ne comprends pas la question.', array['Sorry, I don''t understand the question.','I''m sorry, I don''t understand the question.','I don''t understand the question, sorry.','I don''t understand the question. Sorry.','I don''t understand the question, I''m sorry.']::text[], 'Pour nier un verbe au présent simple, on utilise I don''t + verbe de base : I don''t understand. Le verbe understand ne s''emploie pas avec be.', 3, '{"id": "en.l58.e06", "unitIds": ["en.g40.short_answers", "en.v.i_understand"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Désolé, je ne comprends pas la question.", "promptLanguage": "fr", "answer": "Sorry, I don''t understand the question.", "acceptedAnswers": ["Sorry, I don''t understand the question.", "I''m sorry, I don''t understand the question.", "I don''t understand the question, sorry.", "I don''t understand the question. Sorry.", "I don''t understand the question, I''m sorry."], "hint": "Understand est un verbe : la négation se fait avec don''t.", "explanation": "Pour nier un verbe au présent simple, on utilise I don''t + verbe de base : I don''t understand. Le verbe understand ne s''emploie pas avec be.", "tip": "Je ne comprends pas = I don''t understand (jamais I am not understand).", "extraExample": {"text": "I don''t understand this word.", "translation": "Je ne comprends pas ce mot."}, "errorPatterns": [{"contains": "i''m not understand", "category": "grammar", "feedback": "Understand est un verbe : on ne l''emploie pas avec be. Dis I don''t understand."}, {"contains": "i not understand", "category": "grammar", "feedback": "La négation se fait avec don''t : I don''t understand."}, {"contains": "don''t understands", "category": "conjugation", "feedback": "Après don''t, le verbe reste à la forme de base : I don''t understand, sans -s."}], "pool": "lesson", "lessonId": "en.l58", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l58.e07', 'en', 'en.l58', 'en.g40.short_answers', array['en.g40.short_answers']::text[], 'reorder', 'lesson', 'J''aime le café, et mon frère aussi.', array['I like coffee and my brother does too']::text[], 'Pour dire « et lui aussi », on reprend l''auxiliaire du premier verbe sans répéter le verbe : my brother does too (does, car brother = he). Too se place à la fin.', 3, '{"id": "en.l58.e07", "unitIds": ["en.g40.short_answers"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "J''aime le café, et mon frère aussi.", "promptLanguage": "fr", "tokens": ["coffee", "I", "my", "and", "brother", "does", "like", "too"], "answer": "I like coffee and my brother does too", "acceptedAnswers": ["I like coffee and my brother does too"], "hint": "« Aussi » se dit too, à la fin, après l''auxiliaire.", "explanation": "Pour dire « et lui aussi », on reprend l''auxiliaire du premier verbe sans répéter le verbe : my brother does too (does, car brother = he). Too se place à la fin.", "tip": "Même auxiliaire + too à la fin : I do too, she does too, we are too.", "extraExample": {"text": "I work in London and my sister does too.", "translation": "Je travaille à Londres et ma sœur aussi."}, "pool": "lesson", "lessonId": "en.l58", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l58.e08', 'en', 'en.l58', 'en.g40.short_answers', array['en.g40.short_answers','en.v.see_you_later','en.v.good_luck']::text[], 'translation', 'lesson', 'À plus tard, Anna. Bonne chance pour ton nouveau travail !', array['See you later, Anna. Good luck with your new job!','See you later, Anna. Good luck in your new job!','See you later, Anna. Good luck for your new job!','See you later, Anna. Good luck at your new job!','Good luck with your new job, Anna. See you later!','Anna, see you later. Good luck with your new job!']::text[], '« À plus tard » se dit see you later et « bonne chance » se dit good luck. Pour « bonne chance pour ton travail », on dit good luck with your job.', 4, '{"id": "en.l58.e08", "unitIds": ["en.g40.short_answers", "en.v.see_you_later", "en.v.good_luck"], "type": "translation", "difficulty": 4, "instruction": "Traduis en anglais.", "prompt": "À plus tard, Anna. Bonne chance pour ton nouveau travail !", "promptLanguage": "fr", "answer": "See you later, Anna. Good luck with your new job!", "acceptedAnswers": ["See you later, Anna. Good luck with your new job!", "See you later, Anna. Good luck in your new job!", "See you later, Anna. Good luck for your new job!", "See you later, Anna. Good luck at your new job!", "Good luck with your new job, Anna. See you later!", "Anna, see you later. Good luck with your new job!"], "hint": "Deux expressions toutes faites : see you later et good luck.", "explanation": "« À plus tard » se dit see you later et « bonne chance » se dit good luck. Pour « bonne chance pour ton travail », on dit good luck with your job.", "tip": "Good luck with + ce qu''on souhaite réussir.", "extraExample": {"text": "Good luck with your exam!", "translation": "Bonne chance pour ton examen !"}, "errorPatterns": [{"contains": "good lucky", "category": "word_confusion", "feedback": "Lucky veut dire « chanceux ». Pour souhaiter bonne chance, on dit good luck."}, {"contains": "good chance", "category": "word_confusion", "feedback": "Good chance veut dire « une bonne probabilité ». Pour « bonne chance », on dit good luck."}, {"contains": "see you after", "category": "vocabulary", "feedback": "« À plus tard » se dit see you later."}], "pool": "lesson", "lessonId": "en.l58", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l58.e09', 'en', 'en.l58', 'en.v.i_understand', array['en.v.i_understand','en.g40.short_answers']::text[], 'free_answer', 'lesson', 'Comment dit-on : « J''ai compris » ?', array['I understand.','I''ve understood.','I understood.','I get it.','I got it.','Got it.','I''ve got it.','I see.','Understood.','I understand now.','Now I understand.','Okay, I understand.','OK, I understand.','Now I get it.','Now I see.','Oh, I see.','Ah, I see.','Oh, I get it.','OK, got it.','Okay, got it.','Okay, I get it.','OK, I see.','I have understood now.','I do understand.']::text[], 'En français, on dit « j''ai compris » au passé, mais l''anglais dit très souvent I understand, au présent : ce qui compte, c''est que tu comprends maintenant. I see, I get it et Got it sont aussi très courants à l''oral.', 4, '{"id": "en.l58.e09", "unitIds": ["en.v.i_understand", "en.g40.short_answers"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la réponse en anglais.", "prompt": "Comment dit-on : « J''ai compris » ?", "promptLanguage": "fr", "answer": "I understand.", "acceptedAnswers": ["I understand.", "I''ve understood.", "I understood.", "I get it.", "I got it.", "Got it.", "I''ve got it.", "I see.", "Understood.", "I understand now.", "Now I understand.", "Okay, I understand.", "OK, I understand.", "Now I get it.", "Now I see.", "Oh, I see.", "Ah, I see.", "Oh, I get it.", "OK, got it.", "Okay, got it.", "Okay, I get it.", "OK, I see.", "I have understood now.", "I do understand."], "hint": "En anglais, on pense au résultat : tu comprends maintenant.", "explanation": "En français, on dit « j''ai compris » au passé, mais l''anglais dit très souvent I understand, au présent : ce qui compte, c''est que tu comprends maintenant. I see, I get it et Got it sont aussi très courants à l''oral.", "tip": "« J''ai compris » = I understand (présent), pas I have understand.", "extraExample": {"text": "Ah, I see. Thank you for explaining.", "translation": "Ah, j''ai compris. Merci pour l''explication."}, "errorPatterns": [{"contains": "have understand", "category": "conjugation", "feedback": "Avec have, il faut le participe passé (understood), pas la forme de base. Le plus naturel est simplement I understand."}, {"contains": "understanded", "category": "conjugation", "feedback": "Understand est irrégulier : understand – understood – understood. Le plus naturel ici est I understand."}, {"contains": "i am understand", "category": "grammar", "feedback": "Understand est un verbe : on ne l''emploie pas avec be. Dis I understand."}], "pool": "lesson", "lessonId": "en.l58", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l58.e10', 'en', 'en.l58', 'en.g40.short_answers', array['en.g40.short_answers','en.v.never_mind']::text[], 'free_answer', 'lesson', 'Tom dit : « I don''t know the answer. » Réponds-lui que toi non plus, puis ajoute never mind.', array['Me neither. Never mind.','Me neither, never mind.','I don''t either. Never mind.','Neither do I. Never mind.','Never mind, me neither.']::text[], 'Tom dit une phrase négative : pour « moi non plus », on dit Me neither (ou I don''t either, Neither do I). Never mind veut dire « ce n''est pas grave ».', 5, '{"id": "en.l58.e10", "unitIds": ["en.g40.short_answers", "en.v.never_mind"], "type": "free_answer", "difficulty": 5, "instruction": "Réponds en anglais : une réaction courte, puis never mind.", "prompt": "Tom dit : « I don''t know the answer. » Réponds-lui que toi non plus, puis ajoute never mind.", "promptLanguage": "fr", "requirements": {"mustInclude": [["me neither", "neither do i", "don''t either", "do not either", "me either"], ["never mind"]], "minWords": 3}, "answer": "Me neither. Never mind.", "acceptedAnswers": ["Me neither. Never mind.", "Me neither, never mind.", "I don''t either. Never mind.", "Neither do I. Never mind.", "Never mind, me neither."], "hint": "Tom dit une phrase négative : pense à either ou neither.", "explanation": "Tom dit une phrase négative : pour « moi non plus », on dit Me neither (ou I don''t either, Neither do I). Never mind veut dire « ce n''est pas grave ».", "tip": "Phrase négative → Me neither ; Me too est réservé aux phrases affirmatives.", "extraExample": {"text": "I can''t find my keys. — Me neither. Never mind.", "translation": "Je ne trouve pas mes clés. — Moi non plus. Ce n''est pas grave."}, "errorPatterns": [{"contains": "me too", "category": "grammar", "feedback": "Me too veut dire « moi aussi » et répond à une phrase affirmative. Tom dit une phrase négative : Me neither."}, {"contains": "don''t neither", "category": "grammar", "feedback": "Ne mets pas deux négations. Dis I don''t either ou Me neither."}, {"contains": "me not", "category": "grammar", "feedback": "On ne dit pas Me not. « Moi non plus » se dit Me neither."}], "pool": "lesson", "lessonId": "en.l58", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l59.e01', 'en', 'en.l59', 'en.g41.tense_contrast', array['en.g41.tense_contrast']::text[], 'mcq', 'lesson', 'Anna ___ to work every day.', array['walks']::text[], 'Every day indique une habitude : on utilise le présent simple. Avec Anna (she), on ajoute un -s : walks.', 2, '{"id": "en.l59.e01", "unitIds": ["en.g41.tense_contrast"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon temps.", "prompt": "Anna ___ to work every day.", "promptLanguage": "en", "options": ["walks", "is walking", "walked", "has walked"], "answer": "walks", "acceptedAnswers": ["walks"], "hint": "Every day indique une habitude.", "explanation": "Every day indique une habitude : on utilise le présent simple. Avec Anna (she), on ajoute un -s : walks.", "tip": "Habitude (every day, always, usually) = présent simple.", "extraExample": {"text": "Tom drinks coffee every morning.", "translation": "Tom boit du café tous les matins."}, "errorPatterns": [{"equals": "is walking", "category": "verb_tense", "feedback": "Le présent continu parle d''une action en cours (now, at the moment). Every day indique une habitude : présent simple."}, {"equals": "walked", "category": "verb_tense", "feedback": "Walked est un passé : il faudrait un marqueur comme yesterday. Every day indique une habitude : walks."}, {"equals": "has walked", "category": "verb_tense", "feedback": "Le present perfect ne sert pas à décrire une habitude. Every day indique une habitude : présent simple, walks."}], "pool": "lesson", "lessonId": "en.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l59.e02', 'en', 'en.l59', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.memory']::text[], 'mcq', 'lesson', 'Last summer, we ___ many happy memories in Paris.', array['made']::text[], 'Last summer donne un moment précis dans le passé : on utilise le past simple. Make est irrégulier : le past simple est made.', 3, '{"id": "en.l59.e02", "unitIds": ["en.g41.tense_contrast", "en.v.memory"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon temps.", "prompt": "Last summer, we ___ many happy memories in Paris.", "promptLanguage": "en", "options": ["made", "have made", "are making", "make"], "answer": "made", "acceptedAnswers": ["made"], "hint": "Last summer est un moment précis dans le passé.", "explanation": "Last summer donne un moment précis dans le passé : on utilise le past simple. Make est irrégulier : le past simple est made.", "tip": "Last summer, yesterday, ago : past simple.", "extraExample": {"text": "Tom lost his key two days ago.", "translation": "Tom a perdu sa clé il y a deux jours."}, "errorPatterns": [{"equals": "have made", "category": "verb_tense", "feedback": "Avec un moment précis comme last summer, on n''utilise pas le present perfect. Utilise le past simple : made."}, {"equals": "are making", "category": "verb_tense", "feedback": "Are making est le présent continu (action en cours). Last summer est passé : made."}, {"equals": "make", "category": "verb_tense", "feedback": "Make est au présent. Last summer demande le passé : made."}], "pool": "lesson", "lessonId": "en.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l59.e03', 'en', 'en.l59', 'en.g41.tense_contrast', array['en.g41.tense_contrast']::text[], 'match', 'lesson', 'Quel temps choisir selon le marqueur ?', '{}'::text[], 'Le petit mot de temps te guide : every day = habitude, at the moment = action en cours, yesterday = moment précis du passé, ever / never = expérience, next week = futur.', 2, '{"id": "en.l59.e03", "unitIds": ["en.g41.tense_contrast"], "type": "match", "difficulty": 2, "instruction": "Associe chaque marqueur de temps au temps qu''il demande.", "prompt": "Quel temps choisir selon le marqueur ?", "promptLanguage": "fr", "pairs": [{"left": "every day", "right": "présent simple"}, {"left": "at the moment", "right": "présent continu"}, {"left": "yesterday", "right": "past simple"}, {"left": "ever / never", "right": "present perfect"}, {"left": "next week", "right": "futur (will / going to)"}], "answer": "every day = présent simple ; at the moment = présent continu ; yesterday = past simple ; ever / never = present perfect ; next week = futur (will / going to)", "acceptedAnswers": [], "explanation": "Le petit mot de temps te guide : every day = habitude, at the moment = action en cours, yesterday = moment précis du passé, ever / never = expérience, next week = futur.", "tip": "Cherche d''abord le marqueur de temps : il te dit quel temps utiliser.", "extraExample": {"text": "I''m studying English at the moment.", "translation": "J''étudie l''anglais en ce moment."}, "pool": "lesson", "lessonId": "en.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l59.e04', 'en', 'en.l59', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.chance']::text[], 'fill_blank', 'lesson', 'I have a chance to travel next year, so I ___ visit Spain.', array['will','''ll','am going to']::text[], 'Next year parle du futur : on utilise will + verbe de base (ou am going to + verbe de base). Did, have et am tout seuls ne forment pas un futur.', 3, '{"id": "en.l59.e04", "unitIds": ["en.g41.tense_contrast", "en.v.chance"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le futur.", "prompt": "I have a chance to travel next year, so I ___ visit Spain.", "promptLanguage": "en", "options": ["will", "did", "have", "am"], "answer": "will", "acceptedAnswers": ["will", "''ll", "am going to"], "hint": "Next year parle du futur.", "explanation": "Next year parle du futur : on utilise will + verbe de base (ou am going to + verbe de base). Did, have et am tout seuls ne forment pas un futur.", "tip": "Futur (next year, tomorrow, soon) = will ou going to + verbe de base.", "extraExample": {"text": "Tomorrow, I will call the dentist.", "translation": "Demain, j''appellerai le dentiste."}, "errorPatterns": [{"equals": "did", "category": "verb_tense", "feedback": "Did est un passé. Next year parle du futur : will visit."}, {"equals": "have", "category": "verb_tense", "feedback": "Have visit n''existe pas ici. Pour le futur, on dit will visit ou am going to visit."}, {"equals": "am", "category": "verb_tense", "feedback": "Am visit est incorrect. Pour le futur, on dit will visit ou am going to visit."}], "pool": "lesson", "lessonId": "en.l59", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l59.e05', 'en', 'en.l59', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.life']::text[], 'fill_blank', 'lesson', 'In his life, Tom has ___ in three different countries. (live)', array['lived']::text[], 'On parle de toute la vie de Tom (in his life), sans date précise : present perfect. Après has, il faut le participe passé : lived.', 3, '{"id": "en.l59.e05", "unitIds": ["en.g41.tense_contrast", "en.v.life"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la bonne forme du verbe entre parenthèses.", "prompt": "In his life, Tom has ___ in three different countries. (live)", "promptLanguage": "en", "options": ["lived", "live", "lives", "living"], "answer": "lived", "acceptedAnswers": ["lived"], "hint": "Has est suivi du participe passé.", "explanation": "On parle de toute la vie de Tom (in his life), sans date précise : present perfect. Après has, il faut le participe passé : lived.", "tip": "In my life, ever, never : have / has + participe passé.", "extraExample": {"text": "She has never been ill in her life.", "translation": "Elle n''a jamais été malade de sa vie."}, "errorPatterns": [{"equals": "live", "category": "conjugation", "feedback": "Après has, le verbe ne reste pas à la forme de base : il faut le participe passé lived."}, {"equals": "lives", "category": "conjugation", "feedback": "Lives est le présent (3e personne). Après has, il faut le participe passé : lived."}, {"equals": "living", "category": "conjugation", "feedback": "Après has, on n''utilise pas -ing mais le participe passé : lived."}], "pool": "lesson", "lessonId": "en.l59", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l59.e06', 'en', 'en.l59', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.moment']::text[], 'translation', 'lesson', 'Elle regarde un film en ce moment.', array['She is watching a film at the moment.','She is watching a movie at the moment.','At the moment, she is watching a film.','At the moment, she is watching a movie.','She is watching a film right now.','She is watching a movie right now.','She is watching a film now.','She is watching a movie now.']::text[], 'En ce moment indique une action en cours : on utilise le présent continu, is + verbe en -ing. At the moment est le marqueur qui le confirme.', 3, '{"id": "en.l59.e06", "unitIds": ["en.g41.tense_contrast", "en.v.moment"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Elle regarde un film en ce moment.", "promptLanguage": "fr", "answer": "She is watching a film at the moment.", "acceptedAnswers": ["She is watching a film at the moment.", "She is watching a movie at the moment.", "At the moment, she is watching a film.", "At the moment, she is watching a movie.", "She is watching a film right now.", "She is watching a movie right now.", "She is watching a film now.", "She is watching a movie now."], "hint": "En ce moment = une action qui se passe maintenant.", "explanation": "En ce moment indique une action en cours : on utilise le présent continu, is + verbe en -ing. At the moment est le marqueur qui le confirme.", "tip": "At the moment, now, right now : be + verbe en -ing.", "extraExample": {"text": "I''m cooking dinner at the moment.", "translation": "Je prépare le dîner en ce moment."}, "errorPatterns": [{"contains": "she watches", "category": "verb_tense", "feedback": "Le présent simple décrit une habitude. En ce moment = action en cours : she is watching."}, {"contains": "she watching", "category": "grammar", "feedback": "Il manque is avant watching : she is watching."}, {"contains": "has watched", "category": "verb_tense", "feedback": "Le present perfect ne convient pas pour une action en cours. Utilise le présent continu : is watching."}], "pool": "lesson", "lessonId": "en.l59", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l59.e07', 'en', 'en.l59', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.moment']::text[], 'reorder', 'lesson', 'Elle n''a jamais oublié ce moment.', array['She has never forgotten that moment']::text[], 'Never + aucune date précise : present perfect. On place never entre has et le participe passé forgotten (forget – forgot – forgotten).', 3, '{"id": "en.l59.e07", "unitIds": ["en.g41.tense_contrast", "en.v.moment"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Elle n''a jamais oublié ce moment.", "promptLanguage": "fr", "tokens": ["moment", "She", "has", "never", "forgotten", "that"], "answer": "She has never forgotten that moment", "acceptedAnswers": ["She has never forgotten that moment"], "hint": "Never se place entre has et le participe passé.", "explanation": "Never + aucune date précise : present perfect. On place never entre has et le participe passé forgotten (forget – forgot – forgotten).", "tip": "Jamais = have / has + never + participe passé.", "extraExample": {"text": "Tom has never lost his passport.", "translation": "Tom n''a jamais perdu son passeport."}, "pool": "lesson", "lessonId": "en.l59", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l59.e08', 'en', 'en.l59', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.experience']::text[], 'translation', 'lesson', 'Elle a vécu une super expérience l''année dernière.', array['She had a great experience last year.','She had a wonderful experience last year.','She had an amazing experience last year.','She had a fantastic experience last year.','She had a good experience last year.','She had a nice experience last year.','Last year, she had a great experience.','Last year, she had a wonderful experience.','Last year, she had an amazing experience.','Last year, she had a fantastic experience.','Last year, she had a good experience.','Last year, she had a nice experience.']::text[], 'L''année dernière donne un moment précis dans le passé : past simple. En anglais, on dit have an experience (had au passé), et pas live an experience.', 4, '{"id": "en.l59.e08", "unitIds": ["en.g41.tense_contrast", "en.v.experience"], "type": "translation", "difficulty": 4, "instruction": "Traduis en anglais. « super » = great.", "prompt": "Elle a vécu une super expérience l''année dernière.", "promptLanguage": "fr", "answer": "She had a great experience last year.", "acceptedAnswers": ["She had a great experience last year.", "She had a wonderful experience last year.", "She had an amazing experience last year.", "She had a fantastic experience last year.", "She had a good experience last year.", "She had a nice experience last year.", "Last year, she had a great experience.", "Last year, she had a wonderful experience.", "Last year, she had an amazing experience.", "Last year, she had a fantastic experience.", "Last year, she had a good experience.", "Last year, she had a nice experience."], "hint": "Last year est un moment précis ; en anglais, on « a » une expérience.", "explanation": "L''année dernière donne un moment précis dans le passé : past simple. En anglais, on dit have an experience (had au passé), et pas live an experience.", "tip": "Avec last year, yesterday ou ago : past simple, jamais le present perfect.", "extraExample": {"text": "We had a good time last weekend.", "translation": "Nous avons passé un bon moment le week-end dernier."}, "errorPatterns": [{"contains": "has had", "category": "verb_tense", "feedback": "Last year est un moment précis : on utilise le past simple (had), pas le present perfect."}, {"contains": "lived a", "category": "word_confusion", "feedback": "En anglais, on ne « vit » pas une expérience : on a une expérience. Dis she had a great experience."}, {"contains": "she have", "category": "grammar", "feedback": "Avec she, on dit has (présent) ou had (passé). Ici, last year demande had."}], "pool": "lesson", "lessonId": "en.l59", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l59.e09', 'en', 'en.l59', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.g39.present_perfect_intro','en.v.chance']::text[], 'free_answer', 'lesson', 'Comment demander « As-tu déjà eu l''occasion de visiter Londres ? » en anglais ?', array['Have you ever had the chance to visit London?','Have you ever had a chance to visit London?','Have you ever had the chance to go to London?','Have you ever had a chance to go to London?','Have you ever had the opportunity to visit London?','Have you already had the chance to visit London?','Have you already had a chance to visit London?','Have you had the chance to visit London yet?','Have you had a chance to visit London yet?','Have you had the chance to visit London before?','Have you had a chance to visit London before?']::text[], 'On parle d''une expérience sans date précise : present perfect, Have you ever had…? En anglais, « une occasion » se dit a chance (ou an opportunity).', 4, '{"id": "en.l59.e09", "unitIds": ["en.g41.tense_contrast", "en.g39.present_perfect_intro", "en.v.chance"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la question en anglais.", "prompt": "Comment demander « As-tu déjà eu l''occasion de visiter Londres ? » en anglais ?", "promptLanguage": "fr", "answer": "Have you ever had the chance to visit London?", "acceptedAnswers": ["Have you ever had the chance to visit London?", "Have you ever had a chance to visit London?", "Have you ever had the chance to go to London?", "Have you ever had a chance to go to London?", "Have you ever had the opportunity to visit London?", "Have you already had the chance to visit London?", "Have you already had a chance to visit London?", "Have you had the chance to visit London yet?", "Have you had a chance to visit London yet?", "Have you had the chance to visit London before?", "Have you had a chance to visit London before?"], "hint": "Une expérience de vie : Have you ever + participe passé de have.", "explanation": "On parle d''une expérience sans date précise : present perfect, Have you ever had…? En anglais, « une occasion » se dit a chance (ou an opportunity).", "tip": "« Occasion » (de faire quelque chose) se dit chance en anglais.", "extraExample": {"text": "Have you ever had the chance to speak English abroad?", "translation": "As-tu déjà eu l''occasion de parler anglais à l''étranger ?"}, "errorPatterns": [{"contains": "did you ever", "category": "verb_tense", "feedback": "Pour une expérience de vie jusqu''à maintenant, on utilise Have you ever + participe passé : Have you ever had…? Did you ever… parle plutôt d''une période du passé terminée."}, {"contains": "ever have", "category": "conjugation", "feedback": "Après Have you ever, il faut le participe passé : had, pas have."}, {"contains": "the occasion", "category": "word_confusion", "feedback": "En anglais, une occasion de faire quelque chose se dit chance ou opportunity, pas occasion."}], "pool": "lesson", "lessonId": "en.l59", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l59.e10', 'en', 'en.l59', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.g39.present_perfect_intro']::text[], 'free_answer', 'lesson', 'Une phrase avec ever ou never (une expérience de vie), et une phrase avec yesterday, last ou ago (un moment précis du passé).', array['I have never been abroad. I visited London last year.','Anna has never lived abroad. She moved to Paris two years ago.','Have you ever seen this film? I saw it yesterday.']::text[], 'Ever et never demandent le present perfect (have / has + participe passé). Yesterday, last et ago donnent un moment précis : on utilise le past simple.', 5, '{"id": "en.l59.e10", "unitIds": ["en.g41.tense_contrast", "en.g39.present_perfect_intro"], "type": "free_answer", "difficulty": 5, "instruction": "Écris deux phrases en anglais.", "prompt": "Une phrase avec ever ou never (une expérience de vie), et une phrase avec yesterday, last ou ago (un moment précis du passé).", "promptLanguage": "fr", "requirements": {"mustInclude": [["ever", "never"], ["yesterday", "last", "ago"]], "minWords": 8}, "answer": "I have never been abroad. I visited London last year.", "acceptedAnswers": ["I have never been abroad. I visited London last year.", "Anna has never lived abroad. She moved to Paris two years ago.", "Have you ever seen this film? I saw it yesterday."], "hint": "Ever / never : have + participe passé. Yesterday / last / ago : past simple.", "explanation": "Ever et never demandent le present perfect (have / has + participe passé). Yesterday, last et ago donnent un moment précis : on utilise le past simple.", "tip": "Expérience sans date : have + participe passé. Moment précis : past simple.", "extraExample": {"text": "I have never eaten fish. I tried it yesterday.", "translation": "Je n''ai jamais mangé de poisson. Je l''ai goûté hier."}, "errorPatterns": [{"contains": "have visited last", "category": "verb_tense", "feedback": "Avec last year (moment précis), on utilise le past simple : I visited, sans have."}, {"contains": "have seen yesterday", "category": "verb_tense", "feedback": "Avec yesterday, on utilise le past simple : I saw, sans have."}, {"contains": "have went", "category": "conjugation", "feedback": "Went est le past simple. Après have, il faut le participe passé : gone ou been."}], "pool": "lesson", "lessonId": "en.l59", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l60.e01', 'en', 'en.l60', 'en.g41.tense_contrast', array['en.g41.tense_contrast']::text[], 'mcq', 'lesson', 'What is Tom doing today?', array['He is walking in the park.']::text[], 'Le texte dit « today he is walking in the park » : le présent continu (is walking) montre ce qu''il fait aujourd''hui. Yesterday et tomorrow parlent d''un autre jour.', 2, '{"id": "en.l60.e01", "unitIds": ["en.g41.tense_contrast"], "type": "mcq", "difficulty": 2, "instruction": "Lis le texte, puis choisis la bonne réponse.", "context": "Tom is in London for a week. He is staying in a small hotel near the station. Yesterday he visited a museum, and today he is walking in the park. Tomorrow he is going to meet his friend Anna.", "prompt": "What is Tom doing today?", "promptLanguage": "en", "options": ["He is walking in the park.", "He visited a museum.", "He is going to meet Anna.", "He is staying at home."], "answer": "He is walking in the park.", "acceptedAnswers": ["He is walking in the park."], "hint": "Cherche le mot today dans le texte.", "explanation": "Le texte dit « today he is walking in the park » : le présent continu (is walking) montre ce qu''il fait aujourd''hui. Yesterday et tomorrow parlent d''un autre jour.", "tip": "Repère le temps du verbe : is walking = maintenant, visited = hier, is going to = demain.", "extraExample": {"text": "At the moment, Anna is reading a report.", "translation": "En ce moment, Anna lit un rapport."}, "errorPatterns": [{"equals": "he visited a museum", "category": "verb_tense", "feedback": "Visited est un passé : c''est ce que Tom a fait yesterday, pas today."}, {"equals": "he is going to meet anna", "category": "verb_tense", "feedback": "Is going to parle du futur : c''est prévu pour tomorrow, pas pour today."}, {"equals": "he is staying at home", "category": "instruction", "feedback": "Relis le texte : Tom n''est pas à la maison, il marche dans le parc aujourd''hui."}], "pool": "lesson", "lessonId": "en.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l60.e02', 'en', 'en.l60', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.believe']::text[], 'mcq', 'lesson', 'Which sentence about Ben is true?', array['He has lived in three countries.']::text[], 'Le texte dit « Ben has lived in three countries » : present perfect, une expérience de vie. Il a rendu visite à Anna last year (past simple), pas last week.', 3, '{"id": "en.l60.e02", "unitIds": ["en.g41.tense_contrast", "en.v.believe"], "type": "mcq", "difficulty": 3, "instruction": "Lis le texte, puis choisis la phrase vraie.", "context": "Anna has never been abroad. Her brother Ben has lived in three countries. Last year he visited her in London. Now Anna believes that living abroad is a great experience.", "prompt": "Which sentence about Ben is true?", "promptLanguage": "en", "options": ["He has lived in three countries.", "He has never been abroad.", "He visited Anna last week.", "He is Anna''s father."], "answer": "He has lived in three countries.", "acceptedAnswers": ["He has lived in three countries."], "hint": "Fais attention aux marqueurs de temps : never, last year…", "explanation": "Le texte dit « Ben has lived in three countries » : present perfect, une expérience de vie. Il a rendu visite à Anna last year (past simple), pas last week.", "tip": "Present perfect = expérience sans date ; past simple + last year = moment précis.", "extraExample": {"text": "My sister has visited many museums.", "translation": "Ma sœur a visité beaucoup de musées."}, "errorPatterns": [{"equals": "he has never been abroad", "category": "instruction", "feedback": "Never been abroad concerne Anna, pas Ben. Ben has lived in three countries."}, {"equals": "he visited anna last week", "category": "instruction", "feedback": "Le texte dit last year, pas last week."}, {"equals": "he is anna''s father", "category": "vocabulary", "feedback": "Ben est le frère d''Anna (her brother), pas son père."}], "pool": "lesson", "lessonId": "en.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l60.e03', 'en', 'en.l60', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.describe','en.v.explain','en.v.believe','en.v.agree','en.v.opinion']::text[], 'match', 'lesson', 'Les mots pour exprimer son avis', '{}'::text[], 'Describe, explain, believe et agree sont des verbes : on dit I agree (pas I am agree). Opinion est un nom : in my opinion = à mon avis.', 2, '{"id": "en.l60.e03", "unitIds": ["en.g41.tense_contrast", "en.v.describe", "en.v.explain", "en.v.believe", "en.v.agree", "en.v.opinion"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot anglais à sa traduction.", "prompt": "Les mots pour exprimer son avis", "promptLanguage": "fr", "pairs": [{"left": "describe", "right": "décrire"}, {"left": "explain", "right": "expliquer"}, {"left": "believe", "right": "croire"}, {"left": "agree", "right": "être d''accord"}, {"left": "opinion", "right": "avis"}], "answer": "describe = décrire ; explain = expliquer ; believe = croire ; agree = être d''accord ; opinion = avis", "acceptedAnswers": [], "explanation": "Describe, explain, believe et agree sont des verbes : on dit I agree (pas I am agree). Opinion est un nom : in my opinion = à mon avis.", "tip": "En anglais, agree est déjà un verbe : I agree, jamais I am agree.", "extraExample": {"text": "In my opinion, this film is great.", "translation": "À mon avis, ce film est super."}, "pool": "lesson", "lessonId": "en.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l60.e04', 'en', 'en.l60', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.describe']::text[], 'fill_blank', 'lesson', 'Yesterday, Tom ___ his new apartment to me. (describe)', array['described']::text[], 'Yesterday est un moment précis : on utilise le past simple. Describe est régulier et finit par -e : on ajoute seulement -d, d''où described.', 3, '{"id": "en.l60.e04", "unitIds": ["en.g41.tense_contrast", "en.v.describe"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la bonne forme du verbe entre parenthèses.", "prompt": "Yesterday, Tom ___ his new apartment to me. (describe)", "promptLanguage": "en", "options": ["described", "describes", "describing", "describe"], "answer": "described", "acceptedAnswers": ["described"], "hint": "Yesterday est un moment précis du passé.", "explanation": "Yesterday est un moment précis : on utilise le past simple. Describe est régulier et finit par -e : on ajoute seulement -d, d''où described.", "tip": "Yesterday + verbe régulier : base + -ed (juste -d si le verbe finit par e).", "extraExample": {"text": "Tom closed the window yesterday.", "translation": "Tom a fermé la fenêtre hier."}, "errorPatterns": [{"equals": "describes", "category": "verb_tense", "feedback": "Describes est le présent (3e personne). Yesterday demande le passé : described."}, {"equals": "describing", "category": "verb_tense", "feedback": "Describing est la forme en -ing. Avec yesterday, il faut le past simple : described."}, {"equals": "describe", "category": "verb_tense", "feedback": "Describe est la forme de base. Avec yesterday, il faut le past simple : described."}], "pool": "lesson", "lessonId": "en.l60", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l60.e05', 'en', 'en.l60', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.explain']::text[], 'fill_blank', 'lesson', 'Right now, the teacher ___ the rule. (explain)', array['is explaining']::text[], 'Right now indique une action qui se passe maintenant : on utilise le présent continu, is + explaining.', 3, '{"id": "en.l60.e05", "unitIds": ["en.g41.tense_contrast", "en.v.explain"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la bonne forme du verbe explain.", "prompt": "Right now, the teacher ___ the rule. (explain)", "promptLanguage": "en", "options": ["is explaining", "explains", "explained", "has explained"], "answer": "is explaining", "acceptedAnswers": ["is explaining"], "hint": "Right now indique une action en cours.", "explanation": "Right now indique une action qui se passe maintenant : on utilise le présent continu, is + explaining.", "tip": "Right now, now, at the moment : be + verbe en -ing.", "extraExample": {"text": "Look! Tom is carrying a big bag.", "translation": "Regarde ! Tom porte un gros sac."}, "errorPatterns": [{"equals": "explains", "category": "verb_tense", "feedback": "Le présent simple décrit une habitude. Right now parle d''une action en cours : is explaining."}, {"equals": "explained", "category": "verb_tense", "feedback": "Explained est un passé. Right now parle d''une action en cours : is explaining."}, {"equals": "has explained", "category": "verb_tense", "feedback": "Le present perfect ne convient pas à une action en cours. Utilise le présent continu : is explaining."}], "pool": "lesson", "lessonId": "en.l60", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l60.e06', 'en', 'en.l60', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.believe']::text[], 'translation', 'lesson', 'Je crois qu''Anna va aimer son nouveau travail.', array['I believe Anna will like her new job.','I believe that Anna will like her new job.','I believe Anna is going to like her new job.','I believe that Anna is going to like her new job.','I think Anna will like her new job.','I think that Anna will like her new job.','I think Anna is going to like her new job.','I think that Anna is going to like her new job.']::text[], 'Je crois se dit I believe (ou I think) : believe est un verbe, donc pas de be. Le travail n''a pas encore commencé : on utilise le futur, will like ou is going to like.', 3, '{"id": "en.l60.e06", "unitIds": ["en.g41.tense_contrast", "en.v.believe"], "type": "translation", "difficulty": 3, "instruction": "Lis le texte, puis traduis en anglais. « aimer » = like.", "context": "Anna has a new job in Paris. She starts next week. She doesn''t know many people there, but she is very happy.", "prompt": "Je crois qu''Anna va aimer son nouveau travail.", "promptLanguage": "fr", "answer": "I believe Anna will like her new job.", "acceptedAnswers": ["I believe Anna will like her new job.", "I believe that Anna will like her new job.", "I believe Anna is going to like her new job.", "I believe that Anna is going to like her new job.", "I think Anna will like her new job.", "I think that Anna will like her new job.", "I think Anna is going to like her new job.", "I think that Anna is going to like her new job."], "hint": "« Je crois que » se dit I believe (ou I think). Le futur : will ou going to.", "explanation": "Je crois se dit I believe (ou I think) : believe est un verbe, donc pas de be. Le travail n''a pas encore commencé : on utilise le futur, will like ou is going to like.", "tip": "I believe / I think + sujet + will + verbe de base.", "extraExample": {"text": "I believe Tom will win the game.", "translation": "Je crois que Tom va gagner le match."}, "errorPatterns": [{"contains": "i''m believe", "category": "grammar", "feedback": "Believe est un verbe : on ne l''emploie pas avec be. Dis I believe."}, {"contains": "will likes", "category": "conjugation", "feedback": "Après will, le verbe reste à la forme de base : will like, sans -s."}, {"contains": "will to", "category": "grammar", "feedback": "Après will, on ne met pas to : will like."}], "pool": "lesson", "lessonId": "en.l60", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l60.e07', 'en', 'en.l60', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.explain']::text[], 'reorder', 'lesson', 'Hier, le professeur nous a expliqué la règle.', array['Yesterday the teacher explained the rule to us','The teacher explained the rule to us yesterday']::text[], 'Yesterday est un moment précis : past simple (explained). On dit explain something to someone : explained the rule to us. Yesterday peut se placer au début ou à la fin.', 3, '{"id": "en.l60.e07", "unitIds": ["en.g41.tense_contrast", "en.v.explain"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Hier, le professeur nous a expliqué la règle.", "promptLanguage": "fr", "tokens": ["the", "explained", "Yesterday", "rule", "teacher", "us", "the", "to"], "answer": "Yesterday the teacher explained the rule to us", "acceptedAnswers": ["Yesterday the teacher explained the rule to us", "The teacher explained the rule to us yesterday"], "hint": "Hier = yesterday, donc past simple : explained.", "explanation": "Yesterday est un moment précis : past simple (explained). On dit explain something to someone : explained the rule to us. Yesterday peut se placer au début ou à la fin.", "tip": "Explain + quelque chose + to + quelqu''un.", "extraExample": {"text": "Anna explained the problem to her boss.", "translation": "Anna a expliqué le problème à son patron."}, "pool": "lesson", "lessonId": "en.l60", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l60.e08', 'en', 'en.l60', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.v.agree','en.v.opinion']::text[], 'translation', 'lesson', 'Anna didn''t agree with Tom.', array['Anna n''était pas d''accord avec Tom.','Anna n''etait pas d''accord avec Tom.','Anna n''a pas été d''accord avec Tom.','Anna n''était pas du même avis que Tom.','Anna n''était pas de l''avis de Tom.']::text[], 'Didn''t agree est au past simple négatif : « n''était pas d''accord ». Le texte parle d''une soirée passée (last night), donc la phrase est au passé.', 4, '{"id": "en.l60.e08", "unitIds": ["en.g41.tense_contrast", "en.v.agree", "en.v.opinion"], "type": "translation", "difficulty": 4, "instruction": "Lis le texte, puis traduis la phrase en français.", "context": "Tom and Anna saw a film last night. Tom loved it, but Anna thought it was too long. They have different opinions about the film.", "prompt": "Anna didn''t agree with Tom.", "promptLanguage": "en", "answer": "Anna n''était pas d''accord avec Tom.", "acceptedAnswers": ["Anna n''était pas d''accord avec Tom.", "Anna n''etait pas d''accord avec Tom.", "Anna n''a pas été d''accord avec Tom.", "Anna n''était pas du même avis que Tom.", "Anna n''était pas de l''avis de Tom."], "hint": "Didn''t est un passé négatif.", "explanation": "Didn''t agree est au past simple négatif : « n''était pas d''accord ». Le texte parle d''une soirée passée (last night), donc la phrase est au passé.", "tip": "Didn''t + verbe de base = passé négatif.", "extraExample": {"text": "Sam didn''t agree with the teacher.", "translation": "Sam n''était pas d''accord avec le professeur."}, "errorPatterns": [{"contains": "était d''accord", "category": "grammar", "feedback": "Attention à la négation : didn''t agree veut dire « n''était pas d''accord »."}, {"contains": "n''est pas d''accord", "category": "verb_tense", "feedback": "Didn''t agree est au passé : « n''était pas d''accord »."}, {"contains": "est d''accord", "category": "grammar", "feedback": "Attention à la négation : didn''t agree veut dire « n''était pas d''accord »."}], "pool": "lesson", "lessonId": "en.l60", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l60.e09', 'en', 'en.l60', 'en.v.agree', array['en.v.agree','en.g41.tense_contrast']::text[], 'free_answer', 'lesson', 'Comment dit-on « Je suis d''accord » en anglais ?', array['I agree.','I agree with you.','I agree with that.','I totally agree.','I completely agree.','I do agree.','Agreed.']::text[], 'En anglais, agree est un verbe : « je suis d''accord » se dit I agree. On ne dit pas I am agree, car agree n''est pas un adjectif.', 3, '{"id": "en.l60.e09", "unitIds": ["en.v.agree", "en.g41.tense_contrast"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Je suis d''accord » en anglais ?", "promptLanguage": "fr", "answer": "I agree.", "acceptedAnswers": ["I agree.", "I agree with you.", "I agree with that.", "I totally agree.", "I completely agree.", "I do agree.", "Agreed."], "hint": "Agree est déjà un verbe : pas besoin de be.", "explanation": "En anglais, agree est un verbe : « je suis d''accord » se dit I agree. On ne dit pas I am agree, car agree n''est pas un adjectif.", "tip": "« Être d''accord » = agree, sans be : I agree.", "extraExample": {"text": "Tom doesn''t agree with Anna.", "translation": "Tom n''est pas d''accord avec Anna."}, "errorPatterns": [{"contains": "i''m agree", "category": "grammar", "feedback": "Agree est un verbe : on ne dit pas I am agree. Dis simplement I agree."}, {"contains": "i am agree", "category": "grammar", "feedback": "Agree est un verbe : on ne dit pas I am agree. Dis simplement I agree."}, {"contains": "i agreed", "category": "verb_tense", "feedback": "Agreed est un passé. Pour dire « je suis d''accord » maintenant, on utilise le présent : I agree."}], "pool": "lesson", "lessonId": "en.l60", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.l60.e10', 'en', 'en.l60', 'en.g41.tense_contrast', array['en.g41.tense_contrast','en.g39.present_perfect_intro','en.v.describe']::text[], 'free_answer', 'lesson', 'Écris trois phrases sur toi, comme Lucy : ce que tu as fait hier ou le week-end dernier, un endroit où tu es déjà allé (ou jamais allé), et ce que tu vas faire bientôt.', array['Last weekend I visited my parents. I have never been abroad. Next year I am going to travel to Spain.','Yesterday I watched a film. I have been to London twice. Tomorrow I will call my brother.','Two days ago I met a friend. I have never been to a museum in Paris. Next week I am going to visit the park.']::text[], 'Chaque phrase demande son temps : un moment précis du passé (last weekend, yesterday) = past simple ; une expérience sans date = present perfect ; un projet = going to ou will.', 5, '{"id": "en.l60.e10", "unitIds": ["en.g41.tense_contrast", "en.g39.present_perfect_intro", "en.v.describe"], "type": "free_answer", "difficulty": 5, "instruction": "Lis le texte, puis écris en anglais.", "context": "Lucy lives in Paris and works in a museum. Last weekend, she visited her brother in London. She has never been to Spain, but she is going to travel there next summer.", "prompt": "Écris trois phrases sur toi, comme Lucy : ce que tu as fait hier ou le week-end dernier, un endroit où tu es déjà allé (ou jamais allé), et ce que tu vas faire bientôt.", "promptLanguage": "fr", "requirements": {"mustInclude": [["yesterday", "last", "ago"], ["have", "has", "''ve"], ["going to", "will", "''ll", "next", "tomorrow", "soon"]], "minWords": 12}, "answer": "Last weekend I visited my parents. I have never been abroad. Next year I am going to travel to Spain.", "acceptedAnswers": ["Last weekend I visited my parents. I have never been abroad. Next year I am going to travel to Spain.", "Yesterday I watched a film. I have been to London twice. Tomorrow I will call my brother.", "Two days ago I met a friend. I have never been to a museum in Paris. Next week I am going to visit the park."], "hint": "Passé daté : past simple. Expérience : have / has + participe passé. Futur : will ou going to.", "explanation": "Chaque phrase demande son temps : un moment précis du passé (last weekend, yesterday) = past simple ; une expérience sans date = present perfect ; un projet = going to ou will.", "tip": "Marqueur de temps d''abord, temps ensuite : last weekend → past simple, never → have + participe, next year → going to.", "extraExample": {"text": "Last Friday I cooked dinner. I have never been to Spain. Next month I''m going to learn French.", "translation": "Vendredi dernier j''ai préparé le dîner. Je ne suis jamais allé en Espagne. Le mois prochain, je vais apprendre le français."}, "errorPatterns": [{"contains": "have went", "category": "conjugation", "feedback": "Went est le past simple. Après have, il faut le participe passé : gone ou been."}, {"contains": "have visited last", "category": "verb_tense", "feedback": "Avec un moment précis (last weekend, last year), on utilise le past simple : I visited, sans have."}, {"contains": "will to", "category": "grammar", "feedback": "Après will, on ne met pas to : will call, will go."}], "pool": "lesson", "lessonId": "en.l60", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m01.01', 'en', null, 'en.g01.subject_pronouns', array['en.g01.subject_pronouns']::text[], 'mcq', 'diagnostic', 'Tom is a man. ___ is a teacher.', array['He']::text[], 'Tom est un homme : on le remplace par he. She est pour une femme et it pour une chose ou un animal.', 1, '{"id": "en.diag.m01.01", "unitIds": ["en.g01.subject_pronouns"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon pronom.", "prompt": "Tom is a man. ___ is a teacher.", "promptLanguage": "en", "options": ["He", "She", "It"], "answer": "He", "acceptedAnswers": ["He"], "explanation": "Tom est un homme : on le remplace par he. She est pour une femme et it pour une chose ou un animal.", "tip": "Homme : he. Femme : she. Chose ou animal : it.", "extraExample": {"text": "Anna is a woman. She is a student.", "translation": "Anna est une femme. Elle est étudiante."}, "errorPatterns": [{"equals": "she", "category": "grammar", "feedback": "She remplace une femme. Tom est un homme : he."}, {"equals": "it", "category": "grammar", "feedback": "It remplace une chose ou un animal, pas une personne. Pour Tom, on dit he."}], "level": 0, "topic": "pronouns", "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m01.02', 'en', null, 'en.g03.be_affirmative', array['en.g03.be_affirmative']::text[], 'fill_blank', 'diagnostic', 'They ___ at home.', array['are']::text[], 'Avec they (ils, elles), le verbe être se dit are : they are at home.', 1, '{"id": "en.diag.m01.02", "unitIds": ["en.g03.be_affirmative"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète avec la bonne forme du verbe être.", "prompt": "They ___ at home.", "promptLanguage": "en", "options": ["are", "is", "am"], "answer": "are", "acceptedAnswers": ["are"], "explanation": "Avec they (ils, elles), le verbe être se dit are : they are at home.", "tip": "You, we, they : are.", "extraExample": {"text": "We are happy.", "translation": "Nous sommes heureux."}, "errorPatterns": [{"equals": "is", "category": "conjugation", "feedback": "Is va avec he, she et it. Avec they, on dit are."}, {"equals": "am", "category": "conjugation", "feedback": "Am va uniquement avec I. Avec they, on dit are."}], "level": 0, "topic": "verbs", "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m01.03', 'en', null, 'en.g02.articles', array['en.g02.articles']::text[], 'mcq', 'diagnostic', 'Comment dit-on « une heure » en anglais ?', array['an hour']::text[], 'Le h de hour ne se prononce pas : le mot commence par un son de voyelle. Devant un son de voyelle, « un, une » se dit an : an hour.', 2, '{"id": "en.diag.m01.03", "unitIds": ["en.g02.articles"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « une heure » en anglais ?", "promptLanguage": "fr", "options": ["an hour", "a hour", "the hour"], "answer": "an hour", "acceptedAnswers": ["an hour"], "explanation": "Le h de hour ne se prononce pas : le mot commence par un son de voyelle. Devant un son de voyelle, « un, une » se dit an : an hour.", "tip": "On choisit a ou an selon le son, pas selon la lettre.", "extraExample": {"text": "an idea", "translation": "une idée"}, "errorPatterns": [{"equals": "a hour", "category": "grammar", "feedback": "Le h de hour est muet : on entend un son de voyelle. On dit an hour."}, {"equals": "the hour", "category": "grammar", "feedback": "The veut dire « l'', le, la ». Pour « une heure », on dit an hour."}], "level": 0, "topic": "construction", "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m01.04', 'en', null, 'en.g05.have_has', array['en.g05.have_has']::text[], 'fill_blank', 'diagnostic', 'Anna ___ a dog.', array['has']::text[], 'Anna, c''est « elle » : she. Avec he, she et it, have devient has : Anna has a dog.', 1, '{"id": "en.diag.m01.04", "unitIds": ["en.g05.have_has"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Anna ___ a dog.", "promptLanguage": "en", "options": ["has", "have", "is"], "answer": "has", "acceptedAnswers": ["has"], "explanation": "Anna, c''est « elle » : she. Avec he, she et it, have devient has : Anna has a dog.", "tip": "He, she, it : has.", "extraExample": {"text": "Tom has a car.", "translation": "Tom a une voiture."}, "errorPatterns": [{"equals": "have", "category": "conjugation", "feedback": "Anna est une seule personne (she) : have devient has."}, {"equals": "is", "category": "grammar", "feedback": "Is veut dire « est ». Pour posséder un chien, on utilise has."}], "level": 0, "topic": "verbs", "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m01.05', 'en', null, 'en.g04.be_negative_questions', array['en.g04.be_negative_questions','en.g06.possessive_adjectives','en.g07.plural_nouns']::text[], 'reorder', 'diagnostic', 'Mes sœurs ne sont pas en retard.', array['My sisters are not late']::text[], 'Le possessif My se place devant le nom pluriel sisters. Le verbe are est suivi de not pour la négation, puis de late.', 2, '{"id": "en.diag.m01.05", "unitIds": ["en.g04.be_negative_questions", "en.g06.possessive_adjectives", "en.g07.plural_nouns"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former une phrase.", "prompt": "Mes sœurs ne sont pas en retard.", "promptLanguage": "fr", "tokens": ["late", "My", "sisters", "not", "are"], "answer": "My sisters are not late", "acceptedAnswers": ["My sisters are not late"], "explanation": "Le possessif My se place devant le nom pluriel sisters. Le verbe are est suivi de not pour la négation, puis de late.", "tip": "Sujet + are + not + adjectif.", "extraExample": {"text": "Our friends are not ready.", "translation": "Nos amis ne sont pas prêts."}, "level": 0, "topic": "construction", "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m02.01', 'en', null, 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.live']::text[], 'mcq', 'diagnostic', 'Tom and I ___ in London.', array['live']::text[], 'Tom and I, c''est « nous » : le verbe garde sa forme de base, sans -s. On dit donc live.', 1, '{"id": "en.diag.m02.01", "unitIds": ["en.g08.verbs_base_form", "en.v.live"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Tom and I ___ in London.", "promptLanguage": "en", "options": ["live", "lives", "are live", "living"], "answer": "live", "acceptedAnswers": ["live"], "explanation": "Tom and I, c''est « nous » : le verbe garde sa forme de base, sans -s. On dit donc live.", "tip": "Avec I, you, we, they : le verbe ne change pas.", "extraExample": {"text": "My sister and I live in Paris.", "translation": "Ma sœur et moi habitons à Paris."}, "errorPatterns": [{"equals": "lives", "category": "conjugation", "feedback": "Tom and I, c''est comme we : le verbe ne prend pas de -s."}, {"equals": "are live", "category": "grammar", "feedback": "Are est le verbe être : on ne le met pas devant un autre verbe."}, {"equals": "living", "category": "grammar", "feedback": "Pour dire où on habite, on utilise la forme de base : we live."}], "level": 1, "topic": "verbs", "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m02.02', 'en', null, 'en.g09.do_vs_make', array['en.g09.do_vs_make','en.v.make','en.v.dinner']::text[], 'mcq', 'diagnostic', 'My mother and I ___ dinner at home.', array['make']::text[], 'On prépare le dîner : on crée un repas, donc make dinner. My mother and I, c''est « nous » : pas de -s.', 2, '{"id": "en.diag.m02.02", "unitIds": ["en.g09.do_vs_make", "en.v.make", "en.v.dinner"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon verbe.", "prompt": "My mother and I ___ dinner at home.", "promptLanguage": "en", "options": ["make", "do", "makes", "does"], "answer": "make", "acceptedAnswers": ["make"], "explanation": "On prépare le dîner : on crée un repas, donc make dinner. My mother and I, c''est « nous » : pas de -s.", "tip": "Un repas qu''on prépare : make dinner, jamais do dinner.", "extraExample": {"text": "We make coffee for our friends.", "translation": "Nous faisons du café pour nos amis."}, "errorPatterns": [{"equals": "do", "category": "word_confusion", "feedback": "Do sert aux tâches (do homework). Pour préparer un repas, on dit make dinner."}, {"equals": "makes", "category": "conjugation", "feedback": "My mother and I, c''est comme we : le verbe ne prend pas de -s."}, {"equals": "does", "category": "word_confusion", "feedback": "Pour préparer un repas, on dit make dinner, et le verbe ne prend pas de -s ici."}], "level": 1, "topic": "verbs", "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m02.03', 'en', null, 'en.g10.want_need_to', array['en.g10.want_need_to','en.v.need']::text[], 'fill_blank', 'diagnostic', 'I need ___ do my homework.', array['to']::text[], 'Quand need est suivi d''un verbe, on ajoute to : need to + verbe de base.', 2, '{"id": "en.diag.m02.03", "unitIds": ["en.g10.want_need_to", "en.v.need"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le mot qui manque.", "prompt": "I need ___ do my homework.", "promptLanguage": "en", "options": ["to", "that", "for", "of"], "answer": "to", "acceptedAnswers": ["to"], "explanation": "Quand need est suivi d''un verbe, on ajoute to : need to + verbe de base.", "tip": "Want / need + to + verbe.", "extraExample": {"text": "We want to eat dinner at home.", "translation": "Nous voulons dîner à la maison."}, "errorPatterns": [{"equals": "that", "category": "grammar", "feedback": "On ne dit pas « need that » avant un verbe. On dit need to + verbe."}, {"equals": "for", "category": "preposition", "feedback": "For ne s''emploie pas entre need et un verbe. Il faut to."}, {"equals": "of", "category": "preposition", "feedback": "Of ne s''emploie pas entre need et un verbe. Il faut to."}], "level": 1, "topic": "verbs", "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m02.04', 'en', null, 'en.g11.can', array['en.g11.can','en.v.drive']::text[], 'mcq', 'diagnostic', 'Comment dit-on « Je ne sais pas conduire » en anglais ?', array['I can''t drive.']::text[], 'Pour dire qu''on ne sait pas faire quelque chose, on utilise can''t + verbe de base. On n''ajoute pas to, et la négation se place sur can.', 2, '{"id": "en.diag.m02.04", "unitIds": ["en.g11.can", "en.v.drive"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « Je ne sais pas conduire » en anglais ?", "promptLanguage": "fr", "options": ["I can''t drive.", "I can drive not.", "I can''t to drive.", "I am can''t drive."], "answer": "I can''t drive.", "acceptedAnswers": ["I can''t drive."], "explanation": "Pour dire qu''on ne sait pas faire quelque chose, on utilise can''t + verbe de base. On n''ajoute pas to, et la négation se place sur can.", "tip": "Can''t + verbe de base, sans to.", "extraExample": {"text": "My brother can''t swim.", "translation": "Mon frère ne sait pas nager."}, "errorPatterns": [{"equals": "i can drive not.", "category": "word_order", "feedback": "La négation se place sur can : can''t, puis le verbe."}, {"equals": "i can''t to drive.", "category": "grammar", "feedback": "Après can''t, on n''ajoute pas to."}, {"equals": "i am can''t drive.", "category": "grammar", "feedback": "Can''t est déjà le verbe : on n''ajoute pas am."}], "level": 1, "topic": "verbs", "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m02.05', 'en', null, 'en.g13.imperative', array['en.g13.imperative','en.v.take']::text[], 'reorder', 'diagnostic', 'Ne prends pas mon téléphone !', array['Don''t take my phone']::text[], 'Pour interdire, on met Don''t devant le verbe de base : Don''t take. Il n''y a pas de sujet dans un ordre.', 2, '{"id": "en.diag.m02.05", "unitIds": ["en.g13.imperative", "en.v.take"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Ne prends pas mon téléphone !", "promptLanguage": "fr", "tokens": ["phone", "Don''t", "my", "take"], "answer": "Don''t take my phone", "acceptedAnswers": ["Don''t take my phone"], "explanation": "Pour interdire, on met Don''t devant le verbe de base : Don''t take. Il n''y a pas de sujet dans un ordre.", "tip": "Un ordre négatif : Don''t + verbe de base.", "extraExample": {"text": "Don''t give the key to Tom.", "translation": "Ne donne pas la clé à Tom."}, "level": 1, "topic": "construction", "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m03.01', 'en', null, 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person']::text[], 'mcq', 'diagnostic', 'My son ___ milk every morning.', array['drinks']::text[], 'My son = he. Au présent simple, le verbe prend -s avec he, she, it : my son drinks.', 2, '{"id": "en.diag.m03.01", "unitIds": ["en.g14.present_simple_third_person"], "type": "mcq", "difficulty": 2, "level": 2, "topic": "present", "instruction": "Choisis la bonne forme du verbe.", "prompt": "My son ___ milk every morning.", "promptLanguage": "en", "options": ["drinks", "drink", "drinking"], "answer": "drinks", "acceptedAnswers": ["drinks"], "explanation": "My son = he. Au présent simple, le verbe prend -s avec he, she, it : my son drinks.", "tip": "He, she, it : le verbe prend -s.", "extraExample": {"text": "Anna plays with her dog.", "translation": "Anna joue avec son chien."}, "errorPatterns": [{"equals": "drink", "category": "conjugation", "feedback": "My son = he : le verbe prend -s au présent simple. On dit my son drinks."}, {"equals": "drinking", "category": "grammar", "feedback": "Le verbe en -ing a besoin de be (is drinking). Pour une habitude (every morning), on utilise le présent simple : drinks."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m03.02', 'en', null, 'en.g15.present_simple_negative', array['en.g15.present_simple_negative']::text[], 'fill_blank', 'diagnostic', 'My dog ___ eat fish.', array['doesn''t']::text[], 'My dog = it. Avec he, she, it, la négation du présent simple se fait avec doesn''t + verbe de base.', 2, '{"id": "en.diag.m03.02", "unitIds": ["en.g15.present_simple_negative"], "type": "fill_blank", "difficulty": 2, "level": 2, "topic": "verbs", "instruction": "Complète la phrase.", "prompt": "My dog ___ eat fish.", "promptLanguage": "en", "options": ["doesn''t", "don''t", "isn''t"], "answer": "doesn''t", "acceptedAnswers": ["doesn''t"], "explanation": "My dog = it. Avec he, she, it, la négation du présent simple se fait avec doesn''t + verbe de base.", "tip": "I, you, we, they : don''t. He, she, it : doesn''t.", "extraExample": {"text": "She doesn''t drink coffee.", "translation": "Elle ne boit pas de café."}, "errorPatterns": [{"equals": "don''t", "category": "conjugation", "feedback": "Don''t s''emploie avec I, you, we, they. Avec my dog (= it), on dit doesn''t."}, {"equals": "isn''t", "category": "grammar", "feedback": "Isn''t s''emploie avec be ou avec un verbe en -ing. Avec le verbe eat, on utilise doesn''t."}], "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m03.03', 'en', null, 'en.g16.present_simple_questions', array['en.g16.present_simple_questions']::text[], 'mcq', 'diagnostic', 'Comment dit-on « Est-ce que ton frère joue de la musique ? »', array['Does your brother play music?']::text[], 'Ton frère = he, donc la question commence par Does. Après Does, le verbe reste à sa forme de base : play, sans -s.', 2, '{"id": "en.diag.m03.03", "unitIds": ["en.g16.present_simple_questions"], "type": "mcq", "difficulty": 2, "level": 2, "topic": "construction", "instruction": "Choisis la question correcte.", "prompt": "Comment dit-on « Est-ce que ton frère joue de la musique ? »", "promptLanguage": "fr", "options": ["Does your brother play music?", "Do your brother play music?", "Does your brother plays music?", "Is your brother play music?"], "answer": "Does your brother play music?", "acceptedAnswers": ["Does your brother play music?"], "explanation": "Ton frère = he, donc la question commence par Does. Après Does, le verbe reste à sa forme de base : play, sans -s.", "tip": "Does + sujet + verbe de base : le -s est déjà dans Does.", "extraExample": {"text": "Does she work in London?", "translation": "Est-ce qu''elle travaille à Londres ?"}, "errorPatterns": [{"equals": "Do your brother play music?", "category": "conjugation", "feedback": "Your brother = he : la question commence par Does, pas par Do."}, {"equals": "Does your brother plays music?", "category": "conjugation", "feedback": "Après Does, le verbe reste à sa forme de base : play."}, {"equals": "Is your brother play music?", "category": "grammar", "feedback": "Is s''emploie avec to be. Avec play, on pose la question avec Does."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m03.04', 'en', null, 'en.g17.frequency_adverbs', array['en.g17.frequency_adverbs']::text[], 'reorder', 'diagnostic', 'Ma sœur est toujours en retard.', array['My sister is always late']::text[], 'Avec le verbe be, l''adverbe de fréquence se place après be : my sister is always late.', 2, '{"id": "en.diag.m03.04", "unitIds": ["en.g17.frequency_adverbs"], "type": "reorder", "difficulty": 2, "level": 2, "topic": "construction", "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Ma sœur est toujours en retard.", "promptLanguage": "fr", "tokens": ["late", "always", "My", "is", "sister"], "answer": "My sister is always late", "acceptedAnswers": ["My sister is always late"], "explanation": "Avec le verbe be, l''adverbe de fréquence se place après be : my sister is always late.", "tip": "Après be, avant les autres verbes.", "extraExample": {"text": "My parents are never late.", "translation": "Mes parents ne sont jamais en retard."}, "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m03.05', 'en', null, 'en.g18.present_continuous', array['en.g18.present_continuous','en.g19.simple_vs_continuous']::text[], 'mcq', 'diagnostic', 'Lucy and Ben ___ TV now.', array['are watching']::text[], 'Now indique que l''action se passe en ce moment : on utilise le présent continu, be + verbe en -ing. Lucy and Ben = they, donc are watching.', 3, '{"id": "en.diag.m03.05", "unitIds": ["en.g18.present_continuous", "en.g19.simple_vs_continuous"], "type": "mcq", "difficulty": 3, "level": 2, "topic": "present", "instruction": "Choisis la bonne forme.", "prompt": "Lucy and Ben ___ TV now.", "promptLanguage": "en", "options": ["are watching", "watch", "watches"], "answer": "are watching", "acceptedAnswers": ["are watching"], "explanation": "Now indique que l''action se passe en ce moment : on utilise le présent continu, be + verbe en -ing. Lucy and Ben = they, donc are watching.", "tip": "Maintenant, en ce moment : be + -ing.", "extraExample": {"text": "My sister is talking on the phone now.", "translation": "Ma sœur parle au téléphone maintenant."}, "errorPatterns": [{"equals": "watch", "category": "verb_tense", "feedback": "Watch décrit une habitude. Avec now, on veut dire « en ce moment » : are watching."}, {"equals": "watches", "category": "verb_tense", "feedback": "Avec now, on utilise le présent continu : are watching. De plus, Lucy and Ben = they, donc pas de -s."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m04.01', 'en', null, 'en.g20.was_were', array['en.g20.was_were']::text[], 'mcq', 'diagnostic', 'My parents ___ in Paris two days ago.', array['were']::text[], 'My parents correspond à they. Avec they, le passé de to be est were. Two days ago place la phrase dans le passé.', 2, '{"id": "en.diag.m04.01", "unitIds": ["en.g20.was_were"], "type": "mcq", "difficulty": 2, "level": 3, "topic": "past", "instruction": "Choisis la bonne forme.", "prompt": "My parents ___ in Paris two days ago.", "promptLanguage": "en", "options": ["were", "was", "are"], "answer": "were", "acceptedAnswers": ["were"], "explanation": "My parents correspond à they. Avec they, le passé de to be est were. Two days ago place la phrase dans le passé.", "tip": "Passé de to be : was avec I, he, she, it ; were avec you, we, they.", "extraExample": {"text": "We were at the beach yesterday.", "translation": "Nous étions à la plage hier."}, "errorPatterns": [{"equals": "was", "category": "conjugation", "feedback": "Was s''utilise avec I, he, she et it. My parents = they : on dit were."}, {"equals": "are", "category": "verb_tense", "feedback": "Are est le présent. Two days ago parle du passé : were."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m04.02', 'en', null, 'en.g21.past_simple_regular', array['en.g21.past_simple_regular']::text[], 'fill_blank', 'diagnostic', 'My friend ___ me last night. (call)', array['called']::text[], 'Last night place l''action dans le passé. Call est un verbe régulier : on ajoute -ed, ce qui donne called, avec toutes les personnes.', 2, '{"id": "en.diag.m04.02", "unitIds": ["en.g21.past_simple_regular"], "type": "fill_blank", "difficulty": 2, "level": 3, "topic": "past", "instruction": "Complète avec le passé du verbe entre parenthèses.", "prompt": "My friend ___ me last night. (call)", "promptLanguage": "en", "options": ["called", "call", "calls"], "answer": "called", "acceptedAnswers": ["called"], "explanation": "Last night place l''action dans le passé. Call est un verbe régulier : on ajoute -ed, ce qui donne called, avec toutes les personnes.", "tip": "Verbe régulier au passé : verbe + -ed, sans -s.", "extraExample": {"text": "Anna cleaned the door yesterday.", "translation": "Anna a nettoyé la porte hier."}, "errorPatterns": [{"equals": "call", "category": "verb_tense", "feedback": "Call est la forme de base, pour le présent. Avec last night, on ajoute -ed : called."}, {"equals": "calls", "category": "verb_tense", "feedback": "Le -s est réservé au présent. Au passé, on ajoute -ed : called."}], "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m04.03', 'en', null, 'en.g22.irregular_verbs', array['en.g22.irregular_verbs']::text[], 'fill_blank', 'diagnostic', 'Yesterday, we ___ lunch at home. (have)', array['had']::text[], 'Have est un verbe irrégulier : son passé est had, et non haved. Yesterday indique le passé.', 3, '{"id": "en.diag.m04.03", "unitIds": ["en.g22.irregular_verbs"], "type": "fill_blank", "difficulty": 3, "level": 3, "topic": "verbs", "instruction": "Complète avec le passé du verbe entre parenthèses.", "prompt": "Yesterday, we ___ lunch at home. (have)", "promptLanguage": "en", "options": ["had", "have", "haved"], "answer": "had", "acceptedAnswers": ["had"], "explanation": "Have est un verbe irrégulier : son passé est had, et non haved. Yesterday indique le passé.", "tip": "Verbe irrégulier : pas de -ed, une forme à apprendre (have → had).", "extraExample": {"text": "She had breakfast at seven.", "translation": "Elle a pris son petit-déjeuner à sept heures."}, "errorPatterns": [{"equals": "have", "category": "verb_tense", "feedback": "Have est le présent. Avec yesterday, on utilise le passé : had."}, {"equals": "haved", "category": "conjugation", "feedback": "Have est irrégulier : on n''ajoute pas -ed. Son passé est had."}], "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m04.04', 'en', null, 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions']::text[], 'reorder', 'diagnostic', 'Où es-tu allé hier ?', array['Where did you go yesterday']::text[], 'Avec un mot interrogatif, l''ordre est Where + did + sujet + verbe de base. Go reste à la base, car did porte déjà le passé.', 3, '{"id": "en.diag.m04.04", "unitIds": ["en.g23.past_simple_negative_questions"], "type": "reorder", "difficulty": 3, "level": 3, "topic": "construction", "instruction": "Remets les mots dans l''ordre pour poser la question.", "prompt": "Où es-tu allé hier ?", "promptLanguage": "fr", "tokens": ["yesterday", "Where", "go", "you", "did"], "answer": "Where did you go yesterday", "acceptedAnswers": ["Where did you go yesterday"], "explanation": "Avec un mot interrogatif, l''ordre est Where + did + sujet + verbe de base. Go reste à la base, car did porte déjà le passé.", "tip": "Question au passé : mot interrogatif + did + sujet + base.", "extraExample": {"text": "What did you eat at lunch?", "translation": "Qu''est-ce que tu as mangé au déjeuner ?"}, "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m04.05', 'en', null, 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions']::text[], 'mcq', 'diagnostic', 'Quelle phrase est correcte ?', array['I didn''t see Tom.']::text[], 'La négation au passé se fait avec didn''t + verbe de base : I didn''t see. Le passé est déjà dans didn''t, donc on n''écrit pas saw.', 3, '{"id": "en.diag.m04.05", "unitIds": ["en.g23.past_simple_negative_questions"], "type": "mcq", "difficulty": 3, "level": 3, "topic": "past", "instruction": "Choisis la phrase correcte.", "prompt": "Quelle phrase est correcte ?", "promptLanguage": "fr", "options": ["I didn''t see Tom.", "I didn''t saw Tom.", "I not saw Tom."], "answer": "I didn''t see Tom.", "acceptedAnswers": ["I didn''t see Tom."], "explanation": "La négation au passé se fait avec didn''t + verbe de base : I didn''t see. Le passé est déjà dans didn''t, donc on n''écrit pas saw.", "tip": "didn''t + verbe de base, jamais le passé.", "extraExample": {"text": "She didn''t buy a present.", "translation": "Elle n''a pas acheté de cadeau."}, "errorPatterns": [{"equals": "i didn''t saw tom", "category": "conjugation", "feedback": "Après didn''t, le verbe reste à la forme de base : didn''t see."}, {"equals": "i not saw tom", "category": "grammar", "feedback": "En anglais, on ne met pas not directement après le sujet : on utilise didn''t + verbe de base."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m05.01', 'en', null, 'en.g24.will_future', array['en.g24.will_future']::text[], 'mcq', 'diagnostic', 'Tomorrow, my sister ___ me at the office.', array['will visit']::text[], 'Pour parler du futur, on met will avant le verbe de base : will visit. Will ne prend jamais de -s et n''est pas suivi de to.', 2, '{"id": "en.diag.m05.01", "unitIds": ["en.g24.will_future"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme.", "prompt": "Tomorrow, my sister ___ me at the office.", "promptLanguage": "en", "options": ["will visit", "wills visit", "will to visit", "will visits"], "answer": "will visit", "acceptedAnswers": ["will visit"], "explanation": "Pour parler du futur, on met will avant le verbe de base : will visit. Will ne prend jamais de -s et n''est pas suivi de to.", "tip": "Will + verbe de base : pas de -s, pas de to.", "extraExample": {"text": "Anna will call you later.", "translation": "Anna t''appellera plus tard."}, "errorPatterns": [{"equals": "wills visit", "category": "conjugation", "feedback": "Will ne prend jamais de -s, même avec my sister (she). On dit will visit."}, {"equals": "will to visit", "category": "grammar", "feedback": "Après will, on ne met pas to : will visit."}, {"equals": "will visits", "category": "conjugation", "feedback": "Après will, le verbe reste à la forme de base : pas de -s."}], "level": 3, "topic": "future", "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m05.02', 'en', null, 'en.g25.going_to', array['en.g25.going_to']::text[], 'fill_blank', 'diagnostic', 'Tom ___ going to change his phone.', array['is','''s']::text[], 'Going to s''utilise avec be, qui change selon le sujet. Avec Tom (he), be devient is : Tom is going to change his phone.', 2, '{"id": "en.diag.m05.02", "unitIds": ["en.g25.going_to"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne forme de be.", "prompt": "Tom ___ going to change his phone.", "promptLanguage": "en", "options": ["is", "are", "am"], "answer": "is", "acceptedAnswers": ["is", "''s"], "explanation": "Going to s''utilise avec be, qui change selon le sujet. Avec Tom (he), be devient is : Tom is going to change his phone.", "tip": "I am, he / she / it is, you / we / they are + going to.", "extraExample": {"text": "We are going to move next week.", "translation": "Nous allons déménager la semaine prochaine."}, "errorPatterns": [{"equals": "are", "category": "conjugation", "feedback": "Are va avec you, we et they. Avec Tom (he), on dit is."}, {"equals": "am", "category": "conjugation", "feedback": "Am va uniquement avec I. Avec Tom (he), on dit is."}], "level": 3, "topic": "future", "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m05.03', 'en', null, 'en.g26.will_vs_going_to', array['en.g26.will_vs_going_to','en.g25.going_to']::text[], 'mcq', 'diagnostic', 'He ___ start next week.', array['is going to']::text[], 'Sam a décidé hier : c''est un projet déjà décidé avant qu''on en parle. On utilise be going to : He is going to start next week.', 3, '{"id": "en.diag.m05.03", "unitIds": ["en.g26.will_vs_going_to", "en.g25.going_to"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne forme.", "context": "Yesterday, Sam decided to study French.", "prompt": "He ___ start next week.", "promptLanguage": "en", "options": ["is going to", "will", "are going to", "is going"], "answer": "is going to", "acceptedAnswers": ["is going to"], "explanation": "Sam a décidé hier : c''est un projet déjà décidé avant qu''on en parle. On utilise be going to : He is going to start next week.", "tip": "Décision déjà prise : going to. Décision sur le moment : will.", "extraExample": {"text": "I''m going to visit my mother this weekend.", "translation": "Je vais rendre visite à ma mère ce week-end."}, "errorPatterns": [{"equals": "will", "category": "grammar", "feedback": "Will sert à une décision prise à l''instant. Sam a déjà décidé hier : on utilise be going to."}, {"equals": "are going to", "category": "conjugation", "feedback": "Avec he, be devient is : He is going to start."}, {"equals": "is going", "category": "grammar", "feedback": "Il manque to après going : be + going to + verbe de base."}], "level": 3, "topic": "future", "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m05.04', 'en', null, 'en.g27.present_continuous_future', array['en.g27.present_continuous_future']::text[], 'mcq', 'diagnostic', 'Anna ___ the doctor tonight at seven.', array['is seeing']::text[], 'Pour un rendez-vous déjà fixé, on utilise le présent continu avec un moment du futur (tonight) : be + verbe en -ing. Avec Anna (she), be devient is.', 3, '{"id": "en.diag.m05.04", "unitIds": ["en.g27.present_continuous_future"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne forme.", "prompt": "Anna ___ the doctor tonight at seven.", "promptLanguage": "en", "options": ["is seeing", "am seeing", "seeing", "is see"], "answer": "is seeing", "acceptedAnswers": ["is seeing"], "explanation": "Pour un rendez-vous déjà fixé, on utilise le présent continu avec un moment du futur (tonight) : be + verbe en -ing. Avec Anna (she), be devient is.", "tip": "Rendez-vous fixé : be + -ing + moment du futur.", "extraExample": {"text": "We are meeting our colleagues tomorrow.", "translation": "Nous retrouvons nos collègues demain."}, "errorPatterns": [{"equals": "am seeing", "category": "conjugation", "feedback": "Am va uniquement avec I. Avec Anna (she), on dit is seeing."}, {"equals": "seeing", "category": "grammar", "feedback": "Il manque be devant seeing : Anna is seeing the doctor."}, {"equals": "is see", "category": "grammar", "feedback": "Après is, le verbe prend -ing : is seeing."}], "level": 3, "topic": "future", "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m05.05', 'en', null, 'en.g25.going_to', array['en.g25.going_to']::text[], 'reorder', 'diagnostic', 'Qu''est-ce que tu vas faire demain ?', array['What are you going to do tomorrow']::text[], 'Dans une question avec going to, on met le mot interrogatif, puis be avant le sujet : What are you going to do ? Tomorrow se place à la fin.', 3, '{"id": "en.diag.m05.05", "unitIds": ["en.g25.going_to"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour traduire.", "prompt": "Qu''est-ce que tu vas faire demain ?", "promptLanguage": "fr", "tokens": ["do", "What", "going", "you", "tomorrow", "to", "are"], "answer": "What are you going to do tomorrow", "acceptedAnswers": ["What are you going to do tomorrow"], "hint": "Le mot interrogatif ouvre la question, puis be passe avant le sujet.", "explanation": "Dans une question avec going to, on met le mot interrogatif, puis be avant le sujet : What are you going to do ? Tomorrow se place à la fin.", "tip": "Question : mot interrogatif + be + sujet + going to + verbe de base.", "extraExample": {"text": "Where are you going to live?", "translation": "Où vas-tu habiter ?"}, "level": 3, "topic": "construction", "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m06.01', 'en', null, 'en.g28.there_is_are', array['en.g28.there_is_are']::text[], 'mcq', 'diagnostic', 'There ___ three bedrooms in our apartment.', array['are']::text[], 'Three bedrooms est un pluriel : on dit there are. « Il y a » ne se traduit jamais avec have.', 1, '{"id": "en.diag.m06.01", "unitIds": ["en.g28.there_is_are"], "type": "mcq", "difficulty": 1, "level": 1, "topic": "construction", "instruction": "Choisis la bonne forme.", "prompt": "There ___ three bedrooms in our apartment.", "promptLanguage": "en", "options": ["are", "is", "have", "has"], "answer": "are", "acceptedAnswers": ["are"], "hint": "Trois chambres : un seul élément ou plusieurs ?", "explanation": "Three bedrooms est un pluriel : on dit there are. « Il y a » ne se traduit jamais avec have.", "tip": "« Il y a » : there is (un seul) ou there are (plusieurs).", "extraExample": {"text": "There are two windows in the bathroom.", "translation": "Il y a deux fenêtres dans la salle de bain."}, "errorPatterns": [{"equals": "is", "category": "grammar", "feedback": "There is s''utilise avec un seul élément. Three bedrooms est un pluriel : there are."}, {"equals": "have", "category": "grammar", "feedback": "« Il y a » ne se dit pas avec have. On utilise there is ou there are."}, {"equals": "has", "category": "grammar", "feedback": "« Il y a » ne se dit pas avec has. Devant un pluriel, on dit there are."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m06.02', 'en', null, 'en.g29.some_any', array['en.g29.some_any']::text[], 'fill_blank', 'diagnostic', 'I don''t have ___ money.', array['any']::text[], 'Dans une phrase négative, on utilise any : I don''t have any money. Money ne se compte pas, donc pas de a.', 1, '{"id": "en.diag.m06.02", "unitIds": ["en.g29.some_any"], "type": "fill_blank", "difficulty": 1, "level": 1, "topic": "construction", "instruction": "Complète avec some, any ou a.", "prompt": "I don''t have ___ money.", "promptLanguage": "en", "options": ["any", "some", "a"], "answer": "any", "acceptedAnswers": ["any"], "hint": "La phrase est négative.", "explanation": "Dans une phrase négative, on utilise any : I don''t have any money. Money ne se compte pas, donc pas de a.", "tip": "Négation : any ; phrase affirmative : some.", "extraExample": {"text": "We don''t have any bread.", "translation": "Nous n''avons pas de pain."}, "errorPatterns": [{"equals": "some", "category": "grammar", "feedback": "Some ne s''utilise pas dans une phrase négative. Après don''t, on dit any."}, {"equals": "a", "category": "grammar", "feedback": "Money ne se compte pas : on ne dit pas « a money ». On dit any money."}], "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m06.03', 'en', null, 'en.g30.how_much_many', array['en.g30.how_much_many']::text[], 'mcq', 'diagnostic', '___ people are there at the party?', array['How many']::text[], 'People se compte et est un pluriel : on utilise how many. How much sert pour les noms qu''on ne compte pas ou pour un prix.', 1, '{"id": "en.diag.m06.03", "unitIds": ["en.g30.how_much_many"], "type": "mcq", "difficulty": 1, "level": 1, "topic": "construction", "instruction": "Choisis la bonne expression.", "prompt": "___ people are there at the party?", "promptLanguage": "en", "options": ["How many", "How much", "How long"], "answer": "How many", "acceptedAnswers": ["How many"], "hint": "On peut compter les personnes.", "explanation": "People se compte et est un pluriel : on utilise how many. How much sert pour les noms qu''on ne compte pas ou pour un prix.", "tip": "On peut compter ? How many. On ne peut pas ? How much.", "extraExample": {"text": "How many friends do you have?", "translation": "Combien d''amis as-tu ?"}, "errorPatterns": [{"equals": "how much", "category": "grammar", "feedback": "How much s''utilise avec un nom qu''on ne compte pas (money, bread). People se compte : how many."}, {"equals": "how long", "category": "grammar", "feedback": "How long demande une durée ou une longueur. Pour « combien de personnes », on dit how many people."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m06.04', 'en', null, 'en.g31.time_and_dates', array['en.g31.time_and_dates']::text[], 'mcq', 'diagnostic', 'Comment dit-on « Il est cinq heures et demie. » en anglais ?', array['It''s half past five.']::text[], '« Et demie » se dit half past devant l''heure : half past five (5 h 30). On n''utilise pas and.', 1, '{"id": "en.diag.m06.04", "unitIds": ["en.g31.time_and_dates"], "type": "mcq", "difficulty": 1, "level": 1, "topic": "vocabulary", "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Il est cinq heures et demie. » en anglais ?", "promptLanguage": "fr", "options": ["It''s half past five.", "It''s five and half.", "It''s half to five.", "It''s five hours half."], "answer": "It''s half past five.", "acceptedAnswers": ["It''s half past five."], "hint": "En anglais, la demie se place avant l''heure.", "explanation": "« Et demie » se dit half past devant l''heure : half past five (5 h 30). On n''utilise pas and.", "tip": "Cinq heures et demie = half past five.", "extraExample": {"text": "It''s half past eight.", "translation": "Il est huit heures et demie."}, "errorPatterns": [{"contains": "five and half", "category": "word_order", "feedback": "On ne dit pas « five and half ». La demie se place avant l''heure : half past five."}, {"contains": "half to five", "category": "grammar", "feedback": "To veut dire « moins » (quarter to five = 4 h 45). Pour 5 h 30, on dit half past five."}, {"contains": "five hours half", "category": "word_confusion", "feedback": "Hours veut dire « durée ». Pour dire l''heure, on dit half past five."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m06.05', 'en', null, 'en.g29.some_any', array['en.g29.some_any']::text[], 'reorder', 'diagnostic', 'Puis-je avoir du café, s''il vous plaît ?', array['Can I have some coffee please','Please can I have some coffee']::text[], 'Pour demander poliment, on dit Can I have some… please ? On garde some dans une demande polie, même si c''est une question.', 2, '{"id": "en.diag.m06.05", "unitIds": ["en.g29.some_any"], "type": "reorder", "difficulty": 2, "level": 1, "topic": "construction", "instruction": "Remets les mots dans l''ordre pour former la demande polie.", "prompt": "Puis-je avoir du café, s''il vous plaît ?", "promptLanguage": "fr", "tokens": ["coffee", "Can", "some", "I", "please", "have"], "answer": "Can I have some coffee please", "acceptedAnswers": ["Can I have some coffee please", "Please can I have some coffee"], "hint": "La phrase commence par Can I have.", "explanation": "Pour demander poliment, on dit Can I have some… please ? On garde some dans une demande polie, même si c''est une question.", "tip": "Can I have some… , please ? : la formule du restaurant.", "extraExample": {"text": "Can I have some milk, please?", "translation": "Puis-je avoir du lait, s''il vous plaît ?"}, "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m07.01', 'en', null, 'en.g32.word_order', array['en.g32.word_order']::text[], 'mcq', 'diagnostic', 'Comment dit-on « Nous aimons beaucoup notre petite maison. » ?', array['We like our small house very much.']::text[], 'Le verbe et son complément restent ensemble (like our small house) et very much se place à la fin. L''adjectif small se met avant le nom.', 3, '{"id": "en.diag.m07.01", "unitIds": ["en.g32.word_order"], "type": "mcq", "difficulty": 3, "level": 4, "topic": "construction", "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « Nous aimons beaucoup notre petite maison. » ?", "promptLanguage": "fr", "options": ["We like our small house very much.", "We like very much our small house.", "We like our house small very much.", "We very like our small house."], "answer": "We like our small house very much.", "acceptedAnswers": ["We like our small house very much."], "explanation": "Le verbe et son complément restent ensemble (like our small house) et very much se place à la fin. L''adjectif small se met avant le nom.", "tip": "Pas d''adverbe entre le verbe et son complément : il va à la fin.", "extraExample": {"text": "I like my new job very much.", "translation": "J''aime beaucoup mon nouveau travail."}, "errorPatterns": [{"equals": "we like very much our small house", "category": "word_order", "feedback": "C''est le calque du français. En anglais, very much se place à la fin : We like our small house very much."}, {"equals": "we like our house small very much", "category": "word_order", "feedback": "L''adjectif se place avant le nom : our small house."}, {"equals": "we very like our small house", "category": "word_order", "feedback": "Very ne se place pas devant like seul. On dit very much, à la fin de la phrase."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m07.02', 'en', null, 'en.g34.prepositions_time', array['en.g34.prepositions_time']::text[], 'fill_blank', 'diagnostic', 'I have a meeting ___ Monday morning.', array['on']::text[], 'Un jour de la semaine, même avec morning, se construit avec on : on Monday morning.', 3, '{"id": "en.diag.m07.02", "unitIds": ["en.g34.prepositions_time"], "type": "fill_blank", "difficulty": 3, "level": 4, "topic": "construction", "instruction": "Choisis la bonne préposition.", "prompt": "I have a meeting ___ Monday morning.", "promptLanguage": "en", "options": ["on", "in", "at"], "answer": "on", "acceptedAnswers": ["on"], "explanation": "Un jour de la semaine, même avec morning, se construit avec on : on Monday morning.", "tip": "Un jour = on : on Monday, on Sunday evening.", "extraExample": {"text": "We go to the park on Sunday afternoon.", "translation": "Nous allons au parc le dimanche après-midi."}, "errorPatterns": [{"equals": "in", "category": "preposition", "feedback": "In sert pour les mois, les saisons et les années. Pour un jour de la semaine, on dit on Monday morning."}, {"equals": "at", "category": "preposition", "feedback": "At sert pour l''heure exacte. Pour un jour de la semaine, on dit on Monday morning."}], "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m07.03', 'en', null, 'en.g35.question_words', array['en.g35.question_words']::text[], 'reorder', 'diagnostic', 'Où travaille ta sœur ?', array['Where does your sister work']::text[], 'L''ordre d''une question est : mot interrogatif + auxiliaire + sujet + verbe. Avec your sister (3e personne), on utilise does.', 3, '{"id": "en.diag.m07.03", "unitIds": ["en.g35.question_words"], "type": "reorder", "difficulty": 3, "level": 4, "topic": "construction", "instruction": "Remets les mots dans l''ordre pour poser la question.", "prompt": "Où travaille ta sœur ?", "promptLanguage": "fr", "tokens": ["does", "Where", "work", "your", "sister"], "answer": "Where does your sister work", "acceptedAnswers": ["Where does your sister work"], "explanation": "L''ordre d''une question est : mot interrogatif + auxiliaire + sujet + verbe. Avec your sister (3e personne), on utilise does.", "tip": "Mot interrogatif, auxiliaire, sujet, verbe.", "extraExample": {"text": "Where does your brother live?", "translation": "Où habite ton frère ?"}, "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m07.04', 'en', null, 'en.g37.comparatives_superlatives', array['en.g37.comparatives_superlatives']::text[], 'mcq', 'diagnostic', 'My phone is ___ than my laptop.', array['cheaper']::text[], 'Cheap est un adjectif court : on ajoute -er pour comparer, puis than. On n''utilise pas more avec un adjectif court.', 3, '{"id": "en.diag.m07.04", "unitIds": ["en.g37.comparatives_superlatives"], "type": "mcq", "difficulty": 3, "level": 4, "topic": "construction", "instruction": "Choisis la bonne forme.", "prompt": "My phone is ___ than my laptop.", "promptLanguage": "en", "options": ["cheaper", "more cheap", "cheapest", "the cheaper"], "answer": "cheaper", "acceptedAnswers": ["cheaper"], "explanation": "Cheap est un adjectif court : on ajoute -er pour comparer, puis than. On n''utilise pas more avec un adjectif court.", "tip": "Adjectif court + -er + than.", "extraExample": {"text": "Anna is taller than Tom.", "translation": "Anna est plus grande que Tom."}, "errorPatterns": [{"equals": "more cheap", "category": "grammar", "feedback": "Cheap est un adjectif court : on ajoute -er (cheaper), on n''utilise pas more."}, {"equals": "cheapest", "category": "grammar", "feedback": "Cheapest veut dire « le moins cher ». Pour comparer deux choses avec than, on dit cheaper."}, {"equals": "the cheaper", "category": "grammar", "feedback": "Avec than, le comparatif s''utilise sans the : cheaper than."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m07.05', 'en', null, 'en.g38.should_could', array['en.g38.should_could']::text[], 'fill_blank', 'diagnostic', 'You are tired. You ___ go to bed early.', array['should']::text[], 'Should donne un conseil. Il ne change jamais et il est suivi du verbe de base, sans to.', 4, '{"id": "en.diag.m07.05", "unitIds": ["en.g38.should_could"], "type": "fill_blank", "difficulty": 4, "level": 4, "topic": "verbs", "instruction": "Complète avec la bonne forme.", "prompt": "You are tired. You ___ go to bed early.", "promptLanguage": "en", "options": ["should", "should to", "shoulds"], "answer": "should", "acceptedAnswers": ["should"], "explanation": "Should donne un conseil. Il ne change jamais et il est suivi du verbe de base, sans to.", "tip": "Should + verbe de base : jamais de to, jamais de -s.", "extraExample": {"text": "He should drink more water.", "translation": "Il devrait boire plus d''eau."}, "errorPatterns": [{"equals": "should to", "category": "grammar", "feedback": "Après should, on ne met pas to : You should go."}, {"equals": "shoulds", "category": "conjugation", "feedback": "Should ne prend jamais de -s."}], "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m08.01', 'en', null, 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro']::text[], 'fill_blank', 'diagnostic', 'Have you ever ___ to Japan?', array['been']::text[], 'Pour demander une expérience de vie, on dit Have you ever + participe passé. Le participe passé qui convient ici est been (have been to). Went est le past simple.', 3, '{"id": "en.diag.m08.01", "unitIds": ["en.g39.present_perfect_intro"], "type": "fill_blank", "difficulty": 3, "level": 4, "topic": "verbs", "instruction": "Complète la question.", "prompt": "Have you ever ___ to Japan?", "promptLanguage": "en", "options": ["been", "went", "be", "was"], "answer": "been", "acceptedAnswers": ["been"], "hint": "Après have, il faut un participe passé.", "explanation": "Pour demander une expérience de vie, on dit Have you ever + participe passé. Le participe passé qui convient ici est been (have been to). Went est le past simple.", "tip": "Have you ever been to… ? : « Es-tu déjà allé à… ? »", "extraExample": {"text": "Has Anna ever been to Paris?", "translation": "Anna est-elle déjà allée à Paris ?"}, "errorPatterns": [{"equals": "went", "category": "conjugation", "feedback": "Went est le past simple. Après have, il faut le participe passé : been."}, {"equals": "be", "category": "conjugation", "feedback": "Après have, le verbe ne reste pas à la forme de base : il faut le participe passé been."}, {"equals": "was", "category": "conjugation", "feedback": "Was est le past simple de be. Après have, il faut le participe passé : been."}], "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m08.02', 'en', null, 'en.g41.tense_contrast', array['en.g41.tense_contrast']::text[], 'mcq', 'diagnostic', 'Tom ___ his keys last night.', array['lost']::text[], 'Last night donne un moment précis dans le passé : on utilise le past simple. Lose est irrégulier : lost.', 3, '{"id": "en.diag.m08.02", "unitIds": ["en.g41.tense_contrast"], "type": "mcq", "difficulty": 3, "level": 4, "topic": "past", "instruction": "Choisis la bonne forme.", "prompt": "Tom ___ his keys last night.", "promptLanguage": "en", "options": ["lost", "has lost", "is losing", "loses"], "answer": "lost", "acceptedAnswers": ["lost"], "hint": "Last night est un moment précis du passé.", "explanation": "Last night donne un moment précis dans le passé : on utilise le past simple. Lose est irrégulier : lost.", "tip": "Moment précis du passé (last night, yesterday, ago) = past simple.", "extraExample": {"text": "Anna called me two hours ago.", "translation": "Anna m''a appelé il y a deux heures."}, "errorPatterns": [{"equals": "has lost", "category": "verb_tense", "feedback": "Avec un moment précis comme last night, on n''utilise pas le present perfect. Dis lost."}, {"equals": "is losing", "category": "verb_tense", "feedback": "Is losing est le présent continu. Last night est passé : lost."}, {"equals": "loses", "category": "verb_tense", "feedback": "Loses est le présent. Last night demande le passé : lost."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m08.03', 'en', null, 'en.g41.tense_contrast', array['en.g41.tense_contrast']::text[], 'mcq', 'diagnostic', 'I usually drink coffee, but today I ___ tea.', array['am drinking']::text[], 'Usually indique une habitude (présent simple), mais today indique une action temporaire, en cours : on utilise le présent continu, am drinking.', 3, '{"id": "en.diag.m08.03", "unitIds": ["en.g41.tense_contrast"], "type": "mcq", "difficulty": 3, "level": 4, "topic": "present", "instruction": "Choisis la bonne forme.", "prompt": "I usually drink coffee, but today I ___ tea.", "promptLanguage": "en", "options": ["am drinking", "drink", "drank", "have drunk"], "answer": "am drinking", "acceptedAnswers": ["am drinking"], "hint": "Today parle de ce qui se passe aujourd''hui, en ce moment.", "explanation": "Usually indique une habitude (présent simple), mais today indique une action temporaire, en cours : on utilise le présent continu, am drinking.", "tip": "Habitude = présent simple ; aujourd''hui, en ce moment = présent continu.", "extraExample": {"text": "Sam usually walks to work, but today he''s driving.", "translation": "Sam va d''habitude au travail à pied, mais aujourd''hui il conduit."}, "errorPatterns": [{"equals": "drink", "category": "verb_tense", "feedback": "Le présent simple décrit l''habitude (usually). Today parle d''une situation du moment : am drinking."}, {"equals": "drank", "category": "verb_tense", "feedback": "Drank est un passé. Today parle du moment présent : am drinking."}, {"equals": "have drunk", "category": "verb_tense", "feedback": "Le present perfect ne convient pas ici. Today indique une action en cours : am drinking."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m08.04', 'en', null, 'en.g40.short_answers', array['en.g40.short_answers']::text[], 'fill_blank', 'diagnostic', 'Anna can''t swim. — I can''t ___.', array['either']::text[], 'Pour dire « moi non plus » après une phrase négative, on dit I can''t either (ou Me neither). Too veut dire « aussi » et sert dans les phrases affirmatives.', 3, '{"id": "en.diag.m08.04", "unitIds": ["en.g40.short_answers"], "type": "fill_blank", "difficulty": 3, "level": 4, "topic": "construction", "instruction": "Complète la réaction.", "prompt": "Anna can''t swim. — I can''t ___.", "promptLanguage": "en", "options": ["either", "too", "neither", "also"], "answer": "either", "acceptedAnswers": ["either"], "hint": "« Moi non plus » : la phrase est négative.", "explanation": "Pour dire « moi non plus » après une phrase négative, on dit I can''t either (ou Me neither). Too veut dire « aussi » et sert dans les phrases affirmatives.", "tip": "Négation + either à la fin = « non plus ».", "extraExample": {"text": "Tom doesn''t like tea. — I don''t either.", "translation": "Tom n''aime pas le thé. — Moi non plus."}, "errorPatterns": [{"equals": "too", "category": "word_confusion", "feedback": "Too veut dire « aussi » et s''emploie dans une phrase affirmative. Après une négation, on dit either."}, {"equals": "neither", "category": "grammar", "feedback": "Neither contient déjà la négation : on dirait I can''t either, ou Me neither, mais pas I can''t neither."}, {"equals": "also", "category": "word_confusion", "feedback": "Also veut dire « aussi », dans une phrase affirmative. Après une négation, « non plus » se dit either."}], "pool": "diagnostic", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.diag.m08.05', 'en', null, 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.g41.tense_contrast']::text[], 'mcq', 'diagnostic', 'What has Sam already done?', array['He has sent an email.']::text[], 'Le texte dit que Sam a just sent an email : c''est fait. Le rapport n''est pas encore fini (hasn''t finished yet).', 4, '{"id": "en.diag.m08.05", "unitIds": ["en.g39.present_perfect_intro", "en.g41.tense_contrast"], "type": "mcq", "difficulty": 4, "level": 4, "topic": "comprehension", "instruction": "Lis le texte, puis choisis la bonne réponse.", "context": "Sam has just sent an email to his boss. He hasn''t finished the report yet.", "prompt": "What has Sam already done?", "promptLanguage": "en", "options": ["He has sent an email.", "He has finished the report.", "He is going to send an email.", "He sent a report yesterday."], "answer": "He has sent an email.", "acceptedAnswers": ["He has sent an email."], "hint": "Hasn''t finished yet = pas encore fini.", "explanation": "Le texte dit que Sam a just sent an email : c''est fait. Le rapport n''est pas encore fini (hasn''t finished yet).", "tip": "Just et already disent « c''est fait » ; not … yet dit « pas encore ».", "extraExample": {"text": "Anna has already called Tom, but she hasn''t called Sam yet.", "translation": "Anna a déjà appelé Tom, mais elle n''a pas encore appelé Sam."}, "errorPatterns": [{"equals": "he has finished the report", "category": "instruction", "feedback": "Le texte dit hasn''t finished the report yet : le rapport n''est pas encore fini."}, {"equals": "he is going to send an email", "category": "verb_tense", "feedback": "Is going to parle du futur. Le texte dit has just sent : l''e-mail est déjà parti."}, {"equals": "he sent a report yesterday", "category": "instruction", "feedback": "Le texte ne parle pas d''hier. Il dit que Sam a just sent an email."}], "pool": "diagnostic", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m01.01', 'en', null, 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.g02.articles','en.g06.possessive_adjectives']::text[], 'translation', 'assessment', 'Ma mère est professeur.', array['My mother is a teacher','My mum is a teacher','My mom is a teacher']::text[], 'Ma se dit my. Mother est une seule personne : le verbe est is. Devant un métier, l''anglais met a : a teacher.', 2, '{"id": "en.assess.m01.01", "unitIds": ["en.g03.be_affirmative", "en.g02.articles", "en.g06.possessive_adjectives"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Ma mère est professeur.", "promptLanguage": "fr", "answer": "My mother is a teacher", "acceptedAnswers": ["My mother is a teacher", "My mum is a teacher", "My mom is a teacher"], "explanation": "Ma se dit my. Mother est une seule personne : le verbe est is. Devant un métier, l''anglais met a : a teacher.", "tip": "Possessif + nom + is + a + métier.", "extraExample": {"text": "Her father is a student.", "translation": "Son père est étudiant."}, "errorPatterns": [{"contains": "is teacher", "category": "grammar", "feedback": "Il manque l''article. Devant un métier, l''anglais met a : a teacher."}, {"contains": "the my", "category": "grammar", "feedback": "On n''utilise pas the avec un possessif : my mother."}, {"contains": "mother are", "category": "conjugation", "feedback": "Mother est une seule personne : is, pas are."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m01.02', 'en', null, 'en.g06.possessive_adjectives', array['en.g06.possessive_adjectives','en.v.wife']::text[], 'fill_blank', 'assessment', 'Tom has a wife. ___ wife is a student.', array['His']::text[], 'Le possessif dépend de celui qui possède. Tom est un homme, donc his wife.', 2, '{"id": "en.assess.m01.02", "unitIds": ["en.g06.possessive_adjectives", "en.v.wife"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon possessif.", "prompt": "Tom has a wife. ___ wife is a student.", "promptLanguage": "en", "answer": "His", "acceptedAnswers": ["His"], "explanation": "Le possessif dépend de celui qui possède. Tom est un homme, donc his wife.", "tip": "Possesseur masculin : his. Possesseur féminin : her.", "extraExample": {"text": "Anna has a brother. Her brother is a teacher.", "translation": "Anna a un frère. Son frère est professeur."}, "errorPatterns": [{"equals": "her", "category": "grammar", "feedback": "Her est pour une femme qui possède. Tom est un homme : his wife."}, {"equals": "its", "category": "grammar", "feedback": "Its est pour un animal ou une chose. Pour Tom, on dit his."}, {"equals": "their", "category": "grammar", "feedback": "Their est pour plusieurs personnes. Tom est seul : his wife."}], "pool": "assessment", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m01.03', 'en', null, 'en.g03.be_affirmative', array['en.g03.be_affirmative','en.v.cold']::text[], 'free_answer', 'assessment', 'Comment dit-on « Elle a froid » en anglais ?', array['She is cold']::text[], 'Pour le froid, l''anglais utilise le verbe être : she is cold. On ne traduit pas « avoir » par have ici.', 3, '{"id": "en.assess.m01.03", "unitIds": ["en.g03.be_affirmative", "en.v.cold"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Elle a froid » en anglais ?", "promptLanguage": "fr", "answer": "She is cold", "acceptedAnswers": ["She is cold"], "explanation": "Pour le froid, l''anglais utilise le verbe être : she is cold. On ne traduit pas « avoir » par have ici.", "tip": "Froid, faim, âge : be (is, am, are), pas have.", "extraExample": {"text": "We are cold.", "translation": "Nous avons froid."}, "errorPatterns": [{"contains": "she has", "category": "verb_tense", "feedback": "Pour le froid, l''anglais utilise le verbe être : she is cold."}, {"contains": "she have", "category": "verb_tense", "feedback": "Pour le froid, l''anglais utilise le verbe être : she is cold."}, {"contains": "she are", "category": "conjugation", "feedback": "Are va avec you, we et they. Avec she, on dit is."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m01.04', 'en', null, 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.g05.have_has','en.v.four','en.v.two']::text[], 'translation', 'assessment', 'Ils ont quatre clés et deux sacs.', array['They have four keys and two bags']::text[], 'Ils = they, donc le verbe est have. Après un nombre plus grand que one, le nom est au pluriel : four keys, two bags.', 3, '{"id": "en.assess.m01.04", "unitIds": ["en.g07.plural_nouns", "en.g05.have_has", "en.v.four", "en.v.two"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais. « et » = and.", "prompt": "Ils ont quatre clés et deux sacs.", "promptLanguage": "fr", "answer": "They have four keys and two bags", "acceptedAnswers": ["They have four keys and two bags"], "explanation": "Ils = they, donc le verbe est have. Après un nombre plus grand que one, le nom est au pluriel : four keys, two bags.", "tip": "Nombre plus grand que un = nom + s.", "extraExample": {"text": "We have three dogs and five books.", "translation": "Nous avons trois chiens et cinq livres."}, "errorPatterns": [{"contains": "they has", "category": "conjugation", "feedback": "Has s''utilise seulement avec he, she et it. Avec they, on dit have."}, {"contains": "four key and", "category": "grammar", "feedback": "Après four, le nom est au pluriel : four keys."}, {"contains": "two bag", "category": "grammar", "feedback": "Après two, le nom est au pluriel : two bags."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m01.05', 'en', null, 'en.g07.plural_nouns', array['en.g07.plural_nouns','en.v.man','en.v.eight']::text[], 'mcq', 'assessment', '« Huit hommes sont à la maison. »', array['Eight men are at home']::text[], 'Man a un pluriel irrégulier : men. Le sujet est au pluriel, donc le verbe est are.', 2, '{"id": "en.assess.m01.05", "unitIds": ["en.g07.plural_nouns", "en.v.man", "en.v.eight"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la phrase correcte.", "prompt": "« Huit hommes sont à la maison. »", "promptLanguage": "fr", "options": ["Eight men are at home", "Eight mans are at home", "Eight man are at home", "Eight men is at home"], "answer": "Eight men are at home", "acceptedAnswers": ["Eight men are at home"], "explanation": "Man a un pluriel irrégulier : men. Le sujet est au pluriel, donc le verbe est are.", "tip": "Man → men. Sujet pluriel : are.", "extraExample": {"text": "Nine women are at school.", "translation": "Neuf femmes sont à l''école."}, "errorPatterns": [{"equals": "eight mans are at home", "category": "spelling", "feedback": "Le pluriel de man est men, pas « mans »."}, {"equals": "eight man are at home", "category": "grammar", "feedback": "Après eight, le nom est au pluriel : men."}, {"equals": "eight men is at home", "category": "conjugation", "feedback": "Men est un pluriel : le verbe est are, pas is."}], "pool": "assessment", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m02.01', 'en', null, 'en.g08.verbs_base_form', array['en.g08.verbs_base_form','en.v.live','en.v.work']::text[], 'translation', 'assessment', 'Ils habitent à Paris et travaillent à Londres.', array['They live in Paris and work in London.','They live in Paris and they work in London.','They are living in Paris and working in London.','They are living in Paris and they are working in London.']::text[], 'Avec they, le verbe reste à sa forme de base : they live, they work. Devant le nom d''une ville, « à » se dit in.', 2, '{"id": "en.assess.m02.01", "unitIds": ["en.g08.verbs_base_form", "en.v.live", "en.v.work"], "type": "translation", "difficulty": 2, "instruction": "Traduis en anglais.", "prompt": "Ils habitent à Paris et travaillent à Londres.", "promptLanguage": "fr", "answer": "They live in Paris and work in London.", "acceptedAnswers": ["They live in Paris and work in London.", "They live in Paris and they work in London.", "They are living in Paris and working in London.", "They are living in Paris and they are working in London."], "hint": "Avec they, les verbes gardent leur forme de base.", "explanation": "Avec they, le verbe reste à sa forme de base : they live, they work. Devant le nom d''une ville, « à » se dit in.", "tip": "I, you, we, they : jamais de -s sur le verbe.", "extraExample": {"text": "We live in London and we work in Paris.", "translation": "Nous habitons à Londres et nous travaillons à Paris."}, "errorPatterns": [{"contains": "they lives", "category": "conjugation", "feedback": "Avec they, le verbe ne prend pas de -s : they live."}, {"contains": "they works", "category": "conjugation", "feedback": "Avec they, le verbe ne prend pas de -s : they work."}, {"contains": "they are live", "category": "grammar", "feedback": "Pas de verbe être devant un autre verbe : they live."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m02.02', 'en', null, 'en.g09.do_vs_make', array['en.g09.do_vs_make','en.v.do','en.v.homework']::text[], 'fill_blank', 'assessment', 'My brother and I ___ our homework at home. (faire)', array['do']::text[], 'Les devoirs sont une tâche à accomplir : on dit do homework. My brother and I, c''est « nous » : le verbe ne prend pas de -s.', 2, '{"id": "en.assess.m02.02", "unitIds": ["en.g09.do_vs_make", "en.v.do", "en.v.homework"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon verbe : do ou make.", "prompt": "My brother and I ___ our homework at home. (faire)", "promptLanguage": "en", "answer": "do", "acceptedAnswers": ["do"], "hint": "Les devoirs sont une tâche à accomplir.", "explanation": "Les devoirs sont une tâche à accomplir : on dit do homework. My brother and I, c''est « nous » : le verbe ne prend pas de -s.", "tip": "Do homework, make dinner : apprends les groupes de mots.", "extraExample": {"text": "You do your homework and I make coffee.", "translation": "Tu fais tes devoirs et je fais du café."}, "errorPatterns": [{"equals": "make", "category": "word_confusion", "feedback": "Make sert à créer ou fabriquer. Les devoirs sont une tâche : on dit do homework."}, {"equals": "does", "category": "conjugation", "feedback": "My brother and I, c''est comme we : le verbe ne prend pas de -s."}], "pool": "assessment", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m02.03', 'en', null, 'en.g10.want_need_to', array['en.g10.want_need_to','en.v.need','en.v.help']::text[], 'free_answer', 'assessment', 'Comment dit-on « Nous avons besoin d''aider notre mère » en anglais ?', array['We need to help our mother.','We need to help our mum.','We need to help our mom.']::text[], 'Avoir besoin de se dit need, suivi de to + verbe de base : need to help. Notre mère se dit our mother.', 3, '{"id": "en.assess.m02.03", "unitIds": ["en.g10.want_need_to", "en.v.need", "en.v.help"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Nous avons besoin d''aider notre mère » en anglais ?", "promptLanguage": "fr", "answer": "We need to help our mother.", "acceptedAnswers": ["We need to help our mother.", "We need to help our mum.", "We need to help our mom."], "hint": "Avoir besoin de + verbe : need to + verbe de base.", "explanation": "Avoir besoin de se dit need, suivi de to + verbe de base : need to help. Notre mère se dit our mother.", "tip": "Need + to + verbe de base.", "extraExample": {"text": "I need to wait for my father.", "translation": "J''ai besoin d''attendre mon père."}, "errorPatterns": [{"contains": "need help", "category": "grammar", "feedback": "Pour « avoir besoin d''aider », il faut to + verbe : need to help."}, {"contains": "need that", "category": "grammar", "feedback": "On ne dit pas « need that » avant un verbe. On dit need to + verbe."}, {"contains": "we needs", "category": "conjugation", "feedback": "Avec we, le verbe ne prend pas de -s : we need."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m02.04', 'en', null, 'en.g11.can', array['en.g11.can','en.v.open','en.v.door']::text[], 'translation', 'assessment', 'Peux-tu ouvrir la porte, s''il te plaît ?', array['Can you open the door, please?','Can you please open the door?','Could you open the door, please?','Could you please open the door?','Please can you open the door?','Please could you open the door?']::text[], 'Pour demander un service, on utilise Can you + verbe de base ? Can se place avant le sujet, sans to. Please rend la demande plus polie.', 3, '{"id": "en.assess.m02.04", "unitIds": ["en.g11.can", "en.v.open", "en.v.door"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Peux-tu ouvrir la porte, s''il te plaît ?", "promptLanguage": "fr", "answer": "Can you open the door, please?", "acceptedAnswers": ["Can you open the door, please?", "Can you please open the door?", "Could you open the door, please?", "Could you please open the door?", "Please can you open the door?", "Please could you open the door?"], "hint": "Pour une demande : Can + you + verbe de base.", "explanation": "Pour demander un service, on utilise Can you + verbe de base ? Can se place avant le sujet, sans to. Please rend la demande plus polie.", "tip": "Peux-tu… ? = Can you… ? + verbe de base.", "extraExample": {"text": "Can you wait for me, please?", "translation": "Peux-tu m''attendre, s''il te plaît ?"}, "errorPatterns": [{"contains": "can you to", "category": "grammar", "feedback": "Après can you, on n''ajoute pas to : Can you open the door?"}, {"contains": "you can open", "category": "word_order", "feedback": "Pour poser une question, on met can avant le sujet : Can you open the door?"}, {"contains": "can you opens", "category": "conjugation", "feedback": "Après can, le verbe ne prend jamais de -s : Can you open?"}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m02.05', 'en', null, 'en.g12.must', array['en.g12.must','en.v.careful']::text[], 'free_answer', 'assessment', 'Comment dit-on « Nous ne devons pas être en retard » en anglais ?', array['We mustn''t be late.','We must not be late.']::text[], 'Pour dire « il ne faut pas », on utilise mustn''t + verbe de base. Le verbe de base d''être est be : we mustn''t be late.', 3, '{"id": "en.assess.m02.05", "unitIds": ["en.g12.must", "en.v.careful"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Nous ne devons pas être en retard » en anglais ?", "promptLanguage": "fr", "answer": "We mustn''t be late.", "acceptedAnswers": ["We mustn''t be late.", "We must not be late."], "hint": "Interdiction : mustn''t + verbe de base. Le verbe être devient be.", "explanation": "Pour dire « il ne faut pas », on utilise mustn''t + verbe de base. Le verbe de base d''être est be : we mustn''t be late.", "tip": "Mustn''t + be + adjectif : pas de to, pas de -s.", "extraExample": {"text": "You mustn''t wait for me.", "translation": "Tu ne dois pas m''attendre."}, "errorPatterns": [{"contains": "mustn''t to", "category": "grammar", "feedback": "Après mustn''t, on n''ajoute pas to : we mustn''t be late."}, {"contains": "mustn''t are", "category": "grammar", "feedback": "Après mustn''t, le verbe être se dit be, pas are : we mustn''t be late."}, {"contains": "don''t must", "category": "grammar", "feedback": "Avec must, la négation est mustn''t (ou must not) : we mustn''t be late."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m03.01', 'en', null, 'en.g14.present_simple_third_person', array['en.g14.present_simple_third_person','en.g17.frequency_adverbs']::text[], 'translation', 'assessment', 'Ma sœur a un ordinateur portable et elle étudie souvent à la maison.', array['My sister has a laptop and she often studies at home.','My sister has a laptop and often studies at home.','My sister has a laptop. She often studies at home.']::text[], 'My sister = she : have devient has et study devient studies (consonne + y). L''adverbe often se place avant le verbe : she often studies.', 3, '{"id": "en.assess.m03.01", "unitIds": ["en.g14.present_simple_third_person", "en.g17.frequency_adverbs"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Ma sœur a un ordinateur portable et elle étudie souvent à la maison.", "promptLanguage": "fr", "answer": "My sister has a laptop and she often studies at home.", "acceptedAnswers": ["My sister has a laptop and she often studies at home.", "My sister has a laptop and often studies at home.", "My sister has a laptop. She often studies at home."], "hint": "Have devient has avec she. Study devient studies. Often se place avant le verbe.", "explanation": "My sister = she : have devient has et study devient studies (consonne + y). L''adverbe often se place avant le verbe : she often studies.", "tip": "She : has, studies. Et l''adverbe avant le verbe.", "extraExample": {"text": "My brother often cooks dinner at home.", "translation": "Mon frère prépare souvent le dîner à la maison."}, "errorPatterns": [{"contains": "sister have a", "category": "conjugation", "feedback": "Avec my sister (= she), have devient has : my sister has a laptop."}, {"contains": "studys", "category": "spelling", "feedback": "Study devient studies : on change le y en i avant -es."}, {"contains": "studies often", "category": "word_order", "feedback": "L''adverbe de fréquence se place avant le verbe : she often studies."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m03.02', 'en', null, 'en.g15.present_simple_negative', array['en.g15.present_simple_negative']::text[], 'fill_blank', 'assessment', 'My parents ___ drink coffee in the evening.', array['don''t']::text[], 'My parents = they : plusieurs personnes. Avec they, la négation du présent simple se fait avec don''t, suivi du verbe de base.', 2, '{"id": "en.assess.m03.02", "unitIds": ["en.g15.present_simple_negative"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec don''t ou doesn''t.", "prompt": "My parents ___ drink coffee in the evening.", "promptLanguage": "en", "answer": "don''t", "acceptedAnswers": ["don''t"], "hint": "My parents = they.", "explanation": "My parents = they : plusieurs personnes. Avec they, la négation du présent simple se fait avec don''t, suivi du verbe de base.", "tip": "Pluriel (they) : don''t. Singulier (he, she, it) : doesn''t.", "extraExample": {"text": "My brother doesn''t eat breakfast.", "translation": "Mon frère ne prend pas de petit-déjeuner."}, "errorPatterns": [{"equals": "doesn''t", "category": "conjugation", "feedback": "My parents = they (pluriel) : on utilise don''t. Doesn''t est pour he, she, it."}, {"equals": "isn''t", "category": "grammar", "feedback": "Isn''t s''emploie avec be ou avec un verbe en -ing. Avec drink au présent simple, on utilise don''t."}], "pool": "assessment", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m03.03', 'en', null, 'en.g16.present_simple_questions', array['en.g16.present_simple_questions']::text[], 'free_answer', 'assessment', 'Does Anna play music?', array['No, she doesn''t.']::text[], 'La question commence par Does : on répond avec doesn''t. Anna se remplace par she : No, she doesn''t. On ne répète pas le verbe play.', 3, '{"id": "en.assess.m03.03", "unitIds": ["en.g16.present_simple_questions"], "type": "free_answer", "difficulty": 3, "instruction": "Réponds « non » avec une réponse courte (No, …).", "prompt": "Does Anna play music?", "promptLanguage": "en", "answer": "No, she doesn''t.", "acceptedAnswers": ["No, she doesn''t."], "hint": "On reprend l''auxiliaire de la question. Anna = she.", "explanation": "La question commence par Does : on répond avec doesn''t. Anna se remplace par she : No, she doesn''t. On ne répète pas le verbe play.", "tip": "Question en Does → Yes, she does. / No, she doesn''t.", "extraExample": {"text": "Do your parents cook? Yes, they do.", "translation": "Tes parents cuisinent-ils ? Oui."}, "errorPatterns": [{"equals": "no she don''t", "category": "conjugation", "feedback": "Avec she, on utilise doesn''t : No, she doesn''t."}, {"equals": "no she isn''t", "category": "grammar", "feedback": "La question commence par Does : on répond avec does / doesn''t, pas avec be."}, {"equals": "no she doesn''t play", "category": "instruction", "feedback": "La consigne demande une réponse courte : on s''arrête à doesn''t. No, she doesn''t."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m03.04', 'en', null, 'en.g19.simple_vs_continuous', array['en.g19.simple_vs_continuous']::text[], 'mcq', 'assessment', 'Quelle phrase est correcte pour parler d''un besoin ?', array['My brother needs a laptop for school.']::text[], 'Need est un verbe d''état : il ne s''utilise presque jamais au présent continu. On le garde au présent simple, avec -s à la 3e personne : my brother needs.', 3, '{"id": "en.assess.m03.04", "unitIds": ["en.g19.simple_vs_continuous"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la phrase correcte.", "prompt": "Quelle phrase est correcte pour parler d''un besoin ?", "promptLanguage": "fr", "options": ["My brother needs a laptop for school.", "My brother is needing a laptop for school.", "My brother need a laptop for school."], "answer": "My brother needs a laptop for school.", "acceptedAnswers": ["My brother needs a laptop for school."], "hint": "Need exprime un besoin, pas une action.", "explanation": "Need est un verbe d''état : il ne s''utilise presque jamais au présent continu. On le garde au présent simple, avec -s à la 3e personne : my brother needs.", "tip": "Need, want, like, know : jamais de -ing.", "extraExample": {"text": "She wants a coffee.", "translation": "Elle veut un café."}, "errorPatterns": [{"equals": "My brother is needing a laptop for school.", "category": "verb_tense", "feedback": "Need est un verbe d''état : on ne dit pas is needing. On dit needs."}, {"equals": "My brother need a laptop for school.", "category": "conjugation", "feedback": "My brother = he : le verbe prend -s au présent simple. On dit needs."}], "pool": "assessment", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m03.05', 'en', null, 'en.g18.present_continuous', array['en.g18.present_continuous']::text[], 'translation', 'assessment', 'Il n''écoute pas de musique maintenant : il appelle sa mère.', array['He isn''t listening to music now. He is calling his mother.','He isn''t listening to music now, but he is calling his mother.','He isn''t listening to music now and he is calling his mother.','He isn''t listening to music right now. He is calling his mother.','He isn''t listening to music at the moment. He is calling his mother.','Now he isn''t listening to music. He is calling his mother.','He isn''t listening to music. He is calling his mother now.','He isn''t listening to music. He is calling his mum now.','He isn''t listening to music now. He is calling his mum.','He isn''t listening to music now. He is calling his mom.']::text[], 'Maintenant indique des actions en cours : présent continu. La négation se fait avec be + not (isn''t listening), et l''action positive avec is calling. On dit listen to music.', 3, '{"id": "en.assess.m03.05", "unitIds": ["en.g18.present_continuous"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Il n''écoute pas de musique maintenant : il appelle sa mère.", "promptLanguage": "fr", "answer": "He isn''t listening to music now. He is calling his mother.", "acceptedAnswers": ["He isn''t listening to music now. He is calling his mother.", "He isn''t listening to music now, but he is calling his mother.", "He isn''t listening to music now and he is calling his mother.", "He isn''t listening to music right now. He is calling his mother.", "He isn''t listening to music at the moment. He is calling his mother.", "Now he isn''t listening to music. He is calling his mother.", "He isn''t listening to music. He is calling his mother now.", "He isn''t listening to music. He is calling his mum now.", "He isn''t listening to music now. He is calling his mum.", "He isn''t listening to music now. He is calling his mom."], "hint": "Maintenant : présent continu pour les deux verbes.", "explanation": "Maintenant indique des actions en cours : présent continu. La négation se fait avec be + not (isn''t listening), et l''action positive avec is calling. On dit listen to music.", "tip": "Négation : isn''t + -ing. Affirmation : is + -ing.", "extraExample": {"text": "They aren''t singing now. They are dancing.", "translation": "Ils ne chantent pas maintenant. Ils dansent."}, "errorPatterns": [{"contains": "doesn''t listen", "category": "verb_tense", "feedback": "Avec maintenant, la négation se fait avec isn''t + -ing : he isn''t listening."}, {"contains": "listening music", "category": "preposition", "feedback": "Listen se construit avec to : listening to music."}, {"contains": "he calling", "category": "grammar", "feedback": "Il manque is : he is calling."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m04.01', 'en', null, 'en.g20.was_were', array['en.g20.was_were','en.v.last']::text[], 'translation', 'assessment', 'Mes parents n''étaient pas à la maison hier soir.', array['My parents weren''t at home last night','My parents weren''t home last night','Last night my parents weren''t at home','Last night my parents weren''t home','My parents weren''t at home yesterday evening','My parents weren''t home yesterday evening','Yesterday evening my parents weren''t at home','Yesterday evening my parents weren''t home']::text[], 'My parents correspond à they : avec they, le passé de to be est were, et la négation est weren''t. « Hier soir » se dit last night ou yesterday evening.', 3, '{"id": "en.assess.m04.01", "unitIds": ["en.g20.was_were", "en.v.last"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Mes parents n''étaient pas à la maison hier soir.", "promptLanguage": "fr", "answer": "My parents weren''t at home last night", "acceptedAnswers": ["My parents weren''t at home last night", "My parents weren''t home last night", "Last night my parents weren''t at home", "Last night my parents weren''t home", "My parents weren''t at home yesterday evening", "My parents weren''t home yesterday evening", "Yesterday evening my parents weren''t at home", "Yesterday evening my parents weren''t home"], "hint": "My parents = they. Quel est le passé négatif de are ?", "explanation": "My parents correspond à they : avec they, le passé de to be est were, et la négation est weren''t. « Hier soir » se dit last night ou yesterday evening.", "tip": "They, we, you → weren''t ; I, he, she, it → wasn''t.", "extraExample": {"text": "The windows weren''t open last night.", "translation": "Les fenêtres n''étaient pas ouvertes hier soir."}, "errorPatterns": [{"contains": "parents wasn''t", "category": "conjugation", "feedback": "Wasn''t s''utilise avec I, he, she et it. Avec my parents (they), on dit weren''t."}, {"contains": "parents aren''t", "category": "verb_tense", "feedback": "Aren''t est le présent. Hier soir, c''est le passé : weren''t."}, {"contains": "yesterday night", "category": "vocabulary", "feedback": "« Hier soir » se dit last night ou yesterday evening, pas yesterday night."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m04.02', 'en', null, 'en.g21.past_simple_regular', array['en.g21.past_simple_regular']::text[], 'fill_blank', 'assessment', 'Tom ___ for two hours yesterday. (study)', array['studied']::text[], 'Study finit par une consonne + y : le y devient i avant -ed. On écrit donc studied. C''est la même forme avec toutes les personnes.', 3, '{"id": "en.assess.m04.02", "unitIds": ["en.g21.past_simple_regular"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le passé du verbe entre parenthèses.", "prompt": "Tom ___ for two hours yesterday. (study)", "promptLanguage": "en", "answer": "studied", "acceptedAnswers": ["studied"], "hint": "Study finit par une consonne + y.", "explanation": "Study finit par une consonne + y : le y devient i avant -ed. On écrit donc studied. C''est la même forme avec toutes les personnes.", "tip": "Consonne + y → -ied : study → studied, carry → carried.", "extraExample": {"text": "She carried two bags to the office.", "translation": "Elle a porté deux sacs jusqu''au bureau."}, "errorPatterns": [{"equals": "studyed", "category": "spelling", "feedback": "Après une consonne (d), le y se change en i : study → studied."}, {"equals": "studdied", "category": "spelling", "feedback": "On ne double pas le d : le y devient simplement i. On écrit studied."}, {"equals": "study", "category": "verb_tense", "feedback": "Study est le présent. Yesterday parle du passé : studied."}], "pool": "assessment", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m04.03', 'en', null, 'en.g22.irregular_verbs', array['en.g22.irregular_verbs']::text[], 'fill_blank', 'assessment', 'Anna ___ to my birthday party with her husband last night. (come)', array['came']::text[], 'Come est irrégulier : son passé est came (/keɪm/). Dans une phrase simple au passé, on n''utilise pas did : on met directement le verbe au passé.', 3, '{"id": "en.assess.m04.03", "unitIds": ["en.g22.irregular_verbs"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le passé du verbe entre parenthèses.", "prompt": "Anna ___ to my birthday party with her husband last night. (come)", "promptLanguage": "en", "answer": "came", "acceptedAnswers": ["came"], "hint": "Come est un verbe irrégulier : il ne prend pas -ed.", "explanation": "Come est irrégulier : son passé est came (/keɪm/). Dans une phrase simple au passé, on n''utilise pas did : on met directement le verbe au passé.", "tip": "Come → came : le o devient a.", "extraExample": {"text": "Tom came home late last night.", "translation": "Tom est rentré tard hier soir."}, "errorPatterns": [{"equals": "come", "category": "verb_tense", "feedback": "Come est le présent. Avec last night, on utilise le passé : came."}, {"equals": "comed", "category": "conjugation", "feedback": "Come est irrégulier : on n''ajoute pas -ed. Son passé est came."}, {"equals": "was come", "category": "grammar", "feedback": "On n''ajoute pas was devant un verbe d''action : came exprime déjà le passé."}], "pool": "assessment", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m04.04', 'en', null, 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.say','en.v.tell']::text[], 'free_answer', 'assessment', 'Comment dit-on « Qu''est-ce que Tom a dit à Anna ? » en anglais ?', array['What did Tom say to Anna','What did Tom tell Anna']::text[], 'Question au passé : What + did + sujet + verbe de base. Say reste à la base (pas said), car did porte déjà le passé. Say se construit avec to (say to Anna), alors que tell se construit directement avec la personne (tell Anna).', 4, '{"id": "en.assess.m04.04", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.say", "en.v.tell"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la question en anglais.", "prompt": "Comment dit-on « Qu''est-ce que Tom a dit à Anna ? » en anglais ?", "promptLanguage": "fr", "answer": "What did Tom say to Anna", "acceptedAnswers": ["What did Tom say to Anna", "What did Tom tell Anna"], "hint": "What + did + sujet + verbe de base.", "explanation": "Question au passé : What + did + sujet + verbe de base. Say reste à la base (pas said), car did porte déjà le passé. Say se construit avec to (say to Anna), alors que tell se construit directement avec la personne (tell Anna).", "tip": "say to quelqu''un ; tell quelqu''un.", "extraExample": {"text": "What did Anna tell you?", "translation": "Qu''est-ce qu''Anna t''a dit ?"}, "errorPatterns": [{"contains": "did tom said", "category": "conjugation", "feedback": "Après did, le verbe reste à la forme de base : What did Tom say ?"}, {"contains": "what tom", "category": "word_order", "feedback": "Une question au passé a besoin de did avant le sujet : What did Tom say ?"}, {"contains": "say anna", "category": "word_confusion", "feedback": "Say se construit avec to : say to Anna. Pour mettre la personne directement, utilise tell : tell Anna."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m04.05', 'en', null, 'en.g23.past_simple_negative_questions', array['en.g23.past_simple_negative_questions','en.v.forget','en.v.present']::text[], 'translation', 'assessment', 'Je n''ai pas oublié ton cadeau.', array['I didn''t forget your present','I didn''t forget your gift']::text[], 'Négation au passé : didn''t + verbe de base. Forget reste à la base (pas forgot), car le passé est déjà dans didn''t. « Ton cadeau » se dit your present.', 4, '{"id": "en.assess.m04.05", "unitIds": ["en.g23.past_simple_negative_questions", "en.v.forget", "en.v.present"], "type": "translation", "difficulty": 4, "instruction": "Traduis en anglais.", "prompt": "Je n''ai pas oublié ton cadeau.", "promptLanguage": "fr", "answer": "I didn''t forget your present", "acceptedAnswers": ["I didn''t forget your present", "I didn''t forget your gift"], "hint": "Didn''t + verbe de base.", "explanation": "Négation au passé : didn''t + verbe de base. Forget reste à la base (pas forgot), car le passé est déjà dans didn''t. « Ton cadeau » se dit your present.", "tip": "didn''t + base : forget, jamais forgot.", "extraExample": {"text": "She didn''t lose her key.", "translation": "Elle n''a pas perdu sa clé."}, "errorPatterns": [{"contains": "didn''t forgot", "category": "conjugation", "feedback": "Après didn''t, le verbe reste à la forme de base : didn''t forget."}, {"contains": "i not forgot", "category": "grammar", "feedback": "En anglais, on ne met pas not directement après le sujet : on utilise didn''t + verbe de base."}, {"contains": "i don''t forget", "category": "verb_tense", "feedback": "Don''t est le présent. Pour le passé, on utilise didn''t."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m05.01', 'en', null, 'en.g24.will_future', array['en.g24.will_future']::text[], 'translation', 'assessment', 'Anna ne viendra pas à la fête demain.', array['Anna won''t come to the party tomorrow','Anna will not come to the party tomorrow','Tomorrow Anna won''t come to the party','Anna won''t be at the party tomorrow','Anna will not be at the party tomorrow','Anna isn''t going to come to the party tomorrow','Anna is not going to come to the party tomorrow','Anna isn''t coming to the party tomorrow','Anna is not coming to the party tomorrow']::text[], 'Pour dire que quelque chose n''arrivera pas, on utilise won''t (will not) + verbe de base : Anna won''t come. Après won''t, le verbe ne prend ni -s ni to.', 3, '{"id": "en.assess.m05.01", "unitIds": ["en.g24.will_future"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Anna ne viendra pas à la fête demain.", "promptLanguage": "fr", "answer": "Anna won''t come to the party tomorrow", "acceptedAnswers": ["Anna won''t come to the party tomorrow", "Anna will not come to the party tomorrow", "Tomorrow Anna won''t come to the party", "Anna won''t be at the party tomorrow", "Anna will not be at the party tomorrow", "Anna isn''t going to come to the party tomorrow", "Anna is not going to come to the party tomorrow", "Anna isn''t coming to the party tomorrow", "Anna is not coming to the party tomorrow"], "hint": "Pour dire qu''elle ne viendra pas, utilise la forme négative de will.", "explanation": "Pour dire que quelque chose n''arrivera pas, on utilise won''t (will not) + verbe de base : Anna won''t come. Après won''t, le verbe ne prend ni -s ni to.", "tip": "Won''t + verbe de base : l''apostrophe est obligatoire.", "extraExample": {"text": "Tom won''t forget your birthday.", "translation": "Tom n''oubliera pas ton anniversaire."}, "errorPatterns": [{"contains": "wont", "category": "spelling", "feedback": "N''oublie pas l''apostrophe : won''t (will not)."}, {"contains": "does not come", "category": "verb_tense", "feedback": "Doesn''t est un présent simple. Pour dire ce qui n''arrivera pas demain, on utilise won''t : Anna won''t come."}, {"contains": "will not to", "category": "grammar", "feedback": "Après won''t (will not), on ne met pas to : Anna won''t come."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m05.02', 'en', null, 'en.g25.going_to', array['en.g25.going_to']::text[], 'translation', 'assessment', 'Mes parents vont acheter une voiture.', array['My parents are going to buy a car','My parents will buy a car']::text[], 'Pour un projet, on utilise be + going to + verbe de base : are going to buy. Avec my parents (they), be devient are, et buy reste à la forme de base.', 3, '{"id": "en.assess.m05.02", "unitIds": ["en.g25.going_to"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Mes parents vont acheter une voiture.", "promptLanguage": "fr", "answer": "My parents are going to buy a car", "acceptedAnswers": ["My parents are going to buy a car", "My parents will buy a car"], "hint": "My parents se remplace par they : quelle forme de be ?", "explanation": "Pour un projet, on utilise be + going to + verbe de base : are going to buy. Avec my parents (they), be devient are, et buy reste à la forme de base.", "tip": "They are going to + verbe de base : seul be s''accorde.", "extraExample": {"text": "My sister is going to buy a house.", "translation": "Ma sœur va acheter une maison."}, "errorPatterns": [{"contains": "parents is", "category": "conjugation", "feedback": "Parents est au pluriel : on dit my parents are."}, {"contains": "parents going to", "category": "grammar", "feedback": "Il manque are devant going to : My parents are going to buy a car."}, {"contains": "going to bought", "category": "verb_tense", "feedback": "Après going to, le verbe reste à la forme de base, jamais au passé : going to buy."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m05.03', 'en', null, 'en.g26.will_vs_going_to', array['en.g26.will_vs_going_to','en.g25.going_to']::text[], 'fill_blank', 'assessment', 'Oh no! The dog ___ eat the cake!', array['is going to','''s going to']::text[], 'Tu vois le chien regarder le gâteau : un signe visible annonce ce qui va arriver. Pour une prédiction fondée sur ce qu''on voit, on utilise be going to : The dog is going to eat the cake.', 3, '{"id": "en.assess.m05.03", "unitIds": ["en.g26.will_vs_going_to", "en.g25.going_to"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec will ou be going to, à la bonne forme.", "context": "There is a cake on the table. The dog is looking at it.", "prompt": "Oh no! The dog ___ eat the cake!", "promptLanguage": "en", "answer": "is going to", "acceptedAnswers": ["is going to", "''s going to"], "hint": "Tu vois quelque chose en ce moment, et cela te montre ce qui va arriver.", "explanation": "Tu vois le chien regarder le gâteau : un signe visible annonce ce qui va arriver. Pour une prédiction fondée sur ce qu''on voit, on utilise be going to : The dog is going to eat the cake.", "tip": "Un signe visible maintenant : be going to.", "extraExample": {"text": "Look at those dark clouds! It''s going to rain.", "translation": "Regarde ces nuages sombres ! Il va pleuvoir."}, "errorPatterns": [{"equals": "will", "category": "grammar", "feedback": "Tu vois le chien regarder le gâteau : c''est un signe visible. Pour une prédiction avec un signe, on utilise be going to."}, {"equals": "is going", "category": "grammar", "feedback": "Il manque to après going : is going to eat."}, {"equals": "going to", "category": "grammar", "feedback": "Il manque is devant going to : The dog is going to eat the cake."}], "pool": "assessment", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m05.04', 'en', null, 'en.g27.present_continuous_future', array['en.g27.present_continuous_future','en.v.doctor']::text[], 'free_answer', 'assessment', 'Comment dit-on « Mon frère voit le médecin la semaine prochaine. » ?', array['My brother is seeing the doctor next week','Next week my brother is seeing the doctor','My brother is meeting the doctor next week','My brother is going to see the doctor next week','My brother will see the doctor next week','My brother is going to the doctor next week','My brother is going to the doctor''s next week','My brother has an appointment with the doctor next week']::text[], 'Pour un rendez-vous déjà fixé, on utilise le présent continu avec un moment du futur : My brother is seeing the doctor next week. Next week se dit sans the ni préposition.', 3, '{"id": "en.assess.m05.04", "unitIds": ["en.g27.present_continuous_future", "en.v.doctor"], "type": "free_answer", "difficulty": 3, "instruction": "Écris en anglais.", "prompt": "Comment dit-on « Mon frère voit le médecin la semaine prochaine. » ?", "promptLanguage": "fr", "answer": "My brother is seeing the doctor next week", "acceptedAnswers": ["My brother is seeing the doctor next week", "Next week my brother is seeing the doctor", "My brother is meeting the doctor next week", "My brother is going to see the doctor next week", "My brother will see the doctor next week", "My brother is going to the doctor next week", "My brother is going to the doctor''s next week", "My brother has an appointment with the doctor next week"], "hint": "Un rendez-vous fixé se dit avec be + un verbe en -ing. Avec my brother (he), be devient is.", "explanation": "Pour un rendez-vous déjà fixé, on utilise le présent continu avec un moment du futur : My brother is seeing the doctor next week. Next week se dit sans the ni préposition.", "tip": "Rendez-vous fixé : be + -ing + next week / tomorrow.", "extraExample": {"text": "Anna is meeting the dentist at ten.", "translation": "Anna retrouve le dentiste à dix heures."}, "errorPatterns": [{"contains": "brother sees", "category": "verb_tense", "feedback": "Pour un rendez-vous personnel déjà fixé, on utilise le présent continu : My brother is seeing the doctor."}, {"contains": "brother seeing", "category": "grammar", "feedback": "Il manque is devant seeing : My brother is seeing the doctor."}, {"contains": "the next week", "category": "grammar", "feedback": "Dans « la semaine prochaine », on ne met pas the : next week."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m05.05', 'en', null, 'en.g24.will_future', array['en.g24.will_future','en.v.lend','en.v.borrow']::text[], 'mcq', 'assessment', 'Tom: « No problem. I ___ you mine. »', array['will lend']::text[], 'Tom propose sa voiture sur le moment : une proposition se dit avec will. Il donne la voiture pour un temps : il la lend (prête). Borrow serait pour celui qui la prend.', 3, '{"id": "en.assess.m05.05", "unitIds": ["en.g24.will_future", "en.v.lend", "en.v.borrow"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne forme.", "context": "Anna doesn''t have a car tomorrow. Tom has an idea.", "prompt": "Tom: « No problem. I ___ you mine. »", "promptLanguage": "en", "options": ["will lend", "will borrow", "will to lend", "lend"], "answer": "will lend", "acceptedAnswers": ["will lend"], "hint": "La voiture est à Tom : que fait-il pour Anna ? Il décide à l''instant.", "explanation": "Tom propose sa voiture sur le moment : une proposition se dit avec will. Il donne la voiture pour un temps : il la lend (prête). Borrow serait pour celui qui la prend.", "tip": "Proposition sur le moment : will + verbe de base. Je donne pour un temps : lend.", "extraExample": {"text": "Don''t worry, I''ll lend you my bag.", "translation": "Ne t''inquiète pas, je te prêterai mon sac."}, "errorPatterns": [{"equals": "will borrow", "category": "word_confusion", "feedback": "Borrow veut dire « emprunter ». C''est Tom qui possède la voiture : il la prête, donc lend."}, {"equals": "will to lend", "category": "grammar", "feedback": "Après will, on ne met pas to : will lend."}, {"equals": "lend", "category": "verb_tense", "feedback": "Le présent simple ne convient pas pour une proposition sur le futur : on dit will lend."}], "pool": "assessment", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m06.01', 'en', null, 'en.g28.there_is_are', array['en.g28.there_is_are','en.v.sofa']::text[], 'translation', 'assessment', 'Il y a un téléphone et deux clés sur le canapé.', array['There is a phone and two keys on the sofa.','There''s a phone and two keys on the sofa.','There are two keys and a phone on the sofa.','There is a phone and two keys on the couch.','There are two keys and a phone on the couch.']::text[], '« Il y a » se dit there is ou there are : le verbe s''accorde avec le premier élément cité. Après two, le nom prend un -s : two keys.', 3, '{"id": "en.assess.m06.01", "unitIds": ["en.g28.there_is_are", "en.v.sofa"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Il y a un téléphone et deux clés sur le canapé.", "promptLanguage": "fr", "answer": "There is a phone and two keys on the sofa.", "acceptedAnswers": ["There is a phone and two keys on the sofa.", "There''s a phone and two keys on the sofa.", "There are two keys and a phone on the sofa.", "There is a phone and two keys on the couch.", "There are two keys and a phone on the couch."], "hint": "Commence par there is si tu cites d''abord un seul objet.", "explanation": "« Il y a » se dit there is ou there are : le verbe s''accorde avec le premier élément cité. Après two, le nom prend un -s : two keys.", "tip": "Un seul élément en premier : there is ; plusieurs : there are.", "extraExample": {"text": "There are three books and a lamp on the table.", "translation": "Il y a trois livres et une lampe sur la table."}, "errorPatterns": [{"contains": "there have", "category": "grammar", "feedback": "« Il y a » ne se dit pas avec have. Écris there is ou there are."}, {"contains": "there is two", "category": "grammar", "feedback": "Two keys est un pluriel : on dit there are two keys. Si tu cites d''abord le téléphone, tu peux dire there is a phone and two keys."}, {"contains": "two key on", "category": "grammar", "feedback": "Après un nombre supérieur à un, le nom prend un -s : two keys."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m06.02', 'en', null, 'en.g29.some_any', array['en.g29.some_any','en.v.ticket']::text[], 'fill_blank', 'assessment', 'We don''t have ___ tickets for tomorrow.', array['any']::text[], 'Dans une phrase négative, on utilise any : We don''t have any tickets. Some est réservé aux phrases affirmatives et aux demandes polies.', 2, '{"id": "en.assess.m06.02", "unitIds": ["en.g29.some_any", "en.v.ticket"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot (some ou any).", "prompt": "We don''t have ___ tickets for tomorrow.", "promptLanguage": "en", "answer": "any", "acceptedAnswers": ["any"], "hint": "La phrase est négative.", "explanation": "Dans une phrase négative, on utilise any : We don''t have any tickets. Some est réservé aux phrases affirmatives et aux demandes polies.", "tip": "Négation (don''t, isn''t…) : any.", "extraExample": {"text": "I don''t have any questions.", "translation": "Je n''ai pas de questions."}, "errorPatterns": [{"equals": "some", "category": "grammar", "feedback": "Some ne s''utilise pas dans une phrase négative. Après don''t have, on dit any."}, {"equals": "a", "category": "grammar", "feedback": "Tickets est un pluriel : on ne met pas a. On dit any tickets."}, {"equals": "many", "category": "grammar", "feedback": "Many s''utilise dans les questions avec how. Pour « pas de billets », on dit don''t have any tickets."}], "pool": "assessment", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m06.03', 'en', null, 'en.g30.how_much_many', array['en.g30.how_much_many','en.v.price','en.v.ticket']::text[], 'free_answer', 'assessment', 'Comment demande-t-il « Combien coûtent les billets ? » en anglais ?', array['How much are the tickets?','How much are tickets?','How much do the tickets cost?','How much are these tickets?']::text[], 'Pour demander un prix, on dit How much… ?. Avec plusieurs billets, le verbe est are : How much are the tickets ? (How much is… avec un seul billet).', 3, '{"id": "en.assess.m06.03", "unitIds": ["en.g30.how_much_many", "en.v.price", "en.v.ticket"], "type": "free_answer", "difficulty": 3, "context": "Tom is at the station. He wants to know the price of the tickets.", "instruction": "Écris la question en anglais.", "prompt": "Comment demande-t-il « Combien coûtent les billets ? » en anglais ?", "promptLanguage": "fr", "answer": "How much are the tickets?", "acceptedAnswers": ["How much are the tickets?", "How much are tickets?", "How much do the tickets cost?", "How much are these tickets?"], "hint": "Pour un prix, on commence par how much. Tickets est un pluriel.", "explanation": "Pour demander un prix, on dit How much… ?. Avec plusieurs billets, le verbe est are : How much are the tickets ? (How much is… avec un seul billet).", "tip": "Un prix : How much is it ? (un) / How much are they ? (plusieurs).", "extraExample": {"text": "How much are the bags?", "translation": "Combien coûtent les sacs ?"}, "errorPatterns": [{"contains": "how many", "category": "grammar", "feedback": "How many sert à compter des objets. Pour demander un prix, on dit how much."}, {"contains": "how much is the tickets", "category": "grammar", "feedback": "Tickets est un pluriel : on dit are. How much are the tickets ?"}, {"contains": "how much tickets", "category": "grammar", "feedback": "Pour demander le prix, il faut un verbe : How much are the tickets ?"}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m06.04', 'en', null, 'en.g31.time_and_dates', array['en.g31.time_and_dates','en.v.shop']::text[], 'translation', 'assessment', 'Le magasin ouvre à huit heures et quart.', array['The shop opens at quarter past eight.','The shop opens at a quarter past eight.','The shop opens at eight fifteen.','The shop is open at quarter past eight.']::text[], 'Pour dire à quelle heure, on utilise at, puis quarter past eight (8 h 15). On ne dit pas « at eight hours and quarter ».', 3, '{"id": "en.assess.m06.04", "unitIds": ["en.g31.time_and_dates", "en.v.shop"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Le magasin ouvre à huit heures et quart.", "promptLanguage": "fr", "answer": "The shop opens at quarter past eight.", "acceptedAnswers": ["The shop opens at quarter past eight.", "The shop opens at a quarter past eight.", "The shop opens at eight fifteen.", "The shop is open at quarter past eight."], "hint": "À quelle heure ? at + heure. « Et quart » se dit quarter past.", "explanation": "Pour dire à quelle heure, on utilise at, puis quarter past eight (8 h 15). On ne dit pas « at eight hours and quarter ».", "tip": "at + quarter past + heure : at quarter past eight.", "extraExample": {"text": "The party is at half past nine.", "translation": "La fête est à neuf heures et demie."}, "errorPatterns": [{"contains": "eight and quarter", "category": "word_order", "feedback": "On ne dit pas « eight and quarter ». Le quart se place avant l''heure : quarter past eight."}, {"contains": "eight hours", "category": "word_confusion", "feedback": "Hours désigne une durée. Pour l''heure, on dit at quarter past eight."}, {"contains": "quarter to eight", "category": "grammar", "feedback": "Quarter to eight veut dire 7 h 45. Pour 8 h 15, on dit quarter past eight."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m06.05', 'en', null, 'en.g30.how_much_many', array['en.g30.how_much_many','en.v.money']::text[], 'mcq', 'assessment', 'Comment dit-on « Nous n''avons pas beaucoup d''argent. » en anglais ?', array['We don''t have much money.']::text[], 'Money ne se compte pas et ne prend jamais de -s : on utilise much (et non many) dans une phrase négative. Avec we, on dit don''t, pas doesn''t.', 2, '{"id": "en.assess.m06.05", "unitIds": ["en.g30.how_much_many", "en.v.money"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la phrase correcte.", "prompt": "Comment dit-on « Nous n''avons pas beaucoup d''argent. » en anglais ?", "promptLanguage": "fr", "options": ["We don''t have much money.", "We don''t have many money.", "We don''t have much moneys.", "We doesn''t have much money."], "answer": "We don''t have much money.", "acceptedAnswers": ["We don''t have much money."], "hint": "Peut-on compter l''argent : un money, deux moneys ?", "explanation": "Money ne se compte pas et ne prend jamais de -s : on utilise much (et non many) dans une phrase négative. Avec we, on dit don''t, pas doesn''t.", "tip": "Money, luggage, bread : much (jamais many) et jamais de -s.", "extraExample": {"text": "I don''t have much food at home.", "translation": "Je n''ai pas beaucoup de nourriture à la maison."}, "errorPatterns": [{"contains": "many money", "category": "grammar", "feedback": "Many s''utilise avec un pluriel qu''on peut compter. Money ne se compte pas : much money."}, {"contains": "moneys", "category": "grammar", "feedback": "Money ne prend jamais de -s : c''est un nom qu''on ne compte pas. On dit much money."}, {"contains": "we doesn''t", "category": "conjugation", "feedback": "Avec we, on utilise don''t, pas doesn''t : we don''t have."}], "pool": "assessment", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m07.01', 'en', null, 'en.g32.word_order', array['en.g32.word_order']::text[], 'translation', 'assessment', 'Mon père aime beaucoup son nouveau téléphone.', array['My father likes his new phone very much.','My father likes his new phone a lot.','My father very much likes his new phone.','My father loves his new phone.','My dad likes his new phone very much.','My dad likes his new phone a lot.','My dad loves his new phone.']::text[], 'Le verbe et son complément restent ensemble : likes his new phone. Very much se place à la fin, et l''adjectif new se place avant phone. Avec my father, le verbe prend un -s.', 3, '{"id": "en.assess.m07.01", "unitIds": ["en.g32.word_order"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Mon père aime beaucoup son nouveau téléphone.", "promptLanguage": "fr", "answer": "My father likes his new phone very much.", "acceptedAnswers": ["My father likes his new phone very much.", "My father likes his new phone a lot.", "My father very much likes his new phone.", "My father loves his new phone.", "My dad likes his new phone very much.", "My dad likes his new phone a lot.", "My dad loves his new phone."], "hint": "Garde « likes his new phone » ensemble.", "explanation": "Le verbe et son complément restent ensemble : likes his new phone. Very much se place à la fin, et l''adjectif new se place avant phone. Avec my father, le verbe prend un -s.", "tip": "Beaucoup se place à la fin : ... very much.", "extraExample": {"text": "My mother likes her old car very much.", "translation": "Ma mère aime beaucoup sa vieille voiture."}, "errorPatterns": [{"contains": "likes very much", "category": "word_order", "feedback": "Very much ne se place pas entre le verbe et son complément. Mets-le à la fin : likes his new phone very much."}, {"contains": "phone new", "category": "word_order", "feedback": "L''adjectif se place avant le nom : his new phone."}, {"contains": "father like ", "category": "conjugation", "feedback": "Avec my father (3e personne), le verbe prend un -s : likes."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m07.02', 'en', null, 'en.g33.prepositions_place', array['en.g33.prepositions_place','en.g34.prepositions_time']::text[], 'mcq', 'assessment', 'Comment dit-on « Mes parents sont à la maison le dimanche. » en anglais ?', array['My parents are at home on Sunday.']::text[], '« À la maison » est l''expression fixe at home. Pour un jour de la semaine, on utilise on : on Sunday.', 3, '{"id": "en.assess.m07.02", "unitIds": ["en.g33.prepositions_place", "en.g34.prepositions_time"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne traduction.", "prompt": "Comment dit-on « Mes parents sont à la maison le dimanche. » en anglais ?", "promptLanguage": "fr", "options": ["My parents are at home on Sunday.", "My parents are in home on Sunday.", "My parents are at home in Sunday.", "My parents are at home at Sunday."], "answer": "My parents are at home on Sunday.", "acceptedAnswers": ["My parents are at home on Sunday."], "explanation": "« À la maison » est l''expression fixe at home. Pour un jour de la semaine, on utilise on : on Sunday.", "tip": "At home, on Sunday, in January : trois prépositions différentes.", "extraExample": {"text": "My brother is at school on Monday.", "translation": "Mon frère est à l''école le lundi."}, "errorPatterns": [{"equals": "my parents are in home on sunday", "category": "preposition", "feedback": "« À la maison » se dit at home, pas in home."}, {"equals": "my parents are at home in sunday", "category": "preposition", "feedback": "Pour un jour de la semaine, on dit on Sunday, pas in."}, {"equals": "my parents are at home at sunday", "category": "preposition", "feedback": "At sert pour l''heure exacte. Pour un jour de la semaine, on dit on Sunday."}], "pool": "assessment", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m07.03', 'en', null, 'en.g35.question_words', array['en.g35.question_words']::text[], 'translation', 'assessment', 'Pourquoi est-elle fatiguée ?', array['Why is she tired?']::text[], 'Avec be, la question se construit sans do : mot interrogatif + be + sujet. On dit Why is she tired ?', 3, '{"id": "en.assess.m07.03", "unitIds": ["en.g35.question_words"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Pourquoi est-elle fatiguée ?", "promptLanguage": "fr", "answer": "Why is she tired?", "acceptedAnswers": ["Why is she tired?"], "hint": "Avec le verbe be, on inverse be et le sujet.", "explanation": "Avec be, la question se construit sans do : mot interrogatif + be + sujet. On dit Why is she tired ?", "tip": "Avec be, pas de do : Why is she ... ?", "extraExample": {"text": "Why is your brother late?", "translation": "Pourquoi ton frère est-il en retard ?"}, "errorPatterns": [{"contains": "why she is", "category": "word_order", "feedback": "Il faut inverser le verbe et le sujet : Why is she tired?"}, {"contains": "why does she", "category": "grammar", "feedback": "Avec be, on n''utilise pas does : Why is she tired?"}, {"contains": "why she tired", "category": "grammar", "feedback": "Il manque le verbe be : Why is she tired?"}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m07.04', 'en', null, 'en.g37.comparatives_superlatives', array['en.g37.comparatives_superlatives']::text[], 'translation', 'assessment', 'C''est le plus grand parc de la ville.', array['It is the biggest park in the city.','It is the largest park in the city.','This is the biggest park in the city.','That is the biggest park in the city.','This is the largest park in the city.','That is the largest park in the city.']::text[], 'Big est un adjectif court : on double le g et on ajoute -est avec the : the biggest. Après un superlatif, on dit in the city (et non of the city).', 4, '{"id": "en.assess.m07.04", "unitIds": ["en.g37.comparatives_superlatives"], "type": "translation", "difficulty": 4, "instruction": "Traduis en anglais.", "prompt": "C''est le plus grand parc de la ville.", "promptLanguage": "fr", "answer": "It is the biggest park in the city.", "acceptedAnswers": ["It is the biggest park in the city.", "It is the largest park in the city.", "This is the biggest park in the city.", "That is the biggest park in the city.", "This is the largest park in the city.", "That is the largest park in the city."], "hint": "Big double son g. Après un superlatif, « de la ville » se dit in the city.", "explanation": "Big est un adjectif court : on double le g et on ajoute -est avec the : the biggest. Après un superlatif, on dit in the city (et non of the city).", "tip": "Superlatif court : the + -est. Et on dit in the city.", "extraExample": {"text": "It is the oldest building in the street.", "translation": "C''est le plus vieux bâtiment de la rue."}, "errorPatterns": [{"contains": "most big", "category": "grammar", "feedback": "Big est un adjectif court : on ajoute -est (biggest), on n''utilise pas most."}, {"contains": "bigest", "category": "spelling", "feedback": "Avec big, on double le g avant -est : biggest."}, {"contains": "of the city", "category": "preposition", "feedback": "Après un superlatif, « de la ville » se dit in the city."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m07.05', 'en', null, 'en.g38.should_could', array['en.g38.should_could']::text[], 'free_answer', 'assessment', 'Tu devrais appeler le docteur.', array['You should call the doctor.','You should call a doctor.','You should phone the doctor.','You should phone a doctor.']::text[], 'Should donne un conseil. Il est suivi du verbe de base, sans to : You should call the doctor.', 3, '{"id": "en.assess.m07.05", "unitIds": ["en.g38.should_could"], "type": "free_answer", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Tu devrais appeler le docteur.", "promptLanguage": "fr", "answer": "You should call the doctor.", "acceptedAnswers": ["You should call the doctor.", "You should call a doctor.", "You should phone the doctor.", "You should phone a doctor."], "hint": "Devrais se dit should, suivi du verbe de base.", "explanation": "Should donne un conseil. Il est suivi du verbe de base, sans to : You should call the doctor.", "tip": "Should + verbe de base : jamais de to.", "extraExample": {"text": "You should open the window.", "translation": "Tu devrais ouvrir la fenêtre."}, "errorPatterns": [{"contains": "should to", "category": "grammar", "feedback": "Après should, on ne met pas to : You should call the doctor."}, {"contains": "should calls", "category": "conjugation", "feedback": "Après should, le verbe reste à la forme de base : call, sans -s."}, {"contains": "call to", "category": "grammar", "feedback": "En anglais, on dit call the doctor, sans to."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m08.01', 'en', null, 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro']::text[], 'translation', 'assessment', 'Je n''ai jamais mangé de sushis.', array['I have never eaten sushi.','I haven''t eaten sushi.','I have never tried sushi.','I have never had sushi.','I haven''t had sushi.']::text[], 'On parle d''une expérience de vie, sans date : present perfect. Never se place entre have et le participe passé de eat : eaten.', 3, '{"id": "en.assess.m08.01", "unitIds": ["en.g39.present_perfect_intro"], "type": "translation", "difficulty": 3, "instruction": "Traduis en anglais.", "prompt": "Je n''ai jamais mangé de sushis.", "promptLanguage": "fr", "answer": "I have never eaten sushi.", "acceptedAnswers": ["I have never eaten sushi.", "I haven''t eaten sushi.", "I have never tried sushi.", "I have never had sushi.", "I haven''t had sushi."], "hint": "Jamais + expérience de vie : have never + participe passé.", "explanation": "On parle d''une expérience de vie, sans date : present perfect. Never se place entre have et le participe passé de eat : eaten.", "tip": "Eat – ate – eaten : après have, on utilise eaten.", "extraExample": {"text": "Ben has never eaten cake for breakfast.", "translation": "Ben n''a jamais mangé de gâteau au petit déjeuner."}, "errorPatterns": [{"contains": "never ate", "category": "conjugation", "feedback": "Ate est le past simple. Après have, il faut le participe passé : eaten."}, {"contains": "never eat sushi", "category": "conjugation", "feedback": "Après have, il faut le participe passé : eaten, pas eat."}, {"contains": "never eated", "category": "spelling", "feedback": "Eat est irrégulier : on n''ajoute pas -ed. Le participe passé est eaten."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m08.02', 'en', null, 'en.g41.tense_contrast', array['en.g41.tense_contrast']::text[], 'fill_blank', 'assessment', 'Ben ___ me a long message yesterday. (send)', array['sent']::text[], 'Yesterday donne un moment précis dans le passé : on utilise le past simple. Send est irrégulier : sent.', 3, '{"id": "en.assess.m08.02", "unitIds": ["en.g41.tense_contrast"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la bonne forme du verbe entre parenthèses.", "prompt": "Ben ___ me a long message yesterday. (send)", "promptLanguage": "en", "answer": "sent", "acceptedAnswers": ["sent"], "hint": "Yesterday est un moment précis du passé.", "explanation": "Yesterday donne un moment précis dans le passé : on utilise le past simple. Send est irrégulier : sent.", "tip": "Yesterday = past simple ; send – sent – sent.", "extraExample": {"text": "Lucy sent a photo to her mother last week.", "translation": "Lucy a envoyé une photo à sa mère la semaine dernière."}, "errorPatterns": [{"equals": "send", "category": "verb_tense", "feedback": "Send est la forme de base. Avec yesterday, il faut le past simple : sent."}, {"equals": "sended", "category": "conjugation", "feedback": "Send est irrégulier : le past simple est sent, pas sended."}, {"equals": "has sent", "category": "verb_tense", "feedback": "Avec yesterday, on n''utilise pas le present perfect. Le past simple suffit : sent."}], "pool": "assessment", "lessonId": null, "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m08.03', 'en', null, 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro']::text[], 'free_answer', 'assessment', 'Comment dit-on « Je viens d''arriver » en anglais ?', array['I have just arrived.','I just arrived.']::text[], 'Pour « venir de », on utilise have just + participe passé : arrived. Just se place entre have et le participe passé.', 4, '{"id": "en.assess.m08.03", "unitIds": ["en.g39.present_perfect_intro"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la phrase en anglais.", "prompt": "Comment dit-on « Je viens d''arriver » en anglais ?", "promptLanguage": "fr", "answer": "I have just arrived.", "acceptedAnswers": ["I have just arrived.", "I just arrived."], "hint": "« Venir de » = have + just + participe passé.", "explanation": "Pour « venir de », on utilise have just + participe passé : arrived. Just se place entre have et le participe passé.", "tip": "Je viens de… = I have just + participe passé.", "extraExample": {"text": "My brother has just left.", "translation": "Mon frère vient de partir."}, "errorPatterns": [{"contains": "i come to", "category": "vocabulary", "feedback": "« Je viens de » ne se traduit pas avec come. On dit I have just + participe passé."}, {"contains": "just arrive at", "category": "conjugation", "feedback": "Après have just, il faut le participe passé : arrived."}, {"contains": "arrived just", "category": "word_order", "feedback": "Just se place entre have et le participe passé : have just arrived."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m08.04', 'en', null, 'en.g39.present_perfect_intro', array['en.g39.present_perfect_intro','en.g41.tense_contrast']::text[], 'mcq', 'assessment', 'What hasn''t Anna found?', array['Her passport.']::text[], 'Le texte dit « she hasn''t found her passport yet » : elle n''a pas encore trouvé son passeport. Son billet, lui, est déjà acheté (has just bought a ticket).', 4, '{"id": "en.assess.m08.04", "unitIds": ["en.g39.present_perfect_intro", "en.g41.tense_contrast"], "type": "mcq", "difficulty": 4, "instruction": "Lis le texte, puis choisis la bonne réponse.", "context": "Anna is at the airport. She has just bought a ticket, but she hasn''t found her passport yet. Her flight leaves in one hour.", "prompt": "What hasn''t Anna found?", "promptLanguage": "en", "options": ["Her passport.", "Her ticket.", "Her flight.", "Her bag."], "answer": "Her passport.", "acceptedAnswers": ["Her passport."], "hint": "Cherche hasn''t found dans le texte.", "explanation": "Le texte dit « she hasn''t found her passport yet » : elle n''a pas encore trouvé son passeport. Son billet, lui, est déjà acheté (has just bought a ticket).", "tip": "Not … yet = pas encore ; just = venir de.", "extraExample": {"text": "Tom hasn''t called the dentist yet.", "translation": "Tom n''a pas encore appelé le dentiste."}, "errorPatterns": [{"equals": "her ticket", "category": "instruction", "feedback": "Anna a just bought a ticket : son billet est acheté. C''est le passeport qu''elle n''a pas encore trouvé."}, {"equals": "her flight", "category": "instruction", "feedback": "Le texte dit seulement que son vol part dans une heure. Ce qu''elle n''a pas trouvé, c''est son passeport."}, {"equals": "her bag", "category": "instruction", "feedback": "Le texte ne parle pas de son sac. Elle n''a pas encore trouvé son passeport."}], "pool": "assessment", "lessonId": null, "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('en.assess.m08.05', 'en', null, 'en.g40.short_answers', array['en.g40.short_answers','en.g39.present_perfect_intro']::text[], 'free_answer', 'assessment', 'Réponds « non, pas encore » à la question : « Have you finished your homework yet? »', array['No, I haven''t.','No, I have not.','No, not yet.','Not yet.','No, I haven''t finished yet.','No, I haven''t finished it yet.','No, I haven''t finished my homework yet.']::text[], 'La question est au present perfect (Have you…?) : la réponse courte reprend have. Réponse négative : No, I haven''t. On peut aussi dire Not yet.', 4, '{"id": "en.assess.m08.05", "unitIds": ["en.g40.short_answers", "en.g39.present_perfect_intro"], "type": "free_answer", "difficulty": 4, "instruction": "Réponds par une réponse courte en anglais.", "prompt": "Réponds « non, pas encore » à la question : « Have you finished your homework yet? »", "promptLanguage": "fr", "answer": "No, I haven''t.", "acceptedAnswers": ["No, I haven''t.", "No, I have not.", "No, not yet.", "Not yet.", "No, I haven''t finished yet.", "No, I haven''t finished it yet.", "No, I haven''t finished my homework yet."], "hint": "La question commence par Have : reprends have.", "explanation": "La question est au present perfect (Have you…?) : la réponse courte reprend have. Réponse négative : No, I haven''t. On peut aussi dire Not yet.", "tip": "Have you…? → Yes, I have. / No, I haven''t.", "extraExample": {"text": "Has Tom called you yet? — No, he hasn''t.", "translation": "Tom t''a-t-il déjà appelé ? — Non, pas encore."}, "errorPatterns": [{"contains": "no i don''t", "category": "grammar", "feedback": "La question commence par Have, pas par Do : on répond No, I haven''t."}, {"contains": "no i didn''t", "category": "grammar", "feedback": "La question commence par Have, pas par Did : on répond No, I haven''t."}, {"contains": "no i''m not", "category": "grammar", "feedback": "La question commence par Have, pas par Are : on répond No, I haven''t."}], "pool": "assessment", "lessonId": null, "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.hello', 'en', 'hello', 'bonjour', 'On dit hello pour saluer quelqu''un, à n''importe quel moment de la journée.', '[{"text": "Hello, Anna!", "translation": "Bonjour, Anna !"}, {"text": "Hello, I am Tom.", "translation": "Bonjour, je suis Tom."}]'::jsonb, '/həˈləʊ/', '{"id": "en.d.hello", "word": "hello", "translation": "bonjour", "otherTranslations": ["salut", "allô (au téléphone)"], "partOfSpeech": "interjection", "ipa": "/həˈləʊ/", "explanation": "On dit hello pour saluer quelqu''un, à n''importe quel moment de la journée.", "examples": [{"text": "Hello, Anna!", "translation": "Bonjour, Anna !"}, {"text": "Hello, I am Tom.", "translation": "Bonjour, je suis Tom."}], "confusions": [{"word": "hi", "note": "version plus familière de hello : salut."}], "unitId": "en.v.hello"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.goodbye', 'en', 'goodbye', 'au revoir', 'On dit goodbye pour dire au revoir quand on part ou quand quelqu''un part.', '[{"text": "Goodbye, Tom.", "translation": "Au revoir, Tom."}, {"text": "Goodbye, children!", "translation": "Au revoir, les enfants !"}]'::jsonb, '/ˌɡʊdˈbaɪ/', '{"id": "en.d.goodbye", "word": "goodbye", "translation": "au revoir", "otherTranslations": [], "partOfSpeech": "interjection", "ipa": "/ˌɡʊdˈbaɪ/", "explanation": "On dit goodbye pour dire au revoir quand on part ou quand quelqu''un part.", "examples": [{"text": "Goodbye, Tom.", "translation": "Au revoir, Tom."}, {"text": "Goodbye, children!", "translation": "Au revoir, les enfants !"}], "confusions": [{"word": "bye", "note": "version plus courte et familière : salut."}], "unitId": "en.v.goodbye"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.thank_you', 'en', 'thank you', 'merci', 'On dit thank you pour remercier quelqu''un ; le th se prononce en plaçant la langue entre les dents.', '[{"text": "Thank you, Anna.", "translation": "Merci, Anna."}, {"text": "A book, please. Thank you!", "translation": "Un livre, s''il vous plaît. Merci !"}]'::jsonb, '/ˈθæŋk juː/', '{"id": "en.d.thank_you", "word": "thank you", "translation": "merci", "otherTranslations": ["je te remercie"], "partOfSpeech": "expression", "ipa": "/ˈθæŋk juː/", "explanation": "On dit thank you pour remercier quelqu''un ; le th se prononce en plaçant la langue entre les dents.", "examples": [{"text": "Thank you, Anna.", "translation": "Merci, Anna."}, {"text": "A book, please. Thank you!", "translation": "Un livre, s''il vous plaît. Merci !"}], "confusions": [{"word": "thanks", "note": "forme plus familière de thank you : merci."}], "unitId": "en.v.thank_you"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.please', 'en', 'please', 's''il te plaît / s''il vous plaît', 'Please rend une demande polie ; il se place au début ou à la fin de la phrase.', '[{"text": "A bag, please.", "translation": "Un sac, s''il vous plaît."}, {"text": "Please, a key.", "translation": "S''il te plaît, une clé."}]'::jsonb, '/pliːz/', '{"id": "en.d.please", "word": "please", "translation": "s''il te plaît / s''il vous plaît", "otherTranslations": [], "partOfSpeech": "adverb", "ipa": "/pliːz/", "explanation": "Please rend une demande polie ; il se place au début ou à la fin de la phrase.", "examples": [{"text": "A bag, please.", "translation": "Un sac, s''il vous plaît."}, {"text": "Please, a key.", "translation": "S''il te plaît, une clé."}], "confusions": [], "unitId": "en.v.please"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.sorry', 'en', 'sorry', 'désolé', 'On est sorry quand on regrette quelque chose ou pour s''excuser : I am sorry.', '[{"text": "I am sorry.", "translation": "Je suis désolé."}, {"text": "We are sorry, teacher.", "translation": "Nous sommes désolés, professeur."}]'::jsonb, '/ˈsɒri/', '{"id": "en.d.sorry", "word": "sorry", "translation": "désolé", "otherTranslations": ["pardon (après une erreur)"], "partOfSpeech": "adjective", "ipa": "/ˈsɒri/", "explanation": "On est sorry quand on regrette quelque chose ou pour s''excuser : I am sorry.", "examples": [{"text": "I am sorry.", "translation": "Je suis désolé."}, {"text": "We are sorry, teacher.", "translation": "Nous sommes désolés, professeur."}], "confusions": [{"word": "excuse me", "note": "sert à attirer l''attention ou à passer devant quelqu''un ; sorry s''emploie après une erreur."}], "unitId": "en.v.sorry"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.man', 'en', 'man', 'homme', 'Un man est un homme adulte ; le pluriel est irrégulier : men.', '[{"text": "The man is a teacher.", "translation": "L''homme est professeur."}, {"text": "A man and a child are at home.", "translation": "Un homme et un enfant sont à la maison."}]'::jsonb, '/mæn/', '{"id": "en.d.man", "word": "man", "translation": "homme", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/mæn/", "explanation": "Un man est un homme adulte ; le pluriel est irrégulier : men.", "examples": [{"text": "The man is a teacher.", "translation": "L''homme est professeur."}, {"text": "A man and a child are at home.", "translation": "Un homme et un enfant sont à la maison."}], "confusions": [{"word": "men", "note": "pluriel de man : des hommes."}], "forms": {"plural": "men"}, "unitId": "en.v.man"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.woman', 'en', 'woman', 'femme', 'Une woman est une femme adulte ; le pluriel est irrégulier : women, qui se prononce /ˈwɪmɪn/.', '[{"text": "The woman is happy.", "translation": "La femme est heureuse."}, {"text": "A woman and a man are ready.", "translation": "Une femme et un homme sont prêts."}]'::jsonb, '/ˈwʊmən/', '{"id": "en.d.woman", "word": "woman", "translation": "femme", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈwʊmən/", "explanation": "Une woman est une femme adulte ; le pluriel est irrégulier : women, qui se prononce /ˈwɪmɪn/.", "examples": [{"text": "The woman is happy.", "translation": "La femme est heureuse."}, {"text": "A woman and a man are ready.", "translation": "Une femme et un homme sont prêts."}], "confusions": [{"word": "wife", "note": "wife = l''épouse de quelqu''un ; woman = une femme en général."}], "forms": {"plural": "women"}, "unitId": "en.v.woman"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.child', 'en', 'child', 'enfant', 'Un child est un enfant ; le pluriel est irrégulier : children.', '[{"text": "The child is tired.", "translation": "L''enfant est fatigué."}, {"text": "A child is at school.", "translation": "Un enfant est à l''école."}]'::jsonb, '/tʃaɪld/', '{"id": "en.d.child", "word": "child", "translation": "enfant", "otherTranslations": ["gamin"], "partOfSpeech": "noun", "ipa": "/tʃaɪld/", "explanation": "Un child est un enfant ; le pluriel est irrégulier : children.", "examples": [{"text": "The child is tired.", "translation": "L''enfant est fatigué."}, {"text": "A child is at school.", "translation": "Un enfant est à l''école."}], "confusions": [{"word": "kid", "note": "mot familier pour enfant, très courant à l''oral."}], "forms": {"plural": "children"}, "unitId": "en.v.child"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.friend', 'en', 'friend', 'ami / amie', 'Friend désigne un ami ou une amie : le mot ne change pas selon le genre.', '[{"text": "Anna is my friend.", "translation": "Anna est mon amie."}, {"text": "A friend is at the house.", "translation": "Un ami est à la maison."}]'::jsonb, '/frend/', '{"id": "en.d.friend", "word": "friend", "translation": "ami / amie", "otherTranslations": ["copain, copine"], "partOfSpeech": "noun", "ipa": "/frend/", "explanation": "Friend désigne un ami ou une amie : le mot ne change pas selon le genre.", "examples": [{"text": "Anna is my friend.", "translation": "Anna est mon amie."}, {"text": "A friend is at the house.", "translation": "Un ami est à la maison."}], "confusions": [{"word": "boyfriend / girlfriend", "note": "petit ami / petite amie (relation amoureuse), pas simplement un ami."}], "forms": {"plural": "friends"}, "unitId": "en.v.friend"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.name', 'en', 'name', 'nom, prénom', 'Name est le mot pour le nom ou le prénom d''une personne, d''un animal ou d''une chose.', '[{"text": "My name is Tom.", "translation": "Je m''appelle Tom."}, {"text": "Her name is Anna.", "translation": "Elle s''appelle Anna."}]'::jsonb, '/neɪm/', '{"id": "en.d.name", "word": "name", "translation": "nom, prénom", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/neɪm/", "explanation": "Name est le mot pour le nom ou le prénom d''une personne, d''un animal ou d''une chose.", "examples": [{"text": "My name is Tom.", "translation": "Je m''appelle Tom."}, {"text": "Her name is Anna.", "translation": "Elle s''appelle Anna."}], "confusions": [], "forms": {"plural": "names"}, "unitId": "en.v.name"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.happy', 'en', 'happy', 'heureux, content', 'Happy décrit quelqu''un qui est content ; il s''emploie avec le verbe être.', '[{"text": "I am happy.", "translation": "Je suis content."}, {"text": "The family is happy.", "translation": "La famille est heureuse."}]'::jsonb, '/ˈhæpi/', '{"id": "en.d.happy", "word": "happy", "translation": "heureux, content", "otherTranslations": [], "partOfSpeech": "adjective", "ipa": "/ˈhæpi/", "explanation": "Happy décrit quelqu''un qui est content ; il s''emploie avec le verbe être.", "examples": [{"text": "I am happy.", "translation": "Je suis content."}, {"text": "The family is happy.", "translation": "La famille est heureuse."}], "confusions": [], "forms": {"comparative": "happier", "superlative": "happiest"}, "unitId": "en.v.happy"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.tired', 'en', 'tired', 'fatigué', 'Tired décrit quelqu''un qui a besoin de se reposer.', '[{"text": "I am tired.", "translation": "Je suis fatigué."}, {"text": "The teacher is tired.", "translation": "Le professeur est fatigué."}]'::jsonb, '/ˈtaɪəd/', '{"id": "en.d.tired", "word": "tired", "translation": "fatigué", "otherTranslations": [], "partOfSpeech": "adjective", "ipa": "/ˈtaɪəd/", "explanation": "Tired décrit quelqu''un qui a besoin de se reposer.", "examples": [{"text": "I am tired.", "translation": "Je suis fatigué."}, {"text": "The teacher is tired.", "translation": "Le professeur est fatigué."}], "confusions": [], "unitId": "en.v.tired"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.ready', 'en', 'ready', 'prêt', 'Ready veut dire prêt : on peut commencer ou partir.', '[{"text": "We are ready.", "translation": "Nous sommes prêts."}, {"text": "Are you ready?", "translation": "Es-tu prêt ?"}]'::jsonb, '/ˈredi/', '{"id": "en.d.ready", "word": "ready", "translation": "prêt", "otherTranslations": [], "partOfSpeech": "adjective", "ipa": "/ˈredi/", "explanation": "Ready veut dire prêt : on peut commencer ou partir.", "examples": [{"text": "We are ready.", "translation": "Nous sommes prêts."}, {"text": "Are you ready?", "translation": "Es-tu prêt ?"}], "confusions": [], "unitId": "en.v.ready"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.student', 'en', 'student', 'étudiant, élève', 'Un student est une personne qui étudie, à l''école ou à l''université.', '[{"text": "He is a student.", "translation": "Il est étudiant."}, {"text": "The student is ready.", "translation": "L''étudiant est prêt."}]'::jsonb, '/ˈstjuːdənt/', '{"id": "en.d.student", "word": "student", "translation": "étudiant, élève", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈstjuːdənt/", "explanation": "Un student est une personne qui étudie, à l''école ou à l''université.", "examples": [{"text": "He is a student.", "translation": "Il est étudiant."}, {"text": "The student is ready.", "translation": "L''étudiant est prêt."}], "confusions": [{"word": "pupil", "note": "élève à l''école ; student est plus général."}], "forms": {"plural": "students"}, "unitId": "en.v.student"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.teacher', 'en', 'teacher', 'professeur, enseignant', 'Un teacher est une personne qui enseigne ; le mot est le même pour un homme et pour une femme.', '[{"text": "She is a teacher.", "translation": "Elle est professeur."}, {"text": "The teacher is late.", "translation": "Le professeur est en retard."}]'::jsonb, '/ˈtiːtʃə/', '{"id": "en.d.teacher", "word": "teacher", "translation": "professeur, enseignant", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈtiːtʃə/", "explanation": "Un teacher est une personne qui enseigne ; le mot est le même pour un homme et pour une femme.", "examples": [{"text": "She is a teacher.", "translation": "Elle est professeur."}, {"text": "The teacher is late.", "translation": "Le professeur est en retard."}], "confusions": [{"word": "professor", "note": "professeur d''université ; teacher est plus général."}], "forms": {"plural": "teachers"}, "unitId": "en.v.teacher"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.mother', 'en', 'mother', 'mère', 'Mother est le mot pour mère ; le th se prononce comme un d doux, avec la langue entre les dents.', '[{"text": "The mother is at home.", "translation": "La mère est à la maison."}, {"text": "She is a mother and a teacher.", "translation": "Elle est mère et professeur."}]'::jsonb, '/ˈmʌðə/', '{"id": "en.d.mother", "word": "mother", "translation": "mère", "otherTranslations": ["maman"], "partOfSpeech": "noun", "ipa": "/ˈmʌðə/", "explanation": "Mother est le mot pour mère ; le th se prononce comme un d doux, avec la langue entre les dents.", "examples": [{"text": "The mother is at home.", "translation": "La mère est à la maison."}, {"text": "She is a mother and a teacher.", "translation": "Elle est mère et professeur."}], "confusions": [{"word": "mum / mom", "note": "maman, mots familiers : mum en anglais britannique, mom en américain."}], "forms": {"plural": "mothers"}, "unitId": "en.v.mother"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.father', 'en', 'father', 'père', 'Father est le mot pour père ; à l''oral, on dit souvent dad.', '[{"text": "The father is tired.", "translation": "Le père est fatigué."}, {"text": "He is a father.", "translation": "Il est père."}]'::jsonb, '/ˈfɑːðə/', '{"id": "en.d.father", "word": "father", "translation": "père", "otherTranslations": ["papa"], "partOfSpeech": "noun", "ipa": "/ˈfɑːðə/", "explanation": "Father est le mot pour père ; à l''oral, on dit souvent dad.", "examples": [{"text": "The father is tired.", "translation": "Le père est fatigué."}, {"text": "He is a father.", "translation": "Il est père."}], "confusions": [{"word": "dad", "note": "papa, mot familier."}], "forms": {"plural": "fathers"}, "unitId": "en.v.father"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.brother', 'en', 'brother', 'frère', 'Un brother est un garçon qui a les mêmes parents que toi : un frère.', '[{"text": "Tom is a brother and a friend.", "translation": "Tom est un frère et un ami."}, {"text": "The brother is happy.", "translation": "Le frère est content."}]'::jsonb, '/ˈbrʌðə/', '{"id": "en.d.brother", "word": "brother", "translation": "frère", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈbrʌðə/", "explanation": "Un brother est un garçon qui a les mêmes parents que toi : un frère.", "examples": [{"text": "Tom is a brother and a friend.", "translation": "Tom est un frère et un ami."}, {"text": "The brother is happy.", "translation": "Le frère est content."}], "confusions": [], "forms": {"plural": "brothers"}, "unitId": "en.v.brother"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.sister', 'en', 'sister', 'sœur', 'Une sister est une fille qui a les mêmes parents que toi : une sœur.', '[{"text": "Anna is a sister and a student.", "translation": "Anna est sœur et étudiante."}, {"text": "The sister is ready.", "translation": "La sœur est prête."}]'::jsonb, '/ˈsɪstə/', '{"id": "en.d.sister", "word": "sister", "translation": "sœur", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈsɪstə/", "explanation": "Une sister est une fille qui a les mêmes parents que toi : une sœur.", "examples": [{"text": "Anna is a sister and a student.", "translation": "Anna est sœur et étudiante."}, {"text": "The sister is ready.", "translation": "La sœur est prête."}], "confusions": [], "forms": {"plural": "sisters"}, "unitId": "en.v.sister"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.family', 'en', 'family', 'famille', 'Family désigne le père, la mère, les enfants et les proches ; le pluriel est families.', '[{"text": "We are a family.", "translation": "Nous sommes une famille."}, {"text": "The family is at home.", "translation": "La famille est à la maison."}]'::jsonb, '/ˈfæməli/', '{"id": "en.d.family", "word": "family", "translation": "famille", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈfæməli/", "explanation": "Family désigne le père, la mère, les enfants et les proches ; le pluriel est families.", "examples": [{"text": "We are a family.", "translation": "Nous sommes une famille."}, {"text": "The family is at home.", "translation": "La famille est à la maison."}], "confusions": [], "forms": {"plural": "families"}, "unitId": "en.v.family"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.late', 'en', 'late', 'en retard', 'Late veut dire en retard, ou tard dans la journée : I am late, it is late.', '[{"text": "I am late.", "translation": "Je suis en retard."}, {"text": "It is late.", "translation": "Il est tard."}]'::jsonb, '/leɪt/', '{"id": "en.d.late", "word": "late", "translation": "en retard", "otherTranslations": ["tard"], "partOfSpeech": "adjective", "ipa": "/leɪt/", "explanation": "Late veut dire en retard, ou tard dans la journée : I am late, it is late.", "examples": [{"text": "I am late.", "translation": "Je suis en retard."}, {"text": "It is late.", "translation": "Il est tard."}], "confusions": [], "forms": {"comparative": "later", "superlative": "latest"}, "unitId": "en.v.late"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.busy', 'en', 'busy', 'occupé', 'Busy veut dire occupé, qui a beaucoup de choses à faire ; le u se prononce comme un i.', '[{"text": "The teacher is busy.", "translation": "Le professeur est occupé."}, {"text": "We are not busy.", "translation": "Nous ne sommes pas occupés."}]'::jsonb, '/ˈbɪzi/', '{"id": "en.d.busy", "word": "busy", "translation": "occupé", "otherTranslations": [], "partOfSpeech": "adjective", "ipa": "/ˈbɪzi/", "explanation": "Busy veut dire occupé, qui a beaucoup de choses à faire ; le u se prononce comme un i.", "examples": [{"text": "The teacher is busy.", "translation": "Le professeur est occupé."}, {"text": "We are not busy.", "translation": "Nous ne sommes pas occupés."}], "confusions": [], "forms": {"comparative": "busier", "superlative": "busiest"}, "unitId": "en.v.busy"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.hungry', 'en', 'hungry', 'qui a faim', 'On dit I am hungry pour « j''ai faim » : l''anglais utilise le verbe être, pas avoir.', '[{"text": "I am hungry.", "translation": "J''ai faim."}, {"text": "The children are hungry.", "translation": "Les enfants ont faim."}]'::jsonb, '/ˈhʌŋɡri/', '{"id": "en.d.hungry", "word": "hungry", "translation": "qui a faim", "otherTranslations": ["affamé"], "partOfSpeech": "adjective", "ipa": "/ˈhʌŋɡri/", "explanation": "On dit I am hungry pour « j''ai faim » : l''anglais utilise le verbe être, pas avoir.", "examples": [{"text": "I am hungry.", "translation": "J''ai faim."}, {"text": "The children are hungry.", "translation": "Les enfants ont faim."}], "confusions": [], "forms": {"comparative": "hungrier", "superlative": "hungriest"}, "unitId": "en.v.hungry"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.cold', 'en', 'cold', 'froid', 'On dit I am cold pour « j''ai froid » et it is cold pour « il fait froid ».', '[{"text": "I am cold.", "translation": "J''ai froid."}, {"text": "It is cold at home.", "translation": "Il fait froid à la maison."}]'::jsonb, '/kəʊld/', '{"id": "en.d.cold", "word": "cold", "translation": "froid", "otherTranslations": ["un rhume (nom)"], "partOfSpeech": "adjective", "ipa": "/kəʊld/", "explanation": "On dit I am cold pour « j''ai froid » et it is cold pour « il fait froid ».", "examples": [{"text": "I am cold.", "translation": "J''ai froid."}, {"text": "It is cold at home.", "translation": "Il fait froid à la maison."}], "confusions": [], "forms": {"comparative": "colder", "superlative": "coldest"}, "unitId": "en.v.cold"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.right', 'en', 'right', 'juste, correct', 'On dit you are right pour « tu as raison » ; right veut aussi dire juste, correct.', '[{"text": "You are right.", "translation": "Tu as raison."}, {"text": "Is the name right?", "translation": "Le nom est-il correct ?"}]'::jsonb, '/raɪt/', '{"id": "en.d.right", "word": "right", "translation": "juste, correct", "otherTranslations": ["qui a raison", "droite, à droite"], "partOfSpeech": "adjective", "ipa": "/raɪt/", "explanation": "On dit you are right pour « tu as raison » ; right veut aussi dire juste, correct.", "examples": [{"text": "You are right.", "translation": "Tu as raison."}, {"text": "Is the name right?", "translation": "Le nom est-il correct ?"}], "confusions": [{"word": "write", "note": "même prononciation /raɪt/ : write veut dire écrire."}], "unitId": "en.v.right"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.car', 'en', 'car', 'voiture', 'Car veut dire voiture ; ce n''est pas le « car » (autocar), qui se dit coach ou bus.', '[{"text": "I have a car.", "translation": "J''ai une voiture."}, {"text": "The car is at home.", "translation": "La voiture est à la maison."}]'::jsonb, '/kɑː/', '{"id": "en.d.car", "word": "car", "translation": "voiture", "otherTranslations": ["auto"], "partOfSpeech": "noun", "ipa": "/kɑː/", "explanation": "Car veut dire voiture ; ce n''est pas le « car » (autocar), qui se dit coach ou bus.", "examples": [{"text": "I have a car.", "translation": "J''ai une voiture."}, {"text": "The car is at home.", "translation": "La voiture est à la maison."}], "confusions": [{"word": "coach", "note": "autocar : on dit coach ou bus, pas car."}], "forms": {"plural": "cars"}, "unitId": "en.v.car"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.house', 'en', 'house', 'maison (le bâtiment)', 'House désigne le bâtiment dans lequel on habite ; le pluriel houses se prononce /ˈhaʊzɪz/.', '[{"text": "We have a house.", "translation": "Nous avons une maison."}, {"text": "The house is cold.", "translation": "La maison est froide."}]'::jsonb, '/haʊs/', '{"id": "en.d.house", "word": "house", "translation": "maison (le bâtiment)", "otherTranslations": ["logement"], "partOfSpeech": "noun", "ipa": "/haʊs/", "explanation": "House désigne le bâtiment dans lequel on habite ; le pluriel houses se prononce /ˈhaʊzɪz/.", "examples": [{"text": "We have a house.", "translation": "Nous avons une maison."}, {"text": "The house is cold.", "translation": "La maison est froide."}], "confusions": [{"word": "home", "note": "chez soi, le foyer : on dit at home."}], "forms": {"plural": "houses"}, "unitId": "en.v.house"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.home', 'en', 'home', 'chez soi, foyer', 'Home est l''endroit où l''on habite, « chez soi » ; on dit at home, sans the.', '[{"text": "She is at home.", "translation": "Elle est à la maison."}, {"text": "We are happy at home.", "translation": "Nous sommes heureux chez nous."}]'::jsonb, '/həʊm/', '{"id": "en.d.home", "word": "home", "translation": "chez soi, foyer", "otherTranslations": ["à la maison (at home)"], "partOfSpeech": "noun", "ipa": "/həʊm/", "explanation": "Home est l''endroit où l''on habite, « chez soi » ; on dit at home, sans the.", "examples": [{"text": "She is at home.", "translation": "Elle est à la maison."}, {"text": "We are happy at home.", "translation": "Nous sommes heureux chez nous."}], "confusions": [{"word": "house", "note": "le bâtiment : a house ; home = chez soi."}], "forms": {"plural": "homes"}, "unitId": "en.v.home"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.dog', 'en', 'dog', 'chien', 'Un dog est un chien, l''animal qu''on garde souvent à la maison.', '[{"text": "I have a dog.", "translation": "J''ai un chien."}, {"text": "The dog is happy.", "translation": "Le chien est content."}]'::jsonb, '/dɒɡ/', '{"id": "en.d.dog", "word": "dog", "translation": "chien", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/dɒɡ/", "explanation": "Un dog est un chien, l''animal qu''on garde souvent à la maison.", "examples": [{"text": "I have a dog.", "translation": "J''ai un chien."}, {"text": "The dog is happy.", "translation": "Le chien est content."}], "confusions": [], "forms": {"plural": "dogs"}, "unitId": "en.v.dog"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.phone', 'en', 'phone', 'téléphone', 'Phone est le mot courant pour téléphone, souvent un téléphone portable.', '[{"text": "She has a phone.", "translation": "Elle a un téléphone."}, {"text": "The phone is at school.", "translation": "Le téléphone est à l''école."}]'::jsonb, '/fəʊn/', '{"id": "en.d.phone", "word": "phone", "translation": "téléphone", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/fəʊn/", "explanation": "Phone est le mot courant pour téléphone, souvent un téléphone portable.", "examples": [{"text": "She has a phone.", "translation": "Elle a un téléphone."}, {"text": "The phone is at school.", "translation": "Le téléphone est à l''école."}], "confusions": [{"word": "mobile / cell phone", "note": "téléphone portable : mobile en anglais britannique, cell phone en américain."}], "forms": {"plural": "phones"}, "unitId": "en.v.phone"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
