insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.daughter', 'en', 'daughter', 'fille (enfant)', 'Une daughter est une fille par rapport à ses parents ; le gh ne se prononce pas.', '[{"text": "His daughter is happy.", "translation": "Sa fille est heureuse."}, {"text": "Our daughter is at school.", "translation": "Notre fille est à l''école."}]'::jsonb, '/ˈdɔːtə/', '{"id": "en.d.daughter", "word": "daughter", "translation": "fille (enfant)", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈdɔːtə/", "explanation": "Une daughter est une fille par rapport à ses parents ; le gh ne se prononce pas.", "examples": [{"text": "His daughter is happy.", "translation": "Sa fille est heureuse."}, {"text": "Our daughter is at school.", "translation": "Notre fille est à l''école."}], "confusions": [{"word": "girl", "note": "fille au sens de petite fille ; daughter = la fille de quelqu''un."}], "forms": {"plural": "daughters"}, "unitId": "en.v.daughter"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
