insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.key', 'en', 'key', 'clé', 'Une key est une clé qui ouvre une porte ou une voiture ; le pluriel est keys, sans changer le y.', '[{"text": "I have the key.", "translation": "J''ai la clé."}, {"text": "The keys are in the car.", "translation": "Les clés sont dans la voiture."}]'::jsonb, '/kiː/', '{"id": "en.d.key", "word": "key", "translation": "clé", "otherTranslations": ["clef"], "partOfSpeech": "noun", "ipa": "/kiː/", "explanation": "Une key est une clé qui ouvre une porte ou une voiture ; le pluriel est keys, sans changer le y.", "examples": [{"text": "I have the key.", "translation": "J''ai la clé."}, {"text": "The keys are in the car.", "translation": "Les clés sont dans la voiture."}], "confusions": [], "forms": {"plural": "keys"}, "unitId": "en.v.key"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.school', 'en', 'school', 'école', 'School désigne l''école ; on dit at school, sans the, pour « à l''école ».', '[{"text": "The children are at school.", "translation": "Les enfants sont à l''école."}, {"text": "The teacher is at school.", "translation": "Le professeur est à l''école."}]'::jsonb, '/skuːl/', '{"id": "en.d.school", "word": "school", "translation": "école", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/skuːl/", "explanation": "School désigne l''école ; on dit at school, sans the, pour « à l''école ».", "examples": [{"text": "The children are at school.", "translation": "Les enfants sont à l''école."}, {"text": "The teacher is at school.", "translation": "Le professeur est à l''école."}], "confusions": [], "forms": {"plural": "schools"}, "unitId": "en.v.school"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.people', 'en', 'people', 'gens, personnes', 'People est un pluriel : on dit people are. Le singulier (une personne) est person.', '[{"text": "People are happy.", "translation": "Les gens sont heureux."}, {"text": "Four people are at home.", "translation": "Quatre personnes sont à la maison."}]'::jsonb, '/ˈpiːpl/', '{"id": "en.d.people", "word": "people", "translation": "gens, personnes", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈpiːpl/", "explanation": "People est un pluriel : on dit people are. Le singulier (une personne) est person.", "examples": [{"text": "People are happy.", "translation": "Les gens sont heureux."}, {"text": "Four people are at home.", "translation": "Quatre personnes sont à la maison."}], "confusions": [{"word": "person", "note": "une seule personne : a person ; people = plusieurs personnes."}], "unitId": "en.v.people"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.one', 'en', 'one', 'un, une', 'One est le chiffre 1 ; avec one, le nom reste au singulier.', '[{"text": "I have one dog.", "translation": "J''ai un chien."}, {"text": "One child is at home.", "translation": "Un enfant est à la maison."}]'::jsonb, '/wʌn/', '{"id": "en.d.one", "word": "one", "translation": "un, une", "otherTranslations": ["1"], "partOfSpeech": "number", "ipa": "/wʌn/", "explanation": "One est le chiffre 1 ; avec one, le nom reste au singulier.", "examples": [{"text": "I have one dog.", "translation": "J''ai un chien."}, {"text": "One child is at home.", "translation": "Un enfant est à la maison."}], "confusions": [{"word": "a / an", "note": "a et an veulent dire « un, une » en général ; one insiste sur le chiffre : un seul."}], "unitId": "en.v.one"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
