insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.he', 'en', 'he', 'il', 'He remplace un homme ou un garçon ; avec he, on dit is et has.', '[{"text": "He is a teacher.", "translation": "Il est professeur."}, {"text": "He has a dog.", "translation": "Il a un chien."}]'::jsonb, '/hiː/', '{"id": "en.d.he", "word": "he", "translation": "il", "otherTranslations": [], "partOfSpeech": "pronoun", "ipa": "/hiː/", "explanation": "He remplace un homme ou un garçon ; avec he, on dit is et has.", "examples": [{"text": "He is a teacher.", "translation": "Il est professeur."}, {"text": "He has a dog.", "translation": "Il a un chien."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.she', 'en', 'she', 'elle', 'She remplace une femme ou une fille ; avec she, on dit is et has.', '[{"text": "She is happy.", "translation": "Elle est heureuse."}, {"text": "She has a phone.", "translation": "Elle a un téléphone."}]'::jsonb, '/ʃiː/', '{"id": "en.d.she", "word": "she", "translation": "elle", "otherTranslations": [], "partOfSpeech": "pronoun", "ipa": "/ʃiː/", "explanation": "She remplace une femme ou une fille ; avec she, on dit is et has.", "examples": [{"text": "She is happy.", "translation": "Elle est heureuse."}, {"text": "She has a phone.", "translation": "Elle a un téléphone."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.it', 'en', 'it', 'il, elle (chose, animal), ce, ça', 'It remplace une chose ou un animal, ou sert à parler du temps ; il se dit avec is et has.', '[{"text": "It is a house.", "translation": "C''est une maison."}, {"text": "It is cold.", "translation": "Il fait froid."}]'::jsonb, '/ɪt/', '{"id": "en.d.it", "word": "it", "translation": "il, elle (chose, animal), ce, ça", "otherTranslations": [], "partOfSpeech": "pronoun", "ipa": "/ɪt/", "explanation": "It remplace une chose ou un animal, ou sert à parler du temps ; il se dit avec is et has.", "examples": [{"text": "It is a house.", "translation": "C''est une maison."}, {"text": "It is cold.", "translation": "Il fait froid."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.we', 'en', 'we', 'nous', 'We veut dire « moi et d''autres personnes » ; le verbe être est are, le verbe avoir est have.', '[{"text": "We are a family.", "translation": "Nous sommes une famille."}, {"text": "We have a house.", "translation": "Nous avons une maison."}]'::jsonb, '/wiː/', '{"id": "en.d.we", "word": "we", "translation": "nous", "otherTranslations": [], "partOfSpeech": "pronoun", "ipa": "/wiː/", "explanation": "We veut dire « moi et d''autres personnes » ; le verbe être est are, le verbe avoir est have.", "examples": [{"text": "We are a family.", "translation": "Nous sommes une famille."}, {"text": "We have a house.", "translation": "Nous avons une maison."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.they', 'en', 'they', 'ils, elles', 'They remplace plusieurs personnes ou choses, au masculin comme au féminin ; on dit they are, they have.', '[{"text": "They are students.", "translation": "Ils sont étudiants."}, {"text": "They have a dog.", "translation": "Ils ont un chien."}]'::jsonb, '/ðeɪ/', '{"id": "en.d.they", "word": "they", "translation": "ils, elles", "otherTranslations": [], "partOfSpeech": "pronoun", "ipa": "/ðeɪ/", "explanation": "They remplace plusieurs personnes ou choses, au masculin comme au féminin ; on dit they are, they have.", "examples": [{"text": "They are students.", "translation": "Ils sont étudiants."}, {"text": "They have a dog.", "translation": "Ils ont un chien."}], "confusions": [{"word": "their / there", "note": "they = ils ; their = leur ; there = là : trois mots différents."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.a', 'en', 'a', 'un, une', 'A s''utilise devant un nom singulier qui commence par un son de consonne : a dog, a university.', '[{"text": "a dog", "translation": "un chien"}, {"text": "a teacher", "translation": "un professeur"}]'::jsonb, '/ə/', '{"id": "en.d.a", "word": "a", "translation": "un, une", "otherTranslations": [], "partOfSpeech": "article", "ipa": "/ə/", "explanation": "A s''utilise devant un nom singulier qui commence par un son de consonne : a dog, a university.", "examples": [{"text": "a dog", "translation": "un chien"}, {"text": "a teacher", "translation": "un professeur"}], "confusions": [{"word": "an", "note": "devant un son de voyelle : an hour."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.an', 'en', 'an', 'un, une', 'An s''utilise devant un nom singulier qui commence par un son de voyelle : an animal, an hour.', '[{"text": "an hour", "translation": "une heure"}, {"text": "an idea", "translation": "une idée"}]'::jsonb, '/ən/', '{"id": "en.d.an", "word": "an", "translation": "un, une", "otherTranslations": [], "partOfSpeech": "article", "ipa": "/ən/", "explanation": "An s''utilise devant un nom singulier qui commence par un son de voyelle : an animal, an hour.", "examples": [{"text": "an hour", "translation": "une heure"}, {"text": "an idea", "translation": "une idée"}], "confusions": [{"word": "a", "note": "devant un son de consonne : a man, a university."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.the', 'en', 'the', 'le, la, l'', les', 'The désigne une personne ou une chose précise ; il ne change jamais (masculin, féminin, pluriel). Devant une voyelle, on le prononce /ðiː/.', '[{"text": "the man", "translation": "l''homme"}, {"text": "the keys", "translation": "les clés"}]'::jsonb, '/ðə/', '{"id": "en.d.the", "word": "the", "translation": "le, la, l'', les", "otherTranslations": [], "partOfSpeech": "article", "ipa": "/ðə/", "explanation": "The désigne une personne ou une chose précise ; il ne change jamais (masculin, féminin, pluriel). Devant une voyelle, on le prononce /ðiː/.", "examples": [{"text": "the man", "translation": "l''homme"}, {"text": "the keys", "translation": "les clés"}], "confusions": [{"word": "a / an", "note": "a et an veulent dire « un, une » ; the veut dire « le, la, les »."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.be', 'en', 'be', 'être', 'Be est l''infinitif du verbe être ; il se conjugue : I am, you are, he / she / it is, we are, they are.', '[{"text": "I am happy.", "translation": "Je suis heureux."}, {"text": "They are ready.", "translation": "Ils sont prêts."}]'::jsonb, '/biː/', '{"id": "en.d.be", "word": "be", "translation": "être", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/biː/", "explanation": "Be est l''infinitif du verbe être ; il se conjugue : I am, you are, he / she / it is, we are, they are.", "examples": [{"text": "I am happy.", "translation": "Je suis heureux."}, {"text": "They are ready.", "translation": "Ils sont prêts."}], "confusions": [], "forms": {"thirdPerson": "is", "past": "was / were", "pastParticiple": "been", "ing": "being"}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.am', 'en', 'am', 'suis', 'Am est la forme du verbe be qui va seulement avec I.', '[{"text": "I am a student.", "translation": "Je suis étudiant."}, {"text": "I am not late.", "translation": "Je ne suis pas en retard."}]'::jsonb, '/æm/', '{"id": "en.d.am", "word": "am", "translation": "suis", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/æm/", "explanation": "Am est la forme du verbe be qui va seulement avec I.", "examples": [{"text": "I am a student.", "translation": "Je suis étudiant."}, {"text": "I am not late.", "translation": "Je ne suis pas en retard."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.is', 'en', 'is', 'est', 'Is est la forme du verbe be avec he, she, it ou un nom singulier.', '[{"text": "She is a teacher.", "translation": "Elle est professeur."}, {"text": "The dog is at home.", "translation": "Le chien est à la maison."}]'::jsonb, '/ɪz/', '{"id": "en.d.is", "word": "is", "translation": "est", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/ɪz/", "explanation": "Is est la forme du verbe be avec he, she, it ou un nom singulier.", "examples": [{"text": "She is a teacher.", "translation": "Elle est professeur."}, {"text": "The dog is at home.", "translation": "Le chien est à la maison."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.are', 'en', 'are', 'es, êtes, sommes, sont', 'Are est la forme du verbe be avec you, we, they ou un nom pluriel.', '[{"text": "You are ready.", "translation": "Tu es prêt."}, {"text": "The children are at school.", "translation": "Les enfants sont à l''école."}]'::jsonb, '/ɑː/', '{"id": "en.d.are", "word": "are", "translation": "es, êtes, sommes, sont", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/ɑː/", "explanation": "Are est la forme du verbe be avec you, we, they ou un nom pluriel.", "examples": [{"text": "You are ready.", "translation": "Tu es prêt."}, {"text": "The children are at school.", "translation": "Les enfants sont à l''école."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.not', 'en', 'not', 'ne... pas', 'Not rend une phrase négative ; avec be, il se place après le verbe : I am not.', '[{"text": "I am not late.", "translation": "Je ne suis pas en retard."}, {"text": "She is not tired.", "translation": "Elle n''est pas fatiguée."}]'::jsonb, '/nɒt/', '{"id": "en.d.not", "word": "not", "translation": "ne... pas", "otherTranslations": [], "partOfSpeech": "adverb", "ipa": "/nɒt/", "explanation": "Not rend une phrase négative ; avec be, il se place après le verbe : I am not.", "examples": [{"text": "I am not late.", "translation": "Je ne suis pas en retard."}, {"text": "She is not tired.", "translation": "Elle n''est pas fatiguée."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.isnt', 'en', 'isn''t', 'n''est pas', 'Isn''t est la forme courte de is not ; elle va avec he, she, it ou un nom singulier.', '[{"text": "He isn''t busy.", "translation": "Il n''est pas occupé."}, {"text": "The car isn''t at home.", "translation": "La voiture n''est pas à la maison."}]'::jsonb, '/ˈɪznt/', '{"id": "en.d.isnt", "word": "isn''t", "translation": "n''est pas", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/ˈɪznt/", "explanation": "Isn''t est la forme courte de is not ; elle va avec he, she, it ou un nom singulier.", "examples": [{"text": "He isn''t busy.", "translation": "Il n''est pas occupé."}, {"text": "The car isn''t at home.", "translation": "La voiture n''est pas à la maison."}], "confusions": [{"word": "aren''t", "note": "aren''t = are not : avec you, we, they."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.arent', 'en', 'aren''t', 'n''es pas, ne sommes pas, ne sont pas', 'Aren''t est la forme courte de are not ; elle va avec you, we, they ou un nom pluriel.', '[{"text": "We aren''t cold.", "translation": "Nous n''avons pas froid."}, {"text": "They aren''t ready.", "translation": "Ils ne sont pas prêts."}]'::jsonb, '/ɑːnt/', '{"id": "en.d.arent", "word": "aren''t", "translation": "n''es pas, ne sommes pas, ne sont pas", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/ɑːnt/", "explanation": "Aren''t est la forme courte de are not ; elle va avec you, we, they ou un nom pluriel.", "examples": [{"text": "We aren''t cold.", "translation": "Nous n''avons pas froid."}, {"text": "They aren''t ready.", "translation": "Ils ne sont pas prêts."}], "confusions": [{"word": "isn''t", "note": "isn''t = is not : avec he, she, it."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.have', 'en', 'have', 'avoir', 'Have sert à dire ce qu''on possède, avec I, you, we et they ; pour la faim, le froid ou l''âge, on utilise be.', '[{"text": "I have a car.", "translation": "J''ai une voiture."}, {"text": "We have two dogs.", "translation": "Nous avons deux chiens."}]'::jsonb, '/hæv/', '{"id": "en.d.have", "word": "have", "translation": "avoir", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/hæv/", "explanation": "Have sert à dire ce qu''on possède, avec I, you, we et they ; pour la faim, le froid ou l''âge, on utilise be.", "examples": [{"text": "I have a car.", "translation": "J''ai une voiture."}, {"text": "We have two dogs.", "translation": "Nous avons deux chiens."}], "confusions": [{"word": "be", "note": "faim, froid, âge, raison : on utilise be (I am hungry), pas have."}], "forms": {"thirdPerson": "has", "past": "had", "pastParticiple": "had", "ing": "having"}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.has', 'en', 'has', 'a', 'Has est la forme du verbe have avec he, she, it ou un nom singulier.', '[{"text": "She has a phone.", "translation": "Elle a un téléphone."}, {"text": "Tom has a dog.", "translation": "Tom a un chien."}]'::jsonb, '/hæz/', '{"id": "en.d.has", "word": "has", "translation": "a", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/hæz/", "explanation": "Has est la forme du verbe have avec he, she, it ou un nom singulier.", "examples": [{"text": "She has a phone.", "translation": "Elle a un téléphone."}, {"text": "Tom has a dog.", "translation": "Tom a un chien."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.my', 'en', 'my', 'mon, ma, mes', 'My se place devant un nom pour dire que la chose est à moi ; il ne change jamais.', '[{"text": "my son", "translation": "mon fils"}, {"text": "My parents are at home.", "translation": "Mes parents sont à la maison."}]'::jsonb, '/maɪ/', '{"id": "en.d.my", "word": "my", "translation": "mon, ma, mes", "otherTranslations": [], "partOfSpeech": "determiner", "ipa": "/maɪ/", "explanation": "My se place devant un nom pour dire que la chose est à moi ; il ne change jamais.", "examples": [{"text": "my son", "translation": "mon fils"}, {"text": "My parents are at home.", "translation": "Mes parents sont à la maison."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.your', 'en', 'your', 'ton, ta, tes, votre, vos', 'Your se place devant un nom pour dire que la chose est à toi ou à vous ; il ne change jamais.', '[{"text": "your name", "translation": "ton prénom"}, {"text": "Your friends are ready.", "translation": "Tes amis sont prêts."}]'::jsonb, '/jɔː/', '{"id": "en.d.your", "word": "your", "translation": "ton, ta, tes, votre, vos", "otherTranslations": [], "partOfSpeech": "determiner", "ipa": "/jɔː/", "explanation": "Your se place devant un nom pour dire que la chose est à toi ou à vous ; il ne change jamais.", "examples": [{"text": "your name", "translation": "ton prénom"}, {"text": "Your friends are ready.", "translation": "Tes amis sont prêts."}], "confusions": [{"word": "you''re", "note": "you''re = you are ; your = ton, votre."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.his', 'en', 'his', 'son, sa, ses (à lui)', 'His indique que la chose appartient à un homme ; le possessif dépend du possesseur, pas du nom qui suit.', '[{"text": "His wife is a teacher.", "translation": "Sa femme est professeur."}, {"text": "Tom has his phone.", "translation": "Tom a son téléphone."}]'::jsonb, '/hɪz/', '{"id": "en.d.his", "word": "his", "translation": "son, sa, ses (à lui)", "otherTranslations": [], "partOfSpeech": "determiner", "ipa": "/hɪz/", "explanation": "His indique que la chose appartient à un homme ; le possessif dépend du possesseur, pas du nom qui suit.", "examples": [{"text": "His wife is a teacher.", "translation": "Sa femme est professeur."}, {"text": "Tom has his phone.", "translation": "Tom a son téléphone."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.her', 'en', 'her', 'son, sa, ses (à elle)', 'Her indique que la chose appartient à une femme ; le possessif dépend du possesseur, pas du nom qui suit.', '[{"text": "Her husband is tired.", "translation": "Son mari est fatigué."}, {"text": "Anna has her bag.", "translation": "Anna a son sac."}]'::jsonb, '/hɜː/', '{"id": "en.d.her", "word": "her", "translation": "son, sa, ses (à elle)", "otherTranslations": [], "partOfSpeech": "determiner", "ipa": "/hɜː/", "explanation": "Her indique que la chose appartient à une femme ; le possessif dépend du possesseur, pas du nom qui suit.", "examples": [{"text": "Her husband is tired.", "translation": "Son mari est fatigué."}, {"text": "Anna has her bag.", "translation": "Anna a son sac."}], "confusions": [{"word": "his", "note": "his = à lui ; her = à elle."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.its', 'en', 'its', 'son, sa, ses (animal, chose)', 'Its indique que la chose appartient à un animal ou à une chose ; il s''écrit sans apostrophe.', '[{"text": "The dog is happy. Its name is Sam.", "translation": "Le chien est content. Son nom est Sam."}, {"text": "The car is at home. Its key is at school.", "translation": "La voiture est à la maison. Sa clé est à l''école."}]'::jsonb, '/ɪts/', '{"id": "en.d.its", "word": "its", "translation": "son, sa, ses (animal, chose)", "otherTranslations": [], "partOfSpeech": "determiner", "ipa": "/ɪts/", "explanation": "Its indique que la chose appartient à un animal ou à une chose ; il s''écrit sans apostrophe.", "examples": [{"text": "The dog is happy. Its name is Sam.", "translation": "Le chien est content. Son nom est Sam."}, {"text": "The car is at home. Its key is at school.", "translation": "La voiture est à la maison. Sa clé est à l''école."}], "confusions": [{"word": "it''s", "note": "it''s = it is ; its = son, sa (sans apostrophe)."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.our', 'en', 'our', 'notre, nos', 'Our se place devant un nom pour dire que la chose est à nous ; il ne change jamais.', '[{"text": "our house", "translation": "notre maison"}, {"text": "Our children are at school.", "translation": "Nos enfants sont à l''école."}]'::jsonb, '/ˈaʊə/', '{"id": "en.d.our", "word": "our", "translation": "notre, nos", "otherTranslations": [], "partOfSpeech": "determiner", "ipa": "/ˈaʊə/", "explanation": "Our se place devant un nom pour dire que la chose est à nous ; il ne change jamais.", "examples": [{"text": "our house", "translation": "notre maison"}, {"text": "Our children are at school.", "translation": "Nos enfants sont à l''école."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.their', 'en', 'their', 'leur, leurs', 'Their se place devant un nom pour dire que la chose est à eux ou à elles ; il ne change jamais.', '[{"text": "their dog", "translation": "leur chien"}, {"text": "Their parents are happy.", "translation": "Leurs parents sont heureux."}]'::jsonb, '/ðeə/', '{"id": "en.d.their", "word": "their", "translation": "leur, leurs", "otherTranslations": [], "partOfSpeech": "determiner", "ipa": "/ðeə/", "explanation": "Their se place devant un nom pour dire que la chose est à eux ou à elles ; il ne change jamais.", "examples": [{"text": "their dog", "translation": "leur chien"}, {"text": "Their parents are happy.", "translation": "Leurs parents sont heureux."}], "confusions": [{"word": "there", "note": "même prononciation /ðeə/ ; there veut dire « là »."}, {"word": "they''re", "note": "they''re = they are."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.go', 'en', 'go', 'aller', 'Go sert à dire qu''on se déplace vers un endroit. On dit go to school, go to London, mais go home, sans to devant home.', '[{"text": "We go to school by car.", "translation": "Nous allons à l''école en voiture."}, {"text": "I go home.", "translation": "Je rentre chez moi."}]'::jsonb, '/ɡəʊ/', '{"id": "en.d.go", "word": "go", "translation": "aller", "otherTranslations": ["partir", "rentrer (go home)"], "partOfSpeech": "verb", "ipa": "/ɡəʊ/", "explanation": "Go sert à dire qu''on se déplace vers un endroit. On dit go to school, go to London, mais go home, sans to devant home.", "examples": [{"text": "We go to school by car.", "translation": "Nous allons à l''école en voiture."}, {"text": "I go home.", "translation": "Je rentre chez moi."}], "confusions": [{"word": "come", "note": "go = aller (vers un autre endroit) ; come = venir (vers la personne qui parle)."}, {"word": "went", "note": "went est le passé de go."}], "forms": {"thirdPerson": "goes", "past": "went", "pastParticiple": "gone", "ing": "going"}, "unitId": "en.v.go"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.do', 'en', 'do', 'faire', 'Do veut dire « faire » une tâche, une activité ou un travail à accomplir. Pour créer ou fabriquer quelque chose, on utilise plutôt make.', '[{"text": "I do my homework at home.", "translation": "Je fais mes devoirs à la maison."}, {"text": "We do it for our family.", "translation": "Nous le faisons pour notre famille."}]'::jsonb, '/duː/', '{"id": "en.d.do", "word": "do", "translation": "faire", "otherTranslations": ["faire (une tâche, une activité)"], "partOfSpeech": "verb", "ipa": "/duː/", "explanation": "Do veut dire « faire » une tâche, une activité ou un travail à accomplir. Pour créer ou fabriquer quelque chose, on utilise plutôt make.", "examples": [{"text": "I do my homework at home.", "translation": "Je fais mes devoirs à la maison."}, {"text": "We do it for our family.", "translation": "Nous le faisons pour notre famille."}], "confusions": [{"word": "make", "note": "do = faire une tâche, une activité ; make = créer, fabriquer, préparer. On dit do homework, make dinner."}], "forms": {"thirdPerson": "does", "past": "did", "pastParticiple": "done", "ing": "doing"}, "unitId": "en.v.do"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.make', 'en', 'make', 'faire, fabriquer', 'Make veut dire « fabriquer, créer, préparer ». On l''emploie aussi dans des expressions à apprendre par cœur : make a mistake, make a decision.', '[{"text": "We make dinner at home.", "translation": "Nous préparons le dîner à la maison."}, {"text": "They make cars.", "translation": "Ils fabriquent des voitures."}]'::jsonb, '/meɪk/', '{"id": "en.d.make", "word": "make", "translation": "faire, fabriquer", "otherTranslations": ["préparer", "créer"], "partOfSpeech": "verb", "ipa": "/meɪk/", "explanation": "Make veut dire « fabriquer, créer, préparer ». On l''emploie aussi dans des expressions à apprendre par cœur : make a mistake, make a decision.", "examples": [{"text": "We make dinner at home.", "translation": "Nous préparons le dîner à la maison."}, {"text": "They make cars.", "translation": "Ils fabriquent des voitures."}], "confusions": [{"word": "do", "note": "make = créer, préparer ; do = accomplir une tâche. On dit make a mistake mais do homework."}], "forms": {"thirdPerson": "makes", "past": "made", "pastParticiple": "made", "ing": "making"}, "unitId": "en.v.make"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.take', 'en', 'take', 'prendre', 'Take veut dire « prendre » quelque chose pour l''avoir avec soi ou pour l''utiliser : take a bag, take the car.', '[{"text": "I take my bag and my phone.", "translation": "Je prends mon sac et mon téléphone."}, {"text": "We take the car.", "translation": "Nous prenons la voiture."}]'::jsonb, '/teɪk/', '{"id": "en.d.take", "word": "take", "translation": "prendre", "otherTranslations": ["emporter", "emmener"], "partOfSpeech": "verb", "ipa": "/teɪk/", "explanation": "Take veut dire « prendre » quelque chose pour l''avoir avec soi ou pour l''utiliser : take a bag, take the car.", "examples": [{"text": "I take my bag and my phone.", "translation": "Je prends mon sac et mon téléphone."}, {"text": "We take the car.", "translation": "Nous prenons la voiture."}], "confusions": [{"word": "give", "note": "take = prendre ; give = donner."}], "forms": {"thirdPerson": "takes", "past": "took", "pastParticiple": "taken", "ing": "taking"}, "unitId": "en.v.take"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.give', 'en', 'give', 'donner', 'Give veut dire « donner » quelque chose à quelqu''un. On peut dire give a book to Tom ou give Tom a book.', '[{"text": "I give my phone to my sister.", "translation": "Je donne mon téléphone à ma sœur."}, {"text": "You give a book to the child.", "translation": "Tu donnes un livre à l''enfant."}]'::jsonb, '/ɡɪv/', '{"id": "en.d.give", "word": "give", "translation": "donner", "otherTranslations": ["offrir"], "partOfSpeech": "verb", "ipa": "/ɡɪv/", "explanation": "Give veut dire « donner » quelque chose à quelqu''un. On peut dire give a book to Tom ou give Tom a book.", "examples": [{"text": "I give my phone to my sister.", "translation": "Je donne mon téléphone à ma sœur."}, {"text": "You give a book to the child.", "translation": "Tu donnes un livre à l''enfant."}], "confusions": [{"word": "take", "note": "give = donner ; take = prendre."}], "forms": {"thirdPerson": "gives", "past": "gave", "pastParticiple": "given", "ing": "giving"}, "unitId": "en.v.give"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.homework', 'en', 'homework', 'devoirs', 'Homework désigne les devoirs qu''on fait pour l''école. C''est un nom indénombrable : il n''a pas de pluriel et ne prend pas de a. On dit do homework.', '[{"text": "We have homework.", "translation": "Nous avons des devoirs."}, {"text": "Tom and Anna do their homework.", "translation": "Tom et Anna font leurs devoirs."}]'::jsonb, '/ˈhəʊmwɜːk/', '{"id": "en.d.homework", "word": "homework", "translation": "devoirs", "otherTranslations": ["travail à faire à la maison"], "partOfSpeech": "noun", "ipa": "/ˈhəʊmwɜːk/", "explanation": "Homework désigne les devoirs qu''on fait pour l''école. C''est un nom indénombrable : il n''a pas de pluriel et ne prend pas de a. On dit do homework.", "examples": [{"text": "We have homework.", "translation": "Nous avons des devoirs."}, {"text": "Tom and Anna do their homework.", "translation": "Tom et Anna font leurs devoirs."}], "confusions": [{"word": "make", "note": "On dit do homework, jamais make homework."}, {"word": "housework", "note": "housework = les tâches ménagères ; homework = les devoirs d''école."}], "unitId": "en.v.homework"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.mistake', 'en', 'mistake', 'erreur, faute', 'Mistake veut dire « erreur ». On dit make a mistake (faire une erreur), jamais do a mistake.', '[{"text": "Sorry, it is a mistake.", "translation": "Pardon, c''est une erreur."}, {"text": "I make a mistake with my homework.", "translation": "Je fais une erreur dans mes devoirs."}]'::jsonb, '/mɪˈsteɪk/', '{"id": "en.d.mistake", "word": "mistake", "translation": "erreur, faute", "otherTranslations": ["se tromper (make a mistake)"], "partOfSpeech": "noun", "ipa": "/mɪˈsteɪk/", "explanation": "Mistake veut dire « erreur ». On dit make a mistake (faire une erreur), jamais do a mistake.", "examples": [{"text": "Sorry, it is a mistake.", "translation": "Pardon, c''est une erreur."}, {"text": "I make a mistake with my homework.", "translation": "Je fais une erreur dans mes devoirs."}], "confusions": [{"word": "fault", "note": "mistake = une erreur ; fault = la faute, la responsabilité (It''s my fault = c''est ma faute)."}], "forms": {"plural": "mistakes"}, "unitId": "en.v.mistake"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.dinner', 'en', 'dinner', 'dîner, repas du soir', 'Dinner est le repas principal de la journée, le plus souvent celui du soir. On dit make dinner (préparer) et eat dinner (dîner).', '[{"text": "We eat dinner with our parents.", "translation": "Nous dînons avec nos parents."}, {"text": "I make dinner for my family.", "translation": "Je prépare le dîner pour ma famille."}]'::jsonb, '/ˈdɪnə/', '{"id": "en.d.dinner", "word": "dinner", "translation": "dîner, repas du soir", "otherTranslations": ["repas principal"], "partOfSpeech": "noun", "ipa": "/ˈdɪnə/", "explanation": "Dinner est le repas principal de la journée, le plus souvent celui du soir. On dit make dinner (préparer) et eat dinner (dîner).", "examples": [{"text": "We eat dinner with our parents.", "translation": "Nous dînons avec nos parents."}, {"text": "I make dinner for my family.", "translation": "Je prépare le dîner pour ma famille."}], "confusions": [], "forms": {"plural": "dinners"}, "unitId": "en.v.dinner"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.decision', 'en', 'decision', 'décision', 'Une decision est un choix qu''on fait. On dit make a decision (prendre une décision).', '[{"text": "We make a decision.", "translation": "Nous prenons une décision."}, {"text": "It is a decision for the family.", "translation": "C''est une décision pour la famille."}]'::jsonb, '/dɪˈsɪʒn/', '{"id": "en.d.decision", "word": "decision", "translation": "décision", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/dɪˈsɪʒn/", "explanation": "Une decision est un choix qu''on fait. On dit make a decision (prendre une décision).", "examples": [{"text": "We make a decision.", "translation": "Nous prenons une décision."}, {"text": "It is a decision for the family.", "translation": "C''est une décision pour la famille."}], "confusions": [], "forms": {"plural": "decisions"}, "unitId": "en.v.decision"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.coffee', 'en', 'coffee', 'café (la boisson)', 'Coffee est la boisson. On dit make coffee (préparer du café). On peut aussi dire a coffee pour « un café » quand on en commande un.', '[{"text": "I like coffee.", "translation": "J''aime bien le café."}, {"text": "Can I have a coffee, please?", "translation": "Puis-je avoir un café, s''il vous plaît ?"}]'::jsonb, '/ˈkɒfi/', '{"id": "en.d.coffee", "word": "coffee", "translation": "café (la boisson)", "otherTranslations": ["un café"], "partOfSpeech": "noun", "ipa": "/ˈkɒfi/", "explanation": "Coffee est la boisson. On dit make coffee (préparer du café). On peut aussi dire a coffee pour « un café » quand on en commande un.", "examples": [{"text": "I like coffee.", "translation": "J''aime bien le café."}, {"text": "Can I have a coffee, please?", "translation": "Puis-je avoir un café, s''il vous plaît ?"}], "confusions": [{"word": "café", "note": "En anglais aussi, un café (le lieu où l''on s''assoit) s''écrit café et se prononce /ˈkæfeɪ/ ; la boisson se dit coffee."}], "forms": {"plural": "coffees"}, "unitId": "en.v.coffee"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.get', 'en', 'get', 'obtenir, recevoir', 'Get est un verbe très courant : il veut dire « recevoir, obtenir », ou « devenir » avec un adjectif (get tired = se fatiguer).', '[{"text": "I get a phone from my parents.", "translation": "Je reçois un téléphone de mes parents."}, {"text": "We get tired.", "translation": "Nous nous fatiguons."}]'::jsonb, '/ɡet/', '{"id": "en.d.get", "word": "get", "translation": "obtenir, recevoir", "otherTranslations": ["devenir", "arriver", "acheter"], "partOfSpeech": "verb", "ipa": "/ɡet/", "explanation": "Get est un verbe très courant : il veut dire « recevoir, obtenir », ou « devenir » avec un adjectif (get tired = se fatiguer).", "examples": [{"text": "I get a phone from my parents.", "translation": "Je reçois un téléphone de mes parents."}, {"text": "We get tired.", "translation": "Nous nous fatiguons."}], "confusions": [{"word": "have", "note": "get = obtenir, recevoir ; have = avoir, posséder."}], "forms": {"thirdPerson": "gets", "past": "got", "pastParticiple": "got", "ing": "getting"}, "unitId": "en.v.get"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.know', 'en', 'know', 'savoir, connaître', 'Know veut dire « savoir » (une information) et « connaître » (une personne, un lieu). Le k ne se prononce pas.', '[{"text": "I know your name.", "translation": "Je connais ton nom."}, {"text": "We know Tom and Anna.", "translation": "Nous connaissons Tom et Anna."}]'::jsonb, '/nəʊ/', '{"id": "en.d.know", "word": "know", "translation": "savoir, connaître", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/nəʊ/", "explanation": "Know veut dire « savoir » (une information) et « connaître » (une personne, un lieu). Le k ne se prononce pas.", "examples": [{"text": "I know your name.", "translation": "Je connais ton nom."}, {"text": "We know Tom and Anna.", "translation": "Nous connaissons Tom et Anna."}], "confusions": [{"word": "no", "note": "know et no se prononcent pareil ; no = non."}, {"word": "meet", "note": "know = connaître déjà quelqu''un ; meet = rencontrer."}], "forms": {"thirdPerson": "knows", "past": "knew", "pastParticiple": "known", "ing": "knowing"}, "unitId": "en.v.know"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.think', 'en', 'think', 'penser, croire', 'Think sert à donner son avis ou à dire ce qu''on croit. Il peut être suivi directement d''une phrase : I think you are right.', '[{"text": "I think you are right.", "translation": "Je pense que tu as raison."}, {"text": "We think they are late.", "translation": "Nous pensons qu''ils sont en retard."}]'::jsonb, '/θɪŋk/', '{"id": "en.d.think", "word": "think", "translation": "penser, croire", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/θɪŋk/", "explanation": "Think sert à donner son avis ou à dire ce qu''on croit. Il peut être suivi directement d''une phrase : I think you are right.", "examples": [{"text": "I think you are right.", "translation": "Je pense que tu as raison."}, {"text": "We think they are late.", "translation": "Nous pensons qu''ils sont en retard."}], "confusions": [{"word": "thank", "note": "think = penser ; thank = remercier."}, {"word": "thing", "note": "think = penser ; thing = une chose."}], "forms": {"thirdPerson": "thinks", "past": "thought", "pastParticiple": "thought", "ing": "thinking"}, "unitId": "en.v.think"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.want', 'en', 'want', 'vouloir', 'Want veut dire « vouloir ». Devant un verbe, on dit want to + verbe de base ; devant un nom, want + nom.', '[{"text": "We want a dog.", "translation": "Nous voulons un chien."}, {"text": "I want to read my book.", "translation": "Je veux lire mon livre."}]'::jsonb, '/wɒnt/', '{"id": "en.d.want", "word": "want", "translation": "vouloir", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/wɒnt/", "explanation": "Want veut dire « vouloir ». Devant un verbe, on dit want to + verbe de base ; devant un nom, want + nom.", "examples": [{"text": "We want a dog.", "translation": "Nous voulons un chien."}, {"text": "I want to read my book.", "translation": "Je veux lire mon livre."}], "confusions": [{"word": "need", "note": "want = avoir envie de ; need = avoir besoin de."}], "forms": {"thirdPerson": "wants", "past": "wanted", "pastParticiple": "wanted", "ing": "wanting"}, "unitId": "en.v.want"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.need', 'en', 'need', 'avoir besoin de', 'Need veut dire « avoir besoin de ». Devant un verbe, on dit need to + verbe de base ; devant un nom, need + nom.', '[{"text": "I need a key for the door.", "translation": "J''ai besoin d''une clé pour la porte."}, {"text": "You need to be careful.", "translation": "Tu as besoin de faire attention."}]'::jsonb, '/niːd/', '{"id": "en.d.need", "word": "need", "translation": "avoir besoin de", "otherTranslations": ["devoir (need to)"], "partOfSpeech": "verb", "ipa": "/niːd/", "explanation": "Need veut dire « avoir besoin de ». Devant un verbe, on dit need to + verbe de base ; devant un nom, need + nom.", "examples": [{"text": "I need a key for the door.", "translation": "J''ai besoin d''une clé pour la porte."}, {"text": "You need to be careful.", "translation": "Tu as besoin de faire attention."}], "confusions": [{"word": "want", "note": "need = avoir besoin de (nécessité) ; want = vouloir (envie)."}], "forms": {"thirdPerson": "needs", "past": "needed", "pastParticiple": "needed", "ing": "needing"}, "unitId": "en.v.need"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.swim', 'en', 'swim', 'nager', 'Swim veut dire « nager ». I can swim signifie « je sais nager ».', '[{"text": "My brother can swim.", "translation": "Mon frère sait nager."}, {"text": "I can''t swim.", "translation": "Je ne sais pas nager."}]'::jsonb, '/swɪm/', '{"id": "en.d.swim", "word": "swim", "translation": "nager", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/swɪm/", "explanation": "Swim veut dire « nager ». I can swim signifie « je sais nager ».", "examples": [{"text": "My brother can swim.", "translation": "Mon frère sait nager."}, {"text": "I can''t swim.", "translation": "Je ne sais pas nager."}], "confusions": [], "forms": {"thirdPerson": "swims", "past": "swam", "pastParticiple": "swum", "ing": "swimming"}, "unitId": "en.v.swim"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.drive', 'en', 'drive', 'conduire', 'Drive veut dire « conduire » une voiture. I can drive signifie « je sais conduire ».', '[{"text": "My mother can drive.", "translation": "Ma mère sait conduire."}, {"text": "We drive home.", "translation": "Nous rentrons en voiture."}]'::jsonb, '/draɪv/', '{"id": "en.d.drive", "word": "drive", "translation": "conduire", "otherTranslations": ["aller en voiture"], "partOfSpeech": "verb", "ipa": "/draɪv/", "explanation": "Drive veut dire « conduire » une voiture. I can drive signifie « je sais conduire ».", "examples": [{"text": "My mother can drive.", "translation": "Ma mère sait conduire."}, {"text": "We drive home.", "translation": "Nous rentrons en voiture."}], "confusions": [], "forms": {"thirdPerson": "drives", "past": "drove", "pastParticiple": "driven", "ing": "driving"}, "unitId": "en.v.drive"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.speak', 'en', 'speak', 'parler (une langue)', 'Speak veut dire « parler », surtout pour une langue ou pour s''adresser à quelqu''un. I speak English = je parle anglais.', '[{"text": "Can you speak English?", "translation": "Parles-tu anglais ?"}, {"text": "We speak French at home.", "translation": "Nous parlons français à la maison."}]'::jsonb, '/spiːk/', '{"id": "en.d.speak", "word": "speak", "translation": "parler (une langue)", "otherTranslations": ["s''exprimer"], "partOfSpeech": "verb", "ipa": "/spiːk/", "explanation": "Speak veut dire « parler », surtout pour une langue ou pour s''adresser à quelqu''un. I speak English = je parle anglais.", "examples": [{"text": "Can you speak English?", "translation": "Parles-tu anglais ?"}, {"text": "We speak French at home.", "translation": "Nous parlons français à la maison."}], "confusions": [{"word": "say", "note": "speak = parler (une langue) ; say = dire quelque chose."}, {"word": "talk", "note": "speak = parler (une langue) ; talk = bavarder, discuter."}], "forms": {"thirdPerson": "speaks", "past": "spoke", "pastParticiple": "spoken", "ing": "speaking"}, "unitId": "en.v.speak"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.english', 'en', 'English', 'anglais (la langue)', 'English est la langue anglaise. Les noms de langues prennent toujours une majuscule en anglais.', '[{"text": "I can speak English.", "translation": "Je sais parler anglais."}, {"text": "Can you write in English?", "translation": "Peux-tu écrire en anglais ?"}]'::jsonb, '/ˈɪŋɡlɪʃ/', '{"id": "en.d.english", "word": "English", "translation": "anglais (la langue)", "otherTranslations": ["anglais (adjectif)"], "partOfSpeech": "noun", "ipa": "/ˈɪŋɡlɪʃ/", "explanation": "English est la langue anglaise. Les noms de langues prennent toujours une majuscule en anglais.", "examples": [{"text": "I can speak English.", "translation": "Je sais parler anglais."}, {"text": "Can you write in English?", "translation": "Peux-tu écrire en anglais ?"}], "confusions": [{"word": "England", "note": "English = la langue ; England = l''Angleterre, le pays."}], "unitId": "en.v.english"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.french', 'en', 'French', 'français (la langue)', 'French est la langue française. Comme tous les noms de langues, il prend une majuscule.', '[{"text": "Tom can speak French.", "translation": "Tom sait parler français."}, {"text": "We read a book in French.", "translation": "Nous lisons un livre en français."}]'::jsonb, '/frentʃ/', '{"id": "en.d.french", "word": "French", "translation": "français (la langue)", "otherTranslations": ["français (adjectif)"], "partOfSpeech": "noun", "ipa": "/frentʃ/", "explanation": "French est la langue française. Comme tous les noms de langues, il prend une majuscule.", "examples": [{"text": "Tom can speak French.", "translation": "Tom sait parler français."}, {"text": "We read a book in French.", "translation": "Nous lisons un livre en français."}], "confusions": [{"word": "France", "note": "French = la langue ; France = le pays."}], "unitId": "en.v.french"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.help', 'en', 'help', 'aider', 'Help veut dire « aider ». On aide quelqu''un directement : help me, help my mother. Après help, « moi » se dit me.', '[{"text": "Can you help me?", "translation": "Peux-tu m''aider ?"}, {"text": "We help our parents at home.", "translation": "Nous aidons nos parents à la maison."}]'::jsonb, '/help/', '{"id": "en.d.help", "word": "help", "translation": "aider", "otherTranslations": ["aide (nom)"], "partOfSpeech": "verb", "ipa": "/help/", "explanation": "Help veut dire « aider ». On aide quelqu''un directement : help me, help my mother. Après help, « moi » se dit me.", "examples": [{"text": "Can you help me?", "translation": "Peux-tu m''aider ?"}, {"text": "We help our parents at home.", "translation": "Nous aidons nos parents à la maison."}], "confusions": [], "forms": {"thirdPerson": "helps", "past": "helped", "pastParticiple": "helped", "ing": "helping"}, "unitId": "en.v.help"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.read', 'en', 'read', 'lire', 'Read veut dire « lire ». Au présent, il se prononce /riːd/. Au passé, il s''écrit pareil mais se prononce /red/.', '[{"text": "I read a book at home.", "translation": "Je lis un livre à la maison."}, {"text": "Can you read French?", "translation": "Sais-tu lire le français ?"}]'::jsonb, '/riːd/', '{"id": "en.d.read", "word": "read", "translation": "lire", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/riːd/", "explanation": "Read veut dire « lire ». Au présent, il se prononce /riːd/. Au passé, il s''écrit pareil mais se prononce /red/.", "examples": [{"text": "I read a book at home.", "translation": "Je lis un livre à la maison."}, {"text": "Can you read French?", "translation": "Sais-tu lire le français ?"}], "confusions": [{"word": "write", "note": "read = lire ; write = écrire."}], "forms": {"thirdPerson": "reads", "past": "read", "pastParticiple": "read", "ing": "reading"}, "unitId": "en.v.read"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.write', 'en', 'write', 'écrire', 'Write veut dire « écrire ». Le w ne se prononce pas.', '[{"text": "Can you write your name?", "translation": "Peux-tu écrire ton nom ?"}, {"text": "I write in English.", "translation": "J''écris en anglais."}]'::jsonb, '/raɪt/', '{"id": "en.d.write", "word": "write", "translation": "écrire", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/raɪt/", "explanation": "Write veut dire « écrire ». Le w ne se prononce pas.", "examples": [{"text": "Can you write your name?", "translation": "Peux-tu écrire ton nom ?"}, {"text": "I write in English.", "translation": "J''écris en anglais."}], "confusions": [{"word": "right", "note": "write et right se prononcent pareil ; right = juste, correct, ou la droite."}, {"word": "read", "note": "write = écrire ; read = lire."}], "forms": {"thirdPerson": "writes", "past": "wrote", "pastParticiple": "written", "ing": "writing"}, "unitId": "en.v.write"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.door', 'en', 'door', 'porte', 'Door est la porte d''une maison, d''une pièce ou d''une voiture.', '[{"text": "The key is for the door.", "translation": "La clé est pour la porte."}, {"text": "Please open the door.", "translation": "Ouvre la porte, s''il te plaît."}]'::jsonb, '/dɔː/', '{"id": "en.d.door", "word": "door", "translation": "porte", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/dɔː/", "explanation": "Door est la porte d''une maison, d''une pièce ou d''une voiture.", "examples": [{"text": "The key is for the door.", "translation": "La clé est pour la porte."}, {"text": "Please open the door.", "translation": "Ouvre la porte, s''il te plaît."}], "confusions": [], "forms": {"plural": "doors"}, "unitId": "en.v.door"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.window', 'en', 'window', 'fenêtre', 'Window est la fenêtre d''une maison, d''une voiture, et aussi la vitrine d''un magasin.', '[{"text": "Can you close the window?", "translation": "Peux-tu fermer la fenêtre ?"}, {"text": "It is cold. Close the window, please.", "translation": "Il fait froid. Ferme la fenêtre, s''il te plaît."}]'::jsonb, '/ˈwɪndəʊ/', '{"id": "en.d.window", "word": "window", "translation": "fenêtre", "otherTranslations": ["vitrine"], "partOfSpeech": "noun", "ipa": "/ˈwɪndəʊ/", "explanation": "Window est la fenêtre d''une maison, d''une voiture, et aussi la vitrine d''un magasin.", "examples": [{"text": "Can you close the window?", "translation": "Peux-tu fermer la fenêtre ?"}, {"text": "It is cold. Close the window, please.", "translation": "Il fait froid. Ferme la fenêtre, s''il te plaît."}], "confusions": [], "forms": {"plural": "windows"}, "unitId": "en.v.window"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.stop', 'en', 'stop', 'arrêter, s''arrêter', 'Stop veut dire « s''arrêter » ou « arrêter » de faire quelque chose. Le mot est le même que le panneau stop.', '[{"text": "You must stop.", "translation": "Tu dois t''arrêter."}, {"text": "Don''t stop!", "translation": "Ne t''arrête pas !"}]'::jsonb, '/stɒp/', '{"id": "en.d.stop", "word": "stop", "translation": "arrêter, s''arrêter", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/stɒp/", "explanation": "Stop veut dire « s''arrêter » ou « arrêter » de faire quelque chose. Le mot est le même que le panneau stop.", "examples": [{"text": "You must stop.", "translation": "Tu dois t''arrêter."}, {"text": "Don''t stop!", "translation": "Ne t''arrête pas !"}], "confusions": [], "forms": {"thirdPerson": "stops", "past": "stopped", "pastParticiple": "stopped", "ing": "stopping"}, "unitId": "en.v.stop"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.wait', 'en', 'wait', 'attendre', 'Wait veut dire « attendre ». Pour attendre quelqu''un ou quelque chose, on dit wait for : wait for Anna.', '[{"text": "We wait for Anna.", "translation": "Nous attendons Anna."}, {"text": "Please wait for me.", "translation": "Attends-moi, s''il te plaît."}]'::jsonb, '/weɪt/', '{"id": "en.d.wait", "word": "wait", "translation": "attendre", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/weɪt/", "explanation": "Wait veut dire « attendre ». Pour attendre quelqu''un ou quelque chose, on dit wait for : wait for Anna.", "examples": [{"text": "We wait for Anna.", "translation": "Nous attendons Anna."}, {"text": "Please wait for me.", "translation": "Attends-moi, s''il te plaît."}], "confusions": [{"word": "expect", "note": "wait = attendre (patienter) ; expect = s''attendre à."}], "forms": {"thirdPerson": "waits", "past": "waited", "pastParticiple": "waited", "ing": "waiting"}, "unitId": "en.v.wait"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.open', 'en', 'open', 'ouvrir', 'Open veut dire « ouvrir ». C''est aussi un adjectif : « ouvert ».', '[{"text": "Please open the window.", "translation": "Ouvre la fenêtre, s''il te plaît."}, {"text": "You mustn''t open the door.", "translation": "Tu ne dois pas ouvrir la porte."}]'::jsonb, '/ˈəʊpən/', '{"id": "en.d.open", "word": "open", "translation": "ouvrir", "otherTranslations": ["ouvert (adjectif)"], "partOfSpeech": "verb", "ipa": "/ˈəʊpən/", "explanation": "Open veut dire « ouvrir ». C''est aussi un adjectif : « ouvert ».", "examples": [{"text": "Please open the window.", "translation": "Ouvre la fenêtre, s''il te plaît."}, {"text": "You mustn''t open the door.", "translation": "Tu ne dois pas ouvrir la porte."}], "confusions": [{"word": "close", "note": "open = ouvrir ; close = fermer."}], "forms": {"thirdPerson": "opens", "past": "opened", "pastParticiple": "opened", "ing": "opening"}, "unitId": "en.v.open"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.close', 'en', 'close', 'fermer', 'Close veut dire « fermer ». Attention : l''adjectif close (« proche ») s''écrit pareil mais se prononce /kləʊs/, avec un s.', '[{"text": "I close my book.", "translation": "Je ferme mon livre."}, {"text": "Can you close the door?", "translation": "Peux-tu fermer la porte ?"}]'::jsonb, '/kləʊz/', '{"id": "en.d.close", "word": "close", "translation": "fermer", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/kləʊz/", "explanation": "Close veut dire « fermer ». Attention : l''adjectif close (« proche ») s''écrit pareil mais se prononce /kləʊs/, avec un s.", "examples": [{"text": "I close my book.", "translation": "Je ferme mon livre."}, {"text": "Can you close the door?", "translation": "Peux-tu fermer la porte ?"}], "confusions": [{"word": "open", "note": "close = fermer ; open = ouvrir."}], "forms": {"thirdPerson": "closes", "past": "closed", "pastParticiple": "closed", "ing": "closing"}, "unitId": "en.v.close"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.careful', 'en', 'careful', 'prudent, attentif', 'Careful veut dire « prudent, qui fait attention ». Be careful = fais attention. Il ne change pas au pluriel.', '[{"text": "You must be careful.", "translation": "Tu dois faire attention."}, {"text": "Be careful with the phone!", "translation": "Fais attention au téléphone !"}]'::jsonb, '/ˈkeəfl/', '{"id": "en.d.careful", "word": "careful", "translation": "prudent, attentif", "otherTranslations": [], "partOfSpeech": "adjective", "ipa": "/ˈkeəfl/", "explanation": "Careful veut dire « prudent, qui fait attention ». Be careful = fais attention. Il ne change pas au pluriel.", "examples": [{"text": "You must be careful.", "translation": "Tu dois faire attention."}, {"text": "Be careful with the phone!", "translation": "Fais attention au téléphone !"}], "confusions": [], "unitId": "en.v.careful"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.come', 'en', 'come', 'venir', 'Come veut dire « venir » : se déplacer vers la personne qui parle ou vers l''endroit où elle est. Come with me = viens avec moi.', '[{"text": "Come with me!", "translation": "Viens avec moi !"}, {"text": "Can you come to my house?", "translation": "Peux-tu venir chez moi ?"}]'::jsonb, '/kʌm/', '{"id": "en.d.come", "word": "come", "translation": "venir", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/kʌm/", "explanation": "Come veut dire « venir » : se déplacer vers la personne qui parle ou vers l''endroit où elle est. Come with me = viens avec moi.", "examples": [{"text": "Come with me!", "translation": "Viens avec moi !"}, {"text": "Can you come to my house?", "translation": "Peux-tu venir chez moi ?"}], "confusions": [{"word": "go", "note": "come = venir (vers ici) ; go = aller (ailleurs)."}], "forms": {"thirdPerson": "comes", "past": "came", "pastParticiple": "come", "ing": "coming"}, "unitId": "en.v.come"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.look', 'en', 'look', 'regarder', 'Look veut dire « regarder ». Devant ce qu''on regarde, on dit look at : look at the dog.', '[{"text": "Look at the dog!", "translation": "Regarde le chien !"}, {"text": "Can you look at my phone?", "translation": "Peux-tu regarder mon téléphone ?"}]'::jsonb, '/lʊk/', '{"id": "en.d.look", "word": "look", "translation": "regarder", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/lʊk/", "explanation": "Look veut dire « regarder ». Devant ce qu''on regarde, on dit look at : look at the dog.", "examples": [{"text": "Look at the dog!", "translation": "Regarde le chien !"}, {"text": "Can you look at my phone?", "translation": "Peux-tu regarder mon téléphone ?"}], "confusions": [{"word": "see", "note": "look = regarder (on le fait exprès) ; see = voir."}, {"word": "watch", "note": "watch = regarder quelque chose qui bouge (un film, un match)."}], "forms": {"thirdPerson": "looks", "past": "looked", "pastParticiple": "looked", "ing": "looking"}, "unitId": "en.v.look"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.listen', 'en', 'listen', 'écouter', 'Listen veut dire « écouter ». Devant quelqu''un ou quelque chose, on dit listen to : listen to the teacher. Le t ne se prononce pas.', '[{"text": "Listen to your mother.", "translation": "Écoute ta mère."}, {"text": "We listen to the teacher.", "translation": "Nous écoutons le professeur."}]'::jsonb, '/ˈlɪsn/', '{"id": "en.d.listen", "word": "listen", "translation": "écouter", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/ˈlɪsn/", "explanation": "Listen veut dire « écouter ». Devant quelqu''un ou quelque chose, on dit listen to : listen to the teacher. Le t ne se prononce pas.", "examples": [{"text": "Listen to your mother.", "translation": "Écoute ta mère."}, {"text": "We listen to the teacher.", "translation": "Nous écoutons le professeur."}], "confusions": [{"word": "hear", "note": "listen to = écouter (on le fait exprès) ; hear = entendre."}], "forms": {"thirdPerson": "listens", "past": "listened", "pastParticiple": "listened", "ing": "listening"}, "unitId": "en.v.listen"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.sit_down', 'en', 'sit down', 's''asseoir', 'Sit down veut dire « s''asseoir » : on passe de debout à assis. Les deux mots vont toujours ensemble dans ce sens.', '[{"text": "Please sit down.", "translation": "Asseyez-vous, s''il vous plaît."}, {"text": "We sit down and listen.", "translation": "Nous nous asseyons et nous écoutons."}]'::jsonb, '/sɪt ˈdaʊn/', '{"id": "en.d.sit_down", "word": "sit down", "translation": "s''asseoir", "otherTranslations": [], "partOfSpeech": "phrasal_verb", "ipa": "/sɪt ˈdaʊn/", "explanation": "Sit down veut dire « s''asseoir » : on passe de debout à assis. Les deux mots vont toujours ensemble dans ce sens.", "examples": [{"text": "Please sit down.", "translation": "Asseyez-vous, s''il vous plaît."}, {"text": "We sit down and listen.", "translation": "Nous nous asseyons et nous écoutons."}], "confusions": [{"word": "stand up", "note": "sit down = s''asseoir ; stand up = se lever."}], "forms": {"thirdPerson": "sits down", "past": "sat down", "pastParticiple": "sat down", "ing": "sitting down"}, "unitId": "en.v.sit_down"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.stand_up', 'en', 'stand up', 'se lever (debout)', 'Stand up veut dire « se mettre debout ». C''est le contraire de sit down.', '[{"text": "Stand up, please.", "translation": "Lève-toi, s''il te plaît."}, {"text": "We stand up and go home.", "translation": "Nous nous levons et nous rentrons."}]'::jsonb, '/stænd ˈʌp/', '{"id": "en.d.stand_up", "word": "stand up", "translation": "se lever (debout)", "otherTranslations": ["se mettre debout"], "partOfSpeech": "phrasal_verb", "ipa": "/stænd ˈʌp/", "explanation": "Stand up veut dire « se mettre debout ». C''est le contraire de sit down.", "examples": [{"text": "Stand up, please.", "translation": "Lève-toi, s''il te plaît."}, {"text": "We stand up and go home.", "translation": "Nous nous levons et nous rentrons."}], "confusions": [{"word": "get up", "note": "stand up = se mettre debout ; get up = se lever du lit."}, {"word": "sit down", "note": "stand up = se lever ; sit down = s''asseoir."}], "forms": {"thirdPerson": "stands up", "past": "stood up", "pastParticiple": "stood up", "ing": "standing up"}, "unitId": "en.v.stand_up"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.work', 'en', 'work', 'travailler', 'Work veut dire « travailler ». C''est aussi un nom : « le travail », qui ne prend pas de -s.', '[{"text": "I work in London.", "translation": "Je travaille à Londres."}, {"text": "We work with children.", "translation": "Nous travaillons avec des enfants."}]'::jsonb, '/wɜːk/', '{"id": "en.d.work", "word": "work", "translation": "travailler", "otherTranslations": ["le travail (nom)", "fonctionner"], "partOfSpeech": "verb", "ipa": "/wɜːk/", "explanation": "Work veut dire « travailler ». C''est aussi un nom : « le travail », qui ne prend pas de -s.", "examples": [{"text": "I work in London.", "translation": "Je travaille à Londres."}, {"text": "We work with children.", "translation": "Nous travaillons avec des enfants."}], "confusions": [{"word": "job", "note": "work = travailler, le travail en général ; job = un emploi précis (a job)."}], "forms": {"thirdPerson": "works", "past": "worked", "pastParticiple": "worked", "ing": "working"}, "unitId": "en.v.work"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.live', 'en', 'live', 'habiter, vivre', 'Live veut dire « habiter » (là où on a sa maison) et « vivre ». Il se prononce /lɪv/ ; l''adjectif live (« en direct ») se prononce /laɪv/.', '[{"text": "We live in Paris.", "translation": "Nous habitons à Paris."}, {"text": "I live with my parents.", "translation": "J''habite avec mes parents."}]'::jsonb, '/lɪv/', '{"id": "en.d.live", "word": "live", "translation": "habiter, vivre", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/lɪv/", "explanation": "Live veut dire « habiter » (là où on a sa maison) et « vivre ». Il se prononce /lɪv/ ; l''adjectif live (« en direct ») se prononce /laɪv/.", "examples": [{"text": "We live in Paris.", "translation": "Nous habitons à Paris."}, {"text": "I live with my parents.", "translation": "J''habite avec mes parents."}], "confusions": [{"word": "leave", "note": "live /lɪv/ = habiter ; leave /liːv/ = partir, quitter."}], "forms": {"thirdPerson": "lives", "past": "lived", "pastParticiple": "lived", "ing": "living"}, "unitId": "en.v.live"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.like', 'en', 'like', 'aimer (bien)', 'Like veut dire « aimer bien, apprécier ». C''est moins fort que love. Pour parler d''une chose en général, pas d''article : I like coffee.', '[{"text": "We like London.", "translation": "Nous aimons bien Londres."}, {"text": "They like my dog.", "translation": "Ils aiment bien mon chien."}]'::jsonb, '/laɪk/', '{"id": "en.d.like", "word": "like", "translation": "aimer (bien)", "otherTranslations": ["apprécier"], "partOfSpeech": "verb", "ipa": "/laɪk/", "explanation": "Like veut dire « aimer bien, apprécier ». C''est moins fort que love. Pour parler d''une chose en général, pas d''article : I like coffee.", "examples": [{"text": "We like London.", "translation": "Nous aimons bien Londres."}, {"text": "They like my dog.", "translation": "Ils aiment bien mon chien."}], "confusions": [{"word": "love", "note": "like = aimer bien ; love = adorer, aimer beaucoup."}], "forms": {"thirdPerson": "likes", "past": "liked", "pastParticiple": "liked", "ing": "liking"}, "unitId": "en.v.like"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.love', 'en', 'love', 'aimer, adorer', 'Love veut dire « aimer beaucoup, adorer ». Il s''utilise pour les personnes et les choses qu''on aime vraiment.', '[{"text": "I love my family.", "translation": "J''aime ma famille."}, {"text": "We love our dog.", "translation": "Nous adorons notre chien."}]'::jsonb, '/lʌv/', '{"id": "en.d.love", "word": "love", "translation": "aimer, adorer", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/lʌv/", "explanation": "Love veut dire « aimer beaucoup, adorer ». Il s''utilise pour les personnes et les choses qu''on aime vraiment.", "examples": [{"text": "I love my family.", "translation": "J''aime ma famille."}, {"text": "We love our dog.", "translation": "Nous adorons notre chien."}], "confusions": [{"word": "like", "note": "love = adorer ; like = aimer bien."}], "forms": {"thirdPerson": "loves", "past": "loved", "pastParticiple": "loved", "ing": "loving"}, "unitId": "en.v.love"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.eat', 'en', 'eat', 'manger', 'Eat veut dire « manger ». On dit eat dinner pour « dîner ».', '[{"text": "We eat dinner at home.", "translation": "Nous dînons à la maison."}, {"text": "I want to eat.", "translation": "Je veux manger."}]'::jsonb, '/iːt/', '{"id": "en.d.eat", "word": "eat", "translation": "manger", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/iːt/", "explanation": "Eat veut dire « manger ». On dit eat dinner pour « dîner ».", "examples": [{"text": "We eat dinner at home.", "translation": "Nous dînons à la maison."}, {"text": "I want to eat.", "translation": "Je veux manger."}], "confusions": [{"word": "drink", "note": "eat = manger ; drink = boire."}], "forms": {"thirdPerson": "eats", "past": "ate", "pastParticiple": "eaten", "ing": "eating"}, "unitId": "en.v.eat"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.to', 'en', 'to', 'à, vers ; (devant un verbe) de', 'To a deux emplois. Devant un verbe de base, il l''introduit : want to go, need to wait. Devant un lieu, il veut dire « à, vers » : go to school. Devant home, on n''utilise pas to : go home. Dans la conversation, il se prononce souvent /tə/.', '[{"text": "I want to go home.", "translation": "Je veux rentrer à la maison."}, {"text": "We go to school.", "translation": "Nous allons à l''école."}]'::jsonb, '/tuː/', '{"id": "en.d.to", "word": "to", "translation": "à, vers ; (devant un verbe) de", "otherTranslations": ["pour"], "partOfSpeech": "preposition", "ipa": "/tuː/", "explanation": "To a deux emplois. Devant un verbe de base, il l''introduit : want to go, need to wait. Devant un lieu, il veut dire « à, vers » : go to school. Devant home, on n''utilise pas to : go home. Dans la conversation, il se prononce souvent /tə/.", "examples": [{"text": "I want to go home.", "translation": "Je veux rentrer à la maison."}, {"text": "We go to school.", "translation": "Nous allons à l''école."}], "confusions": [{"word": "too", "note": "too = aussi, trop ; to = à, vers, ou devant un verbe."}, {"word": "two", "note": "two = le nombre 2 ; to se prononce pareil."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.can', 'en', 'can', 'pouvoir, savoir (faire)', 'Can est un verbe modal : il se place devant un verbe de base, sans to et sans -s. Il exprime la capacité (I can swim), la possibilité, la permission ou une demande (Can you help me?). Pour poser une question, on le met avant le sujet.', '[{"text": "I can swim.", "translation": "Je sais nager."}, {"text": "Can I take your bag?", "translation": "Puis-je prendre ton sac ?"}]'::jsonb, '/kæn/', '{"id": "en.d.can", "word": "can", "translation": "pouvoir, savoir (faire)", "otherTranslations": [], "partOfSpeech": "modal", "ipa": "/kæn/", "explanation": "Can est un verbe modal : il se place devant un verbe de base, sans to et sans -s. Il exprime la capacité (I can swim), la possibilité, la permission ou une demande (Can you help me?). Pour poser une question, on le met avant le sujet.", "examples": [{"text": "I can swim.", "translation": "Je sais nager."}, {"text": "Can I take your bag?", "translation": "Puis-je prendre ton sac ?"}], "confusions": [{"word": "can''t", "note": "can = pouvoir ; can''t = ne pas pouvoir, ne pas savoir."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.cant', 'en', 'can''t', 'ne pas pouvoir, ne pas savoir', 'Can''t est la contraction de cannot (can + not). Il exprime l''incapacité (I can''t swim) ou l''impossibilité. Il est suivi du verbe de base, sans to et sans -s.', '[{"text": "She can''t drive.", "translation": "Elle ne sait pas conduire."}, {"text": "We can''t open the door.", "translation": "Nous ne pouvons pas ouvrir la porte."}]'::jsonb, '/kɑːnt/', '{"id": "en.d.cant", "word": "can''t", "translation": "ne pas pouvoir, ne pas savoir", "otherTranslations": [], "partOfSpeech": "modal", "ipa": "/kɑːnt/", "explanation": "Can''t est la contraction de cannot (can + not). Il exprime l''incapacité (I can''t swim) ou l''impossibilité. Il est suivi du verbe de base, sans to et sans -s.", "examples": [{"text": "She can''t drive.", "translation": "Elle ne sait pas conduire."}, {"text": "We can''t open the door.", "translation": "Nous ne pouvons pas ouvrir la porte."}], "confusions": [{"word": "cannot", "note": "can''t et cannot ont le même sens ; cannot est plus formel."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.cannot', 'en', 'cannot', 'ne pas pouvoir, ne pas savoir', 'Cannot est la forme négative de can, écrite en un seul mot. Il a le même sens que can''t, mais il est un peu plus formel. Il est suivi du verbe de base, sans to.', '[{"text": "You cannot open the window.", "translation": "Tu ne peux pas ouvrir la fenêtre."}, {"text": "I cannot read your name.", "translation": "Je ne peux pas lire ton nom."}]'::jsonb, '/ˈkænɒt/', '{"id": "en.d.cannot", "word": "cannot", "translation": "ne pas pouvoir, ne pas savoir", "otherTranslations": [], "partOfSpeech": "modal", "ipa": "/ˈkænɒt/", "explanation": "Cannot est la forme négative de can, écrite en un seul mot. Il a le même sens que can''t, mais il est un peu plus formel. Il est suivi du verbe de base, sans to.", "examples": [{"text": "You cannot open the window.", "translation": "Tu ne peux pas ouvrir la fenêtre."}, {"text": "I cannot read your name.", "translation": "Je ne peux pas lire ton nom."}], "confusions": [{"word": "can''t", "note": "cannot = forme complète et plus formelle ; can''t = forme courte, la plus courante à l''oral."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.must', 'en', 'must', 'devoir, il faut', 'Must est un verbe modal qui exprime une obligation forte. Il est suivi du verbe de base, sans to et sans -s : you must stop.', '[{"text": "You must stop.", "translation": "Tu dois t''arrêter."}, {"text": "We must wait for Anna.", "translation": "Nous devons attendre Anna."}]'::jsonb, '/mʌst/', '{"id": "en.d.must", "word": "must", "translation": "devoir, il faut", "otherTranslations": [], "partOfSpeech": "modal", "ipa": "/mʌst/", "explanation": "Must est un verbe modal qui exprime une obligation forte. Il est suivi du verbe de base, sans to et sans -s : you must stop.", "examples": [{"text": "You must stop.", "translation": "Tu dois t''arrêter."}, {"text": "We must wait for Anna.", "translation": "Nous devons attendre Anna."}], "confusions": [{"word": "need", "note": "must = obligation forte ; need to = avoir besoin de."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.mustnt', 'en', 'mustn''t', 'ne pas devoir, interdit de', 'Mustn''t est la contraction de must not. Il exprime une interdiction : « il ne faut pas ». Il ne veut pas dire « ce n''est pas nécessaire ». Il est suivi du verbe de base, sans to.', '[{"text": "You mustn''t open the door.", "translation": "Tu ne dois pas ouvrir la porte."}, {"text": "We mustn''t be late.", "translation": "Nous ne devons pas être en retard."}]'::jsonb, '/ˈmʌsnt/', '{"id": "en.d.mustnt", "word": "mustn''t", "translation": "ne pas devoir, interdit de", "otherTranslations": [], "partOfSpeech": "modal", "ipa": "/ˈmʌsnt/", "explanation": "Mustn''t est la contraction de must not. Il exprime une interdiction : « il ne faut pas ». Il ne veut pas dire « ce n''est pas nécessaire ». Il est suivi du verbe de base, sans to.", "examples": [{"text": "You mustn''t open the door.", "translation": "Tu ne dois pas ouvrir la porte."}, {"text": "We mustn''t be late.", "translation": "Nous ne devons pas être en retard."}], "confusions": [{"word": "must", "note": "mustn''t = interdit ; must = obligatoire."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.lets', 'en', 'let''s', 'allons… / faisons…', 'Let''s est la contraction de let us. On l''utilise pour proposer à plusieurs de faire quelque chose. Il est suivi du verbe de base, sans to : Let''s go!', '[{"text": "Let''s go home.", "translation": "Rentrons à la maison."}, {"text": "Let''s wait for Anna.", "translation": "Attendons Anna."}]'::jsonb, '/lets/', '{"id": "en.d.lets", "word": "let''s", "translation": "allons… / faisons…", "otherTranslations": [], "partOfSpeech": "expression", "ipa": "/lets/", "explanation": "Let''s est la contraction de let us. On l''utilise pour proposer à plusieurs de faire quelque chose. Il est suivi du verbe de base, sans to : Let''s go!", "examples": [{"text": "Let''s go home.", "translation": "Rentrons à la maison."}, {"text": "Let''s wait for Anna.", "translation": "Attendons Anna."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.drink', 'en', 'drink', 'boire', 'Drink veut dire « boire » : on l''utilise pour le café, l''eau, le lait et toutes les boissons.', '[{"text": "My father drinks coffee at home.", "translation": "Mon père boit du café à la maison."}, {"text": "Do you want a drink?", "translation": "Tu veux boire quelque chose ?"}]'::jsonb, '/drɪŋk/', '{"id": "en.d.drink", "word": "drink", "translation": "boire", "otherTranslations": ["une boisson (nom)"], "partOfSpeech": "verb", "ipa": "/drɪŋk/", "explanation": "Drink veut dire « boire » : on l''utilise pour le café, l''eau, le lait et toutes les boissons.", "examples": [{"text": "My father drinks coffee at home.", "translation": "Mon père boit du café à la maison."}, {"text": "Do you want a drink?", "translation": "Tu veux boire quelque chose ?"}], "confusions": [{"word": "drunk", "note": "participe passé de drink (bu) ; aussi « ivre »."}], "forms": {"thirdPerson": "drinks", "past": "drank", "pastParticiple": "drunk", "ing": "drinking"}, "unitId": "en.v.drink"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.play', 'en', 'play', 'jouer', 'Play veut dire « jouer » : à un jeu, à un sport, avec quelqu''un ou avec un objet.', '[{"text": "My son plays with his friends after school.", "translation": "Mon fils joue avec ses amis après l''école."}, {"text": "They play in the house.", "translation": "Ils jouent dans la maison."}]'::jsonb, '/pleɪ/', '{"id": "en.d.play", "word": "play", "translation": "jouer", "otherTranslations": ["une pièce de théâtre (nom)"], "partOfSpeech": "verb", "ipa": "/pleɪ/", "explanation": "Play veut dire « jouer » : à un jeu, à un sport, avec quelqu''un ou avec un objet.", "examples": [{"text": "My son plays with his friends after school.", "translation": "Mon fils joue avec ses amis après l''école."}, {"text": "They play in the house.", "translation": "Ils jouent dans la maison."}], "confusions": [{"word": "do", "note": "On dit play pour un jeu ou un sport collectif (play football), mais do pour une activité comme le yoga ou le judo."}], "forms": {"thirdPerson": "plays", "past": "played", "pastParticiple": "played", "ing": "playing"}, "unitId": "en.v.play"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.watch', 'en', 'watch', 'regarder (un écran, un match)', 'Watch s''utilise pour regarder quelque chose qui bouge ou qui dure : la télé, un film, un match.', '[{"text": "My parents watch TV after dinner.", "translation": "Mes parents regardent la télé après le dîner."}, {"text": "She watches a film with her brother.", "translation": "Elle regarde un film avec son frère."}]'::jsonb, '/wɒtʃ/', '{"id": "en.d.watch", "word": "watch", "translation": "regarder (un écran, un match)", "otherTranslations": ["une montre (nom)"], "partOfSpeech": "verb", "ipa": "/wɒtʃ/", "explanation": "Watch s''utilise pour regarder quelque chose qui bouge ou qui dure : la télé, un film, un match.", "examples": [{"text": "My parents watch TV after dinner.", "translation": "Mes parents regardent la télé après le dîner."}, {"text": "She watches a film with her brother.", "translation": "Elle regarde un film avec son frère."}], "confusions": [{"word": "look", "note": "look at s''emploie pour regarder un objet ou une image un instant (look at the picture)."}, {"word": "see", "note": "see veut dire « voir » : on voit sans le faire exprès (I see a dog)."}], "forms": {"thirdPerson": "watches", "past": "watched", "pastParticiple": "watched", "ing": "watching"}, "unitId": "en.v.watch"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.sleep', 'en', 'sleep', 'dormir', 'Sleep veut dire « dormir » : être endormi, au lit ou ailleurs.', '[{"text": "My dog sleeps in the house.", "translation": "Mon chien dort dans la maison."}, {"text": "The children sleep early.", "translation": "Les enfants dorment tôt."}]'::jsonb, '/sliːp/', '{"id": "en.d.sleep", "word": "sleep", "translation": "dormir", "otherTranslations": ["le sommeil (nom)"], "partOfSpeech": "verb", "ipa": "/sliːp/", "explanation": "Sleep veut dire « dormir » : être endormi, au lit ou ailleurs.", "examples": [{"text": "My dog sleeps in the house.", "translation": "Mon chien dort dans la maison."}, {"text": "The children sleep early.", "translation": "Les enfants dorment tôt."}], "confusions": [], "forms": {"thirdPerson": "sleeps", "past": "slept", "pastParticiple": "slept", "ing": "sleeping"}, "unitId": "en.v.sleep"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.cook', 'en', 'cook', 'cuisiner, faire cuire', 'Cook veut dire « préparer un repas en le faisant cuire » : on peut cook dinner ou simplement cook.', '[{"text": "My mother cooks dinner for the family.", "translation": "Ma mère prépare le dîner pour la famille."}, {"text": "I don''t cook in the evening.", "translation": "Je ne cuisine pas le soir."}]'::jsonb, '/kʊk/', '{"id": "en.d.cook", "word": "cook", "translation": "cuisiner, faire cuire", "otherTranslations": ["un cuisinier, une cuisinière (nom)"], "partOfSpeech": "verb", "ipa": "/kʊk/", "explanation": "Cook veut dire « préparer un repas en le faisant cuire » : on peut cook dinner ou simplement cook.", "examples": [{"text": "My mother cooks dinner for the family.", "translation": "Ma mère prépare le dîner pour la famille."}, {"text": "I don''t cook in the evening.", "translation": "Je ne cuisine pas le soir."}], "confusions": [], "forms": {"thirdPerson": "cooks", "past": "cooked", "pastParticiple": "cooked", "ing": "cooking"}, "unitId": "en.v.cook"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.study', 'en', 'study', 'étudier', 'Study veut dire « étudier » une matière ou faire des études. À la 3e personne : he studies (y → ies).', '[{"text": "Lucy studies French at school.", "translation": "Lucy étudie le français à l''école."}, {"text": "I study English every day.", "translation": "J''étudie l''anglais tous les jours."}]'::jsonb, '/ˈstʌdi/', '{"id": "en.d.study", "word": "study", "translation": "étudier", "otherTranslations": ["une étude (nom)"], "partOfSpeech": "verb", "ipa": "/ˈstʌdi/", "explanation": "Study veut dire « étudier » une matière ou faire des études. À la 3e personne : he studies (y → ies).", "examples": [{"text": "Lucy studies French at school.", "translation": "Lucy étudie le français à l''école."}, {"text": "I study English every day.", "translation": "J''étudie l''anglais tous les jours."}], "confusions": [{"word": "learn", "note": "study = étudier (travailler une matière) ; learn = apprendre (acquérir un savoir)."}], "forms": {"thirdPerson": "studies", "past": "studied", "pastParticiple": "studied", "ing": "studying"}, "unitId": "en.v.study"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.finish', 'en', 'finish', 'finir, terminer', 'Finish veut dire « finir » ou « terminer » quelque chose qu''on a commencé. À la 3e personne : he finishes.', '[{"text": "Tom finishes his homework after dinner.", "translation": "Tom finit ses devoirs après le dîner."}, {"text": "We finish work at six.", "translation": "Nous finissons le travail à six heures."}]'::jsonb, '/ˈfɪnɪʃ/', '{"id": "en.d.finish", "word": "finish", "translation": "finir, terminer", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/ˈfɪnɪʃ/", "explanation": "Finish veut dire « finir » ou « terminer » quelque chose qu''on a commencé. À la 3e personne : he finishes.", "examples": [{"text": "Tom finishes his homework after dinner.", "translation": "Tom finit ses devoirs après le dîner."}, {"text": "We finish work at six.", "translation": "Nous finissons le travail à six heures."}], "confusions": [], "forms": {"thirdPerson": "finishes", "past": "finished", "pastParticiple": "finished", "ing": "finishing"}, "unitId": "en.v.finish"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.teach', 'en', 'teach', 'enseigner', 'Teach veut dire « enseigner » : transmettre un savoir à quelqu''un. À la 3e personne : he teaches.', '[{"text": "My mother teaches English at a school.", "translation": "Ma mère enseigne l''anglais dans une école."}, {"text": "I teach my son to swim.", "translation": "J''apprends à mon fils à nager."}]'::jsonb, '/tiːtʃ/', '{"id": "en.d.teach", "word": "teach", "translation": "enseigner", "otherTranslations": ["apprendre quelque chose à quelqu''un"], "partOfSpeech": "verb", "ipa": "/tiːtʃ/", "explanation": "Teach veut dire « enseigner » : transmettre un savoir à quelqu''un. À la 3e personne : he teaches.", "examples": [{"text": "My mother teaches English at a school.", "translation": "Ma mère enseigne l''anglais dans une école."}, {"text": "I teach my son to swim.", "translation": "J''apprends à mon fils à nager."}], "confusions": [{"word": "learn", "note": "teach = enseigner (celui qui sait) ; learn = apprendre (celui qui étudie)."}], "forms": {"thirdPerson": "teaches", "past": "taught", "pastParticiple": "taught", "ing": "teaching"}, "unitId": "en.v.teach"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.carry', 'en', 'carry', 'porter, transporter', 'Carry veut dire « porter » un objet dans ses mains ou sur soi pour le transporter. À la 3e personne : he carries.', '[{"text": "Anna carries her bag to school.", "translation": "Anna porte son sac à l''école."}, {"text": "My father carries the bags to the car.", "translation": "Mon père porte les sacs jusqu''à la voiture."}]'::jsonb, '/ˈkæri/', '{"id": "en.d.carry", "word": "carry", "translation": "porter, transporter", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/ˈkæri/", "explanation": "Carry veut dire « porter » un objet dans ses mains ou sur soi pour le transporter. À la 3e personne : he carries.", "examples": [{"text": "Anna carries her bag to school.", "translation": "Anna porte son sac à l''école."}, {"text": "My father carries the bags to the car.", "translation": "Mon père porte les sacs jusqu''à la voiture."}], "confusions": [{"word": "wear", "note": "carry = porter un objet qu''on transporte ; wear = porter un vêtement sur soi."}], "forms": {"thirdPerson": "carries", "past": "carried", "pastParticiple": "carried", "ing": "carrying"}, "unitId": "en.v.carry"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.fix', 'en', 'fix', 'réparer', 'Fix veut dire « réparer » un objet cassé ou un problème. À la 3e personne : he fixes.', '[{"text": "My father fixes the car.", "translation": "Mon père répare la voiture."}, {"text": "Can you fix my phone?", "translation": "Tu peux réparer mon téléphone ?"}]'::jsonb, '/fɪks/', '{"id": "en.d.fix", "word": "fix", "translation": "réparer", "otherTranslations": ["fixer, arranger (une date)"], "partOfSpeech": "verb", "ipa": "/fɪks/", "explanation": "Fix veut dire « réparer » un objet cassé ou un problème. À la 3e personne : he fixes.", "examples": [{"text": "My father fixes the car.", "translation": "Mon père répare la voiture."}, {"text": "Can you fix my phone?", "translation": "Tu peux réparer mon téléphone ?"}], "confusions": [{"word": "repair", "note": "synonyme un peu plus formel : repair a car."}], "forms": {"thirdPerson": "fixes", "past": "fixed", "pastParticiple": "fixed", "ing": "fixing"}, "unitId": "en.v.fix"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.food', 'en', 'food', 'nourriture', 'Food désigne la nourriture en général. C''est un nom indénombrable : on dit food, pas « a food ».', '[{"text": "I like the food in London.", "translation": "J''aime la nourriture de Londres."}, {"text": "We don''t have food at home.", "translation": "Nous n''avons pas de nourriture à la maison."}]'::jsonb, '/fuːd/', '{"id": "en.d.food", "word": "food", "translation": "nourriture", "otherTranslations": ["un aliment, un plat"], "partOfSpeech": "noun", "ipa": "/fuːd/", "explanation": "Food désigne la nourriture en général. C''est un nom indénombrable : on dit food, pas « a food ».", "examples": [{"text": "I like the food in London.", "translation": "J''aime la nourriture de Londres."}, {"text": "We don''t have food at home.", "translation": "Nous n''avons pas de nourriture à la maison."}], "confusions": [{"word": "meal", "note": "food = la nourriture en général ; meal = un repas (breakfast, lunch, dinner)."}], "forms": {}, "unitId": "en.v.food"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.meat', 'en', 'meat', 'viande', 'Meat désigne la viande en général (bœuf, poulet, etc.). C''est un nom indénombrable, sans article quand on parle en général.', '[{"text": "I don''t eat meat.", "translation": "Je ne mange pas de viande."}, {"text": "My brother likes meat and fish.", "translation": "Mon frère aime la viande et le poisson."}]'::jsonb, '/miːt/', '{"id": "en.d.meat", "word": "meat", "translation": "viande", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/miːt/", "explanation": "Meat désigne la viande en général (bœuf, poulet, etc.). C''est un nom indénombrable, sans article quand on parle en général.", "examples": [{"text": "I don''t eat meat.", "translation": "Je ne mange pas de viande."}, {"text": "My brother likes meat and fish.", "translation": "Mon frère aime la viande et le poisson."}], "confusions": [{"word": "meet", "note": "se prononce de la même façon, mais meet veut dire « rencontrer »."}], "forms": {}, "unitId": "en.v.meat"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.fish', 'en', 'fish', 'poisson', 'Fish désigne le poisson, vivant ou dans l''assiette. Il ne change pas au pluriel : one fish, two fish.', '[{"text": "She doesn''t eat fish.", "translation": "Elle ne mange pas de poisson."}, {"text": "We eat fish at home.", "translation": "Nous mangeons du poisson à la maison."}]'::jsonb, '/fɪʃ/', '{"id": "en.d.fish", "word": "fish", "translation": "poisson", "otherTranslations": ["pêcher (verbe)"], "partOfSpeech": "noun", "ipa": "/fɪʃ/", "explanation": "Fish désigne le poisson, vivant ou dans l''assiette. Il ne change pas au pluriel : one fish, two fish.", "examples": [{"text": "She doesn''t eat fish.", "translation": "Elle ne mange pas de poisson."}, {"text": "We eat fish at home.", "translation": "Nous mangeons du poisson à la maison."}], "confusions": [], "forms": {"plural": "fish"}, "unitId": "en.v.fish"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.milk', 'en', 'milk', 'lait', 'Milk désigne le lait. C''est un nom indénombrable : on dit milk, pas « a milk ».', '[{"text": "My son drinks milk in the morning.", "translation": "Mon fils boit du lait le matin."}, {"text": "I take milk in my coffee.", "translation": "Je prends du lait dans mon café."}]'::jsonb, '/mɪlk/', '{"id": "en.d.milk", "word": "milk", "translation": "lait", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/mɪlk/", "explanation": "Milk désigne le lait. C''est un nom indénombrable : on dit milk, pas « a milk ».", "examples": [{"text": "My son drinks milk in the morning.", "translation": "Mon fils boit du lait le matin."}, {"text": "I take milk in my coffee.", "translation": "Je prends du lait dans mon café."}], "confusions": [], "forms": {}, "unitId": "en.v.milk"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.water', 'en', 'water', 'eau', 'Water désigne l''eau. C''est un nom indénombrable : on dit water, pas « a water ».', '[{"text": "My daughter doesn''t drink water.", "translation": "Ma fille ne boit pas d''eau."}, {"text": "Do you want some water?", "translation": "Tu veux de l''eau ?"}]'::jsonb, '/ˈwɔːtə/', '{"id": "en.d.water", "word": "water", "translation": "eau", "otherTranslations": ["arroser (verbe)"], "partOfSpeech": "noun", "ipa": "/ˈwɔːtə/", "explanation": "Water désigne l''eau. C''est un nom indénombrable : on dit water, pas « a water ».", "examples": [{"text": "My daughter doesn''t drink water.", "translation": "Ma fille ne boit pas d''eau."}, {"text": "Do you want some water?", "translation": "Tu veux de l''eau ?"}], "confusions": [], "forms": {}, "unitId": "en.v.water"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.breakfast', 'en', 'breakfast', 'petit-déjeuner', 'Breakfast est le premier repas de la journée. On dit have breakfast ou eat breakfast, sans article.', '[{"text": "Do you eat breakfast at home?", "translation": "Tu prends ton petit-déjeuner à la maison ?"}, {"text": "We have breakfast at seven.", "translation": "Nous prenons le petit-déjeuner à sept heures."}]'::jsonb, '/ˈbrekfəst/', '{"id": "en.d.breakfast", "word": "breakfast", "translation": "petit-déjeuner", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈbrekfəst/", "explanation": "Breakfast est le premier repas de la journée. On dit have breakfast ou eat breakfast, sans article.", "examples": [{"text": "Do you eat breakfast at home?", "translation": "Tu prends ton petit-déjeuner à la maison ?"}, {"text": "We have breakfast at seven.", "translation": "Nous prenons le petit-déjeuner à sept heures."}], "confusions": [], "forms": {"plural": "breakfasts"}, "unitId": "en.v.breakfast"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.lunch', 'en', 'lunch', 'déjeuner (repas de midi)', 'Lunch est le repas de midi. On dit have lunch ou eat lunch, sans article.', '[{"text": "Does your sister eat lunch at school?", "translation": "Ta sœur déjeune à l''école ?"}, {"text": "My brother has lunch at the office.", "translation": "Mon frère déjeune au bureau."}]'::jsonb, '/lʌntʃ/', '{"id": "en.d.lunch", "word": "lunch", "translation": "déjeuner (repas de midi)", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/lʌntʃ/", "explanation": "Lunch est le repas de midi. On dit have lunch ou eat lunch, sans article.", "examples": [{"text": "Does your sister eat lunch at school?", "translation": "Ta sœur déjeune à l''école ?"}, {"text": "My brother has lunch at the office.", "translation": "Mon frère déjeune au bureau."}], "confusions": [{"word": "dinner", "note": "dinner = le repas du soir (ou le repas principal) ; le repas de midi se dit lunch."}], "forms": {"plural": "lunches"}, "unitId": "en.v.lunch"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.morning', 'en', 'morning', 'matin', 'Morning est le début de la journée, jusqu''à midi. On dit in the morning pour « le matin ».', '[{"text": "Do you drink coffee in the morning?", "translation": "Tu bois du café le matin ?"}, {"text": "She goes to the gym in the morning.", "translation": "Elle va à la salle de sport le matin."}]'::jsonb, '/ˈmɔːnɪŋ/', '{"id": "en.d.morning", "word": "morning", "translation": "matin", "otherTranslations": ["la matinée"], "partOfSpeech": "noun", "ipa": "/ˈmɔːnɪŋ/", "explanation": "Morning est le début de la journée, jusqu''à midi. On dit in the morning pour « le matin ».", "examples": [{"text": "Do you drink coffee in the morning?", "translation": "Tu bois du café le matin ?"}, {"text": "She goes to the gym in the morning.", "translation": "Elle va à la salle de sport le matin."}], "confusions": [], "forms": {"plural": "mornings"}, "unitId": "en.v.morning"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.evening', 'en', 'evening', 'soir, soirée', 'Evening est la fin de la journée, avant d''aller dormir. On dit in the evening pour « le soir ».', '[{"text": "My mother cooks dinner in the evening.", "translation": "Ma mère prépare le dîner le soir."}, {"text": "We often watch TV in the evening.", "translation": "Nous regardons souvent la télé le soir."}]'::jsonb, '/ˈiːvnɪŋ/', '{"id": "en.d.evening", "word": "evening", "translation": "soir, soirée", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈiːvnɪŋ/", "explanation": "Evening est la fin de la journée, avant d''aller dormir. On dit in the evening pour « le soir ».", "examples": [{"text": "My mother cooks dinner in the evening.", "translation": "Ma mère prépare le dîner le soir."}, {"text": "We often watch TV in the evening.", "translation": "Nous regardons souvent la télé le soir."}], "confusions": [{"word": "night", "note": "evening = la soirée, avant d''aller dormir ; night = la nuit, quand on dort. On dit Good evening en arrivant, Good night en partant se coucher."}], "forms": {"plural": "evenings"}, "unitId": "en.v.evening"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.night', 'en', 'night', 'nuit', 'Night est la période où l''on dort. On dit at night pour « la nuit » (et non in the night).', '[{"text": "Does your brother work at night?", "translation": "Ton frère travaille la nuit ?"}, {"text": "My dog sleeps in the house at night.", "translation": "Mon chien dort dans la maison la nuit."}]'::jsonb, '/naɪt/', '{"id": "en.d.night", "word": "night", "translation": "nuit", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/naɪt/", "explanation": "Night est la période où l''on dort. On dit at night pour « la nuit » (et non in the night).", "examples": [{"text": "Does your brother work at night?", "translation": "Ton frère travaille la nuit ?"}, {"text": "My dog sleeps in the house at night.", "translation": "Mon chien dort dans la maison la nuit."}], "confusions": [{"word": "evening", "note": "night = la nuit ; evening = la soirée, avant d''aller se coucher."}], "forms": {"plural": "nights"}, "unitId": "en.v.night"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.day', 'en', 'day', 'jour, journée', 'Day veut dire à la fois « jour » et « journée » : every day = tous les jours, during the day = pendant la journée.', '[{"text": "I drink water every day.", "translation": "Je bois de l''eau tous les jours."}, {"text": "My father never watches TV during the day.", "translation": "Mon père ne regarde jamais la télé pendant la journée."}]'::jsonb, '/deɪ/', '{"id": "en.d.day", "word": "day", "translation": "jour, journée", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/deɪ/", "explanation": "Day veut dire à la fois « jour » et « journée » : every day = tous les jours, during the day = pendant la journée.", "examples": [{"text": "I drink water every day.", "translation": "Je bois de l''eau tous les jours."}, {"text": "My father never watches TV during the day.", "translation": "Mon père ne regarde jamais la télé pendant la journée."}], "confusions": [], "forms": {"plural": "days"}, "unitId": "en.v.day"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.weekend', 'en', 'weekend', 'week-end', 'Weekend désigne le samedi et le dimanche. En anglais britannique, on dit at the weekend ; en américain, on the weekend.', '[{"text": "We often listen to music at the weekend.", "translation": "Nous écoutons souvent de la musique le week-end."}, {"text": "Tom is always happy at the weekend.", "translation": "Tom est toujours content le week-end."}]'::jsonb, '/ˌwiːkˈend/', '{"id": "en.d.weekend", "word": "weekend", "translation": "week-end", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˌwiːkˈend/", "explanation": "Weekend désigne le samedi et le dimanche. En anglais britannique, on dit at the weekend ; en américain, on the weekend.", "examples": [{"text": "We often listen to music at the weekend.", "translation": "Nous écoutons souvent de la musique le week-end."}, {"text": "Tom is always happy at the weekend.", "translation": "Tom est toujours content le week-end."}], "confusions": [], "forms": {"plural": "weekends"}, "unitId": "en.v.weekend"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.early', 'en', 'early', 'tôt', 'Early veut dire « tôt » ou « en avance » par rapport à l''heure habituelle. Il se place souvent à la fin de la phrase.', '[{"text": "My sister never goes to bed early.", "translation": "Ma sœur ne se couche jamais tôt."}, {"text": "We eat dinner early.", "translation": "Nous dînons tôt."}]'::jsonb, '/ˈɜːli/', '{"id": "en.d.early", "word": "early", "translation": "tôt", "otherTranslations": ["en avance", "de bonne heure"], "partOfSpeech": "adverb", "ipa": "/ˈɜːli/", "explanation": "Early veut dire « tôt » ou « en avance » par rapport à l''heure habituelle. Il se place souvent à la fin de la phrase.", "examples": [{"text": "My sister never goes to bed early.", "translation": "Ma sœur ne se couche jamais tôt."}, {"text": "We eat dinner early.", "translation": "Nous dînons tôt."}], "confusions": [{"word": "soon", "note": "early = tôt (avant l''heure habituelle) ; soon = bientôt."}], "forms": {"comparative": "earlier", "superlative": "earliest"}, "unitId": "en.v.early"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.music', 'en', 'music', 'musique', 'Music désigne la musique. C''est un nom indénombrable : on dit music, pas « a music ». On écoute de la musique : listen to music.', '[{"text": "My brother sometimes listens to music.", "translation": "Mon frère écoute parfois de la musique."}, {"text": "I never play music at night.", "translation": "Je ne joue jamais de musique la nuit."}]'::jsonb, '/ˈmjuːzɪk/', '{"id": "en.d.music", "word": "music", "translation": "musique", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈmjuːzɪk/", "explanation": "Music désigne la musique. C''est un nom indénombrable : on dit music, pas « a music ». On écoute de la musique : listen to music.", "examples": [{"text": "My brother sometimes listens to music.", "translation": "Mon frère écoute parfois de la musique."}, {"text": "I never play music at night.", "translation": "Je ne joue jamais de musique la nuit."}], "confusions": [], "forms": {}, "unitId": "en.v.music"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.gym', 'en', 'gym', 'salle de sport', 'Gym désigne la salle de sport. On dit go to the gym pour y aller.', '[{"text": "I always go to the gym in the morning.", "translation": "Je vais toujours à la salle de sport le matin."}, {"text": "Anna usually goes to the gym early.", "translation": "Anna va d''habitude à la salle de sport tôt."}]'::jsonb, '/dʒɪm/', '{"id": "en.d.gym", "word": "gym", "translation": "salle de sport", "otherTranslations": ["la gym, la gymnastique"], "partOfSpeech": "noun", "ipa": "/dʒɪm/", "explanation": "Gym désigne la salle de sport. On dit go to the gym pour y aller.", "examples": [{"text": "I always go to the gym in the morning.", "translation": "Je vais toujours à la salle de sport le matin."}, {"text": "Anna usually goes to the gym early.", "translation": "Anna va d''habitude à la salle de sport tôt."}], "confusions": [], "forms": {"plural": "gyms"}, "unitId": "en.v.gym"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.wake_up', 'en', 'wake up', 'se réveiller', 'Wake up veut dire « se réveiller » : ouvrir les yeux après avoir dormi. On ne dit pas « wake up myself ».', '[{"text": "I usually wake up at six.", "translation": "Je me réveille d''habitude à six heures."}, {"text": "She wakes up early at the weekend.", "translation": "Elle se réveille tôt le week-end."}]'::jsonb, '/ˌweɪk ˈʌp/', '{"id": "en.d.wake_up", "word": "wake up", "translation": "se réveiller", "otherTranslations": ["réveiller (quelqu''un)"], "partOfSpeech": "phrasal_verb", "ipa": "/ˌweɪk ˈʌp/", "explanation": "Wake up veut dire « se réveiller » : ouvrir les yeux après avoir dormi. On ne dit pas « wake up myself ».", "examples": [{"text": "I usually wake up at six.", "translation": "Je me réveille d''habitude à six heures."}, {"text": "She wakes up early at the weekend.", "translation": "Elle se réveille tôt le week-end."}], "confusions": [{"word": "get up", "note": "wake up = se réveiller ; get up = se lever (sortir du lit)."}], "forms": {"thirdPerson": "wakes up", "past": "woke up", "pastParticiple": "woken up", "ing": "waking up"}, "unitId": "en.v.wake_up"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.get_up', 'en', 'get up', 'se lever (du lit)', 'Get up veut dire « se lever » : sortir du lit. On ne dit pas « get up myself ».', '[{"text": "I always get up at seven.", "translation": "Je me lève toujours à sept heures."}, {"text": "My brother never gets up early.", "translation": "Mon frère ne se lève jamais tôt."}]'::jsonb, '/ˌɡet ˈʌp/', '{"id": "en.d.get_up", "word": "get up", "translation": "se lever (du lit)", "otherTranslations": [], "partOfSpeech": "phrasal_verb", "ipa": "/ˌɡet ˈʌp/", "explanation": "Get up veut dire « se lever » : sortir du lit. On ne dit pas « get up myself ».", "examples": [{"text": "I always get up at seven.", "translation": "Je me lève toujours à sept heures."}, {"text": "My brother never gets up early.", "translation": "Mon frère ne se lève jamais tôt."}], "confusions": [{"word": "wake up", "note": "get up = se lever ; wake up = se réveiller."}], "forms": {"thirdPerson": "gets up", "past": "got up", "pastParticiple": "got up", "ing": "getting up"}, "unitId": "en.v.get_up"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.go_to_bed', 'en', 'go to bed', 'aller se coucher', 'Go to bed veut dire « aller se coucher » : on dit go to bed, sans article devant bed.', '[{"text": "He never goes to bed late.", "translation": "Il ne se couche jamais tard."}, {"text": "The children go to bed at eight.", "translation": "Les enfants se couchent à huit heures."}]'::jsonb, '/ˌɡəʊ tə ˈbed/', '{"id": "en.d.go_to_bed", "word": "go to bed", "translation": "aller se coucher", "otherTranslations": [], "partOfSpeech": "expression", "ipa": "/ˌɡəʊ tə ˈbed/", "explanation": "Go to bed veut dire « aller se coucher » : on dit go to bed, sans article devant bed.", "examples": [{"text": "He never goes to bed late.", "translation": "Il ne se couche jamais tard."}, {"text": "The children go to bed at eight.", "translation": "Les enfants se couchent à huit heures."}], "confusions": [{"word": "go to sleep", "note": "go to bed = aller se coucher ; go to sleep = s''endormir."}], "forms": {"thirdPerson": "goes to bed", "past": "went to bed", "pastParticiple": "gone to bed", "ing": "going to bed"}, "unitId": "en.v.go_to_bed"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.take_a_shower', 'en', 'take a shower', 'prendre une douche', 'Take a shower veut dire « prendre une douche ». En anglais britannique, on dit aussi have a shower.', '[{"text": "She always takes a shower in the morning.", "translation": "Elle prend toujours une douche le matin."}, {"text": "We take a shower after the gym.", "translation": "Nous prenons une douche après la salle de sport."}]'::jsonb, '/ˌteɪk ə ˈʃaʊə/', '{"id": "en.d.take_a_shower", "word": "take a shower", "translation": "prendre une douche", "otherTranslations": [], "partOfSpeech": "expression", "ipa": "/ˌteɪk ə ˈʃaʊə/", "explanation": "Take a shower veut dire « prendre une douche ». En anglais britannique, on dit aussi have a shower.", "examples": [{"text": "She always takes a shower in the morning.", "translation": "Elle prend toujours une douche le matin."}, {"text": "We take a shower after the gym.", "translation": "Nous prenons une douche après la salle de sport."}], "confusions": [{"word": "make", "note": "on ne « fait » pas une douche : on dit take a shower (ou have a shower), jamais make a shower."}], "forms": {"thirdPerson": "takes a shower", "past": "took a shower", "pastParticiple": "taken a shower", "ing": "taking a shower"}, "unitId": "en.v.take_a_shower"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.have_breakfast', 'en', 'have breakfast', 'prendre le petit-déjeuner', 'Have breakfast veut dire « prendre son petit-déjeuner ». On dit aussi eat breakfast. Pas d''article devant breakfast.', '[{"text": "Anna never has breakfast at home.", "translation": "Anna ne prend jamais son petit-déjeuner à la maison."}, {"text": "We usually have breakfast at seven.", "translation": "Nous prenons d''habitude le petit-déjeuner à sept heures."}]'::jsonb, '/ˌhæv ˈbrekfəst/', '{"id": "en.d.have_breakfast", "word": "have breakfast", "translation": "prendre le petit-déjeuner", "otherTranslations": [], "partOfSpeech": "expression", "ipa": "/ˌhæv ˈbrekfəst/", "explanation": "Have breakfast veut dire « prendre son petit-déjeuner ». On dit aussi eat breakfast. Pas d''article devant breakfast.", "examples": [{"text": "Anna never has breakfast at home.", "translation": "Anna ne prend jamais son petit-déjeuner à la maison."}, {"text": "We usually have breakfast at seven.", "translation": "Nous prenons d''habitude le petit-déjeuner à sept heures."}], "confusions": [], "forms": {"thirdPerson": "has breakfast", "past": "had breakfast", "pastParticiple": "had breakfast", "ing": "having breakfast"}, "unitId": "en.v.have_breakfast"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.now', 'en', 'now', 'maintenant', 'Now veut dire « maintenant » ou « en ce moment ». Il va souvent avec le présent continu.', '[{"text": "It is raining in London now.", "translation": "Il pleut à Londres en ce moment."}, {"text": "My sister is talking on the phone now.", "translation": "Ma sœur parle au téléphone maintenant."}]'::jsonb, '/naʊ/', '{"id": "en.d.now", "word": "now", "translation": "maintenant", "otherTranslations": ["en ce moment"], "partOfSpeech": "adverb", "ipa": "/naʊ/", "explanation": "Now veut dire « maintenant » ou « en ce moment ». Il va souvent avec le présent continu.", "examples": [{"text": "It is raining in London now.", "translation": "Il pleut à Londres en ce moment."}, {"text": "My sister is talking on the phone now.", "translation": "Ma sœur parle au téléphone maintenant."}], "confusions": [], "forms": {}, "unitId": "en.v.now"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.rain', 'en', 'rain', 'pleuvoir', 'Rain veut dire « pleuvoir ». Le sujet est toujours it : it rains, it is raining. Le nom rain veut dire « la pluie ».', '[{"text": "It is raining now.", "translation": "Il pleut en ce moment."}, {"text": "It often rains in London.", "translation": "Il pleut souvent à Londres."}]'::jsonb, '/reɪn/', '{"id": "en.d.rain", "word": "rain", "translation": "pleuvoir", "otherTranslations": ["la pluie (nom)"], "partOfSpeech": "verb", "ipa": "/reɪn/", "explanation": "Rain veut dire « pleuvoir ». Le sujet est toujours it : it rains, it is raining. Le nom rain veut dire « la pluie ».", "examples": [{"text": "It is raining now.", "translation": "Il pleut en ce moment."}, {"text": "It often rains in London.", "translation": "Il pleut souvent à Londres."}], "confusions": [], "forms": {"thirdPerson": "rains", "past": "rained", "pastParticiple": "rained", "ing": "raining"}, "unitId": "en.v.rain"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.wear', 'en', 'wear', 'porter (un vêtement)', 'Wear veut dire « porter » un vêtement, des lunettes ou un bijou sur soi.', '[{"text": "My sister is wearing a coat now.", "translation": "Ma sœur porte un manteau maintenant."}, {"text": "Tom never wears a hat.", "translation": "Tom ne porte jamais de chapeau."}]'::jsonb, '/weə/', '{"id": "en.d.wear", "word": "wear", "translation": "porter (un vêtement)", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/weə/", "explanation": "Wear veut dire « porter » un vêtement, des lunettes ou un bijou sur soi.", "examples": [{"text": "My sister is wearing a coat now.", "translation": "Ma sœur porte un manteau maintenant."}, {"text": "Tom never wears a hat.", "translation": "Tom ne porte jamais de chapeau."}], "confusions": [{"word": "carry", "note": "wear = porter un vêtement sur soi ; carry = porter un objet dans ses mains ou dans un sac."}], "forms": {"thirdPerson": "wears", "past": "wore", "pastParticiple": "worn", "ing": "wearing"}, "unitId": "en.v.wear"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.talk', 'en', 'talk', 'parler, discuter', 'Talk veut dire « parler, discuter » avec quelqu''un. On dit talk to quelqu''un ou talk on the phone.', '[{"text": "My friends are talking on the phone.", "translation": "Mes amis parlent au téléphone."}, {"text": "Anna talks to her mother every day.", "translation": "Anna parle à sa mère tous les jours."}]'::jsonb, '/tɔːk/', '{"id": "en.d.talk", "word": "talk", "translation": "parler, discuter", "otherTranslations": ["une conversation (nom)"], "partOfSpeech": "verb", "ipa": "/tɔːk/", "explanation": "Talk veut dire « parler, discuter » avec quelqu''un. On dit talk to quelqu''un ou talk on the phone.", "examples": [{"text": "My friends are talking on the phone.", "translation": "Mes amis parlent au téléphone."}, {"text": "Anna talks to her mother every day.", "translation": "Anna parle à sa mère tous les jours."}], "confusions": [{"word": "speak", "note": "talk = bavarder, discuter ; speak = parler (une langue, à quelqu''un) : speak French."}], "forms": {"thirdPerson": "talks", "past": "talked", "pastParticiple": "talked", "ing": "talking"}, "unitId": "en.v.talk"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.laugh', 'en', 'laugh', 'rire', 'Laugh veut dire « rire ». Le gh se prononce comme un f.', '[{"text": "Look! The children are laughing.", "translation": "Regarde ! Les enfants rient."}, {"text": "My father laughs a lot.", "translation": "Mon père rit beaucoup."}]'::jsonb, '/lɑːf/', '{"id": "en.d.laugh", "word": "laugh", "translation": "rire", "otherTranslations": ["un rire (nom)"], "partOfSpeech": "verb", "ipa": "/lɑːf/", "explanation": "Laugh veut dire « rire ». Le gh se prononce comme un f.", "examples": [{"text": "Look! The children are laughing.", "translation": "Regarde ! Les enfants rient."}, {"text": "My father laughs a lot.", "translation": "Mon père rit beaucoup."}], "confusions": [{"word": "smile", "note": "laugh = rire (avec du bruit) ; smile = sourire."}], "forms": {"thirdPerson": "laughs", "past": "laughed", "pastParticiple": "laughed", "ing": "laughing"}, "unitId": "en.v.laugh"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.call', 'en', 'call', 'appeler', 'Call veut dire « appeler » quelqu''un, au téléphone ou à voix haute. On dit call someone, sans préposition.', '[{"text": "Are you calling your mother now?", "translation": "Tu appelles ta mère en ce moment ?"}, {"text": "I call my friends in the evening.", "translation": "J''appelle mes amis le soir."}]'::jsonb, '/kɔːl/', '{"id": "en.d.call", "word": "call", "translation": "appeler", "otherTranslations": ["un appel (nom)", "téléphoner à"], "partOfSpeech": "verb", "ipa": "/kɔːl/", "explanation": "Call veut dire « appeler » quelqu''un, au téléphone ou à voix haute. On dit call someone, sans préposition.", "examples": [{"text": "Are you calling your mother now?", "translation": "Tu appelles ta mère en ce moment ?"}, {"text": "I call my friends in the evening.", "translation": "J''appelle mes amis le soir."}], "confusions": [], "forms": {"thirdPerson": "calls", "past": "called", "pastParticiple": "called", "ing": "calling"}, "unitId": "en.v.call"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.use', 'en', 'use', 'utiliser', 'Use veut dire « utiliser ». Le verbe se prononce /juːz/ ; le nom use (un usage) se prononce /juːs/. Avant -ing, on enlève le e : using.', '[{"text": "My sister is using her laptop now.", "translation": "Ma sœur utilise son ordinateur portable maintenant."}, {"text": "I use my phone every day.", "translation": "J''utilise mon téléphone tous les jours."}]'::jsonb, '/juːz/', '{"id": "en.d.use", "word": "use", "translation": "utiliser", "otherTranslations": ["un usage (nom)"], "partOfSpeech": "verb", "ipa": "/juːz/", "explanation": "Use veut dire « utiliser ». Le verbe se prononce /juːz/ ; le nom use (un usage) se prononce /juːs/. Avant -ing, on enlève le e : using.", "examples": [{"text": "My sister is using her laptop now.", "translation": "Ma sœur utilise son ordinateur portable maintenant."}, {"text": "I use my phone every day.", "translation": "J''utilise mon téléphone tous les jours."}], "confusions": [], "forms": {"thirdPerson": "uses", "past": "used", "pastParticiple": "used", "ing": "using"}, "unitId": "en.v.use"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.sing', 'en', 'sing', 'chanter', 'Sing veut dire « chanter » une chanson ou de la musique.', '[{"text": "Is she singing now?", "translation": "Est-ce qu''elle chante en ce moment ?"}, {"text": "My mother sings in the house.", "translation": "Ma mère chante dans la maison."}]'::jsonb, '/sɪŋ/', '{"id": "en.d.sing", "word": "sing", "translation": "chanter", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/sɪŋ/", "explanation": "Sing veut dire « chanter » une chanson ou de la musique.", "examples": [{"text": "Is she singing now?", "translation": "Est-ce qu''elle chante en ce moment ?"}, {"text": "My mother sings in the house.", "translation": "Ma mère chante dans la maison."}], "confusions": [], "forms": {"thirdPerson": "sings", "past": "sang", "pastParticiple": "sung", "ing": "singing"}, "unitId": "en.v.sing"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.dance', 'en', 'dance', 'danser', 'Dance veut dire « danser ». Avant -ing, on enlève le e : dancing.', '[{"text": "Are your friends dancing now?", "translation": "Tes amis dansent en ce moment ?"}, {"text": "We often dance at the weekend.", "translation": "Nous dansons souvent le week-end."}]'::jsonb, '/dɑːns/', '{"id": "en.d.dance", "word": "dance", "translation": "danser", "otherTranslations": ["une danse (nom)"], "partOfSpeech": "verb", "ipa": "/dɑːns/", "explanation": "Dance veut dire « danser ». Avant -ing, on enlève le e : dancing.", "examples": [{"text": "Are your friends dancing now?", "translation": "Tes amis dansent en ce moment ?"}, {"text": "We often dance at the weekend.", "translation": "Nous dansons souvent le week-end."}], "confusions": [], "forms": {"thirdPerson": "dances", "past": "danced", "pastParticiple": "danced", "ing": "dancing"}, "unitId": "en.v.dance"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.laptop', 'en', 'laptop', 'ordinateur portable', 'Laptop désigne un ordinateur portable. Le mot plus général computer désigne tout ordinateur.', '[{"text": "Tom isn''t using his laptop at the moment.", "translation": "Tom n''utilise pas son ordinateur portable en ce moment."}, {"text": "I carry my laptop in my bag.", "translation": "Je porte mon ordinateur portable dans mon sac."}]'::jsonb, '/ˈlæptɒp/', '{"id": "en.d.laptop", "word": "laptop", "translation": "ordinateur portable", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈlæptɒp/", "explanation": "Laptop désigne un ordinateur portable. Le mot plus général computer désigne tout ordinateur.", "examples": [{"text": "Tom isn''t using his laptop at the moment.", "translation": "Tom n''utilise pas son ordinateur portable en ce moment."}, {"text": "I carry my laptop in my bag.", "translation": "Je porte mon ordinateur portable dans mon sac."}], "confusions": [{"word": "computer", "note": "computer = ordinateur en général ; laptop = ordinateur portable."}], "forms": {"plural": "laptops"}, "unitId": "en.v.laptop"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.today', 'en', 'today', 'aujourd''hui', 'Today veut dire « aujourd''hui ». Avec le présent continu, il parle de ce qui se passe aujourd''hui.', '[{"text": "My colleague is working at home today.", "translation": "Mon collègue travaille à la maison aujourd''hui."}, {"text": "He doesn''t work today.", "translation": "Il ne travaille pas aujourd''hui."}]'::jsonb, '/təˈdeɪ/', '{"id": "en.d.today", "word": "today", "translation": "aujourd''hui", "otherTranslations": [], "partOfSpeech": "adverb", "ipa": "/təˈdeɪ/", "explanation": "Today veut dire « aujourd''hui ». Avec le présent continu, il parle de ce qui se passe aujourd''hui.", "examples": [{"text": "My colleague is working at home today.", "translation": "Mon collègue travaille à la maison aujourd''hui."}, {"text": "He doesn''t work today.", "translation": "Il ne travaille pas aujourd''hui."}], "confusions": [], "forms": {}, "unitId": "en.v.today"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.tonight', 'en', 'tonight', 'ce soir', 'Tonight veut dire « ce soir » (ou « cette nuit »). Avec le présent continu, il parle d''un projet prévu : What are you doing tonight ?', '[{"text": "What are you doing tonight?", "translation": "Qu''est-ce que tu fais ce soir ?"}, {"text": "We are cooking dinner for our friends tonight.", "translation": "Nous préparons le dîner pour nos amis ce soir."}]'::jsonb, '/təˈnaɪt/', '{"id": "en.d.tonight", "word": "tonight", "translation": "ce soir", "otherTranslations": ["cette nuit"], "partOfSpeech": "adverb", "ipa": "/təˈnaɪt/", "explanation": "Tonight veut dire « ce soir » (ou « cette nuit »). Avec le présent continu, il parle d''un projet prévu : What are you doing tonight ?", "examples": [{"text": "What are you doing tonight?", "translation": "Qu''est-ce que tu fais ce soir ?"}, {"text": "We are cooking dinner for our friends tonight.", "translation": "Nous préparons le dîner pour nos amis ce soir."}], "confusions": [], "forms": {}, "unitId": "en.v.tonight"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.at_the_moment', 'en', 'at the moment', 'en ce moment', 'At the moment veut dire « en ce moment ». Il va avec le présent continu et se place en début ou en fin de phrase.', '[{"text": "At the moment, my colleague is talking on the phone.", "translation": "En ce moment, mon collègue parle au téléphone."}, {"text": "I''m not working at the moment.", "translation": "Je ne travaille pas en ce moment."}]'::jsonb, '/ət ðə ˈməʊmənt/', '{"id": "en.d.at_the_moment", "word": "at the moment", "translation": "en ce moment", "otherTranslations": ["actuellement", "à l''instant"], "partOfSpeech": "expression", "ipa": "/ət ðə ˈməʊmənt/", "explanation": "At the moment veut dire « en ce moment ». Il va avec le présent continu et se place en début ou en fin de phrase.", "examples": [{"text": "At the moment, my colleague is talking on the phone.", "translation": "En ce moment, mon collègue parle au téléphone."}, {"text": "I''m not working at the moment.", "translation": "Je ne travaille pas en ce moment."}], "confusions": [], "forms": {}, "unitId": "en.v.at_the_moment"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.office', 'en', 'office', 'bureau (lieu de travail)', 'Office désigne le lieu où l''on travaille avec des collègues. On dit at the office ou in the office.', '[{"text": "My colleague works at the office every day.", "translation": "Mon collègue travaille au bureau tous les jours."}, {"text": "I like my office.", "translation": "J''aime mon bureau."}]'::jsonb, '/ˈɒfɪs/', '{"id": "en.d.office", "word": "office", "translation": "bureau (lieu de travail)", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈɒfɪs/", "explanation": "Office désigne le lieu où l''on travaille avec des collègues. On dit at the office ou in the office.", "examples": [{"text": "My colleague works at the office every day.", "translation": "Mon collègue travaille au bureau tous les jours."}, {"text": "I like my office.", "translation": "J''aime mon bureau."}], "confusions": [{"word": "desk", "note": "office = le lieu de travail ; desk = le meuble sur lequel on travaille. En français, « bureau » veut dire les deux."}], "forms": {"plural": "offices"}, "unitId": "en.v.office"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.colleague', 'en', 'colleague', 'collègue', 'Colleague désigne une personne avec qui on travaille. Il s''emploie pour un homme comme pour une femme.', '[{"text": "Do you know my colleague?", "translation": "Tu connais mon collègue ?"}, {"text": "My colleague drinks coffee every morning.", "translation": "Ma collègue boit du café tous les matins."}]'::jsonb, '/ˈkɒliːɡ/', '{"id": "en.d.colleague", "word": "colleague", "translation": "collègue", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈkɒliːɡ/", "explanation": "Colleague désigne une personne avec qui on travaille. Il s''emploie pour un homme comme pour une femme.", "examples": [{"text": "Do you know my colleague?", "translation": "Tu connais mon collègue ?"}, {"text": "My colleague drinks coffee every morning.", "translation": "Ma collègue boit du café tous les matins."}], "confusions": [], "forms": {"plural": "colleagues"}, "unitId": "en.v.colleague"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.does', 'en', 'does', '(auxiliaire de do à la 3e personne)', 'Does est la forme de do avec he, she, it. On l''utilise pour poser une question (Does she work ?) et, avec not, pour nier (She doesn''t work). Après does, le verbe reste à sa forme de base. Does est aussi le verbe do : he does his homework.', '[{"text": "Does your sister eat lunch at school?", "translation": "Ta sœur déjeune à l''école ?"}, {"text": "He does his homework at home.", "translation": "Il fait ses devoirs à la maison."}]'::jsonb, '/dʌz/', '{"id": "en.d.does", "word": "does", "translation": "(auxiliaire de do à la 3e personne)", "otherTranslations": ["fait (verbe do)"], "partOfSpeech": "auxiliary", "ipa": "/dʌz/", "explanation": "Does est la forme de do avec he, she, it. On l''utilise pour poser une question (Does she work ?) et, avec not, pour nier (She doesn''t work). Après does, le verbe reste à sa forme de base. Does est aussi le verbe do : he does his homework.", "examples": [{"text": "Does your sister eat lunch at school?", "translation": "Ta sœur déjeune à l''école ?"}, {"text": "He does his homework at home.", "translation": "Il fait ses devoirs à la maison."}], "confusions": [{"word": "do", "note": "do s''emploie avec I, you, we, they ; does avec he, she, it."}], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.dont', 'en', 'don''t', 'ne… pas (do not)', 'Don''t (do not) sert à faire la négation au présent simple avec I, you, we, they. Il est suivi du verbe de base : I don''t eat meat.', '[{"text": "I don''t drink milk.", "translation": "Je ne bois pas de lait."}, {"text": "My parents don''t live in London.", "translation": "Mes parents n''habitent pas à Londres."}]'::jsonb, '/dəʊnt/', '{"id": "en.d.dont", "word": "don''t", "translation": "ne… pas (do not)", "otherTranslations": [], "partOfSpeech": "auxiliary", "ipa": "/dəʊnt/", "explanation": "Don''t (do not) sert à faire la négation au présent simple avec I, you, we, they. Il est suivi du verbe de base : I don''t eat meat.", "examples": [{"text": "I don''t drink milk.", "translation": "Je ne bois pas de lait."}, {"text": "My parents don''t live in London.", "translation": "Mes parents n''habitent pas à Londres."}], "confusions": [{"word": "doesn''t", "note": "doesn''t s''emploie avec he, she, it ; don''t avec I, you, we, they."}], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.doesnt', 'en', 'doesn''t', 'ne… pas (does not)', 'Doesn''t (does not) sert à faire la négation au présent simple avec he, she, it. Le verbe qui suit reste à sa forme de base : she doesn''t eat meat.', '[{"text": "She doesn''t eat fish.", "translation": "Elle ne mange pas de poisson."}, {"text": "Tom doesn''t work today.", "translation": "Tom ne travaille pas aujourd''hui."}]'::jsonb, '/ˈdʌznt/', '{"id": "en.d.doesnt", "word": "doesn''t", "translation": "ne… pas (does not)", "otherTranslations": [], "partOfSpeech": "auxiliary", "ipa": "/ˈdʌznt/", "explanation": "Doesn''t (does not) sert à faire la négation au présent simple avec he, she, it. Le verbe qui suit reste à sa forme de base : she doesn''t eat meat.", "examples": [{"text": "She doesn''t eat fish.", "translation": "Elle ne mange pas de poisson."}, {"text": "Tom doesn''t work today.", "translation": "Tom ne travaille pas aujourd''hui."}], "confusions": [{"word": "don''t", "note": "don''t s''emploie avec I, you, we, they ; doesn''t avec he, she, it."}], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.always', 'en', 'always', 'toujours', 'Always veut dire « toujours », 100 % du temps. Il se place avant le verbe, mais après be : I always get up early, she is always late.', '[{"text": "I always go to the gym in the morning.", "translation": "Je vais toujours à la salle de sport le matin."}, {"text": "Tom is always happy at the weekend.", "translation": "Tom est toujours content le week-end."}]'::jsonb, '/ˈɔːlweɪz/', '{"id": "en.d.always", "word": "always", "translation": "toujours", "otherTranslations": [], "partOfSpeech": "adverb", "ipa": "/ˈɔːlweɪz/", "explanation": "Always veut dire « toujours », 100 % du temps. Il se place avant le verbe, mais après be : I always get up early, she is always late.", "examples": [{"text": "I always go to the gym in the morning.", "translation": "Je vais toujours à la salle de sport le matin."}, {"text": "Tom is always happy at the weekend.", "translation": "Tom est toujours content le week-end."}], "confusions": [], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.usually', 'en', 'usually', 'd''habitude, habituellement', 'Usually veut dire « d''habitude » : presque toujours. Il se place avant le verbe, mais après be.', '[{"text": "Anna usually goes to the gym early.", "translation": "Anna va d''habitude à la salle de sport tôt."}, {"text": "We usually have breakfast at seven.", "translation": "Nous prenons d''habitude le petit-déjeuner à sept heures."}]'::jsonb, '/ˈjuːʒuəli/', '{"id": "en.d.usually", "word": "usually", "translation": "d''habitude, habituellement", "otherTranslations": ["en général"], "partOfSpeech": "adverb", "ipa": "/ˈjuːʒuəli/", "explanation": "Usually veut dire « d''habitude » : presque toujours. Il se place avant le verbe, mais après be.", "examples": [{"text": "Anna usually goes to the gym early.", "translation": "Anna va d''habitude à la salle de sport tôt."}, {"text": "We usually have breakfast at seven.", "translation": "Nous prenons d''habitude le petit-déjeuner à sept heures."}], "confusions": [], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.often', 'en', 'often', 'souvent', 'Often veut dire « souvent ». Il se place avant le verbe, mais après be : we often listen to music, she is often tired.', '[{"text": "We often eat dinner early.", "translation": "Nous dînons souvent tôt."}, {"text": "My father is often busy.", "translation": "Mon père est souvent occupé."}]'::jsonb, '/ˈɒfn/', '{"id": "en.d.often", "word": "often", "translation": "souvent", "otherTranslations": [], "partOfSpeech": "adverb", "ipa": "/ˈɒfn/", "explanation": "Often veut dire « souvent ». Il se place avant le verbe, mais après be : we often listen to music, she is often tired.", "examples": [{"text": "We often eat dinner early.", "translation": "Nous dînons souvent tôt."}, {"text": "My father is often busy.", "translation": "Mon père est souvent occupé."}], "confusions": [], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.sometimes', 'en', 'sometimes', 'parfois, quelquefois', 'Sometimes veut dire « parfois ». Il se place avant le verbe, après be, ou au début de la phrase : Sometimes I work at home.', '[{"text": "My brother sometimes listens to music.", "translation": "Mon frère écoute parfois de la musique."}, {"text": "Sometimes I eat lunch at the office.", "translation": "Parfois, je déjeune au bureau."}]'::jsonb, '/ˈsʌmtaɪmz/', '{"id": "en.d.sometimes", "word": "sometimes", "translation": "parfois, quelquefois", "otherTranslations": [], "partOfSpeech": "adverb", "ipa": "/ˈsʌmtaɪmz/", "explanation": "Sometimes veut dire « parfois ». Il se place avant le verbe, après be, ou au début de la phrase : Sometimes I work at home.", "examples": [{"text": "My brother sometimes listens to music.", "translation": "Mon frère écoute parfois de la musique."}, {"text": "Sometimes I eat lunch at the office.", "translation": "Parfois, je déjeune au bureau."}], "confusions": [{"word": "sometime", "note": "sometimes = parfois (adverbe de fréquence) ; sometime = un jour, à un moment (sans précision)."}], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.rarely', 'en', 'rarely', 'rarement', 'Rarely veut dire « rarement ». Il se place avant le verbe, mais après be. Il est déjà négatif : on ne dit pas « don''t rarely ».', '[{"text": "We rarely eat meat.", "translation": "Nous mangeons rarement de la viande."}, {"text": "She is rarely late.", "translation": "Elle est rarement en retard."}]'::jsonb, '/ˈreəli/', '{"id": "en.d.rarely", "word": "rarely", "translation": "rarement", "otherTranslations": [], "partOfSpeech": "adverb", "ipa": "/ˈreəli/", "explanation": "Rarely veut dire « rarement ». Il se place avant le verbe, mais après be. Il est déjà négatif : on ne dit pas « don''t rarely ».", "examples": [{"text": "We rarely eat meat.", "translation": "Nous mangeons rarement de la viande."}, {"text": "She is rarely late.", "translation": "Elle est rarement en retard."}], "confusions": [], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.never', 'en', 'never', 'jamais', 'Never veut dire « jamais ». Il est déjà négatif : on n''ajoute pas don''t ni doesn''t. Il se place avant le verbe, mais après be : Tom never watches TV, she is never late.', '[{"text": "My father never watches TV during the day.", "translation": "Mon père ne regarde jamais la télé pendant la journée."}, {"text": "Anna is never late for school.", "translation": "Anna n''est jamais en retard à l''école."}]'::jsonb, '/ˈnevə/', '{"id": "en.d.never", "word": "never", "translation": "jamais", "otherTranslations": [], "partOfSpeech": "adverb", "ipa": "/ˈnevə/", "explanation": "Never veut dire « jamais ». Il est déjà négatif : on n''ajoute pas don''t ni doesn''t. Il se place avant le verbe, mais après be : Tom never watches TV, she is never late.", "examples": [{"text": "My father never watches TV during the day.", "translation": "Mon père ne regarde jamais la télé pendant la journée."}, {"text": "Anna is never late for school.", "translation": "Anna n''est jamais en retard à l''école."}], "confusions": [], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.yesterday', 'en', 'yesterday', 'hier', 'Yesterday désigne le jour d''avant aujourd''hui et appelle un verbe au passé.', '[{"text": "I was at home yesterday morning.", "translation": "J''étais à la maison hier matin."}, {"text": "Anna called me yesterday.", "translation": "Anna m''a appelé hier."}]'::jsonb, '/ˈjestədeɪ/', '{"id": "en.d.yesterday", "word": "yesterday", "translation": "hier", "partOfSpeech": "adverb", "ipa": "/ˈjestədeɪ/", "explanation": "Yesterday désigne le jour d''avant aujourd''hui et appelle un verbe au passé.", "examples": [{"text": "I was at home yesterday morning.", "translation": "J''étais à la maison hier matin."}, {"text": "Anna called me yesterday.", "translation": "Anna m''a appelé hier."}], "confusions": [{"word": "last night", "note": "« Hier soir » se dit last night ou yesterday evening, et non yesterday night."}], "unitId": "en.v.yesterday"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.last', 'en', 'last', 'dernier', 'Last se place devant un nom de temps (last week, last night) pour parler de la période juste avant celle-ci.', '[{"text": "We were in Paris last week.", "translation": "Nous étions à Paris la semaine dernière."}, {"text": "I slept late last weekend.", "translation": "J''ai dormi tard le week-end dernier."}]'::jsonb, '/lɑːst/', '{"id": "en.d.last", "word": "last", "translation": "dernier", "otherTranslations": ["la dernière, le dernier (final)"], "partOfSpeech": "adjective", "ipa": "/lɑːst/", "explanation": "Last se place devant un nom de temps (last week, last night) pour parler de la période juste avant celle-ci.", "examples": [{"text": "We were in Paris last week.", "translation": "Nous étions à Paris la semaine dernière."}, {"text": "I slept late last weekend.", "translation": "J''ai dormi tard le week-end dernier."}], "confusions": [{"word": "ago", "note": "last se place avant le nom (last week) ; ago se place après la durée (two days ago)."}], "unitId": "en.v.last"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.ago', 'en', 'ago', 'il y a (dans le passé)', 'Ago se place après une durée pour dire combien de temps s''est écoulé depuis un événement passé.', '[{"text": "My parents arrived two days ago.", "translation": "Mes parents sont arrivés il y a deux jours."}, {"text": "I met Tom three weeks ago.", "translation": "J''ai rencontré Tom il y a trois semaines."}]'::jsonb, '/əˈɡəʊ/', '{"id": "en.d.ago", "word": "ago", "translation": "il y a (dans le passé)", "partOfSpeech": "adverb", "ipa": "/əˈɡəʊ/", "explanation": "Ago se place après une durée pour dire combien de temps s''est écoulé depuis un événement passé.", "examples": [{"text": "My parents arrived two days ago.", "translation": "Mes parents sont arrivés il y a deux jours."}, {"text": "I met Tom three weeks ago.", "translation": "J''ai rencontré Tom il y a trois semaines."}], "confusions": [{"word": "before", "note": "before veut dire « avant » (before the party) ; « il y a deux jours » se dit two days ago."}], "unitId": "en.v.ago"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.born', 'en', 'born', 'né', 'Born s''emploie dans to be born, et la naissance se dit au passé : I was born in Paris.', '[{"text": "I was born in London.", "translation": "Je suis né à Londres."}, {"text": "My son was born in Paris.", "translation": "Mon fils est né à Paris."}]'::jsonb, '/bɔːn/', '{"id": "en.d.born", "word": "born", "translation": "né", "otherTranslations": ["née"], "partOfSpeech": "adjective", "ipa": "/bɔːn/", "explanation": "Born s''emploie dans to be born, et la naissance se dit au passé : I was born in Paris.", "examples": [{"text": "I was born in London.", "translation": "Je suis né à Londres."}, {"text": "My son was born in Paris.", "translation": "Mon fils est né à Paris."}], "confusions": [], "unitId": "en.v.born"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.week', 'en', 'week', 'semaine', 'Une week est une période de sept jours.', '[{"text": "I work five days a week.", "translation": "Je travaille cinq jours par semaine."}, {"text": "Tom visited his parents last week.", "translation": "Tom a rendu visite à ses parents la semaine dernière."}]'::jsonb, '/wiːk/', '{"id": "en.d.week", "word": "week", "translation": "semaine", "partOfSpeech": "noun", "ipa": "/wiːk/", "explanation": "Une week est une période de sept jours.", "examples": [{"text": "I work five days a week.", "translation": "Je travaille cinq jours par semaine."}, {"text": "Tom visited his parents last week.", "translation": "Tom a rendu visite à ses parents la semaine dernière."}], "confusions": [{"word": "weak", "note": "weak se prononce pareil /wiːk/ mais veut dire « faible »."}], "forms": {"plural": "weeks"}, "unitId": "en.v.week"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.walk', 'en', 'walk', 'marcher', 'Walk veut dire aller quelque part à pied ; le -ed se prononce /t/ : walked /wɔːkt/.', '[{"text": "I walked to the office yesterday.", "translation": "Je suis allé au bureau à pied hier."}, {"text": "She walks to school every day.", "translation": "Elle va à l''école à pied tous les jours."}]'::jsonb, '/wɔːk/', '{"id": "en.d.walk", "word": "walk", "translation": "marcher", "otherTranslations": ["une promenade (nom)"], "partOfSpeech": "verb", "ipa": "/wɔːk/", "explanation": "Walk veut dire aller quelque part à pied ; le -ed se prononce /t/ : walked /wɔːkt/.", "examples": [{"text": "I walked to the office yesterday.", "translation": "Je suis allé au bureau à pied hier."}, {"text": "She walks to school every day.", "translation": "Elle va à l''école à pied tous les jours."}], "confusions": [], "forms": {"thirdPerson": "walks", "past": "walked", "pastParticiple": "walked", "ing": "walking"}, "unitId": "en.v.walk"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.visit', 'en', 'visit', 'visiter, rendre visite', 'Visit s''utilise pour aller voir une personne ou un lieu ; le -ed se prononce avec une syllabe en plus : visited /ˈvɪzɪtɪd/.', '[{"text": "Anna visited her sister last week.", "translation": "Anna a rendu visite à sa sœur la semaine dernière."}, {"text": "We visited London two days ago.", "translation": "Nous avons visité Londres il y a deux jours."}]'::jsonb, '/ˈvɪzɪt/', '{"id": "en.d.visit", "word": "visit", "translation": "visiter, rendre visite", "otherTranslations": ["une visite (nom)"], "partOfSpeech": "verb", "ipa": "/ˈvɪzɪt/", "explanation": "Visit s''utilise pour aller voir une personne ou un lieu ; le -ed se prononce avec une syllabe en plus : visited /ˈvɪzɪtɪd/.", "examples": [{"text": "Anna visited her sister last week.", "translation": "Anna a rendu visite à sa sœur la semaine dernière."}, {"text": "We visited London two days ago.", "translation": "Nous avons visité Londres il y a deux jours."}], "confusions": [], "forms": {"thirdPerson": "visits", "past": "visited", "pastParticiple": "visited", "ing": "visiting"}, "unitId": "en.v.visit"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.stay', 'en', 'stay', 'rester, séjourner', 'Stay veut dire rester quelque part, ou y passer quelque temps ; son passé garde le y : stayed /steɪd/.', '[{"text": "We stayed at home yesterday.", "translation": "Nous sommes restés à la maison hier."}, {"text": "He stayed with his parents for two days.", "translation": "Il a séjourné chez ses parents pendant deux jours."}]'::jsonb, '/steɪ/', '{"id": "en.d.stay", "word": "stay", "translation": "rester, séjourner", "partOfSpeech": "verb", "ipa": "/steɪ/", "explanation": "Stay veut dire rester quelque part, ou y passer quelque temps ; son passé garde le y : stayed /steɪd/.", "examples": [{"text": "We stayed at home yesterday.", "translation": "Nous sommes restés à la maison hier."}, {"text": "He stayed with his parents for two days.", "translation": "Il a séjourné chez ses parents pendant deux jours."}], "confusions": [], "forms": {"thirdPerson": "stays", "past": "stayed", "pastParticiple": "stayed", "ing": "staying"}, "unitId": "en.v.stay"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.start', 'en', 'start', 'commencer', 'Start veut dire commencer ; comme il finit par t, son passé a une syllabe en plus : started /ˈstɑːtɪd/.', '[{"text": "My day started early yesterday.", "translation": "Ma journée a commencé tôt hier."}, {"text": "The film starts at eight.", "translation": "Le film commence à huit heures."}]'::jsonb, '/stɑːt/', '{"id": "en.d.start", "word": "start", "translation": "commencer", "otherTranslations": ["démarrer", "le début (nom)"], "partOfSpeech": "verb", "ipa": "/stɑːt/", "explanation": "Start veut dire commencer ; comme il finit par t, son passé a une syllabe en plus : started /ˈstɑːtɪd/.", "examples": [{"text": "My day started early yesterday.", "translation": "Ma journée a commencé tôt hier."}, {"text": "The film starts at eight.", "translation": "Le film commence à huit heures."}], "confusions": [{"word": "begin", "note": "start et begin veulent dire « commencer » ; start est régulier (started), begin est irrégulier (began)."}], "forms": {"thirdPerson": "starts", "past": "started", "pastParticiple": "started", "ing": "starting"}, "unitId": "en.v.start"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.travel', 'en', 'travel', 'voyager', 'Travel veut dire aller d''un pays ou d''une ville à un autre ; au passé, on double le l en anglais britannique : travelled (traveled en américain).', '[{"text": "My parents travelled to London two days ago.", "translation": "Mes parents ont voyagé à Londres il y a deux jours."}, {"text": "I travel to work by car.", "translation": "Je me rends au travail en voiture."}]'::jsonb, '/ˈtrævəl/', '{"id": "en.d.travel", "word": "travel", "translation": "voyager", "partOfSpeech": "verb", "ipa": "/ˈtrævəl/", "explanation": "Travel veut dire aller d''un pays ou d''une ville à un autre ; au passé, on double le l en anglais britannique : travelled (traveled en américain).", "examples": [{"text": "My parents travelled to London two days ago.", "translation": "Mes parents ont voyagé à Londres il y a deux jours."}, {"text": "I travel to work by car.", "translation": "Je me rends au travail en voiture."}], "confusions": [{"word": "trip", "note": "travel est un verbe (voyager) ; trip est un nom (un voyage, une excursion)."}], "forms": {"thirdPerson": "travels", "past": "travelled", "pastParticiple": "travelled", "ing": "travelling"}, "unitId": "en.v.travel"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.arrive', 'en', 'arrive', 'arriver', 'Arrive veut dire atteindre un lieu ; il finit par e, donc on ajoute seulement -d : arrived /əˈraɪvd/.', '[{"text": "My brother arrived at the office at eight.", "translation": "Mon frère est arrivé au bureau à huit heures."}, {"text": "We arrived in Paris at night.", "translation": "Nous sommes arrivés à Paris la nuit."}]'::jsonb, '/əˈraɪv/', '{"id": "en.d.arrive", "word": "arrive", "translation": "arriver", "partOfSpeech": "verb", "ipa": "/əˈraɪv/", "explanation": "Arrive veut dire atteindre un lieu ; il finit par e, donc on ajoute seulement -d : arrived /əˈraɪvd/.", "examples": [{"text": "My brother arrived at the office at eight.", "translation": "Mon frère est arrivé au bureau à huit heures."}, {"text": "We arrived in Paris at night.", "translation": "Nous sommes arrivés à Paris la nuit."}], "confusions": [{"word": "come", "note": "arrive insiste sur le moment où l''on atteint un lieu, alors que come insiste sur le fait de venir."}], "forms": {"thirdPerson": "arrives", "past": "arrived", "pastParticiple": "arrived", "ing": "arriving"}, "unitId": "en.v.arrive"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.decide', 'en', 'decide', 'décider', 'Decide veut dire prendre une décision ; il est souvent suivi de to + verbe, et son passé a une syllabe en plus : decided /dɪˈsaɪdɪd/.', '[{"text": "We decided to stay at home.", "translation": "Nous avons décidé de rester à la maison."}, {"text": "Anna decided to call her mother.", "translation": "Anna a décidé d''appeler sa mère."}]'::jsonb, '/dɪˈsaɪd/', '{"id": "en.d.decide", "word": "decide", "translation": "décider", "partOfSpeech": "verb", "ipa": "/dɪˈsaɪd/", "explanation": "Decide veut dire prendre une décision ; il est souvent suivi de to + verbe, et son passé a une syllabe en plus : decided /dɪˈsaɪdɪd/.", "examples": [{"text": "We decided to stay at home.", "translation": "Nous avons décidé de rester à la maison."}, {"text": "Anna decided to call her mother.", "translation": "Anna a décidé d''appeler sa mère."}], "confusions": [], "forms": {"thirdPerson": "decides", "past": "decided", "pastParticiple": "decided", "ing": "deciding"}, "unitId": "en.v.decide"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.ask', 'en', 'ask', 'demander', 'Ask veut dire poser une question ou demander quelque chose à quelqu''un ; le -ed se prononce /t/ : asked /ɑːskt/.', '[{"text": "He asked his teacher for help.", "translation": "Il a demandé de l''aide à son professeur."}, {"text": "Sam asked me for a coffee.", "translation": "Sam m''a demandé un café."}]'::jsonb, '/ɑːsk/', '{"id": "en.d.ask", "word": "ask", "translation": "demander", "partOfSpeech": "verb", "ipa": "/ɑːsk/", "explanation": "Ask veut dire poser une question ou demander quelque chose à quelqu''un ; le -ed se prononce /t/ : asked /ɑːskt/.", "examples": [{"text": "He asked his teacher for help.", "translation": "Il a demandé de l''aide à son professeur."}, {"text": "Sam asked me for a coffee.", "translation": "Sam m''a demandé un café."}], "confusions": [{"word": "answer", "note": "ask = demander, poser une question ; answer = répondre."}], "forms": {"thirdPerson": "asks", "past": "asked", "pastParticiple": "asked", "ing": "asking"}, "unitId": "en.v.ask"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.answer', 'en', 'answer', 'répondre', 'Answer veut dire répondre à une question, à un appel ou à un message ; le w ne se prononce pas.', '[{"text": "She answered the phone.", "translation": "Elle a répondu au téléphone."}, {"text": "I answered Tom''s message.", "translation": "J''ai répondu au message de Tom."}]'::jsonb, '/ˈɑːnsə/', '{"id": "en.d.answer", "word": "answer", "translation": "répondre", "otherTranslations": ["une réponse (nom)"], "partOfSpeech": "verb", "ipa": "/ˈɑːnsə/", "explanation": "Answer veut dire répondre à une question, à un appel ou à un message ; le w ne se prononce pas.", "examples": [{"text": "She answered the phone.", "translation": "Elle a répondu au téléphone."}, {"text": "I answered Tom''s message.", "translation": "J''ai répondu au message de Tom."}], "confusions": [{"word": "ask", "note": "answer = répondre ; ask = demander. On dit answer the phone, sans to."}], "forms": {"thirdPerson": "answers", "past": "answered", "pastParticiple": "answered", "ing": "answering"}, "unitId": "en.v.answer"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.clean', 'en', 'clean', 'nettoyer', 'Clean veut dire rendre propre ; c''est aussi un adjectif (propre) et son passé se prononce /kliːnd/.', '[{"text": "Sam cleaned the windows last weekend.", "translation": "Sam a nettoyé les fenêtres le week-end dernier."}, {"text": "I clean the house every weekend.", "translation": "Je nettoie la maison tous les week-ends."}]'::jsonb, '/kliːn/', '{"id": "en.d.clean", "word": "clean", "translation": "nettoyer", "otherTranslations": ["propre (adjectif)"], "partOfSpeech": "verb", "ipa": "/kliːn/", "explanation": "Clean veut dire rendre propre ; c''est aussi un adjectif (propre) et son passé se prononce /kliːnd/.", "examples": [{"text": "Sam cleaned the windows last weekend.", "translation": "Sam a nettoyé les fenêtres le week-end dernier."}, {"text": "I clean the house every weekend.", "translation": "Je nettoie la maison tous les week-ends."}], "confusions": [], "forms": {"thirdPerson": "cleans", "past": "cleaned", "pastParticiple": "cleaned", "ing": "cleaning"}, "unitId": "en.v.clean"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.see', 'en', 'see', 'voir', 'See veut dire voir quelqu''un ou quelque chose avec les yeux ; son passé est irrégulier : saw /sɔː/.', '[{"text": "I saw Tom at the gym last week.", "translation": "J''ai vu Tom à la salle de sport la semaine dernière."}, {"text": "Can you see the beach?", "translation": "Est-ce que tu vois la plage ?"}]'::jsonb, '/siː/', '{"id": "en.d.see", "word": "see", "translation": "voir", "partOfSpeech": "verb", "ipa": "/siː/", "explanation": "See veut dire voir quelqu''un ou quelque chose avec les yeux ; son passé est irrégulier : saw /sɔː/.", "examples": [{"text": "I saw Tom at the gym last week.", "translation": "J''ai vu Tom à la salle de sport la semaine dernière."}, {"text": "Can you see the beach?", "translation": "Est-ce que tu vois la plage ?"}], "confusions": [{"word": "look", "note": "look = regarder (on dirige son regard) ; see = voir (on perçoit)."}, {"word": "watch", "note": "watch = regarder pendant un moment (un film, un match)."}], "forms": {"thirdPerson": "sees", "past": "saw", "pastParticiple": "seen", "ing": "seeing"}, "unitId": "en.v.see"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.say', 'en', 'say', 'dire', 'Say s''utilise avec ce qu''on dit (say hello) ; son passé said se prononce /sed/.', '[{"text": "She said goodbye to her friends.", "translation": "Elle a dit au revoir à ses amis."}, {"text": "Tom said hello to the teacher.", "translation": "Tom a dit bonjour au professeur."}]'::jsonb, '/seɪ/', '{"id": "en.d.say", "word": "say", "translation": "dire", "partOfSpeech": "verb", "ipa": "/seɪ/", "explanation": "Say s''utilise avec ce qu''on dit (say hello) ; son passé said se prononce /sed/.", "examples": [{"text": "She said goodbye to her friends.", "translation": "Elle a dit au revoir à ses amis."}, {"text": "Tom said hello to the teacher.", "translation": "Tom a dit bonjour au professeur."}], "confusions": [{"word": "tell", "note": "say + ce qu''on dit (said hello) ; tell + la personne (told me his name)."}], "forms": {"thirdPerson": "says", "past": "said", "pastParticiple": "said", "ing": "saying"}, "unitId": "en.v.say"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.tell', 'en', 'tell', 'dire (à quelqu''un), raconter', 'Tell s''utilise avec la personne à qui l''on parle (tell me) ou pour raconter (tell a story) ; son passé est told.', '[{"text": "He told me his name.", "translation": "Il m''a dit son nom."}, {"text": "My mother told us a story.", "translation": "Ma mère nous a raconté une histoire."}]'::jsonb, '/tel/', '{"id": "en.d.tell", "word": "tell", "translation": "dire (à quelqu''un), raconter", "partOfSpeech": "verb", "ipa": "/tel/", "explanation": "Tell s''utilise avec la personne à qui l''on parle (tell me) ou pour raconter (tell a story) ; son passé est told.", "examples": [{"text": "He told me his name.", "translation": "Il m''a dit son nom."}, {"text": "My mother told us a story.", "translation": "Ma mère nous a raconté une histoire."}], "confusions": [{"word": "say", "note": "tell + personne (told me) ; say + ce qu''on dit (said hello). On dit said to me, pas said me."}], "forms": {"thirdPerson": "tells", "past": "told", "pastParticiple": "told", "ing": "telling"}, "unitId": "en.v.tell"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.find', 'en', 'find', 'trouver', 'Find veut dire trouver quelque chose qu''on cherche ou qu''on découvre ; son passé est irrégulier : found /faʊnd/.', '[{"text": "My father found my keys yesterday.", "translation": "Mon père a trouvé mes clés hier."}, {"text": "I can''t find my phone.", "translation": "Je ne trouve pas mon téléphone."}]'::jsonb, '/faɪnd/', '{"id": "en.d.find", "word": "find", "translation": "trouver", "partOfSpeech": "verb", "ipa": "/faɪnd/", "explanation": "Find veut dire trouver quelque chose qu''on cherche ou qu''on découvre ; son passé est irrégulier : found /faʊnd/.", "examples": [{"text": "My father found my keys yesterday.", "translation": "Mon père a trouvé mes clés hier."}, {"text": "I can''t find my phone.", "translation": "Je ne trouve pas mon téléphone."}], "confusions": [{"word": "founded", "note": "founded est le passé de to found (fonder), un autre verbe. Le passé de find est found."}], "forms": {"thirdPerson": "finds", "past": "found", "pastParticiple": "found", "ing": "finding"}, "unitId": "en.v.find"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.put', 'en', 'put', 'mettre, poser', 'Put veut dire placer quelque chose quelque part ; il ne change pas au passé : put → put.', '[{"text": "She put her keys in her bag.", "translation": "Elle a mis ses clés dans son sac."}, {"text": "Please put the book in your bag.", "translation": "Mets le livre dans ton sac, s''il te plaît."}]'::jsonb, '/pʊt/', '{"id": "en.d.put", "word": "put", "translation": "mettre, poser", "partOfSpeech": "verb", "ipa": "/pʊt/", "explanation": "Put veut dire placer quelque chose quelque part ; il ne change pas au passé : put → put.", "examples": [{"text": "She put her keys in her bag.", "translation": "Elle a mis ses clés dans son sac."}, {"text": "Please put the book in your bag.", "translation": "Mets le livre dans ton sac, s''il te plaît."}], "confusions": [], "forms": {"thirdPerson": "puts", "past": "put", "pastParticiple": "put", "ing": "putting"}, "unitId": "en.v.put"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.buy', 'en', 'buy', 'acheter', 'Buy veut dire acheter ; son passé est irrégulier : bought /bɔːt/.', '[{"text": "Anna bought a book for her brother.", "translation": "Anna a acheté un livre pour son frère."}, {"text": "I want to buy a car.", "translation": "Je veux acheter une voiture."}]'::jsonb, '/baɪ/', '{"id": "en.d.buy", "word": "buy", "translation": "acheter", "partOfSpeech": "verb", "ipa": "/baɪ/", "explanation": "Buy veut dire acheter ; son passé est irrégulier : bought /bɔːt/.", "examples": [{"text": "Anna bought a book for her brother.", "translation": "Anna a acheté un livre pour son frère."}, {"text": "I want to buy a car.", "translation": "Je veux acheter une voiture."}], "confusions": [{"word": "by", "note": "by se prononce pareil /baɪ/ mais veut dire « par, près de, en (by car) »."}], "forms": {"thirdPerson": "buys", "past": "bought", "pastParticiple": "bought", "ing": "buying"}, "unitId": "en.v.buy"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.leave', 'en', 'leave', 'partir, quitter', 'Leave veut dire partir d''un endroit ou le quitter, et aussi laisser quelque chose quelque part ; son passé est left.', '[{"text": "My mother left the house at eight.", "translation": "Ma mère a quitté la maison à huit heures."}, {"text": "I left my bag at the gym.", "translation": "J''ai laissé mon sac à la salle de sport."}]'::jsonb, '/liːv/', '{"id": "en.d.leave", "word": "leave", "translation": "partir, quitter", "otherTranslations": ["laisser"], "partOfSpeech": "verb", "ipa": "/liːv/", "explanation": "Leave veut dire partir d''un endroit ou le quitter, et aussi laisser quelque chose quelque part ; son passé est left.", "examples": [{"text": "My mother left the house at eight.", "translation": "Ma mère a quitté la maison à huit heures."}, {"text": "I left my bag at the gym.", "translation": "J''ai laissé mon sac à la salle de sport."}], "confusions": [{"word": "live", "note": "live /lɪv/ = habiter ; leave /liːv/ = partir, quitter."}], "forms": {"thirdPerson": "leaves", "past": "left", "pastParticiple": "left", "ing": "leaving"}, "unitId": "en.v.leave"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.meet', 'en', 'meet', 'rencontrer, retrouver', 'Meet veut dire rencontrer quelqu''un pour la première fois, ou le retrouver ; son passé est met.', '[{"text": "She met her husband at the office.", "translation": "Elle a rencontré son mari au bureau."}, {"text": "I met Anna at the door.", "translation": "J''ai retrouvé Anna à la porte."}]'::jsonb, '/miːt/', '{"id": "en.d.meet", "word": "meet", "translation": "rencontrer, retrouver", "partOfSpeech": "verb", "ipa": "/miːt/", "explanation": "Meet veut dire rencontrer quelqu''un pour la première fois, ou le retrouver ; son passé est met.", "examples": [{"text": "She met her husband at the office.", "translation": "Elle a rencontré son mari au bureau."}, {"text": "I met Anna at the door.", "translation": "J''ai retrouvé Anna à la porte."}], "confusions": [{"word": "meat", "note": "meat se prononce pareil /miːt/ mais veut dire « viande »."}], "forms": {"thirdPerson": "meets", "past": "met", "pastParticiple": "met", "ing": "meeting"}, "unitId": "en.v.meet"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.forget', 'en', 'forget', 'oublier', 'Forget veut dire ne plus se souvenir de quelque chose ou ne pas y penser ; son passé est forgot /fəˈɡɒt/.', '[{"text": "He forgot my birthday.", "translation": "Il a oublié mon anniversaire."}, {"text": "Don''t forget your keys!", "translation": "N''oublie pas tes clés !"}]'::jsonb, '/fəˈɡet/', '{"id": "en.d.forget", "word": "forget", "translation": "oublier", "partOfSpeech": "verb", "ipa": "/fəˈɡet/", "explanation": "Forget veut dire ne plus se souvenir de quelque chose ou ne pas y penser ; son passé est forgot /fəˈɡɒt/.", "examples": [{"text": "He forgot my birthday.", "translation": "Il a oublié mon anniversaire."}, {"text": "Don''t forget your keys!", "translation": "N''oublie pas tes clés !"}], "confusions": [], "forms": {"thirdPerson": "forgets", "past": "forgot", "pastParticiple": "forgotten", "ing": "forgetting"}, "unitId": "en.v.forget"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.begin', 'en', 'begin', 'commencer', 'Begin veut dire commencer, comme start, mais son passé est irrégulier : began /bɪˈɡæn/.', '[{"text": "We began at nine.", "translation": "Nous avons commencé à neuf heures."}, {"text": "The story begins in London.", "translation": "L''histoire commence à Londres."}]'::jsonb, '/bɪˈɡɪn/', '{"id": "en.d.begin", "word": "begin", "translation": "commencer", "partOfSpeech": "verb", "ipa": "/bɪˈɡɪn/", "explanation": "Begin veut dire commencer, comme start, mais son passé est irrégulier : began /bɪˈɡæn/.", "examples": [{"text": "We began at nine.", "translation": "Nous avons commencé à neuf heures."}, {"text": "The story begins in London.", "translation": "L''histoire commence à Londres."}], "confusions": [{"word": "start", "note": "start et begin veulent dire « commencer » ; start est régulier (started), begin est irrégulier (began)."}], "forms": {"thirdPerson": "begins", "past": "began", "pastParticiple": "begun", "ing": "beginning"}, "unitId": "en.v.begin"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.holiday', 'en', 'holiday', 'vacances', 'Holiday désigne une période de repos loin du travail ou de l''école, ou un jour férié ; on dit on holiday pour « en vacances ».', '[{"text": "Where did you go on holiday?", "translation": "Où es-tu allé en vacances ?"}, {"text": "We stayed at a hotel on holiday.", "translation": "Nous avons séjourné dans un hôtel pendant les vacances."}]'::jsonb, '/ˈhɒlədeɪ/', '{"id": "en.d.holiday", "word": "holiday", "translation": "vacances", "otherTranslations": ["un jour férié"], "partOfSpeech": "noun", "ipa": "/ˈhɒlədeɪ/", "explanation": "Holiday désigne une période de repos loin du travail ou de l''école, ou un jour férié ; on dit on holiday pour « en vacances ».", "examples": [{"text": "Where did you go on holiday?", "translation": "Où es-tu allé en vacances ?"}, {"text": "We stayed at a hotel on holiday.", "translation": "Nous avons séjourné dans un hôtel pendant les vacances."}], "confusions": [{"word": "vacation", "note": "vacation est l''équivalent américain de holiday : on vacation."}], "forms": {"plural": "holidays"}, "unitId": "en.v.holiday"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.beach', 'en', 'beach', 'plage', 'Une beach est une étendue de sable ou de galets au bord de la mer.', '[{"text": "We went to the beach yesterday.", "translation": "Nous sommes allés à la plage hier."}, {"text": "We walked on the beach after dinner.", "translation": "Nous avons marché sur la plage après le dîner."}]'::jsonb, '/biːtʃ/', '{"id": "en.d.beach", "word": "beach", "translation": "plage", "partOfSpeech": "noun", "ipa": "/biːtʃ/", "explanation": "Une beach est une étendue de sable ou de galets au bord de la mer.", "examples": [{"text": "We went to the beach yesterday.", "translation": "Nous sommes allés à la plage hier."}, {"text": "We walked on the beach after dinner.", "translation": "Nous avons marché sur la plage après le dîner."}], "confusions": [], "forms": {"plural": "beaches"}, "unitId": "en.v.beach"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.hotel', 'en', 'hotel', 'hôtel', 'Un hotel est un bâtiment où l''on paie pour dormir quelques nuits ; le h se prononce, donc on dit a hotel.', '[{"text": "Did you like the hotel?", "translation": "Est-ce que tu as aimé l''hôtel ?"}, {"text": "He didn''t sleep at the hotel.", "translation": "Il n''a pas dormi à l''hôtel."}]'::jsonb, '/həʊˈtel/', '{"id": "en.d.hotel", "word": "hotel", "translation": "hôtel", "partOfSpeech": "noun", "ipa": "/həʊˈtel/", "explanation": "Un hotel est un bâtiment où l''on paie pour dormir quelques nuits ; le h se prononce, donc on dit a hotel.", "examples": [{"text": "Did you like the hotel?", "translation": "Est-ce que tu as aimé l''hôtel ?"}, {"text": "He didn''t sleep at the hotel.", "translation": "Il n''a pas dormi à l''hôtel."}], "confusions": [], "forms": {"plural": "hotels"}, "unitId": "en.v.hotel"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.trip', 'en', 'trip', 'voyage, excursion', 'Un trip est un déplacement assez court, pour le plaisir ou le travail, avec un retour prévu.', '[{"text": "Did you have a good trip?", "translation": "Est-ce que tu as fait bon voyage ?"}, {"text": "What did you do on your trip?", "translation": "Qu''est-ce que tu as fait pendant ton voyage ?"}]'::jsonb, '/trɪp/', '{"id": "en.d.trip", "word": "trip", "translation": "voyage, excursion", "partOfSpeech": "noun", "ipa": "/trɪp/", "explanation": "Un trip est un déplacement assez court, pour le plaisir ou le travail, avec un retour prévu.", "examples": [{"text": "Did you have a good trip?", "translation": "Est-ce que tu as fait bon voyage ?"}, {"text": "What did you do on your trip?", "translation": "Qu''est-ce que tu as fait pendant ton voyage ?"}], "confusions": [{"word": "travel", "note": "trip est un nom (un voyage) ; travel est un verbe (voyager). On ne dit pas a travel."}], "forms": {"plural": "trips"}, "unitId": "en.v.trip"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.weather', 'en', 'weather', 'le temps (la météo)', 'Weather désigne le temps qu''il fait (soleil, pluie, froid) ; c''est un nom qui ne se met pas au pluriel.', '[{"text": "The weather was cold at the beach.", "translation": "Il faisait froid à la plage."}, {"text": "We didn''t like the weather.", "translation": "Nous n''avons pas aimé la météo."}]'::jsonb, '/ˈweðə/', '{"id": "en.d.weather", "word": "weather", "translation": "le temps (la météo)", "partOfSpeech": "noun", "ipa": "/ˈweðə/", "explanation": "Weather désigne le temps qu''il fait (soleil, pluie, froid) ; c''est un nom qui ne se met pas au pluriel.", "examples": [{"text": "The weather was cold at the beach.", "translation": "Il faisait froid à la plage."}, {"text": "We didn''t like the weather.", "translation": "Nous n''avons pas aimé la météo."}], "confusions": [{"word": "time", "note": "time = le temps qui passe ou l''heure ; weather = le temps qu''il fait."}, {"word": "whether", "note": "whether se prononce presque pareil mais veut dire « si » (conjonction)."}], "unitId": "en.v.weather"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.party', 'en', 'party', 'fête', 'Une party est une réunion où l''on se retrouve pour s''amuser, manger et danser.', '[{"text": "Did you invite Anna to the party?", "translation": "Est-ce que tu as invité Anna à la fête ?"}, {"text": "We danced at Tom''s party.", "translation": "Nous avons dansé à la fête de Tom."}]'::jsonb, '/ˈpɑːti/', '{"id": "en.d.party", "word": "party", "translation": "fête", "partOfSpeech": "noun", "ipa": "/ˈpɑːti/", "explanation": "Une party est une réunion où l''on se retrouve pour s''amuser, manger et danser.", "examples": [{"text": "Did you invite Anna to the party?", "translation": "Est-ce que tu as invité Anna à la fête ?"}, {"text": "We danced at Tom''s party.", "translation": "Nous avons dansé à la fête de Tom."}], "confusions": [], "forms": {"plural": "parties"}, "unitId": "en.v.party"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.birthday', 'en', 'birthday', 'anniversaire', 'Birthday est le jour où l''on fête sa naissance : Happy birthday ! (joyeux anniversaire).', '[{"text": "Yesterday was Tom''s birthday.", "translation": "Hier, c''était l''anniversaire de Tom."}, {"text": "She bought a cake for my birthday.", "translation": "Elle a acheté un gâteau pour mon anniversaire."}]'::jsonb, '/ˈbɜːθdeɪ/', '{"id": "en.d.birthday", "word": "birthday", "translation": "anniversaire", "partOfSpeech": "noun", "ipa": "/ˈbɜːθdeɪ/", "explanation": "Birthday est le jour où l''on fête sa naissance : Happy birthday ! (joyeux anniversaire).", "examples": [{"text": "Yesterday was Tom''s birthday.", "translation": "Hier, c''était l''anniversaire de Tom."}, {"text": "She bought a cake for my birthday.", "translation": "Elle a acheté un gâteau pour mon anniversaire."}], "confusions": [{"word": "anniversary", "note": "anniversary = anniversaire d''un événement (mariage) ; birthday = anniversaire de naissance."}], "forms": {"plural": "birthdays"}, "unitId": "en.v.birthday"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.present', 'en', 'present', 'cadeau', 'Un present est un objet qu''on offre à quelqu''un, par exemple pour un anniversaire ; c''est un synonyme de gift.', '[{"text": "Did you buy a present for Anna?", "translation": "Est-ce que tu as acheté un cadeau pour Anna ?"}, {"text": "He gave me a present.", "translation": "Il m''a offert un cadeau."}]'::jsonb, '/ˈprezənt/', '{"id": "en.d.present", "word": "present", "translation": "cadeau", "partOfSpeech": "noun", "ipa": "/ˈprezənt/", "explanation": "Un present est un objet qu''on offre à quelqu''un, par exemple pour un anniversaire ; c''est un synonyme de gift.", "examples": [{"text": "Did you buy a present for Anna?", "translation": "Est-ce que tu as acheté un cadeau pour Anna ?"}, {"text": "He gave me a present.", "translation": "Il m''a offert un cadeau."}], "confusions": [{"word": "gift", "note": "gift est un synonyme de present (cadeau)."}, {"word": "present (verbe)", "note": "Le verbe present (présenter, offrir) se prononce /prɪˈzent/, avec l''accent sur la 2e syllabe ; le nom « cadeau » se prononce /ˈprezənt/."}], "forms": {"plural": "presents"}, "unitId": "en.v.present"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.cake', 'en', 'cake', 'gâteau', 'Un cake est un gâteau sucré qu''on mange souvent à une fête ; on dit aussi some cake pour « du gâteau ».', '[{"text": "We ate cake at the party.", "translation": "Nous avons mangé du gâteau à la fête."}, {"text": "Tom didn''t eat the cake.", "translation": "Tom n''a pas mangé le gâteau."}]'::jsonb, '/keɪk/', '{"id": "en.d.cake", "word": "cake", "translation": "gâteau", "partOfSpeech": "noun", "ipa": "/keɪk/", "explanation": "Un cake est un gâteau sucré qu''on mange souvent à une fête ; on dit aussi some cake pour « du gâteau ».", "examples": [{"text": "We ate cake at the party.", "translation": "Nous avons mangé du gâteau à la fête."}, {"text": "Tom didn''t eat the cake.", "translation": "Tom n''a pas mangé le gâteau."}], "confusions": [], "forms": {"plural": "cakes"}, "unitId": "en.v.cake"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.invite', 'en', 'invite', 'inviter', 'Invite veut dire demander à quelqu''un de venir à un événement ; il finit par e, donc son passé est invited /ɪnˈvaɪtɪd/.', '[{"text": "Lucy invited me to her birthday party.", "translation": "Lucy m''a invité à sa fête d''anniversaire."}, {"text": "Did Tom invite you to dinner?", "translation": "Est-ce que Tom t''a invité à dîner ?"}]'::jsonb, '/ɪnˈvaɪt/', '{"id": "en.d.invite", "word": "invite", "translation": "inviter", "partOfSpeech": "verb", "ipa": "/ɪnˈvaɪt/", "explanation": "Invite veut dire demander à quelqu''un de venir à un événement ; il finit par e, donc son passé est invited /ɪnˈvaɪtɪd/.", "examples": [{"text": "Lucy invited me to her birthday party.", "translation": "Lucy m''a invité à sa fête d''anniversaire."}, {"text": "Did Tom invite you to dinner?", "translation": "Est-ce que Tom t''a invité à dîner ?"}], "confusions": [], "forms": {"thirdPerson": "invites", "past": "invited", "pastParticiple": "invited", "ing": "inviting"}, "unitId": "en.v.invite"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.story', 'en', 'story', 'histoire (récit)', 'Une story est un récit, vrai ou inventé, qu''on raconte ou qu''on lit.', '[{"text": "My mother told us a story.", "translation": "Ma mère nous a raconté une histoire."}, {"text": "Did Tom tell you the story?", "translation": "Est-ce que Tom t''a raconté l''histoire ?"}]'::jsonb, '/ˈstɔːri/', '{"id": "en.d.story", "word": "story", "translation": "histoire (récit)", "partOfSpeech": "noun", "ipa": "/ˈstɔːri/", "explanation": "Une story est un récit, vrai ou inventé, qu''on raconte ou qu''on lit.", "examples": [{"text": "My mother told us a story.", "translation": "Ma mère nous a raconté une histoire."}, {"text": "Did Tom tell you the story?", "translation": "Est-ce que Tom t''a raconté l''histoire ?"}], "confusions": [{"word": "history", "note": "history = l''histoire (le passé, la matière scolaire) ; story = un récit."}], "forms": {"plural": "stories"}, "unitId": "en.v.story"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.happen', 'en', 'happen', 'se passer, arriver', 'Happen veut dire se produire ; son sujet est un événement ou une chose, pas une personne (What happened ?).', '[{"text": "What happened yesterday?", "translation": "Qu''est-ce qui s''est passé hier ?"}, {"text": "Nothing happened at the party.", "translation": "Rien ne s''est passé à la fête."}]'::jsonb, '/ˈhæpən/', '{"id": "en.d.happen", "word": "happen", "translation": "se passer, arriver", "partOfSpeech": "verb", "ipa": "/ˈhæpən/", "explanation": "Happen veut dire se produire ; son sujet est un événement ou une chose, pas une personne (What happened ?).", "examples": [{"text": "What happened yesterday?", "translation": "Qu''est-ce qui s''est passé hier ?"}, {"text": "Nothing happened at the party.", "translation": "Rien ne s''est passé à la fête."}], "confusions": [], "forms": {"thirdPerson": "happens", "past": "happened", "pastParticiple": "happened", "ing": "happening"}, "unitId": "en.v.happen"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.lose', 'en', 'lose', 'perdre', 'Lose veut dire perdre un objet, un match ou son chemin ; son passé est irrégulier : lost /lɒst/.', '[{"text": "Tom lost his bag at the gym.", "translation": "Tom a perdu son sac à la salle de sport."}, {"text": "Where did you lose your keys?", "translation": "Où as-tu perdu tes clés ?"}]'::jsonb, '/luːz/', '{"id": "en.d.lose", "word": "lose", "translation": "perdre", "partOfSpeech": "verb", "ipa": "/luːz/", "explanation": "Lose veut dire perdre un objet, un match ou son chemin ; son passé est irrégulier : lost /lɒst/.", "examples": [{"text": "Tom lost his bag at the gym.", "translation": "Tom a perdu son sac à la salle de sport."}, {"text": "Where did you lose your keys?", "translation": "Où as-tu perdu tes clés ?"}], "confusions": [{"word": "loose", "note": "loose /luːs/ veut dire « lâche » ; lose /luːz/ veut dire « perdre »."}], "forms": {"thirdPerson": "loses", "past": "lost", "pastParticiple": "lost", "ing": "losing"}, "unitId": "en.v.lose"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.win', 'en', 'win', 'gagner', 'Win veut dire gagner une compétition ou un prix ; son passé won se prononce /wʌn/, comme le chiffre one.', '[{"text": "Anna won a present at the party.", "translation": "Anna a gagné un cadeau à la fête."}, {"text": "Did you win?", "translation": "Est-ce que tu as gagné ?"}]'::jsonb, '/wɪn/', '{"id": "en.d.win", "word": "win", "translation": "gagner", "partOfSpeech": "verb", "ipa": "/wɪn/", "explanation": "Win veut dire gagner une compétition ou un prix ; son passé won se prononce /wʌn/, comme le chiffre one.", "examples": [{"text": "Anna won a present at the party.", "translation": "Anna a gagné un cadeau à la fête."}, {"text": "Did you win?", "translation": "Est-ce que tu as gagné ?"}], "confusions": [], "forms": {"thirdPerson": "wins", "past": "won", "pastParticiple": "won", "ing": "winning"}, "unitId": "en.v.win"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.feel', 'en', 'feel', 'se sentir, ressentir', 'Feel s''utilise pour parler de ce qu''on ressent (feel tired, feel cold) ; son passé est irrégulier : felt.', '[{"text": "After the trip, Anna felt tired.", "translation": "Après le voyage, Anna s''est sentie fatiguée."}, {"text": "Did you feel cold at the beach?", "translation": "Est-ce que tu as eu froid à la plage ?"}]'::jsonb, '/fiːl/', '{"id": "en.d.feel", "word": "feel", "translation": "se sentir, ressentir", "partOfSpeech": "verb", "ipa": "/fiːl/", "explanation": "Feel s''utilise pour parler de ce qu''on ressent (feel tired, feel cold) ; son passé est irrégulier : felt.", "examples": [{"text": "After the trip, Anna felt tired.", "translation": "Après le voyage, Anna s''est sentie fatiguée."}, {"text": "Did you feel cold at the beach?", "translation": "Est-ce que tu as eu froid à la plage ?"}], "confusions": [], "forms": {"thirdPerson": "feels", "past": "felt", "pastParticiple": "felt", "ing": "feeling"}, "unitId": "en.v.feel"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.was', 'en', 'was', 'était (passé de am / is)', 'Was est le passé de am et is : on l''utilise avec I, he, she et it pour dire où l''on était ou comment on était.', '[{"text": "She was tired last night.", "translation": "Elle était fatiguée hier soir."}, {"text": "I was born in London.", "translation": "Je suis né à Londres."}]'::jsonb, '/wɒz/', '{"id": "en.d.was", "word": "was", "translation": "était (passé de am / is)", "partOfSpeech": "verb", "ipa": "/wɒz/", "explanation": "Was est le passé de am et is : on l''utilise avec I, he, she et it pour dire où l''on était ou comment on était.", "examples": [{"text": "She was tired last night.", "translation": "Elle était fatiguée hier soir."}, {"text": "I was born in London.", "translation": "Je suis né à Londres."}], "confusions": [{"word": "were", "note": "were est le passé de are, avec you, we et they."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.were', 'en', 'were', 'étais, étions, étiez, étaient (passé de are)', 'Were est le passé de are : on l''utilise avec you, we et they, y compris quand you désigne une seule personne.', '[{"text": "We were at the beach two days ago.", "translation": "Nous étions à la plage il y a deux jours."}, {"text": "Were you at home yesterday?", "translation": "Étais-tu à la maison hier ?"}]'::jsonb, '/wɜː/', '{"id": "en.d.were", "word": "were", "translation": "étais, étions, étiez, étaient (passé de are)", "partOfSpeech": "verb", "ipa": "/wɜː/", "explanation": "Were est le passé de are : on l''utilise avec you, we et they, y compris quand you désigne une seule personne.", "examples": [{"text": "We were at the beach two days ago.", "translation": "Nous étions à la plage il y a deux jours."}, {"text": "Were you at home yesterday?", "translation": "Étais-tu à la maison hier ?"}], "confusions": [{"word": "was", "note": "was est le passé de am et is, avec I, he, she et it."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.wasnt', 'en', 'wasn''t', 'n''était pas', 'Wasn''t (was not) est la forme négative de was : I, he, she et it n''étaient pas quelque part ou dans un état.', '[{"text": "Tom wasn''t at school yesterday.", "translation": "Tom n''était pas à l''école hier."}, {"text": "It wasn''t cold last week.", "translation": "Il ne faisait pas froid la semaine dernière."}]'::jsonb, '/ˈwɒznt/', '{"id": "en.d.wasnt", "word": "wasn''t", "translation": "n''était pas", "partOfSpeech": "verb", "ipa": "/ˈwɒznt/", "explanation": "Wasn''t (was not) est la forme négative de was : I, he, she et it n''étaient pas quelque part ou dans un état.", "examples": [{"text": "Tom wasn''t at school yesterday.", "translation": "Tom n''était pas à l''école hier."}, {"text": "It wasn''t cold last week.", "translation": "Il ne faisait pas froid la semaine dernière."}], "confusions": [{"word": "weren''t", "note": "weren''t est la forme négative de were, avec you, we et they."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.werent', 'en', 'weren''t', 'n''étais pas, n''étions pas, n''étiez pas, n''étaient pas', 'Weren''t (were not) est la forme négative de were : you, we et they n''étaient pas quelque part ou dans un état.', '[{"text": "We weren''t at home last week.", "translation": "Nous n''étions pas à la maison la semaine dernière."}, {"text": "They weren''t hungry.", "translation": "Ils n''avaient pas faim."}]'::jsonb, '/wɜːnt/', '{"id": "en.d.werent", "word": "weren''t", "translation": "n''étais pas, n''étions pas, n''étiez pas, n''étaient pas", "partOfSpeech": "verb", "ipa": "/wɜːnt/", "explanation": "Weren''t (were not) est la forme négative de were : you, we et they n''étaient pas quelque part ou dans un état.", "examples": [{"text": "We weren''t at home last week.", "translation": "Nous n''étions pas à la maison la semaine dernière."}, {"text": "They weren''t hungry.", "translation": "Ils n''avaient pas faim."}], "confusions": [{"word": "wasn''t", "note": "wasn''t est la forme négative de was, avec I, he, she et it."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.did', 'en', 'did', '(auxiliaire du passé) ; a fait', 'Did est l''auxiliaire du passé pour poser une question (Did you go ?) et le passé de do (I did my homework) ; après did, le verbe reste à la forme de base.', '[{"text": "Did you call Anna yesterday?", "translation": "Est-ce que tu as appelé Anna hier ?"}, {"text": "I did my homework at home.", "translation": "J''ai fait mes devoirs à la maison."}]'::jsonb, '/dɪd/', '{"id": "en.d.did", "word": "did", "translation": "(auxiliaire du passé) ; a fait", "partOfSpeech": "auxiliary", "ipa": "/dɪd/", "explanation": "Did est l''auxiliaire du passé pour poser une question (Did you go ?) et le passé de do (I did my homework) ; après did, le verbe reste à la forme de base.", "examples": [{"text": "Did you call Anna yesterday?", "translation": "Est-ce que tu as appelé Anna hier ?"}, {"text": "I did my homework at home.", "translation": "J''ai fait mes devoirs à la maison."}], "confusions": [{"word": "does", "note": "does s''utilise avec he, she et it au présent ; did s''utilise avec toutes les personnes au passé."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.didnt', 'en', 'didn''t', 'n''a pas, n''ai pas, n''as pas (négation au passé)', 'Didn''t (did not) sert à former la négation au passé, avec toutes les personnes, et il est suivi du verbe à la forme de base.', '[{"text": "I didn''t see the film.", "translation": "Je n''ai pas vu le film."}, {"text": "She didn''t go to work yesterday.", "translation": "Elle n''est pas allée au travail hier."}]'::jsonb, '/ˈdɪdnt/', '{"id": "en.d.didnt", "word": "didn''t", "translation": "n''a pas, n''ai pas, n''as pas (négation au passé)", "partOfSpeech": "auxiliary", "ipa": "/ˈdɪdnt/", "explanation": "Didn''t (did not) sert à former la négation au passé, avec toutes les personnes, et il est suivi du verbe à la forme de base.", "examples": [{"text": "I didn''t see the film.", "translation": "Je n''ai pas vu le film."}, {"text": "She didn''t go to work yesterday.", "translation": "Elle n''est pas allée au travail hier."}], "confusions": [{"word": "doesn''t", "note": "doesn''t est la négation du présent avec he, she et it ; didn''t est la négation du passé, avec toutes les personnes."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.tomorrow', 'en', 'tomorrow', 'demain', 'Tomorrow désigne le jour qui suit aujourd''hui ; on peut lui ajouter morning, afternoon ou evening, sans préposition.', '[{"text": "I''ll call you tomorrow.", "translation": "Je t''appellerai demain."}, {"text": "We''re busy tomorrow morning.", "translation": "Nous sommes occupés demain matin."}]'::jsonb, '/təˈmɒrəʊ/', '{"id": "en.d.tomorrow", "word": "tomorrow", "translation": "demain", "otherTranslations": [], "partOfSpeech": "adverb", "ipa": "/təˈmɒrəʊ/", "explanation": "Tomorrow désigne le jour qui suit aujourd''hui ; on peut lui ajouter morning, afternoon ou evening, sans préposition.", "examples": [{"text": "I''ll call you tomorrow.", "translation": "Je t''appellerai demain."}, {"text": "We''re busy tomorrow morning.", "translation": "Nous sommes occupés demain matin."}], "confusions": [{"word": "yesterday", "note": "hier : le jour d''avant. Tomorrow est le jour d''après."}], "unitId": "en.v.tomorrow"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.next', 'en', 'next', 'prochain', 'Next place devant un nom pour parler de la période qui vient après celle-ci : next week, next weekend. On n''ajoute ni the ni préposition devant.', '[{"text": "We''re going to move next week.", "translation": "Nous allons déménager la semaine prochaine."}, {"text": "Anna will visit us next weekend.", "translation": "Anna nous rendra visite le week-end prochain."}]'::jsonb, '/nekst/', '{"id": "en.d.next", "word": "next", "translation": "prochain", "otherTranslations": ["suivant"], "partOfSpeech": "adjective", "ipa": "/nekst/", "explanation": "Next place devant un nom pour parler de la période qui vient après celle-ci : next week, next weekend. On n''ajoute ni the ni préposition devant.", "examples": [{"text": "We''re going to move next week.", "translation": "Nous allons déménager la semaine prochaine."}, {"text": "Anna will visit us next weekend.", "translation": "Anna nous rendra visite le week-end prochain."}], "confusions": [{"word": "last", "note": "dernier, passé : last week = la semaine dernière. Next week = la semaine prochaine."}], "unitId": "en.v.next"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.soon', 'en', 'soon', 'bientôt', 'Soon veut dire que quelque chose va arriver dans peu de temps. Il se place souvent en fin de phrase.', '[{"text": "Dinner will be ready soon.", "translation": "Le dîner sera bientôt prêt."}, {"text": "See you soon!", "translation": "À bientôt !"}]'::jsonb, '/suːn/', '{"id": "en.d.soon", "word": "soon", "translation": "bientôt", "otherTranslations": ["dans peu de temps"], "partOfSpeech": "adverb", "ipa": "/suːn/", "explanation": "Soon veut dire que quelque chose va arriver dans peu de temps. Il se place souvent en fin de phrase.", "examples": [{"text": "Dinner will be ready soon.", "translation": "Le dîner sera bientôt prêt."}, {"text": "See you soon!", "translation": "À bientôt !"}], "confusions": [{"word": "early", "note": "tôt (avant l''heure habituelle). Soon = bientôt, dans peu de temps."}], "unitId": "en.v.soon"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.later', 'en', 'later', 'plus tard', 'Later veut dire « plus tard », après le moment dont on parle. Il se place le plus souvent en fin de phrase.', '[{"text": "I''m busy now. I''ll call you later.", "translation": "Je suis occupé maintenant. Je t''appellerai plus tard."}, {"text": "We''ll have lunch later.", "translation": "Nous déjeunerons plus tard."}]'::jsonb, '/ˈleɪtə/', '{"id": "en.d.later", "word": "later", "translation": "plus tard", "otherTranslations": ["tout à l''heure"], "partOfSpeech": "adverb", "ipa": "/ˈleɪtə/", "explanation": "Later veut dire « plus tard », après le moment dont on parle. Il se place le plus souvent en fin de phrase.", "examples": [{"text": "I''m busy now. I''ll call you later.", "translation": "Je suis occupé maintenant. Je t''appellerai plus tard."}, {"text": "We''ll have lunch later.", "translation": "Nous déjeunerons plus tard."}], "confusions": [{"word": "late", "note": "en retard ou tard. Later (avec -er) = plus tard."}], "unitId": "en.v.later"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.maybe', 'en', 'maybe', 'peut-être', 'Maybe exprime un doute : ce n''est pas sûr. Il se place souvent au début de la phrase, avant le sujet.', '[{"text": "Maybe I''ll stay at home tonight.", "translation": "Peut-être que je resterai à la maison ce soir."}, {"text": "Maybe Tom will come to the party.", "translation": "Peut-être que Tom viendra à la fête."}]'::jsonb, '/ˈmeɪbi/', '{"id": "en.d.maybe", "word": "maybe", "translation": "peut-être", "otherTranslations": [], "partOfSpeech": "adverb", "ipa": "/ˈmeɪbi/", "explanation": "Maybe exprime un doute : ce n''est pas sûr. Il se place souvent au début de la phrase, avant le sujet.", "examples": [{"text": "Maybe I''ll stay at home tonight.", "translation": "Peut-être que je resterai à la maison ce soir."}, {"text": "Maybe Tom will come to the party.", "translation": "Peut-être que Tom viendra à la fête."}], "confusions": [{"word": "probably", "note": "probablement : on est plutôt sûr. Maybe : on n''est pas sûr du tout."}], "unitId": "en.v.maybe"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.promise', 'en', 'promise', 'promettre', 'Promise veut dire s''engager à faire quelque chose. On peut dire I promise, ou promise + to + verbe, ou promise + I''ll + verbe.', '[{"text": "I promise I''ll help you.", "translation": "Je te promets que je t''aiderai."}, {"text": "She promised to call me.", "translation": "Elle a promis de m''appeler."}]'::jsonb, '/ˈprɒmɪs/', '{"id": "en.d.promise", "word": "promise", "translation": "promettre", "otherTranslations": ["une promesse (nom)"], "partOfSpeech": "verb", "ipa": "/ˈprɒmɪs/", "explanation": "Promise veut dire s''engager à faire quelque chose. On peut dire I promise, ou promise + to + verbe, ou promise + I''ll + verbe.", "examples": [{"text": "I promise I''ll help you.", "translation": "Je te promets que je t''aiderai."}, {"text": "She promised to call me.", "translation": "Elle a promis de m''appeler."}], "confusions": [], "forms": {"thirdPerson": "promises", "past": "promised", "pastParticiple": "promised", "ing": "promising"}, "unitId": "en.v.promise"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.bring', 'en', 'bring', 'apporter', 'Bring veut dire porter quelque chose ou amener quelqu''un vers l''endroit où se trouve celui qui parle, ou vers l''endroit dont on parle.', '[{"text": "I''ll bring the cake to the party.", "translation": "J''apporterai le gâteau à la fête."}, {"text": "Can you bring your laptop tomorrow?", "translation": "Tu peux apporter ton ordinateur portable demain ?"}]'::jsonb, '/brɪŋ/', '{"id": "en.d.bring", "word": "bring", "translation": "apporter", "otherTranslations": ["amener"], "partOfSpeech": "verb", "ipa": "/brɪŋ/", "explanation": "Bring veut dire porter quelque chose ou amener quelqu''un vers l''endroit où se trouve celui qui parle, ou vers l''endroit dont on parle.", "examples": [{"text": "I''ll bring the cake to the party.", "translation": "J''apporterai le gâteau à la fête."}, {"text": "Can you bring your laptop tomorrow?", "translation": "Tu peux apporter ton ordinateur portable demain ?"}], "confusions": [{"word": "take", "note": "emporter, emmener d''ici vers là-bas. Bring = apporter, amener vers ici."}], "forms": {"thirdPerson": "brings", "past": "brought", "pastParticiple": "brought", "ing": "bringing"}, "unitId": "en.v.bring"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.send', 'en', 'send', 'envoyer', 'Send veut dire faire partir quelque chose (un message, un colis) vers quelqu''un. On dit send something to someone ou send someone something.', '[{"text": "I''ll send you a photo tonight.", "translation": "Je t''enverrai une photo ce soir."}, {"text": "Tom sends a book to his mother.", "translation": "Tom envoie un livre à sa mère."}]'::jsonb, '/send/', '{"id": "en.d.send", "word": "send", "translation": "envoyer", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/send/", "explanation": "Send veut dire faire partir quelque chose (un message, un colis) vers quelqu''un. On dit send something to someone ou send someone something.", "examples": [{"text": "I''ll send you a photo tonight.", "translation": "Je t''enverrai une photo ce soir."}, {"text": "Tom sends a book to his mother.", "translation": "Tom envoie un livre à sa mère."}], "confusions": [], "forms": {"thirdPerson": "sends", "past": "sent", "pastParticiple": "sent", "ing": "sending"}, "unitId": "en.v.send"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.lend', 'en', 'lend', 'prêter', 'Lend veut dire donner quelque chose à quelqu''un pour une durée limitée : c''est toi qui possèdes l''objet. On dit lend something to someone ou lend someone something.', '[{"text": "I''ll lend you my car.", "translation": "Je te prêterai ma voiture."}, {"text": "Can you lend me ten pounds?", "translation": "Tu peux me prêter dix livres ?"}]'::jsonb, '/lend/', '{"id": "en.d.lend", "word": "lend", "translation": "prêter", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/lend/", "explanation": "Lend veut dire donner quelque chose à quelqu''un pour une durée limitée : c''est toi qui possèdes l''objet. On dit lend something to someone ou lend someone something.", "examples": [{"text": "I''ll lend you my car.", "translation": "Je te prêterai ma voiture."}, {"text": "Can you lend me ten pounds?", "translation": "Tu peux me prêter dix livres ?"}], "confusions": [{"word": "borrow", "note": "emprunter : on prend l''objet de quelqu''un. Lend = prêter, borrow = emprunter."}], "forms": {"thirdPerson": "lends", "past": "lent", "pastParticiple": "lent", "ing": "lending"}, "unitId": "en.v.lend"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.borrow', 'en', 'borrow', 'emprunter', 'Borrow veut dire prendre quelque chose à quelqu''un pour une durée limitée : c''est lui qui possède l''objet. On dit borrow something from someone.', '[{"text": "Can I borrow your phone, please?", "translation": "Je peux emprunter ton téléphone, s''il te plaît ?"}, {"text": "Anna borrowed a book from the teacher.", "translation": "Anna a emprunté un livre au professeur."}]'::jsonb, '/ˈbɒrəʊ/', '{"id": "en.d.borrow", "word": "borrow", "translation": "emprunter", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/ˈbɒrəʊ/", "explanation": "Borrow veut dire prendre quelque chose à quelqu''un pour une durée limitée : c''est lui qui possède l''objet. On dit borrow something from someone.", "examples": [{"text": "Can I borrow your phone, please?", "translation": "Je peux emprunter ton téléphone, s''il te plaît ?"}, {"text": "Anna borrowed a book from the teacher.", "translation": "Anna a emprunté un livre au professeur."}], "confusions": [{"word": "lend", "note": "prêter : on donne l''objet pour un temps. Borrow = emprunter, lend = prêter."}], "forms": {"thirdPerson": "borrows", "past": "borrowed", "pastParticiple": "borrowed", "ing": "borrowing"}, "unitId": "en.v.borrow"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.plan', 'en', 'plan', 'prévoir', 'Comme verbe, plan veut dire préparer à l''avance ce qu''on va faire (plan to + verbe). Comme nom, a plan est un projet ou un programme.', '[{"text": "We plan to visit London next year.", "translation": "Nous prévoyons de visiter Londres l''année prochaine."}, {"text": "I have a plan for the weekend.", "translation": "J''ai un projet pour le week-end."}]'::jsonb, '/plæn/', '{"id": "en.d.plan", "word": "plan", "translation": "prévoir", "otherTranslations": ["un projet (nom)", "un plan (nom)"], "partOfSpeech": "verb", "ipa": "/plæn/", "explanation": "Comme verbe, plan veut dire préparer à l''avance ce qu''on va faire (plan to + verbe). Comme nom, a plan est un projet ou un programme.", "examples": [{"text": "We plan to visit London next year.", "translation": "Nous prévoyons de visiter Londres l''année prochaine."}, {"text": "I have a plan for the weekend.", "translation": "J''ai un projet pour le week-end."}], "confusions": [], "forms": {"thirdPerson": "plans", "past": "planned", "pastParticiple": "planned", "ing": "planning"}, "unitId": "en.v.plan"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.move', 'en', 'move', 'déménager', 'Move veut dire changer de place. Pour parler d''un logement, on dit move house, ou move to + lieu : move to Paris.', '[{"text": "They''re going to move to Paris.", "translation": "Ils vont déménager à Paris."}, {"text": "Don''t move! Stay there.", "translation": "Ne bouge pas ! Reste là."}]'::jsonb, '/muːv/', '{"id": "en.d.move", "word": "move", "translation": "déménager", "otherTranslations": ["bouger", "déplacer"], "partOfSpeech": "verb", "ipa": "/muːv/", "explanation": "Move veut dire changer de place. Pour parler d''un logement, on dit move house, ou move to + lieu : move to Paris.", "examples": [{"text": "They''re going to move to Paris.", "translation": "Ils vont déménager à Paris."}, {"text": "Don''t move! Stay there.", "translation": "Ne bouge pas ! Reste là."}], "confusions": [], "forms": {"thirdPerson": "moves", "past": "moved", "pastParticiple": "moved", "ing": "moving"}, "unitId": "en.v.move"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.learn', 'en', 'learn', 'apprendre', 'Learn veut dire acquérir un savoir ou un savoir-faire : learn English, learn to drive. Au passé, on écrit learned (partout) ou learnt (surtout en anglais britannique).', '[{"text": "I want to learn French.", "translation": "Je veux apprendre le français."}, {"text": "My son is learning to swim.", "translation": "Mon fils apprend à nager."}]'::jsonb, '/lɜːn/', '{"id": "en.d.learn", "word": "learn", "translation": "apprendre", "otherTranslations": [], "partOfSpeech": "verb", "ipa": "/lɜːn/", "explanation": "Learn veut dire acquérir un savoir ou un savoir-faire : learn English, learn to drive. Au passé, on écrit learned (partout) ou learnt (surtout en anglais britannique).", "examples": [{"text": "I want to learn French.", "translation": "Je veux apprendre le français."}, {"text": "My son is learning to swim.", "translation": "Mon fils apprend à nager."}], "confusions": [{"word": "teach", "note": "enseigner : on transmet un savoir. Learn = apprendre, teach = enseigner."}], "forms": {"thirdPerson": "learns", "past": "learned", "pastParticiple": "learned", "ing": "learning"}, "unitId": "en.v.learn"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.save', 'en', 'save', 'économiser', 'Save veut dire mettre de côté (save money), enregistrer (save a file) ou sauver quelqu''un. Le sens se comprend grâce au mot qui suit.', '[{"text": "We''re going to save money for a holiday.", "translation": "Nous allons économiser de l''argent pour des vacances."}, {"text": "Save your homework on the laptop.", "translation": "Sauvegarde tes devoirs sur l''ordinateur portable."}]'::jsonb, '/seɪv/', '{"id": "en.d.save", "word": "save", "translation": "économiser", "otherTranslations": ["sauvegarder", "sauver"], "partOfSpeech": "verb", "ipa": "/seɪv/", "explanation": "Save veut dire mettre de côté (save money), enregistrer (save a file) ou sauver quelqu''un. Le sens se comprend grâce au mot qui suit.", "examples": [{"text": "We''re going to save money for a holiday.", "translation": "Nous allons économiser de l''argent pour des vacances."}, {"text": "Save your homework on the laptop.", "translation": "Sauvegarde tes devoirs sur l''ordinateur portable."}], "confusions": [], "forms": {"thirdPerson": "saves", "past": "saved", "pastParticiple": "saved", "ing": "saving"}, "unitId": "en.v.save"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.change', 'en', 'change', 'changer', 'Change veut dire rendre différent, ou remplacer une chose par une autre. Au sens de « changer de » (change your job), il n''y a pas de préposition.', '[{"text": "I''m going to change my job.", "translation": "Je vais changer de travail."}, {"text": "The weather will change tomorrow.", "translation": "Le temps changera demain."}]'::jsonb, '/tʃeɪndʒ/', '{"id": "en.d.change", "word": "change", "translation": "changer", "otherTranslations": ["un changement (nom)", "la monnaie (nom)"], "partOfSpeech": "verb", "ipa": "/tʃeɪndʒ/", "explanation": "Change veut dire rendre différent, ou remplacer une chose par une autre. Au sens de « changer de » (change your job), il n''y a pas de préposition.", "examples": [{"text": "I''m going to change my job.", "translation": "Je vais changer de travail."}, {"text": "The weather will change tomorrow.", "translation": "Le temps changera demain."}], "confusions": [], "forms": {"thirdPerson": "changes", "past": "changed", "pastParticiple": "changed", "ing": "changing"}, "unitId": "en.v.change"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.year', 'en', 'year', 'année', 'Year est une période de douze mois. Pour l''âge, on dit I''m twenty years old : on utilise be, jamais « have ».', '[{"text": "Next year, we''re going to travel.", "translation": "L''année prochaine, nous allons voyager."}, {"text": "My daughter is five years old.", "translation": "Ma fille a cinq ans."}]'::jsonb, '/jɪə/', '{"id": "en.d.year", "word": "year", "translation": "année", "otherTranslations": ["an"], "partOfSpeech": "noun", "ipa": "/jɪə/", "explanation": "Year est une période de douze mois. Pour l''âge, on dit I''m twenty years old : on utilise be, jamais « have ».", "examples": [{"text": "Next year, we''re going to travel.", "translation": "L''année prochaine, nous allons voyager."}, {"text": "My daughter is five years old.", "translation": "Ma fille a cinq ans."}], "confusions": [], "forms": {"plural": "years"}, "unitId": "en.v.year"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.job', 'en', 'job', 'emploi', 'Job est un emploi précis : on peut dire a job, my job, a new job. C''est un nom qu''on peut compter.', '[{"text": "Anna has a new job in London.", "translation": "Anna a un nouvel emploi à Londres."}, {"text": "I''m going to look for a job.", "translation": "Je vais chercher un emploi."}]'::jsonb, '/dʒɒb/', '{"id": "en.d.job", "word": "job", "translation": "emploi", "otherTranslations": ["travail", "métier"], "partOfSpeech": "noun", "ipa": "/dʒɒb/", "explanation": "Job est un emploi précis : on peut dire a job, my job, a new job. C''est un nom qu''on peut compter.", "examples": [{"text": "Anna has a new job in London.", "translation": "Anna a un nouvel emploi à Londres."}, {"text": "I''m going to look for a job.", "translation": "Je vais chercher un emploi."}], "confusions": [{"word": "work", "note": "le travail en général, sans article : I like my work. Job = un emploi précis : a job."}], "forms": {"plural": "jobs"}, "unitId": "en.v.job"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.apartment', 'en', 'apartment', 'appartement', 'Un apartment est un logement dans un immeuble. En anglais britannique, on dit aussi flat.', '[{"text": "We''re going to buy an apartment.", "translation": "Nous allons acheter un appartement."}, {"text": "Their apartment is near the office.", "translation": "Leur appartement est près du bureau."}]'::jsonb, '/əˈpɑːtmənt/', '{"id": "en.d.apartment", "word": "apartment", "translation": "appartement", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/əˈpɑːtmənt/", "explanation": "Un apartment est un logement dans un immeuble. En anglais britannique, on dit aussi flat.", "examples": [{"text": "We''re going to buy an apartment.", "translation": "Nous allons acheter un appartement."}, {"text": "Their apartment is near the office.", "translation": "Leur appartement est près du bureau."}], "confusions": [{"word": "house", "note": "une maison, pour une ou plusieurs familles. Apartment = un logement dans un immeuble."}], "forms": {"plural": "apartments"}, "unitId": "en.v.apartment"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.city', 'en', 'city', 'ville', 'City est une grande ville, comme London ou Paris. Le pluriel se forme en -ies.', '[{"text": "London is a big city.", "translation": "Londres est une grande ville."}, {"text": "I''m going to live in a new city.", "translation": "Je vais vivre dans une nouvelle ville."}]'::jsonb, '/ˈsɪti/', '{"id": "en.d.city", "word": "city", "translation": "ville", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈsɪti/", "explanation": "City est une grande ville, comme London ou Paris. Le pluriel se forme en -ies.", "examples": [{"text": "London is a big city.", "translation": "Londres est une grande ville."}, {"text": "I''m going to live in a new city.", "translation": "Je vais vivre dans une nouvelle ville."}], "confusions": [{"word": "town", "note": "une ville plus petite. City = une grande ville."}], "forms": {"plural": "cities"}, "unitId": "en.v.city"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.country', 'en', 'country', 'pays', 'Country est un pays, comme France ou England. Avec the, the country peut aussi désigner la campagne.', '[{"text": "France is a beautiful country.", "translation": "La France est un beau pays."}, {"text": "They want to move to another country.", "translation": "Ils veulent déménager dans un autre pays."}]'::jsonb, '/ˈkʌntri/', '{"id": "en.d.country", "word": "country", "translation": "pays", "otherTranslations": ["campagne (the country)"], "partOfSpeech": "noun", "ipa": "/ˈkʌntri/", "explanation": "Country est un pays, comme France ou England. Avec the, the country peut aussi désigner la campagne.", "examples": [{"text": "France is a beautiful country.", "translation": "La France est un beau pays."}, {"text": "They want to move to another country.", "translation": "Ils veulent déménager dans un autre pays."}], "confusions": [], "forms": {"plural": "countries"}, "unitId": "en.v.country"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.probably', 'en', 'probably', 'probablement', 'Probably veut dire « il y a de grandes chances que ». Avec will, il se place entre will et le verbe : I''ll probably stay. Avec won''t, il se place avant won''t.', '[{"text": "Tom will probably be late.", "translation": "Tom sera probablement en retard."}, {"text": "I probably won''t go to the gym tonight.", "translation": "Je n''irai probablement pas à la salle de sport ce soir."}]'::jsonb, '/ˈprɒbəbli/', '{"id": "en.d.probably", "word": "probably", "translation": "probablement", "otherTranslations": [], "partOfSpeech": "adverb", "ipa": "/ˈprɒbəbli/", "explanation": "Probably veut dire « il y a de grandes chances que ». Avec will, il se place entre will et le verbe : I''ll probably stay. Avec won''t, il se place avant won''t.", "examples": [{"text": "Tom will probably be late.", "translation": "Tom sera probablement en retard."}, {"text": "I probably won''t go to the gym tonight.", "translation": "Je n''irai probablement pas à la salle de sport ce soir."}], "confusions": [{"word": "maybe", "note": "peut-être, moins sûr. Probably = on a de bonnes raisons de le penser."}], "unitId": "en.v.probably"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.hope', 'en', 'hope', 'espérer', 'Hope veut dire souhaiter qu''une chose arrive. On dit I hope + phrase, et après hope on peut employer will pour parler du futur : I hope it will be nice.', '[{"text": "I hope you''ll like the present.", "translation": "J''espère que le cadeau te plaira."}, {"text": "We hope Anna will come.", "translation": "Nous espérons qu''Anna viendra."}]'::jsonb, '/həʊp/', '{"id": "en.d.hope", "word": "hope", "translation": "espérer", "otherTranslations": ["l''espoir (nom)"], "partOfSpeech": "verb", "ipa": "/həʊp/", "explanation": "Hope veut dire souhaiter qu''une chose arrive. On dit I hope + phrase, et après hope on peut employer will pour parler du futur : I hope it will be nice.", "examples": [{"text": "I hope you''ll like the present.", "translation": "J''espère que le cadeau te plaira."}, {"text": "We hope Anna will come.", "translation": "Nous espérons qu''Anna viendra."}], "confusions": [], "forms": {"thirdPerson": "hopes", "past": "hoped", "pastParticiple": "hoped", "ing": "hoping"}, "unitId": "en.v.hope"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.guess', 'en', 'guess', 'deviner', 'Guess veut dire dire ce qu''on pense sans en être sûr. I guess + phrase veut dire « je suppose que… ».', '[{"text": "I guess he''ll be home soon.", "translation": "Je suppose qu''il sera bientôt à la maison."}, {"text": "Can you guess my age?", "translation": "Tu peux deviner mon âge ?"}]'::jsonb, '/ɡes/', '{"id": "en.d.guess", "word": "guess", "translation": "deviner", "otherTranslations": ["supposer", "une supposition (nom)"], "partOfSpeech": "verb", "ipa": "/ɡes/", "explanation": "Guess veut dire dire ce qu''on pense sans en être sûr. I guess + phrase veut dire « je suppose que… ».", "examples": [{"text": "I guess he''ll be home soon.", "translation": "Je suppose qu''il sera bientôt à la maison."}, {"text": "Can you guess my age?", "translation": "Tu peux deviner mon âge ?"}], "confusions": [], "forms": {"thirdPerson": "guesses", "past": "guessed", "pastParticiple": "guessed", "ing": "guessing"}, "unitId": "en.v.guess"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.idea', 'en', 'idea', 'idée', 'Une idea est une pensée ou une proposition. Elle commence par un son de voyelle : an idea. Pour accepter, on dit That''s a good idea.', '[{"text": "That''s a good idea!", "translation": "C''est une bonne idée !"}, {"text": "I have an idea for dinner.", "translation": "J''ai une idée pour le dîner."}]'::jsonb, '/aɪˈdɪə/', '{"id": "en.d.idea", "word": "idea", "translation": "idée", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/aɪˈdɪə/", "explanation": "Une idea est une pensée ou une proposition. Elle commence par un son de voyelle : an idea. Pour accepter, on dit That''s a good idea.", "examples": [{"text": "That''s a good idea!", "translation": "C''est une bonne idée !"}, {"text": "I have an idea for dinner.", "translation": "J''ai une idée pour le dîner."}], "confusions": [], "forms": {"plural": "ideas"}, "unitId": "en.v.idea"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.problem', 'en', 'problem', 'problème', 'Un problem est une difficulté. Il s''écrit sans e à la fin. No problem veut dire « pas de souci ».', '[{"text": "We have a problem with the car.", "translation": "Nous avons un problème avec la voiture."}, {"text": "No problem, I''ll fix it.", "translation": "Pas de problème, je vais le réparer."}]'::jsonb, '/ˈprɒbləm/', '{"id": "en.d.problem", "word": "problem", "translation": "problème", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈprɒbləm/", "explanation": "Un problem est une difficulté. Il s''écrit sans e à la fin. No problem veut dire « pas de souci ».", "examples": [{"text": "We have a problem with the car.", "translation": "Nous avons un problème avec la voiture."}, {"text": "No problem, I''ll fix it.", "translation": "Pas de problème, je vais le réparer."}], "confusions": [], "forms": {"plural": "problems"}, "unitId": "en.v.problem"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.appointment', 'en', 'appointment', 'rendez-vous', 'Un appointment est un rendez-vous fixé à une heure précise avec un professionnel (médecin, dentiste, administration). On dit have an appointment ou make an appointment.', '[{"text": "I have an appointment at ten.", "translation": "J''ai un rendez-vous à dix heures."}, {"text": "Anna is making an appointment with the doctor.", "translation": "Anna prend rendez-vous chez le médecin."}]'::jsonb, '/əˈpɔɪntmənt/', '{"id": "en.d.appointment", "word": "appointment", "translation": "rendez-vous", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/əˈpɔɪntmənt/", "explanation": "Un appointment est un rendez-vous fixé à une heure précise avec un professionnel (médecin, dentiste, administration). On dit have an appointment ou make an appointment.", "examples": [{"text": "I have an appointment at ten.", "translation": "J''ai un rendez-vous à dix heures."}, {"text": "Anna is making an appointment with the doctor.", "translation": "Anna prend rendez-vous chez le médecin."}], "confusions": [{"word": "meeting", "note": "une réunion, souvent de travail. Appointment = un rendez-vous médical ou administratif."}], "forms": {"plural": "appointments"}, "unitId": "en.v.appointment"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.meeting', 'en', 'meeting', 'réunion', 'Un meeting est une réunion où plusieurs personnes se retrouvent, surtout au travail. On dit have a meeting.', '[{"text": "We have a meeting at the office tomorrow.", "translation": "Nous avons une réunion au bureau demain."}, {"text": "Tom is in a meeting now.", "translation": "Tom est en réunion maintenant."}]'::jsonb, '/ˈmiːtɪŋ/', '{"id": "en.d.meeting", "word": "meeting", "translation": "réunion", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈmiːtɪŋ/", "explanation": "Un meeting est une réunion où plusieurs personnes se retrouvent, surtout au travail. On dit have a meeting.", "examples": [{"text": "We have a meeting at the office tomorrow.", "translation": "Nous avons une réunion au bureau demain."}, {"text": "Tom is in a meeting now.", "translation": "Tom est en réunion maintenant."}], "confusions": [{"word": "appointment", "note": "un rendez-vous (médecin, dentiste). Meeting = une réunion."}], "forms": {"plural": "meetings"}, "unitId": "en.v.meeting"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.dentist', 'en', 'dentist', 'dentiste', 'Un dentist soigne les dents. On dit see the dentist ou go to the dentist''s (chez le dentiste).', '[{"text": "My dentist is near the office.", "translation": "Mon dentiste est près du bureau."}, {"text": "I''m going to the dentist''s tomorrow.", "translation": "Je vais chez le dentiste demain."}]'::jsonb, '/ˈdentɪst/', '{"id": "en.d.dentist", "word": "dentist", "translation": "dentiste", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈdentɪst/", "explanation": "Un dentist soigne les dents. On dit see the dentist ou go to the dentist''s (chez le dentiste).", "examples": [{"text": "My dentist is near the office.", "translation": "Mon dentiste est près du bureau."}, {"text": "I''m going to the dentist''s tomorrow.", "translation": "Je vais chez le dentiste demain."}], "confusions": [], "forms": {"plural": "dentists"}, "unitId": "en.v.dentist"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.doctor', 'en', 'doctor', 'médecin', 'Un doctor est un médecin. On dit see a doctor pour consulter, et go to the doctor''s pour aller chez le médecin.', '[{"text": "She''s seeing the doctor tomorrow morning.", "translation": "Elle voit le médecin demain matin."}, {"text": "My mother is a doctor.", "translation": "Ma mère est médecin."}]'::jsonb, '/ˈdɒktə/', '{"id": "en.d.doctor", "word": "doctor", "translation": "médecin", "otherTranslations": ["docteur"], "partOfSpeech": "noun", "ipa": "/ˈdɒktə/", "explanation": "Un doctor est un médecin. On dit see a doctor pour consulter, et go to the doctor''s pour aller chez le médecin.", "examples": [{"text": "She''s seeing the doctor tomorrow morning.", "translation": "Elle voit le médecin demain matin."}, {"text": "My mother is a doctor.", "translation": "Ma mère est médecin."}], "confusions": [], "forms": {"plural": "doctors"}, "unitId": "en.v.doctor"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.flight', 'en', 'flight', 'vol', 'Un flight est un voyage en avion, avec un numéro et une heure. On dit book a flight (réserver un vol) ou catch a flight.', '[{"text": "Our flight to Paris is at six.", "translation": "Notre vol pour Paris est à six heures."}, {"text": "I''m booking a flight for next week.", "translation": "Je réserve un vol pour la semaine prochaine."}]'::jsonb, '/flaɪt/', '{"id": "en.d.flight", "word": "flight", "translation": "vol", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/flaɪt/", "explanation": "Un flight est un voyage en avion, avec un numéro et une heure. On dit book a flight (réserver un vol) ou catch a flight.", "examples": [{"text": "Our flight to Paris is at six.", "translation": "Notre vol pour Paris est à six heures."}, {"text": "I''m booking a flight for next week.", "translation": "Je réserve un vol pour la semaine prochaine."}], "confusions": [], "forms": {"plural": "flights"}, "unitId": "en.v.flight"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.will', 'en', 'will', '(auxiliaire du futur)', 'Will se place avant le verbe de base pour parler du futur : prédiction, décision sur le moment, promesse, proposition. Il ne change pas selon la personne et se réduit en ''ll : I''ll, she''ll, they''ll.', '[{"text": "It will be cold tomorrow.", "translation": "Il fera froid demain."}, {"text": "Will you help me with my homework?", "translation": "Tu veux bien m''aider pour mes devoirs ?"}]'::jsonb, '/wɪl/', '{"id": "en.d.will", "word": "will", "translation": "(auxiliaire du futur)", "otherTranslations": ["marque le futur : je ferai, tu feras…"], "partOfSpeech": "modal", "ipa": "/wɪl/", "explanation": "Will se place avant le verbe de base pour parler du futur : prédiction, décision sur le moment, promesse, proposition. Il ne change pas selon la personne et se réduit en ''ll : I''ll, she''ll, they''ll.", "examples": [{"text": "It will be cold tomorrow.", "translation": "Il fera froid demain."}, {"text": "Will you help me with my homework?", "translation": "Tu veux bien m''aider pour mes devoirs ?"}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.wont', 'en', 'won''t', 'ne… pas (futur)', 'Won''t est la forme courte de will not. Il se place avant le verbe de base pour dire qu''on ne fera pas quelque chose, ou que quelque chose n''arrivera pas.', '[{"text": "I won''t be late, I promise.", "translation": "Je ne serai pas en retard, je te le promets."}, {"text": "It won''t rain tomorrow.", "translation": "Il ne pleuvra pas demain."}]'::jsonb, '/wəʊnt/', '{"id": "en.d.wont", "word": "won''t", "translation": "ne… pas (futur)", "otherTranslations": ["ne voudra pas"], "partOfSpeech": "modal", "ipa": "/wəʊnt/", "explanation": "Won''t est la forme courte de will not. Il se place avant le verbe de base pour dire qu''on ne fera pas quelque chose, ou que quelque chose n''arrivera pas.", "examples": [{"text": "I won''t be late, I promise.", "translation": "Je ne serai pas en retard, je te le promets."}, {"text": "It won''t rain tomorrow.", "translation": "Il ne pleuvra pas demain."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.going_to', 'en', 'going to', 'aller (+ verbe)', 'Going to s''emploie avec am, is ou are, suivi d''un verbe de base, pour parler d''un projet décidé ou d''une prédiction avec un signe visible. À l''oral, on entend souvent gonna /ˈɡɒnə/, mais on n''écrit pas gonna dans un texte soigné.', '[{"text": "I''m going to learn French.", "translation": "Je vais apprendre le français."}, {"text": "Look at the sky! It''s going to rain.", "translation": "Regarde le ciel ! Il va pleuvoir."}]'::jsonb, '/ˈɡəʊɪŋ tuː/', '{"id": "en.d.going_to", "word": "going to", "translation": "aller (+ verbe)", "otherTranslations": ["être sur le point de"], "partOfSpeech": "expression", "ipa": "/ˈɡəʊɪŋ tuː/", "explanation": "Going to s''emploie avec am, is ou are, suivi d''un verbe de base, pour parler d''un projet décidé ou d''une prédiction avec un signe visible. À l''oral, on entend souvent gonna /ˈɡɒnə/, mais on n''écrit pas gonna dans un texte soigné.", "examples": [{"text": "I''m going to learn French.", "translation": "Je vais apprendre le français."}, {"text": "Look at the sky! It''s going to rain.", "translation": "Regarde le ciel ! Il va pleuvoir."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.kitchen', 'en', 'kitchen', 'cuisine (pièce)', 'La kitchen est la pièce de la maison où l''on prépare les repas.', '[{"text": "We have breakfast in the kitchen.", "translation": "Nous prenons le petit-déjeuner dans la cuisine."}, {"text": "There is a dog in the kitchen.", "translation": "Il y a un chien dans la cuisine."}]'::jsonb, '/ˈkɪtʃɪn/', '{"id": "en.d.kitchen", "word": "kitchen", "translation": "cuisine (pièce)", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈkɪtʃɪn/", "explanation": "La kitchen est la pièce de la maison où l''on prépare les repas.", "examples": [{"text": "We have breakfast in the kitchen.", "translation": "Nous prenons le petit-déjeuner dans la cuisine."}, {"text": "There is a dog in the kitchen.", "translation": "Il y a un chien dans la cuisine."}], "confusions": [{"word": "cooking", "note": "la cuisine (l''art de cuisiner, les plats) se dit cooking ; kitchen est seulement la pièce."}], "forms": {"plural": "kitchens"}, "unitId": "en.v.kitchen"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.bedroom', 'en', 'bedroom', 'chambre', 'La bedroom est la pièce où l''on dort, dans une maison ou un appartement.', '[{"text": "The house has three bedrooms.", "translation": "La maison a trois chambres."}, {"text": "I sleep in my bedroom.", "translation": "Je dors dans ma chambre."}]'::jsonb, '/ˈbedruːm/', '{"id": "en.d.bedroom", "word": "bedroom", "translation": "chambre", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈbedruːm/", "explanation": "La bedroom est la pièce où l''on dort, dans une maison ou un appartement.", "examples": [{"text": "The house has three bedrooms.", "translation": "La maison a trois chambres."}, {"text": "I sleep in my bedroom.", "translation": "Je dors dans ma chambre."}], "confusions": [{"word": "room", "note": "room veut dire « pièce » en général (et « chambre d''hôtel ») ; bedroom est la chambre à coucher."}], "forms": {"plural": "bedrooms"}, "unitId": "en.v.bedroom"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.bathroom', 'en', 'bathroom', 'salle de bain', 'La bathroom est la pièce où l''on se lave, avec une douche ou une baignoire.', '[{"text": "I take a shower in the bathroom.", "translation": "Je prends une douche dans la salle de bain."}, {"text": "There is a window in the bathroom.", "translation": "Il y a une fenêtre dans la salle de bain."}]'::jsonb, '/ˈbɑːθruːm/', '{"id": "en.d.bathroom", "word": "bathroom", "translation": "salle de bain", "otherTranslations": ["toilettes (en anglais américain)"], "partOfSpeech": "noun", "ipa": "/ˈbɑːθruːm/", "explanation": "La bathroom est la pièce où l''on se lave, avec une douche ou une baignoire.", "examples": [{"text": "I take a shower in the bathroom.", "translation": "Je prends une douche dans la salle de bain."}, {"text": "There is a window in the bathroom.", "translation": "Il y a une fenêtre dans la salle de bain."}], "confusions": [], "forms": {"plural": "bathrooms"}, "unitId": "en.v.bathroom"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.living_room', 'en', 'living room', 'salon', 'Le living room est la pièce principale de la maison, où l''on se détend et reçoit des amis.', '[{"text": "We watch a film in the living room.", "translation": "Nous regardons un film dans le salon."}, {"text": "Anna is in the living room with her mother.", "translation": "Anna est dans le salon avec sa mère."}]'::jsonb, '/ˈlɪvɪŋ ruːm/', '{"id": "en.d.living_room", "word": "living room", "translation": "salon", "otherTranslations": ["séjour"], "partOfSpeech": "noun", "ipa": "/ˈlɪvɪŋ ruːm/", "explanation": "Le living room est la pièce principale de la maison, où l''on se détend et reçoit des amis.", "examples": [{"text": "We watch a film in the living room.", "translation": "Nous regardons un film dans le salon."}, {"text": "Anna is in the living room with her mother.", "translation": "Anna est dans le salon avec sa mère."}], "confusions": [], "forms": {"plural": "living rooms"}, "unitId": "en.v.living_room"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.garden', 'en', 'garden', 'jardin', 'Le garden est l''espace avec de l''herbe et des plantes à côté d''une maison.', '[{"text": "The dog is in the garden.", "translation": "Le chien est dans le jardin."}, {"text": "My father works in the garden.", "translation": "Mon père travaille dans le jardin."}]'::jsonb, '/ˈɡɑːdn/', '{"id": "en.d.garden", "word": "garden", "translation": "jardin", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈɡɑːdn/", "explanation": "Le garden est l''espace avec de l''herbe et des plantes à côté d''une maison.", "examples": [{"text": "The dog is in the garden.", "translation": "Le chien est dans le jardin."}, {"text": "My father works in the garden.", "translation": "Mon père travaille dans le jardin."}], "confusions": [{"word": "yard", "note": "en anglais américain, le jardin d''une maison se dit souvent yard."}], "forms": {"plural": "gardens"}, "unitId": "en.v.garden"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.table', 'en', 'table', 'table', 'Une table est un meuble plat sur lequel on pose des objets ou on mange.', '[{"text": "The keys are on the table.", "translation": "Les clés sont sur la table."}, {"text": "We eat dinner at the table.", "translation": "Nous dînons à table."}]'::jsonb, '/ˈteɪbl/', '{"id": "en.d.table", "word": "table", "translation": "table", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈteɪbl/", "explanation": "Une table est un meuble plat sur lequel on pose des objets ou on mange.", "examples": [{"text": "The keys are on the table.", "translation": "Les clés sont sur la table."}, {"text": "We eat dinner at the table.", "translation": "Nous dînons à table."}], "confusions": [], "forms": {"plural": "tables"}, "unitId": "en.v.table"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.chair', 'en', 'chair', 'chaise', 'Une chair est un siège avec un dossier, pour une seule personne.', '[{"text": "Sit on the chair, please.", "translation": "Assieds-toi sur la chaise, s''il te plaît."}, {"text": "There is a chair in my bedroom.", "translation": "Il y a une chaise dans ma chambre."}]'::jsonb, '/tʃeə/', '{"id": "en.d.chair", "word": "chair", "translation": "chaise", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/tʃeə/", "explanation": "Une chair est un siège avec un dossier, pour une seule personne.", "examples": [{"text": "Sit on the chair, please.", "translation": "Assieds-toi sur la chaise, s''il te plaît."}, {"text": "There is a chair in my bedroom.", "translation": "Il y a une chaise dans ma chambre."}], "confusions": [{"word": "armchair", "note": "un fauteuil se dit armchair ; chair est la chaise."}], "forms": {"plural": "chairs"}, "unitId": "en.v.chair"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.sofa', 'en', 'sofa', 'canapé', 'Un sofa est un grand siège confortable pour plusieurs personnes, souvent dans le salon.', '[{"text": "My dog sleeps on the sofa.", "translation": "Mon chien dort sur le canapé."}, {"text": "We sit on the sofa and talk.", "translation": "Nous nous asseyons sur le canapé et nous parlons."}]'::jsonb, '/ˈsəʊfə/', '{"id": "en.d.sofa", "word": "sofa", "translation": "canapé", "otherTranslations": ["divan"], "partOfSpeech": "noun", "ipa": "/ˈsəʊfə/", "explanation": "Un sofa est un grand siège confortable pour plusieurs personnes, souvent dans le salon.", "examples": [{"text": "My dog sleeps on the sofa.", "translation": "Mon chien dort sur le canapé."}, {"text": "We sit on the sofa and talk.", "translation": "Nous nous asseyons sur le canapé et nous parlons."}], "confusions": [{"word": "couch", "note": "couch est un synonyme de sofa, très courant."}], "forms": {"plural": "sofas"}, "unitId": "en.v.sofa"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.fridge', 'en', 'fridge', 'réfrigérateur, frigo', 'Le fridge est l''appareil de la cuisine qui garde les aliments au frais ; c''est la forme courte de refrigerator.', '[{"text": "The milk is in the fridge.", "translation": "Le lait est dans le frigo."}, {"text": "Is there any meat in the fridge?", "translation": "Y a-t-il de la viande dans le frigo ?"}]'::jsonb, '/frɪdʒ/', '{"id": "en.d.fridge", "word": "fridge", "translation": "réfrigérateur, frigo", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/frɪdʒ/", "explanation": "Le fridge est l''appareil de la cuisine qui garde les aliments au frais ; c''est la forme courte de refrigerator.", "examples": [{"text": "The milk is in the fridge.", "translation": "Le lait est dans le frigo."}, {"text": "Is there any meat in the fridge?", "translation": "Y a-t-il de la viande dans le frigo ?"}], "confusions": [], "forms": {"plural": "fridges"}, "unitId": "en.v.fridge"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.lamp', 'en', 'lamp', 'lampe', 'Une lamp est un objet qui donne de la lumière, posé sur un meuble ou sur le sol.', '[{"text": "I have a lamp in my bedroom.", "translation": "J''ai une lampe dans ma chambre."}, {"text": "The lamp is next to the sofa.", "translation": "La lampe est à côté du canapé."}]'::jsonb, '/læmp/', '{"id": "en.d.lamp", "word": "lamp", "translation": "lampe", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/læmp/", "explanation": "Une lamp est un objet qui donne de la lumière, posé sur un meuble ou sur le sol.", "examples": [{"text": "I have a lamp in my bedroom.", "translation": "J''ai une lampe dans ma chambre."}, {"text": "The lamp is next to the sofa.", "translation": "La lampe est à côté du canapé."}], "confusions": [], "forms": {"plural": "lamps"}, "unitId": "en.v.lamp"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.menu', 'en', 'menu', 'menu, carte', 'Le menu est la liste de tous les plats et boissons d''un restaurant : en français, c''est la « carte ».', '[{"text": "Can I have the menu, please?", "translation": "Puis-je avoir la carte, s''il vous plaît ?"}, {"text": "The menu has fish and meat.", "translation": "La carte propose du poisson et de la viande."}]'::jsonb, '/ˈmenjuː/', '{"id": "en.d.menu", "word": "menu", "translation": "menu, carte", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈmenjuː/", "explanation": "Le menu est la liste de tous les plats et boissons d''un restaurant : en français, c''est la « carte ».", "examples": [{"text": "Can I have the menu, please?", "translation": "Puis-je avoir la carte, s''il vous plaît ?"}, {"text": "The menu has fish and meat.", "translation": "La carte propose du poisson et de la viande."}], "confusions": [{"word": "set menu", "note": "le « menu » français à prix fixe (entrée, plat, dessert) se dit plutôt set menu."}], "forms": {"plural": "menus"}, "unitId": "en.v.menu"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.bill', 'en', 'bill', 'addition', 'La bill est le papier qui indique combien on doit payer, au restaurant ou pour l''électricité.', '[{"text": "Can I have the bill, please?", "translation": "Puis-je avoir l''addition, s''il vous plaît ?"}, {"text": "The bill is ten pounds.", "translation": "L''addition est de dix livres."}]'::jsonb, '/bɪl/', '{"id": "en.d.bill", "word": "bill", "translation": "addition", "otherTranslations": ["facture"], "partOfSpeech": "noun", "ipa": "/bɪl/", "explanation": "La bill est le papier qui indique combien on doit payer, au restaurant ou pour l''électricité.", "examples": [{"text": "Can I have the bill, please?", "translation": "Puis-je avoir l''addition, s''il vous plaît ?"}, {"text": "The bill is ten pounds.", "translation": "L''addition est de dix livres."}], "confusions": [{"word": "check", "note": "en anglais américain, l''addition se dit the check."}], "forms": {"plural": "bills"}, "unitId": "en.v.bill"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.waiter', 'en', 'waiter', 'serveur', 'Le waiter est la personne qui prend les commandes et apporte les plats au restaurant.', '[{"text": "Tom asks the waiter for some water.", "translation": "Tom demande de l''eau au serveur."}, {"text": "The waiter is busy.", "translation": "Le serveur est occupé."}]'::jsonb, '/ˈweɪtə/', '{"id": "en.d.waiter", "word": "waiter", "translation": "serveur", "otherTranslations": ["waitress : serveuse"], "partOfSpeech": "noun", "ipa": "/ˈweɪtə/", "explanation": "Le waiter est la personne qui prend les commandes et apporte les plats au restaurant.", "examples": [{"text": "Tom asks the waiter for some water.", "translation": "Tom demande de l''eau au serveur."}, {"text": "The waiter is busy.", "translation": "Le serveur est occupé."}], "confusions": [], "forms": {"plural": "waiters"}, "unitId": "en.v.waiter"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.bread', 'en', 'bread', 'pain', 'Bread est un nom qu''on ne compte pas : il n''a pas de pluriel, et on dit some bread, jamais « a bread » ni « breads ».', '[{"text": "I eat bread for breakfast.", "translation": "Je mange du pain au petit-déjeuner."}, {"text": "We don''t have any bread.", "translation": "Nous n''avons pas de pain."}]'::jsonb, '/bred/', '{"id": "en.d.bread", "word": "bread", "translation": "pain", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/bred/", "explanation": "Bread est un nom qu''on ne compte pas : il n''a pas de pluriel, et on dit some bread, jamais « a bread » ni « breads ».", "examples": [{"text": "I eat bread for breakfast.", "translation": "Je mange du pain au petit-déjeuner."}, {"text": "We don''t have any bread.", "translation": "Nous n''avons pas de pain."}], "confusions": [], "forms": {}, "unitId": "en.v.bread"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.order', 'en', 'order', 'commander', 'Order, comme verbe, veut dire demander un plat ou un produit : on commande au restaurant ou dans un magasin.', '[{"text": "We want to order dinner.", "translation": "Nous voulons commander le dîner."}, {"text": "Anna orders fish and Tom orders meat.", "translation": "Anna commande du poisson et Tom commande de la viande."}]'::jsonb, '/ˈɔːdə/', '{"id": "en.d.order", "word": "order", "translation": "commander", "otherTranslations": ["une commande (nom)", "un ordre (nom)"], "partOfSpeech": "verb", "ipa": "/ˈɔːdə/", "explanation": "Order, comme verbe, veut dire demander un plat ou un produit : on commande au restaurant ou dans un magasin.", "examples": [{"text": "We want to order dinner.", "translation": "Nous voulons commander le dîner."}, {"text": "Anna orders fish and Tom orders meat.", "translation": "Anna commande du poisson et Tom commande de la viande."}], "confusions": [], "forms": {"thirdPerson": "orders", "past": "ordered", "pastParticiple": "ordered", "ing": "ordering"}, "unitId": "en.v.order"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.price', 'en', 'price', 'prix', 'Le price est la somme d''argent qu''il faut payer pour acheter quelque chose.', '[{"text": "What is the price of the laptop?", "translation": "Quel est le prix de l''ordinateur portable ?"}, {"text": "The price is five pounds.", "translation": "Le prix est de cinq livres."}]'::jsonb, '/praɪs/', '{"id": "en.d.price", "word": "price", "translation": "prix", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/praɪs/", "explanation": "Le price est la somme d''argent qu''il faut payer pour acheter quelque chose.", "examples": [{"text": "What is the price of the laptop?", "translation": "Quel est le prix de l''ordinateur portable ?"}, {"text": "The price is five pounds.", "translation": "Le prix est de cinq livres."}], "confusions": [{"word": "prize", "note": "prize (/praɪz/) est un prix qu''on gagne, une récompense ; price est le prix à payer."}], "forms": {"plural": "prices"}, "unitId": "en.v.price"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.cheap', 'en', 'cheap', 'bon marché, pas cher', 'Cheap décrit quelque chose dont le prix est bas : on ne paie pas beaucoup.', '[{"text": "The bread is cheap.", "translation": "Le pain est bon marché."}, {"text": "The book is cheap: it''s two pounds.", "translation": "Le livre est bon marché : il coûte deux livres."}]'::jsonb, '/tʃiːp/', '{"id": "en.d.cheap", "word": "cheap", "translation": "bon marché, pas cher", "otherTranslations": [], "partOfSpeech": "adjective", "ipa": "/tʃiːp/", "explanation": "Cheap décrit quelque chose dont le prix est bas : on ne paie pas beaucoup.", "examples": [{"text": "The bread is cheap.", "translation": "Le pain est bon marché."}, {"text": "The book is cheap: it''s two pounds.", "translation": "Le livre est bon marché : il coûte deux livres."}], "confusions": [{"word": "expensive", "note": "le contraire de cheap : cher."}], "forms": {"comparative": "cheaper", "superlative": "cheapest"}, "unitId": "en.v.cheap"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.expensive', 'en', 'expensive', 'cher', 'Expensive décrit quelque chose dont le prix est élevé : on paie beaucoup d''argent.', '[{"text": "The laptop is expensive.", "translation": "L''ordinateur portable est cher."}, {"text": "I don''t want an expensive hotel.", "translation": "Je ne veux pas d''hôtel cher."}]'::jsonb, '/ɪkˈspensɪv/', '{"id": "en.d.expensive", "word": "expensive", "translation": "cher", "otherTranslations": [], "partOfSpeech": "adjective", "ipa": "/ɪkˈspensɪv/", "explanation": "Expensive décrit quelque chose dont le prix est élevé : on paie beaucoup d''argent.", "examples": [{"text": "The laptop is expensive.", "translation": "L''ordinateur portable est cher."}, {"text": "I don''t want an expensive hotel.", "translation": "Je ne veux pas d''hôtel cher."}], "confusions": [{"word": "dear", "note": "dear veut dire « cher » dans une lettre (Dear Anna) ; pour un prix élevé, on dit expensive."}], "forms": {"comparative": "more expensive", "superlative": "most expensive"}, "unitId": "en.v.expensive"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.shop', 'en', 'shop', 'magasin, boutique', 'Une shop est un endroit où l''on achète des choses.', '[{"text": "There is a shop near my house.", "translation": "Il y a un magasin près de ma maison."}, {"text": "Anna buys bread in the shop.", "translation": "Anna achète du pain au magasin."}]'::jsonb, '/ʃɒp/', '{"id": "en.d.shop", "word": "shop", "translation": "magasin, boutique", "otherTranslations": ["faire ses achats (verbe)"], "partOfSpeech": "noun", "ipa": "/ʃɒp/", "explanation": "Une shop est un endroit où l''on achète des choses.", "examples": [{"text": "There is a shop near my house.", "translation": "Il y a un magasin près de ma maison."}, {"text": "Anna buys bread in the shop.", "translation": "Anna achète du pain au magasin."}], "confusions": [{"word": "store", "note": "store est le synonyme américain de shop."}], "forms": {"plural": "shops"}, "unitId": "en.v.shop"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.money', 'en', 'money', 'argent', 'Money est l''argent qu''on utilise pour payer : c''est un nom qu''on ne compte pas, sans pluriel.', '[{"text": "I don''t have any money.", "translation": "Je n''ai pas d''argent."}, {"text": "How much money do you need?", "translation": "De combien d''argent as-tu besoin ?"}]'::jsonb, '/ˈmʌni/', '{"id": "en.d.money", "word": "money", "translation": "argent", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈmʌni/", "explanation": "Money est l''argent qu''on utilise pour payer : c''est un nom qu''on ne compte pas, sans pluriel.", "examples": [{"text": "I don''t have any money.", "translation": "Je n''ai pas d''argent."}, {"text": "How much money do you need?", "translation": "De combien d''argent as-tu besoin ?"}], "confusions": [{"word": "silver", "note": "l''argent (le métal) se dit silver ; l''argent qu''on dépense se dit money."}], "forms": {}, "unitId": "en.v.money"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.ticket', 'en', 'ticket', 'billet, ticket', 'Un ticket est un papier qui donne le droit de voyager, d''entrer quelque part ou de participer à quelque chose.', '[{"text": "I need a ticket for the flight.", "translation": "J''ai besoin d''un billet pour le vol."}, {"text": "Tom has two tickets.", "translation": "Tom a deux billets."}]'::jsonb, '/ˈtɪkɪt/', '{"id": "en.d.ticket", "word": "ticket", "translation": "billet, ticket", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈtɪkɪt/", "explanation": "Un ticket est un papier qui donne le droit de voyager, d''entrer quelque part ou de participer à quelque chose.", "examples": [{"text": "I need a ticket for the flight.", "translation": "J''ai besoin d''un billet pour le vol."}, {"text": "Tom has two tickets.", "translation": "Tom a deux billets."}], "confusions": [{"word": "note", "note": "un billet de banque se dit note (banknote en anglais britannique) ; ticket est un billet de transport ou de spectacle."}], "forms": {"plural": "tickets"}, "unitId": "en.v.ticket"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.station', 'en', 'station', 'gare, station', 'Une station est un lieu où l''on prend un train ou un bus : en français, une gare ou une station.', '[{"text": "Anna is at the station.", "translation": "Anna est à la gare."}, {"text": "Tom waits at the station.", "translation": "Tom attend à la gare."}]'::jsonb, '/ˈsteɪʃn/', '{"id": "en.d.station", "word": "station", "translation": "gare, station", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈsteɪʃn/", "explanation": "Une station est un lieu où l''on prend un train ou un bus : en français, une gare ou une station.", "examples": [{"text": "Anna is at the station.", "translation": "Anna est à la gare."}, {"text": "Tom waits at the station.", "translation": "Tom attend à la gare."}], "confusions": [{"word": "petrol station", "note": "une station-service se dit petrol station (gas station en anglais américain)."}], "forms": {"plural": "stations"}, "unitId": "en.v.station"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.airport', 'en', 'airport', 'aéroport', 'Un airport est le lieu où les avions partent et arrivent.', '[{"text": "We arrive at the airport at six o''clock.", "translation": "Nous arrivons à l''aéroport à six heures."}, {"text": "The airport is near the city.", "translation": "L''aéroport est près de la ville."}]'::jsonb, '/ˈeəpɔːt/', '{"id": "en.d.airport", "word": "airport", "translation": "aéroport", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈeəpɔːt/", "explanation": "Un airport est le lieu où les avions partent et arrivent.", "examples": [{"text": "We arrive at the airport at six o''clock.", "translation": "Nous arrivons à l''aéroport à six heures."}, {"text": "The airport is near the city.", "translation": "L''aéroport est près de la ville."}], "confusions": [], "forms": {"plural": "airports"}, "unitId": "en.v.airport"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.passport', 'en', 'passport', 'passeport', 'Un passport est le document officiel dont on a besoin pour voyager dans un autre pays.', '[{"text": "You need a passport to travel.", "translation": "Il faut un passeport pour voyager."}, {"text": "Is your passport in the bag?", "translation": "Ton passeport est-il dans le sac ?"}]'::jsonb, '/ˈpɑːspɔːt/', '{"id": "en.d.passport", "word": "passport", "translation": "passeport", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈpɑːspɔːt/", "explanation": "Un passport est le document officiel dont on a besoin pour voyager dans un autre pays.", "examples": [{"text": "You need a passport to travel.", "translation": "Il faut un passeport pour voyager."}, {"text": "Is your passport in the bag?", "translation": "Ton passeport est-il dans le sac ?"}], "confusions": [], "forms": {"plural": "passports"}, "unitId": "en.v.passport"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.luggage', 'en', 'luggage', 'bagages', 'Luggage désigne tous les sacs et valises d''un voyageur : c''est un nom qu''on ne compte pas, sans -s, avec un verbe au singulier (the luggage is…).', '[{"text": "The luggage is in the car.", "translation": "Les bagages sont dans la voiture."}, {"text": "Tom carries the luggage.", "translation": "Tom porte les bagages."}]'::jsonb, '/ˈlʌɡɪdʒ/', '{"id": "en.d.luggage", "word": "luggage", "translation": "bagages", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈlʌɡɪdʒ/", "explanation": "Luggage désigne tous les sacs et valises d''un voyageur : c''est un nom qu''on ne compte pas, sans -s, avec un verbe au singulier (the luggage is…).", "examples": [{"text": "The luggage is in the car.", "translation": "Les bagages sont dans la voiture."}, {"text": "Tom carries the luggage.", "translation": "Tom porte les bagages."}], "confusions": [{"word": "baggage", "note": "baggage est un synonyme de luggage, surtout en anglais américain ; il ne prend pas de -s non plus."}], "forms": {}, "unitId": "en.v.luggage"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.twenty', 'en', 'twenty', 'vingt', 'Twenty est le nombre 20 ; vingt et un se dit twenty-one, vingt-deux twenty-two, etc.', '[{"text": "It''s twenty past six.", "translation": "Il est six heures vingt."}, {"text": "The bag is twenty pounds.", "translation": "Le sac coûte vingt livres."}]'::jsonb, '/ˈtwenti/', '{"id": "en.d.twenty", "word": "twenty", "translation": "vingt", "otherTranslations": [], "partOfSpeech": "number", "ipa": "/ˈtwenti/", "explanation": "Twenty est le nombre 20 ; vingt et un se dit twenty-one, vingt-deux twenty-two, etc.", "examples": [{"text": "It''s twenty past six.", "translation": "Il est six heures vingt."}, {"text": "The bag is twenty pounds.", "translation": "Le sac coûte vingt livres."}], "confusions": [], "forms": {}, "unitId": "en.v.twenty"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.hundred', 'en', 'hundred', 'cent', 'Hundred est le nombre 100 : on dit a hundred ou one hundred, et le mot ne prend pas de -s après un nombre (two hundred).', '[{"text": "There are a hundred people at the party.", "translation": "Il y a cent personnes à la fête."}, {"text": "The book has two hundred pages.", "translation": "Le livre a deux cents pages."}]'::jsonb, '/ˈhʌndrəd/', '{"id": "en.d.hundred", "word": "hundred", "translation": "cent", "otherTranslations": [], "partOfSpeech": "number", "ipa": "/ˈhʌndrəd/", "explanation": "Hundred est le nombre 100 : on dit a hundred ou one hundred, et le mot ne prend pas de -s après un nombre (two hundred).", "examples": [{"text": "There are a hundred people at the party.", "translation": "Il y a cent personnes à la fête."}, {"text": "The book has two hundred pages.", "translation": "Le livre a deux cents pages."}], "confusions": [], "forms": {}, "unitId": "en.v.hundred"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.hour', 'en', 'hour', 'heure (durée)', 'Une hour est une durée de soixante minutes ; elle ne sert pas à dire l''heure qu''il est (on dit o''clock). Le h est muet : an hour.', '[{"text": "I work six hours a day.", "translation": "Je travaille six heures par jour."}, {"text": "Anna waits for an hour.", "translation": "Anna attend pendant une heure."}]'::jsonb, '/ˈaʊə/', '{"id": "en.d.hour", "word": "hour", "translation": "heure (durée)", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈaʊə/", "explanation": "Une hour est une durée de soixante minutes ; elle ne sert pas à dire l''heure qu''il est (on dit o''clock). Le h est muet : an hour.", "examples": [{"text": "I work six hours a day.", "translation": "Je travaille six heures par jour."}, {"text": "Anna waits for an hour.", "translation": "Anna attend pendant une heure."}], "confusions": [{"word": "o''clock", "note": "pour l''heure qu''il est, on dit It''s seven o''clock, pas « seven hours »."}], "forms": {"plural": "hours"}, "unitId": "en.v.hour"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.minute', 'en', 'minute', 'minute', 'Une minute est une durée de soixante secondes ; il y a soixante minutes dans une heure.', '[{"text": "Wait a minute, please.", "translation": "Attends une minute, s''il te plaît."}, {"text": "The shop is five minutes from my house.", "translation": "Le magasin est à cinq minutes de ma maison."}]'::jsonb, '/ˈmɪnɪt/', '{"id": "en.d.minute", "word": "minute", "translation": "minute", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈmɪnɪt/", "explanation": "Une minute est une durée de soixante secondes ; il y a soixante minutes dans une heure.", "examples": [{"text": "Wait a minute, please.", "translation": "Attends une minute, s''il te plaît."}, {"text": "The shop is five minutes from my house.", "translation": "Le magasin est à cinq minutes de ma maison."}], "confusions": [], "forms": {"plural": "minutes"}, "unitId": "en.v.minute"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.half', 'en', 'half', 'demi, moitié', 'Half est la moitié de quelque chose ; avec l''heure, half past six veut dire six heures et demie. Le l ne se prononce pas.', '[{"text": "It''s half past six.", "translation": "Il est six heures et demie."}, {"text": "Tom eats half of the cake.", "translation": "Tom mange la moitié du gâteau."}]'::jsonb, '/hɑːf/', '{"id": "en.d.half", "word": "half", "translation": "demi, moitié", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/hɑːf/", "explanation": "Half est la moitié de quelque chose ; avec l''heure, half past six veut dire six heures et demie. Le l ne se prononce pas.", "examples": [{"text": "It''s half past six.", "translation": "Il est six heures et demie."}, {"text": "Tom eats half of the cake.", "translation": "Tom mange la moitié du gâteau."}], "confusions": [], "forms": {"plural": "halves"}, "unitId": "en.v.half"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.there', 'en', 'there', 'il y a (there is / there are)', 'There, suivi de is ou are, sert à dire qu''une chose existe ou se trouve quelque part : there is devant un seul élément, there are devant plusieurs.', '[{"text": "There is a dog in the garden.", "translation": "Il y a un chien dans le jardin."}, {"text": "There are three bedrooms in the house.", "translation": "Il y a trois chambres dans la maison."}]'::jsonb, '/ðeə/', '{"id": "en.d.there", "word": "there", "translation": "il y a (there is / there are)", "otherTranslations": ["là, là-bas (lieu)"], "partOfSpeech": "pronoun", "ipa": "/ðeə/", "explanation": "There, suivi de is ou are, sert à dire qu''une chose existe ou se trouve quelque part : there is devant un seul élément, there are devant plusieurs.", "examples": [{"text": "There is a dog in the garden.", "translation": "Il y a un chien dans le jardin."}, {"text": "There are three bedrooms in the house.", "translation": "Il y a trois chambres dans la maison."}], "confusions": [{"word": "their", "note": "their veut dire « leur, leurs » (their house) ; there sert à dire « il y a » ou « là »."}, {"word": "they''re", "note": "they''re = they are (ils sont) ; ce n''est pas le même mot que there."}], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.some', 'en', 'some', 'du, de la, des, quelques', 'Some exprime une quantité qu''on ne précise pas ; on l''utilise dans les phrases affirmatives et dans les demandes ou offres polies.', '[{"text": "We have some bread.", "translation": "Nous avons du pain."}, {"text": "Can I have some water, please?", "translation": "Puis-je avoir de l''eau, s''il vous plaît ?"}]'::jsonb, '/sʌm/', '{"id": "en.d.some", "word": "some", "translation": "du, de la, des, quelques", "otherTranslations": [], "partOfSpeech": "determiner", "ipa": "/sʌm/", "explanation": "Some exprime une quantité qu''on ne précise pas ; on l''utilise dans les phrases affirmatives et dans les demandes ou offres polies.", "examples": [{"text": "We have some bread.", "translation": "Nous avons du pain."}, {"text": "Can I have some water, please?", "translation": "Puis-je avoir de l''eau, s''il vous plaît ?"}], "confusions": [{"word": "any", "note": "any remplace some dans les négations et les questions simples."}], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.any', 'en', 'any', 'du, de la, des (négation, question)', 'Any s''utilise à la place de some dans les phrases négatives et dans les questions simples, avec les pluriels et les noms qu''on ne compte pas.', '[{"text": "Do you have any money?", "translation": "As-tu de l''argent ?"}, {"text": "There isn''t any coffee in the kitchen.", "translation": "Il n''y a pas de café dans la cuisine."}]'::jsonb, '/ˈeni/', '{"id": "en.d.any", "word": "any", "translation": "du, de la, des (négation, question)", "otherTranslations": ["aucun"], "partOfSpeech": "determiner", "ipa": "/ˈeni/", "explanation": "Any s''utilise à la place de some dans les phrases négatives et dans les questions simples, avec les pluriels et les noms qu''on ne compte pas.", "examples": [{"text": "Do you have any money?", "translation": "As-tu de l''argent ?"}, {"text": "There isn''t any coffee in the kitchen.", "translation": "Il n''y a pas de café dans la cuisine."}], "confusions": [{"word": "some", "note": "some s''utilise dans les phrases affirmatives et les demandes polies (Can I have some… ?)."}], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.much', 'en', 'much', 'beaucoup (de), combien (de)', 'Much s''utilise devant un nom qu''on ne compte pas, surtout dans les questions (how much) et les négations ; en phrase affirmative, on préfère a lot of.', '[{"text": "How much is the ticket?", "translation": "Combien coûte le billet ?"}, {"text": "I don''t have much money.", "translation": "Je n''ai pas beaucoup d''argent."}]'::jsonb, '/mʌtʃ/', '{"id": "en.d.much", "word": "much", "translation": "beaucoup (de), combien (de)", "otherTranslations": [], "partOfSpeech": "determiner", "ipa": "/mʌtʃ/", "explanation": "Much s''utilise devant un nom qu''on ne compte pas, surtout dans les questions (how much) et les négations ; en phrase affirmative, on préfère a lot of.", "examples": [{"text": "How much is the ticket?", "translation": "Combien coûte le billet ?"}, {"text": "I don''t have much money.", "translation": "Je n''ai pas beaucoup d''argent."}], "confusions": [{"word": "many", "note": "many s''utilise avec un pluriel qu''on peut compter ; much avec un nom qu''on ne compte pas."}], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.many', 'en', 'many', 'beaucoup de, combien de', 'Many s''utilise devant un nom pluriel qu''on peut compter, surtout dans les questions (how many) et les négations ; en phrase affirmative, on préfère a lot of.', '[{"text": "How many bags do you have?", "translation": "Combien de sacs as-tu ?"}, {"text": "There aren''t many shops here.", "translation": "Il n''y a pas beaucoup de magasins ici."}]'::jsonb, '/ˈmeni/', '{"id": "en.d.many", "word": "many", "translation": "beaucoup de, combien de", "otherTranslations": [], "partOfSpeech": "determiner", "ipa": "/ˈmeni/", "explanation": "Many s''utilise devant un nom pluriel qu''on peut compter, surtout dans les questions (how many) et les négations ; en phrase affirmative, on préfère a lot of.", "examples": [{"text": "How many bags do you have?", "translation": "Combien de sacs as-tu ?"}, {"text": "There aren''t many shops here.", "translation": "Il n''y a pas beaucoup de magasins ici."}], "confusions": [{"word": "much", "note": "much s''utilise avec un nom qu''on ne compte pas (money, luggage) ; many avec un pluriel."}], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.a_lot_of', 'en', 'a lot of', 'beaucoup de', 'A lot of veut dire « beaucoup de » : il s''utilise avec un pluriel (a lot of books) comme avec un nom qu''on ne compte pas (a lot of money), surtout dans les phrases affirmatives.', '[{"text": "Anna has a lot of books.", "translation": "Anna a beaucoup de livres."}, {"text": "We have a lot of friends.", "translation": "Nous avons beaucoup d''amis."}]'::jsonb, '/ə ˈlɒt əv/', '{"id": "en.d.a_lot_of", "word": "a lot of", "translation": "beaucoup de", "otherTranslations": [], "partOfSpeech": "determiner", "ipa": "/ə ˈlɒt əv/", "explanation": "A lot of veut dire « beaucoup de » : il s''utilise avec un pluriel (a lot of books) comme avec un nom qu''on ne compte pas (a lot of money), surtout dans les phrases affirmatives.", "examples": [{"text": "Anna has a lot of books.", "translation": "Anna a beaucoup de livres."}, {"text": "We have a lot of friends.", "translation": "Nous avons beaucoup d''amis."}], "confusions": [{"word": "lots of", "note": "lots of a le même sens, en plus familier."}], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.oclock', 'en', 'o''clock', 'heures (heure pile)', 'O''clock s''utilise après un nombre pour dire l''heure pile (It''s seven o''clock) ; il ne s''emploie pas avec les minutes (pas de « ten past six o''clock »).', '[{"text": "It''s seven o''clock.", "translation": "Il est sept heures."}, {"text": "The shop opens at nine o''clock.", "translation": "Le magasin ouvre à neuf heures."}]'::jsonb, '/əˈklɒk/', '{"id": "en.d.oclock", "word": "o''clock", "translation": "heures (heure pile)", "otherTranslations": [], "partOfSpeech": "adverb", "ipa": "/əˈklɒk/", "explanation": "O''clock s''utilise après un nombre pour dire l''heure pile (It''s seven o''clock) ; il ne s''emploie pas avec les minutes (pas de « ten past six o''clock »).", "examples": [{"text": "It''s seven o''clock.", "translation": "Il est sept heures."}, {"text": "The shop opens at nine o''clock.", "translation": "Le magasin ouvre à neuf heures."}], "confusions": [{"word": "hour", "note": "hour est une durée (an hour) ; on ne dit pas « seven hours » pour l''heure qu''il est."}], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.quarter', 'en', 'quarter', 'quart', 'Quarter est un quart : avec l''heure, quarter past eight veut dire huit heures et quart, et quarter to nine veut dire neuf heures moins le quart.', '[{"text": "It''s quarter past eight.", "translation": "Il est huit heures et quart."}, {"text": "The meeting is at quarter to nine.", "translation": "La réunion est à neuf heures moins le quart."}]'::jsonb, '/ˈkwɔːtə/', '{"id": "en.d.quarter", "word": "quarter", "translation": "quart", "otherTranslations": [], "partOfSpeech": "noun", "ipa": "/ˈkwɔːtə/", "explanation": "Quarter est un quart : avec l''heure, quarter past eight veut dire huit heures et quart, et quarter to nine veut dire neuf heures moins le quart.", "examples": [{"text": "It''s quarter past eight.", "translation": "Il est huit heures et quart."}, {"text": "The meeting is at quarter to nine.", "translation": "La réunion est à neuf heures moins le quart."}], "confusions": [{"word": "neighbourhood", "note": "un quartier d''une ville se dit neighbourhood, pas quarter."}], "forms": {}, "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.big', 'en', 'big', 'grand, gros', 'Adjectif qui décrit la taille ou l''importance de quelque chose. Il se place avant le nom et ne change jamais.', '[{"text": "We have a big apartment.", "translation": "Nous avons un grand appartement."}, {"text": "Tom has a big dog.", "translation": "Tom a un gros chien."}]'::jsonb, '/bɪɡ/', '{"id": "en.d.big", "word": "big", "translation": "grand, gros", "otherTranslations": ["important"], "partOfSpeech": "adjective", "ipa": "/bɪɡ/", "explanation": "Adjectif qui décrit la taille ou l''importance de quelque chose. Il se place avant le nom et ne change jamais.", "examples": [{"text": "We have a big apartment.", "translation": "Nous avons un grand appartement."}, {"text": "Tom has a big dog.", "translation": "Tom a un gros chien."}], "confusions": [{"word": "tall", "note": "Pour la taille d''une personne, on dit tall, pas big."}], "forms": {"comparative": "bigger", "superlative": "biggest"}, "unitId": "en.v.big"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.small', 'en', 'small', 'petit', 'Adjectif qui décrit une chose de petite taille. C''est le contraire de big.', '[{"text": "I live in a small house.", "translation": "J''habite dans une petite maison."}, {"text": "It is a small problem.", "translation": "C''est un petit problème."}]'::jsonb, '/smɔːl/', '{"id": "en.d.small", "word": "small", "translation": "petit", "partOfSpeech": "adjective", "ipa": "/smɔːl/", "explanation": "Adjectif qui décrit une chose de petite taille. C''est le contraire de big.", "examples": [{"text": "I live in a small house.", "translation": "J''habite dans une petite maison."}, {"text": "It is a small problem.", "translation": "C''est un petit problème."}], "confusions": [{"word": "short", "note": "Short veut dire « petit » pour la taille d''une personne, ou « court ». Small décrit une chose petite en volume."}], "forms": {"comparative": "smaller", "superlative": "smallest"}, "unitId": "en.v.small"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.new', 'en', 'new', 'nouveau, neuf', 'Adjectif pour une chose qui vient d''arriver ou qui n''est pas encore utilisée. C''est le contraire de old.', '[{"text": "I have a new phone.", "translation": "J''ai un téléphone neuf."}, {"text": "Anna has a new job.", "translation": "Anna a un nouveau travail."}]'::jsonb, '/njuː/', '{"id": "en.d.new", "word": "new", "translation": "nouveau, neuf", "partOfSpeech": "adjective", "ipa": "/njuː/", "explanation": "Adjectif pour une chose qui vient d''arriver ou qui n''est pas encore utilisée. C''est le contraire de old.", "examples": [{"text": "I have a new phone.", "translation": "J''ai un téléphone neuf."}, {"text": "Anna has a new job.", "translation": "Anna a un nouveau travail."}], "confusions": [{"word": "news", "note": "News (/njuːz/) est un nom qui veut dire « les nouvelles, l''actualité » : ce n''est pas l''adjectif new."}], "forms": {"comparative": "newer", "superlative": "newest"}, "unitId": "en.v.new"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.old', 'en', 'old', 'vieux, ancien, âgé', 'Adjectif pour une chose ou une personne qui existe depuis longtemps. On l''utilise aussi pour l''âge : How old are you ?', '[{"text": "This is an old book.", "translation": "C''est un vieux livre."}, {"text": "How old is your brother?", "translation": "Quel âge a ton frère ?"}]'::jsonb, '/əʊld/', '{"id": "en.d.old", "word": "old", "translation": "vieux, ancien, âgé", "partOfSpeech": "adjective", "ipa": "/əʊld/", "explanation": "Adjectif pour une chose ou une personne qui existe depuis longtemps. On l''utilise aussi pour l''âge : How old are you ?", "examples": [{"text": "This is an old book.", "translation": "C''est un vieux livre."}, {"text": "How old is your brother?", "translation": "Quel âge a ton frère ?"}], "confusions": [], "forms": {"comparative": "older", "superlative": "oldest"}, "unitId": "en.v.old"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.beautiful', 'en', 'beautiful', 'beau, belle', 'Adjectif pour ce qui est très agréable à regarder : une ville, une plage, une femme, une maison. C''est un adjectif long : on dit more beautiful et the most beautiful.', '[{"text": "Paris is a beautiful city.", "translation": "Paris est une belle ville."}, {"text": "The beach is beautiful in summer.", "translation": "La plage est belle en été."}]'::jsonb, '/ˈbjuːtɪfl/', '{"id": "en.d.beautiful", "word": "beautiful", "translation": "beau, belle", "partOfSpeech": "adjective", "ipa": "/ˈbjuːtɪfl/", "explanation": "Adjectif pour ce qui est très agréable à regarder : une ville, une plage, une femme, une maison. C''est un adjectif long : on dit more beautiful et the most beautiful.", "examples": [{"text": "Paris is a beautiful city.", "translation": "Paris est une belle ville."}, {"text": "The beach is beautiful in summer.", "translation": "La plage est belle en été."}], "confusions": [{"word": "handsome", "note": "Pour un homme, on dit souvent handsome ou good-looking ; beautiful s''emploie plutôt pour une femme, un lieu ou un objet."}], "unitId": "en.v.beautiful"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.street', 'en', 'street', 'rue', 'Nom pour une rue dans une ville, avec des maisons ou des magasins des deux côtés.', '[{"text": "The shop is at the corner of the street.", "translation": "Le magasin est au coin de la rue."}, {"text": "Anna lives in a small street.", "translation": "Anna habite dans une petite rue."}]'::jsonb, '/striːt/', '{"id": "en.d.street", "word": "street", "translation": "rue", "partOfSpeech": "noun", "ipa": "/striːt/", "explanation": "Nom pour une rue dans une ville, avec des maisons ou des magasins des deux côtés.", "examples": [{"text": "The shop is at the corner of the street.", "translation": "Le magasin est au coin de la rue."}, {"text": "Anna lives in a small street.", "translation": "Anna habite dans une petite rue."}], "confusions": [{"word": "road", "note": "Road désigne une route ou une rue plus large ; street est une rue en ville avec des maisons."}], "forms": {"plural": "streets"}, "unitId": "en.v.street"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.park', 'en', 'park', 'parc', 'Nom pour un grand jardin public dans une ville. C''est aussi un verbe : park the car veut dire « garer la voiture ».', '[{"text": "The children play in the park.", "translation": "Les enfants jouent dans le parc."}, {"text": "I walk in the park on Sunday.", "translation": "Je me promène dans le parc le dimanche."}]'::jsonb, '/pɑːk/', '{"id": "en.d.park", "word": "park", "translation": "parc", "otherTranslations": ["garer (verbe)"], "partOfSpeech": "noun", "ipa": "/pɑːk/", "explanation": "Nom pour un grand jardin public dans une ville. C''est aussi un verbe : park the car veut dire « garer la voiture ».", "examples": [{"text": "The children play in the park.", "translation": "Les enfants jouent dans le parc."}, {"text": "I walk in the park on Sunday.", "translation": "Je me promène dans le parc le dimanche."}], "confusions": [], "forms": {"plural": "parks"}, "unitId": "en.v.park"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.building', 'en', 'building', 'bâtiment, immeuble', 'Nom pour une construction avec des murs et un toit : une maison, un bureau, une école ou un immeuble.', '[{"text": "My office is in a new building.", "translation": "Mon bureau est dans un nouveau bâtiment."}, {"text": "The school is a beautiful old building.", "translation": "L''école est un beau vieux bâtiment."}]'::jsonb, '/ˈbɪldɪŋ/', '{"id": "en.d.building", "word": "building", "translation": "bâtiment, immeuble", "partOfSpeech": "noun", "ipa": "/ˈbɪldɪŋ/", "explanation": "Nom pour une construction avec des murs et un toit : une maison, un bureau, une école ou un immeuble.", "examples": [{"text": "My office is in a new building.", "translation": "Mon bureau est dans un nouveau bâtiment."}, {"text": "The school is a beautiful old building.", "translation": "L''école est un beau vieux bâtiment."}], "confusions": [], "forms": {"plural": "buildings"}, "unitId": "en.v.building"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.floor', 'en', 'floor', 'étage ; sol', 'Nom qui désigne soit le sol d''une pièce, soit un étage d''un bâtiment. Avec un étage, on dit on : on the second floor.', '[{"text": "My apartment is on the second floor.", "translation": "Mon appartement est au deuxième étage."}, {"text": "The dog sleeps on the floor.", "translation": "Le chien dort par terre."}]'::jsonb, '/flɔː/', '{"id": "en.d.floor", "word": "floor", "translation": "étage ; sol", "otherTranslations": ["sol", "plancher"], "partOfSpeech": "noun", "ipa": "/flɔː/", "explanation": "Nom qui désigne soit le sol d''une pièce, soit un étage d''un bâtiment. Avec un étage, on dit on : on the second floor.", "examples": [{"text": "My apartment is on the second floor.", "translation": "Mon appartement est au deuxième étage."}, {"text": "The dog sleeps on the floor.", "translation": "Le chien dort par terre."}], "confusions": [{"word": "ground floor", "note": "Rez-de-chaussée en anglais britannique. En anglais américain, on dit first floor."}], "forms": {"plural": "floors"}, "unitId": "en.v.floor"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.corner', 'en', 'corner', 'coin', 'Nom pour l''endroit où deux murs ou deux rues se rencontrent. On dit in the corner pour l''intérieur d''une pièce et at the corner of the street pour une rue.', '[{"text": "The dog is in the corner.", "translation": "Le chien est dans le coin."}, {"text": "The station is at the corner of the street.", "translation": "La gare est au coin de la rue."}]'::jsonb, '/ˈkɔːnə/', '{"id": "en.d.corner", "word": "corner", "translation": "coin", "partOfSpeech": "noun", "ipa": "/ˈkɔːnə/", "explanation": "Nom pour l''endroit où deux murs ou deux rues se rencontrent. On dit in the corner pour l''intérieur d''une pièce et at the corner of the street pour une rue.", "examples": [{"text": "The dog is in the corner.", "translation": "Le chien est dans le coin."}, {"text": "The station is at the corner of the street.", "translation": "La gare est au coin de la rue."}], "confusions": [], "forms": {"plural": "corners"}, "unitId": "en.v.corner"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.monday', 'en', 'Monday', 'lundi', 'Nom pour le jour qui suit le dimanche, au début de la semaine de travail. Les jours prennent toujours une majuscule en anglais, et on dit on Monday pour « le lundi ».', '[{"text": "I work on Monday.", "translation": "Je travaille le lundi."}, {"text": "Monday is a busy day.", "translation": "Le lundi est un jour chargé."}]'::jsonb, '/ˈmʌndeɪ/', '{"id": "en.d.monday", "word": "Monday", "translation": "lundi", "partOfSpeech": "noun", "ipa": "/ˈmʌndeɪ/", "explanation": "Nom pour le jour qui suit le dimanche, au début de la semaine de travail. Les jours prennent toujours une majuscule en anglais, et on dit on Monday pour « le lundi ».", "examples": [{"text": "I work on Monday.", "translation": "Je travaille le lundi."}, {"text": "Monday is a busy day.", "translation": "Le lundi est un jour chargé."}], "confusions": [], "forms": {"plural": "Mondays"}, "unitId": "en.v.monday"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.sunday', 'en', 'Sunday', 'dimanche', 'Nom pour le jour qui suit samedi, en général un jour de repos. Il prend une majuscule, et on dit on Sunday pour « le dimanche ».', '[{"text": "We eat lunch at home on Sunday.", "translation": "Nous déjeunons à la maison le dimanche."}, {"text": "My birthday is on Sunday.", "translation": "Mon anniversaire est dimanche."}]'::jsonb, '/ˈsʌndeɪ/', '{"id": "en.d.sunday", "word": "Sunday", "translation": "dimanche", "partOfSpeech": "noun", "ipa": "/ˈsʌndeɪ/", "explanation": "Nom pour le jour qui suit samedi, en général un jour de repos. Il prend une majuscule, et on dit on Sunday pour « le dimanche ».", "examples": [{"text": "We eat lunch at home on Sunday.", "translation": "Nous déjeunons à la maison le dimanche."}, {"text": "My birthday is on Sunday.", "translation": "Mon anniversaire est dimanche."}], "confusions": [{"word": "son", "note": "Son (fils) se prononce presque pareil, mais ne s''écrit pas pareil : /sʌn/ et /ˈsʌndeɪ/."}], "forms": {"plural": "Sundays"}, "unitId": "en.v.sunday"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.january', 'en', 'January', 'janvier', 'Nom pour le premier mois de l''année. Les mois prennent toujours une majuscule, et on dit in January pour « en janvier ».', '[{"text": "It is cold in January.", "translation": "Il fait froid en janvier."}, {"text": "My birthday is on 5 January.", "translation": "Mon anniversaire est le 5 janvier."}]'::jsonb, '/ˈdʒænjuəri/', '{"id": "en.d.january", "word": "January", "translation": "janvier", "partOfSpeech": "noun", "ipa": "/ˈdʒænjuəri/", "explanation": "Nom pour le premier mois de l''année. Les mois prennent toujours une majuscule, et on dit in January pour « en janvier ».", "examples": [{"text": "It is cold in January.", "translation": "Il fait froid en janvier."}, {"text": "My birthday is on 5 January.", "translation": "Mon anniversaire est le 5 janvier."}], "confusions": [], "unitId": "en.v.january"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.summer', 'en', 'summer', 'été', 'Nom pour la saison la plus chaude de l''année. Les saisons s''écrivent sans majuscule, et on dit in summer ou in the summer.', '[{"text": "We go to the beach in summer.", "translation": "Nous allons à la plage en été."}, {"text": "We have a holiday in summer.", "translation": "Nous avons des vacances en été."}]'::jsonb, '/ˈsʌmə/', '{"id": "en.d.summer", "word": "summer", "translation": "été", "partOfSpeech": "noun", "ipa": "/ˈsʌmə/", "explanation": "Nom pour la saison la plus chaude de l''année. Les saisons s''écrivent sans majuscule, et on dit in summer ou in the summer.", "examples": [{"text": "We go to the beach in summer.", "translation": "Nous allons à la plage en été."}, {"text": "We have a holiday in summer.", "translation": "Nous avons des vacances en été."}], "confusions": [], "forms": {"plural": "summers"}, "unitId": "en.v.summer"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.winter', 'en', 'winter', 'hiver', 'Nom pour la saison la plus froide de l''année. On dit in winter ou in the winter, sans majuscule.', '[{"text": "It is cold in winter.", "translation": "Il fait froid en hiver."}, {"text": "I stay at home in winter.", "translation": "Je reste à la maison en hiver."}]'::jsonb, '/ˈwɪntə/', '{"id": "en.d.winter", "word": "winter", "translation": "hiver", "partOfSpeech": "noun", "ipa": "/ˈwɪntə/", "explanation": "Nom pour la saison la plus froide de l''année. On dit in winter ou in the winter, sans majuscule.", "examples": [{"text": "It is cold in winter.", "translation": "Il fait froid en hiver."}, {"text": "I stay at home in winter.", "translation": "Je reste à la maison en hiver."}], "confusions": [], "forms": {"plural": "winters"}, "unitId": "en.v.winter"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.time', 'en', 'time', 'temps ; heure ; fois', 'Nom très courant : il veut dire « l''heure » (What time is it ?), « le temps qui passe » ou « la fois » (two times). Pour parler de la météo, on ne dit pas time.', '[{"text": "What time is it?", "translation": "Quelle heure est-il ?"}, {"text": "I don''t have time today.", "translation": "Je n''ai pas le temps aujourd''hui."}]'::jsonb, '/taɪm/', '{"id": "en.d.time", "word": "time", "translation": "temps ; heure ; fois", "otherTranslations": ["heure", "fois"], "partOfSpeech": "noun", "ipa": "/taɪm/", "explanation": "Nom très courant : il veut dire « l''heure » (What time is it ?), « le temps qui passe » ou « la fois » (two times). Pour parler de la météo, on ne dit pas time.", "examples": [{"text": "What time is it?", "translation": "Quelle heure est-il ?"}, {"text": "I don''t have time today.", "translation": "Je n''ai pas le temps aujourd''hui."}], "confusions": [{"word": "hour", "note": "Hour est une durée de 60 minutes ; time est l''heure qu''il est ou le temps en général."}, {"word": "weather", "note": "Le temps qu''il fait (la météo) se dit weather, pas time."}], "forms": {"plural": "times"}, "unitId": "en.v.time"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.place', 'en', 'place', 'endroit, lieu', 'Nom général pour un endroit : une ville, un parc, un restaurant. C''est aussi un verbe qui veut dire « placer, mettre ».', '[{"text": "The park is a nice place for children.", "translation": "Le parc est un bel endroit pour les enfants."}, {"text": "Where is the best place to eat?", "translation": "Où est le meilleur endroit pour manger ?"}]'::jsonb, '/pleɪs/', '{"id": "en.d.place", "word": "place", "translation": "endroit, lieu", "partOfSpeech": "noun", "ipa": "/pleɪs/", "explanation": "Nom général pour un endroit : une ville, un parc, un restaurant. C''est aussi un verbe qui veut dire « placer, mettre ».", "examples": [{"text": "The park is a nice place for children.", "translation": "Le parc est un bel endroit pour les enfants."}, {"text": "Where is the best place to eat?", "translation": "Où est le meilleur endroit pour manger ?"}], "confusions": [], "forms": {"plural": "places"}, "unitId": "en.v.place"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.reason', 'en', 'reason', 'raison', 'Nom pour expliquer pourquoi quelque chose arrive. On pose la question avec why et on répond avec because. Attention : « avoir raison » se dit be right.', '[{"text": "What is the reason?", "translation": "Quelle est la raison ?"}, {"text": "Tom is late, but he has a good reason.", "translation": "Tom est en retard, mais il a une bonne raison."}]'::jsonb, '/ˈriːzn/', '{"id": "en.d.reason", "word": "reason", "translation": "raison", "partOfSpeech": "noun", "ipa": "/ˈriːzn/", "explanation": "Nom pour expliquer pourquoi quelque chose arrive. On pose la question avec why et on répond avec because. Attention : « avoir raison » se dit be right.", "examples": [{"text": "What is the reason?", "translation": "Quelle est la raison ?"}, {"text": "Tom is late, but he has a good reason.", "translation": "Tom est en retard, mais il a une bonne raison."}], "confusions": [{"word": "right", "note": "« Avoir raison » se dit be right (You are right), pas have reason."}], "forms": {"plural": "reasons"}, "unitId": "en.v.reason"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.address', 'en', 'address', 'adresse', 'Nom pour l''endroit où quelqu''un habite ou travaille, avec le numéro et la rue. Il s''écrit avec deux d et deux s.', '[{"text": "What is your address?", "translation": "Quelle est ton adresse ?"}, {"text": "My address is 10 Park Street.", "translation": "Mon adresse est 10 Park Street."}]'::jsonb, '/əˈdres/', '{"id": "en.d.address", "word": "address", "translation": "adresse", "partOfSpeech": "noun", "ipa": "/əˈdres/", "explanation": "Nom pour l''endroit où quelqu''un habite ou travaille, avec le numéro et la rue. Il s''écrit avec deux d et deux s.", "examples": [{"text": "What is your address?", "translation": "Quelle est ton adresse ?"}, {"text": "My address is 10 Park Street.", "translation": "Mon adresse est 10 Park Street."}], "confusions": [], "forms": {"plural": "addresses"}, "unitId": "en.v.address"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.age', 'en', 'age', 'âge', 'Nom pour le nombre d''années d''une personne. Pour demander l''âge, on dit plutôt How old are you ? ; on dit I am twenty (pas I have twenty).', '[{"text": "Ben and Anna are the same age.", "translation": "Ben et Anna ont le même âge."}, {"text": "What is your age?", "translation": "Quel est ton âge ?"}]'::jsonb, '/eɪdʒ/', '{"id": "en.d.age", "word": "age", "translation": "âge", "partOfSpeech": "noun", "ipa": "/eɪdʒ/", "explanation": "Nom pour le nombre d''années d''une personne. Pour demander l''âge, on dit plutôt How old are you ? ; on dit I am twenty (pas I have twenty).", "examples": [{"text": "Ben and Anna are the same age.", "translation": "Ben et Anna ont le même âge."}, {"text": "What is your age?", "translation": "Quel est ton âge ?"}], "confusions": [{"word": "old", "note": "Pour dire son âge, on utilise be + nombre : I am twenty. On ne dit jamais I have twenty."}], "forms": {"plural": "ages"}, "unitId": "en.v.age"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.sun', 'en', 'sun', 'soleil', 'Nom pour l''étoile qui nous éclaire et nous chauffe. On l''utilise avec the : the sun.', '[{"text": "The sun is hot today.", "translation": "Le soleil est chaud aujourd''hui."}, {"text": "I sit in the sun.", "translation": "Je m''assois au soleil."}]'::jsonb, '/sʌn/', '{"id": "en.d.sun", "word": "sun", "translation": "soleil", "partOfSpeech": "noun", "ipa": "/sʌn/", "explanation": "Nom pour l''étoile qui nous éclaire et nous chauffe. On l''utilise avec the : the sun.", "examples": [{"text": "The sun is hot today.", "translation": "Le soleil est chaud aujourd''hui."}, {"text": "I sit in the sun.", "translation": "Je m''assois au soleil."}], "confusions": [{"word": "son", "note": "Son se prononce exactement pareil (/sʌn/) mais veut dire « fils »."}], "unitId": "en.v.sun"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.hot', 'en', 'hot', 'chaud (très)', 'Adjectif pour ce qui a une température très élevée : le temps, le café, le soleil. Pour une personne, on dit I am hot (jamais I have hot).', '[{"text": "The coffee is very hot.", "translation": "Le café est très chaud."}, {"text": "It is hot in summer.", "translation": "Il fait chaud en été."}]'::jsonb, '/hɒt/', '{"id": "en.d.hot", "word": "hot", "translation": "chaud (très)", "partOfSpeech": "adjective", "ipa": "/hɒt/", "explanation": "Adjectif pour ce qui a une température très élevée : le temps, le café, le soleil. Pour une personne, on dit I am hot (jamais I have hot).", "examples": [{"text": "The coffee is very hot.", "translation": "Le café est très chaud."}, {"text": "It is hot in summer.", "translation": "Il fait chaud en été."}], "confusions": [{"word": "warm", "note": "Hot veut dire très chaud ; warm veut dire agréablement chaud, doux."}], "forms": {"comparative": "hotter", "superlative": "hottest"}, "unitId": "en.v.hot"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.warm', 'en', 'warm', 'doux, chaud (agréablement)', 'Adjectif pour une chaleur agréable, qui n''est pas trop forte. C''est entre cold et hot.', '[{"text": "The water is warm.", "translation": "L''eau est agréablement chaude."}, {"text": "I like warm weather.", "translation": "J''aime le temps doux."}]'::jsonb, '/wɔːm/', '{"id": "en.d.warm", "word": "warm", "translation": "doux, chaud (agréablement)", "partOfSpeech": "adjective", "ipa": "/wɔːm/", "explanation": "Adjectif pour une chaleur agréable, qui n''est pas trop forte. C''est entre cold et hot.", "examples": [{"text": "The water is warm.", "translation": "L''eau est agréablement chaude."}, {"text": "I like warm weather.", "translation": "J''aime le temps doux."}], "confusions": [{"word": "hot", "note": "Warm est agréable ; hot est très chaud, parfois trop chaud."}], "forms": {"comparative": "warmer", "superlative": "warmest"}, "unitId": "en.v.warm"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.wind', 'en', 'wind', 'vent', 'Nom pour l''air qui se déplace dehors. On dit there is wind ou it is windy pour « il y a du vent ».', '[{"text": "The wind is cold in winter.", "translation": "Le vent est froid en hiver."}, {"text": "There is no wind today.", "translation": "Il n''y a pas de vent aujourd''hui."}]'::jsonb, '/wɪnd/', '{"id": "en.d.wind", "word": "wind", "translation": "vent", "partOfSpeech": "noun", "ipa": "/wɪnd/", "explanation": "Nom pour l''air qui se déplace dehors. On dit there is wind ou it is windy pour « il y a du vent ».", "examples": [{"text": "The wind is cold in winter.", "translation": "Le vent est froid en hiver."}, {"text": "There is no wind today.", "translation": "Il n''y a pas de vent aujourd''hui."}], "confusions": [], "unitId": "en.v.wind"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.snow', 'en', 'snow', 'neige ; neiger', 'Nom pour la neige. Snow est aussi un verbe : it snows (ou it is snowing) veut dire « il neige ».', '[{"text": "There is snow in the park.", "translation": "Il y a de la neige dans le parc."}, {"text": "It snows in January.", "translation": "Il neige en janvier."}]'::jsonb, '/snəʊ/', '{"id": "en.d.snow", "word": "snow", "translation": "neige ; neiger", "partOfSpeech": "noun", "ipa": "/snəʊ/", "explanation": "Nom pour la neige. Snow est aussi un verbe : it snows (ou it is snowing) veut dire « il neige ».", "examples": [{"text": "There is snow in the park.", "translation": "Il y a de la neige dans le parc."}, {"text": "It snows in January.", "translation": "Il neige en janvier."}], "confusions": [], "forms": {"thirdPerson": "snows", "past": "snowed", "pastParticiple": "snowed", "ing": "snowing"}, "unitId": "en.v.snow"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.fast', 'en', 'fast', 'rapide, vite', 'Adjectif pour ce qui va à grande vitesse. C''est aussi un adverbe (vite) : il garde la même forme, on dit drive fast.', '[{"text": "My new car is very fast.", "translation": "Ma nouvelle voiture est très rapide."}, {"text": "Tom drives fast.", "translation": "Tom conduit vite."}]'::jsonb, '/fɑːst/', '{"id": "en.d.fast", "word": "fast", "translation": "rapide, vite", "partOfSpeech": "adjective", "ipa": "/fɑːst/", "explanation": "Adjectif pour ce qui va à grande vitesse. C''est aussi un adverbe (vite) : il garde la même forme, on dit drive fast.", "examples": [{"text": "My new car is very fast.", "translation": "Ma nouvelle voiture est très rapide."}, {"text": "Tom drives fast.", "translation": "Tom conduit vite."}], "confusions": [{"word": "quick", "note": "Quick veut dire « rapide, bref » pour une action courte (a quick call) ; fast parle de vitesse."}], "forms": {"comparative": "faster", "superlative": "fastest"}, "unitId": "en.v.fast"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.slow', 'en', 'slow', 'lent', 'Adjectif pour ce qui ne va pas vite. C''est le contraire de fast.', '[{"text": "My laptop is very slow.", "translation": "Mon ordinateur portable est très lent."}, {"text": "The old car is slow.", "translation": "La vieille voiture est lente."}]'::jsonb, '/sləʊ/', '{"id": "en.d.slow", "word": "slow", "translation": "lent", "partOfSpeech": "adjective", "ipa": "/sləʊ/", "explanation": "Adjectif pour ce qui ne va pas vite. C''est le contraire de fast.", "examples": [{"text": "My laptop is very slow.", "translation": "Mon ordinateur portable est très lent."}, {"text": "The old car is slow.", "translation": "La vieille voiture est lente."}], "confusions": [{"word": "slowly", "note": "Slowly est l''adverbe (lentement) : speak slowly. Slow est l''adjectif : a slow car."}], "forms": {"comparative": "slower", "superlative": "slowest"}, "unitId": "en.v.slow"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.tall', 'en', 'tall', 'grand (taille)', 'Adjectif pour la grande taille d''une personne, d''un arbre ou d''un bâtiment. On ne dit pas big pour la taille d''une personne.', '[{"text": "My brother is very tall.", "translation": "Mon frère est très grand."}, {"text": "She is taller than her mother.", "translation": "Elle est plus grande que sa mère."}]'::jsonb, '/tɔːl/', '{"id": "en.d.tall", "word": "tall", "translation": "grand (taille)", "partOfSpeech": "adjective", "ipa": "/tɔːl/", "explanation": "Adjectif pour la grande taille d''une personne, d''un arbre ou d''un bâtiment. On ne dit pas big pour la taille d''une personne.", "examples": [{"text": "My brother is very tall.", "translation": "Mon frère est très grand."}, {"text": "She is taller than her mother.", "translation": "Elle est plus grande que sa mère."}], "confusions": [{"word": "big", "note": "Big veut dire gros ou grand en volume ; pour la taille d''une personne, on dit tall."}], "forms": {"comparative": "taller", "superlative": "tallest"}, "unitId": "en.v.tall"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.short', 'en', 'short', 'court, petit (taille)', 'Adjectif pour ce qui a peu de longueur ou de hauteur : une histoire courte, une personne petite. C''est le contraire de tall ou de long.', '[{"text": "Anna is shorter than Tom.", "translation": "Anna est plus petite que Tom."}, {"text": "It is a short story.", "translation": "C''est une histoire courte."}]'::jsonb, '/ʃɔːt/', '{"id": "en.d.short", "word": "short", "translation": "court, petit (taille)", "partOfSpeech": "adjective", "ipa": "/ʃɔːt/", "explanation": "Adjectif pour ce qui a peu de longueur ou de hauteur : une histoire courte, une personne petite. C''est le contraire de tall ou de long.", "examples": [{"text": "Anna is shorter than Tom.", "translation": "Anna est plus petite que Tom."}, {"text": "It is a short story.", "translation": "C''est une histoire courte."}], "confusions": [{"word": "small", "note": "Pour la taille d''une personne, on dit short. Small s''emploie pour un objet ou un lieu petit."}], "forms": {"comparative": "shorter", "superlative": "shortest"}, "unitId": "en.v.short"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.easy', 'en', 'easy', 'facile', 'Adjectif pour ce qui ne demande pas d''effort. C''est le contraire de difficult. Le y devient i : easier, the easiest.', '[{"text": "The homework is easy today.", "translation": "Les devoirs sont faciles aujourd''hui."}, {"text": "It is easy to learn English.", "translation": "C''est facile d''apprendre l''anglais."}]'::jsonb, '/ˈiːzi/', '{"id": "en.d.easy", "word": "easy", "translation": "facile", "partOfSpeech": "adjective", "ipa": "/ˈiːzi/", "explanation": "Adjectif pour ce qui ne demande pas d''effort. C''est le contraire de difficult. Le y devient i : easier, the easiest.", "examples": [{"text": "The homework is easy today.", "translation": "Les devoirs sont faciles aujourd''hui."}, {"text": "It is easy to learn English.", "translation": "C''est facile d''apprendre l''anglais."}], "confusions": [], "forms": {"comparative": "easier", "superlative": "easiest"}, "unitId": "en.v.easy"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.advice', 'en', 'advice', 'conseil(s)', 'Nom indénombrable : il n''a pas de pluriel et on ne dit pas an advice. Pour « un conseil », on dit some advice ou a piece of advice.', '[{"text": "My doctor gives me good advice.", "translation": "Mon docteur me donne de bons conseils."}, {"text": "I need some advice.", "translation": "J''ai besoin d''un conseil."}]'::jsonb, '/ədˈvaɪs/', '{"id": "en.d.advice", "word": "advice", "translation": "conseil(s)", "partOfSpeech": "noun", "ipa": "/ədˈvaɪs/", "explanation": "Nom indénombrable : il n''a pas de pluriel et on ne dit pas an advice. Pour « un conseil », on dit some advice ou a piece of advice.", "examples": [{"text": "My doctor gives me good advice.", "translation": "Mon docteur me donne de bons conseils."}, {"text": "I need some advice.", "translation": "J''ai besoin d''un conseil."}], "confusions": [{"word": "advise", "note": "Advise (/ədˈvaɪz/, avec un z) est le verbe « conseiller » ; advice (avec un s) est le nom."}], "unitId": "en.v.advice"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.rest', 'en', 'rest', 'se reposer ; repos', 'Verbe pour arrêter de travailler et récupérer. En anglais, « se reposer » se dit rest, sans pronom. C''est aussi un nom : I need a rest.', '[{"text": "You should rest today.", "translation": "Tu devrais te reposer aujourd''hui."}, {"text": "I need a rest.", "translation": "J''ai besoin de repos."}]'::jsonb, '/rest/', '{"id": "en.d.rest", "word": "rest", "translation": "se reposer ; repos", "otherTranslations": ["repos (nom)"], "partOfSpeech": "verb", "ipa": "/rest/", "explanation": "Verbe pour arrêter de travailler et récupérer. En anglais, « se reposer » se dit rest, sans pronom. C''est aussi un nom : I need a rest.", "examples": [{"text": "You should rest today.", "translation": "Tu devrais te reposer aujourd''hui."}, {"text": "I need a rest.", "translation": "J''ai besoin de repos."}], "confusions": [{"word": "the rest", "note": "The rest veut dire aussi « le reste » : the rest of the food."}], "forms": {"thirdPerson": "rests", "past": "rested", "pastParticiple": "rested", "ing": "resting"}, "unitId": "en.v.rest"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.ill', 'en', 'ill', 'malade', 'Adjectif pour quelqu''un qui n''est pas en bonne santé. On l''utilise surtout après be : She is ill.', '[{"text": "Tom is ill today.", "translation": "Tom est malade aujourd''hui."}, {"text": "She is ill, so she stays at home.", "translation": "Elle est malade, donc elle reste à la maison."}]'::jsonb, '/ɪl/', '{"id": "en.d.ill", "word": "ill", "translation": "malade", "partOfSpeech": "adjective", "ipa": "/ɪl/", "explanation": "Adjectif pour quelqu''un qui n''est pas en bonne santé. On l''utilise surtout après be : She is ill.", "examples": [{"text": "Tom is ill today.", "translation": "Tom est malade aujourd''hui."}, {"text": "She is ill, so she stays at home.", "translation": "Elle est malade, donc elle reste à la maison."}], "confusions": [{"word": "sick", "note": "Synonyme courant, surtout en anglais américain. En anglais britannique, be sick veut aussi dire « vomir »."}], "unitId": "en.v.ill"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.medicine', 'en', 'medicine', 'médicament', 'Nom pour ce qu''on prend pour aller mieux quand on est malade. Medicine veut aussi dire « la médecine » en général.', '[{"text": "Take your medicine, please.", "translation": "Prends ton médicament, s''il te plaît."}, {"text": "The medicine is on the table.", "translation": "Le médicament est sur la table."}]'::jsonb, '/ˈmedsn/', '{"id": "en.d.medicine", "word": "medicine", "translation": "médicament", "otherTranslations": ["médecine"], "partOfSpeech": "noun", "ipa": "/ˈmedsn/", "explanation": "Nom pour ce qu''on prend pour aller mieux quand on est malade. Medicine veut aussi dire « la médecine » en général.", "examples": [{"text": "Take your medicine, please.", "translation": "Prends ton médicament, s''il te plaît."}, {"text": "The medicine is on the table.", "translation": "Le médicament est sur la table."}], "confusions": [{"word": "doctor", "note": "Le médecin se dit doctor ; le médicament se dit medicine."}], "forms": {"plural": "medicines"}, "unitId": "en.v.medicine"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.exercise', 'en', 'exercise', 'faire de l''exercice ; exercice', 'Verbe pour faire du sport ou bouger pour rester en forme. C''est aussi un nom : an English exercise (un exercice).', '[{"text": "You should exercise every day.", "translation": "Tu devrais faire de l''exercice tous les jours."}, {"text": "The exercise is easy.", "translation": "L''exercice est facile."}]'::jsonb, '/ˈeksəsaɪz/', '{"id": "en.d.exercise", "word": "exercise", "translation": "faire de l''exercice ; exercice", "otherTranslations": ["exercice (nom)"], "partOfSpeech": "verb", "ipa": "/ˈeksəsaɪz/", "explanation": "Verbe pour faire du sport ou bouger pour rester en forme. C''est aussi un nom : an English exercise (un exercice).", "examples": [{"text": "You should exercise every day.", "translation": "Tu devrais faire de l''exercice tous les jours."}, {"text": "The exercise is easy.", "translation": "L''exercice est facile."}], "confusions": [{"word": "do", "note": "On peut aussi dire do exercise pour « faire de l''exercice »."}], "forms": {"thirdPerson": "exercises", "past": "exercised", "pastParticiple": "exercised", "ing": "exercising"}, "unitId": "en.v.exercise"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.would_like', 'en', 'would like', 'voudrais, aimerais', 'Expression polie pour demander ou proposer quelque chose. I would like (ou I''d like) veut dire « je voudrais », et Would you like...? veut dire « voulez-vous... ? ».', '[{"text": "I would like a glass of water.", "translation": "Je voudrais un verre d''eau."}, {"text": "Would you like a coffee?", "translation": "Voulez-vous un café ?"}]'::jsonb, '/wʊd laɪk/', '{"id": "en.d.would_like", "word": "would like", "translation": "voudrais, aimerais", "partOfSpeech": "expression", "ipa": "/wʊd laɪk/", "explanation": "Expression polie pour demander ou proposer quelque chose. I would like (ou I''d like) veut dire « je voudrais », et Would you like...? veut dire « voulez-vous... ? ».", "examples": [{"text": "I would like a glass of water.", "translation": "Je voudrais un verre d''eau."}, {"text": "Would you like a coffee?", "translation": "Voulez-vous un café ?"}], "confusions": [{"word": "like", "note": "Like tout seul veut dire « aimer » ; would like est une demande polie."}, {"word": "want", "note": "Want est direct (je veux) ; would like est plus poli (je voudrais)."}], "unitId": "en.v.would_like"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.glass', 'en', 'glass', 'verre', 'Nom pour le récipient dans lequel on boit de l''eau, du lait ou du jus. C''est aussi la matière « verre ».', '[{"text": "Could you bring me a glass of water?", "translation": "Pourriez-vous m''apporter un verre d''eau ?"}, {"text": "The glass is on the table.", "translation": "Le verre est sur la table."}]'::jsonb, '/ɡlɑːs/', '{"id": "en.d.glass", "word": "glass", "translation": "verre", "partOfSpeech": "noun", "ipa": "/ɡlɑːs/", "explanation": "Nom pour le récipient dans lequel on boit de l''eau, du lait ou du jus. C''est aussi la matière « verre ».", "examples": [{"text": "Could you bring me a glass of water?", "translation": "Pourriez-vous m''apporter un verre d''eau ?"}, {"text": "The glass is on the table.", "translation": "Le verre est sur la table."}], "confusions": [{"word": "glasses", "note": "Au pluriel, glasses veut dire aussi « des lunettes »."}], "forms": {"plural": "glasses"}, "unitId": "en.v.glass"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.cup', 'en', 'cup', 'tasse', 'Nom pour le petit récipient avec une anse, utilisé pour le café ou le thé.', '[{"text": "I drink a cup of coffee in the morning.", "translation": "Je bois une tasse de café le matin."}, {"text": "Would you like a cup of coffee?", "translation": "Voulez-vous une tasse de café ?"}]'::jsonb, '/kʌp/', '{"id": "en.d.cup", "word": "cup", "translation": "tasse", "partOfSpeech": "noun", "ipa": "/kʌp/", "explanation": "Nom pour le petit récipient avec une anse, utilisé pour le café ou le thé.", "examples": [{"text": "I drink a cup of coffee in the morning.", "translation": "Je bois une tasse de café le matin."}, {"text": "Would you like a cup of coffee?", "translation": "Voulez-vous une tasse de café ?"}], "confusions": [{"word": "glass", "note": "Cup est une tasse (boisson chaude) ; glass est un verre."}], "forms": {"plural": "cups"}, "unitId": "en.v.cup"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.dessert', 'en', 'dessert', 'dessert', 'Nom pour le plat sucré qu''on mange à la fin d''un repas. Il s''écrit avec deux s.', '[{"text": "The dessert is a cake.", "translation": "Le dessert est un gâteau."}, {"text": "Would you like a dessert?", "translation": "Voulez-vous un dessert ?"}]'::jsonb, '/dɪˈzɜːt/', '{"id": "en.d.dessert", "word": "dessert", "translation": "dessert", "partOfSpeech": "noun", "ipa": "/dɪˈzɜːt/", "explanation": "Nom pour le plat sucré qu''on mange à la fin d''un repas. Il s''écrit avec deux s.", "examples": [{"text": "The dessert is a cake.", "translation": "Le dessert est un gâteau."}, {"text": "Would you like a dessert?", "translation": "Voulez-vous un dessert ?"}], "confusions": [{"word": "desert", "note": "Desert (un seul s, /ˈdezət/) veut dire « désert ». Dessert prend deux s : on en veut deux fois !"}], "forms": {"plural": "desserts"}, "unitId": "en.v.dessert"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.salad', 'en', 'salad', 'salade', 'Nom pour un plat froid de légumes. En anglais, salad est le plat entier, pas la plante.', '[{"text": "I would like a salad for lunch.", "translation": "Je voudrais une salade pour le déjeuner."}, {"text": "Anna eats a salad every day.", "translation": "Anna mange une salade tous les jours."}]'::jsonb, '/ˈsæləd/', '{"id": "en.d.salad", "word": "salad", "translation": "salade", "partOfSpeech": "noun", "ipa": "/ˈsæləd/", "explanation": "Nom pour un plat froid de légumes. En anglais, salad est le plat entier, pas la plante.", "examples": [{"text": "I would like a salad for lunch.", "translation": "Je voudrais une salade pour le déjeuner."}, {"text": "Anna eats a salad every day.", "translation": "Anna mange une salade tous les jours."}], "confusions": [], "forms": {"plural": "salads"}, "unitId": "en.v.salad"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.in', 'en', 'in', 'dans, à, en', 'Préposition qui montre qu''on est à l''intérieur d''un lieu (in the kitchen, in London). Elle s''emploie aussi avec les mois, les saisons, les années et les moments de la journée : in January, in summer, in the morning.', '[{"text": "The keys are in the bag.", "translation": "Les clés sont dans le sac."}, {"text": "We go to the beach in summer.", "translation": "Nous allons à la plage en été."}]'::jsonb, '/ɪn/', '{"id": "en.d.in", "word": "in", "translation": "dans, à, en", "partOfSpeech": "preposition", "ipa": "/ɪn/", "explanation": "Préposition qui montre qu''on est à l''intérieur d''un lieu (in the kitchen, in London). Elle s''emploie aussi avec les mois, les saisons, les années et les moments de la journée : in January, in summer, in the morning.", "examples": [{"text": "The keys are in the bag.", "translation": "Les clés sont dans le sac."}, {"text": "We go to the beach in summer.", "translation": "Nous allons à la plage en été."}], "confusions": [{"word": "on", "note": "On sert pour une surface ou un jour (on the table, on Monday)."}, {"word": "at", "note": "At sert pour un point précis ou une heure (at the door, at 8 o''clock)."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.on', 'en', 'on', 'sur ; le (jour)', 'Préposition qui montre qu''une chose est posée sur une surface ou à un étage (on the table, on the second floor). Avec le temps, elle s''emploie avec les jours et les dates : on Monday, on 5 January.', '[{"text": "The book is on the table.", "translation": "Le livre est sur la table."}, {"text": "I work on Monday.", "translation": "Je travaille le lundi."}]'::jsonb, '/ɒn/', '{"id": "en.d.on", "word": "on", "translation": "sur ; le (jour)", "partOfSpeech": "preposition", "ipa": "/ɒn/", "explanation": "Préposition qui montre qu''une chose est posée sur une surface ou à un étage (on the table, on the second floor). Avec le temps, elle s''emploie avec les jours et les dates : on Monday, on 5 January.", "examples": [{"text": "The book is on the table.", "translation": "Le livre est sur la table."}, {"text": "I work on Monday.", "translation": "Je travaille le lundi."}], "confusions": [{"word": "in", "note": "In veut dire « dans » (à l''intérieur) ; on veut dire « sur » (en contact avec une surface)."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.at', 'en', 'at', 'à', 'Préposition pour un point précis ou un lieu où l''on fait son activité (at the door, at home, at school). Avec le temps, on l''utilise avec l''heure : at 8 o''clock, et dans at night.', '[{"text": "Anna is at the door.", "translation": "Anna est à la porte."}, {"text": "The meeting is at three o''clock.", "translation": "La réunion est à trois heures."}]'::jsonb, '/æt/', '{"id": "en.d.at", "word": "at", "translation": "à", "partOfSpeech": "preposition", "ipa": "/æt/", "explanation": "Préposition pour un point précis ou un lieu où l''on fait son activité (at the door, at home, at school). Avec le temps, on l''utilise avec l''heure : at 8 o''clock, et dans at night.", "examples": [{"text": "Anna is at the door.", "translation": "Anna est à la porte."}, {"text": "The meeting is at three o''clock.", "translation": "La réunion est à trois heures."}], "confusions": [{"word": "in", "note": "In sert pour l''intérieur d''un lieu, un mois ou une saison."}, {"word": "on", "note": "On sert pour une surface, un jour ou une date."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.under', 'en', 'under', 'sous', 'Préposition pour dire qu''une chose est plus bas qu''une autre, juste en dessous.', '[{"text": "The dog is under the table.", "translation": "Le chien est sous la table."}, {"text": "My bag is under the chair.", "translation": "Mon sac est sous la chaise."}]'::jsonb, '/ˈʌndə/', '{"id": "en.d.under", "word": "under", "translation": "sous", "partOfSpeech": "preposition", "ipa": "/ˈʌndə/", "explanation": "Préposition pour dire qu''une chose est plus bas qu''une autre, juste en dessous.", "examples": [{"text": "The dog is under the table.", "translation": "Le chien est sous la table."}, {"text": "My bag is under the chair.", "translation": "Mon sac est sous la chaise."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.next_to', 'en', 'next to', 'à côté de', 'Préposition pour dire qu''une chose est tout près d''une autre, sans rien entre les deux. On ne dit pas « next of » ni « next the ».', '[{"text": "The station is next to the park.", "translation": "La gare est à côté du parc."}, {"text": "Sit next to me.", "translation": "Assieds-toi à côté de moi."}]'::jsonb, '/ˈnekst tuː/', '{"id": "en.d.next_to", "word": "next to", "translation": "à côté de", "partOfSpeech": "preposition", "ipa": "/ˈnekst tuː/", "explanation": "Préposition pour dire qu''une chose est tout près d''une autre, sans rien entre les deux. On ne dit pas « next of » ni « next the ».", "examples": [{"text": "The station is next to the park.", "translation": "La gare est à côté du parc."}, {"text": "Sit next to me.", "translation": "Assieds-toi à côté de moi."}], "confusions": [{"word": "near", "note": "Near veut dire « près de » (pas forcément collé) ; next to veut dire « juste à côté de »."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.between', 'en', 'between', 'entre', 'Préposition pour dire qu''une chose est au milieu de deux autres. On l''utilise avec and : between A and B.', '[{"text": "The shop is between the hotel and the school.", "translation": "Le magasin est entre l''hôtel et l''école."}, {"text": "Sit between Anna and Tom.", "translation": "Assieds-toi entre Anna et Tom."}]'::jsonb, '/bɪˈtwiːn/', '{"id": "en.d.between", "word": "between", "translation": "entre", "partOfSpeech": "preposition", "ipa": "/bɪˈtwiːn/", "explanation": "Préposition pour dire qu''une chose est au milieu de deux autres. On l''utilise avec and : between A and B.", "examples": [{"text": "The shop is between the hotel and the school.", "translation": "Le magasin est entre l''hôtel et l''école."}, {"text": "Sit between Anna and Tom.", "translation": "Assieds-toi entre Anna et Tom."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.behind', 'en', 'behind', 'derrière', 'Préposition pour dire qu''une chose est à l''arrière d''une autre. C''est le contraire de in front of.', '[{"text": "The garden is behind the house.", "translation": "Le jardin est derrière la maison."}, {"text": "The key is behind the book.", "translation": "La clé est derrière le livre."}]'::jsonb, '/bɪˈhaɪnd/', '{"id": "en.d.behind", "word": "behind", "translation": "derrière", "partOfSpeech": "preposition", "ipa": "/bɪˈhaɪnd/", "explanation": "Préposition pour dire qu''une chose est à l''arrière d''une autre. C''est le contraire de in front of.", "examples": [{"text": "The garden is behind the house.", "translation": "Le jardin est derrière la maison."}, {"text": "The key is behind the book.", "translation": "La clé est derrière le livre."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.in_front_of', 'en', 'in front of', 'devant', 'Préposition de lieu en trois mots, qui veut dire « devant ». N''oublie pas of : on ne dit pas « in front the house ».', '[{"text": "The car is in front of the building.", "translation": "La voiture est devant l''immeuble."}, {"text": "Tom is in front of me.", "translation": "Tom est devant moi."}]'::jsonb, '/ɪn ˈfrʌnt əv/', '{"id": "en.d.in_front_of", "word": "in front of", "translation": "devant", "partOfSpeech": "preposition", "ipa": "/ɪn ˈfrʌnt əv/", "explanation": "Préposition de lieu en trois mots, qui veut dire « devant ». N''oublie pas of : on ne dit pas « in front the house ».", "examples": [{"text": "The car is in front of the building.", "translation": "La voiture est devant l''immeuble."}, {"text": "Tom is in front of me.", "translation": "Tom est devant moi."}], "confusions": [{"word": "before", "note": "Before veut dire « avant » (dans le temps). Pour « devant » (lieu), on dit in front of."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.before', 'en', 'before', 'avant', 'Préposition de temps qui veut dire « avant ». Elle s''emploie devant un nom ou un moment : before dinner, before Monday.', '[{"text": "I always take a shower before breakfast.", "translation": "Je prends toujours une douche avant le petit-déjeuner."}, {"text": "I read before dinner.", "translation": "Je lis avant le dîner."}]'::jsonb, '/bɪˈfɔː/', '{"id": "en.d.before", "word": "before", "translation": "avant", "partOfSpeech": "preposition", "ipa": "/bɪˈfɔː/", "explanation": "Préposition de temps qui veut dire « avant ». Elle s''emploie devant un nom ou un moment : before dinner, before Monday.", "examples": [{"text": "I always take a shower before breakfast.", "translation": "Je prends toujours une douche avant le petit-déjeuner."}, {"text": "I read before dinner.", "translation": "Je lis avant le dîner."}], "confusions": [{"word": "in front of", "note": "Pour « devant » dans l''espace, on dit in front of, pas before."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.after', 'en', 'after', 'après', 'Préposition de temps qui veut dire « après ». C''est le contraire de before. Elle s''emploie devant un nom : after dinner, after school.', '[{"text": "I watch TV after dinner.", "translation": "Je regarde la télé après le dîner."}, {"text": "After school, Tom plays music.", "translation": "Après l''école, Tom joue de la musique."}]'::jsonb, '/ˈɑːftə/', '{"id": "en.d.after", "word": "after", "translation": "après", "partOfSpeech": "preposition", "ipa": "/ˈɑːftə/", "explanation": "Préposition de temps qui veut dire « après ». C''est le contraire de before. Elle s''emploie devant un nom : after dinner, after school.", "examples": [{"text": "I watch TV after dinner.", "translation": "Je regarde la télé après le dîner."}, {"text": "After school, Tom plays music.", "translation": "Après l''école, Tom joue de la musique."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.during', 'en', 'during', 'pendant', 'Préposition de temps pour dire que quelque chose se passe pendant une période ou un événement : during the meeting, during the week.', '[{"text": "I don''t talk during the meeting.", "translation": "Je ne parle pas pendant la réunion."}, {"text": "We stay at home during the winter.", "translation": "Nous restons à la maison pendant l''hiver."}]'::jsonb, '/ˈdjʊərɪŋ/', '{"id": "en.d.during", "word": "during", "translation": "pendant", "partOfSpeech": "preposition", "ipa": "/ˈdjʊərɪŋ/", "explanation": "Préposition de temps pour dire que quelque chose se passe pendant une période ou un événement : during the meeting, during the week.", "examples": [{"text": "I don''t talk during the meeting.", "translation": "Je ne parle pas pendant la réunion."}, {"text": "We stay at home during the winter.", "translation": "Nous restons à la maison pendant l''hiver."}], "confusions": [{"word": "for", "note": "For donne la durée (for two hours) ; during dit à quel moment cela arrive (during the meeting)."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.what', 'en', 'what', 'quoi, que, quel', 'Mot interrogatif pour demander une information sur une chose : What is your name ? What time is it ? Il se place au début de la question, suivi de l''auxiliaire.', '[{"text": "What is your name?", "translation": "Comment t''appelles-tu ?"}, {"text": "What time does the meeting start?", "translation": "À quelle heure commence la réunion ?"}]'::jsonb, '/wɒt/', '{"id": "en.d.what", "word": "what", "translation": "quoi, que, quel", "partOfSpeech": "pronoun", "ipa": "/wɒt/", "explanation": "Mot interrogatif pour demander une information sur une chose : What is your name ? What time is it ? Il se place au début de la question, suivi de l''auxiliaire.", "examples": [{"text": "What is your name?", "translation": "Comment t''appelles-tu ?"}, {"text": "What time does the meeting start?", "translation": "À quelle heure commence la réunion ?"}], "confusions": [{"word": "which", "note": "Which s''emploie pour choisir entre quelques possibilités connues ; what pour une question ouverte."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.where', 'en', 'where', 'où', 'Mot interrogatif pour demander un lieu : Where do you live ? Il faut un auxiliaire après where : Where do you live ?, pas Where you live ?', '[{"text": "Where do you live?", "translation": "Où habites-tu ?"}, {"text": "Where is the station?", "translation": "Où est la gare ?"}]'::jsonb, '/weə/', '{"id": "en.d.where", "word": "where", "translation": "où", "partOfSpeech": "adverb", "ipa": "/weə/", "explanation": "Mot interrogatif pour demander un lieu : Where do you live ? Il faut un auxiliaire après where : Where do you live ?, pas Where you live ?", "examples": [{"text": "Where do you live?", "translation": "Où habites-tu ?"}, {"text": "Where is the station?", "translation": "Où est la gare ?"}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.when', 'en', 'when', 'quand', 'Mot interrogatif pour demander un moment : When is your birthday ? When do you finish work ?', '[{"text": "When do you finish work?", "translation": "Quand finis-tu le travail ?"}, {"text": "When is your birthday?", "translation": "Quand est ton anniversaire ?"}]'::jsonb, '/wen/', '{"id": "en.d.when", "word": "when", "translation": "quand", "partOfSpeech": "adverb", "ipa": "/wen/", "explanation": "Mot interrogatif pour demander un moment : When is your birthday ? When do you finish work ?", "examples": [{"text": "When do you finish work?", "translation": "Quand finis-tu le travail ?"}, {"text": "When is your birthday?", "translation": "Quand est ton anniversaire ?"}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.who', 'en', 'who', 'qui', 'Mot interrogatif pour demander qui est la personne : Who is your teacher ? Quand who est le sujet, on n''ajoute pas do : Who lives here ?', '[{"text": "Who is your teacher?", "translation": "Qui est ton professeur ?"}, {"text": "Who lives in this house?", "translation": "Qui habite dans cette maison ?"}]'::jsonb, '/huː/', '{"id": "en.d.who", "word": "who", "translation": "qui", "partOfSpeech": "pronoun", "ipa": "/huː/", "explanation": "Mot interrogatif pour demander qui est la personne : Who is your teacher ? Quand who est le sujet, on n''ajoute pas do : Who lives here ?", "examples": [{"text": "Who is your teacher?", "translation": "Qui est ton professeur ?"}, {"text": "Who lives in this house?", "translation": "Qui habite dans cette maison ?"}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.why', 'en', 'why', 'pourquoi', 'Mot interrogatif pour demander la raison : Why are you late ? On répond avec because.', '[{"text": "Why are you late?", "translation": "Pourquoi es-tu en retard ?"}, {"text": "Why do you learn English?", "translation": "Pourquoi apprends-tu l''anglais ?"}]'::jsonb, '/waɪ/', '{"id": "en.d.why", "word": "why", "translation": "pourquoi", "partOfSpeech": "adverb", "ipa": "/waɪ/", "explanation": "Mot interrogatif pour demander la raison : Why are you late ? On répond avec because.", "examples": [{"text": "Why are you late?", "translation": "Pourquoi es-tu en retard ?"}, {"text": "Why do you learn English?", "translation": "Pourquoi apprends-tu l''anglais ?"}], "confusions": [{"word": "because", "note": "Because donne la réponse à la question avec why."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.how', 'en', 'how', 'comment', 'Mot interrogatif pour demander la manière ou l''état : How are you ? Avec un adjectif, il demande le degré : how old (quel âge), how big (quelle taille).', '[{"text": "How are you?", "translation": "Comment vas-tu ?"}, {"text": "How old is your daughter?", "translation": "Quel âge a ta fille ?"}]'::jsonb, '/haʊ/', '{"id": "en.d.how", "word": "how", "translation": "comment", "partOfSpeech": "adverb", "ipa": "/haʊ/", "explanation": "Mot interrogatif pour demander la manière ou l''état : How are you ? Avec un adjectif, il demande le degré : how old (quel âge), how big (quelle taille).", "examples": [{"text": "How are you?", "translation": "Comment vas-tu ?"}, {"text": "How old is your daughter?", "translation": "Quel âge a ta fille ?"}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.which', 'en', 'which', 'quel, lequel', 'Mot interrogatif pour demander de choisir entre quelques possibilités connues : Which bag do you want ?', '[{"text": "Which book do you like?", "translation": "Quel livre aimes-tu ?"}, {"text": "Which place do you like, the park or the beach?", "translation": "Quel endroit aimes-tu, le parc ou la plage ?"}]'::jsonb, '/wɪtʃ/', '{"id": "en.d.which", "word": "which", "translation": "quel, lequel", "partOfSpeech": "determiner", "ipa": "/wɪtʃ/", "explanation": "Mot interrogatif pour demander de choisir entre quelques possibilités connues : Which bag do you want ?", "examples": [{"text": "Which book do you like?", "translation": "Quel livre aimes-tu ?"}, {"text": "Which place do you like, the park or the beach?", "translation": "Quel endroit aimes-tu, le parc ou la plage ?"}], "confusions": [{"word": "what", "note": "What est pour une question ouverte ; which demande de choisir entre quelques choix."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.and', 'en', 'and', 'et', 'Conjonction qui ajoute une idée ou un mot à un autre : Tom and Anna.', '[{"text": "Anna and Tom play music.", "translation": "Anna et Tom jouent de la musique."}, {"text": "I like coffee and milk.", "translation": "J''aime le café et le lait."}]'::jsonb, '/ænd/', '{"id": "en.d.and", "word": "and", "translation": "et", "partOfSpeech": "conjunction", "ipa": "/ænd/", "explanation": "Conjonction qui ajoute une idée ou un mot à un autre : Tom and Anna.", "examples": [{"text": "Anna and Tom play music.", "translation": "Anna et Tom jouent de la musique."}, {"text": "I like coffee and milk.", "translation": "J''aime le café et le lait."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.but', 'en', 'but', 'mais', 'Conjonction qui relie deux idées opposées : I like summer, but I don''t like the sun.', '[{"text": "The apartment is small, but it is beautiful.", "translation": "L''appartement est petit, mais il est beau."}, {"text": "I like winter, but I don''t like snow.", "translation": "J''aime l''hiver, mais je n''aime pas la neige."}]'::jsonb, '/bʌt/', '{"id": "en.d.but", "word": "but", "translation": "mais", "partOfSpeech": "conjunction", "ipa": "/bʌt/", "explanation": "Conjonction qui relie deux idées opposées : I like summer, but I don''t like the sun.", "examples": [{"text": "The apartment is small, but it is beautiful.", "translation": "L''appartement est petit, mais il est beau."}, {"text": "I like winter, but I don''t like snow.", "translation": "J''aime l''hiver, mais je n''aime pas la neige."}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.or', 'en', 'or', 'ou', 'Conjonction qui propose un choix entre deux possibilités : coffee or water ?', '[{"text": "Do you want coffee or water?", "translation": "Veux-tu du café ou de l''eau ?"}, {"text": "Is it Monday or Sunday?", "translation": "Est-on lundi ou dimanche ?"}]'::jsonb, '/ɔː/', '{"id": "en.d.or", "word": "or", "translation": "ou", "partOfSpeech": "conjunction", "ipa": "/ɔː/", "explanation": "Conjonction qui propose un choix entre deux possibilités : coffee or water ?", "examples": [{"text": "Do you want coffee or water?", "translation": "Veux-tu du café ou de l''eau ?"}, {"text": "Is it Monday or Sunday?", "translation": "Est-on lundi ou dimanche ?"}], "confusions": [], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.because', 'en', 'because', 'parce que', 'Conjonction qui donne la cause. Elle est suivie d''une phrase complète avec un sujet et un verbe : because it rains. Pour « à cause de » + nom, on dit because of.', '[{"text": "I stay at home because it snows.", "translation": "Je reste à la maison parce qu''il neige."}, {"text": "I am tired because I work late.", "translation": "Je suis fatigué parce que je travaille tard."}]'::jsonb, '/bɪˈkɒz/', '{"id": "en.d.because", "word": "because", "translation": "parce que", "partOfSpeech": "conjunction", "ipa": "/bɪˈkɒz/", "explanation": "Conjonction qui donne la cause. Elle est suivie d''une phrase complète avec un sujet et un verbe : because it rains. Pour « à cause de » + nom, on dit because of.", "examples": [{"text": "I stay at home because it snows.", "translation": "Je reste à la maison parce qu''il neige."}, {"text": "I am tired because I work late.", "translation": "Je suis fatigué parce que je travaille tard."}], "confusions": [{"word": "so", "note": "Because donne la cause ; so donne la conséquence."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.so', 'en', 'so', 'donc, alors', 'Conjonction qui donne la conséquence de ce qui vient d''être dit : It is hot, so I drink water. So s''emploie aussi devant un adjectif pour dire « si, tellement ».', '[{"text": "It is cold, so I stay at home.", "translation": "Il fait froid, donc je reste à la maison."}, {"text": "I am tired, so I go to bed.", "translation": "Je suis fatigué, donc je vais me coucher."}]'::jsonb, '/səʊ/', '{"id": "en.d.so", "word": "so", "translation": "donc, alors", "partOfSpeech": "conjunction", "ipa": "/səʊ/", "explanation": "Conjonction qui donne la conséquence de ce qui vient d''être dit : It is hot, so I drink water. So s''emploie aussi devant un adjectif pour dire « si, tellement ».", "examples": [{"text": "It is cold, so I stay at home.", "translation": "Il fait froid, donc je reste à la maison."}, {"text": "I am tired, so I go to bed.", "translation": "Je suis fatigué, donc je vais me coucher."}], "confusions": [{"word": "because", "note": "So donne le résultat ; because donne la raison."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.then', 'en', 'then', 'puis, ensuite', 'Adverbe qui montre l''ordre des actions : d''abord une chose, puis une autre. Il s''écrit avec un e.', '[{"text": "First I wake up, then I take a shower.", "translation": "D''abord je me réveille, puis je prends une douche."}, {"text": "I finish my homework, then I watch TV.", "translation": "Je finis mes devoirs, puis je regarde la télé."}]'::jsonb, '/ðen/', '{"id": "en.d.then", "word": "then", "translation": "puis, ensuite", "partOfSpeech": "adverb", "ipa": "/ðen/", "explanation": "Adverbe qui montre l''ordre des actions : d''abord une chose, puis une autre. Il s''écrit avec un e.", "examples": [{"text": "First I wake up, then I take a shower.", "translation": "D''abord je me réveille, puis je prends une douche."}, {"text": "I finish my homework, then I watch TV.", "translation": "Je finis mes devoirs, puis je regarde la télé."}], "confusions": [{"word": "than", "note": "Than (avec un a) sert aux comparaisons : taller than."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.than', 'en', 'than', 'que (comparaison)', 'Mot qui sert à comparer deux choses après un comparatif : taller than, more expensive than. Il ne se confond pas avec then (puis) ni avec that (que).', '[{"text": "My brother is taller than my father.", "translation": "Mon frère est plus grand que mon père."}, {"text": "London is bigger than Paris.", "translation": "Londres est plus grande que Paris."}]'::jsonb, '/ðæn/', '{"id": "en.d.than", "word": "than", "translation": "que (comparaison)", "partOfSpeech": "conjunction", "ipa": "/ðæn/", "explanation": "Mot qui sert à comparer deux choses après un comparatif : taller than, more expensive than. Il ne se confond pas avec then (puis) ni avec that (que).", "examples": [{"text": "My brother is taller than my father.", "translation": "Mon frère est plus grand que mon père."}, {"text": "London is bigger than Paris.", "translation": "Londres est plus grande que Paris."}], "confusions": [{"word": "then", "note": "Then (avec un e) veut dire « puis »."}, {"word": "that", "note": "That veut dire « que » ou « ce » dans d''autres phrases ; après un comparatif, on met than."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.more', 'en', 'more', 'plus (de)', 'Mot qui sert à former le comparatif des adjectifs longs : more beautiful, more expensive. Il veut aussi dire « plus de » ou « encore » : more water.', '[{"text": "The hotel is more expensive than the apartment.", "translation": "L''hôtel est plus cher que l''appartement."}, {"text": "Could I have more water, please?", "translation": "Puis-je avoir encore de l''eau, s''il vous plaît ?"}]'::jsonb, '/mɔː/', '{"id": "en.d.more", "word": "more", "translation": "plus (de)", "partOfSpeech": "adverb", "ipa": "/mɔː/", "explanation": "Mot qui sert à former le comparatif des adjectifs longs : more beautiful, more expensive. Il veut aussi dire « plus de » ou « encore » : more water.", "examples": [{"text": "The hotel is more expensive than the apartment.", "translation": "L''hôtel est plus cher que l''appartement."}, {"text": "Could I have more water, please?", "translation": "Puis-je avoir encore de l''eau, s''il vous plaît ?"}], "confusions": [{"word": "most", "note": "More compare deux choses ; most désigne la plus haute valeur."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.most', 'en', 'most', 'le plus ; la plupart de', 'Mot qui sert à former le superlatif des adjectifs longs : the most beautiful, the most expensive. Il veut aussi dire « la plupart de » : most people.', '[{"text": "This is the most expensive hotel in the city.", "translation": "C''est l''hôtel le plus cher de la ville."}, {"text": "Most people like summer.", "translation": "La plupart des gens aiment l''été."}]'::jsonb, '/məʊst/', '{"id": "en.d.most", "word": "most", "translation": "le plus ; la plupart de", "partOfSpeech": "adverb", "ipa": "/məʊst/", "explanation": "Mot qui sert à former le superlatif des adjectifs longs : the most beautiful, the most expensive. Il veut aussi dire « la plupart de » : most people.", "examples": [{"text": "This is the most expensive hotel in the city.", "translation": "C''est l''hôtel le plus cher de la ville."}, {"text": "Most people like summer.", "translation": "La plupart des gens aiment l''été."}], "confusions": [{"word": "more", "note": "More se combine avec than ; most se combine avec the."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.should', 'en', 'should', 'devrait', 'Verbe modal pour donner un conseil : You should rest. Il est suivi du verbe de base, sans to et sans -s. Négatif : shouldn''t.', '[{"text": "You should rest.", "translation": "Tu devrais te reposer."}, {"text": "I should go to bed early.", "translation": "Je devrais me coucher tôt."}]'::jsonb, '/ʃʊd/', '{"id": "en.d.should", "word": "should", "translation": "devrait", "partOfSpeech": "modal", "ipa": "/ʃʊd/", "explanation": "Verbe modal pour donner un conseil : You should rest. Il est suivi du verbe de base, sans to et sans -s. Négatif : shouldn''t.", "examples": [{"text": "You should rest.", "translation": "Tu devrais te reposer."}, {"text": "I should go to bed early.", "translation": "Je devrais me coucher tôt."}], "confusions": [{"word": "must", "note": "Must exprime une obligation forte ; should donne un simple conseil."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.could', 'en', 'could', 'pourrait ; pourriez-vous', 'Verbe modal pour une possibilité (We could go to the beach) ou pour demander poliment (Could you help me ?). Il est suivi du verbe de base, sans to.', '[{"text": "We could go to the beach.", "translation": "On pourrait aller à la plage."}, {"text": "Could you help me, please?", "translation": "Pourriez-vous m''aider, s''il vous plaît ?"}]'::jsonb, '/kʊd/', '{"id": "en.d.could", "word": "could", "translation": "pourrait ; pourriez-vous", "partOfSpeech": "modal", "ipa": "/kʊd/", "explanation": "Verbe modal pour une possibilité (We could go to the beach) ou pour demander poliment (Could you help me ?). Il est suivi du verbe de base, sans to.", "examples": [{"text": "We could go to the beach.", "translation": "On pourrait aller à la plage."}, {"text": "Could you help me, please?", "translation": "Pourriez-vous m''aider, s''il vous plaît ?"}], "confusions": [{"word": "can", "note": "Can est plus direct ; could est plus poli pour une demande."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.would', 'en', 'would', 'voudrait ; (conditionnel)', 'Verbe modal qu''on utilise pour être poli, surtout dans would like : I would like a coffee, Would you like a coffee ? Il est suivi du verbe de base, sans to.', '[{"text": "Would you like a cup of coffee?", "translation": "Voulez-vous une tasse de café ?"}, {"text": "I would like a salad, please.", "translation": "Je voudrais une salade, s''il vous plaît."}]'::jsonb, '/wʊd/', '{"id": "en.d.would", "word": "would", "translation": "voudrait ; (conditionnel)", "partOfSpeech": "modal", "ipa": "/wʊd/", "explanation": "Verbe modal qu''on utilise pour être poli, surtout dans would like : I would like a coffee, Would you like a coffee ? Il est suivi du verbe de base, sans to.", "examples": [{"text": "Would you like a cup of coffee?", "translation": "Voulez-vous une tasse de café ?"}, {"text": "I would like a salad, please.", "translation": "Je voudrais une salade, s''il vous plaît."}], "confusions": [{"word": "will", "note": "Will parle du futur ; would sert à être poli (would like)."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.abroad', 'en', 'abroad', 'à l''étranger', 'Abroad veut dire « dans un autre pays » ; il s''emploie sans préposition : go abroad, pas go to abroad.', '[{"text": "My brother lives abroad.", "translation": "Mon frère vit à l''étranger."}, {"text": "Have you ever worked abroad?", "translation": "As-tu déjà travaillé à l''étranger ?"}]'::jsonb, '/əˈbrɔːd/', '{"id": "en.d.abroad", "word": "abroad", "translation": "à l''étranger", "partOfSpeech": "adverb", "ipa": "/əˈbrɔːd/", "explanation": "Abroad veut dire « dans un autre pays » ; il s''emploie sans préposition : go abroad, pas go to abroad.", "examples": [{"text": "My brother lives abroad.", "translation": "Mon frère vit à l''étranger."}, {"text": "Have you ever worked abroad?", "translation": "As-tu déjà travaillé à l''étranger ?"}], "confusions": [], "unitId": "en.v.abroad"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.museum', 'en', 'museum', 'musée', 'Un museum est un bâtiment où l''on peut voir des objets d''art, d''histoire ou de science.', '[{"text": "We visited a museum in Paris.", "translation": "Nous avons visité un musée à Paris."}, {"text": "The museum is closed on Monday.", "translation": "Le musée est fermé le lundi."}]'::jsonb, '/mjuˈziːəm/', '{"id": "en.d.museum", "word": "museum", "translation": "musée", "partOfSpeech": "noun", "ipa": "/mjuˈziːəm/", "explanation": "Un museum est un bâtiment où l''on peut voir des objets d''art, d''histoire ou de science.", "examples": [{"text": "We visited a museum in Paris.", "translation": "Nous avons visité un musée à Paris."}, {"text": "The museum is closed on Monday.", "translation": "Le musée est fermé le lundi."}], "confusions": [], "forms": {"plural": "museums"}, "unitId": "en.v.museum"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.film', 'en', 'film', 'film', 'Un film est une histoire que l''on regarde au cinéma ou à la télévision. En anglais américain, on dit plutôt movie.', '[{"text": "I watched a French film last night.", "translation": "J''ai regardé un film français hier soir."}, {"text": "Have you seen this film?", "translation": "As-tu vu ce film ?"}]'::jsonb, '/fɪlm/', '{"id": "en.d.film", "word": "film", "translation": "film", "otherTranslations": ["pellicule (photo)"], "partOfSpeech": "noun", "ipa": "/fɪlm/", "explanation": "Un film est une histoire que l''on regarde au cinéma ou à la télévision. En anglais américain, on dit plutôt movie.", "examples": [{"text": "I watched a French film last night.", "translation": "J''ai regardé un film français hier soir."}, {"text": "Have you seen this film?", "translation": "As-tu vu ce film ?"}], "confusions": [{"word": "movie", "note": "mot américain pour film ; les deux sont compris partout."}], "forms": {"plural": "films"}, "unitId": "en.v.film"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.ever', 'en', 'ever', 'déjà, un jour (dans une question)', 'Ever s''emploie surtout dans les questions au present perfect pour demander si quelque chose est arrivé « un jour dans la vie » : Have you ever…? Il se place entre le sujet et le participe passé.', '[{"text": "Have you ever been to London?", "translation": "Es-tu déjà allé à Londres ?"}, {"text": "Has Tom ever lost his key?", "translation": "Tom a-t-il déjà perdu sa clé ?"}]'::jsonb, '/ˈevə/', '{"id": "en.d.ever", "word": "ever", "translation": "déjà, un jour (dans une question)", "otherTranslations": ["jamais (dans une question)"], "partOfSpeech": "adverb", "ipa": "/ˈevə/", "explanation": "Ever s''emploie surtout dans les questions au present perfect pour demander si quelque chose est arrivé « un jour dans la vie » : Have you ever…? Il se place entre le sujet et le participe passé.", "examples": [{"text": "Have you ever been to London?", "translation": "Es-tu déjà allé à Londres ?"}, {"text": "Has Tom ever lost his key?", "translation": "Tom a-t-il déjà perdu sa clé ?"}], "confusions": [{"word": "never", "note": "jamais. On dit I have never been abroad (phrase affirmative), mais Have you ever been abroad? (question)."}, {"word": "already", "note": "déjà au sens « c''est déjà fait » ; ever demande si cela est arrivé un jour dans la vie."}], "unitId": "en.v.ever"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.try', 'en', 'try', 'essayer, goûter', 'Try veut dire « essayer de faire quelque chose » ou « goûter / tester quelque chose pour la première fois ».', '[{"text": "Please try this cake.", "translation": "Goûte ce gâteau, s''il te plaît."}, {"text": "I tried to call you, but your phone was off.", "translation": "J''ai essayé de t''appeler, mais ton téléphone était éteint."}]'::jsonb, '/traɪ/', '{"id": "en.d.try", "word": "try", "translation": "essayer, goûter", "partOfSpeech": "verb", "ipa": "/traɪ/", "explanation": "Try veut dire « essayer de faire quelque chose » ou « goûter / tester quelque chose pour la première fois ».", "examples": [{"text": "Please try this cake.", "translation": "Goûte ce gâteau, s''il te plaît."}, {"text": "I tried to call you, but your phone was off.", "translation": "J''ai essayé de t''appeler, mais ton téléphone était éteint."}], "confusions": [], "forms": {"thirdPerson": "tries", "past": "tried", "pastParticiple": "tried", "ing": "trying"}, "unitId": "en.v.try"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.already', 'en', 'already', 'déjà', 'Already dit que quelque chose est fait, parfois plus tôt que prévu. Avec le present perfect, il se place entre have / has et le participe passé, ou à la fin de la phrase.', '[{"text": "I have already finished my homework.", "translation": "J''ai déjà fini mes devoirs."}, {"text": "Anna has already left the office.", "translation": "Anna a déjà quitté le bureau."}]'::jsonb, '/ɔːlˈredi/', '{"id": "en.d.already", "word": "already", "translation": "déjà", "partOfSpeech": "adverb", "ipa": "/ɔːlˈredi/", "explanation": "Already dit que quelque chose est fait, parfois plus tôt que prévu. Avec le present perfect, il se place entre have / has et le participe passé, ou à la fin de la phrase.", "examples": [{"text": "I have already finished my homework.", "translation": "J''ai déjà fini mes devoirs."}, {"text": "Anna has already left the office.", "translation": "Anna a déjà quitté le bureau."}], "confusions": [{"word": "ever", "note": "ever sert à demander une expérience (Have you ever…?) ; already dit que c''est déjà fait."}, {"word": "yet", "note": "yet s''emploie dans les questions et les négations (Have you finished yet? / not yet)."}], "unitId": "en.v.already"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.yet', 'en', 'yet', 'déjà (question), encore (négation)', 'Yet s''emploie à la fin d''une question (Have you eaten yet?) ou d''une négation (I haven''t eaten yet). Il parle de quelque chose qu''on attend encore.', '[{"text": "Have you finished your report yet?", "translation": "As-tu déjà fini ton rapport ?"}, {"text": "I haven''t called Tom yet.", "translation": "Je n''ai pas encore appelé Tom."}]'::jsonb, '/jet/', '{"id": "en.d.yet", "word": "yet", "translation": "déjà (question), encore (négation)", "partOfSpeech": "adverb", "ipa": "/jet/", "explanation": "Yet s''emploie à la fin d''une question (Have you eaten yet?) ou d''une négation (I haven''t eaten yet). Il parle de quelque chose qu''on attend encore.", "examples": [{"text": "Have you finished your report yet?", "translation": "As-tu déjà fini ton rapport ?"}, {"text": "I haven''t called Tom yet.", "translation": "Je n''ai pas encore appelé Tom."}], "confusions": [{"word": "already", "note": "already s''emploie dans les phrases affirmatives : I have already called Tom."}], "unitId": "en.v.yet"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.just', 'en', 'just', 'venir de (avec le present perfect)', 'Avec le present perfect, just veut dire « à l''instant, il y a très peu de temps » : I have just arrived = je viens d''arriver. Il se place entre have / has et le participe passé.', '[{"text": "I have just sent the email.", "translation": "Je viens d''envoyer l''e-mail."}, {"text": "They have just left.", "translation": "Ils viennent de partir."}]'::jsonb, '/dʒʌst/', '{"id": "en.d.just", "word": "just", "translation": "venir de (avec le present perfect)", "otherTranslations": ["juste, seulement"], "partOfSpeech": "adverb", "ipa": "/dʒʌst/", "explanation": "Avec le present perfect, just veut dire « à l''instant, il y a très peu de temps » : I have just arrived = je viens d''arriver. Il se place entre have / has et le participe passé.", "examples": [{"text": "I have just sent the email.", "translation": "Je viens d''envoyer l''e-mail."}, {"text": "They have just left.", "translation": "Ils viennent de partir."}], "confusions": [], "unitId": "en.v.just"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.email', 'en', 'email', 'e-mail, courriel', 'Un email est un message envoyé par Internet. On dit send an email, write an email, get an email.', '[{"text": "I wrote an email to my teacher.", "translation": "J''ai écrit un e-mail à mon professeur."}, {"text": "Did you get my email?", "translation": "As-tu reçu mon e-mail ?"}]'::jsonb, '/ˈiːmeɪl/', '{"id": "en.d.email", "word": "email", "translation": "e-mail, courriel", "partOfSpeech": "noun", "ipa": "/ˈiːmeɪl/", "explanation": "Un email est un message envoyé par Internet. On dit send an email, write an email, get an email.", "examples": [{"text": "I wrote an email to my teacher.", "translation": "J''ai écrit un e-mail à mon professeur."}, {"text": "Did you get my email?", "translation": "As-tu reçu mon e-mail ?"}], "confusions": [], "forms": {"plural": "emails"}, "unitId": "en.v.email"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.report', 'en', 'report', 'rapport', 'Un report est un document qui donne des informations sur un sujet, souvent au travail ou à l''école.', '[{"text": "I''m writing a report for my boss.", "translation": "J''écris un rapport pour mon patron."}, {"text": "She has finished the report.", "translation": "Elle a fini le rapport."}]'::jsonb, '/rɪˈpɔːt/', '{"id": "en.d.report", "word": "report", "translation": "rapport", "otherTranslations": ["faire un rapport (verbe)"], "partOfSpeech": "noun", "ipa": "/rɪˈpɔːt/", "explanation": "Un report est un document qui donne des informations sur un sujet, souvent au travail ou à l''école.", "examples": [{"text": "I''m writing a report for my boss.", "translation": "J''écris un rapport pour mon patron."}, {"text": "She has finished the report.", "translation": "Elle a fini le rapport."}], "confusions": [], "forms": {"plural": "reports"}, "unitId": "en.v.report"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.nice_to_meet_you', 'en', 'nice to meet you', 'enchanté(e)', 'On dit nice to meet you quand on rencontre quelqu''un pour la première fois. On répond souvent Nice to meet you, too.', '[{"text": "Hello, I''m Anna. Nice to meet you.", "translation": "Bonjour, je m''appelle Anna. Enchantée."}, {"text": "Nice to meet you, Mr Brown.", "translation": "Enchanté, monsieur Brown."}]'::jsonb, '/naɪs tə ˈmiːt juː/', '{"id": "en.d.nice_to_meet_you", "word": "nice to meet you", "translation": "enchanté(e)", "partOfSpeech": "expression", "ipa": "/naɪs tə ˈmiːt juː/", "explanation": "On dit nice to meet you quand on rencontre quelqu''un pour la première fois. On répond souvent Nice to meet you, too.", "examples": [{"text": "Hello, I''m Anna. Nice to meet you.", "translation": "Bonjour, je m''appelle Anna. Enchantée."}, {"text": "Nice to meet you, Mr Brown.", "translation": "Enchanté, monsieur Brown."}], "confusions": [], "unitId": "en.v.nice_to_meet_you"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.how_are_you', 'en', 'how are you', 'comment ça va ?', 'How are you? est une salutation très courante. On répond en général I''m fine, thank you. And you?', '[{"text": "Hi Tom, how are you? — I''m fine, thanks.", "translation": "Salut Tom, comment ça va ? — Ça va bien, merci."}, {"text": "How are you today?", "translation": "Comment vas-tu aujourd''hui ?"}]'::jsonb, '/haʊ ɑː juː/', '{"id": "en.d.how_are_you", "word": "how are you", "translation": "comment ça va ?", "otherTranslations": ["comment vas-tu ?, comment allez-vous ?"], "partOfSpeech": "expression", "ipa": "/haʊ ɑː juː/", "explanation": "How are you? est une salutation très courante. On répond en général I''m fine, thank you. And you?", "examples": [{"text": "Hi Tom, how are you? — I''m fine, thanks.", "translation": "Salut Tom, comment ça va ? — Ça va bien, merci."}, {"text": "How are you today?", "translation": "Comment vas-tu aujourd''hui ?"}], "confusions": [], "unitId": "en.v.how_are_you"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.excuse_me', 'en', 'excuse me', 'excusez-moi, pardon', 'Excuse me sert à attirer l''attention de quelqu''un ou à passer poliment. Pour s''excuser après une erreur, on dit plutôt sorry.', '[{"text": "Excuse me, where is the station?", "translation": "Excusez-moi, où est la gare ?"}, {"text": "Excuse me, is this seat free?", "translation": "Pardon, cette place est-elle libre ?"}]'::jsonb, '/ɪkˈskjuːz miː/', '{"id": "en.d.excuse_me", "word": "excuse me", "translation": "excusez-moi, pardon", "partOfSpeech": "expression", "ipa": "/ɪkˈskjuːz miː/", "explanation": "Excuse me sert à attirer l''attention de quelqu''un ou à passer poliment. Pour s''excuser après une erreur, on dit plutôt sorry.", "examples": [{"text": "Excuse me, where is the station?", "translation": "Excusez-moi, où est la gare ?"}, {"text": "Excuse me, is this seat free?", "translation": "Pardon, cette place est-elle libre ?"}], "confusions": [{"word": "sorry", "note": "sorry = je suis désolé (après une erreur) ; excuse me = pour attirer l''attention ou demander poliment."}], "unitId": "en.v.excuse_me"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.of_course', 'en', 'of course', 'bien sûr', 'Of course répond oui avec force : « évidemment ». On l''utilise pour accepter une demande ou confirmer quelque chose d''évident.', '[{"text": "Can I sit here? — Of course.", "translation": "Je peux m''asseoir ici ? — Bien sûr."}, {"text": "Of course I remember you!", "translation": "Bien sûr que je me souviens de toi !"}]'::jsonb, '/əv ˈkɔːs/', '{"id": "en.d.of_course", "word": "of course", "translation": "bien sûr", "partOfSpeech": "expression", "ipa": "/əv ˈkɔːs/", "explanation": "Of course répond oui avec force : « évidemment ». On l''utilise pour accepter une demande ou confirmer quelque chose d''évident.", "examples": [{"text": "Can I sit here? — Of course.", "translation": "Je peux m''asseoir ici ? — Bien sûr."}, {"text": "Of course I remember you!", "translation": "Bien sûr que je me souviens de toi !"}], "confusions": [], "unitId": "en.v.of_course"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.no_problem', 'en', 'no problem', 'pas de problème', 'No problem répond à un merci ou à une demande : « ce n''est pas un souci, avec plaisir ».', '[{"text": "Thanks for your help. — No problem.", "translation": "Merci pour ton aide. — Pas de problème."}, {"text": "Can you open the window? — No problem.", "translation": "Peux-tu ouvrir la fenêtre ? — Pas de problème."}]'::jsonb, '/nəʊ ˈprɒbləm/', '{"id": "en.d.no_problem", "word": "no problem", "translation": "pas de problème", "otherTranslations": ["de rien"], "partOfSpeech": "expression", "ipa": "/nəʊ ˈprɒbləm/", "explanation": "No problem répond à un merci ou à une demande : « ce n''est pas un souci, avec plaisir ».", "examples": [{"text": "Thanks for your help. — No problem.", "translation": "Merci pour ton aide. — Pas de problème."}, {"text": "Can you open the window? — No problem.", "translation": "Peux-tu ouvrir la fenêtre ? — Pas de problème."}], "confusions": [], "unitId": "en.v.no_problem"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.i_understand', 'en', 'I understand', 'je comprends, j''ai compris', 'Pour dire « j''ai compris », l''anglais dit très souvent I understand, au présent : on voit le résultat, on comprend maintenant. On peut aussi dire I get it ou I see.', '[{"text": "Thank you for explaining. I understand now.", "translation": "Merci pour l''explication. J''ai compris maintenant."}, {"text": "I understand your problem.", "translation": "Je comprends ton problème."}]'::jsonb, '/aɪ ˌʌndəˈstænd/', '{"id": "en.d.i_understand", "word": "I understand", "translation": "je comprends, j''ai compris", "partOfSpeech": "expression", "ipa": "/aɪ ˌʌndəˈstænd/", "explanation": "Pour dire « j''ai compris », l''anglais dit très souvent I understand, au présent : on voit le résultat, on comprend maintenant. On peut aussi dire I get it ou I see.", "examples": [{"text": "Thank you for explaining. I understand now.", "translation": "Merci pour l''explication. J''ai compris maintenant."}, {"text": "I understand your problem.", "translation": "Je comprends ton problème."}], "confusions": [], "forms": {"thirdPerson": "understands", "past": "understood", "pastParticiple": "understood", "ing": "understanding"}, "unitId": "en.v.i_understand"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.i_dont_know', 'en', 'I don''t know', 'je ne sais pas', 'I don''t know est la réponse simple quand on n''a pas l''information. On peut ajouter la suite : I don''t know his name.', '[{"text": "Where is Tom? — I don''t know.", "translation": "Où est Tom ? — Je ne sais pas."}, {"text": "I don''t know the answer.", "translation": "Je ne connais pas la réponse."}]'::jsonb, '/aɪ ˌdəʊnt ˈnəʊ/', '{"id": "en.d.i_dont_know", "word": "I don''t know", "translation": "je ne sais pas", "partOfSpeech": "expression", "ipa": "/aɪ ˌdəʊnt ˈnəʊ/", "explanation": "I don''t know est la réponse simple quand on n''a pas l''information. On peut ajouter la suite : I don''t know his name.", "examples": [{"text": "Where is Tom? — I don''t know.", "translation": "Où est Tom ? — Je ne sais pas."}, {"text": "I don''t know the answer.", "translation": "Je ne connais pas la réponse."}], "confusions": [], "unitId": "en.v.i_dont_know"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.never_mind', 'en', 'never mind', 'ce n''est pas grave, laisse tomber', 'Never mind veut dire « ce n''est pas important ». On l''utilise pour rassurer quelqu''un ou pour laisser tomber un sujet.', '[{"text": "I''m sorry, I forgot your book. — Never mind.", "translation": "Désolé, j''ai oublié ton livre. — Ce n''est pas grave."}, {"text": "Never mind, I can do it myself.", "translation": "Laisse tomber, je peux le faire moi-même."}]'::jsonb, '/ˌnevə ˈmaɪnd/', '{"id": "en.d.never_mind", "word": "never mind", "translation": "ce n''est pas grave, laisse tomber", "partOfSpeech": "expression", "ipa": "/ˌnevə ˈmaɪnd/", "explanation": "Never mind veut dire « ce n''est pas important ». On l''utilise pour rassurer quelqu''un ou pour laisser tomber un sujet.", "examples": [{"text": "I''m sorry, I forgot your book. — Never mind.", "translation": "Désolé, j''ai oublié ton livre. — Ce n''est pas grave."}, {"text": "Never mind, I can do it myself.", "translation": "Laisse tomber, je peux le faire moi-même."}], "confusions": [], "unitId": "en.v.never_mind"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.see_you_later', 'en', 'see you later', 'à plus tard', 'See you later se dit pour quitter quelqu''un qu''on va revoir bientôt, souvent le même jour.', '[{"text": "I have to go now. See you later!", "translation": "Je dois y aller. À plus tard !"}, {"text": "Bye, Anna. See you later.", "translation": "Au revoir, Anna. À tout à l''heure."}]'::jsonb, '/ˌsiː juː ˈleɪtə/', '{"id": "en.d.see_you_later", "word": "see you later", "translation": "à plus tard", "otherTranslations": ["à tout à l''heure"], "partOfSpeech": "expression", "ipa": "/ˌsiː juː ˈleɪtə/", "explanation": "See you later se dit pour quitter quelqu''un qu''on va revoir bientôt, souvent le même jour.", "examples": [{"text": "I have to go now. See you later!", "translation": "Je dois y aller. À plus tard !"}, {"text": "Bye, Anna. See you later.", "translation": "Au revoir, Anna. À tout à l''heure."}], "confusions": [], "unitId": "en.v.see_you_later"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.good_luck', 'en', 'good luck', 'bonne chance', 'Good luck se dit à quelqu''un qui va passer un examen, un entretien ou faire quelque chose de difficile. On répond Thank you!', '[{"text": "You have an exam today? Good luck!", "translation": "Tu as un examen aujourd''hui ? Bonne chance !"}, {"text": "Good luck with your new job.", "translation": "Bonne chance pour ton nouveau travail."}]'::jsonb, '/ˌɡʊd ˈlʌk/', '{"id": "en.d.good_luck", "word": "good luck", "translation": "bonne chance", "partOfSpeech": "expression", "ipa": "/ˌɡʊd ˈlʌk/", "explanation": "Good luck se dit à quelqu''un qui va passer un examen, un entretien ou faire quelque chose de difficile. On répond Thank you!", "examples": [{"text": "You have an exam today? Good luck!", "translation": "Tu as un examen aujourd''hui ? Bonne chance !"}, {"text": "Good luck with your new job.", "translation": "Bonne chance pour ton nouveau travail."}], "confusions": [], "unitId": "en.v.good_luck"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.experience', 'en', 'experience', 'expérience', 'Experience désigne ce qu''on a vécu ou appris en faisant les choses : une expérience de vie ou de travail.', '[{"text": "Living abroad was a great experience.", "translation": "Vivre à l''étranger a été une super expérience."}, {"text": "She has a lot of experience.", "translation": "Elle a beaucoup d''expérience."}]'::jsonb, '/ɪkˈspɪəriəns/', '{"id": "en.d.experience", "word": "experience", "translation": "expérience", "partOfSpeech": "noun", "ipa": "/ɪkˈspɪəriəns/", "explanation": "Experience désigne ce qu''on a vécu ou appris en faisant les choses : une expérience de vie ou de travail.", "examples": [{"text": "Living abroad was a great experience.", "translation": "Vivre à l''étranger a été une super expérience."}, {"text": "She has a lot of experience.", "translation": "Elle a beaucoup d''expérience."}], "confusions": [{"word": "experiment", "note": "une expérience scientifique se dit experiment, pas experience."}], "forms": {"plural": "experiences"}, "unitId": "en.v.experience"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.life', 'en', 'life', 'vie', 'Life veut dire « la vie ». En général, on n''utilise pas the devant life : Life is beautiful. Le pluriel est lives.', '[{"text": "Life is beautiful.", "translation": "La vie est belle."}, {"text": "I have never been abroad in my life.", "translation": "Je ne suis jamais allé à l''étranger de ma vie."}]'::jsonb, '/laɪf/', '{"id": "en.d.life", "word": "life", "translation": "vie", "partOfSpeech": "noun", "ipa": "/laɪf/", "explanation": "Life veut dire « la vie ». En général, on n''utilise pas the devant life : Life is beautiful. Le pluriel est lives.", "examples": [{"text": "Life is beautiful.", "translation": "La vie est belle."}, {"text": "I have never been abroad in my life.", "translation": "Je ne suis jamais allé à l''étranger de ma vie."}], "confusions": [], "forms": {"plural": "lives"}, "unitId": "en.v.life"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.memory', 'en', 'memory', 'souvenir, mémoire', 'Memory désigne un souvenir (un moment qu''on garde en tête) ou la mémoire (la capacité de se souvenir).', '[{"text": "This is a happy memory from my childhood.", "translation": "C''est un souvenir heureux de mon enfance."}, {"text": "I have a bad memory for names.", "translation": "J''ai une mauvaise mémoire des noms."}]'::jsonb, '/ˈmeməri/', '{"id": "en.d.memory", "word": "memory", "translation": "souvenir, mémoire", "partOfSpeech": "noun", "ipa": "/ˈmeməri/", "explanation": "Memory désigne un souvenir (un moment qu''on garde en tête) ou la mémoire (la capacité de se souvenir).", "examples": [{"text": "This is a happy memory from my childhood.", "translation": "C''est un souvenir heureux de mon enfance."}, {"text": "I have a bad memory for names.", "translation": "J''ai une mauvaise mémoire des noms."}], "confusions": [{"word": "souvenir", "note": "en anglais, a souvenir est un objet qu''on rapporte d''un voyage ; un souvenir dans la tête se dit memory."}], "forms": {"plural": "memories"}, "unitId": "en.v.memory"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.moment', 'en', 'moment', 'moment, instant', 'Moment désigne un instant précis ou un court moment. Wait a moment veut dire « attends un instant ».', '[{"text": "Wait a moment, please.", "translation": "Attends un instant, s''il te plaît."}, {"text": "It was a special moment for our family.", "translation": "C''était un moment spécial pour notre famille."}]'::jsonb, '/ˈməʊmənt/', '{"id": "en.d.moment", "word": "moment", "translation": "moment, instant", "partOfSpeech": "noun", "ipa": "/ˈməʊmənt/", "explanation": "Moment désigne un instant précis ou un court moment. Wait a moment veut dire « attends un instant ».", "examples": [{"text": "Wait a moment, please.", "translation": "Attends un instant, s''il te plaît."}, {"text": "It was a special moment for our family.", "translation": "C''était un moment spécial pour notre famille."}], "confusions": [], "forms": {"plural": "moments"}, "unitId": "en.v.moment"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.chance', 'en', 'chance', 'occasion, chance', 'Chance veut dire « une occasion de faire quelque chose » ou « la possibilité que quelque chose arrive ». Pour la chance au sens de « bonne fortune », on dit plutôt luck.', '[{"text": "This is your chance to speak English.", "translation": "C''est ton occasion de parler anglais."}, {"text": "I had a chance to visit the museum.", "translation": "J''ai eu l''occasion de visiter le musée."}]'::jsonb, '/tʃɑːns/', '{"id": "en.d.chance", "word": "chance", "translation": "occasion, chance", "partOfSpeech": "noun", "ipa": "/tʃɑːns/", "explanation": "Chance veut dire « une occasion de faire quelque chose » ou « la possibilité que quelque chose arrive ». Pour la chance au sens de « bonne fortune », on dit plutôt luck.", "examples": [{"text": "This is your chance to speak English.", "translation": "C''est ton occasion de parler anglais."}, {"text": "I had a chance to visit the museum.", "translation": "J''ai eu l''occasion de visiter le musée."}], "confusions": [{"word": "luck", "note": "luck = la chance (bonne fortune) : Good luck! ; chance = occasion ou possibilité."}], "forms": {"plural": "chances"}, "unitId": "en.v.chance"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.describe', 'en', 'describe', 'décrire', 'Describe veut dire « dire comment est une personne, un lieu ou une chose ». On dit describe something (pas describe about).', '[{"text": "Can you describe your house?", "translation": "Peux-tu décrire ta maison ?"}, {"text": "She described the film to me.", "translation": "Elle m''a décrit le film."}]'::jsonb, '/dɪˈskraɪb/', '{"id": "en.d.describe", "word": "describe", "translation": "décrire", "partOfSpeech": "verb", "ipa": "/dɪˈskraɪb/", "explanation": "Describe veut dire « dire comment est une personne, un lieu ou une chose ». On dit describe something (pas describe about).", "examples": [{"text": "Can you describe your house?", "translation": "Peux-tu décrire ta maison ?"}, {"text": "She described the film to me.", "translation": "Elle m''a décrit le film."}], "confusions": [], "forms": {"thirdPerson": "describes", "past": "described", "pastParticiple": "described", "ing": "describing"}, "unitId": "en.v.describe"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.explain', 'en', 'explain', 'expliquer', 'Explain veut dire « rendre quelque chose clair pour quelqu''un ». On dit explain something to someone.', '[{"text": "Can you explain this word to me?", "translation": "Peux-tu m''expliquer ce mot ?"}, {"text": "The teacher explained the rule.", "translation": "Le professeur a expliqué la règle."}]'::jsonb, '/ɪkˈspleɪn/', '{"id": "en.d.explain", "word": "explain", "translation": "expliquer", "partOfSpeech": "verb", "ipa": "/ɪkˈspleɪn/", "explanation": "Explain veut dire « rendre quelque chose clair pour quelqu''un ». On dit explain something to someone.", "examples": [{"text": "Can you explain this word to me?", "translation": "Peux-tu m''expliquer ce mot ?"}, {"text": "The teacher explained the rule.", "translation": "Le professeur a expliqué la règle."}], "confusions": [], "forms": {"thirdPerson": "explains", "past": "explained", "pastParticiple": "explained", "ing": "explaining"}, "unitId": "en.v.explain"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.believe', 'en', 'believe', 'croire', 'Believe veut dire « penser que quelque chose est vrai » ou « faire confiance à quelqu''un ». Il ne s''emploie pas au présent continu.', '[{"text": "I believe you.", "translation": "Je te crois."}, {"text": "I don''t believe this story.", "translation": "Je ne crois pas cette histoire."}]'::jsonb, '/bɪˈliːv/', '{"id": "en.d.believe", "word": "believe", "translation": "croire", "partOfSpeech": "verb", "ipa": "/bɪˈliːv/", "explanation": "Believe veut dire « penser que quelque chose est vrai » ou « faire confiance à quelqu''un ». Il ne s''emploie pas au présent continu.", "examples": [{"text": "I believe you.", "translation": "Je te crois."}, {"text": "I don''t believe this story.", "translation": "Je ne crois pas cette histoire."}], "confusions": [], "forms": {"thirdPerson": "believes", "past": "believed", "pastParticiple": "believed", "ing": "believing"}, "unitId": "en.v.believe"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.agree', 'en', 'agree', 'être d''accord', 'Agree est un verbe : on dit I agree (je suis d''accord), jamais I am agree. Pour être d''accord avec quelqu''un : agree with someone.', '[{"text": "I agree with you.", "translation": "Je suis d''accord avec toi."}, {"text": "Tom doesn''t agree with Anna.", "translation": "Tom n''est pas d''accord avec Anna."}]'::jsonb, '/əˈɡriː/', '{"id": "en.d.agree", "word": "agree", "translation": "être d''accord", "partOfSpeech": "verb", "ipa": "/əˈɡriː/", "explanation": "Agree est un verbe : on dit I agree (je suis d''accord), jamais I am agree. Pour être d''accord avec quelqu''un : agree with someone.", "examples": [{"text": "I agree with you.", "translation": "Je suis d''accord avec toi."}, {"text": "Tom doesn''t agree with Anna.", "translation": "Tom n''est pas d''accord avec Anna."}], "confusions": [], "forms": {"thirdPerson": "agrees", "past": "agreed", "pastParticiple": "agreed", "ing": "agreeing"}, "unitId": "en.v.agree"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.opinion', 'en', 'opinion', 'avis, opinion', 'Opinion désigne ce que tu penses d''un sujet. On dit in my opinion (à mon avis) ou What''s your opinion?', '[{"text": "In my opinion, this film is great.", "translation": "À mon avis, ce film est super."}, {"text": "What''s your opinion about the new menu?", "translation": "Quel est ton avis sur le nouveau menu ?"}]'::jsonb, '/əˈpɪnjən/', '{"id": "en.d.opinion", "word": "opinion", "translation": "avis, opinion", "partOfSpeech": "noun", "ipa": "/əˈpɪnjən/", "explanation": "Opinion désigne ce que tu penses d''un sujet. On dit in my opinion (à mon avis) ou What''s your opinion?", "examples": [{"text": "In my opinion, this film is great.", "translation": "À mon avis, ce film est super."}, {"text": "What''s your opinion about the new menu?", "translation": "Quel est ton avis sur le nouveau menu ?"}], "confusions": [], "forms": {"plural": "opinions"}, "unitId": "en.v.opinion"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.been', 'en', 'been', 'été, allé (participe passé de be)', 'Been est le participe passé de be. Avec have / has, il sert à dire qu''on a été quelque part : I have been to London = je suis déjà allé à Londres (et j''en suis revenu). Pour quelqu''un qui est parti et n''est pas encore revenu, on dit gone.', '[{"text": "I have been to Paris twice.", "translation": "Je suis allé à Paris deux fois."}, {"text": "She has never been abroad.", "translation": "Elle n''est jamais allée à l''étranger."}]'::jsonb, '/biːn/', '{"id": "en.d.been", "word": "been", "translation": "été, allé (participe passé de be)", "partOfSpeech": "verb", "ipa": "/biːn/", "explanation": "Been est le participe passé de be. Avec have / has, il sert à dire qu''on a été quelque part : I have been to London = je suis déjà allé à Londres (et j''en suis revenu). Pour quelqu''un qui est parti et n''est pas encore revenu, on dit gone.", "examples": [{"text": "I have been to Paris twice.", "translation": "Je suis allé à Paris deux fois."}, {"text": "She has never been abroad.", "translation": "Elle n''est jamais allée à l''étranger."}], "confusions": [{"word": "gone", "note": "He has gone to London = il est parti à Londres (il y est encore) ; He has been to London = il y est allé et il est revenu."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.too', 'en', 'too', 'aussi', 'Too veut dire « aussi » et se place à la fin d''une phrase affirmative : I like tea, too. Me too = moi aussi. Attention : too peut aussi vouloir dire « trop » (too late = trop tard).', '[{"text": "I''m tired. — Me too.", "translation": "Je suis fatigué. — Moi aussi."}, {"text": "Anna likes this film, and Tom likes it too.", "translation": "Anna aime ce film, et Tom l''aime aussi."}]'::jsonb, '/tuː/', '{"id": "en.d.too", "word": "too", "translation": "aussi", "otherTranslations": ["trop"], "partOfSpeech": "adverb", "ipa": "/tuː/", "explanation": "Too veut dire « aussi » et se place à la fin d''une phrase affirmative : I like tea, too. Me too = moi aussi. Attention : too peut aussi vouloir dire « trop » (too late = trop tard).", "examples": [{"text": "I''m tired. — Me too.", "translation": "Je suis fatigué. — Moi aussi."}, {"text": "Anna likes this film, and Tom likes it too.", "translation": "Anna aime ce film, et Tom l''aime aussi."}], "confusions": [{"word": "either", "note": "too = aussi (phrase affirmative) ; either = non plus (phrase négative)."}, {"word": "two", "note": "two = le chiffre 2 ; il se prononce comme too."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('en.d.either', 'en', 'either', 'non plus', 'Either veut dire « non plus » et se place à la fin d''une phrase négative : I don''t like fish either. On ne le combine pas avec une deuxième négation : on dit Me neither ou I don''t either.', '[{"text": "I don''t like cold coffee. — I don''t either.", "translation": "Je n''aime pas le café froid. — Moi non plus."}, {"text": "Tom can''t swim, and Anna can''t either.", "translation": "Tom ne sait pas nager, et Anna non plus."}]'::jsonb, '/ˈaɪðə/', '{"id": "en.d.either", "word": "either", "translation": "non plus", "otherTranslations": ["l''un ou l''autre"], "partOfSpeech": "adverb", "ipa": "/ˈaɪðə/", "explanation": "Either veut dire « non plus » et se place à la fin d''une phrase négative : I don''t like fish either. On ne le combine pas avec une deuxième négation : on dit Me neither ou I don''t either.", "examples": [{"text": "I don''t like cold coffee. — I don''t either.", "translation": "Je n''aime pas le café froid. — Moi non plus."}, {"text": "Tom can''t swim, and Anna can''t either.", "translation": "Tom ne sait pas nager, et Anna non plus."}], "confusions": [{"word": "too", "note": "too = aussi (phrase affirmative) ; either = non plus (phrase négative)."}], "unitId": null}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.content_versions (language_id, version, bundle_path, sha256, is_current) values ('en', '1.0.0', 'en/1.0.0.json', '3d01677b47f4164fc7a952ffc7a11ac18a033bf6d14c18ddb97fbe5c9ec204eb', true);
